[23] = {
    en = "Ursangous's Paw",
    T = "Лапа Урсанґуса",
    D = "Лапа могутнього ведмедя Урсанґуса — твій трофей за цю частину Полювання в Ясенедолі. На лапі є маленький символ чвертьмісяця; значення цього символу залишається загадкою.$B$BЛапу слід принести Сенані Громосерд у Пост Розщепленого Дерева, щоб довести, що ти переміг цю могутню істоту і завершив цю частину полювання.",
    O = "Принеси Лапу Урсанґуса до Сенані Громосерд у Посту Розщепленого Дерева, Ясенеділ.",
    P = "Ах - $N - я просто думав про тебе! Як проходить твоє полювання?",
    C = "Ах, лапа Урсангуса! Ваша майстерність вражає, $C; йому приписують численні вбивства. Півмісяць на його лапі, безсумнівно, є ознакою того, що його навчили нічні ельфи, які ховаються в Ясеневому долі. Урсангус... був одним із наймогутніших ведмедів, яких можна зустріти в цих краях. Перемога над такою істотою є свідченням вашої волі та рішучості.$B$BYour предки пишалися б!",
},

[24] = {
    en = "Shadumbra's Head",
    T = "Голова Тінетруса",
    D = "Колись швидкий Тінетрус тепер лежить нерухомо, адже ти здобув над ним перемогу. Голова вбитого нічного шаблезуба — гідний трофей для цієї битви Полювання в Ясенедолі. Сенані Громосерд у Посту Розщепленого Дерева захоче побачити цей трофей, щоб зарахувати тобі цю частину полювання.",
    O = "Принеси Голову Тінетруса до Сенані Громосерд у Посту Розщепленого Дерева, Ясенеділ.",
    P = "Ще раз вітаю, $N! Ти прийшов показати мені доказ свого полювання?",
    C = "Перемога $N у Полюванні на Ясеневий ліс! Молодець – безсумнівно, голова Шадумбри є гідним трофеєм для такого вражаючого бою.$B$BShadumbra була добре відома в цій публікації. Будь-яка подорож на захід, особливо пішки, намагаючись вибратися на Зорам-Странд, була пов’язана з небезпекою через цього тигра. Завдяки вам ця небезпека зникла.",
},

[25] = {
    en = "Stonetalon Standstill",
    T = "Застій у Кам’яних Кігтях",
    D = "Якщо хочеш бути корисним, чому б тобі не розібратися з ситуацією біля Шляху Кам’яного Кігтя?$B$BТранспорт між Ясенедолом і Кам’яними Кігтями зупинився через озеро, яке ожило і атакує все, що наближається... тобто всіх на шляху. Ще корисніше, ніж просто розправитися з водними елементалями там, було б розвідати альтанку на озері Містраль — ту, що має чудовий вид на найближчий форпост Альянсу.$B$BГотовий бути корисним?",
    O = "Знищ 12 осквернених водних елементалів на озері Містраль, на схід від Шляху Кам’яного Кігтя і на південний захід від Посту Розщепленого Дерева.$B$BРозвідай альтанку на озері Містраль, що виходить на найближчий форпост Альянсу.$B$BПовернися до Мастока Рилехисса в Посту Розщепленого Дерева, Ясенеділ.",
    P = "Ти вже повернувся? Яка там ситуація? Тепер все прояснилося завдяки вам?",
    C = "Так, я чув, що хтось розірвав там озеро, наче пиловий диявол через Степлі. Судячи з цього, ми могли б створити там можливу зону спостереження, щоб стежити за нашими друзями з Альянсу. Що ж, якщо ми зможемо тримати це на низькому рівні...$B$BLooks як ти, зрештою, виявився досить корисним; перевезення звідси до Stonetalon мають бути легшими. Візьміть це - ви це заслужили.",
},

[26] = {
    en = "A Lesson to Learn",
    T = "Урок для вивчення",
    D = "$N, я з великою радістю стежу за твоїм прогресом. Ти безсумнівно розвиваєшся в цінного захисника природи.$B$BНастав час дізнатися більше про один із численних тваринних аспектів, які Ценарій благословив нас здатністю перетворюватися — той, що дає тобі владу і майстерність над водою. Для цього ти повинен вирушити до села Нічна Гавань у Місячній Галявині і поговорити з Дендритом Зоресяйвом із Кенарійського Кола. Він проведе тебе далі.",
    O = "Поговори з Дендритом Зоресяйвом у селі Нічна Гавань, Місячна Галявина.",
    P = "",
    C = "Вітання, молодий $C; настав час тобі пізнати нашу водяну форму. Це той, який дозволяє вільно і необмежено пересуватися по воді. Ви знайдете цей аспект корисним інструментом і благословенням... але його потрібно заробити, перш ніж ним опанувати.$B$BYou доведеться подолати два випробування. Перший перевірить вашу здатність працювати у воді під тиском. Другий перевірить вашу рішучість зрозуміти аспекти самої форми.$B$BStand готовий, оскільки час тестування настав.",
},

[27] = {
    en = "A Lesson to Learn",
    T = "Урок для вивчення",
    D = "$N, я з великою радістю стежу за твоїм прогресом. Ти безсумнівно розвиваєшся в цінного захисника природи.$B$BНастав час дізнатися більше про один із численних тваринних аспектів, які Ценарій благословив нас здатністю перетворюватися — той, що дає тобі владу і майстерність над водою. Для цього ти повинен вирушити до села Нічна Гавань у Місячній Галявині і поговорити з Дендритом Зоресяйвом із Кенарійського Кола. Він проведе тебе далі.",
