},

[28] = {
    en = "Trial of the Lake",
    T = "Випробування Озера",
    D = "Для твого першого випробування пошукай у глибинах озера Елуне’ара Брелок Святилища. Він швидко розкладається, тож поспіш до Святилища Ремулоса якнайшвидше. Використай брелок у святилищі, а потім поговори з Таджаррі там; вона одна з найнадійніших вартових Місячної Галявини.$B$BУ тебе є обмежений час для виконання завдання, і ти можеш конкурувати з іншими друїдами, які також шукають брелоки. Розумова і фізична спритність будуть вирішальними для твого успіху.$B$BУдачі, $N.",
    O = "Знайди Брелок Святилища в озері Елуне’ара і віднеси його до Святилища Ремулоса на північному заході Місячної Галявини. Там використай Брелок Святилища.$B$BПісля цього ти повинен поговорити з Таджаррі у святилищі, щоб завершити випробування.",
    P = "",
    C = "Ну тепер. схоже, ще один друїд успішно завершив випробування озера! молодці мій молодий друже - молодець.$B$BAs Я сказав. мене звати Таджаррі. Це мій обов’язок і мій привілей — служити наглядачем Місячної поляни. і конкретно цю святиню. Хранитель Ремулос керує Кенаріонським Колом у збереженні природи та рівноваги. і його святиня служить довгою даниною цьому. За допомогою фенечки тут. це вказує на важливість цього місця в Колі.",
},

[29] = {
    en = "Trial of the Lake",
    T = "Випробування Озера",
    D = "Для твого першого випробування пошукай у глибинах озера Елуне’ара Брелок Святилища. Він швидко розкладається, тож поспіш до Святилища Ремулоса якнайшвидше. Використай брелок у святилищі, а потім поговори з Таджаррі там; вона одна з найнадійніших вартових Місячної Галявини.$B$BУ тебе є обмежений час для виконання завдання, і ти можеш конкурувати з іншими друїдами, які також шукають брелоки. Розумова і фізична спритність будуть вирішальними для твого успіху.$B$BУдачі, $N.",
    O = "Знайди Брелок Святилища в озері Елуне’ара і віднеси його до Святилища Ремулоса на північному заході Місячної Галявини. Там використай Брелок Святилища.$B$BПісля цього ти повинен поговорити з Таджаррі у святилищі, щоб завершити випробування.",
    P = "",
    C = "Ну тепер. схоже, ще один друїд успішно завершив випробування озера! молодці мій молодий друже - молодець.$B$BAs Я вже сказав, мене звати Таджаррі. Це мій обов’язок і мій привілей — служити наглядачем Місячної поляни, а особливо цієї святині. Зберігач Ремулос керує Кенаріонським Колом у збереженні природи та рівноваги, і його святилище служить вічною даниною цьому. Використовуючи дрібничку тут, вона служить підказкою важливості цього місця в Колі.",
},

[30] = {
    en = "Trial of the Sea Lion",
    T = "Випробування Морського Лева",
    D = "Для другого випробування тобі знадобляться дві половини, які складають Кулон Морського Лева. Одна половина черпає силу зі спритності аспекту морського лева, що ковзає у воді; інша — із неймовірної витривалості цього аспекту. Друїди однаково використовують обидві ці риси, щоб втілити аспект своєї водної форми.$B$BПоговори з місцевими жителями Місячної Галявини, щоб дізнатися, де можуть бути ці частини, і принеси їх сюди, щоб з’єднати. Після створення кулона віднеси його Дендриту Зоресяйву.",
    O = "Знайди половину Кулона Водної Спритності та половину Кулона Водної Витривалості. Поговори з жителями Місячної Галявини, щоб дізнатися підказки про те, де ці предмети можуть бути.$B$BСклади Кулон Морського Лева з двох половин. Для цього потрібно бути біля Святилища Ремулоса.$B$BПринеси готовий кулон Дендриту Зоресяйву в село Нічна Гавань, Місячна Галявина.",
    P = "Ти сформував свій кулон, щоб я його перевірив, $N? Якщо вам потрібна допомога у пошуку частин, спробуйте запитати інформацію у місцевих жителів. Ви не тільки знайдете те, що шукаєте, але це дасть вам привід дослідити цю дивовижну і священну галявину.",
    C = "Ви пройшли «Випробування морського лева», $N — вітаємо.$B$BEach завдання під час отримання кулона показує, що спритність і витривалість необхідні для того, щоб діяти в гармонії з тим, що ви хочете робити під водою. Жоден не може існувати без іншого, і обидва не можуть бути зроблені без вашої готовності прийняти аспект морського лева.$B$BRemember ці уроки добре, і розраховуйте на них, коли ви придбаєте свою водну форму.",
},

[31] = {
    en = "Aquatic Form",
    T = "Водна форма",
    D = "Ти завершив необхідні уроки, які проходять усі молоді друїди, перш ніж вони зможуть прийняти водний аспект. Тепер повертайся до свого наставника, Турака Рунетотема, у Громовий Бескид. Покажи йому свій кулон і доведи, що ти готовий навчитися того, що він може тебе навчити. Він завершить твоє навчання, дозволяючи тобі стати єдиним із водою.$B$BПрощавай, юний друїде. Ми ще поговоримо.",
    O = "Повернися до Громового Бескиду і покажи Тураку Рунетотему Кулон Морського Лева.",
    P = "Ваше повернення до Громового Утесу не безвісне, хоча мені знадобляться докази ваших уроків, отриманих у Місячній поляні, перш ніж я навчатиму вас вашої водної форми.$B$BDo у вас є підвіска морського лева?",
    C = "Дуже вражаюче, $N. Ваші предки були б задоволені вашим успіхом! Ви готові вивчити свою водну форму, і я із задоволенням навчу вас цьому.$B$BAlso, як визнання ваших досягнень під час двох випробувань, я дарую вам цей предмет. Сподіваюся, ви побачите, що він стане бажаним доповненням до вашого спорядження як захисника природи та хранителя балансу.",
},

[32] = {
