[217] = {
    en = "In Defense of the King's Lands",
    T = "На захист земель короля",
    D = "$N, наші розвідники визначили лідера цього нещодавнього вторгнення троггів. Схоже, ці звірі в Лох-Модані слідують за вождем на ім’я Ґравмуґ. Однак Ґравмуґ добре охороняється. Двоє його найелітніших охоронців, Гризець і Бійчук, ніколи не відходять від нього.$B$BЯкщо ти вважаєш себе гідним, $N, я хочу, щоб ти очолив місію з убивства Ґравмуґа та його двох головорізів. Із мертвим керівництвом троггів ми, можливо, зможемо відтіснити цих звірів назад у землю.",
    O = "Убий лідера троггів, Ґравмуґа, та його двох охоронців, Гризця і Бійчука, а потім доповіси капітану Руґельфуссу в південній вартовій вежі.",
    P = "Ґромуг і двоє його охоронців, Скулячий і Бешкетник, досі живі. Ваша місія не буде завершена, доки всі троє не будуть доведені до смерті. Імперія Гномів розраховує на тебе, $N.",
    C = "Чудово, $N! Ви принесли надію в озеро Лох-Модан. Коли Ґраумуґ мертвий, ми маємо більше шансів побачити, як Трогґів буде знищено з землі.",
},

[218] = {
    en = "The Stolen Journal",
