[267] = {
    en = "The Trogg Threat",
    T = "Загроза трогів",
    D = "$C, ти можеш знати чи не знати про загрозу трогів, що нависла над землями дворфів. Оскільки резерви Залізогарта відправлені на фронт Альянсу, у нас залишилося лише частка сил, необхідних для захисту цих земель. Мій полк призначений стежити за брамою тут, і ми не можемо залишити пост через страх вторгнення.$b$bАле ми мусимо чинити тиск на цих проклятих трогів, що ховаються в пагорбах. Якщо ти готовий до завдання, розпочни наступ на трогів. Принеси мені 8 кам’яних зубів трогів як доказ.",
    O = "Принесіть 8 кам’яних зубів трогів до капітана Ругельфусса в південній сторожовій вежі.",
    P = "У вас є 8 кам'яних зубів Трогга, щоб показати мені? Якщо ні, ще є над чим працювати, $N.",
    C = "Я дуже вражений, $N. Ви зробили велику послугу гномів, захистивши наші землі. Сам король Магні Бронзобородий пишався б!",
},

[268] = {
    en = "Return to Sven",
    T = "Повернення до Свена",
    D = "Книга, яку ти знайшов, була лише наполовину закінчена. Мені довелося залишити її на фермі Свена, коли я звідти втік...$B$BОсь. Візьми мій завершений щоденник до Свена. Він детальніше описує, що сталося на його фермі.$B$BХоча цей щоденник був моєю єдиною компанією останніми тижнями, якщо віддати його означає уникнути гніву Свена, я зроблю це охоче!",
    O = "Поверніться до Свена з завершеним щоденником Джіттерса.",
    P = "Ви знайшли, хто така Тіньова Фігура?",
    C = "Цей щоденник багато чого пояснює мені та налаштовує на шлях проти темних вершників! Я бачив цих вершників у Сутінковому лісі та бачив, як вони розмовляли з чарівником Морбентом Фелом у Забутому Роу.",
},

[269] = {
    en = "Seeking Wisdom",
    T = "Пошук мудрості",
    D = "Вирушай до Штормовію і поговори з єпископом Фартингом у Соборі Світла. Передай йому щоденник Джіттерса і скажи, що ти маєш намір протистояти Морбенту Фелу.$B$BХоча Штормовій покинув Темнолісся, Фартинг — добра душа і дуже мудрий. Він може допомогти тобі в твоєму завданні врятувати нас.$B$BТвоя місія небезпечна, але поспіш, $N. З кожною годиною тіні Темнолісся стають дедалі темнішими.",
    O = "Передайте завершений щоденник Джіттерса єпископу Фартингу в Штормовії.",
    P = "Відпочинок, $gbrother:сестра;. Я можу сказати, що ви подорожували далеко, і ви несете важкий тягар. Чи можете ви сказати мені, що кидає на вас цю темну тінь?",
    C = "<Після прочитання журналу та почуття вашого наміру...>$B$BAn зла пляма закріпилася в уже обложеному Сутінковому лісі. Я дякую Світлу, що у нас є такий герой, як ти, щоб протистояти цьому.$B$BBut спочатку ти маєш підготуватися до майбутнього випробування... адже некромант Морбент Фел надзвичайно могутній і наклав на себе темні чари, щоб захистити його від фізичних нападів. Якщо ви хочете перемогти його, вам знадобиться зброя, яка є доказом проти цих захистів.",
},

[270] = {
    en = "The Doomed Fleet",
    T = "Приречений флот",
    D = "Багато років тому Третя флотія Кул’Тірасу затонула вздовж узбережжя Водно-болотних угідь, болотистої місцевості на північ від дворфійського королівства Залізогарт. На одному з кораблів був вантаж світлокованого заліза.$B$BЦей метал цінний для нас, адже предмети, виготовлені з нього, вражають священною правдою. Якщо ти маєш протистояти Морбенту Фелу, тобі знадобиться така зброя.$B$BВирушай до гавані Менетіл і поговори з моїм колегою-дворфом Глоріном Сталобровом. Якщо втрачений метал можна знайти, він знатиме, де шукати.",
    O = "Вирушайте до гавані Менетіл у Водно-болотних угіддях і поговоріть із Глоріном Сталобровом.",
    P = "",
    C = "Залізо Lightforge — дорогоцінний метал, але схоже, що ваш квест — жахливий. Ти пройшла довгий шлях, $gBrother:Сестро;. Якщо пощастить, ти можеш знайти те, що шукаєш!$B$BAnd Якщо ти отримаєш залізо, я знаю, хто зможе перетворити його на зброю проти цього Некроманта, про якого ти говориш у Сутінковому лісі.",
},

[271] = {
    en = "Vyrin's Revenge",
    T = "Помста Вірин",
    D = "Не хочеш трохи відплатити за Його Зухвалість? Деріл таки має певні навички, мушу визнати.$b$bРік тому великого ведмедя полювали в Ложі Далекомандрівників, але жоден мисливець не мав успіху. Тож Деріл вирішив спробувати свої сили проти нього. Усе, що він отримав за свої зусилля, — це той потворний шрам над оком.$b$bУбий того ведмедя, і я впевнена, що навіть Деріл нарешті замовкне.$b$bВедмідь, Старий Сажеок, зазвичай перебуває біля свого лігва в пагорбах над Тельсамаром.",
    O = "Убийте Старого Сажеока, а потім покажіть свою роботу Дерілу Молодшому в Ложі Далекомандрівників.",
    P = "Ах, $N! Так скоро повернутися? Безсумнівно, ви знову були на полюванні? Не хвилюйтеся, якщо у вас виникли невдачі, у довгостроковій перспективі це зробить вас кращими!$B$B... У будь-якому випадку ви не можете стати набагато гіршим...",
    C = "Е... що це? Судячи з вигляду, голова ведмедя.$B$B<Він несвідомо проводить пальцем по своєму шраму.>$B$BWell, це досить цікаве вбивство. Не міг бути той ведмідь із тих часів...$B$B<Він замовкає, а потім починає помітно тремтіти.>$B$BOh, забери це, забери це! Заберіть цю жахливу річ звідси!",
},

[272] = {
    en = "Trial of the Sea Lion",
    T = "Випробування Морського Лева",
    D = "Для другого випробування тобі потрібні дві половини, що складають Підвіску Морського Лева. Одна половина черпає силу з гнучкості аспекту морського лева, що ковзає водою; інша — з неймовірної витривалості аспекту морського лева. Друїди однаково використовують обидві ці риси, щоб утілити аспект своєї водної форми.$B$BПоговори з місцевими жителями Місячної галявини, щоб дізнатися, де можуть бути ці частини, і принеси обидві сюди, щоб з’єднати їх. Після створення підвіски віднеси її до Дендрита Зоресяйва.",
    O = "Знайдіть половину Підвіски Водної Гнучкості та половину Підвіски Водної Витривалості. Поговоріть із жителями Місячної галявини, щоб отримати підказки про їхнє місце розташування.$B$BСформуйте Підвіску Морського Лева з двох половин. Для цього потрібно бути біля Святилища Ремулоса.$B$BПринесіть з’єднану підвіску Дендриту Зоресяйву в село Ночегавань, Місячна галявина.",
    P = "Ти сформував свій кулон, щоб я його перевірив, $N? Якщо вам потрібна допомога у пошуку частин, спробуйте запитати інформацію у місцевих жителів. Ви не тільки знайдете те, що шукаєте, але це дасть вам привід дослідити цю дивовижну і священну галявину.",
    C = "Ви пройшли «Випробування морського лева», $N — вітаємо.$B$BEach завдання під час отримання кулона показує, що спритність і витривалість необхідні для того, щоб діяти в гармонії з тим, що ви хочете робити під водою. Жоден не може існувати без іншого, і обидва не можуть бути зроблені без вашої готовності прийняти аспект морського лева.$B$BRemember ці уроки добре, і розраховуйте на них, коли ви придбаєте свою водну форму.",
},

[273] = {
    en = "Resupplying the Excavation",
    T = "Поповнення розкопок",
    D = "Ще не пізно, ти можеш піти шукати Гульдара. Він не міг далеко зайти, адже, хоч які вони сильні, Міран і Саїн рухаються повільно, обтяжені тими бочками.$b$bВони йдуть звичайним маршрутом до місця розкопок, виходячи на південь із міста і слідуючи за вигином озера.$b$bНе повинно бути проблем із їхнім пошуком, хіба що вони вже дісталися до місця.",
    O = "Поговоріть із Гульдаром.",
    P = "Знайдіть Хулдара, Мірана та Саена",
    C = "Хммм, щоб зупинити поставки, знадобиться більше, ніж засідка Чорного Заліза!$B$BBut Сеан... Я б ніколи не запідозрив, що він є одним із їхніх симпатиків. Ми з ним працюємо вже майже рік... можливо, я пропустив ознаки.$B$BWell, я подумаю про це пізніше.",
},

[274] = {
    en = "A Dark Threat Looms",
    T = "Темна загроза насувається",
    D = "Це не звичайний вибуховий порошок. Подивися на крихітні сріблясті кристали. І цей виразний запах! Це ясно як день, що це морський порошок. Морський порошок досить безпечний. Але варто йому намокнути, і він може висадити Залізогарт із гори.$b$bХімічну реакцію можна знешкодити, змішавши чотири компоненти: отруту павука-ловця, подрібнений кристал Мо’Грош, сльозу кроколіска і цей знешкоджувальний колоїд. А тепер повідом Гіндервайра, поки не пізно!",
    O = "Ашлан Стоунсмірк хоче, щоб ви повернулися до головного інженера Гіндервайра і повідомили йому про нове відкриття.",
    P = "Що ви привезли з Ашлана?",
    C = "Знезброюючий колоїд? Для Seaforium? О небеса!",
},

