[289] = {
    en = "The Cursed Crew",
    T = "Проклята команда",
    D = "<Підбадьорений, Фітцсіммонс продовжує свою розповідь...>$B$BЯ єдиний, хто вижив із злощасної Третьої флотії Кул’Тірасу, що розбилася біля узбережжя на півночі. Але хоча я єдиний із флотії, хто ще дихає, я не єдиний, хто ще ходить! Бо на одному з наших кораблів був захований великий і страшний скарб, і моторошна сила цього скарбу утримує душі моїх братів у гнилих корпусах кораблів.$B$BАле якщо ти зможеш звільнити деяких моїх братів, можливо, ти знімеш їхнє прокляття.",
    O = "Убийте 13 проклятих матросів, 5 проклятих морських піхотинців і першого помічника Снелліга. Принесіть табакерку Снелліга до першого помічника Фітцсіммонса в гавані Менетіл.",
    P = "Уві сні іноді чую приречені стогони побратимів! Будь ласка, добрий пане, звільніть їх від кайданів і заглушіть їхні крики.",
    C = "Я дякую тобі, $N. І вдячність моїх проклятих братів теж до вас.",
},

[290] = {
    en = "Lifting the Curse",
    T = "Зняття прокляття",
    D = "Щоб зняти прокляття і звільнити всіх моїх братів, ту... річ... заховану на моєму кораблі, треба дістати і очистити! Я не знаю, що це було, але знаю, що воно зберігалося в міцно замкненій скрині корабля, над якою панував капітан Галіндор.$B$BМій старий капітан досі сниться мені. Я знаю, що він ходить на моєму приреченому кораблі, Непохитному. Дістань ключ від нього і використай його, щоб відкрити замкнену скриню Непохитного.$B$BПотім, коли дістанеш прокляту річ, принеси її до священика Глоріну Сталоброва в місті.",
    O = "Дістаньте ключ від скрині Непохитного у капітана Галіндора.$B$BВикористайте ключ, щоб відкрити замкнену скриню Непохитного.",
    P = "Ця скриня надійно замкнена.",
    C = "Ключ заіржавів, але добре підходить до замка.",
},

[291] = {
    en = "The Reports",
    T = "Звіти",
    D = "Чудово! Візьми мій звіт до сенатора Баріна Редстоуна. Він тип похмурий, тож не дозволяй його не надто сонячному настрою впливати на тебе. Він у Залізогарті, у залі, де король Магні тримає раду.$b$bНе знаєш дороги до Залізогарта? Вийди з Караноса на північ, перетни міст, потім іди дорогою на схід — там є великі прапори вздовж дороги — вгору по схилу гори.$b$bДо речі, чи не могли б ви не згадувати, як ви мені допомагали? Не хочу, щоб думали, ніби я тут не працюю старанно, знаєте?",
    O = "Доставте звіт Сеніра до сенатора Баріна Редстоуна в Залізогарті.",
    P = "Hmm... it would seem that my guards are becoming less discriminatory with petitioners. Ну що ти хочеш? Зробіть це швидко.",
    C = "<Він швидко переглядає звіт.>$B$BAuthority КОРОЛЯ!? Невже Магні повністю зневірився! А той клятий Білобород... Взяв справу у свої руки, чи не так? Сенату не буде приємно почути про це.$B$BWhat, ти ще тут? Ідіть, поки я не покличу варту!",
},

