[304] = {
    en = "A Grim Task",
    T = "Суворе Завдання",
    D = "Багато моїх солдатів загинули в битві за Дун Модр. Мій власний брат загинув, коли Західний Міст над Тандольським Мостом був зруйнований. Так, Темнозалізні гноми — диявольська порода. З того, що Рогго зміг зібрати, лідером цих головорізів у Болотинах є чаклун на ім’я Балгарас Мерзенний. Він справжній боягуз, посилає своїх солдатів виконувати його накази, але сам ховається в своєму таборі на Пагорбі Жахоковки, на південний схід.$b$bЯкщо ти зможеш знайти цього нікчемного мерзотника, убий його і принеси мені його вухо. Я винагороджу тебе, $c.",
    O = "Убий Балгараса Мерзенного і принеси його вухо до Довгоборода Похмурого біля Дун Модра.",
    P = "Ви вже змогли знайти Балгараса Нечистого, $C? Він ухилявся від нас уже досить довго.",
    C = "Балгарас Нечистий нарешті мертвий. Хоча його смерть не поверне багатьох невинних гномів, які марно загинули від його руки, вона допоможе повернути душевний спокій тим, хто вижив. Якщо Балгарас мертвий, залишилася покидьком з Темного заліза буде достатньо легко керувати. Тепер ми повинні знищити їх, перш ніж до цих частин буде відправлено нового лідера.$B$BYou добре впоралися, $C.",
},

[305] = {
    en = "In Search of The Excavation Team",
    T = "У пошуках команди розкопок",
    D = "Ох, ти, мабуть, той розвідник, про якого казав Довгоброд! Ти не уявляєш, як я хвилювався.$b$bМоя дружина, Меррін, надсилала мені листи щотижня протягом останнього місяця. Вона працює в команді розкопок Велгара. Але вже майже два тижні від неї немає жодного листа. Напевно, щось не так!$b$bДовгоброд сказав, що відправить розвідника перевірити ситуацію, якщо ми не отримаємо звісток від команди найближчим часом. Гадаю, цей розвідник — ти, $N. Знайди Меррін на місці розкопок на сході!",
