[449] = {
    en = "The Deathstalkers' Report",
    T = "Звіт Смертоловів",
    D = "Хоча рани Квінна загоюються, я хочу якнайшвидше доставити наш звіт верховному виконавцю Гадреку. У ньому міститься інформація, життєво важлива для окупації Відреченими Срібнохвойного лісу.",
