[450] = {
    en = "A Recipe For Death",
    T = "Рецепт смерті",
    D = "Ти можеш ще послужити Королівському товариству аптекарів, $N.$b$bКоли Аруґал наклав своє прокляте закляття на ліс, він прокляв одного з наших найперспективніших членів, аптекаря Берарда. Тепер, як бездумний слуга Аруґала, Берард для нас марний. Але його знахідки можуть мати цінність. Він вивчав стародавню чуму, яка колись знищила все водяне життя в озері Лордамер.$b$bЗдобудь журнал Берарда з його кабінету в корчмі села Жариння і віднеси його аптекарю Ренферрелу.",
    O = "Здобудь журнал аптекаря Берарда в селі Жариння і віднеси його аптекарю Ренферрелу в Гробницю.",
    P = "Я бачу, ти повернувся, $N.",
    C = "Щоденник аптекаря Берарда! Чому ти такий сміливий, $N. А тепер давайте подивимося, чим займався Берард перед тим, як збожеволіти. . .",
},

[451] = {
    en = "A Recipe For Death",
    T = "Рецепт смерті",
    D = "Згідно з журналом Берарда, мох із озерних лізунів і повзунів може бути корисним для нашого завдання створити нову чуму. Ці створіння мешкають на островах в озері Лордамер на сході.$b$bВін також згадує дуже рідкісну затверділу пухлину, яку він знайшов у мурлока Злого Плавника. Схоже, ця пухлина настільки рідкісна, що Берарду вдалося здобути лише одну.$b$bЗбери зразки моху, а також рідкісну затверділу пухлину і віднеси їх головному аптекарю Фаранеллу в Підмісті.",
    O = "Принеси 6 зразків моху озерного повзуна, 6 зразків моху озерного лізуна і затверділу пухлину до головного аптекаря Фаранелла в Підмісті.",
    P = "Що привело тебе до Підземного міста, $N?",
    C = "Такий удар для Королівського аптекарського товариства — втрата Берарда. Але завдяки вашій наполегливій праці та старанним дослідженням аптекаря Ренферрела дослідження Берарда все одно будуть корисними для скрутного становища Темної леді.$B$BWe тут на порозі чогось великого, $N. Якби ви не були настільки вправними у способах ведення бою, я б спробував завербувати вас у члени Товариства.",
},

[452] = {
    en = "Pyrewood Ambush",
    T = "Засідка в Жаринні",
    D = "Ти прибув саме вчасно, $N!$b$bРада Жариння повернеться будь-якої миті. Аруґал має інші справи в фортеці. Він використовує Раду як маріонеток, щоб тримати бездумних слуг Жариння під контролем. Але я вірю, що без керівництва Ради Жариння сини Аруґала повстануть проти свого господаря.$b$bЯ не можу впоратися з усіма самотужки. Мені потрібна твоя допомога. Разом ми знищимо Раду заради Леді Сильвани.",
    O = "Допоможи Смертоловці Фарлеї вбити Раду Жариння.",
    P = "Допоможіть Фаерлеї вбити Раду Піреводу",
    C = "Ти боровся як справжній послідовник Темної леді, $N. Коли рада померла, можливо, ми зможемо раз і назавжди отримати контроль над цим містом і вигнати Аругал із Крепості Тіньового Ікла. я вас вітаю!",
},

[453] = {
    en = "Finding the Shadowy Figure",
    T = "Пошук тіньової постаті",
    D = "Удачі, $N. Сподіваюся, ти знайдеш того хлопця, і сподіваюся, він ще живий.$B$BЯкщо він покинув безпеку Темнолісся, то міг стати здобиччю диких звірів.",
    O = "Знайди тіньову постать. Твої підказки:$B$BВін не місцевий у Темноліссі.$B$BВін нервовий, метушливий чоловік.$B$BВін покинув Темнолісс і попрямував на захід.",
    P = "хто ти?? Залиште мене!",
    C = "<Джіттерс зітхає...>$B$BYes, я автор цієї книги. Ви нарешті знайшли мене, еге ж?$B$BWell якщо ви читаєте цей щоденник...тоді ви знаєте лише половину!",
},

[454] = {
    en = "After the Ambush",
    T = "Після засідки",
    D = "Раніше ми перевозили бочки з порохом туди-сюди партіями... до цієї... халепи. Тепер нам довелося розділити роботу: Міран везе бочки, а я стежу за іншими.$b$bМені неспокійно залишати Мірана перевозити решту вантажу самотужки. Коли він буде готовий вирушати, може, ти супроводжуватимеш його в наступній поїздці?",
    O = "Поговори з Міраном.",
