[477] = {
    en = "Border Crossings",
    T = "Перетин кордону",
    D = "Як ти, напевно, знаєш, місто Янтарний Млин залишається осередком людського спротиву, головним чином через підтримку, яку вони отримують від чарівників Даларану.$b$bЯ не знаю, який у них план, але їхній інтерес до такого глухого села, як Янтарний Млин, свідчить про його більшу важливість.$b$bВони возами доставляли ящики з Гіллсбраду. Багато з цих припасів опиняються в невеликому таборі на північ від села Жариння. Здобудь вміст одного з ящиків і поверни його мені.",
    O = "Здобудь вміст одного з ящиків чарівників Даларану. Село Жариння ти знайдеш на півдні.",
    P = "",
    C = "<Відкривши кришку ящика, ви знайдете асортимент ретельно упакованих предметів. На верхній частині ящика лежить пачка карт, пожовклих із віком, на яких, здається, зображено Сріблястий ліс та інші частини західного Лордерону.$B$BUnderneath карти — це таємничий магічний кулон.>",
},

[478] = {
    en = "Maps and Runes",
    T = "Мапи і руни",
    D = "<Ти швидко виймаєш підвіску з ящика і закриваєш кришку.>",
    O = "Віднеси дивну підвіску до тіньового жерця Алістера в Гробницю.",
    P = "Ти дізнався щось корисне, $N?",
    C = "Карти і цей... кулон, а? Цікаво.$B$BIt Очевидно, що даларанські чарівники зацікавлені в Бурштиновому млині з певною метою, але все одно їх мета прихована для мене.$B$BМожливо Далар буде знати дещо про їх використання.",
