[479] = {
    en = "Ambermill Investigations",
    T = "Розслідування в Янтарному Млині",
    D = "Далар намагається визначити джерело чарівницьких заклять. Поки що нам доведеться сповільнити їхній прогрес будь-яким способом...$b$bЗаклинателі, маги і захисники, без сумніву, носять ці підвіски. Здобудь їх і принеси мені.$b$bЙди головною дорогою на південь і східним відгалуженням до Янтарного Млина.",
    O = "Здобудь 8 даларанських підвісок для тіньового жерця Алістера в Гробниці.",
    P = "Ми повинні поспішати, їхні плани не повинні здійснитися, інакше ми можемо втратити контроль над Сріблястим лісом.",
    C = "Далар виявив, що плетіння досить далеко просунулося, незважаючи на невдачу.$B$BA чарівник великої сили керує магічною енергією. Його треба швидко зупинити.",
},

[480] = {
    en = "The Weaver",
    T = "Ткач",
    D = "Архімаг великої сили наглядає за повторною активацією вузла лей-енергії. З їхнім прогресом наша єдина надія зупинити їх — убити його. Це буде складно, він, без сумніву, захищений багатьма іншими магами і стражами.$b$bТи мусиш піти і швидко його знищити. Коли він буде мертвий, добудь для мене його посох. Іди негайно.",
    O = "Убий даларанського архімага, а потім добудь його посох для тіньового жерця Алістера в Гробниці.",
    P = "Швидко, часу мало, $N!",
    C = "Магія чарівників розсіюється, а лей-енергії занурюються в сплячку. Ваші зусилля були плідними, $N, і ми завдали серйозного удару нашим ворогам і владним чарівникам Даларану.$B$BWe, однак, слід бути пильним, знаючи, що джерело енергії знаходиться так близько... Треба будувати плани на майбутнє.",
