[536] = {
    en = "Down the Coast",
    T = "Вздовж узбережжя",
    D = "Переведений із міської варти Штормовію до Південнобережжя, міста, яке, здається, варто покинути... Запах гавані день і ніч.$b$bНе кажучи вже про старого Редпата... Хоче, щоб я розібрався з мурлоками. Ха! $b$bЯ ледве можу змусити себе вийти до кількох осередків цих рибоподібних на Західному Узбережжі. Якщо ти підеш замість мене і розберешся з ними, я буду вдячний.",
    O = "Убий 10 приливних мисливців Рванофлотів і 10 оракулів Рванофлотів для лейтенанта Фаррена Орінелла в Південнобережжі.",
    P = "Ще один ель, будь ласка, останній, здається, просто зник!$B$BLight, скільки я ще буду тут сидіти?$B$BOh, це ти, $N. Ти вже вбив тих мурлоків?",
    C = "Сподіваюся, цього буде достатньо, щоб переконати Редпата, що я--га!--виконував його накази і позбавив Південний берег від жахливої ​​та жахливої ​​загрози страшних мурлоків! Бо не може бути більшого зла, ніж спустошення зарослої риби!",
},

[537] = {
    en = "Dark Council",
    T = "Темна Рада",
    D = "Лист, який ти приніс, написаний істотою на ім’я Наґаз, членом Пробудження Арґуса. Я не знаю, що таке це Пробудження Арґуса, але якщо вони в союзі з Синдикатом, то вони становлять загрозу.$b$bЯ хочу, щоб ти знайшов Наґаза та тіньових магів Арґуса, згаданих у тому листі. Знайди їх і убий.$b$bШукай у Височинах, де Синдикат найсильніший. Це на північ від Странбраду.$b$bЗ удачею, ти знайдеш цих посланців Пробудження Арґуса там.",
    O = "Убий 4 тіньових магів Арґуса.$b$bПринеси голову Наґаза магістрату Малебу в Південнобережжі.",
    P = "Ви знайшли посланців Поминки Аргуса?",
