[613] = {
    en = "Cracking Maury's Foot",
    T = "Розкриття ноги Морі",
    D = "Прокляття! Той шахрай Морі поставив замок на свою ногу, і я не можу його відкрити! Його скарби всередині ноги, а це те, що він мені винен!$B$BНам потрібно знайти ключ, щоб відкрити замок. Морі, як відомо, грав в азартні ігри з ограми Мош’Оґґ, у їхньому кургані на північний схід. І він казав мені, коли ще був живий, що востаннє, коли він був у кургані, його прогнали після того, як він виграв забагато. Може, в огрів є його ключ.$B$BАле якщо він у них, тобі, можливо, доведеться зарубати купу, щоб знайти потрібного...",
    O = "Принеси ключ Морі до «Морського Вовка» МакКінлі в Бухту Скарбів.",
    P = "Привіт, $N! Ви вже знайшли ключ Морі?",
    C = "Ви знайшли його! Мільйон спасибі, $N. Ви мені дуже допомогли!$B$BHere йдете – ви це заслужили!",
},

[614] = {
    en = "The Captain's Chest",
    T = "Капітанська скриня",
    D = "Я колись вів корабель звідси аж до Ратчета в Калімдорі. Я був успішним капітаном із бездоганною репутацією.$B$BАж поки...$B$BЦі прокляті морські велетні знищили мене! Вони розтрощили мій корабель, убили мою команду і відправили мене на рятувальній шлюпці до Бухти Скарбів. А один із велетнів, Ґорлаш, украв мою капітанську скриню. Він сказав, що хоче її для табакерки. Яка нахабність!$B$BЯ чув, що Ґорлаш блукає узбережжям на схід звідси. Знайди його і поверни мою скриню! Зроби це, і ти заслужиш вдячність капітана.",
    O = "Принеси скриню Смоттса до Гекльбері Смоттса в Бухту Скарбів.",
    P = "Привіт, $N! Ти знайшов Горлаша? Ця скриня була моєю улюбленою, і в ній є приховане відділення, у якому зберігалися мої найбільші скарби!",
    C = "Ви знайшли його! О, щасливий день, це! Дякую, $N. Повернення моїх грудей трохи охолоджує вогонь у мені.$B$BBut моя помста не завершена...",
},

[615] = {
    en = "The Captain's Cutlass",
    T = "Капітанська шабля",
    D = "Після того, як я втратив свій перший корабель через тих велетнів, я купив інший. Назвав його «Помста Смоттса», наповнив припасами і командою, і вирушив знайти лиходіїв. Я знайшов їх, але... вони мене перемогли. Вони розтрощили «Помсту Смоттса», убили мою другу команду і відправили мене на іншій шлюпці.$B$BЦього разу інший велетень, Неґолаш, украв мою шаблю.$B$BЗіткнися з Неґолашем і поверни мені мою шаблю!$B$BПоговори зі Спроґґером. Він був моїм коком на «Помсті Смоттса» і пережив останній напад. Він може допомогти тобі знайти велетня.",
    O = "Поговори зі Спроґґером.",
    P = "",
    C = "Привіт, привіт, $N. Капітан сказав мені, що ти збираєшся за Неголашем, еге ж?",
},

[616] = {
    en = "The Haunted Isle",
    T = "Острів із привидами",
    D = "Барон Ревілґаз доручив мені стежити за чутками про щось дивне і незвичайне в Бухті Скарбів і Тернистій Долині. Зазвичай я не надаю значення історіям про привидів, але чув, як моряки в таверні говорили про острів із привидами біля узбережжя. Водяні елементалі і божевільний гоблін-привид, кажуть вони.$b$bЯкщо ти збираєшся говорити з Ревілґазом, чи не могли б ви переказати йому цю історію?",
