[642] = {
    en = "The Princess Trapped",
    T = "Ув’язнена принцеса",
    D = "Мене звати Мізраель. Я принцеса землі, і мої викрадачі, велетні, ув’язнили мене глибоко під нагір’ями Араті. Ці кристальні уламки — єдиний спосіб, яким я можу спілкуватися з поверхневим світом.$B$BБудь ласка, допоможи мені. Союзники велетнів, кобольди Суховусів, мають такий же уламок у своїй Суховусій ущелині, на схід. Щоб активувати скупчення, ти мусиш зібрати Іскри Мізраель від кобольдів і застосувати їх до нього.$B$BЯ благаю тебе, $N, допоможи мені!",
    O = "Збери 12 Іскор Мізраель, а потім принеси їх до Віхрових Уламків у Суховусій ущелині.",
    P = "Це скупчення осколків дуже схоже на Осколки Мізраеля.  Але те саме відчуття безпеки не пульсує в них.",
    C = "Ах! Ви активували ці фрагменти. Я вже почуваюся собою!$B$BBut На жаль, я ще далеко не вільний...",
},

[643] = {
    en = "Sigil of Arathor",
    T = "Печатка Аратора",
    D = "Хоч вони ледве можуть сказати, що контролюють Стромґард, не кажучи вже про всі нагір’я Араті, людський принц ганяє залишки своєї кавалерії по сільській місцевості. Я не розумію, чому він це робить, але хто зрозуміє, як думають люди, правда?$b$bЯким би не було його обґрунтування, важливіше те, що він віддав одну з печаток лейтенанту Валорколу, їхньому лідеру кавалерії. Знайди його і поверни мені його печатку.",
