},

[654] = {
    en = "Tanaris Field Sampling",
    T = "Польові дослідження в Танарісі",
    D = "Активація джерела живлення змушує польовий тестовий набір почати світитися і вібрувати. Схоже, він працює, як і планувалося.$B$BЗа словами головного інженера Білджвіззла, у тебе є дві години, щоб зібрати потрібні дані в пустелі Танаріс. Якщо ти не збереш їх протягом двох годин, усі дані будуть втрачені, і тобі доведеться купувати нове джерело живлення у нього.$B$BПовернися до нього, коли завершиш завдання.",
    O = "Збери прийнятні зразки від 8 василісків, 8 гієн і 8 скорпіонів. Поверни тестовий набір головному інженеру Білджвіззлу в Ґаджетзані, поки джерело живлення не розрядилося.",
    P = "Ну що, ви отримали все необхідне? Якщо ви цього не зробите, і електроенергія закінчиться, все всередині буде зруйновано, і вам доведеться починати спочатку.$B$BHey, не шукайте в мені співчуття; Я за те, щоб компанія Gadgetzan Water Company отримувала прибуток, і якщо це означає, що ми продаємо вам джерела енергії, доки ми не зможемо дозволити собі імпортувати воду з крижаних джерел Дун Морога, нехай буде так!",
    C = "Тоді гаразд, мені знадобиться лише секунда, щоб відключити джерело живлення. Після цього тепер ви можете робити з ним усе, що забажаєте, не турбуючись про втрату даних усередині.",
},

[655] = {
    en = "Hammerfall",
    T = "Молотобій",
    D = "Це все ще ясно для мене, наче вчора... Стільки років без надії, із деревиною та сталлю, що приковували мене до цього жахливого місця. І нарешті, нарешті! З’явився Вождь. Думхаммер у своїх північних обладунках, із бойовим молотом, піднятим високо.$B$BЦе було... занадто жахливо... Що удар боягуза звалив нашого найбільшого героя. Ззаду він напав на коні, і спис його пронизав... Я впав на коліна. Яка була надія? Яка є надія...",
    O = "Поговори з Тор’ґаном у Молотобої.",
    P = "",
    C = "Ах, Гор'мул, про якого ти говориш. Так, з того, що він каже, здається, що він так і не оговтався після смерті Думхаммера.$B$BGor'мул був тут у полоні, коли Тралл і Оргрім боролися за звільнення табору, але коли земля затряслась і наші брати втекли, він залишився позаду. Він блукав сам і роками губився без напрямку чи надії, поки ми не повернулися, щоб оселитися тут, у Хаммерфоллі.",
},

[656] = {
    en = "Summoning the Princess",
    T = "Виклик Принцеси",
    D = "Ти мусиш перемогти Мізраель, поки вона не набрала сили. Якщо ти цього не зробиш, то, коли вона збере достатньо енергії, вона кине виклик своїм викрадачам! Дехто думає, що її можна контролювати, але якщо вона піддається контролю, то чому гіганти її закували?$B$BБожевільна логіка, правда?$B$BЩоб перемогти її, виклич її біля Уламків Мізраель, де ти вперше з нею розмовляв. Переможи її, збери її Таємничі Кайдани і прив’яжи їх до Уламків Мізраель.$B$BЗроби це, і вона знову буде ув’язнена.",
    O = "Вируш до Уламків Мізраель, виклич її і переможи.$B$BЗбери її Таємничі Кайдани і прив’яжи їх до Уламків Мізраель.",
    P = "Осколки Мізраеля тепер дивно тихі.",
    C = "Коли чарівні кайдани надівають на Осколки, далеко знизу лунає нелюдський зойк. Крик супроводжується ревом.$B$BThe Осколки Мізраеля більше не викликають відчуття тепла та безпеки, як колись. Тепер вони пульсують відкритою загрозою... ніби те, що під ними, не хоче спливати на поверхню.",
},

[657] = {
    en = "Hints of a New Plague?",
    T = "Нова чума?",
    D = "<Кває починає переглядати теку.>$B$BЦе ДУЖЕ цікаво. Здається, апотекар Джорелл проводив якісь смертельні експерименти тут, у Ґо’Шеку. Не впевнена, як це пов’язано з Гіллсбрадом, але Фін не зрадів би, якби ми дозволили цьому тривати.$B$BПоки тебе не було, ми зіткнулися з кількома орками, і я не в тому стані, щоб допомогти Кінелорі. Якщо ти готовий, їй знадобиться захист, коли вона піде на ферму, щоб викрасти дослідження, які Джорелл ще не відправив до Тарренського Млина.",
    O = "Поговори з Кінелорі.",
    P = "",
    C = "Якщо це принесе Фіну мир, я особисто знищу всіх Покинутих. Він так багато зробив для нас після чуми. Ми ніколи не думали, що знову знайдемо друзів чи родину.$B$BWhen ви готові, приходьте, дайте мені знати. Ми відразу почнемо.",
},

[658] = {
    en = "Hints of a New Plague?",
    T = "Нова чума?",
    D = "То Фін послав тебе перевірити нас? Не дивно — він занадто турбується.$B$BМи стежили за фермою кілька днів, і Кін стверджує, що бачила, як нещодавно з маленького будинку на півдні вийшов кур’єр.$B$BВона багато говорить, але я завжди довіряю її чуттям у небезпечних місцях.$B$BТи, випадково, не вправний слідопит? Ми думаємо, що кур’єр може нести нотатки до Тарренського Млина. Якби ми могли дістати ці документи, це могло б пролити світло на те, що відбувається в Гіллсбраді.",
    O = "Знайди Кур’єра Покинутих і принеси її Запечатану Теку Кває біля ферми Ґо’Шек.",
    P = "Ми цінуємо вашу допомогу в пошуку того кур’єра, $N.$B$BWhile вас не було, Кін бачив, як аптекар вийшов з того самого будинку на південь звідси. Я впевнений, що вони ні до чого доброго – мені просто потрібні докази цього, перш ніж ми підемо й зробимо щось необдумане.$B$BHave Вам уже пощастило?",
    C = "Чудово!$B$BLet подивіться, про що йдеться...",
},

[659] = {
    en = "Hints of a New Plague?",
    T = "Нова чума?",
    D = "Вітаю, $N. Я очолюю групу шукачів пригод, які досліджують дивні події в цій місцевості.$B$BМій кузен у Гіллсбраді нещодавно приспав свого пса Стенлі, бо тварина містично виросла до величезних розмірів і люто нападала на всіх, хто наближався.$B$BЯ вважаю, що тут замішана нежить, і ми шукаємо докази цього.$B$BДвоє моїх товаришів, Кває і Кінелорі, вирушили до ферми Ґо’Шек у Нагір’ї Араті, і вже кілька днів не виходили на зв’язок. Знайди їх для мене? Я починаю хвилюватися.",
    O = "Знайди Кває і Кінелорі біля ферми Ґо’Шек у Нагір’ї Араті.",
    P = "",
    C = "Спробуй залишатися якомога тихішим, мандрівнику.$B$BOrcs не надто сприймай, коли за тобою шпигують, і на цій фермі є більше, ніж може здатися на перший погляд.",
},

[660] = {
