},

[715] = {
    en = "Liquid Stone",
    T = "Рідкий камінь",
    D = "Я думаю, що предмети, які ти здобув для Лотвіла, будуть найменшою з наших проблем, $N. З іншого боку, ти довів, що більш ніж вправний у науках, які Лотвіл вважає священними, тож як щодо того, щоб допомогти мені?$B$BМені потрібне зілля зцілення і зілля меншої невидимості; обидва можуть скоро стати в нагоді, якщо він це зробить.$B$BНатомість я дам тобі рецепт зілля, яке я розробляю, навчаючись у Лотвіла. Воно базується на деяких дослідженнях, які він проводить тут, у Безплідних краях.",
    O = "Принеси зілля зцілення і зілля меншої невидимості до Люсьєна Тоссельренча в Безплідних краях.",
    P = "Він все ближче до фінішу. Як у вас справи?",
    C = "ТАК!$B$BI означає, дякую, $N. Вони стануть у нагоді під час подорожей по Безплідній землі.",
},

[716] = {
    en = "Stone Is Better than Cloth",
    T = "Камінь кращий за тканину",
    D = "Я знаю, яким скупим може бути Лотвіл, $N, тож дозволь мені зробити для тебе щось за всі твої зусилля. Можливо, це навіть захистить тебе від майбутньої катастрофи, якою є найновіший винахід Лотвіла.$B$BЯ працював із усіма зайвими каменями, які ти збирав для нього, і можу зробити гарні наручники, які тобі можуть сподобатися. Звісно, вони зачаровані.$B$BМені лише потрібні візерункові бронзові наручники, виготовлені ковалем, щоб я міг завершити наручники, які роблю для тебе.",
    O = "Принеси візерункові бронзові наручники до Люсьєна Тоссельренча в Безплідних краях.",
    P = "Я б не став довго чекати, щоб отримати цей браслет, $N.$B$BWho знає, що буде далі?",
    C = "Ось, $N. Приміряйте їх.",
},

[717] = {
    en = "Tremors of the Earth",
    T = "Тремтіння землі",
    D = "Стало очевидно, що ми не можемо гарантувати, що Блеклеш і Гематус залишаться ув’язненими в Летлоровому яру. Те, що там оселилися чорні дракони, і що оґри зуміли вкрасти Знак Землі, вказує на те, що потрібно вжити радикальніших заходів.$B$BВ’язниця драконів підтримується трьома рунними каменями, які можна здобути лише за допомогою Знака Землі. Ці рунні камені потім можна використати, щоб зламати печатку, яка ув’язнює їх.$B$B$n... забезпеч, щоб їхні сни були вічними.",
    O = "Використай Знак Землі, щоб активувати Стовпи Аметисту, Опалу і Діаманту та здобути рунні камені.$B$BРозмісти рунні камені в Печатці Землі, щоб звільнити Блеклеша і Гематуса.$B$BУбий їх і поверни кайдани Блеклеша, ланцюги Гематуса і Знак Землі до Ґарека.",
    P = "Сильна магія та сили так довго утримували дрейків у в’язниці, але ми не можемо допустити жодної можливості звільнення Блеклеша та Гематуса.",
    C = "Кірін-Тору більше не потрібно буде турбуватися про в’язнів Летлора. Я повернуся, щоб повідомити про успіх своєму господареві. Крас, без сумніву, буде задоволений.",
},

[718] = {
    en = "Mirages",
    T = "Міражі",
    D = "У поспіху, коли ми покидали розкопки в Ульдамані, ми змушені були залишити багато возів і ящиків із припасами по дорозі. Місцеві оґри з табору Кош гудуть над нашим покинутим спорядженням, як стерв’ятники над гнилою тушкою. І пахнуть не набагато краще, ніж ті туші, до речі.$B$BТак чи інакше, вони забрали віз, який перевозив усі наші зброї та інше... тож — це трохи ніяково — ми не можемо добути їжу.$B$BМи тут у скрутному становищі, чи не могли б ви нам допомогти?",
    O = "Здобудь ящик із припасами для Сіґрун Залізосокири.",
    P = "У пустелі погано бути голодним, друже, дозволь мені сказати тобі це.$B$BHey... що це там...",
    C = "Дуже дякую, $N. Поки тебе не було, я... е-е... проковтнув повний рот піску. Це...$B$BWell, досить, сьогодні ввечері ми підемо поїсти. Їжте як королі!",
},

[719] = {
    en = "A Dwarf and His Tools",
    T = "Дворф і його інструменти",
    D = "Гей, $N. Будь обережний тут. Усюди Темне Залізо — здається, клан Тінегорн.$B$BВони щойно напали на місце розкопок, де я працював — убили майже всіх, включно з моїм босом Молотоступом. Я ледве втік живим.$B$BМісце розкопок одразу на північ звідси, і я намагаюся придумати, як повернути частину наших припасів, особливо мою щасливу кирку.$B$BДумаєш, зможеш мені допомогти? Один із тих проклятих Темних Заліз має мою кирку! Це може бути будь-хто з них.",
    O = "Знайди щасливу кирку Райєдола і поверни її до Проспектора Райєдола на південь від розкопок Молотоступа.",
    P = "Не знаю, що шукали Shadowforge, але вони точно мали мету.",
    C = "Ти мій рятівник, $C. Я радий, що хтось міг навчити тих Shadowforge урок або два. Дякуємо за вашу допомогу.",
},

