[721] = {
    en = "A Sign of Hope",
    T = "Знак надії",
    D = "$N, чи можеш ти його знайти? Чи можеш знайти Молотоступа в Ульдамані?$B$BЯкщо ці брудні Тінегорни тримають його в заручниках, щоб дізнатися, що він знає про розкопки титанів, то весь Залізогарт може бути у великій біді.$B$BВже давно Темне Залізо шукає магію, щоб створювати потужніших ґолемів. Молотоступ робив те саме, звісно, але лише щоб їх зупинити.$B$BВони, ймовірно, тримають його живим, поки не дізнаються, що він знає. Поспіши, якщо хочеш його врятувати!",
    O = "Знайди Молотоступа Греза в Ульдамані.",
    P = "",
    C = "Так? Ах, вибачте... <кашель> Відчуваю таку слабкість. Чи можете ви підійти ближче, $C?$B$BRyedol вас надіслав? Слава Мурадіну, цей хлопець не такий повільний у голові, як я колись думав. <кашель>",
},

[722] = {
    en = "Amulet of Secrets",
    T = "Амулет таємниць",
    D = "Ти хоробрий... <кашель>... що прийшов до Ульдамана за мною, $c.$B$BЯкщо ти справді тут, щоб допомогти... старому Молотоступу, тоді... <кашель>... тобі потрібно знайти... мій амулет.$B$BТемноглиб його забрав... Магреґан Темноглиб. Він десь тут... у руїнах, точно. Той амулет приведе їх... <кашель>... прямо до сувоїв, якщо його не зупинити. Це на тобі, $N. Будь ласка... добудь той амулет.$B$BСувої точно допоможуть Темному Залізу створювати ще потужніших ґолемів. Я це знаю. Я відчуваю це в своїх кістках.",
    O = "Знайди амулет Молотоступа і поверни його йому в Ульдамані.",
