},

[723] = {
    en = "Prospect of Faith",
    T = "Перспектива віри",
    D = "<Молотоступ тримається за свої рани і робить паузу, щоб зібратися з силами, перш ніж заговорити знову.>$B$BЗнайди Райєдола, $N. Принеси йому мій амулет. <кашель кашель> Він... <кашель> розбереться, що робити. Він знає, що я шукав витоки нашого народу, і він... <кашель>... знає, що моєю місією було зупинити клан Тінегорн. Їм не можна дозволити знайти сувої... <кашель>",
    O = "Віднеси амулет Молотоступа до Проспектора Райєдола в Безплідних краях.",
    P = "Я б сказав, що це був поганий день, але це Бедлендс: кожен день поганий день.",
    C = "Амулет Молотка? Мені здається, мій настрій підвищився, коли я думав, що він мертвий. Знання лише посилює біль. Цей амулет був справою його життя. Я не можу дозволити, щоб його смерть була марною.",
},

[724] = {
    en = "Prospect of Faith",
    T = "Перспектива віри",
    D = "Гаразд, гаразд... хто б знав, що робити?$B$BІсторик Карнік! Точно!$B$BВін у Залізогарті. Він зможе допомогти. Він і Молотоступ працювали разом, щоб знайти загублені артефакти в Ульдамані.$B$BГадаю, Тінегорни дізналися, що вони двоє знали більше, ніж припускали.$B$BРозкажи Карніку, що сталося з Молотоступом, і віддай йому амулет — він скаже, що робити далі.",
    O = "Віднеси амулет Молотоступа до Історика Карніка в Залізогарті.",
    P = "Ах, так. Ще один мандрівник, який шукає щось від гномів.$B$BMa Вибачте, але я зараз не маю часу відповідати на безглузді запитання.",
    C = "О! Ну, це зовсім інша справа. Ви, мабуть, ще не усвідомлюєте серйозності цієї справи, чи не так?$B$BI глибоко переживає загибель Молотопа, але якщо він послав вас сюди зі своїм амулетом, то він зрозумів, що поставлено на карту.$B$BWe пізніше доведеться знайти час, щоб оплакувати його смерть.$B$BLet я покажу вам одну з причин, чому цей амулет такий цінний.",
},

[725] = {
    en = "Passing Word of a Threat",
    T = "Передача звістки про загрозу",
    D = "$N, біжи і знайди Радника Белґрума якомога швидше. Розкажи йому, що ти бачив, і запитай, як він хоче, щоб ми діяли. Ця записка пояснить йому більше.$B$BТим часом я поговорю з духом Молотоступа. Може, він знає щось, що допоможе нам зупинити діяльність цих мерзенних Тінегорнів у Безплідних краях. Нам залишається лише молитися.",
