[735] = {
    en = "The Star, the Hand and the Heart",
    T = "Зірка, Рука і Серце",
    D = "Дайджест Яґіна, еге ж? Ти починаєш новий розділ нашого ордену десь? Неважливо, не мені питати.$B$BЯ допоможу тобі, бо в мене є зайвий примірник. Ми мусимо допомагати один одному, так? Саме так ми процвітаємо.$B$BМені потрібні три предмети сили. Принеси їх мені, і я віддам тобі дайджест.$B$BЯ не назву їхні імена. Вуха можуть нас підслухати. Але ось, я запишу їх.",
    O = "Поверни предмети, зазначені в записці Кісткорука, до Ґерріґа Кісткорука в Залізогарті.",
    P = "У вас є реліквії, про які я просив?",
    C = "Ти винахідливий, $C. Якщо ви справді зобов’язані розпочати нову главу нашого ордену, то я вірю, що ви добре ним керуватимете.",
},

[736] = {
    en = "The Star, the Hand and the Heart",
    T = "Зірка, Рука і Серце",
    D = "Тобі потрібен Дайджест Яґіна? Твій план, отже, зібрати нову зграю? Звісно, так і є... і звісно, я допоможу тобі, $gбрате:сестро;.$B$BАле ти також мусиш допомогти мені.$B$BМені потрібні три предмети сили. Принеси мені ці, і дайджест буде твій.$B$BЯ не можу назвати імена цих предметів, але я запишу їх.$B$BДобудь мені предмети з цього списку. Якщо ти це зробиш, то ти справді гідний відкрити власний розділ нашого ордену.",
    O = "Принеси предмети, зазначені в записці Бел’дуґура, до Хранителя Бел’дуґура в Підмісті.",
    P = "Як проходить твоя місія, $c.",
    C = "Я вражений! Ви володієте великими навичками або великим багатством, щоб отримати ці реліквії. У будь-якому випадку, ви для нас актив.",
},

[737] = {
    en = "Forbidden Knowledge",
    T = "Заборонене знання",
    D = "Ось дайджест для тебе, $N. Не потрібно нагадувати, що з ним треба поводитися дуже обережно. І тримати його подалі від недружніх рук.$B$BЦя книга містить багато правд...$B$B...А правда може палити.",
    O = "Принеси Дайджест Яґіна до Телдуріна.",
    P = "Хо! Тебе довго не було. Ви отримали дайджест?",
    C = "Ви зрозуміли! О, надія проблискує!$B$BYour зусилля ще можуть врятувати нас, $N. Тобі мають поставити пам'ятник! Святиню, яку вони повинні збудувати! Нехай буде славне ім’я твоє, доки у твоїх онуків не з’являться онуки!$B$BUnless...ВОНИ звільняються й піднімаються на поверхню.  Якщо це станеться, ви можете забути про дітей.$B$BIf ВОНИ звільнені, тоді ми всі їжа для черв’яків.",
},

[738] = {
