},

[741] = {
    en = "The Absent Minded Prospector",
    T = "Неуважний Проспектор",
    D = "То Проспектор хоче відправити таємничий скам’янілий відбиток до Ліги Дослідників у Дарнасі? Мені не подобається залишати Темнобережжя без нього.$B$BОсь, $n, достав цей таємничий скам’янілий відбиток до Головного Археолога Сивовуса в Дарнасі.",
    O = "Віднеси таємничий скам’янілий відбиток до Головного Археолога Сивовуса в Дарнасі.",
    P = "Що я можу для вас зробити, $R?",
    C = "боже! Доручіть Prospector Remtravel виявити таку знахідку!",
},

[742] = {
    en = "The Ashenvale Hunt",
    T = "Полювання в Ясенедолі",
    D = "Увага, юні шукачі пригод! Дикі землі Ясенедолу чекають на вас!$B$BОрда міцно закріпилася в землях на північ від Степів. Наші два форпости — Пост Шпилястого Древа і Форпост Зорамського Узбережжя — прагнуть принести славу Орді! Ті, хто хоче довести свою цінність, мають шукати настанов там. Зокрема: Сенані Громове Серце в Посту Шпилястого Древа, прямо на північ від Степів, шукає шукачів пригод, готових узяти участь у великому полюванні Ясенедолу!",
    O = "Поговори з Сенані Громове Серце в Посту Шпилястого Древа, Ясенеділ.",
    P = "",
    C = "Ласкаво просимо на новий кордон, $N. Ashenvale — це країна можливостей, де такий молодий $C, як ти, може знайти безмежні шанси довести свою мужність. Огляньте форпост тут і обов’язково вирушайте на Зорам-Странд, оскільки там також є ще один форпост Орди.$B$BYour присутність тут говорить мені, що ви прийшли дізнатися більше про полювання. Слухайте уважно, і я з радістю поділюся з вами тим, що вам потрібно знати.",
},

[743] = {
    en = "Dangers of the Windfury",
    T = "Небезпека Вітрокривих",
    D = "Дякую, що знайшов час поговорити зі мною, $N. Я Руул, воїн і вчитель.$B$BТи явно досяг віку, коли мусиш готуватися до своїх випробувань, якщо хочеш вирушати далі за межі Мулґору.$B$BЯкщо ти бажаєш випробувати свою силу, почни з пошуку гарпій Вітрокривих на південний схід. Вони гніздяться вздовж країв гір подалі від дороги.$B$BВони одні з наших природних ворогів тут, у Мулґорі, і будуть хорошим мірилом твоїх навичок.",
    O = "Принеси 8 пазурів Вітрокривих до Руула Орлокрилого в селі Криваве Копито.",
    P = "Люті Вітру — смертоносні вороги. З їхньою силою в битві може змагатися лише бажання свіжого м’яса.",
    C = "Ви добре зробили, $N. Здається, ви добре підготувалися до подорожі. Нехай вітер завжди буде вам у спину.",
},

[744] = {
    en = "Preparation for Ceremony",
    T = "Підготовка до церемонії",
    D = "$N, мій брат незабаром постане перед Вождем Кривавим Копитом, і для мене честь виготовити для нього головний убір.$B$BЯ хочу попросити тебе про послугу, поки я закінчую вичинку цих шкіряних ремінців. У мене немає часу, щоб зібрати достатньо пір’я, і я подумав, чи не могли б ви зібрати ще для мене?$B$BТи можеш знайти пір’я потрібного розміру у гарпій, що мешкають далеко на півночі і північному заході від Громового Бескиду. Мені потрібно лише 6 блакитних і 6 бронзових пір’їн, щоб завершити дизайн.",
    O = "Збери 6 блакитних пір’їн і 6 бронзових пір’їн і принеси їх до Ейяна Орлокрилого в Громовий Бескид.",
    P = "Цей головний убір точно стане чудовим подарунком для брата.",
    C = "Дякую за вашу допомогу, $N.$B$BMy участь у церемонії мого брата майже завершена. Подарувати йому його головний убір і бути свідком церемонії — все, що вимагається від мене.",
},

[745] = {
    en = "Sharing the Land",
    T = "Спільна земля",
    D = "$N, багато конфліктів ранять цю землю. Я сподіваюся, що ти не станеш свідком стількох із них, скільки бачив я. Але є один, який я попросив би тебе шукати. Він дасть тобі уявлення про те, наскільки жахливою, якщо її не зупинити, може бути навіть невелика загроза для землі.$B$BҐноли Блідошкурих оселилися на південь від Кривавого Копита і в печері на заході. Вони не поважають наші спроби спілкуватися з ними, і вони безконтрольно вбивають дику природу Мулґору.$B$BСлова більше не відповідь.",
    O = "Убий 10 дубильників Блідошкурих, 8 шкіродерів Блідошкурих і 5 браконьєрів Блідошкурих, а потім повернися до Бейна Кривавого Копита в село Криваве Копито.",
    P = "Якби Палемани більше поважали землю та її мешканців, цей конфлікт ніколи б не відбувся.",
    C = "$N, добре, що ти серйозно поставився до мого завдання. Повага до землі та її істот є важливою. Смерть і життя — це коло... необхідність. Одне не може існувати без іншого. Знайдіть час, щоб подумати про це, і ніколи не забуйте про це.",
},

[746] = {
    en = "Dwarven Digging",
    T = "Дворфійські розкопки",
    D = "Дворфи готують місце розкопок на північний захід. Вони думають, що в землі ховаються таємниці, і це правда, але викопувати і оскверняти землю — не спосіб заслужити її вчення.$B$BЗбери дворфійські інструменти для копання, розбий їх і повернися до мене з розбитими інструментами дворфів.$B$BТи можеш розбити інструменти в кузні. Одна є в Громовому Бескиді, але будь-яка кузня — навіть кузня в дворфійському таборі — підійде.",
    O = "Збери 5 кирк Проспекторів.$B$BУ кузні розбий кирки Проспекторів, щоб створити розбиті інструменти.$B$BПринеси 5 розбитих інструментів до Бейна Кривавого Копита в село Криваве Копито.",
    P = "Привіт, $N.  У вас є зламані інструменти?  Копання гномів розлютить кодос Мулгора.  Це осквернення має бути припинено!",
    C = "Дякую, $N. Це заспокоїть звірів Мулгора. І, за бажанням духів, воно навчить гномів, що виглиблення землі — це не шлях до знань.",
},

[747] = {
    en = "The Hunt Begins",
    T = "Полювання починається",
    D = "Ти маєш багатообіцяючий вигляд і доведеш свою цінність племені. Можливо, незабаром тебе приймуть у велике місто Громовий Бескид. Але перед цим ти мусиш довести себе моєму батькові, Вождю Яструбокрилу.$B$BТут, на плато Червоної Хмари, ми пишаємося гострими мисливськими навичками. Таурени полюють із необхідності і для спорту. Наші запаси м’яса вичерпалися, і нам потрібне пір’я для одягу. Полюй на рівнинних бігунів неподалік і доведи себе, поповнивши запаси села.",
    O = "Ґрулл Яструбокрил у таборі Нараче хоче, щоб ти приніс йому 7 пір’їн рівнинного бігуна і 7 шматків м’яса рівнинного бігуна.",
    P = "Забезпечення племені м’ясом і пір’ям – це перший крок до того, щоб довести себе як $C перед Вождем.",
    C = "Таурен з Нараче дякую, $N. Ви багатообіцяєте.",
},

[748] = {
    en = "Poison Water",
    T = "Отруєна вода",
    D = "Гобліни та їхні слуги осквернили наші священні водяні колодязі! Ми не можемо цього дозволити.$B$BЩоб очистити кожен колодязь, я мушу створити очисний тотем, а потім ти мусиш принести тотем до колодязя і виконати ритуал очищення.$B$BСпочатку ми створимо очисний тотем для Водяного Колодязя Зимового Копита. Для цього земля мусить надати свою допомогу. Полюй на степових вовків за їхніми лапами і на дорослих рівнинних бігунів за їхніми пазурами. Вони на південний захід.$B$BПовернися до мене з лапами і пазурами, $N.",
    O = "Принеси 6 лап степового вовка і 4 пазурі рівнинного бігуна до Мулла Громорогого в Криваве Копито.",
    P = "У тебе є лапи й кігті, $N?",
    C = "Ви добре зробили, $N. Я візьму їх і зв’яжу їх силу в тотем очищення.",
},

[749] = {
    en = "The Ravaged Caravan",
    T = "Зруйнований караван",
    D = "Кілька днів тому ми знайшли караван Компанії Вентур, що подорожував під охороною на північному березі озера Кам’яного Бика. Ми втратили двох наших у попередній битві, тож ми швидко напали і знищили караван.$B$BМи залишили їхні ящики з припасами, думаючи, що наші смолоскипи знищать усе цінне, але, враховуючи, що спасателі Компанії Вентур були помічені біля згорілих возів, можливо, ми помилилися.$B$BМоже, ти міг би піти до каравану і оглянути вміст ящиків.",
    O = "Морін Хмаролов хоче, щоб ти оглянув вміст ящика з припасами у зруйнованому каравані.",
    P = "",
    C = "Усі сторони ящика мають штамп із знаком Mining Division Venture Co. Примітки, акуратно надруковані на боці коробки, вказують на те, що вміст має бути перероблено на одному з центральних заводів.",
},

[750] = {
    en = "The Hunt Continues",
    T = "Полювання триває",
    D = "Таурен, вправний у мистецтві полювання, знає, що його здобич — не просто трофей. Звірі рівнин забезпечують нам засоби для виживання. Ти справиш велике враження на старійшин, якщо зможеш принести цінні шкури гірських пум. Ти можеш знайти цих звірів, що ховаються в пагорбах на південь.$B$BНашим дітям потрібен одяг, а наші намети потребують ремонту.",
    O = "Ґрулл Яструбокрил у таборі Нараче хоче, щоб ти приніс йому 10 шкур гірських пум.",
    P = "Якщо ти зможеш надати племені шкури, я передам своєму батькові, вождю Яструбу, про твої щедрі вчинки.",
    C = "Таурен з Нараче дякує вам за ці запаси, $N. Завдяки твоєму вмінню полювати, ти неодмінно колись будеш шанований у Громовому Утесі.",
},

[751] = {
    en = "The Ravaged Caravan",
    T = "Зруйнований караван",
    D = "Відкривши кришку, ти бачиш щільно упаковану суміш руди і мінералів, ще один доказ гірничої операції Компанії Вентур у Мулґорі. На вершині руди і мінералів ти виймаєш щільно зв’язану пачку паперів.$B$BУ передгір’ях на схід ти ледь чуєш звуки роботи і бачиш дим, що піднімається від великого вогню.",
    O = "Поверни документи Компанії Вентур до Моріна Хмаролова біля села Криваве Копито.",
    P = "Вітаю, $N. Чи дізналися ви щось нове про плани та операції Venture Co. на нашій батьківщині?$B$BIf вони планують використовувати наші землі так само, як і інші, аутраннери швидко покладуть цьому край.",
    C = "Дійсно виглядає, що Venture Co. намагається пограбувати у нас наші природні ресурси. Добре знати це насправді, і тепер, здається, ми повинні щось з цим робити.",
},

[752] = {
    en = "A Humble Task",
    T = "Скромне завдання",
    D = "Усі члени племені діляться гармонією життя. Ми живемо разом і працюємо разом.$B$BНаша відданість один одному несе велику відповідальність. Я прошу тебе виконати скромне завдання.$B$BМоя мати вирушила сьогодні вранці по воду до колодязя на південний схід від Нараче. Минуло вже чимало часу. Може, ти міг би перевірити, чи все з нею гаразд, поки я займаюся справами племені тут?",
    O = "Вождь Яструбокрил хоче, щоб ти пошукав його матір біля водяного колодязя на південний схід від табору Нараче.",
    P = "",
    C = "Ви пройшли весь цей шлях, щоб допомогти старій жінці? Мій мій, ти не сторож?",
},

[753] = {
    en = "A Humble Task",
    T = "Скромне завдання",
    D = "Я пройшла багато шляхів у житті, і ці старі ноги вже не такі бадьорі, як колись. Я все ще можу виконувати свої обов’язки перед племенем. Іноді старій жінці просто потрібно трохи більше часу, щоб виконати завдання.$B$BАле ти виглядаєш як енергійний $c. Давай перевіримо твою юнацьку бадьорість. Візьми глечик води з колодязя і принеси його моєму синові, Вождю, в табір Нараче.$B$BПам’ятай, що навіть найскромніше завдання може заслужити визнання старійшин.",
    O = "Візьми глечик води з водяного колодязя.$B$BПоверни глечик до Вождя Яструбокрила в табір Нараче, який на північний захід від колодязя.",
    P = "Ти виглядаєш так, наче повернувся з рівнини. У вас є якісь повідомлення від Великої Матері Яструбиного вітру?",
    C = "Я бачу, що ви принесли цей глечик назад за наказом Великої Матері.$B$BYour Готовність допомагати іншим і забезпечувати тауренів табору Нараче змушує мене вірити, що колись ви змусите плем’я пишатися Громовим Утесом.",
},

[754] = {
    en = "Winterhoof Cleansing",
    T = "Очищення Зимового Копита",
    D = "Я створив тотем для очищення Водяного Колодязя Зимового Копита. Тепер ти мусиш взяти його до колодязя і виконати ритуал очищення. Ти знайдеш його на південний схід, його охороняють мерзенні гобліни!$B$BЦе не буде легким завданням, але ти мусиш це зробити, якщо ми хочемо знову використовувати його води.$B$BХай щастить тобі, $N.",
    O = "Використай Очисний Тотем Зимового Копита біля Водяного Колодязя Зимового Копита, а потім повернися до Мулла Громорогого.",
    P = "Очистіть водяний колодязь Winterhoof",
    C = "Звістка про твій вчинок дійшла до мене миттєво тому — вже звірі біля криниці п’ють його охоче.$B$BYou велику справу зробили для краю, $N. І ви зробили велику справу для народу Таурен.",
},

[755] = {
    en = "Rites of the Earthmother",
    T = "Обряди Матері-Землі",
    D = "Твоя готовність виконати скромне завдання для тауренів Нараче і твоє прагнення вчитися — шляхетні риси, $n. Я вірю, що одного дня тебе прославлятимуть у Громовому Бескиді як великого $c.$B$BПеред цим ти мусиш пройти Обряди Матері-Землі, яких є три.$B$BПерше випробування — Обряд Сили. Вирушай до Провидиці Сивомузика і скажи їй, що Вождь Яструбокрил послав тебе.$B$BТи знайдеш оселю провидиці прямо на південь від табору Нараче, заховану в пагорбах.",
    O = "Вирушай до Провидиці Сивомузика, яка живе в пагорбах прямо на південь від табору Нараче.",
    P = "",
    C = "Вас прислав вождь Яструбиний Вітер? Приступити до обрядів Матері-Землі – непросте завдання...",
},

[756] = {
    en = "Thunderhorn Totem",
    T = "Тотем Громового Рогу",
    D = "Щоб створити Очисний Тотем Громового Рогу, ти мусиш зібрати пазурі хижаків рівнин Мулґору. Полюй на степових мисливців за їхніми пазурами мисливця і на рівнинних пум за їхніми пазурами пуми, а потім повернися до мене.$B$BТи знайдеш степових мисливців і рівнинних пум на схід і захід.",
    O = "Принеси 6 пазурів мисливця і 6 пазурів пуми до Мулла Громорогого.",
    P = "$N, у тебе є кігті, які я послав тобі зібрати? Водяний колодязь Thunderhorn з кожною годиною стає все більш забрудненим!",
    C = "Дякую, $N. Чистота, з якою ці звірі полюють, є життєво важливою для створення наступного очисного тотема.$B$BThe гобліни ніколи не дізнаються різниці між боротьбою з землею та життям у гармонії з нею.",
},

[757] = {
    en = "Rite of Strength",
    T = "Обряд Сили",
    D = "Обряди Матері-Землі — це кроки, які молодий таурен мусить зробити, щоб заслужити повагу в Громовому Бескиді.$B$BСпочатку ти мусиш пройти Обряд Сили. У цьому випробуванні ти мусиш довести свою хоробрість, знищуючи ворогів племені.$B$BЩетиноспини з Яру Шиполистого на схід зазіхають на наші племінні землі. Вони влаштовують засідки на наші мисливські загони і крадуть із села в темряві.$B$BПокажи свою доблесть, знищивши цих лиходіїв, і повернися до Вождя в табір Нараче з їхніми поясами як доказ твоїх діянь.",
    O = "Убий щетиноспинів у Яру Шиполистого і принеси 12 поясів щетиноспинів до Вождя Яструбокрила в табір Нараче.",
    P = "Ви завершили Обряд Сили, $N? Мені потрібен доказ вашої хоробрості проти ворога нашого племені, Бристлбеків.",
    C = "Ви пройшли перше випробування Обрядів Матері-Землі. Плем'я буде пишатися.",
},

[758] = {
    en = "Thunderhorn Cleansing",
    T = "Очищення Громового Рогу",
    D = "Тотем готовий, $N. І знову, твоє завдання — виконати ритуал очищення.$B$BІди до Водяного Колодязя Громового Рогу, на північ від села, і використай Очисний Тотем Громового Рогу у своєму ритуалі. Після цього повернися до мене.$B$BХай духи ведуть тебе.",
    O = "Використай Очисний Тотем Громового Рогу біля Водяного Колодязя Громового Рогу, а потім повернися до Мулла.",
    P = "Очистіть водяний колодязь Громового Рогу",
    C = "Предки роду Громових Рогов говорили зі мною уві сні, вихваляючи тебе за твої дії біля їх колодязя.$B$BFor свою вдячність, вони бажають подарувати тобі це...",
},

[759] = {
    en = "Wildmane Totem",
    T = "Тотем Дикогривих",
    D = "Залишився лише один водяний колодязь для очищення, названий на честь клану Дикогривих. Щоб цей колодязь був чистим, земля мусить пожертвувати зуби лютого хижака, альфа-степового вовка. Знайди альф на півночі, а потім повернися до мене, коли твоє полювання завершиться.$B$BАльфи часто блукають біля підніжжя нашого величного міста, Громового Бескиду.",
    O = "Принеси 8 зубів альфа-степового вовка до Мулла Громорогого в село Криваве Копито.",
    P = "$N. У вас є зуби, які я просив?",
    C = "Дуже добре, $N. Я відчуваю жертву землі в цій жертві, і мій дух переповнюється смутком і гордістю.",
},

[760] = {
    en = "Wildmane Cleansing",
    T = "Очищення Дикогривих",
    D = "Твоє очищення колодязів Зимового Копита і Громового Рогу відоме серед духів, юний $N. Тотем Дикогривих створено, і попереду твоє останнє завдання.$B$BВодяний Колодязь Дикогривих лежить на північ від Громового Бескиду. Виконай ритуал! Зціли землю від отрут гоблінів! Нехай чиста вода знову тече!",
    O = "Використай Очисний Тотем Дикогривих біля Водяного Колодязя Дикогривих, а потім повернися до Мулла Громорогого.",
    P = "Очистіть криницю Wildmane",
    C = "Ви зробили це. Ви очистили криниці, оздоровили нашу землю. Село Bloodhoof вдячне, $N.$B$BMay вітер шепоче про ваші вчинки протягом ста сезонів, і нехай води Мулгора залишаться чистими назавжди.",
},

[761] = {
    en = "Swoop Hunting",
    T = "Полювання на яструбів",
    D = "Яструб — хитрий птах, якого важко знайти і полювати. Збірка пір’їн яструба — це знак кмітливості і рішучості для мисливця.$B$BЯкщо ти готовий узятися за це завдання, то вирушай у рівнини і полюй на яструбів.$B$BПринеси мені їхні пір’їни, і принеси честь своєму клану.$B$BЯструбів можна знайти будь-де в Мулґорі, але твої очі мусять бути гострими, щоб їх помітити, а твої копита — швидкими, щоб їх спіймати.",
    O = "Принеси 8 трофейних пір’їн яструба до Гаркена Вітрототема в село Криваве Копито.",
    P = "Ти знайшов нальоти, $N.  У вас є їх перо?",
    C = "Я знаю, що збирати ці перо було непростим завданням, $N. Роблячи це, ви доводите, що маєте $C заслуг. Приємно бачити вас у Bloodhoof Village.",
},

[762] = {
    en = "An Ambassador of Evil",
    T = "Посол зла",
    D = "Посол Інфернус був посланий до фортеці Анґор самим Раґнаросом, щоб наглядати за Тінегорнами, які шукають загублені артефакти в Ульдамані.$B$BЦе вже призвело до величезних втрат серед нашого народу, але, очевидно, стало ще гірше. Я вагаюся гадати, скільки артефактів вони могли б знайти і використати проти Залізогарта.$B$BНаша мета проста, $c. Повернися до Безплідних країв і знищ Посла Інфернуса. Щойно загрозу буде усунуто, повернися до Радника Белґрума з доказом твоєї перемоги.$B$BТепер це в твоїх руках.",
    O = "Убий Посла Інфернуса у фортеці Анґор і принеси доказ його смерті до Радника Белґрума в Залізогарті.",
    P = "Час має значення, $N. Рагнарос не чекатиме, поки ми підготуємось.",
    C = "$N, твою відданість Стальгорну та гномам неможливо спростувати. Я дякую вам за вашу допомогу в цьому питанні.$B$BI надішле історику Карніку повідомлення про те, що ви досягли успіху, і я також розпоряджуся якомога швидше надіслати допомогу в Безплодні землі, щоб допомогти відновити місце розкопок. Ще раз дякую.$B$BBefore йдіть, я хотів би вас ще про одне попросити від імені короля Бронзоборода.",
},

[763] = {
    en = "Rites of the Earthmother",
    T = "Обряди Матері-Землі",
    D = "Щоб продовжити Обряди Матері-Землі, ти мусиш пройти ще два випробування. Настав час розширити твій досвід, $n.$B$BВирушай до села Криваве Копито і знайди Вождя, Бейна Кривавого Копита, сина Керна. Там ти зможеш продовжити свою подорож і заслужити визнання старійшин Громового Бескиду.$B$BВізьми цей тотем до Бейна. Він упізнає мої різьблення і допоможе тобі на твоєму шляху.$B$BСлідуй дорогою з табору Нараче і поспішай. Не збивайся зі шляху, інакше загубишся.",
