[846] = {
    en = "Revenge of Ga$b$b",
    T = "Помста Ґанна",
    D = "З планів Хазґорма ясно, що дворфи покладалися на вибухівку та ці гучні машини, щоб розривати землю.$B$BЯ хочу, щоб дворфи скуштували власної отрути. Згідно з цими планами, якщо ми поєднаємо нітрогліцерин із деревною масою та нітратом натрію, ми зможемо створити вибуховий заряд. Стрілки, солдати та офіцери в фортеці, як відомо, мають ці припаси.$B$BЗбери ці предмети і принеси їх мені. Я виготовлю заряд, який дворфи не забудуть!",
    O = "Ґанн Кам’яний Шпиль хоче, щоб ти приніс йому 6 флаконів нітрогліцерину, 6 зв’язок деревної маси і 6 зразків нітрату натрію.",
    P = "Я бачу, ти повернувся, $N.$B$BWhile Смерть Кхазгорма може дещо затримати розкопки на землях моїх предків, але в жодному разі не припинить повне знищення.$B$BThe Триматися в Баель-Модані — це зростаюча військова загроза. Створений для захисту місця розкопок, тепер він також готовий до наступальної сили.$B$BIf у вас є інгредієнти, які я просив, я можу створити заряд, який змусить поспішних гномів переглянути свої дії тут, у Степлі.",
    C = "Я бачу, що ви досить працьовиті, $C.$B$BNo сумніваюся, що незабаром ми матимемо відповідний сюрприз для цих гномів.",
},

[847] = {
