[905] = {
    en = "The Angry Scytheclaws",
    T = "Розлючені серпокігті",
    D = "Тепер, $N, полювання стає глибшим. Тепер ти мусиш перемогти свою здобич і знайти шлях до її лігва.$B$BПолюй на сонячнолуских рапторів на півдні. Убий їх і забери пір’я, які вони носять. Поклади пір’я на гнізда серпокігтів на південний захід від Застійного Оазису. Покажи їхнім побратимам, що ти їх не боїшся!",
    O = "Убий сонячнолуских рапторів і збери їхні пір’я. Використай пір’я на 3 гніздах серпокігтів. Повернися до Сергри Темношип на Перехресті.",
    P = "Ти був у гніздах, $N?",
    C = "Ваше завдання виконано? Поміркуйте про життя Scytheclaw, коли ви це робите. Кожна істота містить важливі уроки. $B$BSome з інших вважають, що я був надто важким на уроці. Я знаю, що ви просто виконуєте мої накази, але я хочу, щоб ви подумали про життя істот, яких ви вбиваєте. $B$BThough часом вони неприємні, вони стають загрозливими лише тоді, коли ми хочемо їх убити. Сьогодні осквернення завдасть нам більше проблем, ніж вирішить проблеми...",
},

[906] = {
    en = "Betrayal from Within",
    T = "Зрада зсередини",
    D = "Візьми голову Лока до Торка на Перехресті, $r. <хрюк> Він має зрозуміти, що сталося з моїм племенем, без зайвих слів — ха, не те щоб він повірив, що Манглезуб допомагав у <хрюк> таких справах. Але я впевнений, він винагородить тебе за виконання такого великого подвигу. <хрюк>$B$BЯ продовжуватиму благословляти тебе силою Аґамаґґана, доки я залишаюся в цій клітці, $r. До того часу — прощавай.",
    O = "Принеси череп Лока до Торка на Перехресті в Степах.",
    P = "Так, що це?",
    C = "Ти знайшов лідера Бритогривих і сам його вбив, $N? Чудово.$B$BI я без слів, але це не означає, що я без подяки. Людям Перехрестя було б добре поважати твою силу.$B$BI Мушу визнати, я думав, що лідером цих набігів на наші лінії постачання був ще один quilboar. Ще раз дякую, $N.",
},

[907] = {
    en = "Enraged Thunder Lizards",
    T = "Розлючені громоящери",
    D = "Тепер, $N, ти мусиш зіткнутися з великими громоящерами. Ці звірі такі великі, що земля тремтить, коли вони гупають по рівнинах. Будь обережний, борючись із ними, адже один неправильний крок — і ти можеш опинитися під їхніми ногами.$B$BТи знайдеш громоящерів у південних Степах. Їх називають Громошнобами, Громошкурами і Громоголовами. Повернися до мене, коли переможеш їх.",
    O = "Принеси 3 порції крові громоящера до Джорна Небозора в табір Таураджо.",
    P = "Чи перемогли грозових ящірок, $N?",
    C = "Приємно бачити, що ти повертаєшся з доказом перемоги. І добре знати, що ви зробили це, не зламавши кістки.",
},

[908] = {
    en = "",
    T = "Серед руїн",
    D = "Молот Сутінків оселився в руїнах Місячного Святилища в Глибинах Чорного Танку. Їхня присутність лише змушує стихії працювати проти нас. Якщо їх не зупинити, ця область назавжди стане їхньою.$B$B$N, вирушай у Чорний Танк і знайди глибокий камінь руїн; він має бути десь у воді. У ньому є глибоке ядро — пристрій, який, якщо правильно прочитати, розповість історію всієї стихійної активності. Якщо я матиму його, ми з Кільцем Землі, можливо, зможемо щось зробити, щоб їх зупинити!",
    O = "Принеси Глибоке Ядро до Дже’неу Санкреа в заставі Зорам’ґар, Ясенеділ.",
    P = "",
    C = "",
},

[909] = {
    en = "",
    T = "Барон Акваніс",
    D = "Переможений водяний елементаль залишив по собі дивну водяну кулю. Ти припускаєш, що цей об’єкт якимось чином живив звіра енергією. Всередині кулі гойдається брудна на вигляд вода. Сама куля здається невразливою до будь-якої фізичної сили.$B$BЯкщо хтось і може розібратися з цим предметом, то це Дже’неу Санкреа з Кільця Землі. Він перебуває в заставі Орди Зорам’ґар у Ясенедолі.",
    O = "Принеси Дивну Водяну Кулю до Дже’неу Санкреа в заставі Зорам’ґар, Ясенеділ.",
    P = "",
    C = "",
},

[910] = {
    en = "Down at the Docks",
    T = "На причалі",
    D = "Я чув історії про могутні кораблі, що плавають між Трісфалем і Бухтою Скарбів! Було б так круто пливти океаном і битися в багатьох великих морських битвах. Може, коли виросту, я стану могутнім моряком Орди! Так!$B$BЧи не могли б ви відвести мене подивитися на доки Трісфаля, будь ласка? Я обіцяю не лізти у воду і не створювати проблем — я просто хочу побачити великі кораблі і вдихнути солоне морське повітря! Так!",
    O = "Відведи свого підопічного до доків Трісфаля в Степах.",
    P = "Ми вже там?",
    C = "Ого, океан ВЕЛИЧЕЗНИЙ! Там було багато морських чайок і таке інше – тут так само гамірно й гамірно, як я й думав. Поруч також є пірати - так круто!$B$BThank ти за те, що привів мене до Ратчет, $N. Це було так круто!",
},

[911] = {
    en = "Gateway to the Frontier",
    T = "Ворота до рубежу",
    D = "Кажуть, що Ясенеділ — це новий рубіж, а Вал Мор’шан у Степах — це ворота до нього. Було б так круто бути піонером, вирубуючи все необхідне з диких земель! Кажуть, що саме тут Орда і Альянс зіткнуться найбільше в майбутньому, і я хочу бути там, $N!$B$BЧи не могли б ви відвести мене до Валу Мор’шан, щоб я побачив, як виглядає рубіж, будь ласка? Я хочу побачити, де Орда виганяє цих смердючих нічних ельфів!",
    O = "Відведи свого підопічного до Валу Мор’шан у північній частині Степів, перед входом у Ясенеділ.",
    P = "Ідіть до валу Мор'шан у Степлі.",
    C = "Ого! Ясеневий ліс — це місце, де відбуваються справжні пригоди! Ти коли-небудь бився в Ясеневому долі, Йохане? Коли я стану героєм, коли виросту, я хочу приїхати в Ясеневий ліс і битися за славу Орди!$B$BThank ти за те, що привів мене на кордон, $N. ти найкращий!",
},

