[928] = {
    en = "Crown of the Earth",
    T = "Корона Землі",
    D = "Хоча я міг би розповісти тобі більше про місячні колодязі та Тельдрассіль, я мушу відправити тебе далі. Корітрас Місячна Лють чекатиме на тебе. Я перелив флакон води, який ти мені приніс, у цю посудину, щоб ти відніс її йому.$B$BЗнайди Корітраса. Ти знайдеш його біля місячного колодязя в Доланаарі. Іди дорогою на південь із Альдрассіля, виходячи з Тіневого Гаю, і продовжуй слідувати за бруківкою, коли дорога поверне на захід.$B$BАле тримайся дороги, $n. Останнім часом у лісах з’явилися небезпечні звірі.",
    O = "Принеси Частково Наповнену Посудину до Корітраса Місячної Люті в Доланаарі.",
    P = "Вітаю, $C. Чому я зобов'язаний задоволенням від нашої зустрічі?",
    C = "Ах, я бачу. Вас прислав Тенарон. Ну тоді, здається, у нас є про що поговорити, багато чого зробити, і мало часу, щоб це зробити.$B$BI думаю, що нам краще почати.",
},

[929] = {
    en = "Crown of the Earth",
    T = "Корона Землі",
    D = "Спочатку дозволь розповісти тобі більше про завдання, яке ти мусиш виконати. Друїди в Дарнасі використовують воду місячних колодязів Тельдрассіля, і їхній колодязь час від часу потрібно поповнювати. За допомогою цих спеціально створених флаконів ти можеш збирати воду колодязів.$B$BВізьми цю посудину до місячного колодязя біля села Зіркобриз на сході і наповни її водою, а потім повернися до мене. Коли ти виконаєш своє завдання, я продовжу історію там, де зупинився Тенарон...",
