[942] = {
    en = "The Absent Minded Prospector",
    T = "Неуважний Проспектор",
    D = "Цей скам’янілий предмет дуже нагадує той, який я колись бачив у Залізогарті. Археолог на ім’я Флаґонґут привіз його на нашу щорічну конференцію Ліги Дослідників. Він вважав, що скам’янілість має силу, яку можна якось розблокувати.$B$BОстаннє, що я чув, Флаґонґут зачинився в таверні Глибоководдя в гавані Менетіл, чекаючи на ескорт до розкопок Велґара. Знайди його і покажи йому скам’янілість Ремтревела. Можливо, він зможе розкрити таємниці минулого.$B$BКорабель до Менетіла відпливає з Аубердіна.",
    O = "Віднеси таємничу скам’янілість до Археолога Флаґонґута в гавані Менетіл.",
    P = "Що ти там маєш, друже?",
    C = "боже! Ви кажете, що це прийшло з далеких земель Калімдору?$B$BAmazing! Просто неймовірно!",
},

[943] = {
    en = "The Absent Minded Prospector",
    T = "Неуважний Проспектор",
    D = "Проспектор Велґар тепер тримає оригінальну скам’янілість на своєму місці в Болотинах. Коли я знайшов Камінь Релу, я вважав, що він є ключем до розкриття таємниці скам’янілості.$B$BПоки я подорожував дорогою, щоб зустрітися з Велґаром, на мене напали раптори, і реліквія була втрачена. Я не знаю, який із цих строкатих звірів проковтнув реліквію, але якщо ти зможеш її повернути, я зможу розкрити силу цих артефактів.$B$BПринеси мені Камінь Релу і оригінальну скам’янілість, яку тримає він.",
    O = "Археолог Флаґонґут у гавані Менетіл хоче, щоб ти приніс йому Камінь Релу і Скам’янілість Флаґонґута.",
    P = "За допомогою каменю Релу я зможу відкрити приховані секрети моєї скам’янілості, а також скам’янілості Ремтревела з Темних берегів, $N.",
    C = "Чудово, $N!$B$BNow, щоб дізнатися, чи зможу я використати камінь, щоб розшифрувати силу скам’янілостей.",
},

[944] = {
    en = "The Master's Glaive",
    T = "Майстрова Глефа",
    D = "Дивно, що наґи тут, у Темнобережжі. Але ще дивніше... це Молот Сутінків. Цей культ поклоняється старим, дуже старим лордам землі. Лордам, переможеним давно.$B$BМайстрів Глефа, на півдні, — це місце, де впав один із таких старих лордів.$B$BІди туди і пошукай більше культистів Молота Сутінків.$B$BВізьми цей флакон для ворожіння. Використай його, щоб створити чашу ворожіння після огляду Майстрової Глефи. Потім поговори зі мною через чашу.",
    O = "Збери інформацію, а потім використай Флакон Ворожіння, щоб створити Чашу Ворожіння. Використай чашу, щоб поговорити з Ону.",
    P = "Глефа Майстра, $N.$B$BGo там, тоді поговоріть зі мною знову.",
    C = "Сутінковий Молот у Глефі Майстра?$B$BUnfortunate.$B$BThe старий лорд, проколотий Глефою, давно мертвий, але це не означає, що уламки його сили ще не залишилися.$B$BThe Сутінковий Молот, мабуть, шукає цієї сили.",
},

[945] = {
    en = "Therylune's Escape",
    T = "Втеча Терилуни",
    D = "Допоможи!$B$BЯ блукав біля Майстрової Глефи, і ці брудні культисти оточили мене. Добре, що я вмію ховатися!!$B$BЧи можеш ти допомогти мені вибратися звідси? І мені потрібно повідомити мою сестру Терисіль, що зі мною все гаразд. Вона в Ясенедолі, у Святилищі Аессінни.",
    O = "Допоможи Терилуні втекти, а потім скажи Терисіль у Святилищі Аессінни, що її сестра в безпеці.",
