[980] = {
    en = "The New Springs",
    T = "Нові джерела",
    D = "Я чув про інші гарячі джерела в місці під назвою Зимоключ, далеко на півночі звідси. Дивно те, що поблизу немає жодних вулканів. Цікаво, правда?$B$BЯкщо хочеш дізнатися більше, вируш до Зимоключа і поговори з моєю подругою. Її звати Донова Сноуден, і вона зараз перебуває біля гарячих джерел.$B$BЩе раз дякую за допомогу з моїм термометром! До зустрічі!",
    O = "Вируш до Зимоключа і поговори з Доновою Сноуден.",
    P = "",
    C = "Привіт, $N. Так, те, що вам сказав Кракл, правда...",
},

[981] = {
    en = "The Tower of Althalaxx",
    T = "Вежа Алталаху",
    D = "За всю роботу, яку ти виконав, ти заслуговуєш на щедру винагороду. Повернися до Делґрена і скажи йому, що Атрикус Нарассін упав від твоєї руки, а Культ Темного Пасма розбитий і розсіяний.",
    O = "Поговори з Делґреном Очищувачем у Форпості Маестри.",
    P = "",
    C = "Я знав, що ти впораєшся з цим завданням, $B$BI передчуваєш великі справи, і що ти виправиш багато кривд, які мучать наші землі. Прийми мої благословення, $N, а також цей подарунок.",
