[1007] = {
    en = "The Ancient Statuette",
    T = "Старовинна статуетка",
    D = "Я доручаю тобі завдання, $N.$B$BЯ був на своєму маленькому судні, пропливаючи над затопленими руїнами Зораму, коли на мене напали наґи, виринувши з води і роздираючи мене своїми кігтями! Я втік, несучи які міг припаси, щоб облаштувати цей скромний табір.$B$BАле коли я дістався до берега і побіг... я втратив свою цінну річ.$B$BБудь ласка, $N, знайди місце мого нападу, вздовж узбережжя на півночі, і пошукай старовинну статуетку. Це причина, чому я наважився на небезпеки Зорамського Пасма.",
    O = "Принеси Старовинну Статуетку Талену в його табір біля Зорамського Пасма.",
    P = "Ти знайшов статуетку, $N?",
    C = "Ви знайшли його! Дякую, $N!$B$BThe Старе місто Зорам зберігає багато таємниць, і ця статуетка може бути ключем до багатьох із них.",
},

[1008] = {
    en = "The Zoram Strand",
    T = "Зорамське Пасмо",
    D = "На нашому північно-західному узбережжі, відомому як Зорамське Пасмо, ховається зло.$B$BЦе місце спочинку приреченого міста Зорам, зруйнованого під час Розлому і затопленого морями. Воно було втрачене для нічних ельфів на віки. Втрачене і майже забуте.$B$BТепер наґи повернулися, і з якою метою — ми не знаємо. Але причина мало важить; ми мусимо знищити цих мерзотників і скинути їх назад у глибини!$B$BПовернися до мене, коли твоя місія буде виконана.",
    O = "Принеси 20 голів гнівохвостів Шіндрелл Швидковогню в Астранаар.",
    P = "Ми не можемо дозволити нагам вторгнутися на наше узбережжя, $N.  Важливо, щоб ви пішли на Zoram Strand і завершили свою місію.",
    C = "Дуже добре, $N.  Ваші дії в зоні Зорам проти наг заслуговують похвали.$B$BI знайте, що ваш подвиг був нелегким, бо сила й підступність наг добре відомі нічним ельфам.  Ми це знаємо, бо у нас з ними спільна історія.$B$BIt — це історія, яку я хочу не повторити.",
},

[1009] = {
    en = "Ruuzel",
    T = "Руузель",
    D = "Я боюся, що таємниці старовинної статуетки залишаться назавжди прихованими, якщо ти не знайдеш ключ до її старовинного замка.$B$BЦей ключ — перстень, Перстень Зораму. Він належав правителям цього міста, перш ніж хвилі Розлому затопили його.$B$BРоками перстень був втрачений, але нещодавно наґи його знайшли.$B$BЇхня лідерка, Руузель, мешкає на острові на північному краю Зораму. Будь ласка, $N, добудь цей перстень для мене!",
    O = "Принеси Перстень Зораму Талену біля Зорамського Пасма.",
    P = "Кажуть, що Кільце Зорама є ключем до будь-якого замку в місті. У вас є, $N?",
    C = "Ти знайшов каблучку! Дякую, $N. Будь ласка, прийми це як плату, і знай, що твої сьогоднішні справи назавжди залишаться в моїй пам'яті.",
},

[1010] = {
    en = "Bathran's Hair",
    T = "Волосся Батрана",
    D = "У старих руїнах Притулку Батрана на півночі росла рослина, відома як Волосся Батрана, яка могла лікувати недуги духу.$B$BУ селищі є хвора дитина, і я вірю, що це більше, ніж просто фізична хвороба. Чи не могли б ви вирушити до Притулку Батрана і пошукати Волосся Батрана? Воно може знадобитися мені, щоб належно лікувати дитину.$B$BПритулок Батрана лежить на північ від Форпосту Маестри і трохи південніше кордону з Темнобережжям.",
    O = "Принеси 5 Волосся Батрана Оренділу Широколисту в Ясенедолі.",
    P = "Ти зібрав волосся Батрана, $N?  Здоров'я дитини слабшає з кожною годиною...",
    C = "Ах, у вас є волосся!  Тепер я змішаю ліки для дитини і нехай моя суміш подіє.$B$BAnd... Покинуті перебувають у притулку Батран?  Це дуже неприємно чути.  Дійсно дуже тривожно...",
},

[1011] = {
    en = "Forsaken Diseases",
    T = "Хвороби Покинуті",
    D = "Покинуті, нежить Орди, прокралися до Ясенедолу, ховаючись у наших руїнах і курганах. Ми вважаємо, що їхня мета — поширювати хвороби серед земель нічних ельфів. Ми мусимо це підтвердити!$B$BПокинуті мають табір на південь звідси, біля кургану Дор’Даніл, де вони створюють отрути та хвороби і розливають їх у пляшки. Пробийся до цього табору і викради пляшку з хворобою. Повернися з такою пляшкою. Я перевірю її і з’ясую її призначення.",
    O = "Принеси Пляшку Хвороби Кайнету Тишковітру в Лісопісні.",
    P = "Ти знайшов табір, $N? У вас є пляшка хвороби?",
    C = "Дуже добре, $N. Тепер... випробувавши вміст цієї пляшки, будуть виявлені цілі Покинутих!",
},

[1012] = {
    en = "Insane Druids",
    T = "Божевільні друїди",
    D = "Коли я боровся з отрутами Покинуті, у мене було видіння. Я бачив друїдів у кургані Дор’Даніл, отруєних... убитих нежиттю! Тепер вони блукаючі привиди, відірвані від своїх тіл і доведені до божевілля.$B$BЩоб духи друїдів колись знайшли спокій, ти мусиш увійти до кургану Дор’Даніл і знищити їхніх колись великих лідерів: Таніла Темноліса, Утіля Місячного Клича і Маворіса Хмаролама.$B$BЗроби це і повернися до мене.",
    O = "Убий друїдів: Таніла Темноліса, Утіля Місячного Клича, Маворіса Хмаролама; потім повернися до Кайнета Тишковітру в Лісопісні.",
    P = "Страждання друїдів Дор'даніла все ще переслідують мої сни, $N. Ви повинні знищити їхніх лідерів!",
    C = "Я відчув, як страждання Дор'данілових Курганів зменшилися, і знав, що ти виконав своє завдання.$B$BIt ти виконав жахливу роботу, $N, бо духи, яких ти знищив, були лише жертвами зла Покинутих. Але з їх знищенням, будемо сподіватися, що інші божевільні духи знайдуть спокій.",
},

[1013] = {
    en = "The Book of Ur",
    T = "Книга Ура",
    D = "$N, у Твердині Тінекриву є книга, Книга Ура, яка була б дуже цінною у моїй колекції. Ур був великим магом Даларана до приходу Скари, його дослідження інших світів мають велику цінність для... певних осіб серед Покинуті.$B$BУвійди до Твердині Тінекриву і знайди цю книгу. Принеси її мені, і я доповім про твою службу нашій Темній Пані...",
    O = "Принеси Книгу Ура хранителю Бель’дуґуру в Аптекарстві Підмістя.",
    P = "Ти знайшов книгу, $N?",
    C = "Дуже добре. Ця книга чудово поповнить мої колекції творів Ура. Його знання були великі, але сумління утримувало його від справжньої влади. І тому, коли прийшов Бич і його сила була випробувана, це не вдалося.$B$BWe Покинутих не може дозволити собі такої слабкості, якщо ми хочемо вижити...",
},

[1014] = {
    en = "Arugal Must Die",
    T = "Аруґал мусить померти",
    D = "Аруґал усе ще мешкає в Твердині Тінекриву. Ми не можемо вважати Срібнохвойний ліс стратегічною твердинею Темної Пані, поки Аруґала не буде знищено.$B$BЯ подбаю, щоб його магія була викорінена, $N. Але я залишаю в твоїх руках завдання забезпечити, щоб Аруґал отримав заслужену смерть.$B$BВируш до Твердині Тінекриву і поклади край мерзенним заклинанням цього чаклуна раз і назавжди. Принеси мені голову цього підлого чарівника!",
    O = "Убий Аруґала і принеси його голову Далару Світанковому у Сепульхрі.",
    P = "Зі смертю Аругала ми можемо збільшити твердиню Темної Леді на Лордероні.",
    C = "Сріблястий Ліс нарешті звільнився від пороку того нещасного Аругала. Ви зробили Темній Леді велику послугу, $N. Ваша наполегливість буде винагороджена.",
},

[1015] = {
    en = "The New Frontier",
    T = "Новий кордон",
    D = "Увага, герої!$B$BКоло Кенарія шукає міцних осіб, які допоможуть їм досліджувати величезні нові кордони Калімдору! Заборонена пустка невимовних небезпек лежить далеко на захід від Танаріса та Ґаджетзана, і Коло потребує охочих і чесних помічників, які діятимуть від їхнього імені.$B$BУсі зацікавлені особи мають звернутися до Кола Кенарія. Поговори з верховним друїдом Фандралом Оленерогом у Кенарійському Анклаві Дарнаса для отримання додаткової інформації!",
    O = "Поговори з верховним друїдом Фандралом Оленерогом у Кенарійському Анклаві Дарнаса про заклик Кола Кенарія досліджувати кордони Калімдору.",
    P = "",
    C = "Чому ти думаєш, що я хочу, щоб мене дошкуляли такі, як ти, $C? Зачекайте, дозвольте мені припинити важливі обов’язки, якими я займаюся щодня, щоб я міг допомогти вам знайти куди-небудь. У будь-якому разі добробут Дарнаса — ні, всього Тельдрассила — має стояти на другому місці після придбання дрібнички для вашої колекції.$B$BThe дурні в Місячній поляні марнують мій час, кличучи про допомогу, і тепер я повинен терпіти це?",
},

[1016] = {
    en = "Elemental Bracers",
    T = "Браслети елементалів",
    D = "Візьми цей ворожильний сувій — він може визначити творця цих елементалів. Але тобі знадобиться щось від них, щоб використати як реагент для зосередження магії сувою — їхні браслети підійдуть якнайкраще.$B$BКілька цілих браслетів від цих істот має вистачити. Інші браслети будуть непридатними для наших цілей, але вони можуть мати цінність для торговця, якщо захочеш їх продати. Щойно матимеш цілі браслети, спробуй використати сувій. Повернися до мене з результатами, і ми продовжимо звідти.",
    O = "Збери 5 цілих браслетів елементалів і використай на них Ворожильний Сувій. Після цього принеси Ворожений Сувій вартівниці Велені Зіркоудар у Притулок Срібновітру.",
    P = "Оскільки ви повинні знищити наручі, щоб убити елементалів, ймовірно, буде важко знайти конкретні, які містять інформацію, необхідну сувою віщування. Ви можете обмінювати наручі з іншими, щоб отримати ті, які вам потрібні, чи, можливо, у вас уже є пророчений папір?",
    C = "Молодець, $N, це має дати нам інформацію, необхідну для виявлення винуватця. Як би ви ставилися до того, щоб усунути мага, який наповнює наші басейни зіпсованими елементалями? Зіпсованість Ясеневого долю та інших територій змушує мене крутитися сам по собі — від того, що чарівник активно намагається знищити його, мене без кінця нудить. Ми змусимо його заплатити.",
},

[1017] = {
    en = "Mage Summoner",
    T = "Маг-викликач",
    D = "У Степах є лише один маг-нежить, здатний осквернити стільки водяних елементалів. І він же єдиний, досить дурний, щоб це спробувати. Сарілюс Згубнород сидить, мабуть, на вершині Піку Жахливого Туману і сміється з мене.$B$B$N, ти мусиш вирушити на ворожу територію і знищити цього негідника. Мені набридла його дурість, і ми мусимо показати йому, що стається з тими, хто дратує вартівників.$B$BУбий його і принеси мені його голову. Але будь обережним, Орда може стежити за тобою.",
    O = "Убий Сарілюса Згубнорода і принеси його голову вартівниці Велені Зіркоудар у Притулок Срібновітру.",
    P = "Чи зроблено? Сарілус Фолборн мертвий?",
    C = "Тепер я бачу, як ця огидна усмішка назавжди стерлася з його обличчя. Ви зробили дуже добре, $N. Візьми це, Світло Елуни, випий його, коли все здається втраченим і смерть близько. Це може врятувати вас, Божа воля.",
},

[1018] = {
    en = "The New Frontier",
    T = "Новий кордон",
    D = "Увага, герої!$B$BКоло Кенарія шукає міцних осіб, які допоможуть їм досліджувати величезні нові кордони Калімдору! Заборонена пустка невимовних небезпек лежить далеко на захід від Танаріса та Ґаджетзана, і Коло потребує охочих і чесних помічників, які діятимуть від їхнього імені.$B$BУсі зацікавлені особи мають звернутися до Кола Кенарія. Поговори з верховним друїдом Гамуулом Рунетотемом на Піднесенні Старійшин у Громовому Бескиді для отримання додаткової інформації!",
    O = "Поговори з верховним друїдом Гамуулом Рунетотемом на Піднесенні Старійшин у Громовому Бескиді про заклик Кола Кенарія досліджувати кордони Калімдору.",
    P = "",
