[1023] = {
    en = "Raene's Cleansing",
    T = "Очищення Рейн",
    D = "Перебираючи речі Тероніса, ти знаходиш журнал у хорошому стані.$B$BТи береш журнал і залишаєш тіло Тероніса як є.$B$BЗалишилося лише знайти самоцвіт, який шукав Тероніс. Рейн згадувала, що він десь у цій місцевості. Можливо, його мають мурлоки...",
    O = "Знайди Сяючий Самоцвіт і повернися до Рейн Вовкобіг в Астранаар із журналом Тероніса.",
    P = "Ласкаво просимо назад, $N.",
    C = "Це жахливо, $N. Тероніс мертвий?!$B$BThe час трауру настане, але поки що ми повинні зосередити наші зусилля. Я надішлю кілька Вартових якнайшвидше знайти тіло Тероніса.$B$BYou маю щоденник Тероніса та дорогоцінний камінь, який він шукав. Як ви думаєте, ви здатні виконати його завдання? Я відпочив би набагато краще, знаючи, що його смерть не була марною.",
},

[1024] = {
    en = "Raene's Cleansing",
    T = "Очищення Рейн",
    D = "Тобі доведеться самому проводити дослідження, але з нотаток Тероніса здається, що наступним кроком буде пошук інших частин жезла, створеного Дартолом. Я б почала з місячного колодязя на схід від озера Ірис. Коли будеш готовий, іди дорогою і поверни на північ, коли побачиш невелику зону відпочинку ліворуч.$B$BТам є дріада на ім’я Шаель’дрін, яка краще підходить, щоб тебе направити. Знайди її.$B$BТримай самоцвіт при собі — він знадобиться Шаель’дрін, якщо вона допомагатиме тобі відтворити жезл.",
    O = "Знайди Шаель’дрін біля місячного колодязя на північному сході.",
    P = "Привіт. як справи",
    C = "О, Раєн прислала вас? Це справді має бути серйозно. Чим я можу вам допомогти?",
},

[1025] = {
    en = "An Aggressive Defense",
    T = "Агресивний захист",
    D = "Перш ніж вирушити до місячного колодязя, у мене є ще одне завдання, яке допоможе людям Ясенедолу, якщо ти хочеш перевірити свої вміння.$B$BНа дорозі, що веде на схід перед річкою Фалфаррен, фурболги атакують мандрівників. Їхні зболені розум живляться страхом, а їхній апетит втамовується кров’ю невинних.$B$BДопоможи вартівникам захистити ці землі, показавши цим чудовиськам ту ж милість, яку вони виявили нашому народу.$B$BЇхні табори, здається, на південь від дороги... будь обережним.",
    O = "Убий 1 вартового лігва, 2 урси, 10 тотеміків і 12 воїнів племені Бруднолісу, а потім повернися до Рейн Вовкобіг в Астранаар.",
    P = "Фурболги не завжди були нашим ворогом, $N. Але часи змінюються, і тут, у цих темних лісах, уже не час миру.",
    C = "Ви добре зробили, $N. дякую",
},

[1026] = {
    en = "Raene's Cleansing",
    T = "Очищення Рейн",
    D = "Мені шкода, що твої звістки не кращі.$B$BРейн права, я знаю про творіння Дартола і про треантів у цій місцевості — принаймні знала колись. Тепер вони зіпсовані, їхня природа перекручена.$B$BЯкщо твоя мета — знайти наступну частину жезла, тобі доведеться знайти ключ, щоб відкрити скриню, у якій вона лежить.$B$BДерев’яний ключ знаходиться в одного з треантів на північний схід звідси, біля Лісопагорба. Щойно матимеш його, шукай невелику галявину на захід від дороги біля кордону з Лісопагорбом... скриня має бути захована десь там.",
    O = "Знайди Дерев’яний Ключ і частину Жезла Дартола, перш ніж повернутися до Шаель’дрін біля місячного колодязя.",
    P = "Мене засмучує те, що третанти стали корумпованими. Я хотів би зробити більше, щоб допомогти їм.",
    C = "Я радий, що ти повернувся, $N.",
},

[1027] = {
