},

[1033] = {
    en = "Elune's Tear",
    T = "Сльоза Елуни",
    D = "Я сподівався, що ліки Оренділа врятують Релару, але боюся, що вони лише сповільнили хворобу, яка охопила мою дитину. Ми мусимо знайти сильніші ліки! На щастя, Оренділ розповів мені про подальші засоби, які можна спробувати, якщо перший не спрацює.$B$BСльоза Елуни — це тип каменю, який можна знайти лише в одному місці: на острові посеред озера Ірис, на схід від Астранаару. Оренділ сказав, що цей камінь змиває псування... будь ласка, $N, принеси мені Сльозу Елуни і молися, щоб вона поклала край хворобі моєї дитини!",
    O = "Принеси Сльозу Елуни Пелтурасу в Астранаар.",
    P = "$N, ти знайшов Iris Lake? У вас є Сльоза?",
    C = "О, ти знайшов! Я покладу сльозу в вариво і помолюся, щоб вона вилікувала її.$B$BThank ти! Дякую, $N!",
},

[1034] = {
    en = "The Ruins of Stardust",
    T = "Руїни Зоряного Пилу",
    D = "Сльоза Елуни частково змила хворобу моєї доньки. Її кошмари зменшилися, і я дякую богині за її благословення. Але... лихоманка все ще вирує в ній.$B$BОренділ розповів мені про морозний пил, який можна знайти серед Руїн Зоряного Пилу. Можливо, він послабить лихоманку Релари. Збери трохи цього пилу і, будь ласка, повернися до мене.$B$BРуїни Зоряного Пилу лежать на південь, $N. Нехай Елуна пришвидшить твою подорож.",
    O = "Принеси 5 жмень зоряного пилу Пелтурасу в Астранаар.",
    P = "У вас ще є Stardust, $N?",
    C = "Ви зібрали пил! Я зроблю з них припарку — вона має знизити температуру Релари.$B$BThank знову ти, $N. Без вашої допомоги моя дитина точно б загинула.",
},

[1035] = {
    en = "Fallen Sky Lake",
    T = "Озеро Падіння Неба",
    D = "Лихоманка Релари минула, але вона все ще дуже слабка. Я не вірю, що сам час поверне їй втрачені сили. Я вважаю, що для цього потрібна сила місячного каменя.$B$BРаніше ми збирали місячні камені біля озера Падіння Неба на південному сході... поки не з’явилися Тінолози.$B$BЇхній лідер, Оракул Тінолозів, зібрав усі впалі місячні камені і тримає їх при собі. Тепер тобі потрібно забрати місячний камінь у Оракула.$B$BІ, боюся, для цього тобі доведеться його вбити.",
    O = "Забери Впалий Місячний Камінь у Оракула Тінолозів і принеси його Пелтурасу в Астранаар.",
    P = "Ви стикалися з Оракулом із Тіньових заростей, $N? Якщо так, то, будь ласка, передайте мені впав місячний камінь. У Релари залишилося сил ще на кілька вдихів!",
    C = "Ой, $N, ти врятував мою дочку! Я знаю, що сила місячного каменя поверне моїй доньці її силу!$B$BI ніколи не зможе повністю відплатити вам за ту допомогу, яку ви мені надали, але... будь ласка, візьміть це. Крім Релари, це моя найдорожча річ.",
},

[1036] = {
    en = "Avast Ye, Scallywag",
    T = "Гей, пройдисвіт!",
    D = "$N... так, я чув про тебе. Я чув, що ти не друг Бухти Скарбів — як і ми, пірати Кривавих Вітрил. Флотський майстер Фіраллон шукає міцних і здорових $G чоловіків:жінок; таких, як ти, для особливої місії.$B$BЯкщо тобі цікаво, вирушай до «Кривавої Завіси» і поговори з ним на нижній палубі. Корабель стоїть на якорі біля Дикого Узбережжя на схід звідси, поруч із «Прибоєм» і «Удачею Діви».",
    O = "Поговори з флотським майстром Фіраллоном на борту «Кривавої Завіси» біля узбережжя Долини Тернової Долі.",
    P = "",
    C = "Аваст ye, scallywag. Я чую, що ти – тип, який любить трохи грати. Що ж, якщо ви не друг Буті-Бей, тоді ви можете мати особливе місце серед Bloodsail Buccaneers.$B$BArrrrr...",
},

[1037] = {
    en = "Velinde Starsong",
    T = "Велінда Зіркоспів",
    D = "Велінда Зіркоспів була моєю попередницею тут, у Ясенедолі. Спочатку здавалося, що вона тримала ситуацію в Лісопагорбі під контролем, але поступово її зусилля слабшали. Одного дня вона просто зникла.$B$BМене відправили сюди, щоб продовжити її роботу. На жаль, я нічого не знаю про жрицю. Можливо, Тін’тель Лезоткач, одна з командирів вартівників, знає деталі її зникнення, які мені невідомі.$B$BВона напевно зрозуміє важливість такої інформації.",
    O = "Поговори з Тін’тель Лезоткачем на Терасі Воїнів у Дарнасі.",
    P = "",
    C = "Зоряна пісня Велінде? Те, що жриця зникла деякий час тому, майже напевно загальновідомо. Щодо подальших подробиць подій, які супроводжували її від’їзд... для мене були б вагомі причини оприлюднити таку інформацію.",
},

[1038] = {
    en = "Velinde's Effects",
    T = "Речі Велінди",
    D = "Том Мел’Тандріс показав вам це? Гадаю, не буде великої шкоди, якщо я дозволю вам оглянути її речі. Цей ключ відкриє скриню, де ми зберігали її майно в казармах Сторожів. Вона вела щоденник своїх обов’язків, і якщо щось можна дізнатися, то саме з нього.$b$bМушу попередити: Сторожі вважають, що у неї були власні причини піти, і вони сподіваються, що вона може повернутися будь-коли. Жриця в минулому зробила чимало, щоб заслужити нашу довіру.",
    O = "Пошукайте щоденник Велінди в її скрині, а потім поверніть його разом із ключем до Тін’тель Блейдвівер у Дарнассусі.",
    P = "Що ти дізнався?",
    C = "Здається, зникнення Велінде викликає більше занепокоєння, ніж здавалося спочатку. Навіть досі я не можу повірити, що вона прийшла до поганого кінця. Можливо, нам буде корисно зв’язатися з нею.$B$B$N, оскільки ви виявили особистий інтерес до цього питання, я хотів би заручитися вашою допомогою.",
},

[1039] = {
    en = "The Barrens Port",
    T = "Порт у Степах",
    D = "Ратчет — єдиний порт у Степах. Найімовірніше, Велінда знайшла в Ратчеті торгове судно, яке відвезло її до Бухти Чорноводдя в Азероті. Ми мали обмежені контакти з гоблінами, які керують портом, але наглядач причалу має знати про прибуття та відбуття пасажирів кораблів.$b$bЙдіть дорогою на південний схід через Ясенеділ, і ви опинитеся в Степах. Будьте обережні, $n, воїни Орди патрулюють ці землі. У порту ви будете в безпеці.",
    O = "Поговоріть із наглядачем причалу Діззівіґом у Ратчеті.",
    P = "",
    C = "$R, а? Повинен визнати, ми не отримуємо багато вашого типу тут. Когось шукаєш, а? Просто дайте мені хвилинку, я впевнений, що це записано в одній із моїх бухгалтерських книг.$B$BLot людей проїжджає сюди, тож дайте мені хвилинку.",
},

[1040] = {
    en = "Passage to Booty Bay",
    T = "Подорож до Бухти Здобичі",
    D = "Ах, нарешті знайшов. Треба було сказати, що вона проходила тут так давно. Дивімося.$b$bВелінда. Замовила проїзд до Бухти Здобичі на «Чорному Оспреї». У мене немає записів про інше, тож, гадаю, корабель безпечно прибув до порту.$b$bБільше нічим не можу допомогти, але вона розпитувала про подорож сушею на тому боці світу, і я згадав Раззґота, водія караванів із Бухти Здобичі. Можливо, ця Велінда подорожувала з ним.$b$bРушай, у мене не цілий день для тебе.",
    O = "Сідайте на корабель до Бухти Здобичі та поговоріть із караванником Раззґотом.",
    P = "",
    C = "Так? Мені не здається, що ви належите до тих, хто має товари, які потребують доставки, тож або ви шукаєте роботу в моєму каравані, а роботи зараз немає, або ви, ймовірно, спілкуєтесь не з тим гобліном.$B$BSo який це?",
},

[1041] = {
    en = "The Caravan Road",
    T = "Караванний Шлях",
    D = "Виявляється, я помилявся щодо вас, а це трапляється не щодня.$b$bЯ справді пам’ятаю цю Велінду, про яку ви питаєте. Не кожен день нічна ельфійка-жриця хоче подорожувати з брудним старим — але чудовим для ваших перевезень! — караваном, як мій.$b$bМи розійшлися на шляху на північ, вона прямувала до Темнолісся. Клерк там веде всілякі записи. Може знати щось корисне.$b$bБудьте обережні в джунглях, це смертельно небезпечне місце навіть у найкращі часи.",
    O = "Поговоріть із клерком Далтрі в Темноліссі.",
    P = "",
    C = "Незважаючи на всі дивні події, що відбуваються за останні кілька років, я веду записи про незнайомців якомога точніше. Ніколи не знаєш, коли це може стати в нагоді... хоча це зазвичай неприємна справа, коли це трапляється. Не пропонувати нічого про цей Velinde, який ви шукаєте.",
},

[1042] = {
    en = "The Carevin Family",
    T = "Родина Керевіна",
    D = "Ні, у мене немає записів про те, що Велінда Зореспів зупинялася в Темноліссі... хоча, якщо дозволите сказати, я важко уявляю, щоб нічна ельфійка-жриця знімала кімнату в таверні, якщо ви розумієте, про що я?$b$bАле ці вовколюди, про яких ви згадали, — про них я чув. Нещодавно Келор прийшов у місто з низкою їхніх голів. Він працює з родиною Керевіна. Мисливці на демонів, нежить та інших чудовиськ. Поговоріть із Джонатаном, він голова родини.",
    O = "Поговоріть із Джонатаном Керевіним у Темноліссі.",
    P = "",
    C = "Це темні часи. Недобрі новини шепочуть з кожної хиткої гілки, а зло можна знайти під кожним каменем.$B$BAnd в такі часи невідомий незнайомець входить до мого дому і питає воргена... Я не проситиму пробачення за свої підозри, лише відповіді.$B$BAnd відповіді, я матиму.",
},

[1043] = {
    en = "The Scythe of Elune",
    T = "Коса Елуни",
    D = "Ваша історія звучить правдиво... Я не зовсім розумію ваші мотиви, але якщо ваша справа тут, у Темноліссі, полягає в тому, щоб очистити ліс від ворґенів у будь-якій кількості, то я можу обійтися без розуміння заради результатів.$b$bНа півдні є шахта, яку заполонили ворґени... Вони з’явилися нізвідки, але, за нашими даними, саме там їх уперше виявили.$b$bРобіть свою справу, але я б попросив, якщо ви знайдете щось важливе, поділитися зі мною. Ми приймемо будь-яку допомогу в нашій війні проти зла.",
    O = "Шукайте ознаки Косі Елуни, а потім поверніться до Джонатана Керевіна в Темноліссі.",
    P = "Ліс небезпечний для непідготовлених. Тримайте свою зброю під рукою, а свій розум ще ближче, інакше ваша наступна подорож до лісу з привидами може стати останньою.",
    C = "Ви розповідаєте цікаву історію, $N. Хоча вплив родини Каревінів недостатньо великий, щоб ми могли знайти корінь цих проблем і покінчити з ними раз і назавжди, ми зробимо все можливе, щоб стримати кількість воргенів у Сутінковому лісі.$B$BAlready Я доручив Калору зробити це його першочерговим завданням.",
},

[1044] = {
    en = "Answered Questions",
    T = "Відповіді на Питання",
    D = "Ми приборкаємо проблему з ворґенами, не хвилюйтеся про це. Це зло, яке ваша подруга принесла в наші ліси, буде локалізоване, і я не тримаю на неї зла за її дії. Дивні події відбуваються в ці часи, $n, і темрява не знає спочинку.$b$bЯ більше не затримуватиму вас. Підозрюю, що є інші, які мають почути про те, що ви знайшли в шахтах Темнолісся.",
    O = "Поверніться до Тін’тель Блейдвівер у Дарнассусі.",
    P = "",
    C = "Отже, це доля Велінде, чи не так? Верховна жриця буде розчарована, дізнавшись про це, вони були хорошими друзями до її зникнення. Тим не менш, Коса Елуни, безперечно, була дарована їй як дар від нашої богині, і мене бентежить, що вона випала з рук її слуг.$B$BAnother, однак, справа для іншого разу. Я дуже вдячний вам за те, чого ви досягли.",
},

[1045] = {
    en = "Raene's Cleansing",
    T = "Очищення Рейни",
    D = "Нічні ельфи старі, як сам час, але їхня гординя руйнує їхній власний світ. А тепер вона руйнує й наші життя. Але це вже не піддається контролю...$B$BЯ звинувачую ельфів у багатьох речах, але ми все ще відповідаємо за свої вчинки. Навіть поза скверною, ми здатні на велике зло.$B$BРан Кровозуб — одне з таких зол. Жадібний до влади, сповнений хіті... скверна лише посилила його. Моя ненависть до ельфів палає, але я не бажаю зла їхнім дітям, тож ми мусимо самі наводити лад.",
    O = "Убийте Рана Кровозуба та 4 Охоронців Кровозуба і поверніться до Кролґа біля озера Містраль.",
    P = "Ти вже вбив Рана, друже?$B$BEven Нічні ельфи насправді не заслуговують на його гнів. Його ненависть палає ще яскравіше, ніж моя власна, але його розум більше не належить йому. Він становить загрозу для всіх природних істот цього лісу.",
    C = "Ти добре впорався, мій друже.$B$BThe ліс все ще забруднений, але принаймні ми знаємо, що зробили невелику частину, щоб повернути йому колишню славу. Якщо ви захочете повернутися до мене знову, я буду насолоджуватися товариством собі подібних.$B$BBe добре. Можливо, наші племена знову зустрінуться в менш насильницькі часи.",
},

[1046] = {
    en = "Raene's Cleansing",
    T = "Очищення Рейни",
    D = "Повертайся до свого племені та дай їм знати про твою перемогу тут.$B$BПокажи їм свій трофей і насолоджуйся славою...",
