[1075] = {
    en = "A Scroll from Mauren",
    T = "Сувій від Морена",
    D = "Гаразд, тепер до частини мого плану з дистанційним підривом... о, я ще не пояснив цього, чи не так?$B$BЯкщо коротко, то ось що: з невеликою магією я можу зробити так, що вибухівка спрацює, коли вас не буде поруч. Я збираю пристрій, який дозволить вам натиснути лише одну кнопку, і NG-5 вибухне, коли ви будете готові.$B$BАле мені потрібне заклинання від друга в Штормовії — його звати Коллін Морен. Ви знайдете його в кварталі магів там. Він людина, тож його легко помітити.",
    O = "Знайдіть Колліна Морена в Штормовії.",
    P = "",
    C = "Тепер це заклинання, яке вам потрібно; той, який дозволить вам підірвати вибухівку на відстані... хммм.",
},

[1076] = {
    en = "Devils in Westfall",
    T = "Дияволи в Західному Краї",
    D = "Ах, здається, я зрозумів. Заклинання для передачі повідомлень... гадаю, це той ефект, який він шукає.$B$BМені доведеться створити сувій із накладеним на нього заклинанням. Для цього мені потрібен уламок від пилового вихору.$B$BПоки я збираю решту компонентів, чому б вам не вирушити до Західного Краю та не знайти одного з цих мерзенних створінь? Вони небезпечні, але я впевнений, це для вас дрібниця, якщо ви готові піддатися одному з експериментів Гаксіса.$B$BЯ буду тут, коли ви повернетеся.",
    O = "Принесіть Уламки Пилового Вихору до Колліна Морена в Штормовії.",
    P = "Привіт, $N. Ви знайшли потрібний мені компонент?",
    C = "Дайте мені кілька хвилин, і я підготую ваш сувій.",
},

[1077] = {
