},

[1092] = {
    en = "Gerenzo's Orders",
    T = "Накази Ґеренцо",
    D = "Гадаю, мені теж варто подумати про те, щоб вибратися звідси. Не мине багато часу, як чутки про те, що тут сталося, дійдуть до вищого керівництва, і я впевнений, що вони не будуть раді знову мене бачити.$B$BЯ прослизну і зустрінуся з Зізом. Сподіваюся, він зможе знайти мені нову роботу!$B$BЯ спробую трохи прибрати цей безлад, але тобі варто негайно віднести зразок руди до Зіза. Він сказав мені, що влаштував табір десь на західній стороні Скельного Ущелину. Удачі.",
    O = "Достав зразок невідомої руди до Зіза Фіззіка в Кам’яношпилевих горах.",
    P = "Чимось я можу вам допомогти?",
    C = "Аааа, я знав, що зробив правильно, сказавши Пізніку залишитися. Я впевнений, що інженерам у Undermine буде найбільше цікаво подивитися на це...$B$BOf звичайно, я захочу залишити маленьку частину для себе, але те, чого вони не знають, не зашкодить їм, так?",
},

[1093] = {
    en = "Super Reaper 6000",
    T = "Супер Жнець 6000",
    D = "Жахливо, що Компанія Вентур тут накоїла, правда? Про що вони думали? Гоблінська компанія найняла гнома!$B$BНа щастя, Спаттервалв знає генія, коли його бачить. Найняв мене одразу після того, як мене вигнали!$B$BКажуть, вони побудували величезну лісорубну машину, і Спат хоче, щоб я вкрав її плани. На жаль, Ґеренцо — клятий гном — хоче моєї смерті на місці... може, ти міг би вкрасти плани для мене? Ти повинен знайти їх у одного з їхніх операторів.",
    O = "Дістань креслення Супер Жнеця 6000 для Зіза Фіззіка в Кам’яношпилевих горах.",
    P = "Ви знайшли ці плани? Я дуже хочу справити враження на нового боса. Сподіваюсь, коли він переконається в моїй відданості — ну, наскільки він може бути переконаний... честі гобліна, розумієте? — він почуватиметься комфортно, користуючись моїм досить вражаючим генієм.",
    C = "Гей, це те, що я думаю? Чудово!$B$BNow, подивимося. Ох... як я маю розуміти ці речі... не можу зрозуміти, як думають гноми. Дозвольте сказати вам, я здивований, що вони змогли побудувати колесо, не кажучи вже про ті літаючі машини, які їм так подобаються.",
},

[1094] = {
    en = "Further Instructions",
    T = "Подальші інструкції",
    D = "Цей конверт містить усю інформацію, яку я зміг зібрати, коли мене виганяли... внутрішні документи Компанії Вентур, кілька посібників, технічні речі... О, і, звісно, креслення Супер Жнеця 6000.$B$BСпаттервалв оселився в Трісфалі в Степах. Не повинно бути проблем із його пошуком, він маленький зелений хлопець.",
    O = "Достав запечатаний конверт до Спаттервалва в Степах.",
    P = "Привіт! Чим я можу вам допомогти?",
    C = "Фізікс, а? Не можу сказати, що я йому довіряю, але ця інформація здається достатньою. Чого б я не віддав, щоб венчурна компанія зникла з мого волосся.$B$BThey все-таки придумали хороші машини... Я не можу заперечувати, що ми отримали користь від використання деяких вдосконалень, які вони винайшли.",
},

[1095] = {
    en = "Further Instructions",
    T = "Подальші інструкції",
    D = "Справа з цим гномом, якого найняла Компанія Вентур, викликала неабиякий переполох у Підземміні. Торгові принци не схвалюють зв’язків Разданка з цим Ґеренцо.$B$BРіддлвокс попросив мене розібратися з проблемою, і я впевнений, що йому наказали це зробити один або кілька торгових принців. Звісно, Директор мені цього не сказав. Скажімо так, у мене є передчуття.$B$BУ будь-якому разі, Ґеренцо мусить бути усунутий, і це буде відповідним випробуванням для Фіззіка, щоб він із ним розібрався.",
    O = "Принеси нові накази до Зіза Фіззіка в Кам’яношпилевих горах.",
    P = "",
    C = "Усунути Геренцо? Тепер є перспектива, проти якої я не заперечую.$B$BGnomes досить погано, але те, що я дізнався про Геренцо, лише погіршує ситуацію. Очевидно, він був одним із головних інженерів у Ґномерегані, де працював над їхнім секретним проектом — ми ніколи не змогли проникнути в Дун Морога настільки добре, щоб дізнатися конкретні деталі. Це був провал. Наші звіти кажуть, що б це не було, буквально вибухнуло їм в обличчя.",
},

[1096] = {
    en = "Gerenzo Wrenchwhistle",
    T = "Ґеренцо Вістлвренч",
    D = "Я зустрічав Ґеренцо одного разу, але, скажу тобі, він не з приємних на вигляд. Його плоть виглядає так, ніби гниє, і він пришив до свого тіла метал і шестерні, замінив деякі кінцівки механічними.$B$BНа північний схід звідси, високо над озером Скельної Каламуті, біля водяного колеса, Ґеренцо наглядає за всім об’єктом. Я ніяк не можу пробитися туди, не кажучи вже про те, щоб узятися за Ґеренцо... Але ти виглядаєш так, ніби можеш впоратися.$B$BЯкщо ти вб’єш його для мене, я зроблю так, щоб це вартувало твоїх зусиль!",
