[1164] = {
    en = "To Steal From Thieves",
    T = "Вкрасти у злодіїв",
    D = "Ця мерзотниця! Ця свиня! Кената все ще жива; її сім’я процвітає, поки я страждаю. Справді покинуті!$B$BМоя сім’я загинула, забрана чумою. Наш маєток також конфісковано; розграбовано і спалено під час війни. А після всього цього вона та її кляті діти мали нахабство вкрасти єдині цінні речі, що в мене залишилися.$B$BМені вже байдуже на ті речі, які вони вкрали. Тепер я хочу їхніх голів!$B$BУбий їх для мене! Вируш до ферми Дабірі в Араті, на північний схід від Точки Притулку.",
    O = "Принеси голови Кенати, Фардела і Марселя Дабірі Женаві Каллоу в Підмісті.",
    P = "Убийте їх усіх і принесіть мені їхні голови!",
    C = "Ти стоїш переді мною як образ помсти, і я схиляюся перед тобою на знак подяки.$B$BWith смерть корови, і знаючи, що їх насіння більше не поширюватиметься на поверхні Азероту, я можу спрямувати свою енергію на щось більш прибуткове. Сподіваюся, ви пограбували їхню садибу після того, як їх добили.",
},

[1166] = {
    en = "Overlord Mok'Morokk's Concern",
    T = "Клопіт Верховного Володаря Мок’Морокка",
    D = "Схилися перед Верховним Володарем Мок’Морокком!$B$BРексар зробив мене могутнім вождем клану Кам’яного Молота!$B$BЯ хороший вождь. Я захищаю клан.$B$BВеликі дракони прийшли і спалили наше старе житло. Я розумний огр. Знайшов новий дім для клану тут.$B$BПокинув старе житло так швидко, що забув дещо. Крихітний $R, іди забери мої речі. Вируш на південь і знайди мій смачний грог, мій нюхальний порошок і мою скриню. Я любитиму тебе, коли ти це зробиш. Шукай у Лігві Полум’я та Руїнах Кам’яного Молота... вони там, я впевнений!",
    O = "Верховний Володар Мок’Морокк у Селі Товстостін хоче, щоб ти забрав його грог, нюхальний порошок і скриню в Болоті Скорботи.",
    P = "Я спраглий грогу. Я теж сумую за нюхальним запахом. Де сейф? Ідіть за Оверлордом Мок'Морокком.$B$BGo знайдіть південь у старому домі. Я надто зайнятий веденням огрів, щоб отримати.",
    C = "Ти хороший $r. Я дуже сумую за речами. Ти мені зараз подобаєшся.",
},

[1167] = {
    en = "The Tower of Althalaxx",
    T = "Вежа Алталаху",
    D = "Перш ніж протистояти Атрикусу, було б розумно порадитися з Балтулом. Я не сумніваюся, що він пильно стежив за Вежею Алталаху, і, можливо, має інформацію про останні події.",
    O = "Поговори з Балтулом Тінеударом біля Вежі Алталаху.",
    P = "",
    C = "Ах, я радий знову тебе бачити, $N! Тут відбуваються найдивніші речі, я радий, що ти з’явився!$B$BIt було дуже дивно, $N. Усе здавалося нормальним — ну, таким нормальним, як тут усе — а потім раптом із верхньої кімнати вежі спалахнуло сліпуче світло. Потім почулися крики. Крики розколювали повітря, час від часу блискавки вдаряли в землю. що відбувається",
},

[1168] = {
    en = "Army of the Black Dragon",
    T = "Армія Чорного Дракона",
    D = "Мок’Морокк став Верховним Володарем за наказом Рексара. Йому важливіша влада, ніж доля огрів.$B$BЧорні дракони вбили багато огрів. Вбили дружину Тарга. Мок’Морокк наказав нам тікати. Примусив нас прийти сюди.$B$BОгри повинні битися. Огри не вміють тікати. Мок’Морокк дбає лише про Мок’Морокка.$B$BЯ називаю Руїни Кам’яного Молота домом. Мені подобається на півдні. Це місце — не дім.$B$BДопоможи огерам боротися з армією чорних драконів. Я хочу помсти. Я хочу додому.",
    O = "Тарг у Селі Товстостін хоче, щоб ти знищив 15 розвідників Вогнеманів, 10 попелехвостих Вогнеманів і 5 вартових Вогнеманів.",
    P = "Мок'Морокк скаже всім ограм залишатися й берегти це місце в безпеці. Я вважаю, що ограм потрібно вбити армію чорних драконів і повернутися додому.$B$BYou допомогти ограм повернутися додому. Допоможіть ограм помститися.",
    C = "Ви вбиваєте багатьох з армії чорного дракона. Ти хоробрий $r.$B$BMake Тарг щасливий.",
},

[1169] = {
    en = "Identifying the Brood",
    T = "Визначення виводку",
    D = "Поки той боягузливий дурень Мок’Морокк купається у владі, а Тарг бореться з демонами смутку та помсти і змагається за лідерство в клані, я, здається, єдиний, кого хвилює джерело агресії проти нашого старого дому.$B$BЧому такий здивований погляд, $N? Думаєш, я говоритиму, як неосвічений грубіян, лише тому, що я огр?$B$BТепер до справи: принеси мені серця і язики з дракончиків і виводків. Я простежу корінь цього зла...",
    O = "Драз’Зілб у Селі Товстостін хоче, щоб ти приніс йому 15 палаючих язиків і 15 палаючих сердець.",
    P = "За допомогою сердець і язиків обпалених нащадків армії чорного дракона я можу розшифрувати, який жалюгідний звір запровадив своє потомство в наш дім. Можливо, маючи більше знань про наших агресорів, ми зможемо спробувати знищити їх раз і назавжди та повернути Село Кам’яного Молота з руїн.$B$BOf Звичайно, переконати Мок’Морокка вивести його мляву, жирну масу з цієї смітної нори само по собі стане епічним квестом…",
    C = "Безсумнівно, це була небезпечна справа, зібрати всі ці серця та язики. Я заглиблюсь у глибини таємниць, щоб простежити походження чорної загрози, яка опустилася на наш колишній дім.",
},

[1170] = {
    en = "The Brood of Onyxia",
    T = "Виводок Оніксії",
    D = "Село Кам’яного Молота захопив виводок Оніксії. Але чому донька чорного драконячого лорда, Смертокрила, напала на наші землі?$B$BЦе дуже тривожно. Напевно, Оніксією керувала якась мета, окрім облоги невеликої групи огрів.$B$BНегайно повідом Мок’Морокка! Треба діяти.",
    O = "Поговори з Верховним Володарем Мок’Морокком у Селі Товстостін.",
    P = "",
    C = "Чому ти розповідаєш мені про драконів? Я не люблю драконів. Мені тут подобається. Тут немає драконів.",
},

[1171] = {
    en = "The Brood of Onyxia",
    T = "Виводок Оніксії",
    D = "Залиш мене в спокої. Іди скажи Драз’Зілбу, що ми залишаємося тут. Тут немає чорних драконів.",
    O = "Поговори з Драз’Зілбом у Селі Товстостін.",
    P = "",
    C = "Цей ледачий боягуз!$B$BMok'Morokk демонстрував силу, коли Рексар був нашим лідером. Але незабаром після відходу Рексара Мок'Морокк став жертвою спокус влади. Замість того, щоб вести, він вимагав. Він не служить своїм людям, а радше очікує, що ми будемо служити йому.$B$BSomething треба зробити.",
},

[1172] = {
    en = "The Brood of Onyxia",
    T = "Виводок Оніксії",
    D = "Виводок Оніксії розкиданий по Драконячих Трясовинах. Дуже важливо, щоб більше жодне драконеня не вилупилося.$B$BПоспіши до Драконячого Болота на півдні Болота Скорботи. Напевно, вона влаштувала там своє лігво. Знайди яйця цього злого дракона і знищ їх.$B$BМи ніколи не повернемо Село Кам’яного Молота, якщо навколишня територія залишатиметься розплідником.$B$BЩодо Мок’Морокка... у мене інші плани на цього дурня.",
    O = "Драз’Зілб у Селі Товстостін хоче, щоб ти знищив 5 яєць Оніксії.",
    P = "Ви повинні поспішати до Драконього Морка, $n. З яйцями Оніксії, пронизаними навколо Wyrmbog, ми зіткнемося з величезною кількістю, якщо нічого не вжити швидко.$B$BDestroy її яйця! Не дайте чумі чорного дракона поширитися по нашій батьківщині!",
    C = "Чудово! Мине деякий час, перш ніж Onyxia зможе виробляти більше яєць.$B$BOn від імені мого народу, я дякую вам, $n.$B$BI наразі просив вас багато. Можливо, ти зможеш надати клану Кам’яного Молота останню послугу.$B$BMok «Морокк не підходить, щоб керувати нами. Тарг був би чудовим лідером, але йому заважають його травми та вік. Виженіть Мок'Морокка з цього місця силою. Лише тоді ми зможемо призначити нового лідера, який поверне нас до нашого справжнього дому на півдні.",
},

