[1175] = {
    en = "A Bump in the Road",
    T = "Невелика перешкода",
    D = "Після великої аварії з гоблінським болідом «Червоний Гром» і василіском Кронкрайдер найняв мене доглядати за трасою. Я не знаю, чим харчуються тварини на рівнинах, щоб виростати такими великими, але ми мусимо обережно проріджувати їх, щоб вони не забрели на трасу під час перегонів.$B$BСкажу так: якщо хочеш трохи заробити, іди і прибери василісків із цієї зони.",
    O = "Убий 10 солонокам’яних василісків, 10 солонокам’яних кришталешкурів і 6 солонокам’яних споглядачів для майстра траси Жеріна на Мерехтливих Рівнинах.",
    P = "Це досить погано, коли потрібно розчищати уламки гонщиків, не вибираючи їх із спалених частин тварин.",
    C = "Сподіваюся, ти не вбив нікого з василісків на коліях! Тушки довго гниють на сонці, і краще б не виносити лопату, щоб прибрати.",
},

[1176] = {
    en = "Load Lightening",
    T = "Полегшення ваги",
    D = "Коли йдеться про перегони, важлива кожна дрібниця! Чи то невелике налаштування вихідної потужності, чи послаблення натяжних пружин, чи полегшення ваги каркаса — усе треба враховувати.$B$BМи використовуємо кістки грифів для багатьох дрібних структурних модифікацій наших болідів, адже вони мають ідеальний баланс міцності та ваги. І що найкраще — їх легко дістати, адже солончаки всіяні грифами.$B$BПринеси мені трохи, і я добре заплачу.",
    O = "Принеси 10 порожнистих кісток грифа Поззіку на Мерехтливі Рівнини.",
    P = "У вас є ті кістки для мене? Я якраз збирався почати працювати над полегшенням рульової установки, але я не хочу відкривати її без усіх необхідних мені частин.",
    C = "Чудово! Я можу змусити команду працювати над цим негайно. Дякую, $n!",
},

[1177] = {
