[1184] = {
    en = "Parts of the Swarm",
    T = "Частини рою",
    D = "Повернися до Белґрома в Орґріммар і скажи йому, що Моктар добре виконує його доручення тут, у Тисячі Голок. Також скажи, що мої дослідження просуваються, і я сподіваюся скоро дізнатися більше. Це має його дуже порадувати.",
    O = "Повернися до Белґрома Кам’яного Молота в Орґріммар.",
    P = "",
    C = "Я ціную ваші зусилля, $c. Воєначальникові буде приємно почути, наскільки ви наполегливо виконували свої обов’язки.$B$BOh, звичайно, я згадаю йому ваше ім’я. Він часто розмовляє зі мною і дуже цінує мою думку.$B$BGo зараз у мене багато справ. І якщо ви незабаром поговорите з Корраном і він матиме новини про цих створінь, тоді поверніться до мене — я вважаю, що вони є загрозою, яку потрібно сприймати серйозно.",
},

[1185] = {
    en = "Under the Chitin Was...",
    T = "Під хітином було...",
    D = "",
    O = "",
    P = "",
    C = "Гей, це знову ти! Ну, я маю на увазі вас - як у вас, тобто $N! Так, це ти!$B$BHey, дозволь мені почати спочатку!$B$BThat об’єкт, який ти знайшов у Сілітусі, насправді це була книга. Це був щоденник, написаний на дуже давньому діалекті того, що ми зараз називаємо дарнаською мовою. Це займе деякий час, але я збираюся пройти через це дуже ретельно. Я гадав, ти маєш знати, що те, що ти знайшов, було надзвичайно цінним для Кола.$B$BThe денна мати в захваті й усе!",
},

[1186] = {
    en = "The Eighteenth Pilot",
    T = "Вісімнадцятий пілот",
    D = "Я зайнятий інтеграцією цього нового регулятора палива в наші боліди, але якщо хочеш ще допомогти команді, поговори з Раззеріком. Він наш пілот — ну, якщо бути точним, вісімнадцятий пілот — і він любить додавати свої маленькі модифікації до болідів.$B$BВін трохи не в собі, тож постарайся не надто дивуватися.",
    O = "Поговори з Раззеріком на Мерехтливих Рівнинах.",
    P = "",
    C = "Ви той $R, який допомагав Позіку, чи не так? Колись я був схожий на вас, бігав по боксу, допомагаючи виконувати будь-яку роботу, яку дозволяли мені виконувати механіки.$B$BNow подивіться на мене! Надзвичайний пілот гоблінської гоночної команди!",
},

[1187] = {
    en = "Razzeric's Tweaking",
    T = "Модифікації Раззеріка",
    D = "Поззік — чудовий механік, я знаю, але він боїться просто навантажити вогневу міць і гнати на повну. Я — ні.$B$BПісля того, як Поззік закінчує з болідом, я беру трохи часу, щоб додати свої модифікації — знаєш, послабити кермо, зняти частину каркаса, додати більше пального!$B$BЯ замовив морський форіумовий підсилювач у Шріва в Ґізморіумі в Ґаджетзані, але, схоже, дирижабль, на якому його везли, розбився в Болоті Скорботи! Мені він потрібен, $N!",
    O = "Забери морський форіумовий підсилювач для Раззеріка на Мерехтливих Рівнинах.",
    P = "Як я маю показувати своє обличчя навколо траси без невеликого додаткового удару ногами, щоб змусити мене рухатися? Це пародія, я вам кажу.",
    C = "Тільки погляньте на цю красу! П'ятнадцять фунтів солідної сили сифорію! Як тільки я прив’яжу це до свого гонщика, я буду так швидко їздити по трасі, що двічі переможу гномів!",
},

[1188] = {
    en = "Safety First",
    T = "Безпека перш за все",
    D = "Але що це? Шрів залишив запобіжник увімкненим. Це обмежить кількість енергії, яку я зможу отримати від підсилювача. Я казав йому, що хочу його вимкнути! Так не годиться.$B$BТобі доведеться віднести це до Ґізморіуму в Ґаджетзані в пустелі Танаріс і попросити Шріва це виправити.",
    O = "Принеси морський форіумовий підсилювач Шріву в Ґаджетзан.",
    P = "Як я впевнений, ви знаєте, Gizmorium може задовольнити всі ваші потреби в майструванні! Чим я можу вам допомогти?",
    C = "Тільки Razzeric подивився б на це і сказав, що я якось поставив би на нього якийсь запобіжний замок. Цей прискорювач майже повністю складається з сеафорієвої вибухівки. Я вже модифікував його так, щоб більше його корисного навантаження було доставлено під час використання, але Razzeric ніколи не задоволений, якщо він не переходить до одинадцяти!",
},

[1189] = {
    en = "Safety First",
    T = "Безпека перш за все",
    D = "Ось, я зробив те, що хотів Раззерік. Просто скажи йому, щоб був обережним, коли це вмикатиме. Якщо він зробить найменшу помилку, він не поїде вперед, а стане просто обгорілою плямою на трасі.$B$BБуло б шкода, якби це сталося. Хтозна, чи буде наш дев’ятнадцятий пілот хоч трохи кращим?",
    O = "Поверни модифікований морський форіумовий підсилювач Раззеріку на Мерехтливі Рівнини.",
    P = "Ви можете повірити, що Позік висипав на гонщика відро піску? Як я можу досягти максимальної швидкості з відром піску під сидінням?",
    C = "Тепер це більше подобається! Мені б хотілося побачити вираз очей гномів, коли вони побачать, як я вставляю цю дитину.$B$BToo погано, я буду надто зайнятий встановленням нового рекорду дистанції!",
},

[1190] = {
    en = "Keeping Pace",
    T = "Тримати темп",
    D = "Брати Брасболтс винайшли новий будівельний матеріал, це єдине логічне пояснення. Їхні боліди працюють швидше, ніж раніше, але їхні конструкції та всі інші дані, які ми зібрали з їхніх заїздів, ідентичні.$B$BМи знаємо, що Різзл Брасболтс майже постійно зосереджений на кресленнях цього нового відкриття.$B$BЗамек може влаштувати відволікання, щоб ти міг викрасти ці креслення для Поззіка.",
    O = "Попроси Замека влаштувати відволікання, а потім викради креслення Різзла для Поззіка на Мерехтливих Рівнинах.",
    P = "",
    C = "Нашкрябаний поспішною, поспішною рукою сувій нотаток і малюнків для вдосконалення деякого сировини.",
},

