},

[1192] = {
    en = "Indurium Ore",
    T = "Індуріумова руда",
    D = "",
    O = "",
    P = "Я хотів би інтегрувати індуріум у різні частини наших гонщиків, але мені потрібна велика кількість необробленого індурію, щоб створити ці частини.$B$BYou можна знайти індурієву руду в розкопках Ульдаман у Безплодних землях, по той бік моря в Каз Модані.$B$BThe гноми отримують її власні запаси, тому важливо, щоб ми мали свою власну. крокувати з ними.",
    C = "Чудово! Я негайно запрошую команду працювати над деталями, які нам знадобляться для наступної гонки.",
},

[1193] = {
    en = "A Broken Trap",
    T = "Зламана пастка",
    D = "",
    O = "",
    P = "Перед вами велика розбита пастка. Судячи з усього, огри намагалися відремонтувати пастку, але марно. Поруч з пасткою лежить поспішно написана записка, і, як не дивно, у ній детально описано, що саме потрібно для її ремонту: торієвий віджет і трохи фросту. Якби пастку відремонтували, огр, який проходив поруч із нею, міг би потрапити в пастку, і його можна було б уникнути.$B$BClearly, здається випадковим, що дуже мало огрів вміють читати.$B$BClearly.",
    C = "Торієвий віджет легко ковзає на місце, утворюючи канал для стікання морозної олії. Щойно останні краплі олії зливаються в нього, пастка фіксується на місці.$B$BWoe бути будь-якому необережному людоеду, який випадково пройшов повз!",
},

[1194] = {
    en = "Rizzle's Schematics",
    T = "Схеми Різзла",
    D = "Схеми Різзла описують процес очищення індуріумової руди. З його записів зрозуміло, що індуріумову руду добувають у дворфійських розкопках Ульдамана в Безплідних Землях.$B$BБільшість інших нотаток стосуються жаростійких властивостей.$B$BЯк притискач для креслень лежить шматок, що виглядає як неочищена індуріумова руда.",
    O = "Принеси зразок індуріумової руди Поззіку на Мерехтливі Рівнини.",
    P = "",
    C = "Індуріум? Цікаво... Якщо він здатний протистояти нагріванню в тому ступені, про який ви говорите, це пояснює підвищення продуктивності, яке показали гноми останнім часом.$B$BThis зразок, який ви мені принесли, також буде неоціненним. Я зможу виконати деякі тести щодо цього, але мені знадобиться більше, щоб це було для нас справді корисним.",
},

[1195] = {
    en = "The Sacred Flame",
    T = "Священне Полум’я",
    D = "Кентаври Ґалак у Тисячі Голок охороняють артефакт із часів створення кентаврів.$B$BМи хочемо його забрати, але нам потрібен флакон води з одного з місячних колодязів нічних ельфів.$B$BЩоб зібрати воду, тобі спершу потрібно отримати один із флаконів, які носять дріади біля Відступу Райнвуду в самому серці Ясенедолу. Є місячний колодязь біля західного берега річки Фалфаррен, на південь від головної дороги, де ти можеш наповнити флакон.",
    O = "Поверни наповнений вигравіруваний флакон Занґену Кам’яному Копиту в Громовий Бескид.",
    P = "Коли ми отримаємо наповнений флакон, ми зможемо надіслати його моєму колезі, Рау, у Тисячу голок. Це він попросив пляшечку з водою, тож він краще знатиме, як ми можемо нею скористатися.",
    C = "Дуже добре. Це має задовольнити запит Рау. Чи могли б ви доставити йому це? Можливо, вам сподобається провести час у Нідлс.",
},

[1196] = {
    en = "The Sacred Flame",
    T = "Священне Полум’я",
    D = "Принеси наповнений флакон Рау Скелебігу на Пост Вільного Вітру в південно-східній частині Тисячі Голок. До Тисячі Голок можна дістатися через Великий Підйомник на південному краю Степів.$B$BЯ не здивуюся, якщо ти зможеш ще допомогти нам.",
    O = "Достав наповнений вигравіруваний флакон Рау Скелебігу на Пост Вільного Вітру.",
    P = "Я не думаю, що вас надіслав Zangen, так?",
    C = "Хм, так, ця пляшечка з водою чудово послужить нашим цілям. Через спільне походження дріад і кентаврів вода з місячних колодязів дозволить нам порушити захист вічного вогню, що оточує реліквію кентавра.",
},

[1197] = {
    en = "The Sacred Flame",
    T = "Священне Полум’я",
    D = "Використовуючи воду, яку ти приніс, ти зможеш тимчасово загасити полум’я, що утримує реліквію кентаврів. Однак це не спрацює назавжди, тож тобі доведеться поспішити.$B$BТи знайдеш Скелю Роздвоєного Копита, твердиню кентаврів, на півночі звідси. Полум’я зберігається в Укріпленні Роздвоєного Копита, добре охоронюваній частині скелі.$B$BБудь обережним, кентаври Ґалак мають велику чисельність тут і неохоче віддадуть щось таке дороге для них.",
    O = "Забери Роздвоєне Копито для Рау Скелебіга на Пост Вільного Вітру.",
    P = "Я дуже хочу взятися за Роздвоєне Копито. Ви вже взяли?",
    C = "Я відчуваю дивну енергію, що виходить від Копита... Я не сумніваюся, що ми відкриємо дивовижну нову інформацію про кентавра в результаті його дослідження.$B$BMy дякую, $N. Тепер я повинен почати розшифровувати таємниці, які ви мені принесли.",
},

[1198] = {
    en = "In Search of Thaelrid",
    T = "У пошуках Тельріда",
    D = "Багато чуток ходить про союз Молодильного Молота та наґ у Глибинах Чорнокриву на узбережжі Ясенедолу.$B$BМоя роль тут, у Світанковій Зорі, — збирати якомога більше інформації, щоб ми знали, коли і де потрібна допомога.$B$BМинуло вже кілька тижнів, як я відправив розвідника перевірити активність у Глибинах Чорнокриву. Срібний Вартівник Тельрід досі не повернувся з доповіддю.$B$BМої інші розвідники зайняті нагальними справами.$B$BЗнайди і допоможи Тельріду, $N.",
    O = "Знайди Срібного Вартівника Тельріда в Глибинах Чорнокриву.",
    P = "",
    C = "Dawnwatcher Shaedlass був радий надіслати вас. У цьому зіпсованому місці справді розгортається лиха змова.",
},

[1199] = {
    en = "Twilight Falls",
    T = "Сутінки падають",
    D = "Наділені стародавніми ритуалами хаотичних Старих Богів, члени Молодильного Молота прагнуть повернути своїх темних покровителів і поширювати смерть і жах по всьому світу.$B$BМи вважаємо, що Молодильний Молот об’єднався з наґами і збирається в Глибинах Чорнокриву на узбережжі Ясенедолу.$B$BЯкий би злий план не визрівав у глибинах старого храму, його потрібно зірвати.$B$BВеди війну проти Молота і принеси докази своїх дій. Твої зусилля будуть щедро винагороджені.",
    O = "Принеси 10 підвісок Молодильного Молота Срібному Вартівнику Манадосу в Дарнасі.",
    P = "Blackfathom Deeps колись був древнім храмом нічних ельфів. Колись тут містилася найпотужніша місячна криниця. Хто знає, яке зло вариться там зараз у руках Сутінкового Молота.$B$BHave ви досягли успіху в позбавленні їх присутності?",
    C = "Ви, безсумнівно, відважної та благородної крові, $N. Серебряний світанок хвалить вас за ваші зусилля проти зла.",
},

[1200] = {
    en = "Blackfathom Villainy",
    T = "Злодійство Чорнокриву",
    D = "Сили покинули мене. Твоя допомога потрібна!$B$BДавно це місце було великим храмом Елуни. Але нещастя призвело до руїни, коли псування Старого Бога просочилося з-під землі і осквернило священний Місячний Колодязь.$B$BАку’Май, слуга Старого Бога, піднявся з вод.$B$BКультисти Молодильного Молота об’єдналися з наґами, щоб захопити ці землі. Культисти, очолювані Келрісом, приносять невинних у жертву Аку’Маї заради сили.$B$BУбий Келріса і принеси його голову Селґорму в Дарнас, $N, благаю.",
    O = "Принеси голову Володаря Сутінок Келріса Світанковому Селґорму в Дарнасі.",
    P = "Час є дорогоцінним товаром, $C.$B$BMy роль тут, у Дарнасі, полягає в тому, щоб забезпечити процвітання Серебряного світанку та завадити злим силам, які зазіхають на Калімдор.$B$BState швидко займайтеся своєю справою або вирушайте.",
    C = "Келріс вислизав від нас протягом досить тривалого часу.$B$BIt Здається, коли зло виявляло свою присутність у цих краях, Келріс відігравав свою роль. Деякий час ми вважали його мертвим або зниклим безвісти.$B$BBut це цілком логічно. Поклавши край його правлінню, ви врятували життя багатьох невинних людей.$B$BBy світло! Принести когось в жертву слугі Старого Бога заради особистої вигоди — бездоганно!$B$BYou зробили велику справу, $N. Я вітаю вас від імені Срібної Зорі.",
},

[1201] = {
    en = "Theramore Spies",
    T = "Шпигуни Терамора",
    D = "Орда і Альянс мають хитке перемир’я. Окремі сутички та таємні дії проводяться однією стороною проти іншої, і наш обов’язок — забезпечити перевагу Орди!$B$BЗараз саме час це зробити.$B$BШпигуни Альянсу зайняли позиції на схід від Села Товстостін. Вони стежать за селом і доповідають про наші пересування до Терамора, чого ми не можемо допустити.$B$BПолюй на шпигунів і знищуй їх. Дай чіткий сигнал їхнім начальникам, що ми не терпітимемо їхньої присутності!",
    O = "Убий 9 шпигунів Терамора, а потім повернися до Назіра Кривавошпиля в Село Товстостін.",
    P = "Ви знайшли зловмисників, $N?",
    C = "Хороша робота.  Їхні агенти вправні, але недостатньо хороші, щоб уникнути пильного ока Орди!",
},

[1202] = {
    en = "The Theramore Docks",
    T = "Причали Терамора",
    D = "$N, двоє наших шпигунів були відправлені викрасти документи з корабля на причалах Терамора. Вони здобули папери, але їх виявили, і вони змушені були викинути документи в море.$B$BОдин шпигун пізніше втік, але не зміг повернути здобич. Він доповів мені про свою невдачу, і тепер я доручаю це завдання тобі.$B$BДокументи знаходяться в скрині, десь у водах під причалами Терамора. Знайди ці документи, $N, і принеси їх мені.",
    O = "Принеси документи капітана Назіру Кривавошпилю в Село Товстостін.",
    P = "Ви знайшли документи, $N?  Вони зберігають інформацію, життєво важливу для стабільності Альянсу, а отже, життєво важливу для безпеки Орди.",
    C = "Я вітаю вас, $N. Це була непроста місія. Але отримані вами документи дуже цінуються нашим начальством.",
},

[1203] = {
    en = "Jarl Needs a Blade",
    T = "Джарлу Потрібен Клинок",
    D = "Мені треба різати. Я не скажу тобі, що я збираюся різати, але... мені потрібен клинок. Певний клинок...$B$BДехто називає його мечем. Я називаю його гойдалкою.$B$BДопоможеш мені? Ті рибо-люди, знаєш, мурлоки чи як їх там... Є один, якого звуть Гостроколючка, носить великий меч, живе на півночі звідси біля пляжу. Це той меч, який мені потрібен!$B$BАле не спи на цьому. Те, що я ріжу, не зберігатиметься вічно...",
    O = "Принеси Меч Гостроколючки до «Болотного Ока» Джарла в Садибі Болотного Світла.",
    P = "У вас є моє лезо??",
    C = "Це гарне лезо. Має хороший розмах. Це гарне лезо. дякую Дякую, дякую, дякую!!! Тепер я хочу спробувати...$B$BLater. Я спробую пізніше. Але, як я вже казав... дякую.",
},

[1204] = {
    en = "Mudrock Soup and Bugs",
    T = "Суп із Бруднокаменів і комах",
    D = "Я працюю над стравою, яку називаю «Суп із Бруднокаменів і комах». Мені все ще потрібні основні інгредієнти, і... ну, я не думаю, що протримаюся довго, блукаючи Болотом Скорботи!$B$BТож, $N, чи можеш ти пополювати для мене? Спершу мені потрібні язики черепах Бруднокаменів. Бруднокаменів можна знайти вздовж узбережжя, переважно в затоці.$B$BАле я хочу не просто язики! Я чув, що язики деяких Бруднокаменів роздвоєні...$B$BКажуть, роздвоєні язики мають особливий смак, і я хочу цей смак у своїй страві...",
    O = "Принеси 8 роздвоєних язиків Бруднокаменів Морґану Стерну в Терамор.",
    P = "Ви отримали роздвоєні язики?",
    C = "Ці підійдуть! Дякую, $N!$B$BNow Я спробую різні способи приготування цих язиків, щоб знайти найкращий спосіб підкреслити їхній смак.$B$BEventually У мене буде страва, гідна того, щоб подати її в Блакитному Затворнику в Штормовії!",
},

[1205] = {
    en = "Deadmire",
    T = "Мертвоболото",
    D = "Мертвоболото — це стародавній кроколіск у Болоті Скорботи. І настав його час померти.$B$BСтарі кістки скриплять, коли він тягне своє величезне тіло через болото, і хоча він усе ще рухається з силою і швидкістю молодості, його старе тіло завдає болю великому духу всередині, духу, чиє полум’я не згасне.$B$BАле тепер він живе в постійному, божевільному болю. Ти мусиш покласти край життю цієї благородної істоти, $N. Ти мусиш привести Мертвоболото до спокою.",
    O = "Принеси зуб Мертвоболота Мелору в Громовий Бескид.",
    P = "У вас є зуб Deadmire, $N?  Ви припинили страждання істоти?",
    C = "Дуже добре, $N.$B$BI впевнений, що полювання було нелегким, але добре знати, що біль звіра нарешті закінчився.",
},

[1206] = {
    en = "Jarl Needs Eyes",
    T = "Ярлу потрібні очі",
    D = "Сік із очей — смачний сік для пиття. Шкода, що в більшості створінь лише два ока.$B$BАле павуки мають багато очей. Дуже багато. І сік із очей Темного Туману смачний. Гладкий і солоний! Нерозкриті очі павуків... Я вже відчуваю їхній смак.$B$BПавуки Темного Туману на заході, у Печері Темного Туману. Ти думаєш, павуків назвали на честь печери... чи навпаки?",
    O = "Принеси 40 нерозкритих очей Темного Туману «Болотному Оку» Ярлу в Садибі Болотного Світла.",
    P = "Де ті очі?",
    C = "У вас є очі! У вас є очі! Смачні, смачні очі павука!$B$BSome очі... коли ти дивишся на них, вони дивляться у відповідь. Їжте останні. Вони складають тобі компанію... на болоті.$B$BHello, маленькі павучі очі. Привіт! Ти на смак як курка. Липка, солона курка!$B$BMmmh.",
},

[1218] = {
    en = "Soothing Spices",
    T = "Заспокійливі спеції",
    D = "Я люблю готувати. Справжню болотну кухню. Смажені зелені жаб’ячі лапки і таке інше.$B$BА для готування мені потрібні спеції. Заспокійливі спеції. Тоді я зроблю рагу, зварю його і з’їм, і тобі теж дам.$B$BЛюбиш рагу?",
    O = "Принеси 3 заспокійливі спеції «Болотному Оку» Ярлу в Болото Скорботи.",
    P = "Спеції. Кожному з нас може знадобитися трохи спецій у нашому житті. Ви згодні?",
    C = "Ах, це спеція! Тепер ось болотна добра тушонка.",
},

[1219] = {
    en = "The Orc Report",
    T = "Звіт орка",
    D = "Порпаючись у пухкому ґрунті, ти знаходиш відрубану руку орка. У руці затиснута кістяна трубка. А в трубці — заплямований брудом пергамент.$B$BПергамент написаний оркською мовою... і виглядає важливим.",
    O = "Принеси звіт шпигуна лейтенанту Терамора.",
    P = "У вас є звіт?",
    C = "Хм... Я погано читаю по-оркськи, але це схоже на звіт... написаний шпигуном орків!",
},

[1220] = {
    en = "Captain Vimes",
    T = "Капітан Ваймс",
    D = "Капітан Ваймс мусить побачити звіт орка, який ти знайшов, $N. Він краще за всіх знає оркську мову. І він має знати, що поблизу Терамора є шпигуни Орди!$B$BКапітан у казармах, на північно-східній стороні острова Терамор.",
    O = "Принеси звіт шпигуна капітану Ґаррану Ваймсу.",
    P = "Маєш щось для мене?",
    C = "Звіт від шпигуна орків! Як ви це знайшли? Неважливо - давайте подивимося, що там написано...",
},

[1221] = {
    en = "Blueleaf Tubers",
    T = "Синьолисті бульби",
    D = "Синьолисті бульби — делікатес у всьому світі! Але вони рідкісні, дуже рідкісні. Єдине місце, де їх можна знайти, — це тут, у Степах, глибоко під землею, у Лабіринті Гострих Шипів.$B$BІ навіть там їх неможливо знайти, якщо не знати, де саме шукати! Тому я навчив цих ховрахів-нюхачів знаходити їх для мене. У них чудовий нюх, і вони можуть учуяти бульбу за п’ятдесят кроків.$B$BЦе буде нелегко, але якщо ти принесеш мені трохи бульб, я щедро заплачу.",
    O = "Візьми ящик із дірками.$BВізьми командний жезл нюхача.$BВізьми і прочитай посібник власника нюхача.$B$BУ Лабіринті Гострих Шипів використай ящик із дірками, щоб викликати ховраха-нюхача, і використай командний жезл на ховраху, щоб він шукав бульби.$B$BПринеси 6 синьолистих бульб, командний жезл нюхача і ящик із дірками Мебоку Міззіксу в Ратчет.",
    P = "У вас є бульби, $N?",
    C = "Чудово, ви їх отримали! Я можу продати це своїм контактам за комплект!$B$BThanks за доставку, $N! Ви чудовий партнер.",
},

[1222] = {
    en = "Stinky's Escape",
    T = "Втеча Смердюка",
    D = "Чудово, нарешті щось, що не хоче мене з’їсти!$B$BМені потрібна допомога з тваринами тут, і ти підходиш, $Gдруже:леді;.$B$BКухар Морґан Стерн досліджує новий рецепт, і він відправив мене сюди зібрати листя болотника. Мабуть, він думає, що вони смачні.$B$BТак чи інакше, шукаючи рослину болотника... я опинився в оточенні! Можеш допомогти мені вибратися звідси і прикрити мені спину, поки я шукаю болотник?",
    O = "Проведи «Смердюка» Іґнатца, а потім поговори з Морґаном Стерном у Тераморі.",
    P = "Ви бачили пана Ігнаца? Колись я відправив його в болото, а він не повернувся!",
    C = "Містер Ігнац щойно був тут із листям богні, і він сказав мені, що ви допомогли йому вирватися з справжньої біди.$B$BThank ви, $N. Я попрошу свого дядька пригостити вас наступного разу, коли ви відвідаєте Блакитного Затворника в Штормовії.",
},

[1238] = {
    en = "The Lost Report",
    T = "Загублений звіт",
    D = "Порпаючись у пухкому ґрунті, ти знаходиш відрубану руку орка. У руці затиснута кістяна трубка. А в трубці — заплямований брудом пергамент.$B$BПергамент — це звіт, складений орком, який тижнями шпигував за містом Терамор.$B$BПісля перегляду пергаменту стає зрозуміло, що його потрібно доставити до оркського майстра шпигунства в Селі Товстостін.",
    O = "Принеси звіт шпигуна Назіру Кривавошпилю в Село Товстостін.",
    P = "Маєш щось для мене?",
    C = "Гарна робота, $N. Наш агент, Марг Найтай, дислокувався біля Терамора. Йому доручили шпигувати за містом. $B$BThis — його остання доповідь, і, можливо, вона остання — судячи з ваших свідчень, я боюся, що Марґ зустрів свій кінець у болоті...",
},

[1239] = {
    en = "The Severed Head",
    T = "Відрубана голова",
    D = "Сильне копання відкриває голову чоловічого орка, грубо відрубану біля шиї. Його губи застигли в гримасі, а темні очі зухвало дивляться вперед.",
    O = "Принеси голову зухвалого орка Назіру Кривавошпилю в Село Товстостін.",
    P = "У вас є інша справа, щоб повідомити, $N?",
    C = "Це голова Марг Найтай! Як я й боявся, він мертвий.$B$BLook на рані на його шиї! Чи могла зброя зробити цей нерівний поріз, чи якийсь звір убив нашого агента? $B$BThis — це таємниця, яку ми повинні розгадати, $N. Ми повинні з'ясувати, чи смерть Марг сталася від рук Альянсу!",
},

[1240] = {
    en = "The Troll Witchdoctor",
    T = "Троль-знахар",
    D = "Ми мусимо дізнатися про обставини смерті Марґа! І єдиний спосіб це зробити, $N, — через відьомську магію тролів.$B$BВіднеси голову Марґа до Кін’вілея в Долину Тернової Долі, до базового табору Ґром’ґол.$B$BКін’вілей — наймогутніший знахар тролів Темного Списа. Якщо хтось і може поговорити з духом Марґа Нічоокого, то це він.",
    O = "Віднеси голову зухвалого орка Кін’вілею в базовий табір Ґром’ґол у Долині Тернової Долі.",
    P = "У вас злий дух, $gbrother:сестро;. Що привело вас до Кін'вілі?",
    C = "А, тепер бачу. Дух цього орка зв’язаний у нашому світі, кипить від люті через невиконане завдання.$B$BWell, давайте поговоримо з цим розлюченим орком...",
},

[1241] = {
    en = "The Missing Diplomat",
    T = "Зниклий дипломат",
    D = "Нещодавно до Терамора відправили дипломата для зустрічі з Джайною Праудмур. Цей дипломат так і не прибув.$B$BЯ вважаю, що в цій змові замішані Дефіаси, але я не впевнений, як саме. Зникнення дипломата поки що не привернуло уваги громадськості, але це не може тривати довго.$B$BАгенти короля вже обшукують місто в пошуках зачіпок, але я хочу залучити і своїх контактів.$B$BУ Долині Героїв є мій старий друг на ім’я Йорґен. Знайди його, дай йому цю записку і дотримуйся його вказівок.",
    O = "Знайди Йорґена в Штормовії.",
    P = "Хммм, тобі краще мати вагомі причини переривати чоловіка та його риболовлю. Я не ставлюся добре до рознощиків, не кажучи вже про жебраків.",
    C = "Хм... <Йорген дивиться на вас примруженими очима.>$B$BAll правильно. Я допоможу тобі, але не тому, що хочу, а тому, що зобов’язаний.$B$BAnd Давайте з’ясуємо одну річ: ти знаєш набагато більше, ніж мав би. Давайте збережемо цю маленьку таємницю і не будемо балакати по тавернах про все, що дізнаєтеся. Зрозуміло?",
},

[1242] = {
    en = "The Missing Diplomat",
    T = "Зниклий дипломат",
    D = "Віднеси цю записку Еллінґу Тріасу. Нічого йому не кажи. Просто будь ввічливим і зачекай, поки він відповість. І не хвилюйся, він відповість.$B$BЯ лише ще раз наголошу, $N: стався до цієї справи серйозно і тримай язик за зубами.$B$BТріаса можна знайти в його сирній крамниці, «Сир Тріаса», у Торговому районі. Удачі.",
    O = "Достав запечатану записку Йорґена Еллінґу Тріасу в Штормовій.",
    P = "Привіт, $N. Чи можу я щось для вас зробити? Можливо, ви захочете спробувати наш особливий чеддер Trias? Або блок дарнасського блю?",
    C = "Вибачте, лист для мене? Ну, я буду... нечасто ви отримуєте доставку, яка не є ящиком чи бочкою, коли все, що ви робите, це робота. Давайте подивимося, про що йдеться.$B$B<Еллінг дивиться на вас, відкриваючи листа.>$B$BYou виглядаєте трохи напруженим, добре, $N?",
},

[1243] = {
    en = "The Missing Diplomat",
    T = "Зниклий дипломат",
    D = "Йорґен, старий ти син... То ось як воно буде, га?$B$BГаразд, я впораюся з цим. Сподіваюся, він швидше опиниться в Крученому Просторі!$B$BОсь що буде, $N. Я почну використовувати свої контакти тут, але ти займатимешся більшою частиною роботи, щоб я заощадив трохи монет.$B$BВируш до Темнолісся в Сутінковому лісі і знайди Вартівника Бекуса — він зазвичай патрулює північну дорогу прямо біля міста. Просто скажи йому, що ти розслідуєш діяльність Дефіасів від мого імені, і він допоможе тобі будь-якою інформацією, яку зможе надати.",
    O = "Передай запечатану записку Вартівнику Бекусу в Сутінковому лісі.",
    P = "Не надто безпечно подорожувати лісом, $N. Будьте обережні, і якщо ви побачите щось підозріле або небезпечне, негайно зверніться до спостерігачів. Не намагайтеся нічого взяти на себе. Ми не несемо відповідальності за щось жахливе, що може з тобою трапитися.$B$BBut ми обоє знаємо, що ти все одно будеш ігнорувати мене й боротися з тим, що прийде з темряви, чи не так? Ха-ха, так, ви типи авантюристів... все одно.",
    C = "О, Тріас прислав тебе, га? Це трохи по-іншому.$B$BFeel вільний боротися з будь-якими чудовиськами, які приходять на вас із темряви. Я впевнений, що ви легко впораєтеся з цим, якщо ви з тих, хто спілкується з такими, як він.$B$BSo, що моєму другу потрібно від мене в такий похмурий день?",
},

[1244] = {
    en = "The Missing Diplomat",
    T = "Зниклий дипломат",
    D = "Діяльність Дефіасів? Ну, завжди є якась активність; навіть якщо вони тримаються осторонь, ми вважаємо їх загрозою.$B$BАле тепер, коли я думаю про це, нещодавно було помічено дещо дивне. Це було, мабуть, пару тижнів тому, але деякі їхні агенти зібралися біля садиби Еддла. Зі звіту я припустив, що там сталося щось серйозне.$B$BЧому б тобі не перевірити це місце спершу і не принести мені все, що знайдеш?$B$BСадиба знаходиться на південь від дороги з Західного Краю, щойно ти входиш до Сутінкового лісу.",
    O = "Знайди теку Дефіасів і поверни її Вартівнику Бекусу в Сутінковий ліс.",
    P = "Будь обережний, $N. Я знаю, що Тріас був тим, хто прислав вас сюди, але це не означає, що в лісі не ховається нічого, що не могло б завдати вам проблем... особливо коли ви розслідуєте Defias.",
    C = "Ти повернувся цілий і неушкоджений. Ви не можете просити більше, ніж це, чи не так?$B$BNow, давайте подивимося, що ми тут маємо. З огляду на будь-які документи Defias, які я бачив, це виглядає досить офіційно. Але це може бути обманом, щоб просто вибити вас із колії того, що ви шукаєте.",
},

[1245] = {
    en = "The Missing Diplomat",
    T = "Зниклий дипломат",
    D = "Ого, це виглядає занадто складно, щоб бути просто відволіканням. Мені навіть не варто дивитися на ці папери. Віднеси їх Тріасу — він зможе в них розібратися. І НЕ дозволяй нікому стати на твоєму шляху. Це більше, ніж я можу осилити. Може, навіть більше, ніж він, але побачимо.$B$BІ зроби мені послугу, $N, не кажи нікому, що я тобі допомагав. Якщо мої начальники дізнаються, що я знав про це і не поділився з ними, вони, мабуть, мене повісять.",
    O = "Принеси теку Дефіасів Еллінґу Тріасу в Штормовій.",
    P = "Я бачу, ти повернувся, і цілий. Ми обоє знаємо, що ти тут не заради сиру, тож давай припинимо приємності. Бекус чимось допоміг, чи ти вже поїхав до Сутінкового лісу?",
    C = "Так... це цікаве читання. Йорген і ДеЛейві були розумні, коли залучили мене до цього.$B$BSeems Defias дуже старалися, щоб завершити цей свій план. Хм... що це? Кулак? Це знайоме ім'я.",
},

[1246] = {
    en = "The Missing Diplomat",
    T = "Зниклий дипломат",
    D = "Так, тепер, коли я думаю про це... Дашел... Дашел щось там... Як його звали? КУЛАК! Дашел Кам’яний Кулак. У деяких колах його називають Кулаком — мабуть, тому, що він любить битися.$B$BЗазвичай його можна знайти в Старому Місті — прямо в самому центрі. Іди поговори з ним. Якщо треба, використай меч чи щось важке і тупе, щоб переконати його відкритися. І не вагайся. Якщо він замішаний так глибоко, як свідчать ці папери, він не дасть тобі інформацію добровільно.",
    O = "Поговори з Дашелом Кам’яним Кулаком у Штормовії.",
    P = "",
    C = "Що?!$B$BYou заходити в мій провулок і ставити запитання про мій особистий бізнес? Бізнес, до якого ви явно не маєте відношення.",
},

[1247] = {
    en = "The Missing Diplomat",
    T = "Зниклий дипломат",
    D = "Так, гм... я можу дещо знати про ту зустріч у садибі Еддла. Сталася, здається, кілька тижнів тому. Я справді не брав у цьому участі. Моя роль закінчилася, коли план А провалився... кляті шукачі пригод.$B$BХлопець, якого ми заслали для плану Б, прибув із Менетіла; його звали Слім. Це все, що я знаю про їхній запасний план.",
    O = "Поговори з Еллінґом Тріасом у Штормовії.",
    P = "",
    C = "Радий бачити, що ти ще живий, $N. Отже, з Дашелем все пройшло добре, так?$B$BI читав більше про цей їхній план, і хоча в ньому не вказано ім’я дипломата, якого вони переслідували, у ньому йдеться про план Б, який вони застосували після невдачі під час своєї першої спроби захопити його.$B$BThis Слім, про якого згадав Дашель, не має іншого імені, написаного тут, але якщо ви скажете, що він у Менетил, то це початок.",
},

[1248] = {
    en = "The Missing Diplomat",
    T = "Зниклий дипломат",
    D = "Мій контакт пішов на пенсію в Заболотті, у портовому місті Менетіл. Він має бути готовий допомогти лише на твоє слово, якщо ти скажеш, що працюєш на мене. Його звати Міхаїл. Він згадував, що стане барменом, коли кілька років тому залишав Штормовій.$B$BПоговори з ним, знайди цього Сліма і дізнайся, чи є ще щось про цього викраденого дипломата. Нам потрібно з’ясувати, куди його забрали, або принаймні, хто він. У теці нічого не сказано про їхні плани після викрадення.",
    O = "Поговори з Міхаїлом у Заболотті.",
    P = "",
    C = "Ласкаво просимо, ласкаво просимо, ласкаво просимо, $N. Добре, що ти приєднався до нас. Можливо, сьогодні ель? Або трохи баранини?$B$BName будь ласка, і я подбаю про те, щоб про тебе подбали. Мене звати Михайло, і я з нетерпінням чекаю на те, щоб служити вам.$B$BHmm? Що це? Тріас? Тише, друже. Про це не вся таверна послухає.",
},

[1249] = {
    en = "The Missing Diplomat",
    T = "Зниклий дипломат",
    D = "Ти кажеш, що Еллінґ тебе послав? Тоді моя гостинність зростає вдесятеро. Усе, що тобі потрібно, просто попроси. Я зроблю все можливе, щоб допомогти.$B$BГм, Слім, кажеш? Не впевнений, що ім’я здається знайомим, але я триматиму очі відкритими.$B$BНе дивися зараз, $N, але джентльмен біля виходу поглядає сюди. Він занадто уважно слухає нашу розмову, якщо ти розумієш, про що я? Якби я був тобою, я б зробив усе, щоб знешкодити його, перш ніж він втече через двері.",
    O = "Знешкодь Тапоке Яна, перш ніж він втече, а потім повернися до Міхаїла в Менетіл.",
    P = "Він вислизнув? Дивлячись на нас, він виглядав трохи сумно.",
    C = "Зловив його, га? Добре для вас. Я здивований, що це був Слім.$B$BI Скажу відверто, я ніколи не думав, що пропущу хвилювання деяких з більш хитрих підпільних заходів. Гадаю, старі звички важко вмирають. Не кажіть про це Еллінгу — він, мабуть, спробував би змусити мене повернутися до Штормовію, якби дізнався, що я пропустив подію.$B$BI Я радий, що міг принаймні трохи допомогти вам, поки ви були в Менетілі. Якщо вам ще щось потрібно, просто запитайте.",
},

[1250] = {
    en = "The Missing Diplomat",
    T = "Зниклий дипломат",
    D = "Дефіаси не платили мені достатньо, щоб померти за їхню справу. Вони викрали короля. Так, короля Штормовію, не якогось там дрібного дипломата. Він прямував до Терамора на зустріч із Джайною Праудмур — це, мабуть, було важливо і дуже секретно. Але не лише Дефіаси в цьому замішані. Вони працюють із кимось. Я думаю, вони знали, що це більше, ніж вони можуть осилити.$B$BМоя роль полягала лише в тому, щоб посадити їхнього агента на корабель короля, коли той стояв у гавані. Його звали Гендель. Це все, що я знаю. Присягаюся!",
    O = "Поговори з Міхаїлом у Заболотті.",
    P = "",
    C = "КОРОЛЬ?! Я маю на увазі... короля? Справжній король? Ви жартуєте? Ви не згадали, що шукаєте викрадачів короля. Я навіть не чув, що він зник безвісти — це пояснювало б, що його сина коронували.$B$BI негайно надішле повідомлення Еллінгу. Він захоче знати, що ви на сліді.$B$BI ніколи б не здогадався, що Ян продасть Штормовій за якусь паскудну монету. Навіть негідник повинен мати честь, коли справа доходить до деяких речей.$B$BThe Головне зараз — знайти цього Генделя. І я думаю, що можу допомогти в цьому.",
},

[1251] = {
    en = "The Black Shield",
    T = "Чорний щит",
    D = "Залізний щит, почорнілий від вогню, що вирував у корчмі, прикріплений до напівзруйнованої димової труби, однієї з небагатьох частин, що залишилися від будівлі, яка колись була корчмою «Тінистий Відпочинок».$B$BЩит можна зняти з цегли димоходу.",
    O = "Принеси почорнілий залізний щит Кроґу в Село Товстостін.",
    P = "Що у вас там, $n? Докази із залишків Shady Rest I$b$b?",
    C = "Я погоджуюсь, що люди мають дивні смаки до декорування, але чи використовували б вони звичайний залізний щит, щоб прикрасити свій камін? Можливо, цей щит поставили туди ті, хто підпалив корчму.$B$BA попередження? Загроза?",
},

