[1258] = {
    en = "... and Bugs",
    T = "...і комахи",
    D = "Ще один компонент мого нового рецепта — це панцирна нога гігантського краба. А краби, що є в Болоті Скорботи — їх називають Бруднопанцирними — просто не підходять! Боюся, єдині відповідні краби живуть далеко, у Болоті Скорботи.$B$BПанцир ноги краба — ключовий елемент презентації страви, тож мені потрібні ідеальні, без шрамів ноги. У дорослого краба може бути лише одна чи дві такі ноги, а мені потрібно багато, щоб дослідити мою страву.$B$BТож, $N... ти готовий до подорожі?",
    O = "Принеси 12 ідеальних ніг повзунів Морґану Стерну в Терамор.",
    P = "Мої дослідження з мовами Mudrock добре просуваються. Я вірю, що ваше полювання на крабів пройшло добре?",
    C = "Це чудові екземпляри, $N! Раковини в ідеальному стані, а м'ясо рожеве і ніжне. У ваших жилах тече кров кухаря, я в цьому впевнений!",
},

[1259] = {
    en = "Lieutenant Paval Reethe",
    T = "Лейтенант Павал Ріт",
    D = "Я не впізнаю імені лейтенанта Павала Ріта. Твій найкращий варіант — поговорити з ад’ютантом Тесораном. Він веде облік усіх записів гвардії Терамора, від особового складу до їхнього спорядження.$B$BВін зможе швидко перевірити, хто такий цей Ріт, за своїми книгами.",
    O = "Дізнайся більше про Ріта від ад’ютанта Тесорана в Тераморі.",
    P = "",
    C = "Привіт, $N. Вам потрібна інформація про конкретного члена гвардії Терамор? Ріте, це було?$B$BJust дай мені хвилину, щоб знайти потрібну книгу.",
