[1260] = {
    en = "Morgan Stern",
    T = "Морґан Стерн",
    D = "Я розробляю нове меню для ресторану. Воно буде наповнене сільськими стравами з тематикою «байю». Я думаю, моїм клієнтам у «Блакитному Відлюднику» вони сподобаються!$B$BЯ відправив свого племінника Морґана до Терамора, міста на краю Болота Скорботи. Він там збирає рецепти від місцевих, і я мушу знати, що він уже знайшов.$B$BПодорож до Терамора довга. Занадто довга для мене. Але я впевнений, що молодий $C, як ти, скочить із радості від можливості подорожувати, так?",
    O = "Поговори з Морґаном Стерном у Тераморі.",
    P = "",
    C = "О, мій дядько надіслав вас, чи не так?$B$BWell Я досліджував рецепти, і в мене є підказки, але мені потрібна допомога.$B$BHelp від когось, хто готовий замочити ноги.",
},

[1261] = {
    en = "Marg Speaks",
    T = "Марґ говорить",
    D = "Клятий Бруднопанцир! Ти не можеш убити Марґа! Ах, але я мертвий. Тож, мабуть, він мене убив...$B$BАле моя місія! Моя місія! Ти, $N, мусиш її завершити.$B$BПоблизу Терамора я помітив групу солдатів Альянсу, що таборували на пляжі. І один солдат носив підвіску... підвіску, прикрашену коштовностями, які жоден солдат не міг би собі дозволити!$B$BТієї ночі я прокрався до їхнього табору і вкрав підвіску, але на зворотному шляху до бази Бруднопанцирний краб-чоловік убив мене!$B$B$N, ти мусиш знайти того Бруднопанцира і повернути підвіску!",
    O = "Принеси коштовну підвіску Назіру в Село Товстостін.",
    P = "$N, ти дізнався про долю Марг?",
    C = "Цей кулон носив солдат Штормовію??$B$BThank ти, $N. Ви розкрили таємницю смерті Марг. Але цей кулон — нова таємниця, яку потрібно розгадати, яка може мати жахливі наслідки для Альянсу та Орди.",
},

[1262] = {
    en = "Report to Zor",
    T = "Звіт Зору",
    D = "Дивно, що підвіска, яку вкрав Марґ, була в руках звичайних солдатів. Можливо, її власник був замаскований, або, можливо, самі солдати її вкрали!$B$BНезалежно від того, що правда, це підвіска дворянина, і ми мусимо дізнатися, хто її справжній власник, якщо хочемо розгадати її таємницю.$B$BВіднеси підвіску до Зора Самотнього Древа в Орґріммар. Він добре обізнаний у політиці Альянсу і знатиме, чи має ця підвіска історію серед дворян Штормовію.",
    O = "Принеси коштовну підвіску Зору Самотньому Древу в Орґріммар.",
    P = "Ви подорожували з Brackenwall Village у Dustwallow? Як справляється Назір і як справляються його зусилля на болоті?",
    C = "Цей кулон виготовлено з великою майстерністю та точністю, $N. Жоден орк не бажав би такої коштовності...$B$BBut багато людей бажали б.$B$BI вивчити цей кулон. Будемо сподіватися, що з часом її таємниці нам відкриються.",
},

