[1301] = {
    en = "James Hyal",
    T = "Джеймс Хайал",
    D = "Перш ніж працювати тут, у Синьому Відлюднику, мене навчав один із найкращих кухарів і корчмарів, яких я коли-небудь зустрічав. Його звали Джеймс Хайал. Усе, що я маю, і все, чого досяг у житті, — завдяки йому.$b$bЦікаво, як він поживає. Його брат Вінсент і він пішли працювати в таверні в Гавані Менетіл, але я давно не чув від нього звісток.$b$bЯкщо ти коли-небудь опинишся в тих краях, чи не могли б ти передати йому привіт від мене?",
    O = "Поговоріть із Вінсентом Хайалом у Гавані Менетіл.",
    P = "",
    C = "Джеймс? О, він пішов досить давно.$B$BFelt друге дихання патріотизму, мабуть. Неважко зрозуміти, чому він це зробив. Незважаючи на все божевілля в Лордероні, багато людей приєдналися до Джайни Праудмур, коли вона йшла через море.",
},

[1302] = {
    en = "James Hyal",
    T = "Джеймс Хайал",
    D = "Мій брат Джеймс вирушив із леді Праудмур через море. Останнє, що я чув, бої там вщухли, і Джеймс відкривав таверну десь на континенті. Де б він не був, я впевнений, він добре справляється. Чудовий був кухар.$b$bЯ давно від нього не чув — мабуть, занадто зайнятий своєю таверною, гадаю, — але клерк у Тераморі, ймовірно, зможе тобі його вказати.",
    O = "Поговоріть із клерком Лендрі в Тераморі.",
    P = "",
    C = "Джеймс Хайал, Джеймс Хайал... Чому це ім’я звучить так знайомо?$B$BOf звичайно! Інцидент Shady Rest I$b$b. Якщо у вас є якась інформація про те, що там сталося, я прошу вас поговорити про це з капітаном Ваймсом. Він веде розслідування.",
},

[1318] = {
    en = "Unfinished Gordok Business",
    T = "Незавершена Справа Ґордоків",
    D = "Тепер ти король, тож, можливо, зможеш повернути цінний артефакт Ґордоків від моторошного ельфа, який називає себе принцом! Попередній король зазнав невдачі, як і всі інші королі після Тортелдріна — того моторошного ельфа, що вкрав його у давнього короля Ґордоків!$B$BАртефакт називається Рукавиця Мощі Ґордоків. Давні легенди кажуть, що лише справжній король Ґордоків може її повернути. Легенди також кажуть, що моторошний ельф досі десь тут — знайди його, і вона стане могутньою рукавицею, яку ти носитимеш вічно! Яр, я покажу тобі!",
    O = "Знайдіть Рукавицю Мощі Ґордоків і поверніть її капітану Кромкрашу в Зловісному Молотові.$B$BЗа словами Кромкраша, «давня легенда» каже, що Тортелдрін — «моторошний» ельф, який називав себе принцом, — вкрав її в одного з королів Ґордоків.",
    P = "",
    C = "",
},

[1319] = {
    en = "The Black Shield",
    T = "Чорний Щит",
    D = "Вибач, $n, я не можу багато допомогти, але можу направити тебе до того, хто зможе. Каз Двохшестерня, один із наших найкращих ковалів, працює в кузні.$b$bВіднеси щит до нього, і подивися, що він зможе тобі сказати.",
    O = "Покажіть Почорнілий Залізний Щит Казу Двохшестерні в Тераморі.",
    P = "Щось, на що я можу подивитися?",
    C = "Хм... цікава у вас залізяка. Безумовно, не зроблено жодним із ковалів, яких я знаю по цей бік моря, і це точно не моя робота.",
},

[1320] = {
    en = "The Black Shield",
    T = "Чорний Щит",
    D = "Ах, я ледь не пропустив це... Шкіряний ремінь на звороті, мабуть, згорів, але здається, що його виготовили для великої особи. Я б сказав, для таурена, якщо точніше.$b$bЦе все, що я можу сказати. Передай капітану Ваймсу, що мені шкода, що я не зміг більше допомогти.",
    O = "Поговоріть із капітаном Гарраном Ваймсом у Тераморі.",
    P = "",
    C = "Це небагато інформації, над якою можна працювати, але ми повинні мати це на увазі. Сподіваюся, деякі інші частини цієї таємниці стануть на свої місця та намалюють більш корисну картину того, що сталося.",
},

[1321] = {
    en = "The Black Shield",
    T = "Чорний Щит",
    D = "Хм... Я не бачу нічого незвичайного в цьому щиті. Треба попросити нашого коваля, До’ґола, глянути на нього, може, він скаже більше, але я б не надто сподівався...",
    O = "Покажіть Почорнілий Залізний Щит До’ґолу в Селищі Твердошкурів.",
    P = "Щось для мене, $c?",
    C = "Це хороший щит. Дуже міцний, важкий, хороший. Але До'голу це не потрібно. Я роблю щити, а не купую їх, $n.$B$BYou має це знати.",
},

[1322] = {
    en = "The Black Shield",
    T = "Чорний Щит",
    D = "Хм, ось тут на краю щита є напис, але його важко прочитати через увесь цей попіл.$b$bМені потрібна кислота, щоб очистити його. Отрута павуків Темнокликів із болота підійде. Принеси мені кілька їхніх мішечків, і я зможу це очистити.",
    O = "Принесіть 6 Кислотних Отруйних Мішечків для До’ґола в Селищі Твердошкурів.",
    P = "Ви дістали їм мішки від павуків?",
    C = "Мені не подобаються такі великі павуки, що я не можу сісти на них і хлюпати їх.$B$BThanks за те, що дістав їх, $n. Тепер я розриваю їх і виливаю на щит...",
},

[1323] = {
    en = "The Black Shield",
    T = "Чорний Щит",
    D = "Ой, здається, я капнув забагато кислоти на щит. Дозволь мені трохи протерти...$b$bХм, важко прочитати, але здається, це ім’я Мосарн. Ніколи про нього не чув. Може, Кроґ знає. Кроґ знає багатьох.",
    O = "Поговоріть із Кроґом у Селищі Твердошкурів.",
    P = "",
    C = "Мосарн? Звучить знайомо... Я не можу доторкнутися до цього. Можливо, це прийде до мене пізніше.$B$BIt, мабуть, не важливо. Щит може прийти звідки завгодно і нічого не означає...",
},

[1324] = {
    en = "The Missing Diplomat",
    T = "Зниклий Дипломат",
    D = "Що?! Ти прийшов сюди, звинувачуючи мене в союзі з Дефіасами, і думаєш, я просто стоятиму тут, поки ти мене ображаєш?! Щось мені підказує, що ти давно на це напрошувався.",
    O = "Переможіть рядового Гендела в Пиловій Трясовині.",
    P = "Знову привіт, $N. Сподіваюся, ви не проти допомоги, але ми не могли дозволити Генделу втекти або, що ще гірше, померти.",
    C = "Запевняю вас, ми всі дуже засмучені поточними подіями, але дозвольте нам відвезти його назад у Терамор для деякого допиту, і ми побачимо, як знайти короля.$B$BI Я впевнений, що моя леді Праудмор хотіла б подякувати вам за вашу допомогу. Поговоріть з нею, коли у вас буде хвилина.",
},

[1338] = {
    en = "Stormpike's Order",
    T = "Замовлення Штормспайка",
    D = "Є гномський зброяр, чию роботу я дуже ціную. Його звуть Фурен Довгобород, і його майстерність не має рівних. Мені потрібен новий щит, і я хочу, щоб це був його виріб!$B$BПроблема в тому... Фурен далеко на півдні, у гномському районі Штормовію. У людських землях! Не уявляю, чому він там живе, так далеко від Залізогарта. Люди, мабуть, платять йому королівський викуп, щоб утримувати його там!$B$BТож, якщо ти любиш подорожувати і не проти заробити трохи монет, чи не передаси Фурену моє замовлення на щит?",
    O = "Віднесіть Запит Штормспайка до Фурена Довгоборода в Штормовії.",
    P = "Лист із країв гномів? Цікаво, хто б телефонував так далеко на півночі...$B$BPlease, дайте мені подивитися порядок.",
    C = "Ах, прохання від одного з Грозових Пайків. Це гордий клан, повний якісних гномів. Багаті теж.$B$BThank ти, $N. До кінця дня я приступлю до роботи над щитом альпініста Грозового Пайка.",
},

[1339] = {
    en = "Mountaineer Stormpike's Task",
    T = "Завдання Штормспайка",
    D = "Я чув, що Гірський Сторож Штормспайк шукає бігуна. Когось, хто готовий трохи подорожувати за нього. Як щодо цього? Чи ти той $r, що впорається з роботою?$B$BЯкщо так, то знайдеш Штормспайка на вершині північної сторожової вежі.",
    O = "Поговоріть із Гірським Сторожем Штормспайком.",
    P = "",
    C = "Це вірно. У мене є завдання, яке я не можу виконати, поки сторожу. Фактично, це відведе вас далеко від озера Лох-Модан.$B$BYour ідеальний шанс для пригод!",
},

[1358] = {
    en = "Sample for Helbrim",
    T = "Зразок для Хелбріма",
    D = "Мій колега в Калімдорі, аптекар Хелбрім, досліджує вплив токсинів Лордерону на звірів Калімдору. Йому було б дуже цікаво отримати зразок вовчих сердець, які надіслав мені Ренферрел.$B$BХелбрім перебуває в Степах, у селищі під назвою Перехрестя. Щоб дістатися до нього, тобі потрібно полетіти на цепеліні до столиці орків, Оргріммара, а потім вирушити на південь пішки через Дуротар. Далі на захід у Степах, і ти скоро дійдеш до Перехрестя.",
    O = "Принесіть Зразок Вовчого Серця до аптекаря Хелбріма в Степах.",
    P = "У вас є пакет для мене?",
    C = "Ах, дуже добре. Якщо перші повідомлення правдиві, то токсичність цих сердець може призвести до подальшого прогресу в наших знаннях про отрути.$B$BThis — це вітання, $N. Ваша винагорода добре заслужена.",
},

[1359] = {
    en = "Zinge's Delivery",
    T = "Доставка Зінґе",
    D = "Вовчі серця, які ти приніс, мають унікальну властивість, якої немає в подібних зразках. У них є токсичність, яка мала б бути смертельною для самих вовків, у яких вони билися!$B$BЦе неймовірно, і ми мусимо дослідити це глибше. Я залишив кілька зразків сердець. Віднеси їх моєму колезі, аптекарю Зінґе. Ти знайдеш її в нашій штаб-квартирі в Підмісті.",
    O = "Принесіть Зразки Вовчих Сердець до аптекаря Зінґе в Підмісті.",
    P = "Маєш щось для мене?",
    C = "Ах так, зразки серця, про які говорив Ренферель. Мені дуже хочеться поекспериментувати з цим... Королівське аптекарське товариство завжди цікавиться відкриттям нових форм токсинів.",
},

[1360] = {
    en = "Reclaimed Treasures",
    T = "Повернення Скарбів",
    D = "Я мав чудову роботу копача на розкопках Ульдаману в Безплідних Землях... поки не з’явилися ці кляті троги. Я втік, ледь зберігши свою шкуру, і нічого більше. У хаосі я залишив свою найціннішу річ. Вона в безпеці від трогів у моїй скрині, але прямо серед них.$B$BЯ буду в боргу перед тобою, і честю, і монетами, якщо ти зможеш принести її мені! Скриня з моїм ім’ям стоїть у кінці Північної Зали. Саме її тобі потрібно дістати.",
    O = "Дістаньте цінну річ Крома Міцнорука з його скрині в Північній Залі Ульдаману і принесіть йому в Залізогарт.",
    P = "Ну, а тепер чи зможеш ти шльопати цих трогґів достатньо довго, щоб залізти мені в груди й схопити мій скарб?",
    C = "Ах, я знову відчуваю себе повноцінним — щиро вам дякую.$B$BSome гноми можуть цінувати блиск металу, а дехто може цінувати блиск дорогоцінних каменів... але Стаутарм без дорогоцінної кулі в руці — це навряд чи Стаутарм!",
},

[1361] = {
    en = "Regthar Deathgate",
    T = "Реґтар Смертобрам",
    D = "Воїн Орди, Реґтар Смертобрам, набирає агентів для місії в землі Пустки. Поговоріть із ним, якщо хочете добровільно взяти участь. Він розташувався в Степах, у серії бункерів на захід від Перехрестя.$B$BІ нагостріть свою зброю. Пустка — це місце, роздерте війною.",
    O = "Поговоріть із Реґтаром Смертобрамом.",
    P = "Зауважу, що ваше завдання не виконане, $N. Мені повідомити Шарліндру про твою недолугість?",
    C = "Так, я набираю. Ця місія веде до Пустощі, проти кентавра, який там знаходиться. Я буду коротким, щоб ви могли швидко почати.",
},

[1362] = {
    en = "The Kolkar of Desolace",
    T = "Колкар Пустки",
    D = "Кентаври Колкар живуть у Пустці, і їхні сили поширилися в Степах. Це відомий факт, і у нас є агенти Орди, які з ними борються тут.$B$BАле доки кентаври сильні в Пустці, вони завжди будуть загрозою. Час позбутися цієї загрози.$B$BПоговоріть із Фелґуром Двохклинком у Посту Примарного Воїна в Пустці. Його відправили зібрати інформацію про кентаврів. Він знатиме, як найкраще впоратися з Колкаром Пустки.",
    O = "Поговоріть із Фелґуром Двохклинком у Посту Примарного Воїна в Пустці.",
    P = "",
    C = "Ви тут за наказом Регтара? Тоді ви тут, щоб розібратися з кентавром. Добре.$B$BI сподіваюся, ви відпочили. Я не знаю, чим закінчиться наша кампанія проти кентавра, але я знаю, що боротьба буде довгою.$B$BHave сідай і слухай.",
},

[1363] = {
    en = "Mazen's Behest",
    T = "Завдання Мазена",
    D = "Як доглядач бібліотеки Академії Таємних Мистецтв і Наук, я відповідаю за те, щоб усі магічні фоліанти та сувої завжди були на місці. Хтозна, які біди можуть статися, якщо ці зачаровані тексти потраплять до чужих рук?$b$bЦе нагадало мені... мій помічник, Делліс, минулого тижня припустився жахливої помилки. Він вправний у бібліотеці, але некомпетентний, коли виходить за ворота Штормовію. Стань героєм і допоможи старому Деллісу, гаразд?",
    O = "Поговоріть із послушником Деллісом у Штормовії.",
    P = "",
    C = "Це не моя вина. Насправді це не було.",
},

[1364] = {
    en = "Mazen's Behest",
    T = "Завдання Мазена",
    D = "Інструкції майстра Мазена були чіткими: доставити дуже важливе есе до стража Махара Ба в Твердиню Пекловартів.$b$bАле я ніколи раніше не був у Випалених Землях! Подорож була страшною!$b$bКоли я дістався до Болота Скорботи, я звернув не туди і опинився оточений жахливими болотними створіннями, схожими на рослини. Вони кинулися на мене, тож я втік. Але в поспіху впустив есе. Я впевнений, що одна з тих істот його забрала.$b$bЧи не могли б ви спробувати повернути його і доставити Махару Ба?",
    O = "Дістаньте «Есе Хадґара про Конвергенцію Вимірів» і доставте їх стражу Махару Ба в Твердиню Пекловартів.",
    P = "Що привело вас до фортеці Nethergarde, $R?",
    C = "О, чудово!$B$BFor деякий час я побоювався, що мій запит на Есе Кадгара про конвергенцію вимірів проігнорував Майстер Мазен з Академії таємничих мистецтв і наук.$B$BHe, мабуть, загрузло запитами, враховуючи багато дивних подій, що відбуваються.$B$BNow, якщо вибачте, мені потрібно негайно почати дослідження. Нарешті поглянути на проникливість такого великого, як Кадгар, мене безмежно хвилює.",
},

[1365] = {
    en = "Khan Dez'hepah",
    T = "Хан Дез’хепах",
    D = "Колкар — не єдині кентаври в Пустці. Багато кланів блукають цими сухими рівнинами, воюючи і гинучи один проти одного. І це добре, що вони воюють між собою, адже вони сильні та жорстокі. Якби кентаври об’єдналися проти нас, вони б стали грізним ворогом.$B$BМи мусимо розібратися з ними, перш ніж вони об’єднаються.$B$BТвоє перше завдання — зірвати плани клану Колкар. Зроби це, убивши їхнього лідера, хана Дез’хепаха.$B$BСелище Колкар на північному сході звідси. Іди, і нехай удача буде з тобою.",
    O = "Принесіть голову хана Дез’хепаха до Фелґура Двохклинка в Пустці.",
    P = "$N, ти переміг хана Дез'гепу?",
    C = "молодці Ця стрімка дія проти Колкар є ефективною демонстрацією сили, а силу — це те, що кентавр розуміє найкраще.$B$BThe Смерть лідера Колкар не лише порушить цей клан, але й заспокоїть інших.",
},

[1366] = {
    en = "Centaur Bounty",
    T = "Нагорода за Кентаврів",
    D = "Тепер, коли ти налякав клани кентаврів, час їх знекровити. Під час мандрів Пусткою полюй на кентаврів. Мені байдуже, який клан ти обереш. Просто збирай вуха. Цілу купу вух.$B$BПослабивши їхню чисельність, ти послабиш їхню рішучість і придушиш будь-які думки про розширення.$B$BЩасливого полювання, $N.",
    O = "Принесіть 15 Вух Кентаврів до Фелґура Двохклинка в Пустці.",
    P = "Як твоя колекція вух, $N? великий?",
    C = "Тепер кентавр повинен знати твоє ім'я. Я впевнений, що вони це знають, поважають і бояться. І так само, як вони знають вас, вони знають прапор, під яким ви їдете.$B$BThe прапор Орди.",
},

[1367] = {
    en = "Magram Alliance",
    T = "Союз із Маґрам",
    D = "Щоб перемогти кентаврів, ми мусимо використати їхню ненависть проти них самих. Ми укладемо союз із одним із кланів і через них дізнаємося, як перемогти всі клани.$B$BЯкщо ти обереш союз із Маґрам, то вбивай їхніх ворогів, Ґелкіс. Це здобуде тобі повагу серед Маґрам. Коли ти здобудеш достатньо поваги, поговори з представником Маґрам, Варуґом, на околиці Селища Маґрам, у південно-східній частині Пустки.",
    O = "Здобудьте Дружню репутацію з Маґрам, а потім поговоріть із Варуґом.",
    P = "Залиште! Маграм не розмовляє зі слабкими. Ми вбиваємо їх!$B$BIf хочеш поговорити зі мною, то покажи мені, що ти сильний. Поверніться після того, як уб'єте багатьох Гелкі.",
    C = "Гелкі плачуть, коли чують твоє ім’я, $N. Вони бояться вас і ненавидять вас. Вони ненавидять вас, як ненавидять Маграма!$B$BMaybe Ви сильні, як Маграм. ми побачимо...",
},

[1368] = {
    en = "Gelkis Alliance",
    T = "Союз із Ґелкіс",
    D = "Щоб перемогти кентаврів, ми мусимо використати їхню ненависть проти них самих. Ми укладемо союз із одним із кланів і через них дізнаємося, як перемогти всі клани.$B$BЯкщо ти обереш союз із Ґелкіс, то вбивай їхніх найзліших ворогів, Маґрам. Після того, як ти здобудеш повагу Ґелкіс, поговори з шаманом Ґелкіс, Утек Мудрою, на околиці Селища Ґелкіс, у південно-західній частині Пустки.",
    O = "Здобудьте Дружню репутацію з Ґелкіс, а потім поговоріть із Утек Мудрою.",
    P = "Ваші дві ноги ступають на землю Гелкіса. Вам тут не раді!$B$BProve ви шукаєте дружби з Гелкі. Убити кентавра Маграма. Поверніться, коли земля буде вологою від крові Маграма.",
    C = "Земля говорить зі мною. І там сказано, що ви вбили багатьох Маграмів. Це добре.$B$BIf ти друг Гелкісів, тоді слухай. У мене для вас є ще завдання.",
},

[1369] = {
    en = "Broken Tears",
    T = "Розбиті Сльози",
    D = "Ґелкіс думають, що наша мати-кентавриця, Терадрас, нас захищає. Вони дурні. Ніхто не захищає кентаврів. Маґрам не потребують захисту! Ми найсильніші!$B$BПокажи Ґелкіс, які вони дурні. Іди до печери в їхньому селищі. Вони накопичують там кристали, сльози Терадрас. Знищ ці сльози і принеси мені уламки!",
    O = "Підтримуйте свою репутацію з Маґрам і принесіть 3 Розбиті Сльози до Варуґа в Селищі Маґрам.",
    P = "Якщо ти нам не ворог, то зробиш те, що я прошу!",
    C = "У тебе сльози! Тепер Гелкі знатимуть, що Терадрас їм не допоможе. Вона не буде плакати, коли ми їх роздавимо! Маграм правитиме!$B$BYou розумні, щоб допомогти нам, $N. Ми найсильніші.",
},

[1370] = {
    en = "Stealing Supplies",
    T = "Крадіжка Запасів",
    D = "Коли ми не воюємо, ми полюємо за м’ясом. М’ясо дає нам силу, а ситі воїни б’ються краще, ніж голодні.$B$BТе саме з Маґрам. Вони зберігають запаси м’яса, щоб могли воювати довше між полюваннями. Якщо ти нападеш на їхнє селище на сході і забереш їхні запаси м’яса, їхня сила згасне.",
    O = "Принесіть 6 мішків Грубосушеного М’яса до Утек Мудрої в Селищі Ґелкіс.",
    P = "Поверніться після того, як ви ще раз доведете свою цінність Гелкісам!",
    C = "добре. Я чую, як голосно бурчать животи Маграмів з їхнього села, далеко!$B$BI віддасть це м’ясо Гелкісам. І ми будемо боротися багато днів без відпочинку.$B$BWhat ти зробив це добре для Гелкі, $N.",
},

[1371] = {
    en = "Gizmo for Warug",
    T = "Ґаджет для Варуґа",
    D = "Давно маленький гном прийшов у Пустку. У нього були коні й віз, а у возі — дивні речі. Смішні речі. Речі, що горіли різними кольорами. Речі, що рухалися, але не були живими. Я вбив того маленького гнома, але перед тим... він змусив мене сміятися.$B$BЯ зберіг свою улюблену річ із його воза. Це був чоловік із дерева, і він махав мені, поки я не вдарив його і не зламав.$B$BЯ хочу новий. Принеси мені новий!",
    O = "Підтримуйте свою репутацію з Маґрам і принесіть Покращений Тренувальний Манекен до Варуґа в Селищі Маґрам у Пустці.",
    P = "Якщо ти нам не ворог, то зробиш те, що я прошу!",
    C = "Так, це те, що я мав! Я зроблю так, щоб він рухався знову. Це змушує мене сміятися!",
},

[1372] = {
    en = "Nothing But The Truth",
    T = "Ніщо, Крім Правди",
    D = "Наша експедиційна група була відправлена за наказом Варіматраса для розвідки нижнього Азероту.$b$bПід час розвідки я помітив людського шпигуна, який стежив за Притулком Жебраків. Перш ніж я встиг його схопити, деякі наші орчі... побратими... захопили його і відвели до Стонарда, їхньої твердині в Болоті Скорботи.$b$bЯ хочу... допомогти... нашим орчим союзникам. Вони не бачили нашого табору тут, але я все одно хочу підставити плече.$b$bПрацюй із Фаустіном тут, щоб створити... сироватку правди для нашого друга в Стонарді.",
    O = "Поговоріть із аптекарем Фаустіном у Притулку Жебраків.",
    P = "",
    C = "Зредус якраз розповідав мені про цікавого маленького Інфільтратора до вашого прибуття.$B$BQuite справді проблема. Останнє, що нам потрібно, — це метушливий чоловік, який обнюхує Beggar's Haunt.$B$BI Я впевнений, що оркам Стонарда дуже хочеться почути, що скаже наш друг. Бачачи, що вони наші союзники, гм, ми повинні допомогти їм отримати будь-яку інформацію від людини.$B$BWork зі мною, $N, і ми доставимо сироватку правди до Стонарда.$B$BFor Орда!$B$B... я правильно зрозумів?",
},

[1373] = {
    en = "Ongeku",
    T = "Онґеку",
    D = "Ти ще маєш себе довести, і твоє наступне завдання забере тебе далеко, тож поки що Ґелкіс воюватимуть із Маґрам без тебе.$B$BЗемля шепоче багато таємниць тим, хто слухає. Одна з таємниць, яку я чую, — про червоний кристал. Його називають дренетистом, і він новий для нашої землі. Він походить із місця, де літають гори і де правлять демони.$B$BПринеси мені уламок дренетисту, і це зробить мою магію сильною! Уламок знаходиться в місці під назвою Болото Скорботи, його тримає загублений Онґеку.",
    O = "Підтримуйте свою репутацію з Ґелкіс і принесіть Уламок Дренетисту до Утек Мудрої в Селищі Ґелкіс у Пустці.",
    P = "Покажи мені, що ти друг Гелкі, $N.",
    C = "Так, це той черепок, про який шепотіла земля. Я відчуваю в ньому сильну магію! Я використаю цю магію проти ворогів Гелкі.$B$BYou виконали для нас ще одне завдання, $N. Можливо, скоро ми назвемо тебе другом.",
},

[1374] = {
    en = "Khan Jehn",
    T = "Хан Джен",
    D = "Земля говорить зі мною, і вона каже, що Маґрам слабшають. Тепер час убити їхнього хана!$B$BПринеси мені голову хана Маґрам, Джена!",
    O = "Принесіть голову хана Джена до Утек Мудрої в Селищі Ґелкіс у Пустці.",
    P = "Покажи мені, що ти друг Гелкі, $N.",
    C = "Хан Єн був сильний, але дурний. Він вважав свою власну силу великою. Він не бачив, що земна магія сильніша. Тепер кентавр Маграма впаде без свого лідера, і Гелкі одного дня правитимуть!",
},

[1375] = {
    en = "Khan Shaka",
    T = "Хан Шака",
    D = "Ти допоміг Маґрам, і ти мені подобаєшся. Тепер убий хана Ґелкіс! Його звуть хан Шака, і я хочу його голову! Хочу дивитися на неї і сміятися з нього!",
    O = "Підтримуйте свою репутацію з Маґрам і принесіть голову хана Шаки до Варуґа в Селищі Маґрам у Пустці.",
    P = "Виконуйте завдання для Magram, а я вам допоможу.",
    C = "Хан Шака мертвий!  Я покладу його голову на щуку і залишу її при собі, щоб Шака міг побачити силу Маграма!",
},

[1380] = {
    en = "Khan Hratha",
    T = "Хан Храта",
    D = "$N, ти допоміг нам проти Маґрам. Тепер допоможи нам перемогти Марудінів! Убий голову їхнього клану, хана Храту!$B$BЩоб викликати його, сурми в Марудінський Ріг Війни. Він на високому урвищі в Долині Списів.$B$BАле щоб сурмити в ріг, тобі потрібен мундштук для рога. Їх рідко носять лише довірені кентаври Марудінів.$B$BПісля того, як ріг задме, кентаври прийдуть. Убивай їх, доки не з’явиться Храта.$B$BХан Храта має частину... ключа. Принеси її мені...",
    O = "Підтримуйте свою репутацію з Ґелкіс і принесіть Уламок Марудінського Ключа до Утек Мудрої в Селищі Ґелкіс.",
    P = "Хан Грата мертвий? У вас є фрагмент ключа?",
    C = "Він мертвий! Хан Грата мертвий! І зараз Мараудин впаде! Коли Гелкі будуть правити цією землею, $N, ми пам’ятатимемо вас. І духи землі співатимуть твоє ім’я навіки.",
},

[1381] = {
    en = "Khan Hratha",
    T = "Хан Храта",
    D = "Хан Ґелкіс мертвий, і тепер Марудіни впадуть! Убий хана Марудінів, Храту!$B$BЩоб викликати його, сурми в ріг на високому урвищі в Долині Списів. Але щоб сурмити в ріг, тобі потрібен мундштук. Щоб дістати мундштук, убий кентаврів Марудінів. Убивай, доки не знайдеш мундштук. Потім сурми в ріг.$B$BЗроби це, і кентаври Марудінів прийдуть до вежі. Убивай їх, доки не з’явиться хан Храта. Храта має частину ключа. Віддай цю частину мені...",
    O = "Підтримуйте свою репутацію з Маґрам і принесіть Уламок Марудінського Ключа до Варуґа в Селищі Маґрам у Пустці.",
    P = "Роби те, що я прошу.  Доведи мені, що ти союзник Маграма!",
    C = "Хан Грата мертвий!  Тепер Маграм — найсильніший із кентаврів!  Ми розчавимо інших і керуватимемо Пусткою!$B$BWe пам’ятатимемо, ти, $N, і ти будеш пощадений від наших копит, коли всі інші будуть розтоптані.",
},

[1382] = {
    en = "Strange Alliance",
    T = "Дивний Союз",
    D = "Нам пощастило, що клани кентаврів воюють між собою, адже якби вони об’єдналися в єдину силу, їх би ніщо не зупинило. Так, нам пощастило, і ми повинні скористатися нашою перевагою.$B$BОдин із кланів кентаврів, клан Ґелкіс, веде жорстоку війну з кланом Маґрам. Якщо ми нападемо на Маґрам, то, можливо, зможемо укласти союз із Ґелкіс.$B$BПоговоріть із Утек Мудрою на околиці таборів Ґелкіс у південно-західній частині Пустки. Через неї ми зможемо укласти союз із Ґелкіс.",
    O = "Здобудьте Дружню репутацію з Ґелкіс, а потім поговоріть із Утек Мудрою.",
    P = "геть! Гелкі не хочуть вас тут. Залиште зараз!!$B$BReturn після того, як убите багатьох Маграмів, а потім я поговорю з вами.",
    C = "Твоє ім'я шепочеться серед Гелкі. На ваших руках багато крові Маграма. Це добре.$B$BMaybe також добре, якщо ми розмовляємо. Розкажіть про те, що ви можете зробити для Гелкісів і що ми можемо зробити для вас.",
},

[1383] = {
    en = "Nothing But The Truth",
    T = "Ніщо, Крім Правди",
    D = "У мене є ідеальна сироватка на думці. Вона розбереться з правдою саме так, як із правдою слід розбиратися.$b$bДля цього зілля мені знадобиться кілька сердець Тіньових Пантер із Болота. Також мені потрібен зачарований гриб від Лорда Трясовини, що мешкає там. Я впевнений, що ти, $n, зможеш переконати його поділитися кількома.$b$bТепер найскладніше — знайти пухлину Глибокоступа з далекої Пустки. Дуже рідко тамтешні велетні хворіють, і утворюється пухлина.$b$bА тепер геть, іди!",
    O = "Аптекар Фаустін у Притулку Жебраків потребує 5 Сердець Тіньових Пантер, Гриб Лорда Трясовини та Пухлину Глибокоступа.",
    P = "Той Інфільтратор у Стонарді напевно... відкриється... після того, як вип'є мою спеціальну сироватку. Ха-ха!$B$BThe необхідні інгредієнти аж ніяк не легко придбати. Тіньові пантери поширені на болоті, але зібрати достатню кількість сердець для нашої мети може бути складно. А Володар боліт може бути таким метушливим звіром.$B$BAs Що стосується пухлини Deepstrider, їх дуже важко знайти. Але хімічна реакція, яку я можу отримати з цього, не має собі рівних.",
    C = "Чудово, $N! І вчасно. Зі слів Зрадуса, Інфільтратор одужав від ран і готовий до допиту орків.$B$BGive мені лише хвилинка, щоб приготувати пуа — я маю на увазі приготувати сироватку правди.",
},

[1384] = {
    en = "Raid on the Kolkar",
    T = "Набіг на Колкар",
    D = "Кентаври Колкар думають, що їхня магія сильна. Вони не знають магії! Вони б не впізнали магію, навіть якби вона їх вкусила!$B$BТи покажеш їм, що їхня магія слабка. Іди до Колкар на північний схід і вбивай їх. Забирай їхні обереги. Принеси мені ці обереги, і я кину їх у вогонь і сміятимуся!",
    O = "Підтримуйте свою репутацію з Ґелкіс і принесіть 10 Грубих Оберегів до Утек Мудрої в Селищі Ґелкіс у Пустці.",
    P = "Маєш принади? Ви показали Колкару, що вони слабкі?",
    C = "Ти робиш добру справу для Гелкіс. Колкар слабкий і загине. Їх магія жалюгідна і не врятує їх. Ти показав їм це, і їхній страх зробить їх ще слабкішими!$B$BAnd на наших землях слабкі скоро помирають.",
},

[1385] = {
    en = "Brutal Politics",
    T = "Жорстока Політика",
    D = "Пустка — земля, охоплена війною. Кентаври воюють між собою, і ми вважаємо, що переможець серед них розіллється назовні і загрожуватиме нашим фортецям. Цього ми не можемо допустити.$B$BМи мусимо дізнатися, як перемогти кентаврів, і для цього... ми мусимо укласти союз із одним із кланів. Кентаври Маґрам воюють із Ґелкіс. Якщо ти битимешся з Ґелкіс, Маґрам можуть розглянути союз.$B$BЗаслужи прихильність Маґрам, а потім поговори з Варуґом у селищі Маґрам у південно-східній частині Пустки.",
    O = "Здобудьте Дружню репутацію з Маґрам, а потім поговоріть із Варуґом.",
    P = "Ти зараз підеш, а то Маграм розчавить тебе! Щоб бути нашим другом, ти повинен убити Гелкіса.",
    C = "Тобі випадає багато Гелків. Мені це подобається. Можливо, ти зможеш робити більше речей, які мені подобаються. Можливо, ви з Маграмом станете друзями.",
},

[1386] = {
    en = "Assault on the Kolkar",
    T = "Напад на Колкар",
    D = "Колкар думають, що вони сильні, але ми сміємося з них! Ми сміємося і вбиваємо їх! Ти теж їх убий. Покажи мені, що ти можеш убивати Колкар, як ми. Вирушай на північ і зарубай їх усіх!",
    O = "Підтримуйте свою репутацію з Маґрам. Убийте 12 Кентаврів Колкар, 12 Розвідників Колкар і 6 Молотобійців Колкар, а потім поверніться до Варуґа в Селищі Маґрам у Пустці.",
    P = "Ви боїтеся Колкара? Чому ти їх не вбиваєш? Можливо, ти розучився вбивати. Поспішайте вбити Колкара, поки вони не загинули!",
    C = "Колкари бояться вас тепер! Сподіваюся, ти сміявся, коли вбивав їх. Краще сміятися, коли вбиваєш, щоб ворог побачив, що він слабкий.",
},

[1387] = {
    en = "Centaur Bounty",
    T = "Нагорода за кентаврів",
    D = "Кентаври складаються з багатьох кланів. Кожен має свого ватажка та власні цілі, але всі вони мають одну спільну рису — жорстокість.$B$BЯкщо ми хочемо знайти мир, кентаврів потрібно усунути. Я доручаю тобі це завдання.$B$BПід час мандрівки Безпліддям полюй на кентаврів і принось мені їхні вуха. Багато вух.$B$BЗроби це заради Альянсу, $N, і ми станемо на крок ближче до завершення війни.",
    O = "Принеси 15 вух кентаврів до капрала Мелкінса на Пункт Ніжеля в Безплідді.",
    P = "У вас є звіт, $N?",
    C = "Ах, вуха. Молодець.$B$BYour Служба Альянсу беззаперечна, $N. Кров, яку ви пролили в Desolace, без сумніву, врятує незліченну кількість життів.",
},

[1388] = {
    en = "Nothing But The Truth",
    T = "Ніщо, крім правди",
    D = "Усе йде за планом, $N. Я хочу, щоб ти передав цей сироватковий еліксир правди Смертосталкеру Зраедусу, і він покаже, як його правильно... застосувати.$B$BХа-ха!",
    O = "Передай сироватковий еліксир правди Фаустіна Смертосталкеру Зраедусу в Притулку Жебраків.",
    P = "Сподіваюся, ви довели свою користь нашому дорогому другові, аптекарю Фаустіну.",
    C = "Я знав, що старий Фаустін придумає щось хороше! Ви, безперечно, надзвичайно допомогли.$B$BNow Давайте приступимо до справи, чи не так?",
},

[1389] = {
    en = "Draenethyst Crystals",
    T = "Кристали дренетисту",
    D = "Загублені, що живуть у Притулку Спустошення, схожі на нас, але вони — чудовиська... збожеволілі від труднощів нашої подорожі до Азероту. Колись вони були нашими братами, а тепер живуть у Притулку Спустошення на сході, ловлячи або вбиваючи всіх, хто наближається.$B$BВони викрали дещо священне для нас — кристали дренетисту.$B$BУ нас немає сил, щоб увійти в Притулок і повернути наші кристали з їхніх хатин і вогнищ, але без цих кристалів... ми також можемо втратити свій шлях.",
    O = "Принеси 6 кристалів дренетисту до Маґтура в Гавань у Болоті Скорботи.",
    P = "У вас є кристали?",
    C = "Дякую, $N. Ми у вашому боргу.",
},

[1390] = {
    en = "",
    T = "Ой, ми знову їх убили.",
    D = "Відсутній текст",
    O = "Відсутній текст",
    P = "",
    C = "",
},

[1391] = {
    en = "Nothing But The Truth",
    T = "Ніщо, крім правди",
    D = "Нам потрібно діяти з певною обережністю. Зрештою, ти ж не збираєшся просто зайти туди і переконати дурня випити настоянку Фаустіна, правда?$B$BАле якщо є щось, від чого люди не можуть відмовитися, то це алкоголь. Я візьму сироватку Фаустіна і змішаю її з цим елем. Гарантую, бідолаха не вагатиметься, коли справа дійде до того, щоб хильнути пива.$B$BПоспіши до Стонарда в Болоті Скорботи, $N. І тримай нашу маленьку місію в таємниці...",
    O = "Віднеси пиво Зраедуса до Інфільтратора Марксена в Стонарді.",
    P = "Please have mercy on me! У мене є інформація, яка виходить за межі альянсу. Хоча я не симпатик Орди, відбувається політична зрада, яка має бути розкрита!",
    C = "Напій для мене? Як мило. Минули дні, як вони дозволили мені пити. Дайте мені випити це, а потім я розповім вам, чого я навчився....",
},

[1392] = {
    en = "Noboru the Cudgel",
    T = "Нобору Палиця",
    D = "Нобору місяцями тероризував дренеїв Гавані, і його палиця є символом жорстокості, яку вони зазнали від рук загублених.",
    O = "Принеси палицю Нобору до лідера Гавані в Болоті Скорботи.",
    P = "вітаю. І ласкаво просимо до Гавані.",
    C = "Ви отримали зброю страшного Нобору? Значить, він мертвий?$B$BThis — це радісний день для Гавані. Нобору та його банда були для нас жахом, вони блукали по болотах і вбивали будь-якого дренея, який траплявся йому на шляху. Він був прямою загрозою нашому виживанню, і ми не мали сил протистояти йому.$B$BWe нам пощастило мати в особі друга, $N.",
},

[1393] = {
    en = "Galen's Escape",
    T = "Втеча Ґалена",
    D = "Допоможи, благаю! Ці істоти збираються мене з’їсти!$B$BВиведи мене звідси, і я дам тобі великий скарб! Він у моєму таборі в болоті на північ від Стонарда, але замкнений у скрині, яку можна відкрити лише трюком, відомим мені.$B$BЯкщо ти допоможеш мені втекти, я навчу тебе цього трюку.",
    O = "Проведи Ґалена з небезпеки, потім знайди його табір у Болоті Скорботи та відкрий його скриню.",
    P = "Виведіть Галена з Заповідника Фоллоу.",
    C = "Замкова щілина цього сейфа залита чорною смолою. Неможливо відкрити.$B$BBut Гален розповів вам про приховану засувку на дні скриньки... $B$B...Після швидкого пошуку засувку знайдено. Засув відкривається, і скринька відкривається...",
},

[1394] = {
    en = "Final Passage",
    T = "Останній прохід",
    D = "Ти добре впорався, $N. Ти пройшов моє випробування і всі попередні. Повертайся до Дорна в Тисячі Голок. Він відчує зміни в тобі і побачить, що твій розум, тіло і дух досить сильні, щоб ти був нагороджений за свої зусилля.$B$BЗалишайся вірним рівновазі, яку ти демонстрував під час цих випробувань, $N. Дорн перевірить тебе знову в майбутньому, якщо ти це зробиш.",
    O = "Поговори з Дорном Рівностежником у Тисячі Голок.",
    P = "",
    C = "Ах, $N. Минуло багато часу з тих пір, як ти востаннє заходив у мій дім. Здається, минуло багато місяців відтоді, як ти зробив свій перший стрибок, який поставив тебе на твій шлях.$B$BAnd тепер ти повертаєшся до мене сильнішим, ніж колись... більш просвітленим. Це мене радує. І ви повинні бути справедливо винагороджені за те, що додивилися мої тести до кінця.",
},

[1395] = {
    en = "Supplies for Nethergarde",
    T = "Постачання для Пеклогарду",
    D = "Ця скриня з каменями сили потрібна в Твердині Пеклогарду, у Вибухових Землях. Вони не триматимуть силу довго, тому ми не можемо відправити їх з наступним караваном.$B$BТи мусиш їх доставити, і зробити це швидко.$B$BВіднеси їх до Квартирмейстера Лунґерца в Твердині Пеклогарду. Щоб дістатися до твердині, подорожуй на схід через Перевал Мертвого Вітру, потім на схід через Болото Скорботи, а потім на південь через Вибухові Землі.$B$BБудь обережним, $N. Ти подорожуватимеш небезпечними землями, але не повинен зазнати невдачі.",
    O = "Достав скриню з каменями сили до Квартирмейстера Лунґерца, поки камені не втратили силу.",
    P = "Привіт! Не зважайте на метушню, у Крепості Nethergarde все як завжди.$B$BYou маєте щось для мене?",
    C = "Ах, камені сили! Маги будуть раді їх побачити!$B$BMany дякую, $N. Я знаю, що твоя подорож із Темногір'я була нелегкою.",
},

[1396] = {
    en = "Encroaching Wildlife",
    T = "Наступ дикої природи",
    D = "Мій караван прямував до східного узбережжя, але ми не досягли мети. Загублені напали на нас, убивши вартових і знищивши припаси.$B$BЯ єдиний вижив після їхньої атаки. Я поклявся захищати те, що залишилося від припасів, але дикі звірі підкрадаються поблизу. Будь ласка, допоможи мені захистити мій табір від цих створінь!",
    O = "Убий 8 молодих пилкозубих кроколісків, 10 павуків скорботи і 10 болотних ягуарів, а потім повернися до Вартівника Біґґса в Болоті Скорботи.",
    P = "Болотяні створіння натискаються ближче, $N. Будь ласка, ви повинні захистити табір!",
    C = "Звуки тварин тепер слабкі, більш віддалені. Дякую, $N. Тепер будемо сподіватися, що вони не повернуться!",
},

[1398] = {
    en = "Driftwood",
    T = "Плавуча деревина",
    D = "Я дуже тобі вдячний, $N. У тобі б’ється чесне серце. І тепер у мене є ще одне завдання, з яким я покірно прошу твоєї допомоги.$B$BЯкщо я коли-небудь дістануся до Пеклогарду, мені потрібно полагодити цей віз. А для цього... мені потрібна деревина. Міцна, суха деревина — не губчаста чи сплутана, як у дерев болота.$B$B$N, вирушай на схід до узбережжя і пошукай суху плавучу деревину, висушену сонцем. Принеси її мені.",
    O = "Принеси 8 шматків сонцесушеної плавучої деревини до Вартівника Біґґса в Болоті Скорботи.",
    P = "Ти знайшов корчі, $N?",
    C = "Ця деревина легка, але міцна. Дякую, $N. Це буде добре працювати.",
},

[1418] = {
    en = "Neeka Bloodscar",
    T = "Ніка Кривавошрам",
    D = "Безпліддя суворе і лежить близько до земель Альянсу, Лох-Модану, тому зв’язок між Стонардом і форпостом Карґата часто переривається.$B$BДоведи свою цінність, $N. Подорожуй до Безпліддя і поговори з Нікою Кривавошрам, головною розвідницею форпосту Карґата. Поговори з нею, а потім поверни її звіт мені.",
    O = "Поговори з Нікою Кривавошрам.",
    P = "",
    C = "Гельґрум хоче звіту, еге ж? Не минуло й трьох днів. Він провалив свою місію? Якщо у Стонарда немає мого звіту, то, здається, він зазнав невдачі.$B$BLet сподівається, що наступний бігун, якого я відправлю, матиме більше навичок або більше удачі.",
},

[1419] = {
    en = "Coyote Thieves",
    T = "Злодії-койоти",
    D = "Ти провів багато днів у Безплідді, $C? Відчув його спеку? Зіткнувся з звірами, що блукають його пиловими рівнинами? Настав час це зробити.$B$BСкельні койоти — витривалий вид. Витривалий і досить зухвалий, щоб прокрадатися до Карґата і красти наші запаси їжі. Допоможи позбутися цих злодіїв!$B$BПолюй на скельних койотів, $N. Принеси мені їхні щелепні кістки. Принеси достатньо, і, можливо, я повірю, що ти знаєш Безпліддя.",
    O = "Принеси 30 щелепних кісток койотів до Ніки Кривавошрам у Карґаті.",
    P = "У вас є щелепи?",
    C = "Це гарна колекція щелепних кісток, $N. Тепер ці койоти не будуть рвати наші запаси на сміття.$B$BWell готово. Койоти з Безплодних земель не є легкою здобиччю. Твій вчинок показує мені, що ти можеш просто вижити тут.",
},

[1420] = {
    en = "Report to Helgrum",
    T = "Звіт для Гелґрума",
    D = "Я написала свіжий звіт для Гелґрума в Стонарді. Достав його йому.$B$BІ якщо ти вважаєш себе бігуном, не заблукай. І не падай від рук ворога.",
    O = "Достав звіт Ніки до Гелґрума Швидкого в Стонарді.",
    P = "Ви повернулися. У вас є звіт?",
    C = "Дякую, $N. Зі звіту Ніки я бачу, що Альянс не позбавлений власних проблем. І ми можемо виявити, що у нас є спільні вороги.",
},

[1421] = {
    en = "The Lost Caravan",
    T = "Загублений караван",
    D = "Я був приголомшений під час нападу Загублених, але перед тим, як мої очі затьмарилися, я помітив, як один із наших возів тягнуть до Притулку Спустошення, села загублених на півночі.$B$BУ тому возі була скриня каравану з цінними реагентами, необхідними для досліджень магів Твердині Пеклогарду. Знайди цю скриню і дістань ці реагенти, $N. Принеси їх мені.",
    O = "Знайди скриню каравану в Притулку Спустошення, дістань реагенти магів і принеси їх до Вартівника Біґґса.",
    P = "У вас є реактиви чарівника, $N?",
    C = "Ах, ви їх знайшли! З ними чарівники в Nethergarde можуть продовжувати свою роботу. Я не знаю, чим вони займаються, але це пов’язано з Темним порталом у Вижжених землях і є життєво важливим для безпеки Альянсу.",
},

[1422] = {
    en = "Threat From the Sea",
    T = "Загроза з моря",
    D = "Поки я починаю роботу над твоєю зброєю, чому б тобі не поговорити з Катаром? Він згадував, що йому потрібна допомога з патрулюванням узбережжя, і я б волів, щоб ти тримав свої розум і зброю напоготові, а не напивався з іншими гультяями, з якими я ділю цей табір.",
    O = "Поговори з Катаром у Болоті Скорботи.",
    P = "",
    C = "Замовкни хвилинку, $C. Навіть за глухим гуркотом моря все ще чути те огидне булькання людей-риб.",
},

[1423] = {
    en = "The Lost Supplies",
    T = "Загублені припаси",
    D = "Ця бочка маленька, але міцна. Її шви запечатані жовтим, різким воском. На дні бочки вибито напис:$B$BКВАРТИРМЕЙСТЕР ЛУНҐЕРЦ$B$BТВЕРДИНЯ ПЕКЛОГАРДУ",
    O = "Принеси загублені припаси до Квартирмейстера Лунґерца.",
    P = "Маєш щось для мене?",
    C = "Ах, дякую $N! Так багато припасів втрачено від Темногір’я сюди. Приємно бачити, що деякі з них одужали.",
},

[1424] = {
    en = "Pool of Tears",
    T = "Озеро Сліз",
    D = "Вождь послав нас дослідити дивні події в Храмі Атал’Гаккара.$B$BТролі Атал’ай — це плем’я темних чаклунів, відомих своєю забороненою магією. Уяви наше здивування, коли ми прибули сюди і виявили, що храм затоплений.$B$BТепер його охороняють зелені дракони, які стверджують, що вони захисники Азероту.$B$BНам потрібно з’ясувати, що сталося. Досліди територію навколо Озера Сліз і збери артефакти Атал’ай. З них я зможу почати розгадувати цю загадку.",
    O = "Фел’зерул у Стонарді хоче, щоб ти зібрав 10 артефактів Атал’ай.",
    P = "Ніхто не знає, які темні практики відбувалися в храмі Атал'Хаккара. Але ми знаємо, що використовувалися великі та потужні сили магії.$B$BWe маємо дізнатися якомога більше про таку магію. Можливо, заклинання Атал'ая знадобляться Орді.$B$BOnce ви зібрали достатньо артефактів Атал'ая з Басейну Сльозів, я можу почати розуміти, чого сподівалися досягти тролі і що пішло так жахливо не так.",
    C = "Ваша старанність у збиранні артефактів Атал'ай гідна похвали, $C.",
},

[1425] = {
    en = "Deliver the Shipment",
    T = "Доставка вантажу",
    D = "Поки я лагоджу цей віз, $N, у мене є ще одне завдання для тебе.$B$BЯ запакував найважливіші припаси, врятовані від атак оґрів. Віднеси їх до Твердині Пеклогарду. Твердиня розташована в північних пагорбах Вибухових Земель, стежачи за Темним Порталом.$B$BЩоб дістатися до Пеклогарду, іди дорогою на схід. Коли вона розгалужується, поверни на південь у Вибухові Землі, потім ліворуч на наступному роздоріжжі. Слідуй дорогою, $N, і будь обережним.",
    O = "Достав вантаж до Пеклогарду до Квартирмейстера Лунґерца в Твердині Пеклогарду.",
    P = "Маєш справу зі мною?",
    C = "що? Пакет із каравану Біггса? Ми думали, що це, і він, загубилися.$B$BThank ти, $N. Якщо пощастить, ці запаси міститимуть такий необхідний реагент, кристали Азорану. Наші запаси закінчуються...",
},

[1426] = {
    en = "Threat From the Sea",
    T = "Загроза з моря",
    D = "Я не люблю море, ані жодну істоту, що з нього виходить. Воно могутнє, але сліпе; жорстоке і безжалісне. Мені було б надзвичайно приємно знищувати риболюдей сотнями, якби це було в моїх силах. Але я отримую певне задоволення, спостерігаючи за їхньою смертю від рук тих, хто виконує волю Орди.$B$BЦе приводить нас до тебе, $C. Скількох ти можеш убити? Чи готовий ти випробувати себе проти їхніх наймогутніших представників?",
    O = "Убий 10 болотних мурлоків, 10 болотних чорнилоплюїв і 10 болотних м’ясоїдів, а потім повернися до Катара в Болоті Скорботи.",
    P = "Я терплячий. Терплячий і вічний, як старий камінь канк з Дренора. Люди-риби не зможуть подолати наші кордони, поки я стою. Якби в нашому розпорядженні була армія, я б очистив цей світ і всі інші від їх присутності. Я відчуваю, як моя ненависть кипить, коли тільки про них кажу.",
    C = "Море здається величезним і невблаганним, але ви заплямували його кров’ю її власної ікри. Люди-риби знають біль. Їхня дурість змусить їх зміцнити свої лави від спустошення, яке ви спричинили, і це добре.$B$BLet їхні клекотливі крики затьмарюють рев моря до ночі. Я буду посміхатися щоразу, коли почую, що хтось із них замовк.$B$BReturn мені, якщо ти хочеш убити більше риболюдей. З радістю винагороджу вас ще раз.",
},

[1427] = {
    en = "Threat From the Sea",
    T = "Загроза з моря",
    D = "Перш ніж відпочити, поговори ще раз із Ток’Каром. Поки тебе не було, здається, він закінчив кілька одиниць зброї. За твою допомогу тут він запропонує тобі одну з них. Ти добре зробиш, якщо випробуєш її силу проти риболюдей, коли будеш готовий... але лише щоб ще більше мене порадувати.",
    O = "Поговори з Ток’Каром у Болоті Скорботи.",
    P = "",
    C = "Ах, $N, ти повернувся. добре. Я закінчив створювати більше зброї для нашої боротьби з мурлоками. За те, що ви принесли нам свіже пилкоподібне м’ясо та викликали легку посмішку на обличчі Катара, я пропоную один із них вам.",
},

[1428] = {
    en = "Continued Threat",
    T = "Продовження загрози",
    D = "Мені приємно бачити, що твоя ненависть до риболюдей зростає разом із моєю.$B$BЗнайди ще більше їхнього роду вздовж узбережжя, і коли наситишся боєм, повертайся до мене. Тоді ми поговоримо про нагороду за твою старанність.",
    O = "Убий 10 болотних чорнилоплюїв, 10 болотних м’ясоїдів і 10 болотних оракулів, а потім повернися до Катара в Болоті Скорботи.",
    P = "Я не буду щасливий, поки море та всі його діти не замовкнуть... особливо ці огидні люди-риби.",
    C = "Молодець, $C. Я закликаю більше їх крові. Нехай згинуть усі люди-риби.",
},

[1429] = {
    en = "The Atal'ai Exile",
    T = "Вигнанець Атал’ай",
    D = "Поки ти боровся з небезпеками Озера Сліз, один із моїх розвідників повернувся зі сувоєм, написаним кров’ю на висушеній плоті. Здається, це судовий вирок проти жерця племені Атал’ай.$B$BЦього жерця засудили до долі гіршої за смерть серед Атал’ай.$B$BЙого вигнали жити далеко на півночі, у Внутрішніх Землях, разом із тролями Візербарку.$B$BЯ зберу ці артефакти в пакунок. Ти мусиш знайти вигнанця і дізнатися про їхнє справжнє призначення. Повертайся до мене, коли завершиш свою подорож.",
    O = "Принеси пакунок артефактів Атал’ай до Вигнанця Атал’ай у Внутрішніх Землях.",
    P = "Ти сміливий, що прийшов сюди. Хоробрий чи дурний...",
    C = "Ви принесли мені артефакти виклику Atail'ai?$B$BI бачите, як Пророк Джаммал'ан веде учнів Кривавої кімнати до обраної долі. Цікаво, Хаккар повернувся до Храму? Чи спіткала їх доля?",
},

[1430] = {
    en = "Fresh Meat",
    T = "Свіже м’ясо",
    D = "Мої клієнти дуже полюбляють соковитий смак м’яса повзунів; особливо м’ясо від гігантських повзунів.$B$BЯкщо ти плануєш вирушити до узбережжя, я можу зробити так, щоб це вартувало твоїх зусиль — принеси мені кілька їхніх ніг, щоб я відправив їх до Оргріммара.$B$BУзбережжя на схід звідси, і ти не матимеш проблем із пошуком цих створінь, що гасають по пляжах і під водою.",
    O = "Принеси 10 ніг гігантських повзунів до Дара в Болоті Скорботи.",
    P = "У мене бочка вина чекає на твій успіх, $N. Цілком правильно, що я спробую товар, перш ніж відправити його назад моїм клієнтам.",
    C = "Ах, це має бути ідеально. Я не можу дочекатися, щоб скуштувати їх після того, як вони ідеально приготовані на відкритому вогні. Ви повинні взяти його зразок із собою у подорожі. Це справді дуже смачно.",
},

[1431] = {
    en = "Alliance Relations",
    T = "Відносини з Альянсом",
    D = "Тихше, $C, і дозволь мені поділитися з тобою дещо важливим для нашого народу, але далеко не очевидним.$B$BМи гордий народ, і війна з людьми випробувала навіть величезне терпіння Тралла. Бачиш, наш Вождь мудрий і розсудливий, і він продовжує ставити свій народ на перше місце. Зрештою, він дипломат, і за час із людьми він багато дізнався про їхні звичаї.$B$BЯкщо розповідь, яку я почав, зацікавила тебе, знайди Келдрана біля західного виходу з міста. Його халупа там.",
    O = "Поговори з Келдраном в Оргріммарі.",
    P = "",
    C = "$N, благородний $C. Я Келдран, учень магії... та інших містичних мистецтв.$B$BThe справа, про яку Крейвен послав вас сюди, щоб поговорити зі мною, вимагає трохи більше тонкощів, ніж ви потребували раніше, але це не означає, що ви все ще не можете допомогти нашій справі.$B$BPlease, влаштуйтеся зручніше, і я скажу вам, чому Вождь потребує моєї допомоги... і ваш.$B$BIt починається з зовнішності, $N. Як бачить себе Орда. Як нас бачать наші союзники. А головне, як нас бачать вороги.",
},

[1432] = {
    en = "Alliance Relations",
    T = "Відносини з Альянсом",
    D = "У міру того, як Альянс просувається все глибше в Калімдор, можуть бути зроблені хибні висновки про те, що Орда укладає угоди з Палаючим Легіоном. Вождь не може цього допустити. І з його благословення я беру на себе контроль над їхнім усуненням.$B$BУ мене є агенти в районі Безпліддя на Посту Примарного Вітру на північ від великого Кладовища Кодо. Вирушай на південь від Обвугленої Долини в Кам’яношпилевих горах, і ти його знайдеш. Прибувши, шукай Такату Сталелеза.",
    O = "Поговори з Такатою Сталелезом у Безплідді.",
    P = "",
    C = "Вітаю, $C. Ви приносите новини з Оргріммара; це добре.$B$BThe нашестя демонів переповнює цю територію навіть більше, ніж запах гною кентавра. Вершники заявляють, що ця земля є їхньою, але очевидно є впливи поза їхнім контролем, які розчавлять їх, якщо їх не стримувати.$B$BIt Мені не подобається, що ми опосередковано допомагаємо кентавру, але це для блага Орди, тому я виконую свій обов’язок перед Вождем, навіть якщо це означає допомогу чорнокнижникам в Орді.",
},

[1433] = {
    en = "Alliance Relations",
    T = "Відносини з Альянсом",
    D = "Палаючий Клинок має багато цілей, але знай, що вони злі до глибини душі, їхні духи зіпсовані, і їхнє знищення — єдиний спосіб зірвати їхні плани.$B$BКелдран відправив зі мною Мауріна через його знання про Клинок і їхні чаклунські методи.$B$BВін контролює наші плани проти Клинка, поки я займаюся іншими демонічними загрозами тут, у Безплідді.$B$BПоговори з ним, і він скерує тебе в його задумах.",
    O = "Поговори з Мауріном Кістколомом у Безплідді.",
    P = "",
    C = "Ах, так. Допомога тих, хто вірний Вождю, завжди цінується.$B$BMy ім’я Морін. Я тут за велінням Келдрана та дитинча Вождя Тралла. Я хочу допомогти молодому лідерові протистояти злу, яке загрожує його правлінню.$B$BCome, підійди ближче, $C. Я поясню вам мій план видалення гнійного нариву, яким є Палаючий Клинок.",
},

[1434] = {
    en = "Befouled by Satyr",
    T = "Зганьблені сатирами",
    D = "Зараження демонами не відбувається без інших впливів — щось інше дозволяє злу закріпитися.$B$BЦе може початися зі слабкого духу, непотрібного прагнення влади; можливо, це жага помсти чи прагнення остаточної справедливості. Коли нас охоплює біль, зло використовує нас — зло, таке як сатири.$B$BМіж ними та Палаючим Клинком є зв’язки, і Тралл бажає їх знищення. Шукай їх на північному сході звідси і повертайся до мене, коли відкинеш їх назад.",
    O = "Убий 7 гнівопохітних шахраїв, 7 гнівопохітних присягопорушників, 7 гнівопохітних зрадників і 7 гнівопохітних пеклопокликачів, а потім повернися до Такати Сталелеза в Безплідді.",
    P = "Напарник таурена попередив мене, що сатири — це не те, чим вони здаються. Він вірить, що в них є щось більше, що їхнє зло є спотворенням їх справжньої природи. Але я не бачив таких речей.$B$BI бачу лише безжальне вбивство слабких і розбещення тих, хто прагне темної влади.$B$BI продовжуватиму виконувати свій обов’язок знищувати їх, доки Вождь не накаже мені інакше. До того часу я не шкодую їх.",
    C = "Ви добре зробили, $c. Ви виявили честь і відданість.$B$BWhen нашу кампанію в Пустощі завершено, Вождь знатиме, що ви допомогли нам у наших діях тут і що ви допомогли реалізувати його волю.$B$BI дякую.",
},

[1435] = {
    en = "The Burning of Spirits",
    T = "Спалення духів",
    D = "Смерть — найбажаніший результат для тих мерзенних створінь, що зрадили свого сюзерена з таких егоїстичних причин. Але смерть недостатня, коли йдеться про тих, хто віддався темряві.$B$BВізьми цей самоцвіт. Коли один із Палаючого Клинка буде близький до смерті, активуй його магію. Заклинання витягне зіпсований дух із жертви, залишивши за собою просочений самоцвіт.$B$BПринеси мені ці просочені самоцвіти, щоб я міг належним чином їх знищити.$B$BІди, і хай смерть обійде тебе стороною.",
    O = "Поверни палаючий самоцвіт і 15 просочених палаючих самоцвітів до Мауріна Кістколома в Безплідді.",
    P = "Я намагався зробити магію максимально простою. Витягнути дух вашої жертви з його пораненої форми має бути дитячою грою. Не покладайтеся на силу дорогоцінного каменю, щоб повністю вбити свого ворога. Ви повинні активувати дорогоцінний камінь лише тоді, коли вони близькі до смерті, інакше він буде марним.",
    C = "Ах, ви успішно повернулися. Це добре. Дайте мені дорогоцінні камені, і я покладу їх у безпечне місце...$B$BMy завдання для вас виконано, $C. Поговоріть з Такатою, коли відпочинете. У нього можуть бути інші завдання для вас, або, можливо, потрібно, щоб ви повернулися в Оргріммар, щоб повідомити Келдрану про наш прогрес тут, у Пустощі.",
},

[1436] = {
    en = "Alliance Relations",
    T = "Відносини з Альянсом",
    D = "Боротьба йде добре, $N. Можливо, Вождь дозволить нам повернутися до наших домівок до зміни сезонів, якщо ми продовжимо досягати таких великих успіхів у нашій битві проти демонів та їхніх поплічників.$B$BПовертайся до Келдрана і повідом йому, що ми зробили. Я впевнений, він нагородить тебе за твої зусилля тут. Його справа важлива для нього, і він пишатиметься, знаючи, що Вождь поважає його занепокоєння.",
    O = "Поговори з Келдраном в Оргріммарі.",
    P = "",
    C = "Ви повернулися з Desolace більш ніж успішно, $N. Дякую.$B$BThank за ваші зусилля, час і розуміння мого прохання. Тралл розуміє та бажає миру між Ордою та Альянсом, і, вживаючи заходів, щоб переконатися, що наша зовнішність є прийнятною, ми не провокуватимемо жодних подальших загроз непотрібного насильства.$B$BI я в боргу перед вами.",
},

[1437] = {
    en = "Vahlarriel's Search",
    T = "Пошуки Валарріеля",
    D = "Я Валарріель, $N. Я прибув сюди, щоб дізнатися про долю двох зниклих дворян із дарнаської купецької родини — Дому Малем. Батько родини боїться найгіршого, і я мушу зробити все можливе, щоб знайти його зниклих дітей. Я ще не почав пошуки Тіраніса чи Далінди, але я сподіваюся, що не затримаюся тут надовго.$B$BОстанні відомості говорять, що вони проходили через Кам’яношпилеві гори кілька тижнів тому.$B$BЯкщо ти знайдеш їхній віз, будь ласка, негайно знайди мене.",
    O = "Знайди і обшукай віз Тіраніса і Далінди Малем у Безплідді.",
    P = "",
    C = "Коли ви нишпорите навколо залишків фургона, стає очевидним, що його атакували як заклинаннями, так і зброєю. Бій здавався одностороннім і швидким; там немає крові та жодних останків будь-яких тіл.$B$BWhoever напав на вагон був ефективним і швидким.",
},

[1438] = {
    en = "Vahlarriel's Search",
    T = "Пошуки Валарріеля",
    D = "Знайди Далінду і Тіраніса, якщо зможеш, і повернися до мене з твоїми знахідками. Почни пошуки з цієї фортеці. Я негайно зв’яжуся зі своїми начальниками в Дарнасі і повідомлю їх про ситуацію.$B$B$N, є ще дещо, що я хочу тобі наголосити. Мої начальники висловили певне занепокоєння щодо Тіраніса та його мотивів перебування тут. Для них важливіше, щоб Далінда була знайдена і повернута в безпеці. Тіраніса потрібно... оцінити, перш ніж його заберуть додому.",
    O = "Знайди Далінду Малем у Безплідді.",
    P = "",
    C = "Дякую Елуні, хтось нарешті прийшов допомогти. Будь ласка, $C, мені потрібна ваша допомога. Я та мій брат Тіраніс були схоплені та привезені сюди Палаючим Клинком. Гадаю, вони збираються принести мене в жертву своїм володарям демонів!$B$BI знав, що прийти до Пустощі було помилкою, але Тіраніс нещодавно почав жадати знань про все таємне — навіть всупереч волі нашого народу. Він вирішив здійснити цю подорож навіть після того, як почув розповіді про зараження демонами цієї землі.$B$BI побоюйтеся найгіршого для нього.",
},

[1439] = {
    en = "Search for Tyranis",
    T = "Пошуки Тіраніса",
    D = "Нас привели сюди після того, як орки зарубали всіх наших вартових і слуг. О, які жахливі речі вони з ними робили! Я думала, що вони точно вб’ють нас прямо там, але стало зрозуміло, що в них інші плани.$B$BТіраніс намагався з ними говорити. Я думаю, він хотів вразити їх своїми знаннями про таємне... не знаю, чому.$B$BБудь ласка, я не можу звідси піти, поки не дізнаюся, що сталося з моїм братом. Знайди його, а потім повернися за мною, коли його доля стане відомою.",
    O = "Знайди Тіраніса Малем у Безплідді.",
    P = "Я боюся, що Тіраніс спробує дізнатися секрети Палаючого Клинка і зарахує себе до їхнього роду, якщо вони це дозволять — він завжди обожнював силу, яку магія приносить тим, кого вона спокушає.$B$BI Я не впевнений, що зможу витримати повернення додому до своєї родини з новинами про дух Тіраніса, який заграє з такими небезпеками. Це досить жахливий злочин серед мого роду, щоб займатися такими речами, але стати тим, від чого ми намагаємось захистити себе, що ж, це зрозуміло.",
    C = "Це жахливо! Але я вважаю, що це було необхідно. Якби це було не твоєю рукою, то точно було б рукою мого народу. Мабуть, я мав би подякувати вам, будь ласка, вибачте мене, якщо це не здається щирим. Я не маю на увазі.$B$BWith Знаючи про долю мого брата в руках, здається, час моєї втечі настав. Якщо ви все ще бажаєте, я прийму вашу допомогу у втечі з цього жахливого місця.$B$BWhen ви готові, ми можемо пробитися в безпечне місце.",
},

[1440] = {
    en = "Return to Vahlarriel",
    T = "Повернення до Валарріеля",
    D = "Отже, настав час? Я ціную твої зусилля, і якщо ситуація не дозволить, дозволь мені подякувати тобі зараз за все, що ти зробив для мене і моєї родини. Якщо ти готовий, то мені тут більше немає чого робити — ми можемо вирушити, коли ти вважатимеш, що час настав.",
    O = "Супроводи Далінду Малем із Фортеці Громового Сокира, а потім повернися до Валарріеля Демоновбивці в Безплідді.",
    P = "Врятувати Далінду Малем",
    C = "Дякую, $N. Далінда благополучно повернулася сюди, на Найджелс-Пойнт, у набагато кращому стані, ніж я міг очікувати. Те, що вона прибула сюди своїми силами, було добрим знаком. Сподіваюся, ти почуваєшся добре?$B$BIt Мені боляче знати, що Тіраніс і Далінда не повернулися, але збентеження, пов’язане з рішенням Тіраніс, належить їй терпіти. Це те, з чим їй доведеться мати справу, коли вона повернеться в Дарнас.",
},

