[1501] = {
    en = "Creature of the Void",
    T = "Істота з Порожнечі",
    D = "Так мало чорнокнижників залишилося... Ми багато ризикуємо, але ці ризики виправдані. Ти мусиш швидко досягти зрілості у своїх здібностях, якщо хочеш бути корисним Орді та Вождю.$B$BНастав час навчитися нового заклинання виклику.$B$BСпершу ти мусиш здобути Скрижаль Верґа, яку викрали чорнокнижники Палаючого Леза і тепер тримають у їхньому лігвищі в Скелі Черепа на схід від міста. Зі скрижаллю я покажу тобі руни, необхідні для виклику порожняра.",
    O = "Здобудь Скрижаль Верґа для Ґан’рула Кривавоокого в Орґріммарі.",
    P = "У вас є Скрижаль Верги, $N? Якщо ні, я не хочу говорити з вами, поки ви цього не зробите.",
    C = "добре. Сподіваюся, ви завдали ще деяких втрат Палаючому Клинку, коли пішли за цим.$B$BThey були джерелом великого роздратування для Вождя та великої шкоди для чорнокнижників загалом.",
},

[1502] = {
    en = "Thun'grim Firegaze",
    T = "Тун’ґрім Вогнегляд",
    D = "Життєво важливо, щоб зброя воїна була високої якості. І якщо є орк, який може створювати якісну зброю, то це Тун’ґрім Вогнегляд. Він відлюдник, що живе на вершинах пагорбів на схід від Перехрестя.$B$BЯкщо ти шукаєш зброю, воїне, то тобі варто звернутися до Тун’ґріма. Щоб знайти його, спершу вируш до Перехрестя на захід, а потім іди на схід у пагорби. Його табір розташований високо на вершині пагорба.",
    O = "Поговори з Тун’ґрімом Вогнеглядом у Степах.",
    P = "",
    C = "Мої очі давно висохли від погляду на полум’я кузні, але деякі речі я все ще бачу. Я бачу, що ти чогось хочеш.$B$BAnd Якщо ти знайшов дорогу сюди, я можу здогадатися, чого ти хочеш.",
},

[1503] = {
    en = "Forged Steel",
    T = "Кована сталь",
    D = "Я дам тобі зброю, $N, але спершу ти мусиш мені допомогти. Кілька ночей тому до мого табору прийшли Гострошерсті з північного заходу. Вони не наважилися битися зі мною, але знали, що мої очі слабкі — кілька відволікали мене хрюканням, поки інші крали в мене! Боягузи!$B$BВони вкрали залізну скриню, а в ній були ковані сталеві злитки. Якщо ти зможеш їх повернути, я дам тобі зброю, яку ти шукаєш.$B$BШукай залізну скриню в таборах кабанолюдей і повернися з кованими сталевими злитками.",
    O = "Принеси Ковані Сталеві Злитки Тун’ґріму Вогнегляду в Степи.",
    P = "У вас є мої сталеві прути?",
    C = "Ви їх знайшли! І всі бари тут, що мене не дивує. Я не думав, що Бритвогриви знають, що робити з такою високою сталлю.$B$BThank ти, $N. Ось вам нагорода. Нехай він служить тобі добре.",
},

[1504] = {
    en = "The Binding",
    T = "Зв’язування",
    D = "Тепер уважно розглянь Скрижаль Верґа, адже вона містить гліфи, необхідні для виклику. Візьми їх до кола виклику в наметі Ніру Вогнелеза по той бік печери. Там ти зможеш викликати порожняра.$B$BТи мусиш перемогти його, використовуючи будь-які фізичні та магічні засоби, які маєш у своєму розпорядженні. Коли це буде зроблено, повернися до мене з гліфами виклику, і я покажу тобі, як підкорити цю істоту своїй волі.",
    O = "Використовуючи Гліфи Виклику, призови і підкори порожняра, а потім поверни Гліфи Виклику Ґан’рулу Кривавоокому в Орґріммар.",
    P = "Мандрівник Безодні — могутня істота. Я пам’ятаю, як я був на твоєму місці, $N. З роками мій власний бродяга безодні став менше битися зі мною, хоча я підозрюю, що це лише тому, що він сподівається, що я підведу свою пильність.$B$BRemember це, $N.",
    C = "Ви добре зробили, $N. Я покажу тобі, як викликати захисника Безодні, схожого на того, якого ти щойно переміг.$B$BYou маєш знати, що ми покладаємо на тебе високі сподівання, і наразі ти їх виправдав.$B$BDo Однак не дозволяй це спасти тобі голову, оскільки завдання, які ще перед тобою, зроблять це таким же простим, як прокинутися вранці.",
},

[1505] = {
    en = "Veteran Uzzek",
    T = "Ветеран Уззек",
    D = "Орда шанує своїх воїнів, адже їхня сила незаперечна. Але по-справжньому великі воїни — це також великі учні.$B$BЗнайди Уззека. Він ветеран багатьох битв і тепер навчає молодих воїнів мистецтву бою. Ти знайдеш його на південь від Поста Далекого Дозору, оркського гарнізону на кордоні Степів і Дуротару на сході.",
    O = "Поговори з Уззеком на Посту Далекого Дозору.",
    P = "",
    C = "Привіт, молодий. Ви тут, щоб отримати інструкцію?",
},

[1506] = {
    en = "Gan'rul's Summons",
    T = "Запрошення Ґан’рула",
    D = "Ти тут. $N, так?$B$BСподіваюся, твій графік не надто щільний, бо Ґан’рул хоче бачити тебе негайно. Ти знайдеш його зі старшими чорнокнижниками в Розщелині Тіней.$B$BСудячи з мого попереднього досвіду з Ґан’рулом, твоє запрошення — це або дуже хороша, або дуже погана новина.",
    O = "Поговори з Ґан’рулом Кривавооким в Орґріммарі.",
    P = "",
    C = "добре. Я боявся, що Офек не досягне вас.$B$BIt настав час підвищити ваше навчання чаклуна. Будь-який бізнес, який у вас зараз є, доведеться почекати.$B$BI вірите, що з цим не виникне проблем?",
},

[1507] = {
    en = "Devourer of Souls",
    T = "Пожирач душ",
    D = "Настав час тобі навчитися більшого про магію виклику. Ти навчишся викликати суккуба, істоту з неймовірними ментальними здібностями. Вона може зачаровувати тих, у кого слабкий розум, і змушувати їх служити їй — але не бійся! Я впевнений, що ти впораєшся з цим викликом.$B$BСуккуба можна викликати лише за допомогою предмета, який символізує велику відданість і любов. Я залишаю тобі знайти такий об’єкт.$B$BПорада? Поговори з Казулом... Здається, немає нічого, чого б цей древній чорнокнижник не знав.",
    O = "Поговори з Казулом у Розщелині Тіней.",
    P = "",
    C = "Хм... Зарм. Ви все ще новачок на своєму шляху, але я відчуваю в вас можливість стати величним.$B$BYou народилися з даром, $N. Дивіться, щоб вони не пропали даремно.",
},

[1508] = {
    en = "Blind Cazul",
    T = "Сліпий Казул",
    D = "Гм... Але, звісно, ти прийшов до мене не за цим.$B$BЯкщо Ґан’рул послав тебе до мене, це означає, що ти маєш викликати суккуба і тобі потрібен предмет для приманки.$B$BГм... Якщо ти довіряєш сліпому вести тебе, $N, то слухай. У скелях Орґріммара, на захід від вежі повітряних вершників, живе Занкайя. Вона чекає повернення свого коханого.$B$BІди до неї.",
    O = "Поговори з Занкайєю в Орґріммарі.",
    P = "",
    C = "Ви прийшли з новинами про Дограна? Він мав повернутися кілька днів тому, а я нічого не чув...",
},

[1509] = {
    en = "News of Dogran",
    T = "Новини про Доґрана",
    D = "Мій коханий, Доґран, нещодавно був відправлений до Перехрестя на службу. Це було підвищення, і він дуже пишався.$B$BМені, звісно, було сумно, але я не показувала цього. І ще я хвилювалася. Степи — набагато небезпечніше місце, ніж Орґріммар, і я боялася найгіршого.$B$BТепер минув тиждень після того, як він мав повернутися, а я не отримала від нього жодної звістки...$B$BМоже, ти міг би поїхати до Перехрестя і дізнатися, чи є якісь новини? Він працював із Ґазроґом, який, мабуть, усе ще там.",
    O = "Поговори з Ґазроґом на Перехресті.",
    P = "",
    C = "Занкая? Це приятель Дограна, чи не так?$B$BYeah, я чув від нього, але це не та новина, про яку ми повинні повідомляти їй...$B$BNo, він не мертвий. Але він поранений і в'язень кілбоара.",
},

[1510] = {
    en = "News of Dogran",
    T = "Новини про Доґрана",
    D = "Він був розміщений у Таборі Таурахо, де ми намагаємося викорінити кабанолюдей. Він повів кількох піхотинців до одного з їхніх таборів, де його сильно поранили. Інші повернулися і намагалися його врятувати. Він був у поганому стані, рани загноїлися, тож вони боялися його переносити без попереднього лікування.$B$BВони надіслали повідомлення сюди, просячи цілющий настій від тролів у Малак’аджині біля підніжжя Кам’яних Кігтів. Ми відправили когось по нього, але вони ще не повернулися.",
    O = "Поговори з Кен’зіґлою в Малак’аджині.",
    P = "",
    C = "Ще один $R, еге ж? Сподіваюся, ви прийшли не за іншим. Він не встиг. Ті гобліни принесли йому користь.$B$BHe сказав, що йому потрібен лікувальний напій, але нічого іншого.",
},

[1511] = {
    en = "Ken'zigla's Draught",
    T = "Настій Кен’зіґли",
    D = "Я подумав, що може прийти ще хтось по настій, тож я його все одно приготував.$B$BОсь, тримай, $N. Але пам’ятай, дай йому лише половину! Це дасть йому достатньо сил, щоб рухатися, не втрачаючи багато крові. Зачекай ніч, а потім дай другу половину.$B$BТак чи інакше, тобі потрібно віднести це Лоґмару в Табір Таурахо. Судячи з того, що сказав перший, він має знати, де цей Доґран.",
    O = "Достав Настій Кен’зіґли Рядовому Лоґмару в Табір Таурахо.",
    P = "Так, що це?",
    C = "Ну, пора! Догран вимирає там, чекаючи на це.$B$BWe потрібно негайно повідомити йому про це, але більшість хрюкачів, розміщених тут, виконують місію пошуку їжі.",
},

[1512] = {
    en = "Love's Gift",
    T = "Дар кохання",
    D = "Занкайя молода і красива. Бути прив’язаною до каліки... Я не дозволю їй страждати від цієї несправедливості.$B$BЗалиш мене, $N. І дякую тобі. Я можу закінчити своє життя у славній битві, а не як бездушна оболонка.$B$BІ, будь ласка, я прошу тебе не розповідати моїй коханій про це... Я не хочу, щоб вона відчувала провину.",
    O = "Принеси Покритий Брудом Кулон Ґан’рулу Кривавоокому в Орґріммар.",
    P = "Ви повернулися. Ви готові битися з суккубом?",
    C = "Якщо ви скажете мені, що цього буде достатньо, я довіряю вам, $N. Але дозвольте мені його почистити... Незайманий і сяючий, він може бути ще більш привабливим для суккуба.",
},

[1513] = {
    en = "The Binding",
    T = "Зв’язування",
    D = "Віднеси це до кола виклику в наметі Ніру, $N. Виклич мерзенного суккуба і покажи йому свою владу. Я вірю в силу твоєї магії. Але, як завжди, будь обережним, адже гордість і надмірна впевненість погубили багатьох перспективних чорнокнижників.$B$BКоли ти переможеш його, поверни кулон мені, щоб я міг повідомити Занкайї новину.",
    O = "Використовуючи Кулон Доґрана, призови і підкори суккуба, а потім поверни Кулон Доґрана Ґан’рулу Кривавоокому в Орґріммар.",
    P = "Коли я дивлюся на суккуба, моє серце починає витати... Але в той же час я майже відчуваю відплив моєї душі, відтікає, як припливи.$B$BBe обережно, друже.",
    C = "Успіх! Переконайтеся, що я не очікував нічого меншого від свого зіркового учня.$B$BYou довів вашу цінність, і я з радістю покажу вам метод виклику вашого підкореного суккуба. Ідіть зараз, вам потрібно багато чого навчитися, і коли я побачу вас наступного разу, я сподіваюся, що ви знайшли справжню владу над своїм суккубом.$B$BLeave печаль Дограна та Занкаї для тих із нас, кому вже багато років, але пам’ятайте про це та тримайте це як захист від підступів темної сили, яку ви навчилися викликати сьогодні.",
},

[1514] = {
    en = "Corrupted Windblossom",
    T = "Зіпсована Вітроквітка",
    D = "",
    O = "",
    P = "Ви знайшли хворобливу, зіпсовану версію того, що виглядає як вітроцвіт. Ягоди, що звисають з рослини, здаються гнилими та отруйними. Він відчайдушно потребує певної уваги, якщо хочеться повернути його до нормального стану.",
    C = "Ви наносите дві рослинні мазі Кенаріону на квітку вітру. Воно відразу починає скидати зіпсовану форму, перетворюючись на живу та здорову рослину.",
},

[1515] = {
    en = "Dogran's Captivity",
    T = "Полон Доґрана",
    D = "Ти дійшов так далеко, тож якщо хочеш довести це до кінця, я не зупинятиму тебе. Але я не можу виділити тобі додаткових людей, ти будеш сам.$B$BДоґрана тримають у таборі кабанолюдей на півночі звідси. Шукай групу з двох хатин. Його добре охоронятимуть — якщо, звісно, вони ще не вбили його або він не помер від ран.$B$BУдачі.",
    O = "Достав Настій Кен’зіґли Доґрану в Степи.",
    P = "Уррррхххх...",
    C = "Неприємний на смак вариво...$B$BI зараз відчуває в собі силу, достатню, щоб відшкутильгати... Але моя нога, я втратитиму її на все життя. Моя рука теж.",
},

[1516] = {
    en = "Call of Earth",
    T = "Поклик Землі",
    D = "Настав час, молодий $C. Ти став сильним, і твій дух міцний, як земля. Шлях шамана показує, що ти вже маєш мудрість, навіть не довівши себе.$B$BЕлемент землі скеровуватиме твою долю, стане частиною тебе, якщо ти готовий. Але ти мусиш постати перед самою землею. Якщо ти готовий, ти побачиш те, що знають лише шамани.$B$BЗнайди Скверноловів на півночі і забери в них два копита. Повертайся до мене, і ми поговоримо про твоє майбутнє.",
    O = "Принеси 2 Копита Сквернолова Канаґі Землезову в Долину Випробувань.",
    P = "Терпіння — найбільша чеснота землі. Земля є свідком циклу всіх речей: гори стають пустелями; річки перетворюються на каньйони. Земля — найвпертіша й наймудріша з усіх стихій, і вона не терпить нетерпіння.$B$BThe земля манить вас зараз, бо наближається час конфлікту. Коли ти повернешся до мене успішним, тоді ти станеш набагато ближчим до одужання.$B$BOthers заздрить твоїй мудрості та ненавидітиме тебе за своє невігластво.",
    C = "Чудово. Ваш успіх свідчить про те, що ви готові.$B$BOf всі елементи, земля є основою всього. Це ваша сила, ваша витривалість і ваше терпіння. Земля захистить вас, але лише за умови належної поваги. Як і інші елементи, навіть земля може бути мінливою. Земля — це основа життя, і, дотримуючись її законів, ти здобудеш більшу мудрість. Ніколи не забувайте про секрети, якими з вами ділиться земля.$B$BI зараз створить для вас сапту, і, прийнявши її, ви зрозумієте свій шлях.",
},

[1517] = {
    en = "Call of Earth",
    T = "Поклик Землі",
    D = "Сапта — це напій, створений для зв’язку наших духів з елементами. Наповнений магією, цей напій дозволяє тим, хто має сильну волю, побачити елементи так, як ніхто інший. Твій дух буде пов’язаний з елементом, для якого створена сапта, і лише небагато шаманів знають її рецепт.$B$BСапту завжди п’ють у святому місці, і ніде більше — запам’ятай це.$B$BЗнайди Скелю Духів на південний захід звідси — вона розташована в кінці Скритої Стежки. Випий свою сапту там, і... ну, ти сам побачиш.",
    O = "Знайди Скелю Духів і випий Земляну Сапту.",
    P = "",
    C = "Ах... $N... Земля рада, що ви тут.$B$BBound разом тілом і духом ви підете вперед, знаючи, що гори — ваша сила; рівнини — ваше терпіння; і сам світ — ваша сутність.$B$BStanding перед землею смиренно — це все, що від вас вимагається, щоб ви пройшли цей обряд. Але інші не такі пасивні. Вони можуть бути хаотичними і часто жорстокими, але така природа стихій. Подвійні натури, які протистоять одна одній, ви повинні прийти до заплутаного вивчення цих речей.",
},

[1518] = {
    en = "Call of Earth",
    T = "Поклик Землі",
    D = "Візьми цей грубий кварц від мене і принеси його Канаґі Землезову як доказ нашої зустрічі. Він створить для тебе тотем, і цей камінчик буде його серцем. Хоч він і маленький, ти зрозумієш, що розмір не має значення, і що навіть найменші речі можуть пережити багатьох інших.$B$BБудь терплячим, $N. Залишайся сильним. І шукай мудрості. Це те, що вимагає земля від тебе. Зрештою, ти станеш єдиним із землею — поважай її, як вона поважатиме тебе.",
    O = "Принеси Грубий Кварц Канаґі Землезову в Долину Випробувань.",
    P = "Я хочу бути першим, хто повністю привітає вас на першому з чотирьох шляхів, які назавжди ведуть вас у вашій долі.$B$BIf у вас є камінь, який дала вам земля, я дам вам тотем, який вона обіцяла.$B$BIf ні, тоді піду з вами, поки ви не знайдете свій шлях.",
    C = "Чудово! $B$BThe тотем, який я створю для вас, — це більше, ніж символ вашого статусу серед $C — він має й інші здібності. Одним із способів використання тотема є фокус для заклинань. Ці заклинання пов’язані із землею, і в міру того, як ви здобудете все більшу й більшу мудрість, вам стане доступніше більше земних здібностей.$B$BThe тренери дізнаються, коли ви будете готові до більших знань.$B$BBut поки що візьміть цей тотем землі та сувій, щоб навчити вас вашій першій здібності.",
},

[1519] = {
    en = "Call of Earth",
    T = "Поклик Землі",
    D = "Настав час, молодий $C. Твоє тіло росте і міцніє, а твій дух витримує, як земля. Я бачу в тобі мудрість, яка вже є.$B$BЗемля скеровує наш народ, і вона говорить до нас, як говоритиме до тебе з часом. Але ти мусиш пройти випробування. Якщо ти готовий, то побачиш те, що знають лише наші.$B$BЗнайди шаманів Гострошерстих у їхній ущелині на сході і забери в них мазь, яку вони використовують у ритуалах. Повертайся до мене, лише коли матимеш достатньо для власного зілля.",
    O = "Принеси 2 Ритуальні Мазі Провидцеві Воронячому Перу в Табір Нараче.",
    P = "Земля терпляча і чекатиме на вас, доки ви не будете готові, тому що вона знає, що з часом усе руйнується та відроджується. Це цикл речей. Гори стають пустелями. Річки стають каньйонами. Земля — найвпертіша й наймудріша з усіх стихій.$B$BYou понад усе потрібно навчитися терпінню й витривалості. Земля кличе вас зараз, тому що вона відчуває, що ви готові. Вважайте це своїм переродженням, якщо вам це вдасться. Ви ніколи не зможете повернутися до невігластва потім.",
    C = "Добре, $N. Ваше повернення сюди означає, що ви справді готові до наступного кроку.$B$BOf усі елементи, земля є основою всього. Це ваша сила, ваша витривалість і ваше терпіння. Мати-Земля захистить вас, але тільки якщо ви виявите до неї належну повагу. Вона — основа життя, і, дотримуючись її законів, ти набудеш більшої мудрості. Ніколи не забувайте про секрети, якими вона з вами ділиться.$B$BI зараз створить для вас вашу сапту, і, прийнявши її, перед вами відкриється новий шлях.",
},

[1520] = {
    en = "Call of Earth",
    T = "Поклик Землі",
    D = "Сапта — це напій, створений для зв’язку наших духів з елементами. Наповнений магією, цей напій дозволяє тим, хто відкритий розумом, побачити елементи так, як їх не бачив ніхто раніше. Твій дух назавжди буде пов’язаний з елементом, для якого створена сапта, і лише небагато наших знають секрети її створення.$B$BСапту завжди п’ють у святому місці, і ніде більше.$B$BЗнайди шаманське святилище на сході звідси і випий сапту.",
    O = "Знайди Скелю Кодоеда і випий Земляну Сапту.",
    P = "",
    C = "Ах... $N... Земля рада, що ви тут.$B$BBound разом тілом і духом ви підете вперед, знаючи, що гори — ваша сила; рівнини — ваше терпіння; і сам світ — ваша сутність.$B$BStanding перед землею смиренно — це все, що від вас вимагається, щоб ви пройшли цей обряд. Але інші не такі пасивні. Вони можуть бути хаотичними і часто жорстокими, але така природа стихій. Подвійні натури, які протистоять одна одній, ви повинні прийти до заплутаного вивчення цих речей.",
},

[1521] = {
    en = "Call of Earth",
    T = "Поклик Землі",
    D = "Візьми цей грубий кварц від мене і принеси його Провидцеві Воронячому Перу як доказ нашої зустрічі. Вона створить для тебе тотем, і цей камінчик буде його серцем. Хоч він і маленький, ти зрозумієш, що розмір не має значення, і що навіть найменші речі можуть пережити гори.$B$BБудь терплячим, $N. Залишайся сильним. І шукай мудрості. Це те, що вимагає земля від тебе. Зрештою, ти станеш єдиним із землею — поважай її, як вона поважатиме тебе.",
    O = "Принеси Грубий Кварц Провидцеві Воронячому Перу в Табір Нараче.",
    P = "Вітаю, $N. Ви б не повернулися до мене, якби не виконали свого завдання. Дозвольте мені першим вітати вас на першому з чотирьох шляхів, які назавжди керуватимуть вашими подорожами.$B$BIf у вас є камінь, який дала вам земля, я дам вам тотем, який вона обіцяла. Якщо ні, то мені вас шкода. Коли ви повністю присвятили себе природним стихіям, ви відчуваєте велику гордість.",
    C = "Чудово.$B$BThe тотем, який я створю для вас, — це більше, ніж просто символ, він має й інші здібності. Одним із способів використання тотема є фокус для заклинань. Ці заклинання прив’язані до землі, і в міру того, як ви набуваєте все більшої й більшої мудрості, вам стане доступніше більше земних здібностей. Тренери, яких можна знайти по всьому Калімдору, дізнаються, коли ви будете готові до більших знань, і повідомлять вам про це, коли ви їх відвідаєте.$B$BBut поки що візьміть цей тотем землі та сувій, щоб навчити вас вашій першій здатності.",
},

[1522] = {
    en = "Call of Fire",
    T = "Поклик Вогню",
    D = "Вогонь із тобою, моне. Я бачу, що ти вже сильний у шляхах землі, і мені здається, що ти готовий поговорити з Краналом.$B$BКранал живе на північ від Перехрестя в Степах. Він сильний у шляхах елементів і може навчити тебе шляхам вогню... якщо ти вважаєш, що готовий.$B$BЙого легко знайти, тільки не заходь надто далеко — якщо зайдеш далеко, опинишся в землях нічних ельфів.",
    O = "Знайди Кранала Фісса в Степах.",
    P = "",
    C = "Хммм, Серн прислав вас до мене, чи не так?$B$BWell Тоді Серну завжди можна довіряти, тож це має означати, що ви готові взяти участь у наступній сапті--сапті вогню.$B$BI вже бачу це у ваших очах, горіння, бажання. Ви відчули смак сили, і тепер ви готові отримати більше. Терпіння, $N. Згадайте, чого навчила вас земля. Сила та руйнування прийдуть легко, але ви все одно повинні знати, коли тримати вашу руку.",
},

[1523] = {
    en = "Call of Fire",
    T = "Поклик Вогню",
    D = "Давно тебе не перевіряли, $N. Ти досі виявляв терпіння у своїх заняттях, але настав час тобі дізнатися більше. Настав час навчитися про руйнування... і хаос. Елемент вогню стане твоїм для розуміння, якщо ти готовий заплатити за це.$B$BЗнайди Кранала Фісса в Степах. Він живе в невеликій оселі на північ від Перехрестя, але будь обережним, якщо ти дістався до земель нічних ельфів, значить, ти зайшов надто далеко.",
    O = "Знайди Кранала Фісса в Степах.",
    P = "",
    C = "Хммм, Нарм прислав вас до мене, чи не так?$B$BWell Тоді Нарму завжди можна довіряти, тож це має означати, що ви готові взяти участь у наступній сапті--сапті вогню.$B$BI вже бачите це у ваших очах, горіння, бажання. Ви відчули смак сили, і тепер ви готові отримати більше. Терпіння, $N. Згадайте, чого навчила вас земля. Сила та руйнування прийдуть легко, але ви все одно повинні знати, коли тримати вашу руку.",
},

[1524] = {
    en = "Call of Fire",
    T = "Поклик Вогню",
    D = "Ти досить сильний, щоб володіти тотемом вогню, але це не означає, що ти готовий.$B$BУздовж річки Південної Люті в Дуротарі, перед Великим Морем, є прихована стежка до однієї з найвищих вершин у цих землях. Знайди шлях до вершини, і ти знайдеш одне з наших святих святилищ, яке охороняє Тельф Джулам — Святилище Сплячого Полум’я.$B$BВізьми цей смолоскип до нього — він позначить, що ти намагаєшся приборкати вогонь. Поверни його мені запаленим від жаровні в святилищі, і я подбаю, щоб тобі дали тотем вогню.",
    O = "Достав Смолоскип Сплячого Полум’я Тельфу Джуламу в Дуротарі.",
    P = "Вітання, $N. Ви опинилися в Храмі Сплячого Полум'я. Лише ті, хто достатньо обізнаний у шаманському мистецтві, коли-небудь дізнаються секрети цього місця та силу, яку воно містить. Мені шкода, що ви пройшли весь цей шлях, але тепер вас повернули назад — зрештою, подорож сюди далеко не безпечна, — але я охоронець святині й не можу дозволити будь-кому блукати тут.",
    C = "Ах, моя помилка, $N. Я прошу вибачення. Я не знав, що ти володієш Факелом. Мені приємно познайомитися з вами.$B$BMany авантюристи знаходять сюди дорогу, шукаючи втрачений скарб або обіцянку містичних істот, яких потрібно вбити, лише щоб їх відвернули від, здавалося б, порожнього храму. Але ми знаємо правду, чи не так, $N?$B$BThis святиня зберігає більший секрет від мирських членів Орди. Для нас це святе.",
},

[1525] = {
    en = "Call of Fire",
    T = "Поклик Вогню",
    D = "Але ти прийшов сюди не за уроком історії, чи не так? Ти прийшов за Вічним Полум’ям і тотемом вогню.$B$BПерший крок — створити сапту і зв’язати тебе з полум’ям.$B$BЯ можу створити вогняну сапту для тебе, якщо ти принесеш мені два предмети. Перший — вогняна смола, простий предмет, який зазвичай носять заклинателі Гострошерстих у східних Степах.$B$BДругий предмет буде небезпечнішим: мішечок із реактивами від одного з культистів Палаючого Леза. Ти можеш знайти їх у печері над ущелинами на північний схід від Бритвого Пагорба.",
    O = "Принеси 1 Вогняну Смолу і 1 Мішечок із Реактивами Тельфу Джуламу в Дуротарі.",
    P = "У мене достатньо інгредієнтів для сапти вогню, якщо ви знайдете пакет з реагентами та трохи вогняної смоли. Фанатики Палаючого Клинка носять необхідні компоненти для більшості своїх заклинань у цих мішечках, і зазвичай у них достатньо необхідних мені предметів, щоб нам не довелося довго шукати щось інше.$B$BThe сапти завжди виготовляються з інгредієнтів, тісно пов’язаних із відповідними елементами. Це полегшує нашу роботу через зв’язки чорнокнижників із вогнем.",
    C = "Це чудово підійде, $N.$B$BFire — це щось більше, ніж хаос і руйнування, пам’ятайте про це. Це також про життя та творення. Таким чином зв'язуються всі речі. Сили протистоять одна одній, але в той же час одна без іншої не може існувати. Обидва гасять одне одного, але також надають одне одному значення. Завжди пам’ятайте про це.$B$BUsing різні види магії в поєднанні одна з одною покажуть не лише справжню майстерність, але й велику мудрість.",
},

[1526] = {
    en = "Call of Fire",
    T = "Поклик Вогню",
    D = "Вогняна сапта готова. Настав час тобі зустрітися з полум’ям. Використай сапту в святилищі і вирушай на вершину гори, щоб зіткнутися з проявом там. Він не атакуватиме, поки ти не будеш готовий, але він зрозуміє, що ти можеш його бачити.$B$BЗнищ його швидко, $N, адже він лише зростатиме в силі, чим довше ти зволікатимеш. Після його поразки поклади його палаючі вуглинки в жаровню і запали смолоскип.",
    O = "Переможи Молодший Прояв Вогню і поклади Палаючу Вуглинку в жаровню на вершині Святилища Вічного Полум’я.",
    P = "Мангал становить приблизно третину вашого зросту і виглядає нормально, за винятком написів уздовж гладких металевих рейок. Метал не має ознак зносу від погодних умов, а чаша, яка стоїть у верхній частині, прохолодна на дотик.",
    C = "Біле гаряче полум’я спалахує в чаші, коли ви кладете в неї вуглинку. Ви можете відчути магічні ефекти сапти, що протікає по вашому тілу, і вогонь ритмічно танцює перед вами.$B$BYou помістіть верхню частину факела в чашу, і вона миттєво спалахне.",
},

[1527] = {
    en = "Call of Fire",
    T = "Поклик Вогню",
    D = "Міцно тримаючи смолоскип, ти відвертаєшся від жаровні і дивишся на Дуротар. Ти відчуваєш хвилювання, що тягне твій дух, коли вітер посилюється і змушує полум’я гнівно танцювати.$B$BТи вирушаєш стежкою назад до Степів у пошуках Кранала Фісса.",
    O = "Достав Смолоскип Вічного Полум’я Краналу Фіссу в Степи.",
    P = "Так, $N? Що у вас там?",
    C = "Твій дух горить яскравіше, ніж будь-який смолоскип, який я коли-небудь бачив, $N, і ти маєш пишатися цим.$B$BIf ти продовжуй цей шлях, стихії будуть твоїми, а наші брати шукатимуть у тебе керівництва та мудрості. Дозвольте першому привітати вас і подарувати ваш новий тотем.",
},

[1528] = {
    en = "Call of Water",
    T = "Поклик Води",
    D = "Вода в твоєму майбутньому, моне. Я бачу, що ти вже сильний у шляхах вогню, і мені здається, що ти готовий поговорити з Іслен.$B$BІслен живе вздовж узбережжя Степів. Якщо вирушити на південь уздовж річки Південної Люті, ти не пропустиш її — шукай велику акулу! Вона сильна в шляхах елементів і може навчити тебе шляхам води... якщо ти вважаєш, що готовий.$B$BЇї легко знайти, тільки не заходь надто далеко на південь — вона трохи за Ратчетом.",
    O = "Знайди Іслен Водовидицю в Степах.",
    P = "",
    C = "Вітер швидко наближається до вас з-за горизонту; тверда земля під ногами твоїми; і ваш дух уже зігрітий вогнем — я б сказав, що вам пора дізнатися про чистоту води.$B$BYour шлях привів вас так далеко, і ваш дух дасть вам сили йти далі. Але перший крок зробити вам.",
},

[1529] = {
    en = "Call of Water",
    T = "Поклик Води",
    D = "Давно тебе не перевіряли, $N. Ти досі виявляв терпіння у своїх заняттях, але настав час тобі дізнатися більше. Настав час навчитися про чистоту води.$B$BЗнайди Іслен Водовидицю в Степах. Вона живе на східному узбережжі, на південь від річки Південної Люті і Ратчета. Ти знайдеш її там у її рибальській хатині. Удачі тобі, $N.",
    O = "Знайди Іслен Водовидицю в Степах.",
    P = "",
    C = "Вітер швидко наближається до вас з-за горизонту; тверда земля під ногами твоїми; і ваш дух уже зігрітий вогнем — я б сказав, що вам пора дізнатися про чистоту води.$B$BYour шлях привів вас так далеко, і ваш дух дасть вам сили йти далі. Але перший крок зробити вам.",
},

[1530] = {
    en = "Call of Water",
    T = "Поклик Води",
    D = "Якщо є одна річ, яку ти мусиш знати про воду, то це те, що вода означає відродження.$B$BЇї сила тече, розмиває і очищає все на своєму шляху. Ти знайдеш її здатність до зцілення і відновлення неперевершеною, але лише коли вона чиста.$B$BКоли ти зрозумієш, що забруднена вода може знищити все, до чого торкається, ти оціниш, наскільки важливим є цей ресурс.$B$BЯкщо хочеш отримати водяну сапту, знайди Брайн глибоко в Південних Степах. Її дім постійно атакують кабанолюди там.",
    O = "Знайди Брайн у Південних Степах.",
    P = "",
    C = "Так?$B$BMmm. У мене таке відчуття, що я знаю, про що ти збираєшся мене спитати: чому хтось може жити тут, у найглибшій частині Степлі, навколо загроза квілборів і жодного захисту? Що ж, у кожного з нас є свої причини, щоб виправдати, чому ми діємо так, як ми робимо. Справжнє запитання полягає в тому, що приводить скромного $R до найглибших куточків Степлі, щоб поговорити з жінкою, яка, очевидно, не піклується про власне благополуччя?$B$BI Готовий посперечатися, що ми обидва знаємо відповідь на це питання.",
},

[1531] = {
    en = "Call of Air",
    T = "Поклик Повітря",
    D = "Ти робиш успіхи, моне. Ти готовий довести, що гідний тотема повітря, але спершу тобі потрібно знайти Прейт Хмаровидицю в Тисячі Голок. Вона готова розповісти тобі, як отримати тотем повітря, якщо ти поставишся до неї з достатньою повагою.$B$BВирушай на південь через Степи, а коли дістанешся до Тисячі Голок, іди на схід. Ти знайдеш її в укритті разом із її хлопцем — ха-ха, не кажи їй, що я її дражнив, вона цього не любить.",
    O = "Знайди Прейт Хмаровидицю в Тисячі Голок.",
    P = "",
    C = "На даний момент. Я дам тобі те, що тобі потрібно, щоб зосередити свої чари та закликати духів повітря. Візьміть цей тотем, а коли будете готові, тренуйтеся зі мною ще трохи.",
},

[1532] = {
    en = "Call of Air",
    T = "Поклик Повітря",
    D = "Вітри Калімдору поспішають зустріти тебе, і ти будеш серед наймогутніших наших $Gбратів:сестер;. Я пишаюся, що ти дійшов так далеко і маєш таке багатообіцяюче майбутнє.$B$BЕлемент повітря важко контролювати, але я вірю, що твої навички подолають будь-які перешкоди, які постануть перед тобою.$B$BВирушай на самий південь Степів і увійди до Тисячі Голок. Там, далеко на сході, ти знайдеш Прейт Хмаровидицю. Вона навчить тебе більшого.",
    O = "Знайди Прейт Хмаровидицю в Тисячі Голок.",
    P = "",
    C = "На даний момент. Я дам тобі те, що тобі потрібно, щоб зосередити свої чари та закликати духів повітря. Візьміть цей тотем, а коли будете готові, тренуйтеся зі мною ще трохи.",
},

[1534] = {
    en = "Call of Water",
    T = "Поклик Води",
    D = "Візьми цей бурдюк і вирушай глибоко в пишний ліс, який нічні ельфи називають Ясенедолом. Він далеко на північ від Степів.$B$BЯк тільки увійдеш до лісу, іди на захід. Уздовж гір, що розділяють Кам’яні Кігті та Ясенедол, і за озером Містраль, ти знайдеш святе місце: Руїни Зоряного Пилу. У центрі озера є невеликий фонтан.$B$BПринеси мені зразок води з цього фонтана. Це буде останній компонент, який тобі знадобиться, перш ніж я відправлю тебе назад до Іслен.",
    O = "Наповни Порожній Синій Бурдюк у Руїнах Зоряного Пилу в Ясенедолі і поверни його Брайн у Степи.",
    P = "У тебе вже є вода, $N? Казки кажуть, що руїни були захищені великими створіннями природи, які не дбають про відвідувачів, але це можуть бути міфи, щоб відлякати ворогів нічних ельфів.$B$BRegardless, будьте обережні.",
    C = "Чудово, $N. Зібравши всі три зразки, я можу створити для вас флакон із найчистішою водою, яку знайде будь-яка жива істота. Його буде використано на наступних етапах вашого обряду переходу.$B$BI Я радий зарахувати вас до нашого роду, $N. Ви пишаєтеся $C, і я з нетерпінням чекаю почути про ваші подвиги в майбутньому.",
},

[1535] = {
    en = "Call of Water",
    T = "Поклик Води",
    D = "Щоб зрозуміти і отримати сапту від мене, ти мусиш шукати лише найчистіші форми води. Збираючи зразки для мене, звертай увагу на своє оточення. Помічай істот, які залежать від води, які її захищають. Подивися, як вона впливає на ліси і пустелі. Спостерігай, як речовина, що підтримує життя, змушує істот забирати життя.$B$BМи почнемо з простого завдання: унизу біля моєї хатини є ставок із дорогоцінною рідиною. Наповни цим бурдюк і повернися до мене.",
    O = "Наповни Порожній Коричневий Бурдюк у водоймі під хатиною Брайн і поверни його їй у Степи.",
    P = "Я майже готовий відправити вас на інші ваші завдання. Ви вже наповнили шкіру?$B$BI знаєте, яким захистом може бути quilboar. Навіть таке маленьке джерело води є для них величезним багатством. Вони влаштовують великі бенкети, коли навіть найменший дощ приходить у Степлі. Вода є священною для їхнього роду, тому що її дуже мало. Ви розумієте?",
    C = "Я думав, що може статися кровопролиття, якщо ти спробуєш взяти воду з басейну. Шкода, що кілбоар не розуміє, що все живе пов’язане разом; що їхня жадібність лише увічнює біль і страждання їхнього народу. Як багато вони могли б досягти, якби відклали свої розбіжності вбік і їхні клани об’єдналися.$B$BAgain, на жаль, але, швидше за все, це благо для інших рас Степлі.",
},

[1536] = {
    en = "Call of Water",
    T = "Поклик Води",
    D = "Давно я подорожував із кількома супутниками до Передгір’їв Гіллсбрада. Ми захищалися від наполегливих людей, які там живуть, і опинилися в невеликому містечку, яке захопили Покинуті: Тарренський Млин.$B$BТам я знайшов дивну річ: у центрі міста був невеликий колодязь із чистою джерельною водою. Я не впевнений, що заражені жителі міста навіть усвідомлюють його цінність — це маленький святий залишок у морі нечистоти.$B$BПринеси мені зразок тієї води в цьому бурдюку.",
    O = "Наповни Порожній Червоний Бурдюк у колодязі в Тарренському Млині і поверни його Брайн у Степи.",
    P = "Колодязь, який залишається чистим у місті, нагадує мені історії, які мені розповідали, коли я був молодшим, $N. Навіть у часи великого болю та горя можна знайти шматочок надії, маленький символ, щоб об’єднатися. Народ орків бачить Тралла таким чином. Він вижив, незважаючи на великі труднощі, і повстав, щоб вести наш народ своєю силою та прикладом.$B$BI Я не впевнений, що жоден орк постраждав так сильно, як він, але водночас я не впевнений, що жоден орк є таким сильним, як він.",
    C = "Це добре, $N. Ви віддані справі та маєте здатність шукати те, що потрібно.$B$BOne більше зразків — це все, що мені потрібно, щоб створити реагент, необхідний для вашої сапти. Айлен теж буде задоволена.",
},

[1558] = {
