},

[1598] = {
    en = "The Stolen Tome",
    T = "Вкрадений том",
    D = "Ти тут! $N, так?$B$BСподіваюся, ти впевнений у тому, що хочеш стати чорнокнижником, бо якщо ти не зможеш себе захистити, тебе, ймовірно, затягне під воду.$B$BМені доручили тебе навчати, але спершу я мушу переконатися, що ти достатньо сильний.$B$BБув новачок, який навчався в Абатстві і втік, щоб приєднатися до Братства Дефіасів. Чому мене це хвилює? Ну, він вкрав кілька важливих книг.$B$BОдна з них — книга, яку я давно хотів мати, «Сили Порожнечі». Вкради її для мене, вони ховають її в своєму наметі у Виноградниках.",
    O = "Здобудь «Сили Порожнечі» для Друсілли Ла Салль.",
    P = "Це було надто помітно для мене, щоб вкрасти книгу самому. Яке щастя, що один із їхніх власних пирогів зробив за мене брудну роботу.",
    C = "Чудово... Я так і не зміг отримати доступ до цього тексту, він зберігався в захищеному крилі бібліотеки, яке для мене могло б виглядати підозрілим, якби тинявся.$B$BWell, ти добре впорався, отримавши це, і я переконаний, що ти, ймовірно, впораєшся зі своїм власним бісом, тому немає причин не показати тобі, як його викликати.",
},

[1599] = {
    en = "Begi$b$bings",
    T = "Початки",
    D = "Ти, мабуть, той новий чорнокнижник, про якого всі шепочуться. Напевно, хтось узяв тебе під своє крило, якщо вони попросили мене відірватися від моїх досліджень, щоб почати твоє навчання.$B$BНе хвилюйся, я не триматиму це проти тебе.$B$BНайпростіше з заклинань виклику, яке ти вивчиш, — це виклик імпа. Але перш ніж я тобі це передам, ти мусиш довести, що маєш необхідні магічні та фізичні здібності.$B$BПринеси мені три пір’яні амулети від новачків Морозоманів із печери на південний захід.",
    O = "Принеси 3 Пір’яні Амулети Аламару Ґрімму в Наковальні.",
    P = "Ці амулети з пір’я, які носять новачки, мають якусь магічну силу. Буде цікаво їх дослідити. Я б не очікував такого від тролів.",
    C = "Дуже добре, дуже добре! Ти добре впорався, $N. Можливо, врешті-решт інтерес, який до вас виявляють, є заслуженим.$B$BThat вирішуватимуть інші — припустімо, що ваш чорт не здолає вас і не зруйнує вашу кар’єру в зародку. Наразі я задоволений тим, що ти, ймовірно, переживеш свої перші кілька місяців як $C.$B$BA слово про чортика, $N. Як знає $R, нехай його розмір не вводить вас в оману, його магія може бути дуже небезпечною.",
},

[1618] = {
    en = "Gearing Redridge",
    T = "Спорядження Червоногір’я",
    D = "Ми, дворфи, не єдині, хто бореться. Наші союзники-люди також мають повно роботи!$B$BЧервоногір’я періодично зазнає атак від орків Чорнокаменя, і їхні запаси спорядження завжди на межі. Якщо ти допоможеш їм, я впевнений, що місцевий коваль, Вернер Осґуд, навчить тебе кільком хитрощам.",
    O = "Тормус Глибоковогонь хоче, щоб ти приніс 4 Рунні Мідні Пояси і 4 Важкі Мідні Молоти Вернеру Осґуду в Червоногір’ї.",
    P = "Сподіваюся, ви тут із хорошими новинами зі Стальгорну. Тому що я на межі розуму!",
    C = "Дякую, $N. This will help me out tremendously. Оскільки орки Чорної скелі атакують із фортеці Стоунвотч, а гноли Красногорця ховаються в передгір’ях на півночі, я завжди лагоджу броню та створюю нову зброю для наших військ.$B$BThe запаси, які ви привезли, дадуть мені хвилину спокою. У мене буде достатньо часу, щоб навчити тебе чогось...",
},

[1638] = {
    en = "A Warrior's Training",
    T = "Тренування воїна",
    D = "Ти довів, що ти вправний воїн, $N. Але ти ще молодий і маєш багато чому навчитися.$B$BПоговори з Гаррі Барлґардом — він зазвичай у таверні «Свиня і Свисток» у Старому Місті Штормовію. Гаррі — старий ветеран і хороший учитель. Він може показати тобі кілька рухів, які допоможуть тобі довше залишатися живим.",
    O = "Поговори з Гаррі Барлґардом.",
    P = "",
    C = "О хо! Випий зі мною, $N. Зовні ти виглядаєш жорстким, але давай перевіримо, чи зможе твій інтуїція витримати кілька кухлів найсильнішого Pig and Whistle!!$B$BOr... ти був тут на уроці?",
},

[1639] = {
    en = "Bartleby the Drunk",
    T = "Бартлебі П’яниця",
    D = "Так, я можу тебе навчити. Але спершу я хочу побачити, які в тебе вже є навички.$B$BБачиш того п’яницю там, у кінці бару? Бартлебі? Я хочу, щоб ти забрав у нього його кухоль.$B$BХа, і якщо ти знаєш Бартлебі, то знаєш, що він просто так його не віддасть.",
    O = "Поговори з Бартлебі.",
    P = "",
    C = "Привіт, красуня $gboy:дівчинка;! Що таке цнотлива штука, як ти, у «Свині та свистку»? Будьте обережні, а то можете зламати ніготь...",
},

[1640] = {
    en = "Beat Bartleby",
    T = "Побити Бартлебі",
    D = "Ти хочеш що?? Ти божевільний!$B$BЄдиний спосіб, як ти отримаєш цей кухоль, — це якщо вирвеш його з моїх холодних, мертвих пальців...",
    O = "Переможи Бартлебі, а потім поговори з ним.",
    P = "Перемагати Бартлбі",
    C = "Ти набагато сильніший, ніж виглядаєш!",
},

[1641] = {
    en = "The Tome of Divinity",
    T = "Том Божественності",
    D = "",
    O = "",
    P = "",
    C = "Тут, у Штормовії, я відповідаю за спрямування паладінів на шлях до більшої чесноти, оскільки вони присвячують себе Світлу та захищають Азерот від Бича та інших загроз.$B$BThe Настав час, щоб ви зробили свій перший крок до того, щоб бути справді доброчесними. Якщо ви приймете це, я дам вам Книгу Божественності. Вивчаючи його, ви дізнаєтеся дещо про Світло та про те, що від вас очікується. Якщо ви це розумієте і здатні, то вам вдасться досягти більших здібностей.",
},

[1642] = {
    en = "The Tome of Divinity",
    T = "Том Божественності",
    D = "У всьому паладин мусить відображати Світло, яке доповнює нашу силу. Прагнути бути божественним для нашого роду не означає прагнути до божества — ми прагнемо бути добрими в усіх діях.$B$BХоча в ці суворі часи нас закликають знищувати зло, ти завжди мусиш пам’ятати, що допомога іншим — це те, що дійсно вирізняє тебе серед громадян Азероту. Співчуття, терпіння, хоробрість — ці речі значать для паладина не менше, ніж сила в бою.$B$BДобре це запам’ятай і ніколи не забувай.",
    O = "Поговори з Дуторіаном Раллом у Штормовії.",
    P = "",
    C = "Знову привіт, $N. Як проходять ваші дослідження Тома Божественності?$B$BThen Ви повинні бути готові до випробування. У всьому місті і на наших землях завжди є завдання, які потрібно виконати; прояви співчуття та розуміння; люди, які потребують допомоги; істот, яких потрібно вбивати.$B$BBy, доводячи, що ви маєте терпіння, щоб допомагати іншим, особливо тим, кому пощастило менше, ви доводите, що ви слуга Світла та здорового розуму.",
},

[1643] = {
    en = "The Tome of Divinity",
    T = "Том Божественності",
    D = "Твоє завдання, $N, — знайти когось у Штормовії, хто потребує допомоги. Когось із чистим серцем і мотивами. Можливо, того, хто допомагає іншим. Можливо, того, кому потрібен провідник. Хай там як, ця людина мусить мати благородні наміри і покладатися на твою доброту.$B$BЗроби це і повернися до мене, коли закінчиш. Тоді ми поговоримо більше про твій шлях і що означає бути паладином Світла.",
    O = "Знайди Стефані Тернер у Торговому районі Штормовію.",
    P = "",
    C = "О, привіт, любов. Як проходять ваші пригоди? О, я дуже радий чути, що у вас усе добре.$B$BOh, я? Дякую, що запитали. З огляду на все, у мене все добре.$B$BThe Збільшення кількості торговців зменшило кількість шкіри та тканини, з якими люди готові розлучитися, тому шити одяг для дітей у притулку було важче, але ми впораємося. Під ",
},

[1644] = {
    en = "The Tome of Divinity",
    T = "Том Божественності",
    D = "Хай благословенні будуть їхні серця, більшість із них не мають сімей через атаки Скари за останнє десятиліття.$B$BМій чоловік Джон збирає матеріали, щоб я могла пошити сорочки і штани для дітей, але я навіть не мала часу це зробити. Я була занадто зайнята тим, щоб забезпечити їм їжу і дах над головою.$B$BЩо? Ти готовий допомогти? О, хвала Світлу, і дякую тобі, $N.$B$BЯкби ти міг принести мені трохи лляної тканини, щоб я могла пошити одяг для дітей, це дуже б мені допомогло.",
    O = "Принеси 10 Лляних Тканин Стефані Тернер у Штормовій.",
    P = "Я сподіваюся, що моєму Джону пощастить більше в Стальгорні. Йому так не подобаються його поїздки туди, тому що вони залишають дітей і мене самих, але він знає, що це потрібно робити. Він такий добрий.$B$BSome роки були легшими, ніж інші, але цей був набагато суворішим. Це майже так, наче щось у повітрі сигналізує про величезні зміни. Хто знає?",
    C = "Дякую, $N, дуже дякую! $B$BThe діти будуть дуже задоволені, а ти заощадив мені стільки часу. Тепер я зможу зосередитися на інших потребах дітей, і, сподіваюся, мій Джон зможе повернутися додому раніше, ніж ми думали.$B$BThank знову ти, $N. Я знав, що можу покластися на милосердя інших. Світло з тобою.",
},

[1645] = {
    en = "The Tome of Divinity",
    T = "Том Божественності",
    D = "",
    O = "",
    P = "",
    C = "Тут, у Стальгорні, я відповідаю за те, щоб паладіни вийшли на шлях до більшої чесноти, оскільки вони присвячують себе Світлу й захищають Азерот від Бича та інших загроз.$B$BThe Настав час, щоб ви зробили свій перший крок до того, щоб бути справді доброчесними. Якщо ви приймете це, я дам вам Книгу Божественності. Вивчаючи його, ви дізнаєтеся дещо про Світло та про те, що від вас очікується. Якщо ви це розумієте і здатні, то вам вдасться досягти більших здібностей.",
},

[1646] = {
    en = "The Tome of Divinity",
    T = "Том Божественності",
    D = "У всьому паладин мусить відображати Світло, яке доповнює нашу силу. Прагнути бути божественним для нашого роду не означає прагнути до божества — ми прагнемо бути добрими в усіх діях.$B$BХоча в ці суворі часи нас закликають знищувати зло, ти завжди мусиш пам’ятати, що допомога іншим — це те, що дійсно вирізняє тебе серед громадян Азероту. Співчуття, терпіння, хоробрість — ці речі значать для паладина не менше, ніж сила в бою.$B$BДобре це запам’ятай і ніколи не забувай.",
    O = "Поговори з Тізою Бойовою Кузнею в Залізогарті.",
