[1667] = {
    en = "Dead-tooth Jack",
    T = "Мертвозубий Джек",
    D = "Берлґард послав тебе, чи не так? Так, у мене є запасна зброя, але спочатку в мене для тебе завдання...$B$BКолись давно лиходій із Дефіасів, Мертвозубий Джек, обдурив мене. Було темно, він був одягнений у накидку Штормовію, і я подумав, що це маршал Даґан. Він сказав, що йому потрібен мій старий значок маршала Штормовію, і я віддав його... а потім він розсміявся і втік, перш ніж я встиг його спіймати!$B$BПоверни мій значок! Мертвозубий Джек, мабуть, сховав його у своєму таборі на півдні.",
    O = "Дістаньте Значок Гаґґарда з табору Мертвозубого Джека і поверніться до маршала Гаґґарда.",
    P = "У вас є мій значок? Я не хочу думати про те, яке лихо міг би спричинити Мертвозубий Джек.",
    C = "Чудово, ви знайшли це! Я боявся, що він зник назавжди, використаний Defias, щоб видати себе за чиновника Штормовію. Ну, тепер цього не станеться, завдяки вам.$B$BHere це зброя, яку я використовував, коли був маршалом. Я підтримував їх у чудовій формі - вибирайте!",
},

[1678] = {
    en = "Vejrek",
    T = "Вейрек",
    D = "Якщо хочеш піднятися в лавах воїнів, то мусиш бути міцним. Я можу навчити тебе нових прийомів, але спочатку доведи, що ти можеш упоратися з справжніми ворогами.$B$BВейрек — найсильніший троль, якого ти знайдеш у цих краях, і саме його тобі треба перемогти. У нього є хатина в передгір’ях на південь від Твердині Морозоманів.$B$BПринеси мені голову Вейрека, і я знатиму, що ти маєш хист.",
    O = "Принесіть голову Вейрека до Мурена Штормспайка в Залізогарті.",
    P = "Ви були в хатині Вейрека, $N? Це той сморід тролів, який я відчуваю на тобі?",
    C = "Вейрек точно був потворний, еге? Чудово, $N! У вас є те, що потрібно, а тепер давайте розпочнемо ваш урок... $B$BYou може цього не знати, але сильний захист дуже важливий для $C. Це дає йому змогу протистояти ворогам, які вразили інших, і це те, що потрібно вашим союзникам.",
},

[1679] = {
    en = "Muren Stormpike",
    T = "Мурен Штормспайк",
    D = "Привіт, воїне! Ти показуєш великі здібності, але тобі ще треба багато чому навчитися, і Мурен Штормспайк — саме той гном, який може тебе навчити.$B$BТи знайдеш Мурена в Залі Зброї у Військовому Крилі Залізогарта. Поговори з ним, коли будеш готовий дізнатися, що означає бути воїном.",
