[1683] = {
    en = "Vorlus Vilehoof",
    T = "Ворлус Мерзокопит",
    D = "Перш ніж я зможу тебе навчити, ти мусиш показати мені свою рішучість.$B$BСатир Ворлус Мерзо копит знайшов один із наших віддалених місячних колодязів на південний схід від Бан’етільського Куреня. Тепер він плескається в ньому, оскверняючи чисті води своєю гидотою.$B$BЗнайди Ворлуса біля місячного колодязя і знищ його. Принеси мені його ріг як доказ, і я почну твоє поглиблене навчання воїна.$B$BШлях до місячного колодязя добре прихований, $N, але залишайся зосередженим і пильним, і ти його знайдеш.",
    O = "Принесіть Ріг Ворлуса до Еланарії в Дарнасі.",
    P = "У вас є ріг, $N? Чи наша місячна криниця вільна від демона Ворлуса?",
    C = "Молодець, $N. Приємно знати, що Ворлус переможений, а наша місячна криниця очищена, і приємно бачити молодих воїнів, які прагнуть уберегти наш улюблений Тельдрассил від корупції.$B$BNow дозвольте нам розпочати ваше навчання...",
},

[1684] = {
