    en = "The Rethban Gauntlet",
    T = "Ретбанська Рукавиця",
    D = "Моє випробування називається Ретбанською Рукавицею. Щоб пройти його, тобі лише потрібно увійти до Ретбанських Печер, дістатися до першого розгалуження, а потім повернутися сюди. Легко! Але є кілька нюансів...$B$BТи мусиш повернутися протягом години.$B$BНа твоєму шляху буде купа гнолів Червоногір’я.$B$BПеред початком тобі потрібно випити ковток нашого фірмового напою Ячмінославів: Пекучий Ячмінослав!$B$BТо що скажеш? Ретбанські Печери в передгір’ях на північ від Озерограду. Готовий пройти Ретбанську Рукавицю?",
    O = "Увійдіть до Ретбанських Печер, дійдіть до першого розгалуження і поверніться до Йоруса Ячмінослава в межах відведеного часу.$B$BВи не повинні померти і відпустити свій дух.",
    P = "Увійдіть до печер Ретбан",
    C = "Ви це зробили! молодець! Тричі ура за $N!",
},

[1700] = {
    en = "Grimand Elmore",
    T = "Ґріманд Ельмор",
    D = "Я зробив копію своїх нотаток про техніки, які я вивчив, створюючи твої обладунки, і мені потрібно, щоб їх віднесли до Ґріманда Ельмора. Він тут, у Гномському Районі, в крамниці зброї.$B$BІ пригнися, коли передаватимеш їх йому. Він дуже пишається своїми навичками і не зрадіє ідеї навчитися чогось від мене...",
    O = "Віднесіть Нотатки Фурена до Ґріманда Ельмора.",
    P = "Привіт, і добре познайомилися. Чим я можу бути вам корисний?",
    C = "Фурен написав це? Як він сміє! Та я навчив його всього, що він знає! Думка про те, що він міг би мене чогось навчити, це обурливо! Обурливо!$B$BHm... але в його нотатках є щось, що я хотів би спробувати...",
},

[1701] = {
    en = "Fire Hardened Mail",
    T = "Загартована Вогнем Кольчуга",
    D = "Отже, я дав тобі гарний щит, але ми не мусимо на цьому зупинятися. Я знаю секрети створення надзвичайно міцних кольчужних обладунків. Це непросто і потребує дуже рідкісних матеріалів, але якщо ти готовий узятися за цю роботу, я зроблю для тебе один елемент.$B$BЩо скажеш, $N? Якщо ти готовий до виклику, я дам тобі список того, що потрібно зібрати і де це знайти.",
    O = "Зберіть матеріали, які потрібні Фурену Довгобороду, і принесіть їх йому в Штормовій.",
    P = "Як проходить полювання на сміття, $N? У вас є матеріали?",
    C = "Ви все отримали? Дивовижно! Я боявся, що ці химери вас точно з’їдять!$B$BWell Давайте почнемо з тією бронею...",
},

[1702] = {
    en = "The Shieldsmith",
    T = "Майстер Щитів",
    D = "Ти дійсно показав, на що здатний, коли пройшов Ретбанську Рукавицю, $N. І я дотримую свого слова. Я дам тобі обіцяну нагороду...$B$BТільки вона в Штормовії.$B$BПоговори з моїм другом, Фуреном Довгобородом, у Гномському Районі Штормовію. Він найкращий майстер щитів, якого ти коли-небудь зустрінеш, і він мені винен велику послугу.$B$BОсь, віднеси Фурену цю бочку Пекучого Ячмінослава і попроси в нього щит. Він дасть тобі гарний.",
    O = "Віднесіть Бочку Пекучого Ячмінослава до Фурена Довгоборода.",
    P = "Привіт! Сухі часи, вам не здається?",
