},

[1703] = {
    en = "Mathiel",
    T = "Матіель",
    D = "Я зробив копію своїх нотаток про техніки, які я вивчив, створюючи твої обладунки, і мені потрібно, щоб хтось відніс їх ковалю Матіелю. Він живе в Дарнасі, що досить далеко, але я впевнений, що він буде дуже вдячний дізнатися про мої відкриття.",
    O = "Віднесіть Нотатки Фурена до Матіеля.",
    P = "Я вітаю вас, $C.",
    C = "Це цікаво, справді дуже цікаво. Мій колега-гном Фурен зробив грандіозне відкриття!$B$BThank ти, $N. Для мене буде честю застосувати його нові техніки у своїх роботах.",
},

[1704] = {
