},

[1718] = {
    en = "The Islander",
    T = "Острів’янин",
    D = "Твоя слава як воїна зростає, $N. Тепер час перевірити себе проти своїх побратимів і дізнатися, на що ти здатний.$B$BЄ острів біля узбережжя Степів, на південь від Кабестана. Його називають Островом Бійки, і це місце, де зустрічаються воїни.$B$BЗустрічаються і б’ються.$B$BПоговори з головним воїном Острова Бійки, Кланноком Маклеодом. Якщо він визнає тебе гідним, то Кланнок поведе тебе далі шляхом воїна.$B$BЩоб дістатися до Острова Бійки, шукай мілину вздовж Торговельного Узбережжя.",
    O = "Поговоріть із Кланноком Маклеодом.",
    P = "",
    C = "Привіт, $N. Приємно бачити, що ви добралися до острова Фрей. Сподіваюся, вам це сподобається...",
},

[1719] = {
    en = "The Affray",
    T = "Бійка",
    D = "Якщо хочеш навчатися в мене, то спочатку мусиш пройти Бійку. Це виклик, який ми на Острові Бійки любимо кидати воїнам, що вважають себе крутими, і якщо ти пройдеш це випробування, я знатиму, що ти справді такий.$B$BЩоб почати, зайди в середину того натовпу он там і стань на ґрати. Це дасть знати Твіґґі Плоскоголову, що ти готовий, і він надішле проти тебе суперників.$B$BПереможи всіх суперників, і він викличе Великого Вілла. Убий Великого Вілла і повернися до мене в межах відведеного часу.",
    O = "Убийте Великого Вілла, а потім поговоріть із Кланноком Маклеодом на Острові Бійки.",
    P = "Стопіть на решітку, щоб почати Сварку",
    C = "Молодець, $N. Ви пройшли The Affray!$B$BYou — гідний воїн, і я маю честь навчити вас...",
},

[1738] = {
    en = "Heartswood",
    T = "Серцедерево",
    D = "Готуючись до твого приходу, я використав свій дар ясновидіння, щоб зазирнути в світ і крізь тумани часу. Я знайшов те, що ти шукаєш.$b$bПід час Війни Стародавніх двоє закоханих загинули разом у битві. Там, де вони зробили свій останній подих, виросло дерево, відоме як серцедерево, символ їхнього вічного кохання.$b$bЦього має бути достатньо, щоб спокусити суккуба. Ти знайдеш його в руїнах Орділь’Арану в північно-західній частині лісу Ясенедолу.",
    O = "Дістаньте Серцедерево з Ясенедолу і принесіть його до Ґакіна Темнопряда в Магічний Квартал Штормовію.",
    P = "Ваш пошук був успішним, $N?",
    C = "Так, я можу сказати, що це чудово підійде, дозвольте мені трохи попрацювати з ним... $B$BTakar винахідливий хлопець, щоб мати поруч, чи не так? Якби я міг переконати його повернутися до цивілізації.",
},

[1739] = {
    en = "The Binding",
    T = "Скуття",
    D = "Використовуючи ядро серцедерева, ти зможеш використати заклинання на колі виклику в склепі внизу, щоб відкрити портал для проходу суккуба.$b$bБудь обережний, $n, суккуби підкоряли навіть найсильніші розуми.$b$bКоли ти переможеш його і повернеш у порожнечу, повертайся до мене, і я покажу тобі, як його викликати і контролювати.",
    O = "Використовуйте Ядро Серцедерева, щоб викликати і підкорити суккуба, а потім поверніть Ядро Серцедерева до Ґакіна Темнопряда в «Зарубаний Ягнець».",
    P = "Іноді я думаю, чи Сурена не був замаскованим суккубом, посланим спотворити та спотворити мій розум... Ха! Мені здається, я віддаю їй занадто багато довіри.",
    C = "Молодець, молодець, $N. Я бачу, що ми зробили правильно, вирішивши навчити вас. Ваша продуктивність точно не розчарує.$B$BI Не соромтеся показати вам, як керувати своїм щойно пов’язаним суккубом. Уважно спостерігайте.",
},

[1740] = {
    en = "The Orb of Soran'ruk",
    T = "Куля Соран’рука",
    D = "Коли демони Легіону втрачають прихильність, їхні душі ув’язнюються в кулях і передаються їхнім магам і чорнокнижникам.$b$bБагато з них носили їхні слуги в Азероті. Навіть уламки все ще мають силу демонів, ув’язнених усередині.$b$bКуля Соран’рука була розбита на дві частини, одна з них була ще більше роздроблена і використовується адептами Молота Сутіні в Чорноглибних Нетрях. Інша, більша частина, потрапила до чарівника в Твердині Тіней. Знайди їх, і я зможу відновити кулю.",
    O = "Знайдіть 3 Уламки Соран’рука і 1 Великий Уламок Соран’рука і поверніть їх до Доана Кархана в Степах.",
    P = "Мені знадобилося багато років, щоб зібрати шматки кулі Зарґейна, але вона мені добре послужила, оскільки я впевнений, що куля Соран'рука послужить і тобі.",
    C = "Так... Сфера не була сильно фрагментована, і майже всі частини тут. Відтворити їх, зробити Соран'рук знову цілим — це просто.$B$BI присвятив своє життя вивченню сфер Палаючого Легіону та їх відтворенню. Ви зробили мені послугу, зібравши ці фрагменти для вивчення, і я поверну вам їх — повністю реконструйовані — у формі, яку ви виберете.",
},

[1758] = {
    en = "Tome of the Cabal",
    T = "Фоліант Кабали",
    D = "Щоб викликати пекельного мисливця для твого випробування, простого кола виклику буде недостатньо.$b$bЯ і мої троє адептів допоможемо створити магічні кола. Тобі потрібна копія «Фоліанта Кабали», яка давно для нас загублена. Її написала перша група чорнокнижників, що викликали пекельного мисливця без сторонньої допомоги.$b$bМожливо, Кром Міцнорук зможе тобі допомогти. Останнім часом він бродячий чорнокнижник, проводить свої дні, накопичуючи стародавні тексти і ховаючись у бібліотеці Залізогарта.",
    O = "Поговоріть із Кромом Міцноруком у Залізогарті.",
    P = "",
    C = "Том Кабала? Хм... звучить знайомо. Але я ніколи раніше не бачив його тут - і, повірте мені, я пам'ятаю кожну прочитану книгу. $B$BHmm... Ах, так!$B$BI бачили посилання на це в бібліотечних книгах каталогізації.",
},

[1778] = {
    en = "The Tome of Divinity",
    T = "Фоліант Божественності",
    D = "Я планую скоро повернутися додому. Сподіваюся, Стефані в Штормовії все добре. Не можу дочекатися, коли знову її побачу. До наступної зустрічі, $c.",
    O = "Поговоріть із Тізою Бойовою Кузнею в Залізогарті.",
    P = "",
    C = "Отже, ти так швидко повернувся, га? І чого, на мою думку, ви досягли за час, проведений поза межами міста?$B$BWere Ви можете допомогти благородній справі? Можливо, ви дізналися цінність благодійності або щось більше про свої зобов’язання перед громадянами Азероту. Скажи мені, кому ти допоміг і як.... Вражаюче, $N, це справді дії того, хто йде за Світлом.$B$BSuch жертва завжди буде винагороджена вчасно.",
},

[1779] = {
    en = "The Tome of Divinity",
    T = "Фоліант Божественності",
    D = "Я хочу, щоб ти взяв це, $N. Це називається Символ Життя.$B$BТи довів свою милосердність і терплячість, а тепер я хочу, щоб ти показав, наскільки вправним ти став у бою і силі.$B$BМій чоловік Муйредон нещодавно повернувся після сутички з Темнозалізними гномами, і ледь залишився живим — він там, його рани зцілює один із наших жерців.$B$BВізьми Символ і поговори з ним. Якщо ти зможеш допомогти йому, ми скоро знову поговоримо. Нехай Світло осяє тебе.",
    O = "Візьміть Символ Життя і поговоріть із Муйредоном Бойовою Кузнею в Залізогарті.",
    P = "",
    C = "*кашель*$B$BGood день з тобою, $C. Не зважайте на мої рани, добрий священик вчасно подбає про старого Муіредона. Вам ще не потрібна сила цього Символу Життя.$B$BSo, моя дружина послала вас поговорити зі мною, га? Чесно. Я знайдіть час, щоб поговорити з вами — я розповім вам, що саме трапилося з Муіредоном і його найкращим другом Нармом, таким же $C, як і ви.",
},

[1780] = {
    en = "The Tome of Divinity",
    T = "Фоліант Божественності",
    D = "Я віднесу це дітям ще сьогодні. Бережи себе, добрий $c. Нечасто $G люди:жінки; твого характеру з’являються в місті, але ти довів, що паладини тут, у Штормовії, ніколи не відвернуться від тих, хто потребує допомоги.$B$BПрощавай.",
    O = "Поговоріть із Дуторіаном Раллом у Штормовії.",
    P = "",
    C = "Ти так швидко повернувся, $N. А чого ви досягли за час, проведений далеко від Собору?$B$BHave ви допомогли благородній справі? Можливо, ви дізналися цінність благодійності або щось більше про свої зобов’язання перед громадянами Азероту. Скажи мені, кому ти допоміг і як... Ну, я вражений, $N, це, безумовно, дії того, хто йде за Світлом і цінує інших понад себе.$B$BSuch жертва завжди буде винагороджена з часом.",
},

[1781] = {
    en = "The Tome of Divinity",
    T = "Фоліант Божественності",
    D = "Візьми це, $N. Це називається Символ Життя.$B$BТи довів свою милосердність і терплячість, і тепер настав час перевірити, чи достатньо ти сильний, щоб зосередити один із найбільших дарів Світла.$B$BМій друг Ґазін нещодавно повернувся після сутички з Дефіасами в Ельвінні біля Дозору Героїв — він ледь залишився живим. Він біля вівтаря, його рани зцілюють наші жерці.$B$BВізьми Символ і поговори з ним. Якщо ти зможеш допомогти йому, ми скоро знову поговоримо. Нехай ти купаєшся в славі Світла.",
    O = "Віднесіть Символ Життя до Ґазіна Тенорма в Штормовії.",
    P = "",
    C = "*кашляє*$B$BPleasure до зустрічі, $R. Не зважайте на мої рани, цього разу добрий священик може подбати про старого Газіна. Мені не знадобиться сила того Символу Життя, який у вас є... у всякому разі ні.$B$BSo, Дуторіан послав вас поговорити зі мною, так? Справедливо. Я точно розповім вам, що сталося зі мною та моїм другом Генце. І якщо вам пощастить, і ви матимете певні навички, можливо, ви все ще зможете нам усім допомогти.",
},

[1782] = {
    en = "Furen's Armor",
    T = "Обладунки Фурена",
    D = "",
    O = "",
    P = "",
    C = "Ось твоя броня, $N. Це витримає найсильніші напади, інакше мене звуть не Фурен Довгобородий!$B$BAnd Я маю подякувати вам. Я багато чого навчився, працюючи з матеріалами, які мені приніс$Byou. Я думаю, що одного разу я досягну ще одного прориву!$B$BI Я передам те, що я дізнався, іншим$Bblacksmiths з Альянсу.$B$BI скажу їм, що ви дуже допомогли, і, можливо, вони захочуть відповісти вам за це.",
},

[1783] = {
    en = "The Tome of Divinity",
    T = "Фоліант Божественності",
    D = "Ми стежили за деякими Темнозалізними гномами, що засіли на південь від озера Шоломового Ложу. Ми знали, що вони задумали щось лихе, тож ми з Нармом вирішили підійти ближче — побачили, як їхній капітан віддає накази своїм людям.$B$BМи з Нармом скористалися шансом зарубати кількох із них, але вони виявилися міцнішими, ніж ми думали, і ще більше їх на нас наскочило. Нарм сказав мені бігти по підмогу, тож я тут.$B$BНарму потрібна допомога, і я не заспокоюся, доки він її не отримає.$B$BЧи можеш ти допомогти, $N?",
    O = "Візьміть Символ Життя і воскресьте Нарма Фалка в Дун-Мороґу.",
    P = "",
    C = "Я не можу віддячити тобі достатньо, $gbrother:сестро;.$B$BI можу лише припустити, що Тіза та Муіредон послали тебе сюди, щоб допомогти мені, якщо ти несеш Символ життя.$B$BIt Це правда, я впав у Темне Залізо, намагаючись отримати один із сценаріїв: я зміг протриматися достатньо довго, щоб дозволити Муіредону втекти, але Світло встигло майже обняв мене повністю, коли ти підійшов. Той факт, що ви були достатньо могутніми, щоб використовувати Символ, означає для вас великі речі, але буде час поговорити про це пізніше.",
},

[1784] = {
    en = "The Tome of Divinity",
    T = "Фоліант Божественності",
    D = "Перед тим, як я загинув у битві, ми з Муйредоном майже зарубали одного з шпигунів Темнозалізних біля того маленького будинку. Ми бачили, як їхній капітан передавав їм накази, і намагалися зарубати його та забрати ці накази.$B$BДеякі члени ради в Залізогарті досі не вірять, що Темнозалізні гноми присутні в Дун-Мороґу. Якщо ми здобудемо один із тих наказів, ми не лише матимемо доказ їхньої присутності, але й, можливо, дізнаємося, що вони планують.$B$BДістань один із тих наказів і віднеси його Муйредону, $N.",
    O = "Дістаньте Наказ Темнозалізних від Темнозалізних гномів біля Шоломового Ложу і поверніться до Муйредона Бойової Кузні в Залізогарті.",
    P = "Повернувся! Я радий це бачити, $N. Мої рани зажили, і я збираюся повернутися до озера Хелмс-Бед, щойно переконаю дружину, що зі мною все буде добре.",
    C = "ха-ха! Ви зробили це! Я врятував Нарма і знайшов докази, які моя дружина повинна віднести до ради. Благословення Світла, якщо я колись його побачу... звичайно, не враховуючи мою дружину.$B$BThank знову так, $N.",
},

[1785] = {
    en = "The Tome of Divinity",
    T = "Фоліант Божественності",
    D = "Я бачу, як моя дружина там сяє від гордості. Тобі краще швидко до неї підійти. Думаю, вона хоче з тобою поговорити.$B$BНехай Світло буде з тобою, могутній $c. Я чекатиму на тебе на полі бою проти Скари і тих Темнозалізних, коли настане час.",
    O = "Поговоріть із Тізою Бойовою Кузнею в Залізогарті.",
    P = "",
    C = "Сьогодні ти зробив усьому Стальгорну велику послугу, $N. Я пишаюся тим, що ви серед нас, і якщо ви відчуваєте, що готові, я хотів би благословити вас цим сувоєм. Символ життя спрацював би лише тоді, коли його використовував $C, який був готовий отримати одне з найбільших благословень Світла — силу повертати мертвих до життя.$B$BI навчить вас здатності воскрешати своїх супутників. Використовуй це мудро, $N, і дякую тобі від себе, мого чоловіка та від імені Стальгорна.",
},

[1786] = {
    en = "The Tome of Divinity",
    T = "Фоліант Божественності",
    D = "Ми з Гензе дісталися до Дозору Героїв, острова посеред озера Кам’яного Кургану в північно-східному Ельвінні. Ми чули, що Дефіаси проникли в наші кордони, і хотіли знайти докази для радників короля.$B$BМи помітили кількох із цих покидьків, які переглядали якісь документи, і напали. На жаль, нас швидко здолали інші маги.$B$BГензе прикривав мене, поки я тікав... дурень, вирішив бути хоробрим.$B$BВін там зараз, Гензе. Чи можеш ти нам допомогти, $N?",
    O = "Візьміть Символ Життя і воскресьте Гензе Фалка в Ельвінні.",
    P = "",
    C = "Дякую, $Gbrother:sister;.$B$BSeeing ти володієш Символом Життя, чи можу я припустити, що тебе надіслав Дуторіан чи Газін?$B$BI впав у руки заклиначів Defias, поки ми з Газіним намагалися отримати від них їхні плани: я зміг протриматися достатньо довго, щоб дозволити Газіну втекти, але зрештою їхня магія мене приголомшило.$B$BBut ти зміг повернути мене: здатність використовувати Символ дається не кожному, $N. Це добре для вас, що ви змогли посилити його своєю вірою.",
},

[1787] = {
    en = "The Tome of Divinity",
    T = "Фоліант Божественності",
    D = "Ми ще поговоримо про Символ пізніше. Зараз важливо дістати ті папери, які ми бачили в Дефіасів. Якщо ми зможемо їх забрати, ми доведемо, що Дефіаси проникли в Ельвінн, і, можливо, дізнаємося, які в них плани.$B$BЯ зараз не в змозі битися, $N. Чи вважаєш ти себе достатньо сильним, щоб забрати ті папери в Дефіасів тут, на острові?$B$BЯкщо тобі вдасться їх дістати, віднеси їх до Ґазіна і дай йому знати, що я в порядку.",
    O = "Дістаньте Наказ Дефіасів від Чаклунів-Розбійників Дефіасів в Ельвінні і поверніться до Ґазіна Тенорма в Штормовії.",
    P = "Чи безпечний Henze, $N? Ви досягли успіху?$B$BBetween ваші навички володіння зброєю та сила світла, я думаю, що Heroes' Vigil захищена від будь-якої загрози Defias, але це мають сказати Король та його радники.",
    C = "Чудово! Ти зробив це і врятував Хенце. Світло точно з тобою, $N!",
},

[1788] = {
    en = "The Tome of Divinity",
    T = "Фоліант Божественності",
    D = "Я віднесу накази до радників короля після того, як Дуторіан їх перегляне, але тим часом тобі варто піти поговорити з Дуторіаном. Він точно захоче похвалити тебе!$B$BЩе раз дякую, $N. Сподіваюся, ми ще зустрінемося. Ти точно союзник, якого я гордий назвати другом.",
    O = "Поговоріть із Дуторіаном Раллом у Штормовії.",
    P = "",
    C = "Ти добре попрацював цього дня, $N. Вам слід пишатися тим, чого ви досягли.$B$BEven більше того, ви повинні пишатися своїми здібностями. Не кожен може використовувати силу Символу Життя. Викликати Світло, щоб повернути мертвих, означає, що ви готові до однієї з найбільших честей $C: сили воскресіння. $B$BYou матиме силу повертати загиблих товаришів, подібно до того, як ви робили для Henze.$B$BBe добре, $N. Світло сяє на вас, і ви повинні вітати його цілком.",
