[2278] = {
    en = "The Platinum Discs",
    T = "Платинові диски",
    D = "Центральними експонатами цієї скарбниці є чотири величезні платинові диски, кожен із яких прикрашений численними символами невідомого походження. Торкаючись до них, твоя рука відчуває поколювання. Одразу після дотику до дисків з’являється образ великого кам’яного спостерігача.$B$B«Привіт. Я хранитель знань. Синтез Земляних Творцями зафіксовано і збережено тут для цього світу в Дисках Норґаннона.»$B$BТи відкрив багатство раніше невідомих світових знань!",
    O = "Поговори з кам’яним спостерігачем і дізнайся, які стародавні знання він зберігає. Після того, як ти дізнаєшся, які знання він пропонує, активуй Диски Норґаннона.",
    P = "Голос спостерігача за каменем ніби звучить у вашій внутрішній сутності:$B$B",
    C = "Виконуючи вказівки спостерігача каменів, ви знову отримуєте доступ до Дисків Норганнона тепер, коли ви дізналися про історію землян, трогів і гномів. Зсередини дисків чути слабке коротке дзижчання. Після цього спостерігач за камінням говорить:$B$B",
},

[2279] = {
    en = "The Platinum Discs",
    T = "Платинові диски",
    D = "Знову торкаючись до Дисків Норґаннона, твоя рука відчуває поколювання. Цього разу, однак, ізсередини дисків чути дивний скрегіт.$B$BТвій наплічник раптово стає важчим, ніж був раніше. Усередині ти виявляєш мініатюрну версію дисків!$B$BБез сумніву, предмет такого роду був би неоціненним для тих, хто цікавиться стародавньою історією Азероту. Ліга Дослідників у Залізогарті — це така група, відома по всьому Альянсу; можливо, вони зможуть добре використати його.",
    O = "Достав мініатюрну версію Дисків Норґаннона до Ліги Дослідників у Залізогарт.",
    P = "Так, я можу вам чимось допомогти?  Запевняю вас, я зараз дуже зайнятий.  Але якщо це надзвичайно важливо для Ліги дослідників, то я весь у вухах!",
    C = "Що у вас там... ой-ой.  Де ви це знайшли?$B$BNo, справді?$B$BYou з ким про що говорили?$B$BNO, ДІЙСНО?!$B$BMy добре $C, можливо, ви щойно зробили археологічну знахідку року!  Клянуся богами, яких я жартую, знахідка століття!  Якщо ці диски такі, якими я їх уявляю, то це може бути тим самим ключем, який ми шукали!  Це цілком може раз і назавжди підтвердити законність зачарованого творіння гномів!",
},

[2280] = {
    en = "The Platinum Discs",
    T = "Платинові диски",
    D = "Знову торкаючись до Дисків Норґаннона, твоя рука відчуває поколювання. Цього разу, однак, ізсередини дисків чути дивний скрегіт.$B$BТвій наплічник раптово стає важчим, ніж був раніше. Усередині ти виявляєш мініатюрну версію дисків!$B$BБез сумніву, предмет такого роду був би неоціненним для тих, хто цікавиться стародавньою історією Азероту. Мудреці Громового Бескиду — це такі історики, відомі по всій Орді; можливо, вони зможуть добре використати його.",
    O = "Достав мініатюрну версію Дисків Норґаннона одному з мудреців у Громовому Бескиді.",
    P = "Так, молодий, я бачу, як ти крокуєш до мого намету інтенсивно крокуєш... з рішучістю у своїй меті. Ви шукаєте моєї поради, чи є якась справа надзвичайно важливою для Орди? Можливо, ви бажаєте, щоб вам розкрили таємницю Всесвіту?",
    C = "Що це тут таке?$B$BImpressive, молодий! Ці диски, в них я відчуваю таємниці, які земля міцно тримала багато років. Ви вчинили дуже мудро, коли принесли їх мені сюди.",
},

[2281] = {
    en = "Redridge Rendezvous",
    T = "Зустріч у Червоногір’ї",
    D = "Відправляти тебе в поле зараз було б самогубством. Рензіку не потрібен ще один мертвий розбійник на руках. Але не хвилюйся, $N — Рензік приведе тебе до ладу.$B$BВирушай до Червоногірських Гір і поговори з нашим спільником на ім’я Луцій. Ти знайдеш його біля причалів Озерного, серед інших сумнівних типів.",
    O = "Вирушай до Озерного в Червоногірських Горах і поговори з Луцієм.",
    P = "",
    C = "Ах, твої пальці трохи жирні, еге ж? Не хвилюйся, $N, я перетворив на досвідчених шахраїв більше непотрібних злодіїв, ніж ти.",
},

[2282] = {
    en = "Alther's Mill",
    T = "Млин Альтера",
    D = "Ми тренуємо злодіїв тут уже багато років! Зрештою, не кожен пройдисвіт народжується з грацією та витонченістю старого Луція.$B$BТрохи вище по дорозі ти знайдеш Млин Альтера. У мене там є скриня з чимось важливим усередині. Іди і забери її для мене! Принеси назад той жетон, і ти отримаєш свій Сертифікат Злодійства!",
    O = "Відкрий Скриньку Луція, добудь Жетон Злодійства і поверни його Луцію в Озерне.",
    P = "Невже я забув згадати про орків?$B$BI чув, що вони носилися біля млина.",
    C = "Зламав його, чи не так? Гарна робота, $N.$B$BIf ти помреш зараз, ми можемо бути спокійні, знаючи, що це сталося через твою власну дурість, а не через недосвідченість.",
},

[2283] = {
    en = "Necklace Recovery",
    T = "Повернення нашийника",
    D = "У нас є робота для тебе, якщо в тебе вистачить сміливості її взяти!$B$BГлибоко в Безплідних Землях є розкопки Ульдамана. Ми чули історію про якогось дурного паладина, який нещодавно там загинув. Чому нас це хвилює? Тому що на ньому був дуже цінний нашийник. Кажуть, на ньому три великі самоцвіти: рубін, сапфір і топаз.$B$BСуть у тому, що ми хочемо його, і ми платимо ВЕЛИКЕ СРІБЛО, щоб його дістати. Він може бути пошкоджений, але це неважливо; ми полагодимо будь-які подряпини на ньому.",
    O = "Шукай цінний нашийник у розкопках Ульдамана і принеси його назад до Драна Дрофферса в Орґріммар. Нашийник може бути пошкоджений.",
    P = "Ну, у вас є намисто?  Не побачиш у нас мідяка, як не матимеш того намиста!",
    C = "Мммм порятунок!  Я відчуваю запах намиста звідси.  А тепер давайте подивимося на цю красу...$B$BHey, як ви думаєте, що ви тут намагаєтеся зробити?  У цьому намисті бракує дорогоцінних каменів!  Ви думаєте, ми б не помітили?  Навіть Малтон бачив, що дорогоцінні камені зникли.$B$BWell, можливо, ви їх не крали... але це намисто нічого не варте без цих дорогоцінних каменів!  Ваша робота тут ще не закінчена, напевно!",
},

[2284] = {
    en = "Necklace Recovery, Take 2",
    T = "Повернення нашийника, дубль 2",
    D = "Якби Мелтон не був дурнем, ці самоцвіти все ще десь в Ульдамані. Тобі доведеться повернутися туди і пошукати їх.$B$BЯк я сказав раніше, якщо інформація, яку ми маємо, правильна, то там є рубін, сапфір і топаз, які належать до нашийника. Знайди їх і встав у нашийник.$B$BЩодо того, де ці самоцвіти, хто знає? Може, тобі пощастить, і ти знайдеш труп паладина. Якщо його ще не обібрали, можливо, самоцвіти все ще при ньому.",
    O = "Знайди підказку про місцезнаходження самоцвітів у глибинах Ульдамана.",
    P = "",
    C = "Ви, здається, знайшли останки паладина, про якого Дран згадував раніше. Пошук останків виявив те, що, здається, є його щоденником. Книга в поганому стані, оскільки засохла кров забруднила більшу частину тексту в книзі. Однак те, що ви можете прочитати, є тарабарщиною; вона написана рідною мовою людей, наскільки вам відомо.$B$BYou книгу потрібно перекласти, якщо ви хочете почерпнути з неї якісь знання.",
},

[2298] = {
    en = "Kingly Shakedown",
    T = "Королівський струс",
    D = "Отже, ми були в розпалі планування третьої фази, коли пара дурнів Маґні увірвалася сюди, говорячи про якийсь грабіж і арешт деяких членів Прихованого Кола.$B$BНіхто не надягає кайдани на старого Чорноборода! Суперечка стала гарячою, і якось твоє ім’я випливло!$B$BМоя порада? Бери першого грифона з Залізогарта і гайда до Штормовію. Проберися до Старого Міста і поговори там із моїм старим другом Рензіком «Шивом».",
    O = "Подорожуй до Штормовію і знайди Рензіка «Шива».",
    P = "",
    C = "Завжди добре мати в наших лавах одного з шахраїв Хульфдана!",
},

[2299] = {
    en = "To Hulfdan!",
    T = "До Хулфдана!",
    D = "Де ти був, $N? Хулфдан шукав тебе всюди. Ми думали, що король, можливо, закував тебе в кайдани.$B$BВирушай до Залізогарта якомога швидше і поговори з Хулфданом!",
    O = "Подорожуй до Залізогарта і поговори з Хулфданом Чорнобородом.",
    P = "",
    C = "Тише, $N, охоронці можуть тебе почути.",
},

[2300] = {
    en = "SI:7",
    T = "СІ:7",
    D = "Рензік шукав тебе, рибо.$B$BЯ б не змушував чекати другого за вислугою Матіаса, якби був на твоєму місці.",
    O = "Подорожуй до Штормовію і знайди Рензіка «Шива».",
    P = "",
    C = "Ви готові приступити до роботи чи вам потрібно подрімати, перш ніж ми почнемо?",
},

[2318] = {
    en = "Translating the Journal",
    T = "Переклад щоденника",
    D = "У глухому куті, ти знаєш, що тобі потрібно перекласти книгу мовою, яку ти розумієш. Безумовно, у світі є багато людей, які могли б це зробити; однак найближче місце, де може бути хтось із такими навичками, — це форпост Карґат у Безплідних Землях. Можливо, це гарне місце для початку.",
    O = "Знайди когось, хто може перекласти щоденник паладина. Найближче місце, де може бути хтось підходящий, — це Карґат у Безплідних Землях.",
    P = "",
    C = "Могутній $C, я знаю, що ти робиш тут, у Безплодних землях. Я знаю, що ти шукаєш мого дару мов. Ви шукаєте частини того намиста, яке знайшли в Ульдамані.$B$BSurprised? Не будь – це моя робота знати такі речі. Натомість давайте обговоримо, що ви збираєтеся робити для перекладеного журналу. Повірте мені – я єдиний, кого ви знайдете, хто може це перекласти.$B$BBetter все ж дозвольте мені зробити вам кращу пропозицію, ніж Dran Droffers, і це дозволить вам завершити угоду з ними. Зараз цікаво, так?",
},

[2338] = {
    en = "Translating the Journal",
    T = "Переклад щоденника",
    D = "Дрофферс і Син Салведж не досить розумні, щоб відновити магію в нашийнику, але я можу. Усе, що я хочу, — це вивчити нашийник, щоб навчитися виготовляти такі сам. Для цього мені потрібен твій нашийник. Позич мені його, і в обмін на час, який я матиму для вивчення, я перекладу щоденник для тебе. Поки ти шукатимеш самоцвіти, я матиму досить часу, щоб дізнатися, що мені потрібно.$B$BЦе проста угода, і ніхто інший не дізнається. Що скажеш?",
    O = "Позич нашийник Джаркалу. В обмін він перекладе щоденник для тебе.",
    P = "Ви думали про це, так? Ти розумний $C, якщо погодишся на цю угоду — ми з тобою отримаємо те, чого хочемо обидва, а Дроферс і Син Салвадж подумають, що вони отримують те, чого хочуть.",
    C = "Ви добре розумієте, коли бачите його – я знав, що можу на вас покластися.$B$BIt зайде лише мить, поки я промовлю заклинання, щоб швидко перевести людську мову у форму, яку ви зрозумієте. Я троль слова; запитайте будь-кого в Орді про Яркала Моссмелда. А тепер почнемо...",
},

[2339] = {
    en = "Find the Gems and Power Source",
    T = "Знайди самоцвіти і джерело живлення",
    D = "Ось щоденник, перекладений, щоб ти міг його прочитати. Суть у тому, що дворфи заховали рубін, трогги заховали топаз, а трогг на ім’я Ґрімлок має сапфір.$B$BДивись — тобі потрібне джерело живлення, щоб нашийник знову запрацював. Дран Дрофферс цього не знає. Щоб знайти його, я б зробив так: заглибся якомога далі в Ульдаман і знищ найсильніший конструкт, який там є. Без сумніву, у нього буде джерело.$B$BКоли збереш усе, повертайся сюди!",
    O = "Добудь усі три самоцвіти та джерело живлення для нашийника з Ульдамана, а потім принеси їх Джаркалу Моссмелду в Карґат. Джаркал вважає, що джерело живлення може бути у найсильнішого конструкта в Ульдамані.$B$BЗі щоденника ти знаєш...$B* Рубін захований у забарикадованій зоні Тінефортеці.$B* Топаз схований в урні в одній із зон троггів, біля дворфів Альянсу.$B* Сапфір забрав Ґрімлок, лідер троггів.",
    P = "У вас є ще одна подорож у глибини Ульдамана, якщо у вас немає дорогоцінних каменів і джерела енергії, здатного направити магічну силу назад у намисто.$B$BYou отримаєте дорогоцінні камені назад, щоб доставити їх головорізам в Оргріммарі; Я збережу джерело живлення, оскільки це буде те, що змусить намисто працювати в першу чергу...",
    C = "Дуже добре, $C.  Тепер плоди нашого перенаправлення окупляться щедро.  Я закінчив із самим намистом, і я впевнений, що зможу послідовно дублювати процес будівництва.$B$BBut спочатку я використаю спеціально підготовлене заклинання, щоб швидко проаналізувати ці дорогоцінні камені, перш ніж ви віднесете їх разом із намисто назад до Оргріммару.  Це займе лише короткий час.",
},

[2340] = {
    en = "Deliver the Gems",
    T = "Достав самоцвіти",
    D = "Будь-яка оправа нашийника і самоцвіт підійдуть, якщо вони з того ж матеріалу. Однак це джерело живлення поверне магію до нашийника... я сподіваюся.$B$BЯ з радістю надаю самоцвіти, необхідні для твоєї версії нашийника, якщо джерело живлення дійсно спрацює.$B$BВирушай до Орґріммара і виконай свою частину угоди з Дрофферс і Син Салведж. Тільки тримай язик за зубами про нашу угоду, і коли повернешся, я можу мати для тебе чудовий сюрприз.",
    O = "Достав Нашийник і Самоцвіт Салведж Драну Дрофферсу в Орґріммар.",
    P = "Ну подивіться хто це! Я бачу, ти не поспішав сюди. Будемо сподіватися, що це не марна трата мого часу! Вам не заплатять, якщо ви не отримаєте все, що я просив. І повірте мені в цьому – ми перевіримо все двічі та потрійно!",
    C = "Так, це все тут. Скажи, не проти, якщо ми теж залишимо сумку? ні? Дякую, ціную це! Гаразд!$B$BThis намисто стане нашим найбільшим видобутком! Але не відчувайте себе дуже погано; Я впевнений, що намисто тобі все одно не підійде. Знову!$B$BA угода є угодою, тож ось ваша плата за порятунок. Наші справи поки що тут зроблені; перевірте пізніше, щоб побачити, чи є у нас ще робота. А до тих пір бійте!",
},

[2341] = {
    en = "Necklace Recovery, Take 3",
    T = "Повернення нашийника, дубль 3",
    D = "Поки Дран і Мелтон Дрофферси сперечаються через свій новий скарб, половина угоди завершена. Тепер час вирушити до Безплідних Земель, щоб закінчити справу, адже Джаркал Моссмелд у Карґаті може мати для тебе особливу нагороду.",
    O = "Відвідай Джаркала Моссмелда в Карґаті, щоб дізнатися, чи він досяг успіху.",
    P = "",
    C = "Джерело живлення, яке ви мені дали, перевершило всі мої очікування щодо нього. Я зміг зробити і вам, і собі намисто, і в мене залишилося достатньо, щоб зробити ще принаймні три. Вони отримають чималу плату, а Droffers і Son Salvage не будуть розумнішими.$B$BHere їдь, друже. Я дякую тобі за чудову роботу... і щось особливе для твоїх проблем.",
},

[2342] = {
    en = "Reclaimed Treasures",
    T = "Повернені скарби",
    D = "Прибирати кажанячі загони цією мітлою — не гідне заняття для Ґаррета! Я заробив трохи монет на цій клятій роботі, і я готовий витратити їх на тебе, щоб покращити своє становище.$B$BЗброя вибору родини Ґарретів замкнена в нашій скрині в Південній Загальній Залі Ульдамана, з часів, коли ми, Ґаррети, працювали там копачами. Без неї я застрягну тут назавжди — буквально — підмітаючи за цими пекельними кажанами.$B$BПоверни скарб моєї родини і принеси його мені! Допоможи мені відновити моє спадкове право!",
    O = "Добудь родинний скарб Патріка Ґаррета з їхньої родинної скрині в Південній Загальній Залі Ульдамана і принеси його йому в Підмістя.",
    P = "Підмітання ніколи не закінчується... ці кажани плідно знущаються над мною та моєю мітлою.  Будь ласка, скажіть мені, що ви повернули скарб моєї родини!  Я запропонував тобі своє срібло — цього мало?!",
    C = "Нарешті - мітла, гідна Гаррета.  Ви, до біса, варті кожного срібла, яке я витратив на вас, я кажу!$B$BDo ви мене чуєте, погані кажани?  Тепер я володію улюбленою зброєю родини Гарретів!  Тремтіть, кажани, тремтіть!!",
},

[2358] = {
    en = "Horns of Nez'ra",
    T = "Роги Нез’ри",
    D = "Багато років тому Роги Нез’ри були викрадені з маєтку Рейвенхолдт. Я шукав їх по континентах і океанах, лише щоб дізнатися, що ці нікчемні звірі весь цей час мали їх у своєму володінні.$B$BУбивай кожного орка Чорнокаменя, якого зустрінеш, доки не повернеш Роги Нез’ри. Якщо ти повернеш роги, знайди мене в Озерному.$B$BЗроби це для мене, і твоє ім’я стане відомим у Рейвенхолдті, $N.",
    O = "Поверни Роги Нез’ри до Тіні Арантіра в Озерне.",
    P = "У вас є роги принца демонів?",
    C = "Відмовити Рейвенгольдту в артефакті означало б заперечити власне існування. Молодець, $C. Ви ще можете побувати серед убивць Рейвенгольдта.$B$BAs, молодого шахрая, який шукав пригод у Темних берегах, я знайшов чай, який відновлює енергію під час бою. Він добре служив мені протягом багатьох років, і тепер я передаю вам смак чаю з розторопші. Випий його, коли втомишся, $N, і знову бийся з силою!$B$B",
},

[2359] = {
    en = "Klaven's Tower",
    T = "Вежа Клавена",
    D = "Я стежив за цією вежею тижнями, $N. Нещодавно з Сутінкового Лісу прибув великий вантаж, а разом із ним і ці охоронці.$B$BХто вони? Твоя здогадка не гірша за мою. Можу сказати одне — вони не люди.$B$BУ будь-якому разі, у вантажі була скриня — я припускаю, що ці потвори її охороняють. Зомбі з шипами тримає ключ, який нам потрібен.$B$BДобудь той ключ, проникни до вежі і розкрий, що в тій скрині. Віднеси свої знахідки назад до Матіаса.",
    O = "Вкради Ключ Вежі Дефіасів, проникни до Вежі Дефіасів і розкрий вміст Скрині Сутінкового Лісу. Віднеси будь-яку знайдену інформацію назад до Матіаса Шоу в Штормовію. Прочитай Щоденник Кірнена, щоб отримати уявлення про вежу.",
    P = "Є новини від агента Кернена?",
    C = "Це пояснює дрони Defias, які ви з Кеарненом бачили за межами вежі, $N. Це також пояснило б причетність Венчурної компанії до Defias і дивних поставок із Сутінкового лісу.$B$BAccording до цієї книги занзільські тролі в Тернистій долині знайшли спосіб воскрешати мертвих за допомогою зілля... або, точніше, отрути.$B$BYou не буде корисним для SI:7 без твердого розуміння отрут, $N -- особливо з рецептом створення нежиті під рукою.",
},

[2360] = {
    en = "Mathias and the Defias",
    T = "Матіас і Дефіаси",
    D = "Вчасно, $N. Розвідка СІ:7 повідомляє про надзвичайно високу активність Дефіасів у Західному Краї.$B$BСхоже, Дефіаси захопили покинуту сторожову вежу Альянсу на південний схід від Сторожового Пагорба і використовують її як базу для контрабанди товарів із маршруту постачання Червоногір’я.$B$BВирушай до Західного Краю і зв’яжися з агентом Кірнен для інструктажу. Ти знайдеш її прихованою біля вежі.$B$B...і $N, якщо тебе викриють, СІ:7 відхреститься від будь-якої причетності до тебе.",
    O = "Подорожуй до Західного Краю і знайди агента Кірнен для інструктажу.",
    P = "",
    C = "Матіас нарешті послав іншого агента, щоб мене підтримати, еге ж? Я сподіваюся, що він готовий почути погані новини.",
},

[2361] = {
    en = "Restoring the Necklace",
    T = "Відновлення нашийника",
    D = "",
    O = "",
    P = "",
    C = "Я радо дарую тобі це намисто, могутній $C.  Ви зробили мені неоціненну послугу, і я вам за це дякую.  Носіть його з гордістю та голосно та неодноразово згадуйте, хто зробив його для вас!$B$BAlso, якби ви могли додати той факт, що він справді не проклятий, це було б чудово.",
},

[2378] = {
    en = "Find the Shattered Hand",
    T = "Знайди Розколотую Руку",
    D = "Ти добре послужив Смертостежцям, $N, але, можливо, настав час тобі вирушити далі. Хоча ти показав здібності в мистецтві скритності та обману, тобі ще потрібно багато тренуватися.$B$BСмертостежці мають союзників у Розколотій Руці. Шукай тих, хто може нам допомогти — знайди Шентула в Орґріммарі.",
    O = "Вирушай до Орґріммара і поговори з Шентулом у Розщелині Тіней.",
    P = "",
    C = "Отже, вас прислали наші могутні союзники Шентхулу? Як не надихає....",
},

[2379] = {
    en = "Zando'zan",
    T = "Зандо’зан",
    D = "Твоєї рішучості недостатньо, щоб подолати перешкоди, які чекають попереду.$B$BПоговори з Зандо’заном, щоб почати своє тренування як оперативник Розколотої Руки.$B$BЛише коли ти опануєш мистецтва скритності та злодійства, ти зможеш зробити наступний крок до своєї долі.",
    O = "Поговори з Зандо’заном у Розщелині Тіней.",
    P = "",
    C = "Можливо, Зандо'зан помилявся. Зандо'зан просить вибачення.",
},

[2380] = {
    en = "To Orgrimmar!",
    T = "До Орґріммара!",
    D = "Ти ще не майстер скритності та обману, але все це може і буде змінено. Очевидно, ти вразив тих, хто керує, своїми скромними навичками, адже великий Шентул попросив тебе за ім’ям.$B$BВізьми дорогу на північ звідси до Орґріммара і поговори з Шентулом у Розщелині Тіней.",
    O = "Поговори з Шентулом у Розщелині Тіней в Орґріммарі.",
    P = "",
    C = "Важливо, щоб Зруйнована Рука залишалася пильною перед обличчям змін, які Тралл хоче внести в Орду. Однієї нашої кількості буде недостатньо, щоб подолати його панування — необхідно оволодіти скритністю й обманом.",
},

[2381] = {
    en = "Plundering the Plunderers",
    T = "Грабунок грабіжників",
    D = "Я не хочу тебе лякати, $N, але останні п’ять злодіїв, яких я посилав украсти скарб південноморців, повернулися до мене по частинах.$B$BНа південь уздовж узбережжя ти знайдеш «Приливний Гребінь», корабель південноморських піратів. У трюмі захований скарб — скарб південноморців. На другому рівні цього корабля є піратське кубло, де вони тренують своїх злодіїв.$B$BПіднімися на цей корабель, вкради скарб і принеси його мені. Використовуй піратське кубло, якщо потрібно потренувати свої злодійські навички, але будь обережний!",
    O = "Принеси Скарб Південноморців назад до Вренікса Поганця в Ратчет. Не забудь взяти Е.К.А.К. і Злодійські Інструменти з Гізмотронного Апарата Вренікса. Обидва ці предмети тобі знадобляться для завершення місії.$B$BЯкщо на тебе нападуть незвично ворожі папуги, використовуй Е.К.А.К.!",
    P = "Ну, принаймні, у вас все ще є всі частини тіла. Ви знайшли скарб?$B$B",
    C = "Неймовірно! неймовірно! Просто неймовірно! Ти маєш талант, Вейр. Або це, або ти найщасливіша людина!$B$BHere — це твоя частина подій. Я впевнений, що ви б використали цей матеріал краще, ніж я.$B$B",
},

[2382] = {
    en = "Wrenix of Ratchet",
    T = "Вренікс із Ратчета",
    D = "Зандо’зан бачив це! Так, день наближається! Смерть Тралла... кинджал у його спині, отрута, що просочується в кожну вену... Зандо’зан сказав забагато.$B$B$N! Зандо’зан має завдання для $N! $N мусить вирушити до Ратчета, на схід від Перехрестя, і поговорити з Вреніксом Поганцем. Іди!",
    O = "Подорожуй до Ратчета і поговори з Вреніксом Поганцем.",
    P = "",
    C = "Ще один? Останні п'ять, які надіслав мені той божевільний троль, стали їжею для акул. Будемо сподіватися, що вам трохи краще, а?$B$B",
},

[2383] = {
    en = "Simple Parchment",
    T = "Простий пергамент",
    D = "Ах, поки тебе не було, для тебе прийшов пергамент, $N.$B$BПрочитай його, коли матимеш час. Якщо я не помиляюся, він від тренера воїнів Франґа. Він хоче поговорити з тобою, коли ти будеш готовий. Ти знайдеш його біля Ліґва, у затінку.",
    O = "Прочитай Простий Пергамент і поговори з Франґом у Долині Випробувань.",
    P = "Що це у вас там? Пергамент? Ти не вчений, я сподіваюся...",
    C = "А, це мій пергамент. Я чув, що ти приїдеш до Долини, $N. Я радий бачити, що ви впоралися – будемо сподіватися, що ви переживете майбутні випробування. Як я вже сказав, коли ти здобудеш силу, приходь до мене — я зроблю все можливе, щоб навчити тебе способам воїна.$B$BGood удачі, $N, і повертайся до мене, коли будеш готовий.",
},

[2398] = {
    en = "The Lost Dwarves",
    T = "Загублені дворфи",
    D = "Розкопки в Ульдамані не завжди були переповнені ворогами. Ми, дворфи Залізогарта, колись контролювали цю територію, але... це було до приходу троггів. Вони прийшли так швидко і в такій кількості, що навіть дворфська міць не могла їх зупинити!$B$BНасправді, їхній напад був настільки раптовим, що я боюся, що деякі з наших людей могли залишитися за лінією ворога.$B$BМій друг Баелоґ очолив невелику групу дворфів глибоко в розкопках незадовго до появи троггів. Якщо він і його команда живі, я хочу, щоб ти їх знайшов.",
    O = "Знайди Баелоґа в Ульдамані.",
    P = "",
    C = "Настав час тобі з’явитися! Я був у небезпеці програти парі з Олафом!$B$BHe побився об заклад, що його борода виросте до колін, перш ніж він побачить іншого живого $R. Ну ось, і, як бачите, до бороди Олафа залишилося ще кілька дюймів.$B$BThanks, $N. Я розділю з тобою виграш.",
},

[2399] = {
    en = "The Sprouted Fronds",
    T = "Пророслі пагони",
    D = "",
    O = "",
    P = "",
    C = "Листя, які Деналан посадив у своєму саду, проросли та виросли.  Вони тремтять, прагнучи, щоб їх зібрали....",
},

[2418] = {
    en = "Power Stones",
    T = "Силові камені",
    D = "Колись я мав сутичку з дворфами Тінефортеці. Вони привели мене до Фортеці Анґор, щоб вивчити два типи дивних каменів з Ульдамана. Я виявив, що ці камені є стабільними джерелами енергії, якщо їх правильно обробити. Дивовижно, що можна знайти в цих старих розкопках!$B$BУ будь-якому разі, після того, як я розповів їм секрет каменів, вони вигнали мене з Фортеці Анґор і почали копати в Ульдамані в пошуках нових.$B$BЯ хочу ці камені для себе! Принеси мені обидва типи, і я щедро заплачу!",
    O = "Принеси 8 Силових Каменів Дентріума і 8 Силових Каменів Ан’Аллеума Ріґґлфуззу в Безплідні Землі.",
    P = "У вас є камені сили, $N?  У мене є робот-гризун, якому потрібен джерело живлення...",
    C = "Чудово, ви знайшли!  Дуже дякую, $N.  Ти найнадійніший $r, якого я зустрічав!$B$BI не можу дочекатися, щоб спробувати це на деяких пристроях, з якими я працював.  Б’юсь об заклад, що за відповідних обставин пристрої, що живляться цим камінням, працюватимуть, і працюватимуть, і працюватимуть...",
},

[2438] = {
    en = "The Emerald Dreamcatcher",
    T = "Смарагдовий ловець снів",
    D = "Колись мені подарував смарагдовий ловець снів Гаеролас Талветен, наглядач друїдів у Бан’етільському Барлозі. Цей потужний амулет здатен висмоктувати енергію зі Смарагдового Сну, даруючи удачу тим, хто його носить.$B$BНа жаль, я не зміг забрати його з моєї скриньки в Селі Зоряного Вітру... Хоча Зоряний Вітер колись був спокійним місцем, тепер він піддався псуванню фурболгів, що там мешкають.$B$BМожливо, ти захочеш повернути мій ловець снів, $c?",
    O = "Принеси Смарагдовий Ловець Снів Таллонкаю Свіфтроту в Доланаар.",
    P = "Будь ласка, поспішайте. Я можу лише сподіватися, що мій смарагдовий ловець снів не постраждав від фурболга.$B$BHave ти вже знайшов його, $N?",
    C = "Мій смарагдовий ловець снів для мене дуже важливий. Це подарунок лише небагатьом. Дякуємо, що повернули його, $N.",
},

[2439] = {
    en = "The Platinum Discs",
    T = "Платинові диски",
    D = "Цей предмет — неймовірна знахідка. Стародавні Титани, або Творці, як їх називають ці диски, є ключем до нашого зачарованого створення, якщо вірити знанням, що тут зберігаються! Нам потрібно вкласти якомога більше часу в дослідження цього.$B$BЩо стосується тебе, героїчний $c, візьми цей ваучер до Дініти Кам’яного Плаща в сховищі. Він гарантує тобі те, що я вважаю гідною нагородою за таку величезну знахідку!$B$BПовертайся до мене, коли будеш готовий; у Лізі Дослідників ще багато роботи!",
    O = "Віднеси ваучер нагороди до Дініти Кам’яного Плаща в Сховище Залізогарта.",
    P = "Ласкаво просимо до Сховища Стальгорну, $N.  Що я можу зробити для вас сьогодні?",
    C = "Так, ваучер від Ліги дослідників... і досить цінний, можу додати.$B$BThe Ліга дослідників надає мені право пропонувати вам вибір компенсації безпосередньо з їхнього сховища.  Ви маєте отримати цей предмет, і ви можете вибрати між п’ятьма кращими цілющими зіллями або п’ятьма більшими зіллями мани в якості нагороди.",
},

[2440] = {
    en = "The Platinum Discs",
    T = "Платинові диски",
    D = "Я зосереджу свою енергію на цих дисках; з часом вони відкриють мені свої справжні таємниці.$B$BЩо стосується тебе, $N, я тепер винагороджу тебе за твою старанність у тому, що ти привернув мою увагу до цього. Візьми цей ваучер до Бени Зимового Копита, тренера алхімії в Громовому Бескиді. Вона дасть тобі особливий предмет, який, я вірю, тобі сподобається, і забезпечить тебе вибором зілль із моїх особистих запасів.$B$BПовертайся до мене незабаром, адже я відчуваю, що попереду ще багато роботи з цією знахідкою.",
    O = "Віднеси ваучер нагороди до Бени Зимового Копита в Громовий Бескид.",
    P = "Вітаю, $C! Ви тут для навчання алхімії чи, можливо, чогось іншого?",
    C = "Що ж, $N, ти, мабуть, дуже порадував Мудреця Правдошукача, коли він дав тобі цей предмет. Ви також отримаєте подарунок із його сховку зілля; Ви можете вибрати між 5 кращими цілющими зіллями або 5 більшими зіллями мани в якості нагороди.",
},

[2458] = {
    en = "Deep Cover",
    T = "Глибоке прикриття",
    D = "Компанія Венчур... Може, ти чув про них?$B$BПротягом року ми працювали над тим, щоб заслати агента глибоко в їхні лави. Завдяки великій праці та ретельному плануванню нам це вдалося.$B$BНещодавно ми отримали звістку, що Компанія Венчур планує щось грандіозне. Вирушай на північ від Болотяного Болота до вежі Компанії Венчур і зв’яжися з нашим таємним агентом, наглядачем Фіззулем.$B$BКоли побачиш вежу, використай цю сигнальну гармату, а потім підійди до Фіззуля і покажи йому салют Розколотої Руки.",
    O = "Вирушай до Вежі Компанії Венчур, на північ від Болотяного Болота, і зв’яжися з таємним оперативником Розколотої Руки, наглядачем Фіззулем.$B$BКоли вежа буде на видноті, використай Сигнальну Гармату, щоб подати сигнал про своє прибуття Фіззулю. Випали ДВА сигнали, а потім підійди до Фіззуля і виконай салют Розколотої Руки.$B$BЦі дії потрібно виконати в правильному порядку, адже Фіззуль атакує і знищить будь-кого, кого не впізнає.",
    P = "",
    C = "Приємно бачити в цих краях ще одного агента Зруйнованої руки, однак ракета, можливо, була занадто сильною!$B$BNext час, коли вам знадобиться поговорити зі мною, дмухніть у цей свисток двічі, і я знатиму, що ви союзник.",
},

[2459] = {
    en = "Ferocitas the Dream Eater",
    T = "Феросітас Пожирач Снів",
    D = "Смарагд... Він зник! Мій ловець снів пошкоджений!$B$BНа північ від Зоряного Вітру є група містиків Ґнарлпайн. Я чув звіти, що їхній лідер, Феросітас Пожирач Снів, носить намисто, яке світиться зеленим у ночі. Тепер, побачивши мій ловець снів, я впевнений, що він украв мій смарагд... Він ніколи не зрозуміє, що його сила марна для нього.$B$BЗнайди цей зниклий самоцвіт, $N. І, поки ти там, позбудься кількох зіпсованих містиків.",
    O = "Таллонкай Свіфтрот у Доланаарі хоче, щоб ти вбив 7 Містиків Ґнарлпайн і знайшов Зниклий Самоцвіт.",
    P = "Фероцітас і Містики Гнарпіна повинні повернути те, що належить мені. Будь ласка, візьміть смарагд, щоб я міг відремонтувати свій смарагдовий ловець снів.",
    C = "Тепер я можу відремонтувати свій ловець снів. Дякую, $N.",
},

[2460] = {
    en = "The Shattered Salute",
    T = "Салют Розколотої Руки",
    D = "Як розбійник Розколотої Руки, надзвичайно важливо, щоб ти вивчив Салют Розколотої Руки. Це єдиний спосіб по-справжньому ідентифікувати іншого члена Руки.$B$BДивись, вчись, повторюй.",
    O = "Виконай Салют Розколотої Руки на Шентулі.",
    P = "",
    C = "Молодець, $N. Тепер ви готові продовжити.",
},

[2478] = {
    en = "Mission: Possible But Not Probable",
    T = "Місія: Можлива, але не ймовірна",
    D = "Тобі потрібно вкрасти ключ від вежі у бригадира Сіліксіза, $N. Коли ключ буде в твоїх руках, тримай його — він може знадобитися пізніше.$B$BПам’ятай, отрута послабила все в цій вежі. Використовуй свої здібності, щоб посіяти хаос і руйнування серед її мешканців. Убий їх усіх — не виявляй милосердя!$B$BКоли все всередині лежатиме в кривавій купі, зламай замок на скрині Ґаллівікса і вкради сховок зміненої суміші Занзіла, що всередині. Візьми голову Ґаллівікса і суміш до Шентула в Орґріммар.",
    O = "Вкради Ключ Вежі Сіліксіза у бригадира Сіліксіза, а потім убий двох Мутованих Дронів Компанії Венчур, двох Патрульних Компанії Венчур і двох Спостерігачів Компанії Венчур.$B$BУбий головного бригадира Ґаллівікса і забери його голову, а потім зламай замок на скрині Ґаллівікса і вкради Сховок Зміненої Суміші Занзіла. Віднеси Сховок і Голову Ґаллівікса назад до Шентула в Орґріммар для подальших інструкцій.",
    P = "Що ти маєш повідомити, $N?",
    C = "Бідний Фіззул, він був хорошим агентом — одним із наших найкращих. На жаль, це ціна, яку ми платимо, $N. Бути польовим агентом Розбитої руки — це небезпечна робота.$B$BYou добре виконав свій обов’язок, $C. Було б прикро, якби ви не дожили, щоб служити нам знову.",
},

[2479] = {
    en = "Hinott's Assistance",
    T = "Допомога Хінотта",
    D = "Віднеси зразок суміші до Сержа Хінотта в Тарренський Млин.$B$BЯкщо хтось і може тебе вилікувати, то це Серж. Живи досить довго, і Серж покаже тобі шляхи створення та використання отрут.",
    O = "Подорожуй до Тарренського Млина в Передгір’ях Гіллсбрада і достав Зразок Суміші Занзіла Сержу Хінотту.$B$BЩоб дістатися до Тарренського Млина, сядь на цепелін до Підмістя і йди дорогою на південь через Срібнохвой і до Гіллсбрада. Дотримуйся вказівників!",
    P = "Що це???",
    C = "Ви виглядаєте надзвичайно блідим, $C. І що це за неприємний аромат, який ви видаєте? Я повинен знати!",
},

[2480] = {
    en = "Hinott's Assistance",
    T = "Допомога Хінотта",
    D = "Я ніколи не бачив таких дивовижних результатів від отрути! Занзіл, кажеш? Ніколи про нього не чув, але мушу похвалити його за створення цього зілля.$B$BОтже, я мушу вилікувати тебе від цього, а потім навчити, як використовувати отруту?$B$BДай мені кілька хвилин, щоб вивчити токсин, $N.",
    O = "Зачекай, поки Серж Хінотт завершить створення ліків.",
    P = "",
    C = "Ліки готове! Випий цей антитоксин, і повзуче безумство припиниться, але я нічого не зможу вдіяти із запахом.",
},

[2498] = {
    en = "Return to Denalan",
    T = "Повернення до Деналана",
    D = "Я щойно отримав звістку, що Деналан біля озера Аль’Амет виявив, що може бути причиною пухлин, які вражають лісовиць. Будь ласка, поговори з ним і скажи, що я тебе послав.$B$BПоспіши, $N; йому потрібна наша допомога.",
    O = "Релліан Зеленопир хоче, щоб ти поговорив із Деналаном біля озера Аль’Амет.",
    P = "",
    C = "Ах, значить, Релліан послав тебе мені на допомогу. Я радий, що ви приїхали сюди так скоро.$B$BI виявили щось дуже тривожне!",
},

[2499] = {
    en = "Oakenscowl",
    T = "Дубовошкур",
    D = "У печері вздовж південного берега озера лісовиця на ім’я Дубовошкур поширює псування на всіх істот, які вважають озеро Аль’Амет своїм домом.$B$BЯ не наважився підійти надто близько, але навіть здалеку очевидно: Дубовошкур отруєний найбільшою пухлиною, яку я коли-небудь бачив... Я б назвав її гігантською.$B$B$N, ти вже багато зробив для моїх зусиль, але я прошу тебе виконати ще одне завдання. Знайди Дубовошкура і збери пухлину; усуни це джерело псування з мого дому.",
    O = "Деналан біля озера Аль’Амет хоче, щоб ти зібрав Гігантську Пухлину з Дубовошкура.",
    P = "Ви вже знайшли Oakenscowl, $R?",
    C = "Я знав, що ти більш ніж здатний позбавити озеро від цього жахливого звіра.$B$BIt це тривожна ситуація; Колись Оукенскоул був великим лідером серед свого роду... але корупція не робить різниці між низькими та благородними.$B$BThe Розмір цієї пухлини досить тривожний, але я повинен вивчити її, щоб дізнатися більше про хворобу, яка турбує популяцію лісорубів.$B$BThank ви, $N.",
},

[2500] = {
    en = "Badlands Reagent Run",
    T = "Рейд на реагенти в Безплідних Землях",
    D = "$C, я хотів би скористатися твоїми послугами. Я алхімік із певною репутацією, і мені потрібна твоя допомога в отриманні деяких реагентів із Безплідних Земель.$B$BМені потрібні такі предмети, щоб поповнити мої запаси: п’ять шлунків канюка, десять іклів скельного койота і п’ять уламків кам’яного елементаля. Очевидно, ти можеш добути їх із самих звірів; якщо ти не боєць, то знайди друзів, які вміють битися.$B$BДобудь ці предмети для мене, і ти отримаєш трохи монет за угоду.$B$BЩо скажеш?",
    O = "Добудь реагенти, які потрібні Ґаку Цілителю, із Безплідних Земель, а потім повернися до нього в Телсамар.",
    P = "Ви вже отримали те, що мені потрібно?  You won't get paid unless you bring me those reagents.",
    C = "Ах, молодець $N.  Мені їх повинно вистачити принаймні на деякий час.  Ось ваша оплата, як і обіцяли.$B$BIf ви зацікавлені, у мене є ще кілька реактивів, які я можу використати.  Однак їх можна знайти лише в глибині розкопок Ульдамана.  Їх буде непросто отримати, але я зроблю це варте вашого часу, якщо ви знову захочете мені допомогти.$B$BМожливо щось більше, ніж блискучі монети, так?",
},

[2501] = {
    en = "Badlands Reagent Run II",
    T = "Рейд на реагенти в Безплідних Землях II",
    D = "Ти дуже мені допоміг, $N. Я хотів би нагородити тебе самим рецептом настою, який я тобі раніше дав, але я мушу попросити тебе виконати досить небезпечне завдання.$B$BЦя скринька містить три порожні тауматургічні посудини; вони просякнуті аурою налаштування, яка висмоктує кров обпаленого дракона-вартового. Використання однієї на звірі сильно його розлютить, тож будь обережний. Коли всі три будуть наповнені, принеси їх мені.$B$BЗроби це, і рецепт буде твій.",
    O = "Використай порожні тауматургічні посудини на обпалених драконах-вартових у Безплідних Землях. Коли вони будуть наповнені, принеси їх Ґаку Цілителю в Телсамар.",
    P = "Ви використовували судини, щоб отримати мені необхідну спалену кров дракона-охоронця?  Так, я знаю, що це небезпечне завдання... але рецепт мого відновного напою чекає на ваш успіх.  Ризик і винагорода, друже... ризик і винагорода...",
    C = "Від одного алхіміка до іншого, я вітаю вас.  Ось візьміть цей рецепт і передайте його собі.  Нехай він принесе вам успіх і нагороди, які приносив мені протягом багатьох років!",
},

[2518] = {
    en = "Tears of the Moon",
    T = "Сльози Місяця",
    D = "Леді Сатрах колись була улюбленицею Елуни. Граціозна і чиста, павучиха пряла свої срібні нитки під місячним світлом, ловлячи вечірній туман. Срібляста роса мала сильні цілющі властивості і зберігалася тут, у храмі.$B$BАле останнім часом Сатрах збожеволіла. Її майбутні покоління тепер також під загрозою.$B$BЗнайди Леді Сатрах, $N, і поклади край її стражданням. Вона мешкає вздовж північних кордонів Тельдрассіла, біля озера Криничного. Збери її сріблясті павутинки і принеси їх мені.",
    O = "Жриця А’мура в Храмі Місяця в Дарнасі хоче, щоб ти приніс їй Сріблясті Павутинки Леді Сатрах.",
    P = "Я шкодую про завдання, яке я попросив вас виконати; але на леді Сатра немає надії.$B$BIt ми сподіваємося принести в жертву прядки Елуні. Цією жертвою Елуна благословить Сатру, щоб вона могла переродитися та мати мир.",
    C = "Ліс оплакує леді Сатру, але це треба було зробити.$B$BThank ти, $N.",
},

[2519] = {
    en = "The Temple of the Moon",
    T = "Храм Місяця",
    D = "Колись велика істота лісу потребує допомоги, $r.$B$BЄ складне завдання, яке потрібно виконати.$B$BБудь ласка, знайди жрицю А’муру; вона тобі все пояснить. Ти знайдеш її на південний схід звідси, всередині Храму Місяця.",
    O = "Сестра Аквінна хоче, щоб ти поговорив із жрицею А’мурою в Храмі Місяця.",
    P = "",
    C = "Отже, сестра Аквінна прислала вас?",
},

[2520] = {
    en = "Sathrah's Sacrifice",
    T = "Жертва Сатрах",
    D = "Тепер ти мусиш завершити завдання, до якого тебе призначено. Візьми павутинки і принеси жертву Леді Сатрах Елуні; поклади велику павучиху на спочинок.$B$BУсередині цього храму знайди центральний фонтан. Там ти можеш залишити жертву. Святі води очистять і усунуть псування, яке довело Сатрах до божевілля.$B$BКоли ти завершиш це, повернися до мене.",
    O = "Жриця А’мура хоче, щоб ти поклав Сріблясті Павутинки Леді Сатрах до фонтану всередині храму, а потім повернувся до неї.",
    P = "Ви принесли жертву біля фонтану, $n?",
    C = "Втрата леді Сатри засмучує, але лише таким чином вона може відродитися з оновленим духом.$B$BMay Елуна охоче приймає жертву, яку ви їй запропонували.",
},

[2521] = {
    en = "To Serve Kum'isha",
    T = "На службі Кум’іші",
    D = "$R, чи може твій крихітний мозок осягнути рідкість бездоганної сфери дренетисту? Дренеї витрачали цілі життя в пошуках лише однієї такої сфери, лише щоб зустріти жахливу долю, не виконавши своєї мети.$B$BОтже, ти стоїш перед Кум’ішою, знаючи, що просить Кум’іша, і все ще хочеш допомогти? Гаразд, $r... Під час твоїх мандрівок цими землями, якщо ти знайдеш бездоганну сферу дренетисту, поверни її мені, і я винагороджу тебе багатствами, які перевершать твої найсміливіші мрії.",
    O = "Під час твоїх мандрівок по Вибухових Землях, якщо ти натрапиш на Бездоганну Сферу Дренетисту, віднеси цей предмет назад до Кум’іші Збирача.$B$BПопереджаю, цей самоцвіт — один із найрідкісніших кристалів у всьому Азероті. Будь-яка істота в цих землях може тримати Бездоганну Сферу Дренетисту.$B$BТи будеш винагороджений за кожну зібрану Бездоганну Сферу Дренетисту.",
    P = "Я присвятив своє життя пошуку бездоганних сфер дренетисту. Ціле життя, тау",
    C = "Чи мої очі мене обманюють? Неможливо! Де ти... Як...$B$BМожливо тепер розлом можна відкрити, повернувши нас на батьківщину.",
},

[2522] = {
    en = "Kum'isha's Endeavors",
    T = "Старання Кум’іші",
    D = "Хоча створення порталу зазнало невдачі, я залишаюся сповненим надії, що моя наступна спроба буде успішною.$B$BНадія дренеїв така ж палка, як твоя жага до дрібничок, $r. Повертайся в ці прокляті землі і добудь ще одну бездоганну сферу дренетисту.$B$BЗвісно, вибір узятися за це завдання повністю за тобою *усміхається*.",
    O = "Знайди і поверни Бездоганну Сферу Дренетисту Кум’іші Збирачу.",
    P = "Ви знайшли ще одну бездоганну сферу дренетиста?",
    C = "Просто неймовірно. Я сумнівався, що ти зможеш знайти іншу сферу, але ось вона, пульсує в моїх руках.$B$BWell готово, $N!$B$BShould ти більше не знайдеш — і я вважаю, що це неможливо — поверни їх мені, і я винагороджу тебе знову.",
},

[2523] = {
    en = "Corrupted Songflower",
    T = "Зіпсована Піснеквітка",
    D = "",
    O = "",
    P = "Ви знайшли хворобливу, зіпсовану версію того, що виглядає як рослина пісочний. Від рослини виходить різкий нездоровий запах. Він відчайдушно потребує певної уваги, якщо хочеться повернути його до нормального стану.",
    C = "Ви наносите рослинну мазь Кенаріону на пісенну квітку. Воно негайно починає скидати зіпсовану форму, перетворюючись на живу та здорову рослину.",
},

[2541] = {
    en = "The Sleeping Druid",
    T = "Сплячий друїд",
    D = "Шамани Ґнарлпайн, що мешкають у цьому місці, відкрили спосіб відокремлення духу сплячого друїда від його фізичного тіла. Фурболги оживили мою фізичну форму і використовують її для нападу на будь-кого, хто намагається дослідити Бан’етільський Барліг. Я тепер ув’язнений у Смарагдовому Сні, безсилий зупинити це.$B$BТи мусиш мені допомогти. Шамани Ґнарлпайн носять дивний амулет, який використовується для цього ритуалу, і я хотів би його дослідити. Будь ласка, $N, принеси один мені.",
    O = "Принеси Шаманський Вуду-Амулет Обену Лютопазуру в Бан’етільський Барліг.",
    P = "Якщо я зможу перевірити чари, я, можливо, зможу зрозуміти, як зняти чари. Ви знайшли?",
    C = "Дякую, $N.$B$BWhat це дивна дрібничка... Я відчуваю мерзенну ауру, що виходить від неї; це дуже сильний приворот.",
},

[2561] = {
    en = "Druid of the Claw",
    T = "Друїд Кігтя",
    D = "Після того, як я оглянув цей амулет, $N, я зрозумів, що потрібно зробити. Візьми його і виконай моє прохання.$B$BТобі потрібно дослідити найглибші куточки Барлогу Бан’етіл. Там ти знайдеш моє бездушне тіло… Хоч мені й прикро це казати, але я не бачу іншого способу звільнитися від контролю Гнарлпайнів.$B$BЩоб я міг вирватися від них, ти мусиш убити моє фізичне тіло. Після цього використай вуду-амулет на моєму поваленому тілі. Коли виконаєш це завдання, повертайся до мене.",
    O = "Обен Лютокіготь просить вас убити його бездушне тіло, а потім використати Вуду-Амулет.",
    P = "$N, будь обережним, наближаючись до моєї фізичної форми; зачарування, під яким воно знаходиться, досить потужне.",
    C = "Нарешті я звільнився від контролю Гнарлпіну. Дякую, $N.$B$BMy дух може тепер спокійно спочивати назавжди в Смарагдовому сні.$B$BМожливо одного дня ми можемо зустрітися знову, молодий $C. Але поки що прийміть цю винагороду як символ моєї вдячності.",
},

[2581] = {
    en = "Snickerfang Jowls",
    T = "Щелепи Хихотливого Ікла",
    D = "Відомо, що щелепи гієн мають неймовірну силу, але щоб перекусити три дюйми торієвої сталі? Неможливо, неймовірно, але я бачив це на власні очі.$B$BВирушай до Спустошених Земель і принеси мені три щелепи хихотливого ікла. Під час пошуків хихотливого ікла звертай увагу на кабанів і скорпоків: для початкового аналізу також потрібні дві легені спустошеного кабана і один клешень скорпока.",
    O = "Принесіть три Щелепи Хихотливого Ікла, дві Легені Спустошеного Кабана і один Клешень Скорпока до Кровомага Дразіала.",
    P = "Ти неприємно пахнеш, $N. Чи блукали ви на сірчаних полях? А де мої компоненти?!",
    C = "Як ти почуваєшся, $N? Ви випромінюєте ауру хихикаючого ікла — ваша сила, незрівнянна смертним!$B$BUnfortunately, із компонентами, які ви мені принесли, я зміг би зробити аналіз лише для однієї таблетки. Мені знадобляться додаткові компоненти, якщо вам знадобиться інший планшет.",
},

[2582] = {
    en = "Rage of Ages",
    T = "Лють Віков",
    D = "А, $N, вітаю з поверненням. Схоже, тобі сподобався ефект міцного, дієвого настою, отриманого з хихотливого ікла. Але попереджаю, хоча короткостроковий ефект — це титанічний сплеск сили, довгострокові наслідки для твого духу та розуму можуть бути небезпечними.$B$BЗ урахуванням цього, чи потрібен тобі ще настій? Якщо так, принеси мені ще три щелепи хихотливого ікла, дві легені спустошеного кабана і один клешень скорпока.",
    O = "Принесіть три Щелепи Хихотливого Ікла, дві Легені Спустошеного Кабана і один Клешень Скорпока до Кровомага Дразіала.",
    P = "У вас є органи звіра?",
    C = "Ось ти! Пам’ятайте, використовуйте його економно. Якщо вам потрібен інший, приходьте до мене після того, як закінчите той, який у вас зараз є.",
},

[2583] = {
    en = "A Boar's Vitality",
    T = "Життєва Сила Кабана",
    D = "У цих спустошених землях живуть два види кабанів: попелегривий кабан і пеклокабан.$B$BСхоже, що витривалість цих звірів робить їх майже невразливими до шкоди, адже інші тварини вважають їх занадто складною здобиччю і, відповідно, не вартими зусиль.$B$BНам потрібно провести подальший аналіз, $N. Якщо ти принесеш мені три легені спустошеного кабана, два клешні скорпока і один мозок базиліска, я створю божественний еліксир із залишків аналізу. Ти станеш моїм першим піддослідним!",
    O = "Принесіть три Легені Спустошеного Кабана, два Клешні Скорпока і один Мозок Базиліска до Кровомага Дразіала.",
    P = "Де органи, $N!?",
    C = "Дух кабана освітлює твоє єство, $N! Цікаво, ви вважаєте себе таким же невразливим, як ці звірі?",
},

[2584] = {
    en = "Spirit of the Boar",
    T = "Дух Кабана",
    D = "Коли я вперше ввів тобі еліксир, $N, я зрозумів, що однієї чи двох доз тобі буде замало. Навіть зараз я бачу голод у твоїх очах. Цей настій має залежність, якій, здається, не можуть опиратися навіть найсильніші духом.$B$BНехай буде так! Якщо тобі потрібно більше коктейлю з легеневого соку, вирушай назад у пустку і добудь мені три легені спустошеного кабана, два клешні скорпока і один мозок базиліска.",
    O = "Принесіть три Легені Спустошеного Кабана, два Клешні Скорпока і один Мозок Базиліска до Кровомага Дразіала.",
    P = "Де органи, $N!?",
    C = "Мушу попередити вас, $N, не намагайтеся змішувати створені мною формули. Хімічні властивості формули, яку ви нещодавно проковтнули, завжди матимуть перевагу над колишніми чарами; таким чином, роблячи інше формулювання нульовим.",
},

[2585] = {
    en = "The Decisive Striker",
    T = "Рішучий Ударник",
    D = "Чи бачив ти їх у бою, $N? Я про скорпоків. Чи помічав ти грацію і спритність, з якою вони рухаються? Точність їхніх ударів?$B$BЯкби ми могли якось ізолювати цю спритність і замкнути її в предметі, ми б розбагатіли… тобто… це стало б великим внеском у наукову спільноту.$B$BДопоможи мені, $N, і я дозволю тобі скуштувати результат аналізу.$B$BЩоб створити стабільний зразок, мені потрібно три клешні скорпока, два шлунки грифа і одну легеню спустошеного кабана.",
    O = "Принесіть три Клешні Скорпока, два Шлунки Грифа і одну Легеню Спустошеного Кабана до Кровомага Дразіала.",
    P = "Де органи, $N!?$B$B",
    C = "захоплюючий. Це було найскладніше з усіх аналізів для аналізу.$B$BTake дрібку цієї залишкової солі та покладіть під язик. Ви повинні відчути легке відчуття ейфорії, а потім стан безпрецедентної спритності та швидкості.",
},

[2586] = {
    en = "Salt of the Scorpok",
    T = "Сіль Скорпока",
    D = "Ти живий! Це справді хороші новини. Гадаю, ти повернувся за ще однією порцією аналізу скорпока?$B$BДуже добре, $N, вирушай назад у пустку і не повертайся, доки не збереш три клешні скорпока, два шлунки грифа і одну легеню спустошеного кабана.",
    O = "Принесіть три Клешні Скорпока, два Шлунки Грифа і одну Легеню Спустошеного Кабана до Кровомага Дразіала.",
    P = "Де органи, $N!?",
    C = "Чудова робота, $N. Ось один зразок аналізу для вас, а решта дев’ять буде використано в моєму дослідженні.$B$BAnytime вам потрібно більше аналізу меленого скорпоку, поверніться до мене, і ми домовимося.",
},

[2601] = {
    en = "The Basilisk's Bite",
    T = "Укус Базиліска",
    D = "Ці пустки кишать червоними базилісками, $N. Ці базиліски адаптувалися і процвітають краще, ніж будь-яка інша дика природа в регіоні.$B$BЯ спостерігав здалеку, як вони полюють і займаються своїми щоденними справами — ці звірі демонструють розумові процеси, складніші, ніж у деяких гуманоїдів.$B$BМені потрібні їхні мізки для вивчення!$B$BДобудь мені десять їхніх мізків, $N. Однак суміш не буде повною без двох шлунків грифа, які слугуватимуть основою розчину.",
    O = "Принесіть десять Мізків Базиліска і два Шлунки Грифа до Кровомага Ліннор.",
    P = "Ви повернулися із запитаними органами?",
    C = "Це чудово, $N! Я пропоную вам спробувати внутрішню роботу василіска з червоного каменю.$B$BShould суміш буде на ваш смак, завжди можна зробити більше... за певну ціну.",
},

[2602] = {
    en = "Infallible Mind",
    T = "Непохитний Розум",
    D = "Твоя зосередженість так швидко згасла? Потрібно більше досліджень!$B$BТак, ціна залишається такою ж, $N. Вирушай у Спустошені Землі і повертайся до мене з десятьма мізками червоних базилісків і двома шлунками грифа.",
    O = "Принесіть десять Мізків Базиліска і два Шлунки Грифа до Кровомага Ліннор.",
    P = "Ви повернулися із запитаними органами?",
    C = "Так, так, дайте мені хвилинку, і більше суміші буде готове для споживання, $N.$B$BTake це... і $N, не намагайтеся споживати ці експериментальні суміші поспішно. Результати можуть бути катастрофічними.",
},

[2603] = {
    en = "Vulture's Vigor",
    T = "Сила Грифа",
    D = "Смерть у цих спустошених землях справді має крила, $r. Я бачив, як чорні різники і кісткодери гніздяться на трупах багатьох загиблих дослідників — іноді пожираючи найбридкіші і найзаразніші туші. Дивно, як їхня внутрішня система долає мор, що панує в цих землях.$B$BДопоможи мені у моїх дослідженнях, $N! Мені потрібні шлунки! Також знадобляться дві щелепи хихотливого ікла для основи настоянки.$B$BТвої зусилля будуть винагороджені подвійно.",
    O = "Принесіть десять Шлунків Грифа і дві Щелепи Хихотливого Ікла до Кровомага Ліннор.",
    P = "Не витрачай мій час, $N. Нам нема чого обговорювати, якщо ви не повернули предмети, які я просив.",
    C = "Найбільш відмінно! Я негайно приступлю до роботи. Можливо, можна знайти ліки від багатьох хвороб світу!$B$BAh Так, ваша нагорода - звичайно, якщо вам знадобиться більше жуйки, поверніться до мене, і вам буде дано інше завдання.",
},

[2604] = {
    en = "Spiritual Domination",
    T = "Духовне Панування",
    D = "Я бачу, що твій внутрішній вогонь згас. Чи можеш сказати, що духовна ейфорія тривала годину?$B$BЯкщо тобі потрібен ще шлунковий клей, то мені потрібні ще шлунки. Назад у пустку, $N. Не повертайся, доки не збереш десять шлунків і дві щелепи.",
    O = "Принесіть десять Шлунків Грифа і дві Щелепи Хихотливого Ікла до Кровомага Ліннор.",
    P = "Не витрачай мій час, $N. Нам нема чого обговорювати, якщо ви не повернули предмети, які я просив.",
    C = "Можливо, одного дня я зможу виділити активні ферменти цього аналізу та отримати набагато ефективніший результат. На жаль, вам доведеться задовольнитися тим, що я зараз здатний виробляти. Поверніться до мене, якщо вам знадобиться більше жуйки.",
},

[2605] = {
    en = "The Thirsty Goblin",
    T = "Спраглий Гоблін",
    D = "У мене є ідея, бачиш. Я чув про дивних створінь, яких називають збирачами роси, що живуть на південний захід… і що вони здатні зберігати воду в особливих залозах.$B$BДумаю, якщо я зможу дістати одну з цих залоз, я зможу створити напій, який втамує мою страшну спрагу! Чи можеш ти мені допомогти, $N?$B$BШукай кактусовий сад, $N; там ти знайдеш збирачів роси.",
    O = "Зберіть Наповнену Залозу Роси і принесіть її Маріну Ноггенфоггеру в Ґаджетзані.",
    P = "Скажіть, будь ласка, ви знайшли росозбірники?",
    C = "О, чудово! Дай сюди — дай мені випити!",
},

[2606] = {
    en = "In Good Taste",
    T = "На Хороший Смак",
    D = "Фу! Це на смак просто жахливо! Так собі ідея…$B$BСтривай, що це? О, я знаю, знаю, ти думаєш, що я не повинен здаватися з цією штукою. Ну, добре тоді.$B$BАх, у мене є ідея! Чудово! Віднеси цю росу моїй подрузі Спрінкл — вона чудова кухарка. Скажи їй, що ми тут задумали, і що ми хочемо зробити так, щоб це було легше пити.$B$BТобто, якщо це так погано на смак, то принаймні має бути з перцем… А я цього просто не відчуваю…",
    O = "Марін Ноггенфоггер просить вас поговорити зі Спрінкл у Ґаджетзані.",
    P = "Отже, старий Марін знову задумав, еге ж? З чого зроблена ця суміш?",
    C = "Марін хороший хлопець, не зрозумійте мене неправильно – просто трохи... ексцентричний, я б сказав.$B$BAnd, звичайно, йому знову потрібна моя допомога.",
},

[2607] = {
    en = "The Touch of Zanzil",
    T = "Дотик Занзіла",
    D = "Схоже, ти приніс більше інформації, ніж я очікував. Це дійсно несподіваний поворот подій, $N.$B$BЛіки? Хм… Спускайся до підвалу і поговори з Доком Міксілпіксілом — він, можливо, зможе допомогти.",
    O = "Поговоріть із Доком Міксілпіксілом у підвалі Бараків.",
    P = "",
    C = "Настав час! Просто покладіть сир на стіл і побийте. Осборн заплатить тобі на виході.",
},

[2608] = {
    en = "The Touch of Zanzil",
    T = "Дотик Занзіла",
    D = "Ох, ти виглядаєш як смерть. Поправка — я бачив смерть, ти виглядаєш гірше за смерть. Ти, $g пане:пані;, виглядаєш так, ніби смерть відкашляла тебе на своєму останньому огляді.$B$BХа! Чув це, Норме? Запиши цю фразу!$B$B*Кашель* Хм, так, щоб допомогти тобі, мені потрібно взяти трохи крові. Не хвилюйся, це боляче лише перші… ну, разів п’ятдесят… /лягай, коли будеш готовий до процедури, $N.",
    O = "/Лягайте, щоб Док Міксілпіксіл вас оглянув. Як він може знайти ліки, якщо не знайде причину?",
    P = "Коли ви будете готові до обстеження, ляжте на землю, і я почну флеботомію.",
    C = "Дайте мені хвилину поговорити з моїми колегами, $N. Доктор Монтгомері, містере Ноарм, давайте нараду!",
},

[2609] = {
    en = "The Touch of Zanzil",
    T = "Дотик Занзіла",
    D = "Це одноголосно, $N. У тебе ‘ітіс’.$B$BНа щастя, у мене є ліки від ‘ітісу’.$B$BОсь що мені потрібно: один пучок простих польових квітів, один свинцевий флакон, одну бронзову трубку і, нарешті, але не менш важливо, одну котушку світло-шартрезової шовкової нитки. Стара Емма залишила мені таку котушку в крамниці ‘Найтонша Нитка’. Ти знайдеш крамницю вздовж каналів.$B$BПоспіши, $N, і намагайся нікого не торкатися, доки не вилікуєшся. О, і доктор Монтгомері каже, що тобі потрібен душ — його слова, не мої.",
    O = "Принесіть Доку Міксілпіксілу один Пучок Простих Польових Квітів, один Свинцевий Флакон, одну Бронзову Трубку і одну Котушку Світло-Шартрезової Шовкової Нитки. ‘Ітіс’ сам по собі не лікується, молодий $g хлопче:дівчино;.",
    P = "Якщо ви хочете вилікувати хворобу, вам доведеться більше постаратися, $n. Де реагенти для лікування?",
    C = "що я роблю Що, схоже, я роблю? Я винаходжу ліки від вашого ",
},

[2621] = {
    en = "The Disgraced One",
    T = "Збезчещений",
    D = "Жаль. Це все, що в мене залишилося. Одне погане рішення призвело до кількох жахливих наслідків. Якби я тільки дочекався тих наказів. Можливо, вони б описували жахи, що чекали на нас у тих проклятих землях! Можливо, вони б перенаправили нас на інше завдання? У підсумку, це була моя провина. Усе це моя провина.$B$BТож я стою тут, чекаючи наказів. Я мушу знати. Мені потрібні ці накази.$B$BКомандир-диспетчер Руаґ перебуває в Стонарді. Знайди його і дізнайся, що сталося з наказами.",
    O = "Поговоріть із Командиром-диспетчером Руаґом у Стонарді.",
    P = "",
    C = "Хватка Трала... Ця історія ще свіжа в моїй пам’яті.$B$B<Командор Руаг хитає головою>$B$BTerrible те, що сталося з тим полком. Орда втратила кількох своїх найкращих вояків, коли той батальйон був знищений.",
},

[2622] = {
    en = "The Missing Orders",
    T = "Зниклі Накази",
    D = "Накази? Що тобі може бути потрібно від тих наказів?$B$BНа що ти натякаєш, $N? Звісно, я передав ті накази! Солдати, яких я послав із наказами, потрапили в засідку і були жорстоко побиті мурлоками. Лише один вижив, якщо це можна назвати виживанням. Він ледве говорить, не може ходити і його годують через трубку. Якщо хочеш знати, що сталося з тими наказами, поговори з Бенґором. Я впевнений, він десь тут… і, $N, будь обережний із тим, куди сунеш свій ніс — його можуть відкусити.",
    O = "Поговоріть із Бенґором.",
    P = "",
    C = "Болотний тал... балак.. балакун...$B$B",
},

[2623] = {
    en = "The Swamp Talker",
    T = "Болотний Говорун",
    D = "Накази були видані командиром-диспетчером. Ми взяли… взяли накази. По дорозі до Спустошених Земель нас атакували.$B$BМурлоки… Багато мурлоків… Один на ім’я Болотний Говорун. Забрав накази з моїх рук, коли спис пронизав мій череп. Схід… печера…$B$B<Бенґор знепритомнів.>",
    O = "Дістаньте Накази Вождя і поверніть їх до Полеглого Героя Орди.",
    P = "Чекаю замовлення.",
    C = "Це гірше, ніж я собі уявляв. Дев'ятнадцять моїх людей могли б бути врятовані від агонії, з якою вони зіткнулися. Якби тільки я не діяв так нераціонально.$B$BYou повинен допомогти їм, $N! Я безсилий діяти.",
},

[2641] = {
    en = "Sprinkle's Secret Ingredient",
    T = "Секретний Інгредієнт Спрінкл",
    D = "Коли я був малим, моя сестра готувала всю їжу. Це було жахливо! Я ледве міг їсти деякі з її страв — доки не знайшов те, що я називаю своїм «секретним» інгредієнтом! Додай його до будь-чого, і… ВАУ! Смакує чудово!$B$BЩо це, запитаєш? Це гриб під назвою Фіолетовий Траґан. Якщо хочеш, щоб я допоміг тобі перетворити цей огидний на смак вариво на щось їстівне, вирушай до Внутрішніх Земель і шукай там маленьке озеро.$B$BО, і пам’ятай, Фіолетовий Траґан можна знайти лише під водою.",
    O = "Спрінкл у Ґаджетзані просить вас зібрати Фіолетовий Траґан і повернути його їй.",
    P = "Під водами цього озера — це єдине місце, де можна знайти фіолетовий траган.  Сподіваюся, ви добре вмієте затримувати дихання!",
    C = "Ось і все, $N!$B$BIt виглядає так добре, я міг би просто... Ха-ха, зрозумів!",
},

