},

[2773] = {
    en = "The Mithril Kid",
    T = "Міфриловий Хлопець",
    D = "Тут мене знають як Міфрилового Хлопця. Я постачаю оздоблений міфрил для шукачів пригод по всьому світу.$B$B<Трентон шепоче.>$B$BАле мало хто знає, що я не вмію створювати оздоблені міфрилові рукавиці. Тсс! Це буде наш маленький секрет.$B$BНавчи мене техніки створення оздоблених міфрилових рукавиць, $N, а я в обмін покажу тобі вершину мого навчання під керівництвом Ґалвана: оздоблений міфриловий нагрудник.",
    O = "Принеси два важких міфрилових нагрудники та одні оздоблені міфрилові рукавиці до Трентона Світломолота.",
    P = "Ви закінчили створення предметів, $N?",
    C = "Дякую тобі за все, чого ти мене навчив, $N. Майстер і командир вишуканого міфрілового набору незабаром буде у вашому розпорядженні.$B$BBehold!",
},

