},

[2986] = {
    en = "Call of Water",
    T = "Поклик Води",
    D = "Минуло чимало часу з твоєї останньої перевірки, $N. Ти досі виявляв терпіння у своїх заняттях, але настав час дізнатися більше. Настав час тобі дізнатися про чистоту води.$B$BШукай Іслен Водовидицю в Степах. Вона живе на східному узбережжі, на південь від річки Південної Люті та Ратчета. Ти знайдеш її там у її рибальській хатині. Удачі тобі, $N.",
    O = "Знайди Іслен Водовидицю в Степах.",
    P = "",
    C = "",
},

[2987] = {
    en = "Gordu$b$bi Cobalt",
    T = "Кобальт Ґордунні",
    D = "Я щойно прибув до Фераласу, і чув, що оґри Ґордунні, які населяють тутешні дикі землі, мають цікаві мінерали. Хтозна, що вони задумали, але вони точно охороняють ці речі! Вони не залишають їх просто так лежати; ні, вони закопують їх, щоб такі, як я, не могли до них дістатися.$B$BЯкщо ти готовий, я дам тобі свою лопату. Вирушай до форпосту Ґордунні на північ звідси і викопай мені трохи кобальту Ґордунні. Шукай синє сяйво, а потім починай копати!",
    O = "Орвін Ґіззмік у Таборі Моджаче хоче 12 зразків Кобальту Ґордунні.",
    P = "Підніміться туди й почніть копати!$B$BI Є куди піти і на кого подивитися – час – гроші!",
    C = "Ідеально! Я візьму їх із собою, коли продовжу свою подорож, $N. Я впевнений, що знайду когось, хто заплатить чималі копійки за цей кобальт.$B$BHere, візьміть це собі за клопіт.",
},

[2988] = {
    en = "Witherbark Cages",
    T = "Клітки Вітербарк",
    D = "Син нашого наймогутнішого грифона зник! Спадкоємець Свистокрила, Гостродзьоб, пропав кілька днів тому під час полювання з батьками, і ми вважаємо, що його забрали тролі.$B$BТи мусиш нам допомогти! Перевір клітки в двох селах тролів Вітербарк, щоб дізнатися, чи там Гостродзьоб.",
    O = "Перевір клітки в двох селах тролів Вітербарк, а потім повернися до Майстра Грифонів Кігтесоки.",
    P = "Ти обшукав клітки, $N? Ми повинні знайти Гостродзьоба!",
    C = "Гостродзьоба на селах не було?  Хм... це жахлива новина.  Цьому грифону судилося очолити наступне покоління грифонів.  Якщо він буде втрачений, сила і дух нашого флоту постраждають надзвичайно.",
},

[2989] = {
    en = "The Altar of Zul",
    T = "Вівтар Зула",
    D = "Гостродзьоба не було серед тролів Вітербарк. Можливо, його забрали тролі Вайлбренч. Вирушай до Вівтаря Зула на західному краю території Вайлбренч і шукай дитинча грифона.",
    O = "Перевір верхівку Вівтаря Зула, а потім повернися до Майстра Грифонів Кігтесоки.",
    P = "Поспішайте, $N!  Якщо тролі Мерзенної гілки мають Гостродзьоба, то хто знає, що вони з ним роблять!",
    C = "Гостродзьоба не було?  Це погані новини, але це також гарні новини...$B$BIt Добре, що він не був біля вівтаря Зула, оскільки тролі Мерзенної гілки відомі тим, що приносять жертви.$B$BI дякую вам за допомогу, але, боюся, попереду у мене ще більше завдання.",
},

[2990] = {
    en = "Thadius Grimshade",
    T = "Тадіус Тіньозор",
    D = "Візьми це перо до Тадіуса Тіньозора, віщуна. Він покинув Пік Аерії багато років тому, щоб вивчати темні знання, але в душі він все ще Дикий Молот!$B$BМожливо, його таланти допоможуть нам знайти Гостродзьоба.$B$BЦе перо було взято з гнізда, де спить дитинча грифона. Якщо ти даси його Тадіусу, то, з удачею, він зможе використати свої віщі магії, щоб знайти Гостродзьоба.$B$BУдачі, $N. Ти знайдеш Тадіуса у Вибухових Землях, у магічній вежі Фортеці Пекловарта.",
    O = "Принеси Перо Гостродзьоба до Тадіуса Тіньозора у Вибухові Землі.",
    P = "$N, ти прийшов з подарунком?",
    C = "Ах, так.  Це пір'я належить до гарного грифона.  Той, хто приречений на великі справи... якщо він зможе дожити до дорослого життя неушкодженим.$B$BYou хочете знайти його?  Тоді слухай уважно, сміливий $C...",
},

[2991] = {
    en = "Nekrum's Medallion",
    T = "Медальйон Некрума",
    D = "Я дізнаюся, де твій грифон, але спочатку ти мусиш дещо для мене зробити. У Зул’Фарраку є троль на ім’я Некрум Кишкороздирач, який володіє медальйоном, що я дуже хотів би вивчити. Принеси мені цей Медальйон, і я використаю свої сили, щоб знайти Гостродзьоба.$B$BЗул’Фаррак знаходиться за океаном на заході, у пустелі Танаріс.",
    O = "Принеси Медальйон Некрума до Тадіуса Тіньозора у Вибухові Землі.",
    P = "У вас є Медальйон Некрума, $N?  У ньому приховані сили, які я хочу відкрити.",
    C = "Ах, медальйон Некрума.  Подейкують, що це дало тролю неприродне довге життя, але дорогою ціною.  Я сподіваюся знайти спосіб скористатися силою медальйона, уникнувши його... неприємних побічних ефектів.$B$BYou зробили мені послугу, $N.  Тепер я підтримаю свою частину нашої угоди.",
},

[2992] = {
    en = "The Divination",
    T = "Віщування",
    D = "Дай мені місце, поки я виконую ритуал віщування. Я знайду зв’язок між пером, яке ти мені приніс, і його власником, і простежу цей зв’язок до самого Гостродзьоба.$B$BТобто... я зроблю це, якщо все піде за планом. Якщо ні, то... краще заплющ очі.",
    O = "Зачекай, поки Тіньозор виконає ритуал віщування.",
    P = "",
    C = "Ритуал вдався.  Я бачив Гостродзьоба і можу сказати, як його знайти.",
},

[2993] = {
    en = "Return to the Hinterlands",
    T = "Повернення до Гінтерлендів",
    D = "Гостродзьоб утримується в клітці, високо на скелі на вершині Джинта’Алору в Гінтерлендах. Ключ до цієї клітки має верховна жриця тролів Вайлбренч, Погана Жриця Геккс.$B$BОсь. Я виконав свою частину. Бажаю тобі удачі в твоєму завданні, $N.",
    O = "Поговори з Майстром Грифонів Кігтесокою.",
    P = "",
    C = "Ви говорили з Гримшейдом?  Що він сказав?$B$B...Що?  У тролів Мерзенної гілки є Гостродзьоб?  Це нестерпно!  Ми повинні організувати сили, щоб повернути його!",
},

[2994] = {
    en = "Saving Sharpbeak",
    T = "Порятунок Гостродзьоба",
    D = "Ми мусимо врятувати Гостродзьоба!$B$BПробийся до вершини Джинта’Алору в самому серці території Вайлбренч, добудь ключ до клітки Гостродзьоба у Поганої Жриці Геккс, а потім знайди і врятуй Гостродзьоба!",
    O = "Пробийся до вершини Джинта’Алору, убий Погану Жрицю Геккс, щоб отримати ключ до клітки Гостродзьоба, і врятуй Гостродзьоба.",
    P = "Врятуйте Гостродзьоба!",
    C = "Швидкий Вітер і Кінкло повернулися зі своєю дитиною кілька хвилин тому і метушаться навколо нього, як новоспечені батьки.  Знову побачити їх разом достатньо, щоб навіть у цього старого карлика в очах з’явився туман... $B$BWe не може відплатити тобі достатньо за те, що ти зробив, $N.  Грифони вершини Ері та їхні вершники співатимуть твоє ім’я ще довго, довго.",
},

[2995] = {
    en = "Lines of Communication",
    T = "Лінії зв’язку",
    D = "Ложа Квел’Даніл — це центр комунікації для вищих ельфів Гінтерлендів. Їхні посли працюють над встановленням зв’язків з іншими расами, з якими вони діляться знаннями про тролів Вітербарк, що населяють південні Гінтерленди. Усі документи щодо комунікацій зберігаються в ложі.$B$BНам не потрібні альянси Високодолів з іншими, $N.$B$BЗнищ документи Високодолів. Нам потрібно спалити їхні лінії зв’язку... буквально.",
    O = "Оран Змієпись у Підмісті хоче, щоб ти вирушив до Гінтерлендів і спалив Записи Високодолів, Звіт Високодолів і Нотатки Високодолів.",
    P = "Головне – тримати ельфів Хайвейла в ізоляції. Ви знайшли будиночок?",
    C = "Чудово, $N. Поки Хайвейл працюватиме над відновленням втраченої інформації, ми зможемо перекрити лінії ще далі...",
},

[2996] = {
    en = "Seeking Strahad",
    T = "У пошуках Страхада",
    D = "Я навчав тебе навичкам у минулому, але настав час, щоб тебе навчав інший. Його звати Страхад, і він у Ратчеті. Він людина, але не дозволяй цьому змусити тебе думати, що він слабкий. Він могутній, хоч і може бути малим. Він може навчити тебе про потужніші виклики — я відчуваю, що ти готовий. Вирушай до нього зараз. Він у Ратчеті... над портовим містом біля його вежі.",
    O = "Поговори зі Страхадом Фарсаном у Ратчеті.",
