},

[3042] = {
    en = "Troll Temper",
    T = "Загартовувач тролів",
    D = "Тролі Піщанної Люті з Зул’Фаррака виготовляють загартовувальний агент із пісковиків, і я можу використати його для загартування речей, які я створюю, так, можу! Він високо цінується знавцями, тож якщо ти принесеш мені хороший запас цього загартовувача, я добре тебе винагороджу.$B$BЗул’Фаррак знаходиться на північний захід від Ґаджетзана. Удачі.",
    O = "Принеси 20 Фіалок із Загартовувачем Тролів до Трентона Легкомолота в Ґаджетзані.",
    P = "Ти приніс мені вдачу, $N?",
    C = "Ах, це справді дуже гарна вдача! І так багато! Я пробуду на роботі кілька днів, перш ніж використати все це!$B$BThank ти, $N. Будь ласка, прийміть це як оплату.",
},

[3062] = {
    en = "Dark Heart",
    T = "Темне серце",
    D = "Едана Ненависталон — королева гарпій Північного Джерела, що мешкають у руїнах на заході. Вона втілення зла; я чув, що її серце — це кристал. Вона позбавлена будь-яких емоцій, крім ненависті, яку відчуває до всіх інших. Ти мусиш зіткнутися з Еданою і принести мені її темне серце.$B$BЯ чув про ріг, який носять гарпії — якщо затрубити ним біля каменів Ненависталон у північній частині руїн, це викличе королеву.$B$BУяви її здивування, коли замість її родичів її покличе смерть.",
    O = "Тало Тернове Копито в Таборі Моджаче хоче Темне Серце Едани Ненависталон.",
    P = "Ненависть, яку Едана поширює по країні, має бути зупинена.",
    C = "Тепер я знаю, що Едана справді мертва. Це серце; Я збережу це на згадку про те, що зробив тут для мене, $N. дякую",
},

[3063] = {
    en = "Vengeance on the Northspring",
    T = "Помста на Північному Джерелі",
    D = "За моїх часів я був досвідченим мисливцем. Не було жодної істоти, якої б я боявся. Доки...$B$BЯ був у лісі, гострив своє лезо після важкої битви, коли на мене напали. Гарпії оточили мене, і я ледь зміг дотягнути себе до безпечного місця.$B$BНавіть зараз я все ще чую їхні крики, що лунають...$B$BЯ ніколи не був тим самим після того. Але ненависть кипить у мені — я мушу помститися, після всіх цих років.$B$BГарпії Північного Джерела знаходяться на захід звідси. $N, здійсни мою помсту.",
    O = "Тало Тернове Копито хоче, щоб ти вбив 4 Гарпії Північного Джерела, 4 Розбійниць Північного Джерела, 4 Заклиначок Вітру Північного Джерела і 4 Убивць Північного Джерела.",
    P = "Крила гарпій Північної Весни чорні, як ніч; не зводь з них очей, щоб вони не зникли в темряві.",
    C = "Дякую, $N. Ви заспокоїли розум старого таурена.",
},

