[3065] = {
    en = "Simple Tablet",
    T = "Простий планшет",
    D = "Ах, поки тебе не було, для тебе прийшов пергамент, $N.$B$BПрочитай його, коли матимеш час. Якщо я не помиляюся, він від тренера воїнів Франґа. Він хоче поговорити з тобою, коли ти будеш готовий. Ти знайдеш його біля Ліґва, у затінку.",
    O = "Прочитай Простий Пергамент і поговори з Франґом у Долині Випробувань.",
    P = "Ще один $R для зміцнення рядів. Досить добре для мене.$B$BYou, ймовірно, буде важко тримати хорошу зброю, як-от сокиру, але спис так само хороший, як і будь-що інше.$B$BWelcome до Долини Випробувань.",
    C = "Ви знайдете це місце підходящим, якщо продовжите тренуватися воїнським способом. Якщо у вас виникнуть запитання, не соромтеся запитувати будь-кого, а коли будете готові, повертайтеся до мене на навчання. Я опанував стільки ж, скільки будь-який воїн тут, у Долині, і можу передати ці знання вам... за певну ціну.",
},

[3082] = {
    en = "Etched Tablet",
    T = "Вигравіюваний планшет",
    D = "Ах, поки тебе не було, для тебе прийшов планшет, $N.$B$BПрочитай його, коли матимеш час. Якщо я не помиляюся, він від тренера мисливців Джен’шан. Вона хоче поговорити з тобою, коли ти будеш готовий.",
    O = "Поговори з Джен’шан у Долині Випробувань.",
    P = "Джен'шан бачить могутнього $C перед нею, і духи da схвалюють.$B$BDa шлях da $C є одним із наших найдавніших шляхів життя. Да Орда звернувся до нас, коли вони тільки намагалися вижити в Азероті, і вони просять нас навчити їх, показати їм секрети багатьох тингів. Вони вже були сильними: сильними шаманськими способами; сильний у воїні. Але шлях мисливця не буде їхнім шляхом... тоді.",
    C = "Тепер ми вчимо їх тим речам, а вони вчать нас іншим. Ми стаємо однією расою... майже. Ми вже давно союзники. Тож ви не забудьте їм допомогти. І Джен'шан не забудь тобі допомогти.$B$BJen'шан навчить тебе способам мисливця — навчить тебе добра. Ніколи не забувайте, плем’я дуже поважає $C. Вам належить відіграти важливу роль у майбутньому... ви ніколи цього не забудете.$B$BWhen відчуваєте потребу, приходьте до Дженьшана. Вона навчить вас стільки, скільки зможе, коли відчує, що ви готові.",
},

[3083] = {
    en = "Encrypted Tablet",
    T = "Зашифрований планшет",
    D = "Ах, поки тебе не було, для тебе прийшов планшет, $N.$B$BПрочитай його, коли матимеш час. Якщо я не помиляюся, він від тренера розбійників Рваґа. Він хоче поговорити з тобою, коли ти будеш готовий.",
    O = "Прочитай Зашифрований Планшет і поговори з Рваґом у Долині Випробувань.",
    P = "Ласкаво просимо в Долину Випробувань, Рангранг. Вас би тут не було, якби ви не отримали мою табличку, тож я перейду до суті.$B$BI Я Рваг, і я відповідаю за навчання шахраїв, злодіїв і головорізів тут, у Долині. Я той, до кого Рука звернеться, якщо ти не готовий до того, що має статися. Але не хвилюйтеся, Рука не буде контролювати все, що ви робите, але було б розумно попрацювати з ними, якщо вони потребують ваших талантів.",
    C = "Поки цей час не настане, ти будеш під моєю опікою. Я покажу вам мотузки, як деякі люди кажуть. Щоразу, коли ви відчуєте, що готові, приходьте до мене, і я подбаю про подальше навчання вас. А до того часу практикуйте свої навички та відточуйте їх до леза бритви. Ви ніколи не знаєте, коли вам знадобиться навіть найнезначніша здатність.",
},

[3084] = {
    en = "Rune-Inscribed Tablet",
    T = "Планшет із Рунами",
    D = "Ах, поки тебе не було, для тебе прийшов планшет, $N.$B$BПрочитай його, коли матимеш час. Якщо я не помиляюся, він від тренера шаманів Шікрік. Вона хоче поговорити з тобою, коли ти будеш готовий.",
    O = "Поговори з Шікрік у Долині Випробувань.",
    P = "Ласкаво просимо, $N. Я радий, що ви приїхали. Мої дні стали довгими і навіть зайнятими, оскільки викладати так багато студентів, але прихід одного з вас подібних приносить мені велике відчуття досягнення - я пам’ятаю дні, коли мене навчав один із ваших шаманів.",
    C = "Як ви, мабуть, знаєте, стихії дають нам силу. Вогонь, земля, вода й повітря — ось наші інструменти.$B$BOur сила походить від духів наших предків. Ми лідери нашого народу. Як Тралл для Орди, так і ми будемо ставитися до сіл і міст, які відвідуємо. Вони шукатимуть у нас мудрості та захисту. Щоб бути краще підготовленим, потрібно часто тренуватися. Коли ви відчуєте, що здобули більше сили, приходьте до мене, і я навчу вас, чого вмію.",
},

[3085] = {
    en = "Hallowed Tablet",
    T = "Освячений планшет",
    D = "Ах, поки тебе не було, для тебе прийшов планшет, $N.$B$BПрочитай його, коли матимеш час. Якщо я не помиляюся, він від тренера жерців Кен’джая. Він хоче поговорити з тобою, коли ти будеш готовий.",
    O = "Прочитай Освячений Планшет і поговори з Кен’джаєм біля Ліґва в Долині Випробувань.",
    P = "Отже, ви зробили це... добре, добре! Та духи сказали мені, що ти незабаром приїдеш до Кен’джая. Дозвольте мені першим привітати вас у Долині Випробувань. Це місце не буде вашим домом надовго, але поки воно є, чому б не зробити його найкращим.",
    C = "Перевіривши себе, ви побачите, що у вас краще й краще контролюються алкогольні напої — ви будете дзвонити про великі та чудові моменти... ось тут і з’являється старий Кен’джай. Ви приходите поговорити з Оле Кен’джаєм, коли відчуєте, що готові. Якщо духи погодяться, ми бачимо, що ми навчимо вас потужнішим здібностям... але лише якщо духи погодяться.$B$BGo тепер поговоріть з іншими людьми da Valley. Поговори зі мною пізніше.",
},

[3086] = {
    en = "Glyphic Tablet",
    T = "Гліфічний планшет",
    D = "Ах, поки тебе не було, для тебе прийшов планшет, $N.$B$BПрочитай його, коли матимеш час. Якщо я не помиляюся, він від тренера магів Май’ах. Вона хоче поговорити з тобою, коли ти будеш готовий.",
    O = "Прочитай Гліфічний Планшет і поговори з Май’ах біля входу до Ліґва в Долині Випробувань.",
    P = "Ти вже хочеш догодити Майа, $N. Хай буде добре. Ви поважаєте Майа, а Майа, можливо, поверне вам повагу. Але досить, ти тут, щоб вчитися магії, а не слухати розмови Майа.$B$BThere лише одне, що Май’а не може навчити тебе магії, $N, і цьому, як зупинити корупцію.",
    C = "Ви будете серед наймогутніших істот на планеті, $N... про це не сперечаються. І всі це знають... теж добре це знають!$B$BBut ти, мабуть, втомився! бо це не орки, чи ельфи, чи гноми, яких тобі варто боятися... це побачення, яких ти не можеш побачити. Магія будь сильною. Змусити вас робити те, що ви, можливо, не хочете робити. Зробіть так, щоб ви вважали себе могутнішим, ніж насправді. Наберіться терпіння. Будь кмітливим.$B$BWhen Здається, ти готовий до тренувань, повертайся до Майа. Вона навчить вас того, чого ви готові навчитися, без проблем.",
},

[3087] = {
    en = "Etched Parchment",
    T = "Вигравіюваний пергамент",
    D = "Ах, поки тебе не було, для тебе прийшов пергамент, $N.$B$BПрочитай його, коли матимеш час. Якщо я не помиляюся, він від тренера мисливців Джен’шан. Вона хоче поговорити з тобою, коли ти будеш готовий.",
    O = "Прочитай Вигравіюваний Пергамент і поговори з Джен’шан у Долині Випробувань.",
    P = "Ах, нарешті ви прийшли. добре. Джен'шан чекає на вас.$B$BMany Здається, це легкий шлях, але Джен'шан скаже вам, що це неправда. Оволодіння звірами Дуротару та поза ним потребує стільки ж навичок, скільки оволодіння таємничими мистецтвами або розмова з нашими предками.$B$BFirin' лук чи рушниця можуть бути не такими небезпечними для вас, як використання заклинань, але вони точно небезпечні для вашого ворога.",
    C = "Коли ми закінчимо розмову, тобі слід поговорити з рештою громадян у Долині. Вони просять вас зробити для них речі... дії, які перевірять ваші навички та навчать вас деяких небезпек цієї землі.$B$BAs ви зростаєте в досвіді та мудрості, вам знадобиться Джен'шан, щоб показати вам кращі техніки та навички. Часто повертайтеся до Дженьшана. Я дам вам знати, чого я можу вас навчити.",
},

[3088] = {
    en = "Encrypted Parchment",
    T = "Зашифрований пергамент",
    D = "Ах, поки тебе не було, для тебе прийшов пергамент, $N.$B$BПрочитай його, коли матимеш час. Якщо я не помиляюся, він від тренера розбійників Рваґа. Він хоче поговорити з тобою, коли ти будеш готовий.",
    O = "Прочитай Зашифрований Пергамент і поговори з Рваґом у Долині Випробувань.",
    P = "Тссс, не так голосно. Я там Нартоку не довіряю. Не варто жартувати з тими, хто змушений ховатися в печері глибше, ніж я.$B$BI вірите, у вас не було проблем з орієнтуванням?",
    C = "Тепер, коли ви знаєте, де я тримаюся, я повинен повідомити вам: Розтрощена рука попросила мене піклуватися про вас. Вони хочуть, щоб я навчав вас і повідомляв про все, що їм може знадобитися. Навіть якщо ви ще не зацікавлені в тому, щоб допомогти їм, а ви були б дурнем не бути, я зроблю все можливе, щоб навчити вас... за невелику плату. Повертайтеся до мене в будь-який час, коли ви будете готові, і ми побачимо, чого ви готові навчитися.",
},

[3089] = {
    en = "Rune-Inscribed Parchment",
    T = "Пергамент із Рунами",
    D = "Ах, поки тебе не було, для тебе прийшов пергамент, $N.$B$BПрочитай його, коли матимеш час. Якщо я не помиляюся, він від тренера шаманів Шікрік. Вона хоче поговорити з тобою, коли ти будеш готовий.",
    O = "Прочитай Пергамент із Рунами і поговори з Шікрік у Долині Випробувань.",
    P = "Отже, ви приїхали. Мені було цікаво, коли ти покажешся. Я надіслав пергамент деякий час тому – я не був упевнений, чи він надійшов.$B$BBut досить балаканини... ви тут, тому що вас вибрали, вибрали керувати духовним життям нашого народу.",
    C = "Ви станете каналом спілкування наших предків. Ви матимете силу стихій у своєму розпорядженні. Розрізати ворогів буде дитячою грою; зцілювати своїх союзників так само легко, як дихати. Пам’ятайте про це, коли стикаєтеся з новими викликами, і повертайтеся до мене так часто, як забажаєте. Я залишуся тут, щоб навчити вас новим заклинанням і направити вас на правильний шлях, коли ви будете готові.",
},

[3090] = {
    en = "Tainted Parchment",
    T = "Зіпсований пергамент",
    D = "Ах, поки тебе не було, для тебе прийшов пергамент, $N.$B$BЯ зазвичай уникаю справ із чаклунами, якщо можу, але думаю, тобі варто його прочитати, коли матимеш час. Якщо я не помиляюся, він від твого новопризначеного тренера Нартока. Він хоче поговорити з тобою, коли ти будеш готовий.",
    O = "Прочитай Зіпсований Пергамент і поговори з Нартоком у Ліґві в Долині Випробувань.",
    P = "Нарешті ви прибули... і теж непомітно. Добре.$B$BOur світ повний дурнів, $N. Навіть могутній Тралл має більші недоліки, ніж більшість бачить. Він відмовляється від сили, необхідної, щоб повністю зробити цю землю нашою! Ми не ті самі люди, якими маніпулювали і використовували істоти з Пустоти. Ми свої люди. Ми горді... і ми сильні.",
    C = "А тепер і ти приєднався до наших лав. Не зрозумійте неправильно, $n. Тільки тому, що у вас є доступ до влади, якому багато хто заздрить, це не означає, що вас легко приймуть. Тралл допускає нашого роду в Оргріммар, тому що ми все ще є його родичами — він не може відвернутися від нас, інакше ми станемо такими ж жалюгідними, як люди, які поневолили його. Я хочу сказати: будьте обережні. Ти можеш бути могутнім, але якщо ти дурний, то ти такий же мертвий.$B$BIf тобі потрібне навчання заклинанням, тоді повернися до мене.",
},

[3091] = {
    en = "Simple Note",
    T = "Простий лист",
    D = "Щойно для тебе шукав посланець, $N. Я вважаю, що його відправив тренер воїнів Харутт. Якщо цей лист від Харутта, я б не зволікав із прочитанням його вмісту.",
    O = "Прочитай Простий Лист і поговори з Харуттом Громовим Рогом у Таборі Нараче.",
    P = "Ах, нарешті ти прибув, $C. Я не збрехав у своїй записці, $N. Ми теж особлива порода, не схожі на друїдів чи шаманів нашого племені. Ви так само важливі. Ми покликані захищати наші кордони, полювати на кентавра та йти на війну.",
    C = "Кожен із нас відіграє певну роль у своєму племені. Кожен з нас також повинен пройти всі ті ж обряди. Ніколи не дозволяйте своїй гордості говорити вам інакше.$B$BI залишайтеся тут, щоб навчати нових воїнів, які прагнуть слави битв і які йдуть шляхами наших найдавніших предків. Коли ви будете готові, поверніться до мене, і я зроблю все можливе, щоб навчити вас далі. Йди з благословенням племені, $N.",
},

[3092] = {
    en = "Etched Note",
    T = "Вигравіюваний лист",
    D = "Щойно для тебе шукав посланець, $N. Я вважаю, що його відправив тренер мисливців Ланка. Якщо цей лист від Ланки, я б не зволікав із прочитанням його вмісту.",
    O = "Прочитай Вигравіюваний Лист і поговори з Ланкою Далекострілом на Плато Червоного Хмари.",
    P = "Ласкаво просимо до табору Нараче, $N. Я чую про вас хороші слова. Ваш родовід сильний, і багато хто зі старійшин уже вважає вас вправним. Але це ми перевіримо.$B$BThe рівнини Мулгора на якийсь час стануть вашим домом - ви повинні зробити все можливе, щоб добре вивчити це. Одного разу ви відправитеся в незнайомі країни, щоб оволодіти більшими навичками. Ви повинні бути готові.",
    C = "І моя робота полягає в тому, щоб переконатися, що ви підготувалися, навчивши вас основам нашої професії — як приручити свого домашнього улюбленця, як стріляти з рушниці та багатьом іншим навичкам, які знадобляться.$B$BHunters є сильною частиною нашої традиції та історії, $N. Тобі було б добре пам’ятати, наскільки ти важливий для племені. Вас будуть поважати і шанувати, якщо ви добре служите нашому народу.",
},

[3093] = {
    en = "Rune-Inscribed Note",
    T = "Лист із Рунами",
    D = "Щойно для тебе шукав посланець, $N. Я вважаю, що його відправив тренер шаманів Міла. Якщо цей лист від Міли, я б не зволікав із прочитанням його вмісту.",
    O = "Прочитай Лист із Рунами і поговори з Мілою Світанковою у Таборі Нараче.",
    P = "Так швидко, як вода падає з неба, ось ти переді мною. Я задоволений вашою поспішністю. Це означає, що ви усвідомлюєте важливість нашої зустрічі та вашої присутності. Я не лідер, але я розумію елементи і можу говорити з духами наших людей. Я навчу вас робити те саме.",
    C = "Ми зустрінемося багато разів у наступні дні. Сподіваюся, кожного разу ви залишатимете мою компанію трохи сильнішими... трохи більш підготовленими. Як Вічний вогонь, ваш дух горітиме яскраво й гаряче.$B$BGo зараз, $N. Ідіть і перевірте себе. Я буду тут для вас, коли вам буде потрібно.",
},

[3094] = {
    en = "Verdant Note",
    T = "Зелений лист",
    D = "Щойно для тебе шукав посланець, $N. Я вважаю, що його відправив тренер друїдів Ґарт. Якщо цей лист від Ґарта, я б не зволікав із прочитанням його вмісту.",
    O = "Прочитай Зелений Лист і поговори з Ґартом Туманобігом у Таборі Нараче.",
    P = "Ви приїхали. Це добре. Духи наших предків стали неспокійними в Мулгорі та за його межами, але я не можу сказати чому. Вашим обов’язком назавжди буде навчитися слухати духів природи та діяти як їхній аватар. Пам’ятайте про це.",
    C = "Хоча між нами спільний зв’язок, не чекайте особливого прийому від нічних ельфів. Їхня гордість усе ще обмежує їхній зір, але це нас не хвилює. Вчення Матері-Землі — це все, чим ви повинні займатися, і я навчатиму вас того, що знаю, коли ви зростатимете в мудрості.$B$BReturn мені часто, $N. Ви побачите, що Мати-Земля дарує неймовірні здібності тим, хто найбільш відданий справі.",
},

[3095] = {
    en = "Simple Scroll",
    T = "Простий сувій",
    D = "Ах, поки ти боровся з безмозкими Плетями, для тебе прийшов цей сувій. Я вважаю, що це щось важливе, адже на ньому, здається, печатка тренера воїнів Даннала. Я б приділив час, щоб прочитати його, перш ніж знову вирушати.",
    O = "Прочитай Простий Сувій і поговори з Данналом Стерном у Смертехроні.",
    P = "А, значить, ви приїхали. добре. Я випадково почув, що ще кілька людей змогли втекти від ",
    C = "Я буду тут, щоб навчати вас, коли ви накопичуватимете досвід... знаходите мене так часто, як забажаєте. Я стягую мінімальну плату, але ви знайдете все, чому я можу вас навчити, щоб бути корисним.$B$BGo зараз і перевірте свої навички. У міру набуття досвіду вам стане відомо ще багато речей, деякі з яких я не можу обговорити з вами тут. Просто знайте, що в майбутньому Сільвані знадобляться воїни з вашим типом сили. Ти будеш опорою нашого спасіння. Не забувайте про це.",
},

[3096] = {
    en = "Encrypted Scroll",
    T = "Зашифрований сувій",
    D = "Ах, поки ти боровся з безмозкими Плетями, для тебе прийшов цей сувій. Я вважаю, що це щось важливе, адже на ньому, здається, печатка тренера розбійників Девіда Тріаса. Я б приділив час, щоб прочитати його, перш ніж знову вирушати.",
    O = "Прочитай Зашифрований Сувій і поговори з Девідом Тріасом у Смертехроні.",
    P = "Отже, ви це зробили? Добре, з часом нам знадобиться більше шахраїв. Шодолокери, ймовірно, знайдуть вас, коли подумають, що настане слушний час, тому не йдіть і не помиляйтесь і не робіть нічого, про що можете пошкодувати. Їм потрібні талановиті агенти... а не кишенькові злодії та дурні.",
    C = "Я проводжу більшу частину свого часу тут, у готелі, стежачи за новими обличчями та просто стежачи за майбутніми перспективами. Тримайте свій ніс чистим, і я зроблю все можливе, щоб навчити вас декільком речам. Просто повертайся до мене, коли захочеш, і ми побачимо, чи готовий ти отримати нову навичку чи дві.",
},

[3097] = {
    en = "Hallowed Scroll",
    T = "Освячений сувій",
    D = "Ах, поки ти боровся з безмозкими Плетями, для тебе прийшов цей сувій. Я вважаю, що це щось важливе, адже на ньому, здається, печатка тренера жерців Дуестена. Я б приділив час, щоб прочитати його, перш ніж знову вирушати.",
    O = "Прочитай Освячений Сувій і поговори з Темним Кліриком Дуестеном у церкві в Смертехроні.",
    P = "Отож, поміж вогнем, чумою, бунтом і набагато гіршим до моїх дверей приходить ще один ",
    C = "Ви повинні знати лише одне: ми вижили лише завдяки волі. Саме віра в себе відокремлює нас від інших, і завдяки нашим силам ми спричинимо великі зміни в усьому Азероті. Слабкі будуть спиратися на вас. Прокажені називатимуть тебе Господом. І невігласи шукатимуть у вас поради. Мій обов’язок — переконатися, що у вас є необхідні інструменти, щоб, коли прийде час, ви були готові. У міру зростання досвіду шукайте мене. Я навчу вас більшим силам, якщо ви будете готові.",
},

[3098] = {
    en = "Glyphic Scroll",
    T = "Гліфічний сувій",
    D = "Ах, поки ти боровся з безмозкими Плетями, для тебе прийшов цей сувій. Я вважаю, що це щось важливе, адже на ньому, здається, печатка тренера магів Ізабелли. Я б приділив час, щоб прочитати його, перш ніж знову вирушати.",
    O = "Прочитай Гліфічний Сувій і поговори з Ізабеллою в церкві в Смертехроні.",
    P = "Я знав, що ти прийдеш до мене, $N. Не тому, що у вас немає бажання йти своїм шляхом, а тому, що ми споріднені душі. Ми обидва відчули біль. Ми обидва постраждали. І зараз ми хочемо отримати владу, щоб повернути те, що ми знаємо як наше: цю землю, наші життя, наші долі. Але вам ще є чому навчитися.",
    C = "Ви повинні часто повертатися до мене, якщо хочете стати достатньо могутнім, щоб знищити тих, хто протистоїть нам. Правила магії все ще застосовуються до вас, $N. Ви все одно побачите, що корупція слідує за вами, як голодні вовки вночі. Ви побачите, що його ласка не відрізняється від залежності, коли старий коханець все ще хоче бути поруч з вами. Але ці речі можна уникнути. Ці речі будуть контролювати вас, лише якщо ви їм це дозволите.$B$BGo зараз, поверніться до мене, коли станете могутнішим.",
},

[3099] = {
    en = "Tainted Scroll",
    T = "Зіпсований сувій",
    D = "Ах, поки ти боровся з безмозкими Плетями, для тебе прийшов цей сувій. Я вважаю, що це щось важливе, адже на ньому, здається, печатка тренера чаклунів Максімілліона. Я б приділив час, щоб прочитати його, перш ніж знову вирушати.",
    O = "Прочитай Зіпсований Сувій і поговори з Максімілліоном у Смертехроні.",
    P = "Вітаю вас, $gbrother:sister;. Я знав, що ти прийдеш. Це було лише питанням часу.$B$BWhat Я сказав, що вас цікавить, чи не так? Я потрапив у струну... щось усередині тебе знало, що я вважав правдою. Добре.$B$BKnow ось що: я не зрадник Сільвани. У будь-якому разі вона оцінила б мої претензії, враховуючи, що саме її власні переконання поставили Покинутих у те становище, яке воно є зараз.",
    C = "Я згадав, що раб все ще залишається рабом, незважаючи на господаря. Ви пам'ятаєте? Ми обидва знаємо, що саме цей тип контролю – такий тип влади – є тим, що зараз керує нами. Ми прагнемо, щоб істоти служили нам. Ми знаємо, що ми сильніші та заслуговуємо на більше поваги, ніж інші... і тому тепер ми хочемо взяти це.$B$BI стане вашим союзником у цій боротьбі — боротьбі за нашу власну свободу. Свобода шукати власної прихильності. Коли ви будете готові, поверніться до мене, і я навчу вас усього, що знаю.",
},

[3100] = {
    en = "Simple Letter",
    T = "Простий лист",
    D = "Мені доручили привернути твою увагу до цього, щойно ти повернешся з таборів кобольдів, $N. Це, здається, лист, запечатаний знаком Ллейна, нашого місцевого тренера воїнів. Я б не зволікав із прочитанням його, перш ніж зайнятися іншими справами тут, в Абатстві.",
    O = "Прочитай Простий Лист і поговори з Ллейном Беширом у Нортширському Абатстві.",
    P = "Ах, ти отримав мій лист, $N... добре.$B$BThere Останнім часом в Елвінн напливли воїни - це добре для Штормовія, але погано для кобольдів і дефіїв у цьому районі.",
    C = "Зберігайтеся, вивчіть план землі та повертайтеся до мене щоразу, коли вам знадобиться навчання. Я буду тут і вночі, і вдень.$B$BThe Лицарі Срібної Руки зробили це добре, зробивши це місце досить безпечним, але коли ви познайомитеся з іншими громадянами, я думаю, ви побачите, що всі вони мають проблеми, з якими їм потрібна допомога – допомога, яку їм може надати $C. удачі",
},

[3101] = {
    en = "Consecrated Letter",
    T = "Освячений Лист",
    D = "Мені доручили звернути твою увагу на це, щойно ти повернешся з таборів кобольдів, $N. Це виглядає як лист, запечатаний знаком брата Самуеля, нашого місцевого тренера паладинів. Я б не зволікав із його прочитанням, перш ніж займатись іншими справами тут, в абатстві.",
    O = "Прочитайте Освячений Лист і поговоріть із братом Самуелем у Нортширському Абатстві.",
    P = "Нарешті! Зустрічаємося віч-на-віч, брат з братом. Я вітаю вас у Нортширі. Це буде ваш дім на короткий час, поки ви дізнаєтесь про тонкощі того, як це робиться, але знайте, що Штормовій недалеко, і рано чи пізно ваш шлях приведе вас туди. Але доти потерпіть... Лицар Срібної руки.",
    C = "Тим часом ви повинні знати ще одну чи дві речі. Ви є символом для багатьох тут, на цій землі, — дійте відповідно. Святе світло сяє всередині вас, і це буде очевидно як вашим союзникам, так і вашим ворогам.$B$BAlso, коли ви набуваєте мудрості та сили, вам потрібно буде тренуватися, щоб набути нових здібностей. Ось тут і вступаю я. Коли ви відчуєте, що набули певного досвіду тут, у Нортширі, поверніться до мене, і я навчу вас того, чого, на мою думку, ви готові навчитися. Удачі... $C!",
},

[3102] = {
    en = "Encrypted Letter",
    T = "Зашифрований Лист",
    D = "Мені доручили звернути твою увагу на це, щойно ти повернешся з таборів кобольдів, $N. Це виглядає як лист, запечатаний знаком Джоріка, одного з наших місцевих тренерів. Я б не зволікав із його прочитанням, перш ніж займатись іншими справами тут, в абатстві.",
    O = "Прочитайте Зашифрований Лист і поговоріть із Джоріком Керріданом у стайні за Нортширським Абатством.",
    P = "Ви потрапили сюди цілим, і не схоже, що багато людей бачили вас. Досить добре для мене. Мені не подобається, коли на мене тут звертають багато уваги... гарно й тихо. Я впевнений, що ви розумієте.$B$BHave ще не виникли проблеми? Я радий чути ні. Це скоро зміниться.",
    C = "Ти побачиш, що є багато нарядів, які зажадають наших навичок, Кейлель. Шукачі пригод, SI:7... до біса, навіть Братство Defias не заперечувало б одного-двох шпигунів у Штормовії. Але пам'ятай про це, ти сама собі людина. Не дозволяйте нікому змушувати вас робити те, чого ви не хочете! Крім того, ми тримаємо всі карти... принаймні ми тримаємо до завершення гри. Розумієте, що я маю на увазі?$B$BAnyway, я просто хотів представитися та повідомити вас, що я тут, якщо вам знадобиться навчання. Приходьте в будь-який час.",
},

[3103] = {
    en = "Hallowed Letter",
    T = "Святий Лист",
    D = "Мені доручили звернути твою увагу на це, щойно ти повернешся з таборів кобольдів, $N. Це виглядає як лист, запечатаний знаком жриці Анетти, нашої місцевої тренерки жерців. Я б не зволікав із його прочитанням, перш ніж займатись іншими справами тут, в абатстві.",
    O = "Прочитайте Святий Лист і поговоріть із жрицею Анеттою в Нортширському Абатстві.",
    P = "Ах, нарешті ти прийшов. Я знав, що ти знайдеш до мене дорогу. Святе світло сяє на вас і на обраний вами шлях. Зараз суворі часи — Палаючий Легіон все ще присутній в Азероті, весь Калімдор шукає нові способи захисту від власних негараздів, і від вас залежить, чи допоможете якомога більшій кількості.",
    C = "У міру зростання досвіду поверніться до мене, і я зроблю все можливе, щоб передати вам свої знання. А доти йдіть із співчуттям у серці, і нехай мудрість буде вашим провідником. Пам’ятайте, світ стає кращим лише тоді, коли ви робите його таким.",
},

[3104] = {
    en = "Glyphic Letter",
    T = "Гліфічний Лист",
    D = "Мені доручили звернути твою увагу на це, щойно ти повернешся з таборів кобольдів, $N. Це виглядає як лист, запечатаний знаком Келдена, нашого місцевого тренера магів. Я б не зволікав із його прочитанням, перш ніж займатись іншими справами тут, в абатстві.",
    O = "Прочитайте Гліфічний Лист і поговоріть із Келденом Бременом у Нортширському Абатстві.",
    P = "Привіт, $N. Я Хелден. Чи можу я щось для вас зробити?",
    C = "Ха-ха, я знав, що моя записка не відмовить вас від вашого шляху. Отже, ви готові, чи не так? Готові прийняти свою долю? Готові кинути виклик богам та будь-яким іншим силам, які стоять перед вами в гонитві за знаннями та владою?$B$BI не буде брехати, $N, вас боятимуться так само, як і поважатимуть. Але також знайте, я буду поруч, коли вам знадобиться навчання. Просто шукай мене, коли станеш могутнішим.",
},

[3105] = {
    en = "Tainted Letter",
    T = "Забруднений Лист",
    D = "Мені доручили звернути твою увагу на це, щойно ти повернешся з таборів кобольдів, $N. Це виглядає як лист, запечатаний знаком Друсілли, однієї з наших місцевих тренерів. Я б не зволікав із його прочитанням, перш ніж займатись іншими справами тут, в абатстві.",
    O = "Прочитайте Забруднений Лист і поговоріть із Друсіллою Ла Салль біля Нортширського Абатства.",
    P = "Ах, значить, ти прибув, і не рано, $N. Кілька охоронців мить тому були тут і кидали на мене цікаві погляди... жалюгідні світські погляди.",
    C = "У міру того, як ваша влада зростатиме, ви будете піддаватися спокусі – ви повинні завжди пам’ятати про контроль над собою. Я не буду брехати - корупція може прийти до будь-якого практикуючого таємниці; особливо той, хто має справу з істотами з Круговерть. Будь терплячим і розсудливим... але не дозволяй цьому пригнічувати твої амбіції.$B$BAs ти стаєш могутнішим, повертайся до мене, і я навчу тебе більше про наші способи.",
},

[3106] = {
    en = "Simple Rune",
    T = "Проста Руна",
    D = "Поки ти допомагав мені, мені передали цю руну, щоб я вручив її тобі. Знайди час, щоб прочитати її, коли матимеш можливість. Гадаю, вона від тренера воїнів Трана. Переглянь її та знайди його в Енвілмарі, коли матимеш час.",
    O = "Прочитайте Просту Руну і поговоріть із Траном Корманом у Долині Холодного Кряжу.",
    P = "Сьогодні холодно, чи не так? Сніг наче ніколи не йде, $N.$B$BYou, напевно, це вже помітили, але в нашому місті тепер живуть гноми. Це тому, що вони пішли і вилетіли з власного дому. Не поширюйте про це, але я навряд чи можу їх звинувачувати — думаю, я б також вдався до вибухівки, якби Стальгорн був заражений Чорним Залізом чи подібним.",
    C = "Інші речі, які ви, ймовірно, також побачите, щоб ви були в курсі: гноми використовують у бою магію замість рушниці. Деякі з нас поклоняються Святому Світлу, як деякі люди, і, нарешті, але не менш важливо, трогги. Ви дізнаєтеся про них більше пізніше, але зараз вам потрібно знати, що я тут, щоб допомогти вам.$B$BI бути тут, щоб навчити вас, як бути справжнім $C. Щоразу, коли ти думаєш, що тобі потрібно більше тренувань, повертайся до мене, і я подивлюся, що зможу зробити.",
},

[3107] = {
    en = "Consecrated Rune",
    T = "Освячена Руна",
    D = "Поки ти допомагав мені, мені передали цю руну, щоб я вручив її тобі. Знайди час, щоб прочитати її, коли матимеш можливість. Гадаю, вона від тренера паладинів Бромоса. Переглянь її та знайди його в Енвілмарі, коли матимеш час.",
    O = "Прочитайте Освячену Руну і поговоріть із Бромосом Груммнером у Долині Холодного Кряжу.",
    P = "Отже, ви зробили це! І ні секунди раніше. У Колдрідж-Веллі та за її межами ще багато чого можна зробити. Мені буде потрібна ваша допомога так само, як і вам моя!$B$BYou тепер ви лицар Срібної руки, будьте готові зіграти цю роль.",
    C = "Люди багато чого навчили нас про Святе Світло та про те, наскільки важливим для них є їхній орден... і захист усього Азероту. Ми з великою повагою ставимося до того, наскільки це дотримано традицій, і як одна фігура, одна жертва може змінити біль і порятунок.$B$BThe ми двоє деякий час працюватимемо разом. Щоразу, коли ви думаєте, що готові, поверніться до мене, і ми подбаємо про те, щоб вас трохи навчили. Хіба ж ти не можеш вийти у світ непідготовленим, чи не так?",
},

[3108] = {
    en = "Etched Rune",
    T = "Витравлена Руна",
    D = "Поки ти допомагав мені, мені передали цю руну, щоб я вручив її тобі. Знайди час, щоб прочитати її, коли матимеш можливість. Гадаю, вона від тренера мисливців Торґаса. Переглянь її та знайди його в Енвілмарі, коли матимеш час.",
    O = "Прочитайте Витравлену Руну і поговоріть із Торґасом Грімсоном у Долині Холодного Кряжу.",
    P = "Я зробив це! Приємно чути! Бетчі також не довелося стежити за мною, щоб знайти це місце. Ха-ха!$B$BOur професія має досить традиції, $N. Вивчення шляхів землі. Вчимося вистежувати ведмедя по горах. Навіть щоб вижити лише за рахунок розуму, потрібна велика відвага та хитрість. Думаєш, ти здатний?",
    C = "Єдине, про що ви завжди повинні пам’ятати, це те, що ви повинні поважати світ, у якому живете. Звірі, які вирішили битися разом з вами; блиск вашої зброї; вага ваших боєприпасів; укус сильного вітру; усе це вам потрібно знати докладно.$B$BI зроблю все, що зможу, щоб допомогти вам, але більша частина роботи залежить від вас. Щоразу, коли ви думаєте, що готові, поверніться та поговоріть зі мною. Я навчу тебе, коли зможу.",
},

[3109] = {
    en = "Encrypted Rune",
    T = "Зашифрована Руна",
    D = "Поки ти допомагав мені, мені передали цю руну, щоб я вручив її тобі. Знайди час, щоб прочитати її, коли матимеш можливість. Гадаю, вона від тренера розбійників Солма. Переглянь її та знайди його в Енвілмарі, коли матимеш час.",
    O = "Прочитайте Зашифровану Руну і поговоріть із Солмом Гарґріном у Долині Холодного Кряжу.",
    P = "Ви це зробили! Чудово!$B$BWe останнім часом активізується, тож я радий зарахувати до нашого числа ще одного члена клану Стальгорн. Занадто багато з нас дивляться на таємниче та божественне на мій власний смак. Нічого проти них та їхніх переконань, але немає нічого, як холодне лезо у твоїй руці та тінь, яка захистить тебе від світла, розумієш, що я маю на увазі?",
    C = "У будь-якому випадку, коли ви починаєте зазирати навколо Колдріджа, вам, ймовірно, колись знадобиться тренування. Ти просто повертайся до мене щоразу, коли відчуєш, що тобі це потрібно, і я навчу тебе того, що я знаю: трюк тут, маневр там. Ви знаєте, те, що тримає вас живим і заробляє трохи додаткової монети.$B$BKeep також слідкуйте за нашими друзями-гномами... вони начебто отримали коротший кінець палиці через те, що Гномреган був... знищений. Їм знадобиться наша допомога, щоб відчути себе бажаними.",
},

[3110] = {
    en = "Hallowed Rune",
    T = "Свята Руна",
    D = "Поки ти допомагав мені, мені передали цю руну, щоб я вручив її тобі. Знайди час, щоб прочитати її, коли матимеш можливість. Гадаю, вона від тренера жерців Бранстока. Переглянь її та знайди його в Енвілмарі, коли матимеш час.",
    O = "Прочитайте Святу Руну і поговоріть із Бранстоком Калдером в Енвілмарі.",
    P = "Ах! Зробив це, $N! Чудово! $B$BI хотів сказати, я майже втратив віру, що ти взагалі приїдеш... розумієш, втратив віру? Це жарт, дівчино... ой, нічого. Я все одно прийшов сюди не заради поганих жартів.",
    C = "Я той, хто може навчити тебе, коли ти починаєш орієнтуватися в долині Колдрідж. Коли ти відчуєш, що готовий, повернися до мене, і ми подивимося, чи можливо навчимо тебе нового заклинання чи двох, щоб відбити долину від цих знищених трогів.$B$BYa отримав Світло на своєму боці, разом із усім Стальгорном, $N... ти не тиснеш, щоб ти став чимось особливим.",
},

[3111] = {
    en = "Glyphic Rune",
    T = "Гліфічна Руна",
    D = "Давно високі ельфи навчили нас секретів магії разом із нашими людськими союзниками. Вони проповідували нам про правила і як магія може звести з розуму! Але не вір цьому. Ми не такі, як ельфи; у нас немає тих самих слабкостей. Просто тримайся правильного шляху, і ти побачиш, що магія — це настільки ж потужний інструмент, як і зброя.$B$BКоли будеш готовий, приходь до мене в Енвілмар. Я чекатиму на тебе!",
    O = "Поговоріть із Марриком Нуррібітом в Енвілмарі.",
    P = "",
    C = "",
},

[3112] = {
    en = "Simple Memorandum",
    T = "Простий Меморандум",
    D = "Поки ти допомагав мені, мені передали цей меморандум, щоб я вручив його тобі. Знайди час, щоб прочитати його, коли матимеш можливість. Гадаю, він від тренера воїнів Трана. Переглянь його та знайди Трана в Енвілмарі, коли матимеш час.",
    O = "Прочитайте Простий Меморандум і поговоріть із Траном Корманом у Долині Холодного Кряжу.",
    P = "Ну, ще один меморандум від $R про місію... хіба це не дивно.$B$BNo, ні, я не дражню тебе, крихітко. Треба поважати вашу наполегливість, це безсумнівно. Я був би так само розлючений, якби Стальгорн захопили гноми Чорного Заліза, тож не думайте, що я не співчуваю вашому становищу...",
    C = "Зважаючи на те, що це ваша головна директива, або як би ви це називали сьогодні, я дав слово, що зроблю все можливе, щоб переконатися, що ви та ваші були готові повернути свій дім... і саме це я й зроблю.$B$BAny коли ви відчуєте, що готові, поверніться до старого доброго Трана, і я буду радий поділитися з вами своїми знаннями. Тренування мене потребує певних витрат, але це не буде занадто дорого. удачі",
},

[3113] = {
    en = "Encrypted Memorandum",
    T = "Зашифрований Меморандум",
    D = "Поки ти допомагав мені, мені передали цей меморандум, щоб я вручив його тобі. Знайди час, щоб прочитати його, коли матимеш можливість. Гадаю, він від тренера розбійників Солма. Переглянь його та знайди Солма в Енвілмарі, коли матимеш час.",
    O = "Прочитайте Зашифрований Меморандум і поговоріть із Солмом Гарґріном у Долині Холодного Кряжу.",
    P = "Радий бачити, що ти отримав мою записку й підійшов. Вибачте, що вдавав, що це був меморандум від вашого начальства... без наміру. Я просто знав, що ми двоє, а також інші подібні до нас, повинні триматися разом.$B$BNot Багато хто вважає, що це найкраща річ у світі, коли ваш і мій подібні живуть в одному місті, але я думаю, що ми можемо все добре вирішити. як ти думаєш",
    C = "Я тут майже тримаюся усамітнено, щоб ми не отримали поганої інформації про зниклі речі, але якщо вам щось знадобиться, навчання чи щось інше, просто повертайтеся в будь-який час.$B$BYou і я зрозуміли. Ми знаємо, що коли справа доходить до цього, можна довіряти лише сім’ї... і це саме те, що у нас тут відбувається, чи не так? Не дивлячись на те, що Гномреган був... переповнений, і все, що нам кинули на шляху, ми змушені підтримувати один одного. правильно?",
},

[3114] = {
    en = "Glyphic Memorandum",
    T = "Гліфічний Меморандум",
    D = "Поки ти допомагав мені, мені передали цей меморандум, щоб я вручив його тобі. Знайди час, щоб прочитати його, коли матимеш можливість. Гадаю, він від тренера магів Маррика. Переглянь його та знайди Маррика в Енвілмарі, коли матимеш час.",
    O = "Прочитайте Гліфічний Меморандум і поговоріть із Марриком Нуррібітом в Енвілмарі над Долиною Холодного Кряжу.",
    P = "Так, що це таке, $R? Говори, якщо ти не проти. Я не так добре чую після кількох елів.",
    C = "О, так! Arcane Arts... звичайно.$B$BHere ось що вам потрібно знати, $N: не впадайте в зайві проблеми. Збережіть трохи монет, щоб купити мені ель... або будь-які заклинання, які вам знадобляться. І тримайся подалі від Гномерегана. Крім того, гарного дня! Я буду тут, якщо я тобі знадоблюся чи захочеш потренуватися... чи що завгодно.",
},

[3115] = {
    en = "Tainted Memorandum",
    T = "Забруднений Меморандум",
    D = "Поки ти допомагав мені, мені передали цей меморандум, щоб я вручив його тобі. Знайди час, щоб прочитати його, коли матимеш можливість. Гадаю, він від тренера чаклунів Аламара. Переглянь його та знайди Аламара в Енвілмарі, коли матимеш час.$B$BІ будь обережний, $N, таких, як ти, тут не дуже довіряють.",
    O = "Прочитайте Забруднений Меморандум і поговоріть із Аламаром Гріммом в Енвілмарі над Долиною Холодного Кряжу.",
    P = "Чудово! Ви, очевидно, отримали мій меморандум.$B$BIgnore дурні навколо вас, $N. Святе світло?! Меч і щит?! Це шляхи не для таких відкритих людей, як ми. Подивіться, що ",
    C = "Але це не має значення. Важливо те, що ви бачили своє власне Святе Світло! Ви знаєте, звідки береться сила. Ви розумієте, що мати власних союзників набагато... розумніше. Особливі союзники. Союзники, які, незважаючи на завдання, слухатимуться до останнього подиху.$B$BAnd Ось де я виступаю, $N. Я можу навчити вас початківцям цих особливих здібностей. Шукайте мене частіше, і я зроблю все можливе, щоб навчити вас більше заклинань.",
},

[3116] = {
    en = "Simple Sigil",
    T = "Простий Знак",
    D = "Цей знак передав мені посланець від нашої тренерки воїнів Алісії. Схоже, Алісія хоче поговорити з тобою, коли у тебе буде хвилинка. Прочитай його і принеси їй після цього.",
    O = "Прочитайте Простий Знак і поговоріть із Алісією в Тінистій Долині.",
    P = "Ви зробили це. Я дуже радий.$B$BMuch сталося за останні кілька років, Саріку: створення Тельдрассила, розбещення багатьох лісових створінь тут і за кордоном, відкриття земель, які ми вважали втраченими для нас, як Фералас... так багато, за такий короткий час. Але це лише деякі з причин, чому ми тут, найважливіша — захистити наш рід від подальшого зла.",
    C = "Невдовзі ви побачите інших представників різних рас на гілках нашого дому — не дозволяйте, щоб це викликало у вас упередження. Вони вітаються. Вони допоможуть нам, коли зможуть. Не всі з них будуть альтруїстами, але їм слід висловити певну довіру.$B$BBut все це зараз не має значення. Тепер ми повинні зосередитися на вас і на тому, як ви можете допомогти нашим людям. Я тут саме з цією метою. Я навчатиму вас способам $C, коли ви станете сильнішими. Повертайтеся до мене, коли забажаєте, і я зроблю все, що зможу, щоб допомогти вам.",
},

[3117] = {
    en = "Etched Sigil",
    T = "Витравлений Знак",
    D = "Цей знак передав мені посланець від нашої тренерки мисливців Аянни. Схоже, Аянна хоче поговорити з тобою, коли у тебе буде хвилинка. Прочитай його і принеси їй після цього.",
    O = "Прочитайте Витравлений Знак і поговоріть із Аянною Вічнокрок у верхній частині Алдрассіла в Тінистій Долині.",
    P = "Ви приїхали, і не надто швидко, $N. Ласкаво просимо до Shadowglen.$B$BI вірите, що мій сигіл знайшов вас у гарному настрої та здоров’ї?$B$BAs Раніше я сказав, що я тут, щоб навчити вас як $C; приборкувати звірів, які допомагатимуть вам у битві; з безпомилковою влучністю користуватися луком; поважати землі, які ми називаємо домівкою, а також землі за її межами.",
    C = "Коли ви відчуєте те, чому Shadowglen має вас навчити, приходьте до мене – я зможу допомогти вам зрозуміти вашу роль як $C і те, на що ви здатні.$B$BThese небезпечні часи, $N, не сприймайте як належне вміння ваших домашніх тварин — у цьому світі є речі небезпечніші, ніж ви можете собі уявити. Йди з Елуною і повертайся до мене знову.",
},

[3118] = {
    en = "Encrypted Sigil",
    T = "Зашифрований Знак",
    D = "Цей знак передав мені посланець від нашого тренера розбійників Фрагуна. Схоже, Фрагун хоче поговорити з тобою, коли у тебе буде хвилинка. Прочитай його і принеси йому після цього.",
    O = "Прочитайте Зашифрований Знак і поговоріть із Фрагуном Тінним Шепотом у Тінистій Долині.",
    P = "Привіт, Ферліс. Я радий, що ти знайшов мене. Я подумав, що, можливо, ви заблукали дорогою сюди.$B$BNothing справді щось нове сталося в Shadowglen відтоді, як я надіслав вам свій символ, але я залишу вам усе збирання інформації. Якщо хочете, поговоріть з іншими людьми навколо Алдрасіла.",
    C = "А до того часу знайте, що наші люди потрібні як ніколи в цей важкий час. Мир з іншими расами може зазнати краху в будь-який момент, і багато говорять про те, що члени Орди прагнуть посіяти ще більше насіння недовіри. Пам’ятайте про це.$B$BAs якщо ви наберетеся сили та відчуєте себе більш підготовленим, поверніться до мене сюди, і я подбаю про те, щоб вас трохи навчили. Крім усього іншого, важливо знати, як поводитися з обраною зброєю.",
},

[3119] = {
    en = "Hallowed Sigil",
    T = "Святий Знак",
    D = "Цей знак передав мені посланець від нашої тренерки жриць Шанди. Схоже, Шанда хоче поговорити з тобою, коли у тебе буде хвилинка. Прочитай його і принеси їй після цього.",
    O = "Прочитайте Святий Знак і поговоріть із Шандою в Алдрассілі.",
    P = "Мені приємно бачити, що ти прибув так швидко, $N. Ласкаво просимо.$B$BAs ви, мабуть, чули, що весь Тельдрассил переполохує мандрівниками, які прибувають і від’їжджають. Навіть членам Альянсу навіть було дозволено доступ до гілок Тельдрассила, щоб зустрітися з іншими Калдореями, які готуються до майбутніх пригод.",
    C = "Наразі не турбуйтеся про світ під Тельдрассилом. На це буде час пізніше. Ідіть зараз і поговоріть з іншими в Shadowglen - вони можуть розповісти вам більше про те, що сталося. Допоможіть їм будь-яким способом, і щоразу, коли ви відчуєте, що вам потрібно більше навчання, поверніться до мене, і я навчу вас, чого зможу.",
},

[3120] = {
    en = "Verdant Sigil",
    T = "Зелений Знак",
    D = "Цей знак передав мені посланець від нашого тренера друїдів Марданта. Схоже, Мардант хоче поговорити з тобою, коли у тебе буде хвилинка. Прочитай його і принеси йому після цього.",
    O = "Прочитайте Зелений Знак і поговоріть із Мардантом Міцнодубом у дереві Алдрассіл у Тінистій Долині.",
    P = "Ах, молодий $C. Я бачу, що ти хочеш продовжувати навчання. Добре.$B$BI цікаво, ти вже багато часу провів у Смарагдовій мрії? Можливо, ви ще не готові до цього... З часом, я впевнений.$B$BBut до того часу, ми повинні обговорити інші питання.",
    C = "Я поки що буду вашим наставником і провідником. Мій обов’язок — навчити вас тлумачити не лише те, що нам повідомляють духи, але й складнощі й таємниці Смарагдового сну.$B$BAs якщо ви навчаєтесь і зростаєте у силі, ви більше дізнаєтесь про наш сплячий транс. Але до того часу повертайся до мене так часто, як забажаєш, і я навчу тебе всього, чого зможу, способів нашого роду.",
},

[3121] = {
    en = "A Strange Request",
    T = "Дивне Прохання",
    D = "Ніру Вогняний Клинок в Оргріммарі має те, що мені потрібно, щоб почати тут! Він приготував суміш, яка мені потрібна для мого… ну, ти побачиш.$B$BГайда до Оргріммара. Ось, візьми це з собою. Це зменшена голова, яку я обіцяв Ніру в обмін на трави. Це голова якогось бідолашного дворфа, якого я зустрів у лісі. Я впевнений, Ніру буде задоволений.$B$BТи знайдеш Ніру в Розколині Тіней.",
    O = "Віднесіть Зменшену Голову до Ніру Вогняного Клинка в Оргріммарі.",
    P = "Так?",
    C = "Я чекав, поки Узер'і доставить це...$B$BLet я дам тобі суміш трав, яку я приготував для його... ну, експериментів...",
},

[3122] = {
    en = "Return to Witch Doctor Uzer'i",
    T = "Повернення до Відьмака Узер’і",
    D = "Ось трави, $N. Віднеси їх до відьмака Узер’і.$B$BБудь ласка, повідом йому, що я задоволений зменшеною головою.",
    O = "Доставте Трав’яний Мішок Ніру до відьмака Узер’і у Фераласі.",
    P = "Ви говорили з Ніру?",
    C = "Це саме те, що мені потрібно, щоб підготувати посудину для муйсек, $N. Незабаром ми побачимо, чи виявляться мої останні заклинання настільки потужними, як я сподівався.$B$BPlease, хвилинку. Я повинен провести ритуал і застосувати трави.",
},

[3123] = {
    en = "Testing the Vessel",
    T = "Випробування Посудини",
    D = "Це буде випробування; як для ритуалу, який я провів, так і для твоїх здібностей. Візьми цю посудину, $N. З нею ти зможеш зменшувати і захоплювати створінь усередину.$B$BВирушай до Внутрішніх Земель і шукай створінь, відомих як Дикі Сови, які колись були улюбленцями нічної ельфійської богині Елуни. Твоїми цілями є жорстокі, примітивні або дикі совозвірі, $N. Убий 10 і використай муїсекову посудину, щоб зменшити і захопити їх, перш ніж їхні духи втечуть.",
    O = "Подорожуйте до Внутрішніх Земель і знайдіть Диких Сов. Убийте 10 і використайте Муїсекову Посудину, щоб зменшити і захопити полеглих Диких Сов.$B$BПринесіть 10 Муїсеків Диких Сов і Муїсекову Посудину до відьмака Узер’і у Фераласі.",
    P = "Чи вдалося вам захопити дикого скота?$B$BIf вам це вдасться, ми будемо готові зменшитися та захопити muisek створінь Feralas.",
    C = "Після насильницької смерті муісек істоти може втекти та шукати помсти. Зменшення істот, як це зробив ти, $N, запобігає втечі муісек. Тепер ми можемо використовувати його, як нам заманеться!",
},

[3124] = {
    en = "Hippogryph Muisek",
    T = "Муїсек Гіппогрифа",
    D = "Оскільки ти довів, що ти надійний і маєш здатність використовувати муїсекову посудину, я хочу, щоб ти захопив ще одну істоту.$B$BГіппогрифи були вірними супутниками нічних ельфів протягом багатьох років; їхні духи віддані та непохитні.$B$BТвоє завдання — убити 10 пір’ястих гіппогрифів і швидко зменшити та захопити їх за допомогою посудини, щоб зберегти їхній муїсек. Ти знайдеш гіппогрифів у Високій Пустці, на південь звідси.",
    O = "Убийте 10 Пір’ястих Гіппогрифів будь-якого типу, потім використайте Муїсекову Посудину, щоб зменшити і захопити їх.",
    P = "Чи вдалося вам схопити гіпогрифів?",
    C = "Якщо після вбивства тварини ми дозволили муйсеку втекти, він може прийняти форму ще більшої істоти. Ми ніколи не врятуємося від його помсти.$B$BThis це небезпечна робота, яку я доручив тобі, $N. Знову ж таки, ви добре це зробили.",
},

[3125] = {
    en = "Faerie Dragon Muisek",
    T = "Муїсек Феєричного Дракона",
    D = "$N, наступне, що мені потрібно, — це щоб ти захопив істоту, яка на вигляд може здаватися крихкою, але її потужний дух — це те, що нам справді потрібно. Феєричні дракони, про яких я говорю, служили нічним ельфам як союзники. Ми мусимо захопити одного, щоб Орда могла скористатися цією силою духу також.$B$BОсь муїсек, $N. Убий 8 феєричних дартерів або феєричних драконів і захопи їхній муїсек. Їх можна знайти на захід звідси.",
    O = "Убийте 8 Феєричних Дартерів або Феєричних Драконів. Використайте Муїсекову Посудину, щоб зменшити і захопити полеглих Феєричних Драконів.",
    P = "Чи вдалося вам зняти музику феєричних драконів?",
    C = "Дякую, $N. Тепер духовні сили чарівного дракона будуть доступні для нас.$B$BI Сподіваюся, ви захочете виконати для мене ще одне завдання.",
},

[3126] = {
    en = "Treant Muisek",
    T = "Муїсек Треанта",
    D = "Блукаючі лісові ходуни, яких можна знайти, коли вони бродять лісом, — наша наступна ціль, $N. Нічні ельфи залучили треантів як союзників для боротьби проти Орди. Їхній рух може бути повільним, але їхня роль як захисників незаперечна.$B$BСкоро ми зможемо використати цю силу на нашу користь.$B$BЗнайди 3 блукаючих лісових ходунів; убий їх і використай муїсекову посудину, щоб зменшити і захопити їх.",
    O = "Убийте 3 Блукаючих Лісових Ходунів. Використайте Муїсекову Посудину, щоб зменшити і захопити полеглих Треантів.",
    P = "Чи вдалося вам зафіксувати мандрівних лісових гуляків?",
    C = "Дякую, $N. Наша колекція музики майже повна.",
},

[3127] = {
    en = "Mountain Giant Muisek",
    T = "Муїсек Гірського Велетня",
    D = "Останнє завдання, яке я від тебе вимагатиму, — це подорож на північний захід, щоб знайти останнього ворога.$B$BГірські велетні залишили гори, щоб допомогти нічним ельфам, коли Палаючий Легіон з’явився у світі. Ти впізнаєш їх за їхнім величезним розміром і за тим, як земля починає тремтіти, коли ти йдеш їхньою кам’янистою місцевістю.$B$BЯ прагну використати силу такого розміру. Убий 7 гірських велетнів, потім використай муїсекову посудину, щоб захопити їхній потужний муїсек.",
    O = "Убийте 7 Землеходів або Скельних Велетнів. Використайте Муїсекову Посудину, щоб зменшити і захопити полеглих Гірських Велетнів.",
    P = "Чи змогли ви захопити гірських велетнів?",
    C = "Тільки уявіть можливості того, що ми зараз маємо, $N. Разом із матеріалами, які ви зібрали, я зможу назавжди вловити музику цих істот у те, що забажаю.",
},

[3128] = {
    en = "Natural Materials",
    T = "Природні Матеріали",
    D = "Мені потрібні певні матеріали, щоб завершити мою справу… Ти можеш зробити це разом із іншими завданнями, які я тобі дам.$B$BМені потрібен тріснутий колод від треанта з Фераласу. Інкрустовані мінерали, їх можна знайти на гірських велетнях і феєричних драконах на заході. Також знайди мені міцні жили з совозвірів Внутрішніх Земель або гіппогрифів Фераласу. Нарешті, мені знадобиться велика кількість металевих уламків від будь-якої з цих істот, про які я згадував.",
    O = "Принесіть 2 Тріснуті Колоди, 6 Інкрустованих Мінералів, 20 шматків Міцних Жил і 40 Металевих Уламків до відьмака Узер’і в таборі Мохаче.",
    P = "Чи змогли ви зібрати потрібні мені матеріали?",
    C = "Чудово! Ці матеріали в поєднанні з muisek повинні дати саме ті результати, яких ми хотіли.",
},

[3129] = {
    en = "Weapons of Spirit",
    T = "Зброя Духу",
    D = "Вливання муїсеку в зброю — складний процес. Тепер, коли у мене є всі необхідні матеріали і муїсеки створінь, яких ти захопив, я можу почати. Зачекай трохи; я повернуся за мить.",
    O = "Відьмак Узер’і просить вас зачекати хвилинку, поки він готує зброю.",
    P = "",
    C = "Як і обіцяно, у вас є вибір, $N. Muisek створінь назавжди запечатано в силі цієї зброї.$B$BYou тепер можете використовувати їхню енергію як свою власну. Використовуйте це добре.",
},

[3130] = {
    en = "Against the Hatecrest",
    T = "Проти Гребеня Ненависті",
    D = "На цьому етапі я направлю тебе до мого помічника, Латронікуса. Він уважно стежив за силами наґ до цього часу. Я оціню загальну ситуацію тут щодо наґ; наскільки б я не хотів відправити повну силу проти них, залишити фортецю відкритою для прямої атаки Орди — чи навіть гірше — здається не найкращим рішенням.$B$BУ будь-якому разі, Латронікус чекає. Гарна робота досі, $n. Продовжуй у тому ж дусі.$B$BТи вільний.",
    O = "Доповісте Латронікусу Місяцеспису у Фортеці Пір’яного Місяця.",
    P = "",
    C = "Чудово, $N - я ціную ставлення ",
},

