[3281] = {
    en = "Stolen Silver",
    T = "Вкрадене Срібло",
    D = "Ти, можливо, зарубав рапторів, але срібло, яке вони вкрали, потрібно повернути! У мене є звіти, що раптори мають велике скупчення гнізд на південь від Ратчета, відоме як Землі Рапторів. Ймовірно, вони принесли туди наше вкрадене срібло.$B$BВирушай до цього притулку рапторів і шукай вкрадене срібло. Коли знайдеш, поверни його мені.",
    O = "Принесіть Вкрадене Срібло до Газроґа на Перехресті.",
    P = "У вас є срібло?",
    C = "Ага! Отже, хижаки справді сховали срібло у своєму лігві. Важко повірити, що ці звірі бажають срібла. Можливо, історії про їхній інтелект не такі далекі, як я думав!$B$BThank ти, $N. Прийміть це як нагороду за вашу службу нам і знайте, що охоронці перехрестя повинні вам заплатити за наступний місяць.",
},

[3301] = {
    en = "Mura Runetotem",
    T = "Мура Рунетотем",
    D = "Моя одноплемінниця, Мура Рунетотем, вирушила до Срібнохвойового лісу, щоб допомогти нашим союзникам-невмерлим. Срібнохвойовий ліс — хворий ліс, що вмирає, і Мура сподівалася повернути йому нове життя. Можливо, дивне життя, яке ми знайшли тут, у Степах, може допомогти її роботі в Срібнохвойовому лісі.$B$BВізьми зразок панцирів, які ти зібрав, і принеси його Мурі в Срібнохвойовий ліс. Вона зупинилася в Склепі. З удачею, вивчення панцира дасть їй потрібне розуміння, щоб зцілити те вмираюче місце.",
    O = "Поговоріть із Мурою Рунетотем у Склепі.",
    P = "Я відчуваю на тобі запах пилу Степлі, $C. Ви далеко подорожували.",
    C = "Ах, що це? Ця оболонка має внутрішнє сяйво, наче все ще пульсує життям. Дивовижно! Я маю вивчити це далі.$B$BThank ти, $N. Якщо пощастить, у цій мушлі буде таємниця, яку я зможу використати, щоб допомогти бідній країні Сріблястий бор.",
},

[3321] = {
