[3370] = {
    en = "In Nightmares",
    T = "У Кошмарах",
    D = "Цей уламок містить великі таємниці; це чиста сутність Смаречого Сну. Однак те, що я бачу в цьому уламку, — це не сон; таке бачення швидше назвали б кошмаром.$B$BЯ не хочу тебе лякати, $N, але я вважаю, що найкраще, якщо ти якомога швидше передаси цей уламок у руки мудрого друїда…$B$BТобі потрібно знайти Матренґила Ведмедохідця у Кенарійському Колі. Вирушай до Дарнассуса. Більше я не можу сказати.",
    O = "Принесіть Кошмарний Уламок до Матренґила Ведмедохідця в Дарнассусі.",
    P = "Чи можу я вам чимось допомогти?",
    C = "Фалья послав тебе до мене? Ну а тепер давайте подивимося на той осколок, про який, за вашими словами, вона так вагалася говорити...$B$B<Матренгіл вдивляється в осколок>$B$BOh... Я не... Ну.$B$B$N, дякую, що доставили це мені. Але нерозумно говорити про такі речі, раджу вам. Це питання, якими повинні займатися лише друїди Кенаріону.$B$BLet просто кажуть, що в Смарагдовому сні все не так, як ми думали...$B$BМожливо у майбутньому наші шляхи можуть знову перетнутися.",
},

[3371] = {
    en = "Dwarven Justice",
    T = "Дворфійське Правосуддя",
    D = "У моєму серці — порожня, вакуумна діра, де колись було моє серце, $N. Втрата Доріуса — це те, від чого я не скоро оговтаюся. Я мушу виконати його останнє бажання — винуватці цього холоднокровного вбивства мають бути покарані.$B$BПовернися до Палаючого Ущелини і виконай його останнє прохання: Звільни його людей.",
    O = "Поверніться до Палаючого Ущелини і знайдіть археологічну групу Доріуса.",
    P = "",
    C = "Забудь про мене, допоможи іншим.",
},

[3372] = {
    en = "Release Them",
    T = "Звільни Їх",
    D = "Звільни їх, $r. Навіть після того, як їхні тіла здаються, сила Сунтари змушує їх завершувати свої завдання.$B$BВівтар Сунтари — ключ. Іди на північний захід; у пагорбах над печерою… Сутінковий Молот охороняє реліквію. Дістань її і поклади на вівтар Сунтари.$B$B<Вмираючий археолог падає.>",
    O = "Знайдіть Таємничий Артефакт, який охороняють Ідолопоклонники Сутінкового Молота в північно-західному квадранті Палаючого Ущелини.",
    P = "Вівтар порожній.",
    C = "Ви кладете таємничий артефакт на вівтар Сунтари.",
},

[3373] = {
    en = "The Essence of Eranikus",
    T = "Сутність Еранікуса",
    D = "Коли ти торкаєшся самоцвіту, глибокий голос резонує у твоєму розумі.$B$B«Смертний, почуй це благання. Я Еранікус із Зеленого Драконячого Польоту, хранитель цього проклятого храму. Моє завдання — забезпечити, щоб тролі ніколи знову не воскресили свою мерзенну подобу бога, наразі завершилося невдачею. Вливаючи частину моєї сутності в цей самоцвіт, я відчуваю, як мій контроль над Сном перетворюється на хаос. Будь ласка — поклади цей самоцвіт у джерело сутності в моєму лігві, і нехай наша магія там очистить мою психіку від скверни, щоб я міг відпочити.»",
    O = "Покладіть Сутність Еранікуса в Джерело Сутності, розташоване в цьому лігві в Затопленому Храмі.",
    P = "Коли ви наближаєтеся до есенційного шрифту, про який розповів вам Еранік, його голос знову торкається вашого розуму.$B$B",
    C = "Ви розміщуєте дорогоцінний камінь усередині есенційного шрифту.$B$B",
},

[3374] = {
    en = "The Essence of Eranikus",
    T = "Сутність Еранікуса",
    D = "Ти активуєш Клятвений Камінь, і Ітарій говорить безпосередньо у твій розум через камінь.$B$B«Приймаючи завдання, покладене в цей Клятвений Камінь, ти погоджуєшся допомогти моїй справі та справі Драконячого Польоту Ісери у відродженні зіпсованої душі Еранікуса. Перша жертва, одна з багатьох, які ми з тобою, безсумнівно, зробимо, — це передати мені самоцвіт, який скував ту частину психіки Еранікуса, що залишилася вільною.»$B$B«Зроби це, $N, і ми разом працюватимемо над відродженням душі, гідної спасіння.»",
    O = "Принесіть Клятвений Камінь Драконячого Польоту Ісери та Скуту Сутність Еранікуса до Ітарія в Болоті Скорботи. Там ти зробиш свій вибір — допомагати Драконячому Польоту Ісери чи ні.",
    P = "Ось ми $N, на ще одному роздоріжжі. Настав час зробити інший вибір. Який вибір ти робиш, смертний?",
    C = "Ви зробили свій вибір, і все починається. На сьогоднішній день ваш вибір був тим, що я вважав би правильним; ваші дії та вчинки відтепер визначатимуть, чи буде це продовжуватися.",
},

[3375] = {
    en = "Replacement Phial",
    T = "Замінний Фіал",
    D = "Ем... тобі потрібен ще один фіал для віщування? Ти жартуєш, правда? Що ти зробив із першим?! У нас тут багато роботи, $r. Ці фіали не ростуть на деревах! Хоча, я б хотів, щоб вони росли, бо я б пішов і зірвав один, адже в мене немає іншого!!$B$BЩоб зробити тобі новий, мені потрібні такі речі: зілля мани, шматок вугілля і трохи солодкого нектару. Не питай чому, просто принеси те, що я прошу, і я зроблю тобі новий.",
    O = "Принеси Зілля Мани, Вугілля і Солодкий Нектар Талвашу дель Кісселю в Залізогарті, щоб отримати заміну для Фіалу Віщування Талваша.",
    P = "Щоб зробити ще один флакон, мені потрібне зілля мани, шматок вугілля та трохи солодкого нектару.$B$BThat, і, очевидно, ціла купа терпіння.",
    C = "Могутній шукач пригод доставляє. Ура мені. До речі, я збрехав - у мене був інший флакон. Ну, бери.$B$BWell, чого ти очікував?! ",
},

[3376] = {
    en = "Break Sharptusk!",
    T = "Розбити Гостроклика!",
    D = "$N — я чув про тебе, новачку. Можливо, саме ти допоможеш нам там, де інші зазнали невдачі.$B$BМи, таурени, вирізали собі дім із цієї землі, але не без ціни. Кабани Племені Щетиноспинів із Яру Колючого Леза, очолювані Вождем Гострокликом Терновим Плащем, ускладнюють нам життя своєю безперервною війною проти нас. Я доручаю тобі принести мені голову цього вождя!$B$BТи знайдеш його в яру на сході, у їхньому імпровізованому селі.",
    O = "Принеси голову Вождя Гостроклика Тернового Плаща до Хороброго Вітропера на Плато Червоного Хмари.",
    P = "Гострий бивень більше не турбуватиме нас, коли ви принесете мені докази його смерті.  Я шукаю його голову, $N.$B$BWe таурени живуть для полювання, і немає кращого полювання, ніж на того, хто досить хитрий, щоб, можливо, вполювати нас у відповідь.  Якщо ти успішно впораєшся з цим завданням, молодий, ти почнеш розуміти, що я маю на увазі.",
    C = "Справедливість відбулася сьогодні завдяки вашим швидким діям, $N. Нехай цей вчинок стане попередженням для всіх, хто загрожуватиме нашому дому.$B$BYou заслужив цю нагороду, щоб допомогти тобі під час твоєї подорожі, молодий $C.",
},

[3377] = {
    en = "Prayer to Elune",
    T = "Молитва до Елуни",
    D = "Чи допоможеш мені, смертний? Вислухай мою історію.",
    O = "Вислухай розповідь Замаеля.",
    P = "Дозвольте мені закінчити свою розповідь.",
    C = "Я прийняв свою долю тут, у цій клітці, але молитву треба знайти.",
},

[3378] = {
    en = "Prayer to Elune",
    T = "Молитва до Елуни",
    D = "Чи допоможеш мені, смертний? Чи знайдеш ти молитву до Елуни?$B$BЯк я сказав, молитва була вигравіювана на золотій табличці. Один із цих ідолопоклонників-негідників мусить мати її при собі.$B$BЯкщо ти повернеш мою молитву, віднеси її до Астарії Зорешукачки в Дарнасі. Не має значення, що моя віра відновилася після незліченних злодіянь, які я вчинив проти цього світу та його мешканців, але моя молитва мусить бути почута. Спокута — це останнє, на що я сподіваюся.",
    O = "Знайди Молитву до Елуни і віднеси її до Астарії Зорешукачки в Дарнасі.",
    P = "Що привело вас до Храму Місяця, $N?",
    C = "Елуна посміхається тобі цього вечора, $N. Ви повернули їй загублену душу. Будь ласка, прийміть це на знак нашої вдячності.",
},

[3379] = {
    en = "Shadoweaver",
    T = "Тіньоткач",
    D = "Павуки Пекельного Ущелини є безцінним джерелом тіньового шовку. Як ти знаєш, тіньовий шовк дуже цінується майстрами нашого ремесла.$B$BНещодавно група браконьєрів вторглася на ці землі, бездумно вбиваючи павуків масово, не думаючи про довгострокові наслідки їхніх дій. Твоє перше завдання, отже, просте: Знайди їх... і покінчи з ними.$B$BПочни пошуки на півночі.$B$BЯкщо тобі потрібна допомога, поговори з Рейзом.",
    O = "Убий групу Браконьєрів Тіньового Шовку, що блукають Пекельним Ущелиною. Ні літ вважає, що потрібно знищити п’ятьох із них. Повернися до Ніліта в Пекельному Ущелині, коли завдання буде виконано.",
    P = "Якою інформацією ви володієте?",
    C = "Чудова робота, $N.$B$BI впевнений, що це фрагмент тіньового плетива, якого ви ще не бачили.",
},

[3380] = {
    en = "The Sunken Temple",
    T = "Затонулий Храм",
    D = "У цьому світі є неспокійні духи, $N. Є духи, що були спаплюжені своєю ізоляцією, прив’язані до стародавнього зла...$B$BЯ чув про місце, що лежить глибоко під поверхнею землі — вигнане туди силами, більшими, ніж я коли-небудь бачив.$B$BЯкщо ти хочеш дізнатися більше про це місце, Затонулий Храм, шукай гобліна на ім’я Марвон Риветсікач. Він вивчав багато стародавніх місць світу і востаннє, як відомо, покинув свій дім у Ратчеті, щоб досліджувати руїни тролів у Танарісі.",
    O = "Знайди Марвона Риветсікача в Танарісі.",
    P = "",
    C = "Так, Затонулий храм, я можу сказати, що бачив його на власні очі. Можливо, ви хотіли б почути про це більше?$B$BYou схоже на авантюрного типу -- я знаю речі, які можуть вас заінтригувати...",
},

[3381] = {
    en = "",
    T = "Зустріч із Господарем",
    D = "Ах, молодий $r прийшов поговорити з Санатом. Який чудовий день! Я так вшанований, що ти удостоїв мене своєю присутністю. Дякую!$B$BБудь ласка... не будь настільки зарозумілим, щоб вважати мій сарказм компліментом. Давай прояснимо одну річ: ти мені не подобаєшся. Але ця маленька розмова не стосується нас — вона стосується мого господаря.$B$BПринеси мені пару неушкоджених пір’їн гіпогрифа для моїх стріл, і я дозволю тобі побачити його. Він просив, щоб я відправляв до нього шукачів пригод, якщо вони виявляться достатньо гідними.",
    O = "Принеси 2 Неушкоджених Пір’їни Гіпогрифа до Саната Лім-Йо в Азшарі, якщо хочеш поговорити з його господарем.",
    P = "",
    C = "",
},

[3382] = {
    en = "A Crew Under Fire",
    T = "Екіпаж під вогнем",
    D = "Ми були біля узбережжя, шукаючи безпечне місце, щоб кинути якір. Сонце не зайшло й години, як вони напали... ці прокляті наґи!$B$BЯ не впевнений, що вони шукали, але ясно, що вони цього не знайшли — вони вже поверталися один раз. Пара моїх розвідників стежать за входом до долини, щоб попередити нас, коли буде наступний напад.$B$BМені шкода, що ти з’явився саме зараз, $N, але це не в моїх силах.$B$BГотовий до бою за своє життя?",
    O = "Захищай Капітана Ванессу Белтіс, її екіпаж і пасажирів Розвідника Горизонту від нападу наґ. Капітан Ванесса Белтіс мусить вижити.",
    P = "",
    C = "Ви зробили це! дякую! Напевно, це була одна з найжорстокіших битв, у яких я коли-небудь брав участь. Я не можу вам достатньо подякувати.$B$BI хотілося б, щоб більше членів моєї команди пережили це випробування.$B$BI просив би вас поговорити з усіма вцілілими пасажирами Horizon Scout. Дехто з них мав бізнес у цьому районі, і, якщо ви забажаєте, вони можуть отримати до вас кілька запитів. Ще раз дякую за вашу допомогу.",
},

