[3441] = {
    en = "Divine Retribution",
    T = "Божественна відплата",
    D = "Вислухай мою історію, шукачу пригод.",
    O = "Вислухай розповідь Калрана Вітроклина.",
    P = "Дозвольте мені закінчити... $r.",
    C = "Ви чули достатньо? Ви готові діяти?$B$B",
