[3442] = {
    en = "The Flawless Flame",
    T = "Бездоганне полум’я",
    D = "Ти прийняв правильне рішення, $N.$B$BМи мусимо вдарити там, де завдамо найбільшої шкоди: чотири вартові вежі.$B$BЗ чотирма вежами у вогні ми зможемо розпочати наступ, перш ніж вони встигнуть відреагувати.$B$BТобі потрібен відповідний інструмент, щоб підпалити вежі. Для створення цього інструменту потрібні певні матеріали.$B$BПринеси мені чотири серця полум’я і чотири порції олії големів, і я виготовлю смолоскип бездоганного полум’я.$B$BГолеми та елементалі в цих землях мають бути твоєю першою ціллю.",
    O = "Збери 4 Серця Полум’я і 4 Кулі Олії Големів і поверни їх до Калрана Вітроклина.",
    P = "Ви зібрали матеріали?",
    C = "Молодець, $N. Ми майже готові.",
},

[3443] = {
    en = "Forging the Shaft",
    T = "Кування держака",
    D = "Щоб утримувати бездоганне полум’я, нам потрібен держак і оболонка. Спочатку ти мусиш знайти відповідний держак.$B$BНадсмотрщики та работорговці Темного Заліза в Котлі використовують зброю із зачарованого торію, надзвичайно міцного сплаву. Якщо ти принесеш мені вісім торієвих кинджалів, я зможу розкласти сплав і перекувати держак.",
    O = "Принеси 8 Торієвих Кинджалів до Калрана Вітроклина.",
    P = "Вісім, $N. Мені треба вісім!",
    C = "Ви винятковий працівник, $N. Чи думали ви про зміну професії? Можливо, детектив? Збирач сміття? О, я знаю, один із тих дурних гномів, які повзають пляжами Азероту зі своїми металодетекторами, шукаючи втрачений скарб. Так, це була б ідеальна позиція для вас.",
},

[3444] = {
    en = "The Stone Circle",
    T = "Кам’яне Коло",
    D = "Я колись увійшов до зловісних залів Затонулого Храму. Зло в тому місці пронизує всіх, хто входить; я ледь зміг вибратися, пробираючись крізь слиз, що тепер покриває підлогу. Усе, що я пам’ятаю, — це як я спотикався через велику круглу залу, заповнену статуями змій...$B$BНещодавно я виявив круглий камінь, на якому, здається, був вигравіюваний той самий символ змії. Я наказав упакувати його і відправити до моєї майстерні в Ратчеті. Добудь його, і я, можливо, зможу розповісти тобі більше.",
    O = "Забери Кам’яне Коло з майстерні Марвона Риветсікача в Ратчеті.",
    P = "Ratchet недалеко звідси, $N. Подорож не повинна тривати довго.",
    C = "Так... Це камінь.$B$BIt тепер усе повертається до мене, $N...",
},

[3445] = {
    en = "The Sunken Temple",
    T = "Затонулий Храм",
    D = "Я чув про місце, що лежить глибоко під поверхнею землі — вигнане туди силами, більшими, ніж я коли-небудь бачив.$B$BЯкщо ти хочеш дізнатися більше про це місце, Затонулий Храм, шукай гобліна на ім’я Марвон Риветсікач. Як і Тройас та я, він вивчав багато стародавніх місць світу. Востаннє, як відомо, він покинув свій дім у Ратчеті, щоб досліджувати руїни тролів у Танарісі.$B$BУдачі в його пошуках; його давно не чули.",
    O = "Знайди Марвона Риветсікача в Танарісі.",
    P = "",
    C = "Так, Затонулий храм, я можу сказати, що бачив його на власні очі. Можливо, ви хотіли б почути про це більше?$B$BYou схоже на авантюрного типу -- я знаю речі, які можуть вас заінтригувати...",
},

[3446] = {
    en = "Into the Depths",
    T = "У глибини",
    D = "Усередині храму я знайшов круглу залу з шістьма балконами, на кожному з яких стояла статуя змії на краю. З цікавості я штовхнув одну з них, щоб подивитися, що станеться, і це була пастка! Я ледь не впав на смерть від вибуху. Лежачи там на краю, я глянув униз і помітив, що в основі зали була ще одна статуя; щось на кшталт вівтаря... Гаккар, здається, так його називали.$B$BЯ думаю, що цей вівтар — це секрет. Ти мусиш принести цей жетон до вівтаря в Затонулому Храмі.",
    O = "Знайди Вівтар Гаккара в Затонулому Храмі в Болоті Скорбот.",
    P = "Розглядаючи статую, ви помічаєте поглиблення на її боці, розміром як жетон, який дав вам Марвон...",
    C = "Ви просуваєте кам’яне коло в отвір і чуєте, як воно зафіксувалося.$B$BNow камінь на місці, ви можете продовжувати... але що вам робити далі?$B$BМожливо вам слід оглянути цей вівтар далі...$B$B",
},

[3447] = {
    en = "Secret of the Circle",
    T = "Таємниця Кола",
    D = "Мої спогади туманні, але я розповім тобі, що можу. Коло статуй у Затонулому Храмі, хоч і небезпечне, я вірю, що вони приховують секрет, який відкриває ще більший скарб.$B$BВід головного вівтаря я зміг активувати серію вогнів. Я думаю, якщо ти зможеш розгадати, що означають ці вогні, ти, можливо, зможеш відкрити таємниці, що ховаються в цій залі.$B$BПопереджаю, однак, $N. Велике зло лежить у храмі. Ймовірно, усе цінне буде запекло охоронятися...",
    O = "Вирушай до Затонулого Храму і розкрий секрет, прихований у колі статуй.",
    P = "",
    C = "Око ідола яскраво виблискує навіть у напівтемряві храму. Його прозорість відкриває щось блискуче за ним. Посунувши його вбік, ви простягаєте руку й берете те, що лежить усередині статуї.$B$BThe Скарб Атал'ая тепер ваш.",
},

[3448] = {
    en = "Passing the Burden",
    T = "Передача тягаря",
    D = "Нещодавно мені доручили відповідальність за дослідження Азшари — колись прекрасної місцевості, яку ельфи називали домом. Це було ще за часів, коли вони практикували магію. Тепер це місце більш небезпечне, ніж прекрасне, але це не зупиняє нас від того, щоб перевертати кожен камінь у пошуках відповідей на наше минуле.$B$BМій товариш Тимор запропонував допомогти мені досліджувати цю місцевість, оскільки він має особливий інтерес до таких речей.$B$BВін володіє невеликим будинком праворуч від Зали Таємниць тут, у місті.",
    O = "Поговори з Тимором у Залізогарті.",
    P = "",
    C = "А, Карнік тебе прислав? Я сподівався почути від нього незабаром. Я відкрив для себе такі чудові речі про Азшару. Я знаю, що нічні ельфи мають неймовірну тривалість життя, але кожен іноді забуває деякі з більш... нещасливих подій у своєму житті. Це не критика, це лише спостереження.$B$BLong тому були міста, створені ельфами, наповненими знаннями про магію та інші втрачені мистецтва. Будучи студентом таких речей, я почав своє дослідження. Те, що я знайшов, було дуже захоплюючим.",
},

[3449] = {
    en = "Arcane Runes",
    T = "Арканічні руни",
    D = "Магія колись була так само шанована, як сама Елуна, для деяких ельфів. Деякі з їхніх наймогутніших магів створювали руни і таблички, що описували правила аркани та ідеї їхніх відкриттів. Вони залишали ці речі для всіх, щоб роздумували над ними, у громадських місцях.$B$BЯ дуже хотів би мати відбитки цих рун із Руїн Ельдарата. Я маю набір для тебе, щоб зробити відбитки, але тобі доведеться знайти їх самостійно. Будь обережний, Ліга Дослідників — не єдина, хто цікавиться Ельдаратом.",
    O = "Використовуй Набір для Креслення, щоб зробити відбитки Руни Бет’Амара, Руни Джин’яель, Руни Маркрі та Руни Саель’хай, перш ніж вирушити до маленького острова біля південного півострова Азшари і подати сигнал Пілоту Ксіґґсу Ф’юзелайтнеру, щоб він їх забрав.",
    P = "Добре, добре, добре, $N, радий бачити, що ти вийшов сюди. Вам сподобався Тимор?$B$BAs Хоча це місце небезпечне, на узбережжі не надто багато подій. Це може бути через те, що наги плавають під водою, але це не моя проблема... Я патрулюю небо.",
    C = "Радий бачити тебе цілим і неушкодженим, $N. Сподіваюся, для вас усе було не надто важко.$B$BI негайно відвезу це до Тимора. Він із задоволенням подивиться на ці речі.$B$BGo вперед і кинь сигнальну рушницю... мабуть, усе одно тобі це не принесе користі, а я вже придбав нову.",
},

[3450] = {
    en = "An Easy Pickup",
    T = "Легкий забір",
    D = "Я хочу, щоб відбитки доставили до моєї вежі, але немає потреби, щоб ти йшов туди сам. Я просто організую їхній авіапереліт із Азшари.$B$BКсіґґс Ф’юзелайтнер винен мені одну чи дві послуги і незабаром буде в цій місцевості — він підписався патрулювати узбережжя. Поговори з ним, перш ніж підеш. Він може дати тобі сигнальну гармату, щоб подати йому сигнал. Коли матимеш відбитки, просто вирушай туди, куди він тобі скаже, і передай їх йому, щоб він міг безпечно доставити їх до моєї вежі. Він має бути в ангарі у Військовому Кварталі.",
    O = "Поговори з Ксіґґсом Ф’юзелайтнером у Залізогарті.",
    P = "",
    C = "Що я можу для вас зробити, $N? Наразі я трохи зайнятий підготовкою свого корабля до тривалої подорожі. Я щойно прийшов, щоб побачити деяких пілотів танків. Мені потрібні гриви вендіго, щоб укрити мою кабіну, і зазвичай у них є додаткові.$B$BI можу приділити вам хвилину, якщо ви будете короткими... один із хлопців щойно вилетів на базу Стілгрілла, щоб перевірити, чи є у пілотів там додаткові гриви для мене.",
},

[3451] = {
    en = "Signal for Pickup",
    T = "Сигнал для забору",
    D = "Ах, то Тимор тебе послав, га? Так, я винен йому одну чи дві послуги. Що це? О, цей маленький диявол. Так, я можу йому допомогти. Тобі потрібна сигнальна гармата і місце... досить просто.$B$BЄ маленький острів біля південного півострова Азшари, де ми зробили посадкову площадку. Візьми цю сигнальну гармату і використай її там. Я побачу твій сигнал і прилечу, щоб забрати цю... що б це не було, що він хоче.",
    O = "Поговори з Ксіґґсом Ф’юзелайтнером і отримай у нього Сигнальну Гармату Стандартного Зразка в Залізогарті.",
    P = "",
    C = "Ось мій стандартний сигнальний пістолет, і будьте терплячими після того, як вистрілите з нього – в одному з них є лише пара зарядів, і мені може знадобитися хвилина, щоб дістатися до вас, залежно від того, як далеко я в морі. Просто подивіться на море після того, як запустите ракету.",
},

[3452] = {
    en = "The Flame's Casing",
    T = "Оболонка полум’я",
    D = "Нам потрібна одна остання деталь, щоб сформувати смолоскип.$B$BУ горах на північному заході ти знайдеш великий табір Молота Сутінків. Подейкують, що вони носять символи та ідоли, які віддають шану їхньому богу. Ці символи та ідоли можуть містити достатньо магії, щоб сформувати магічну оболонку. Принеси мені один Символ Раґнароса, і я спробую витягти магію з цього предмета, щоб створити оболонку.",
    O = "Знайди і поверни Символ Раґнароса до Калрана Вітроклина.",
    P = "Без відповідного джерела таємної енергії факел відплати не може бути завершений.",
    C = "Символ випромінює мерзенну магію; ідеально підходить для нашого завдання.",
},

[3453] = {
    en = "The Torch of Retribution",
    T = "Смолоскип Відплати",
    D = "Дай мені хвилинку, щоб поєднати деталі і накласти необхідні зачарування.",
    O = "Зачекай, поки Калран Вітроклин завершить створення Смолоскипа Відплати.",
    P = "Не переривайте процес каналізації.",
    C = "Є одне останнє завдання, яке ви повинні виконати.$B$B",
},

[3454] = {
    en = "The Torch of Retribution",
    T = "Смолоскип Відплати",
    D = "Тепер смолоскип мусить бути прив’язаний до його власника. Візьми смолоскип, $N.",
    O = "Візьми Смолоскип Відплати.",
