[3461] = {
    en = "Return to Tymor",
    T = "Повернення до Тимора",
    D = "Тимор не дав мені нічого, щоб заплатити тобі, тож я пропоную тобі поговорити з ним, коли повернешся до Залізогарта. Я впевнений, він усе ще буде у своєму будинку в Містичному Кварталі. Просто постукай і переконайся, що він добре тобі заплатить. Це місце не пікнік... це точно.$B$BЩе раз дякую за те, що допоміг йому, і удачі.$B$BО, і мені не потрібен набір для креслення. Чому б тобі не повернути його Тимору, коли підеш до нього?",
    O = "Поверни Набір для Креслення Тимору до нього в Залізогарт.",
    P = "Ти повернувся! Чудово. У вас також є мій набір для малювання?",
    C = "Чудово! Мені дуже приємно це чути.$B$BI Мені дуже приємно дістатися до моєї вежі та розглянути ці тертя. Я так заздрю ​​тобі... йти в таке місце, як Азшара. Я думаю, що це будь-який учень таємної мрії.$B$BWell, ми ніколи не говорили про будь-яку винагороду, оскільки ти просто працював у Лізі дослідників, але ти на щось заслуговуєш.",
},

[3462] = {
    en = "Squire Maltrake",
    T = "Зброєносець Малтрейк",
    D = "Поговори з моїм посланцем, Зброєносцем Малтрейком. Він дасть тобі подальші інструкції щодо використання Смолоскипа Відплати.",
    O = "Поговори зі Зброєносцем Малтрейком.",
    P = "",
    C = "Чи готові ви завдати удару?$B$B",
},

[3463] = {
    en = "Set Them Ablaze!",
    T = "Підпали їх!",
    D = "Слухай уважно, $N. Хоча чотири вежі ніколи не можна зруйнувати, ти можеш використати Смолоскип Відплати, щоб підпалити їх на дуже довгий час: вогонь, який не може приборкати жоден елемент чи сила.$B$BПоки вони палають, жоден страж чи вартової одиниці не може перебувати на постах спостереження, і таким чином їхня перша лінія оборони нейтралізується.$B$BТи мусиш увійти до кожної вежі і використати Смолоскип Відплати всередині їхніх укріплень. Остерігайся елітних вартових одиниць Темного Заліза, $N.",
    O = "Підпали Північну, Південну, Східну і Західну Вартові Вежі, використовуючи Смолоскип Відплати всередині кожної з будівель.",
    P = "Ти заблукав, $N?",
    C = "Це славно! Чи не славний пан?",
},

[3481] = {
    en = "Trinkets...",
    T = "Дрібнички...",
    D = "Скриня виглядає замкненою.",
    O = "Відкрий скриню.",
    P = "",
    C = "Скриня відкривається від вашого дотику. Скільки тут може бути сиру? Є тільки один спосіб дізнатися.",
},

[3482] = {
