[3601] = {
    en = "Kim'jael Indeed!",
    T = "Кім’джаель, Справді!",
    D = "Кім’джаель, справді!! Чи знаєш ти, що означає Кім’джаель для кривавих ельфів, $N? Маленький щур… чи щось таке. Які ж вони задираки!$B$BВони найняли мене допомогти розвідати місцевість у пошуках якихось загублених скарбів. Звісно, я погодився, щойно вони сказали «скарби» і назвали суму, яку готові заплатити, але, звісно, вони мене зрадили і намагалися вбити… МЕНЕ!$B$BЦе лише доводить, що кривавим ельфам не можна довіряти.$B$BПроблема в тому, що вони досі мають моє спорядження, і я не можу його повернути. Допоможеш мені?",
    O = "Обшукайте Таласійський Табір у пошуках Компаса Кім’джаеля, Прицілу, Фаршированої Курки та Віззлґубера, а потім поверніть їх Кім’джаелю в Азшарі.",
    P = "Ці смердючі ельфи крові. Кажу тобі, якби я був таким сильним, як ти, я б пішов туди й сам навчив їх чомусь! Але мені доведеться заплатити тобі, щоб ти доглядав за ними замість мене.",
    C = "ха-ха! Ви їх добре отримали, чи не так?!$B$BThis чудово! Це навчить цих Кровавих ельфів зраджувати своїх партнерів... особливо такого відданого, як гоблін-торговець! Бах, ельфи крові...!$B$BWell, найменше, що я можу для вас зробити, це заплатити вам за ваш час... як я і сказав, що зроблю.$B$BHere йдіть... це має бути корисним.",
},

[3602] = {
    en = "Azsharite",
    T = "Азшарит",
    D = "Давні скельні велетні південного регіону Азшари споживають каміння та будівлі землі для поживи. Їхні екскременти після цього — це надзвичайно пластичний і дуже міцний кристал, відомий як Азшарит.$B$BЦі утворення розкидані по південній дузі, але мало хто їх збирає через надзвичайно агресивну вдачу велетнів.$B$BТобі потрібно вирушити на південь і зібрати достатньо Азшариту для створення тіла зброї. Мої пекельні гончаки допоможуть у пошуках кристала.",
    O = "Зберіть двадцять Кристалізованих Азшаритів із південної Азшари. Ви можете використати Пекельного Гончака, щоб допомогти вам ‘винюхати’ місця схованих покладів.$B$BПоверніться до Лорамуса, коли завдання буде виконано.",
    P = "Зло не спить, дурень. У вас буде час для відпочинку, коли ви остаточно помрете. А тепер принеси мені ті кристали.",
    C = "Твої завдання в Азшарі виконано, смертний. Тепер я маю виготовити необхідні компоненти для наступного кроку у вашій пригоді.",
},

[3621] = {
    en = "The Formation of Felbane",
    T = "Формування Прокляття Пекла",
    D = "Зброя готова до кування. Ти мусиш віднести загартований азшарит до того, хто здатен опанувати пекельну енергію.$B$BУ Долині Тернистих Лоз є такий коваль. Ґалван Стародавній, лідер Ордену Мітрилу, викує зброю за твоїми вимогами. Ти знайдеш його табір між Зул’Ґурубом і курганом оґрів Мош’Оґґ.$B$BНехай твоя рішучість і віра допоможуть тобі пройти це випробування. Якщо ти зазнаєш невдачі, знай, що твій Бог посміхається тобі, смертний.",
    O = "Віднесіть Вантаж до Ґалвана Стародавнього в Долині Тернистих Лоз.",
    P = "Лорамус, а? Минуло багато років, як я чув це ім'я.",
    C = "Господи, я можу тільки уявити, через що ви пройшли, щоб отримати ці матеріали. Мало хто ризикує потрапити в Азшару та повернутися живим, не кажучи вже про тих, хто стикається з напівбогами та велетнями!$B$B",
},

