[3741] = {
    en = "Hilary's Necklace",
    T = "Намисто Гіларі",
    D = "Моя подруга Гіларі загубила своє намисто, і ми не можемо його знайти. Ми цілий день рибалили тут, і вже шукали навколо. Єдине, що спадає на думку, — воно впало в озеро. Наші батьки не дозволяють нам плавати в озері... моя мама каже, що під водою є якісь злі істоти, але ти виглядаєш так, ніби не боїшся злих речей.$B$BЧи не могли б ви знайти його для неї, будь ласка?",
    O = "Знайди Намисто Гіларі і поверни його Гіларі в Озеросвіт.",
    P = "привіт Я сумую за своїм намистом. Мій тато отримав його для мене. Тато каже, що в озері живуть чудовиська. Ви побили якихось монстрів?",
    C = "Дякую, що знайшли моє намисто, містере $C... ви дуже добрий! Моя киця теж тобі дякує - чи не так, Еффсі?",
},

[3761] = {
    en = "Un'Goro Soil",
    T = "Ґрунт Ун’Ґоро",
    D = "Ґрунт кратера Ун’Ґоро, як кажуть, збагачений потужними магічними властивостями. Кенарійський Круг хоче вивчити цей ґрунт у великих кількостях; вирушай у дикі землі Ун’Ґоро і збери достатньо зразків для наших подальших досліджень.$B$BРодючий ґрунт іноді виділяється купами, а деякі звірі можуть мати придатні зразки на собі. Віднеси їх усі до Ґеде; шукай купи землі та таурена, що гавкає накази. Він добрий, але краще не дратувати його!",
    O = "Принеси 20 зразків ґрунту Ун’Ґоро до Ґеде на Піднесенні Старійшин у Громовому Бескиді.",
    P = "Спокійно, рядовий. Якщо ви тут, щоб вивантажувати землю з Ун'Горо, тоді це чудово! Інакше зникнути.",
    C = "О, це так, рядовий $N, не намагайтеся допомогти мені вивантажити цей ґрунт на купи! Якби Великі Духи хотіли, щоб це було зроблено, вони б зробили це дивом там, нагорі, чи не так?!$B$BArch Друїд Рунний Тотем хоче поговорити з вами знову, але для його наступного завдання ви виявите, що розуміння підмайстром травництва було б корисним. Якщо ви цього не знаєте, він все одно знайде вам застосування.",
},

[3762] = {
    en = "Assisting Arch Druid Runetotem",
    T = "Допомога Архидруїду Рунетотему",
    D = "Вибачте, $c, чи не могли б ви приділити мені хвилинку вашого часу, якщо можливо?$B$BКенарійський Круг у Громовому Бескиді дуже зацікавлений у досвідчених шукачах пригод, таких як ви, щоб допомогти їм у важливому дослідницькому проєкті. Я не знаю деталей, але можу повідомити, що цей проєкт очолює ніхто інший, як Хамуул Рунетотем.$B$BБудь ласка, якщо вас це цікавить, поговоріть із ним безпосередньо на Піднесенні Старійшин у самому Громовому Бескиді.",
    O = "Поговори з Архидруїдом Хамуулом Рунетотемом у Громовому Бескиді.",
    P = "",
    C = "Вітаю, $C; Я радий, що ви зацікавлені допомогти нашим дослідженням. Потрібно багато зробити, і я зроблю вам ведмежу послугу, якщо повідомлю вам, що ця робота не є небезпечною. Сподіваюся, це вас не злякає... але, судячи з вашого вигляду, я розумію, що небезпека — це те, з чим ви вже стикалися раніше.",
},

[3763] = {
    en = "Assisting Arch Druid Staghelm",
    T = "Допомога Архидруїду Оленорогу",
    D = "Вибачте, $c, чи не могли б ви приділити мені хвилинку вашого часу, якщо можливо?$B$BКенарійський Круг у Дарнасі шукає досвідчених шукачів пригод, таких як ви, щоб допомогти їм у важливому дослідницькому проєкті. Я не знаю деталей, але можу повідомити, що цей проєкт очолює ніхто інший, як Архидруїд Фандрал Оленоріг.$B$BБудь ласка, якщо вас це цікавить, поговоріть із ним безпосередньо в Кенарійському Анклаві в самому Дарнасі.",
    O = "Поговори з Архидруїдом Фандралом Оленорогом у Дарнасі.",
    P = "",
    C = "Ну а тепер, $c... оскільки вам повідомили, що я сам керую цим дослідженням, ви, очевидно, прийшли якнайшвидше.$B$BNow що ви тут, обов’язково зверніть увагу, коли я вперше розповім вам деталі; Не маю бажання повторюватися.",
},

[3764] = {
    en = "Un'Goro Soil",
    T = "Ґрунт Ун’Ґоро",
    D = "Ґрунт кратера Ун’Ґоро, як кажуть, збагачений потужними магічними властивостями. Я хочу знати факти, а не вигадки; вирушай у дикі землі Ун’Ґоро і збери достатньо якісних зразків ґрунту для наших подальших досліджень.$B$BТи можеш вважати, що завдання зі збору нижче твоєї гідності; така позиція не викликає симпатії ні в мене, ні в Кенарійського Кругу. Принеси зразки до Дженала, який, без сумніву, марнує час за цим деревом; шукай купи землі. Він займеться логістикою, а не я.",
    O = "Принеси 20 зразків ґрунту Ун’Ґоро до Дженала в Кенарійському Анклаві в Дарнасі.",
    P = "Ах так, бруд. Архідруїд хоче двадцять вантажів на кожного авантюриста, і двадцять вантажів він отримає. Нехай відпадуть ті, хто змовляється проти нас!",
    C = "Вивантажте свій дорогоцінний вантаж тут, шляхетний $C. Мабуть, це був неабиякий тягар... не на відміну від тягаря, який я несу, будучи провидцем. Ось гонорар за вашу роботу, як продиктував сам архидруїд.$B$BArch Друид Стаггельм хоче поговорити з вами знову $N, але для його наступного завдання вам допоможуть, якщо ви добре розумієтеся на травництві. Якщо ви цього не знаєте, ви все одно зможете допомогти Колу!",
},

[3765] = {
    en = "The Corruption Abroad",
    T = "Псування за кордоном",
    D = "Штормовій — такий гамірний осередок діяльності.$B$BЯ прибув здалеку, щоб шукати допомоги. Часто чути, що хоробрі шукачі пригод блукають цими міськими вулицями.$B$BМій брат, Гершала, потребує допомоги в Темнобережжі. Він мешкає в прибережному місті Аубердін.$B$BПодорож довга і епічна. Саме тому я прошу допомоги у досвідченого $c, такого як ти.",
    O = "Вирушай до Гершали Нічношепота в Аубердіні.",
    P = "",
    C = "Отже, мій брат, Аргос, прислав вас? Я розумію, що ви, мабуть, втомилися від своїх подорожей. Але нам є про що поговорити.",
},

[3781] = {
    en = "Morrowgrain Research",
    T = "Дослідження ранкового зерна",
    D = "За допомогою так званої Вічнозеленої Торби ми вирощували насіння Тарлендріса в ґрунті з кратера Ун’Ґоро. Це насіння розквітає у різноманітні випадкові, потужні трави. Одним із результатів є ранкове зерно, загадкова трава, про яку ми мало знаємо; я маю намір розгадати цю таємницю.$B$BВіднеси це до Матренґила внизу, і він дасть тобі трохи насіння, щоб ти міг почати. Якщо насіння закінчиться, тобі доведеться купувати ще у нього.",
    O = "Візьми Ваучер на Насіння Архидруїда до Матренґила Ведмехідця в Кенарійському Анклаві в Дарнасі.",
    P = "Мир і спокій тобі, друже. Ви тут у справах від самого архідруїда, так?",
    C = "Так, цей ваучер розрахований на двадцять пакетів насіння. Якщо у вас закінчиться, ми можемо надати більше. На жаль, насіння Tharlendris є досить дорогим для виробництва у значній кількості. Ось чому Коло Кенаріону просить тих, хто нам допомагає, допомогти, компенсувавши частину витрат.$B$BThose, які повернулися з морроуграйном, виявили, що винагорода, яку пропонує архідруїд, значно компенсує витрати.",
},

[3782] = {
    en = "Morrowgrain Research",
    T = "Дослідження ранкового зерна",
    D = "За допомогою так званої Вічнозеленої Торби ми вирощували насіння Тарлендріса в ґрунті з кратера Ун’Ґоро. Це насіння розквітло у різноманітні випадкові, потужні трави. Одним із результатів є ранкове зерно, загадкова трава, про яку ми мало знаємо; я дуже сподіваюся розгадати цю таємницю для Кругу.$B$BВіднеси цей ваучер до моєї доньки Башани, і вона дасть тобі трохи насіння, щоб ти міг нам допомогти. Якщо насіння закінчиться, тобі доведеться купувати ще у неї.",
