},

[3787] = {
    en = "Jonespyre's Request",
    T = "Прохання Джонспайра",
    D = "Вибач, друже...$B$BМій колега хотів би поговорити з тобою про дослідження, які ти проводиш разом із Кенарійським Кругом. Він друїд на ім’я Квінтіс Джонспайр, і він мешкає у Фортеці Пір’яного Місяця, Фералас. Він хоче обговорити з тобою ранкове зерно... і дуже просить, щоб наша розмова не дійшла до вух Архидруїда.$B$BЯкщо тебе це цікавить, поговори з ним; без сумніву, усе стане ясно, коли ти це зробиш.",
    O = "Поговори з Квінтісом Джонспайром у Фортеці Пір’яного Місяця.",
    P = "",
    C = "Я дякую тобі, що прийшов, стомлений подорожній!  Дозвольте представитися: я Квінтіс Джонспайр, друїд і покірний слуга Малфуріона та Кенаріонського кола.  Ми з моїми колегами (генерал Шандріс Фізермун і Протекторат — можливо, ви про нас чули) хотіли поговорити з вами про роботу, яку ви виконуєте для Фандрала Стаггельма в Дарнасі.$B$BBefore ми просунулися набагато далі, я хотів би попросити, щоб наша дискусія залишилася лише між нами.  Якщо у вас з цим немає проблем, ми можемо продовжити.",
},

[3788] = {
    en = "Jonespyre's Request",
    T = "Прохання Джонспайра",
    D = "Вибач, друже...$B$BМій колега хотів би поговорити з тобою про дослідження, які ти проводиш разом із Кенарійським Кругом. Він друїд на ім’я Квінтіс Джонспайр, і він мешкає тут, у Фортеці Пір’яного Місяця. Він хоче обговорити з тобою ранкове зерно... і дуже просить, щоб наша розмова не дійшла до вух Архидруїда.$B$BЯкщо тебе це цікавить, поговори з ним; без сумніву, усе стане ясно, коли ти це зробиш.",
    O = "Поговори з Квінтісом Джонспайром у Фортеці Пір’яного Місяця.",
