},

[3789] = {
    en = "Assisting Arch Druid Staghelm",
    T = "Допомога Архидруїду Оленорогу",
    D = "Вибачте, $c, чи не могли б ви приділити мені хвилинку вашого часу, якщо можливо?$B$BКенарійський Круг у Дарнасі шукає досвідчених шукачів пригод, таких як ви, щоб допомогти їм у важливому дослідницькому проєкті. Я не знаю деталей, але можу повідомити, що цей проєкт очолює ніхто інший, як Архидруїд Фандрал Оленоріг.$B$BБудь ласка, якщо вас це цікавить, поговоріть із ним безпосередньо в Кенарійському Анклаві в самому Дарнасі.",
    O = "Поговори з Архидруїдом Фандралом Оленорогом у Дарнасі.",
    P = "",
    C = "Ну а тепер, $C... оскільки вам повідомили, що я сам керую цим дослідженням, ви, очевидно, прийшли якнайшвидше.$B$BNow що ви тут, обов’язково зверніть увагу, коли я вперше розповім вам деталі; Не маю бажання повторюватися.",
},

[3790] = {
    en = "Assisting Arch Druid Staghelm",
    T = "Допомога Архидруїду Оленорогу",
    D = "Вибачте, $c, чи не могли б ви приділити мені хвилинку вашого часу, якщо можливо?$B$BКенарійський Круг у Дарнасі шукає досвідчених шукачів пригод, таких як ви, щоб допомогти їм у важливому дослідницькому проєкті. Я не знаю деталей, але можу повідомити, що цей проєкт очолює ніхто інший, як Архидруїд Фандрал Оленоріг.$B$BБудь ласка, якщо вас це цікавить, поговоріть із ним безпосередньо в Кенарійському Анклаві в самому Дарнасі.",
    O = "Поговори з Архидруїдом Фандралом Оленорогом у Дарнасі.",
    P = "",
    C = "Ну а тепер, $C... оскільки вам повідомили, що я сам керую цим дослідженням, ви, очевидно, прийшли якнайшвидше.$B$BNow що ви тут, обов’язково зверніть увагу, коли я вперше розповім вам деталі; Не маю бажання повторюватися.",
},

[3791] = {
    en = "The Mystery of Morrowgrain",
    T = "Таємниця ранкового зерна",
    D = "Буду відвертим із тобою, $N. Мене цікавить — ні, турбує — чому Архидруїд у Дарнасі використовує ім’я Кенарійського Кругу, а також ресурси Кругу, щоб добути величезну кількість ранкового зерна. Я дослідник — прокляття моя спеціальність. Я чув, що ранкове зерно за певних умов виділяє властивості, подібні до інших трав, що використовуються в примітивних прокльонах.$B$BЯ хочу знати більше, і я прошу твоєї допомоги. Принеси мені десять ранкових зерен, і я подбаю про твою винагороду.",
    O = "Принеси 10 Ранкових Зерен до Квінтіса Джонспайра у Фортеці Пір’яного Місяця.",
    P = "Я шукаю десять морроугрейнів — цього має бути достатньо, щоб принаймні розпочати дослідження.  Безсумнівно, я спалю багато тих, хто йде хибним шляхом, але така природа дослідження.",
    C = "Гах, ці морроузерна змушують мене почуватися... дивно.  Що, в ім’я Елуни, Staghelm задумав із цими речами?$B$BAnyway, ще раз дякую за допомогу.  Ось дещо... знаєте, за зусилля.  Моє дослідження morrowgrain займе деякий час, і мені, безсумнівно, знадобиться більше.  Поки я вже на цьому, гадаю, я міг би знайти час, щоб перевірити, чи має морроуграйн якесь доречне алхімічне використання.  І все-таки я почуваюся некомфортно навіть поруч з ними.",
},

[3792] = {
    en = "Morrowgrain to Feathermoon Stronghold",
    T = "Ранкове зерно до Фортеці Пір’яного Місяця",
    D = "",
    O = "",
    P = "Знову привіт, $N. Мої дослідження просуваються досить добре, але якщо у вас є ще п’ять Morrowgrain, я з радістю заберу їх у вас. Ну... щасливий — це образний термін у цьому випадку; чим більше я поруч з ними, тим незручніше почуваюся. І все-таки мої дослідження вимагають, щоб я зважився й пройшов через це.",
    C = "Дякую $N; Я поки що приберу їх подалі.  Хоча я не розпоряджаюся тими ресурсами, як Staghelm, я можу дати вам дещо для вирішення ваших проблем.  У будь-якому випадку, хто знає, що станеться, якщо Staghelm продовжуватиме отримувати Morrowgrain за Morrowgrain.  Відбувається щось підозріле, запам’ятайте мої слова.$B$BRemember що я завжди шукаю більше Morrowgrain.  Я візьму їх по п’ять штук за раз.",
},

[3801] = {
    en = "Dark Iron Legacy",
    T = "Спадщина Темного Заліза",
    D = "Вітаю, $N. Я Франклорн Форджрайт. Так, той самий Франклорн Форджрайт, відповідальний за метод кам’яного будівництва. Ти, без сумніву, проходив повз або стояв на одному з моїх творінь під час своїх пригод у нашому розтерзаному війною світі.$B$BТи, мабуть, цікавишся, чому я тут і що я хочу від тебе — цілком слушні питання.$B$BМені потрібна твоя допомога, звісно. В обмін на твою допомогу я дам тобі ключ до глибин мого проклятого міста.",
    O = "Поговори з Франклорном Форджрайтом, якщо тебе цікавить отримання ключа до головного міста.",
    P = "",
    C = "Незалежно від того, чи це жадібність привела вас сюди, чи акт безкорисливої ​​відданості, те, що ви збираєтеся зробити, є для блага всіх нас.",
},

[3802] = {
    en = "Dark Iron Legacy",
    T = "Спадщина Темного Заліза",
    D = "Ти знайдеш Фінеуса Темножила за Кільцем Закону, у Залі Ремесел. Убий цього жалюгідного пса і поверни Залізозуб.$B$BВіднеси Залізозуб до Святилища Тауріссана і поклади молот на його законне місце: у руки статуї, зведеної на мою честь.$B$BКоли це буде зроблено, відкриється відділення, у якому я зберігав головний ключ. Що ще важливіше, Залізозуб назавжди залишиться в моїх руках. Якщо вони спробують забрати молот, і статуя, і молот розіб’ються, втрачені назавжди.",
    O = "Убий Фінеуса Темножила і поверни великий молот, Залізозуб. Віднеси Залізозуб до Святилища Тауріссана і поклади його на статую Франклорна Форджрайта.",
    P = "Статуя зловісно маячить над вами.",
    C = "Молот міцно ковзає на місце, в межах обхвату масивного монумента з темного заліза. У підставі статуї відкривається крихітне відділення. Всередині ви знайдете...",
},

[3803] = {
    en = "Morrowgrain to Darnassus",
    T = "Ранкове зерно до Дарнаса",
    D = "",
    O = "",
    P = "Архідруїд завжди шукає додаткову зернину для продовження досліджень Кола Кенаріону. Ми беремо їх із кроком по десять і нагороджуємо вас кешом товарів, які вам знадобляться. Коли у вас буде десять, дайте мені знати, і я винагороджу вас відповідно.",
    C = "Чудово - це завтрашнє зерно, без сумніву, сподобається Архі-друїду.  Я повинен визнати, що... просто перебуваючи поруч з ними, я відчуваю себе трохи незручно.  Я можу тільки уявити, як важко архидруїду терпіти їх у такій великій кількості!$B$BThis для вас, $N.  The Cenarion Circle дякує вам за вашу постійну підтримку.",
},

[3804] = {
    en = "Morrowgrain to Thunder Bluff",
    T = "Ранкове зерно до Громового Бескиду",
    D = "",
    O = "",
    P = "Архідруїд завжди шукає більше зерна для дослідницького проекту Кола Кенаріону на кратері Ун'Горо. Ми беремо їх із кроком по десять і нагороджуємо вас кешом товарів, які вам знадобляться. Коли у вас буде десять, дайте мені знати, і я нагороджу вас відповідно.",
    C = "Чудово – це завтрашнє зерно, без сумніву, допоможе, коли прийде час.  Ми знаємо, що нічні ельфи проводять подібні дослідження цих трав, хоча незрозуміло, з якою метою вони їх використовуватимуть, якщо щось виявлять.  Архідруїд вважає, що потреба в зерні морроу залишатиметься, доки ми не розгадаємо таємниці цієї трави.$B$BThis для вас, $N.  The Cenarion Circle дякує вам за вашу постійну підтримку.",
},

[3821] = {
    en = "Dreadmaul Rock",
    T = "Скеля Жахокруш",
    D = "Ша’ні відправили розслідувати повідомлення про дивну ритуальну діяльність, що надходить від огрів Вогнетривів із Палаючих Степів, понад три тижні тому.$B$BҐортут каже мені, що він не чув нічого від нікого з того загону і що краще мені рухатися далі і зосередитися на поточному завданні. Чи можеш ти в це повірити? Це моя дружина!$B$BЯ не можу залишити свій пост, $N, але я мушу знати, що сталося з Ша’ні. Вирушай до Палаючих Степів і розшукай її.",
    O = "Вирушай до Палаючих Степів і дізнайся, що сталося з Ша’ні Гордокивцем.",
    P = "",
    C = "Мій бідолашний Тал'трак.$B$BWe планував переїхати до моїх матері й тата у Внутрішні землі після того, як наші тури закінчаться. Тепер ці плани зруйновані!",
},

[3822] = {
    en = "Krom'Grul",
    T = "Кром’Ґрул",
    D = "Увесь мій загін був захоплений, $N. Усіх зарубали — крім мене.$B$BЇхній лідер, Кром’Ґрул, хотів зберегти мене для якогось ритуалу.$B$BМене прикували до цього вівтаря і катували звір. Моє фізичне єство перестало функціонувати після години цих тортур. Потім звір зірвав мою весільну носову каблучку з мого обличчя і надів її на свій палець. Я ніколи не бачив такої дикості!$B$BЗнайди Кром’Ґрула і вбий його! Поверни мою каблучку до Тал’трака.$B$BІ $N, скажи йому, що ми зустрінемося знову... в іншому житті.",
    O = "Поверни Носову Кільце Ша’ні від Кром’Ґрула і віддай його Тал’траку в Карґаті. Шукай у різних печерах і шахтах Скелі Жахокруш.",
    P = "Ти знайшов Шані? вона в порядку?",
    C = "<Тал'трак падає.>$B$BWe збиралися переїхати до Внутрішніх земель. Вона тобі сказала? Це мала бути її остання місія.$B$B<Тал'трак ридає.>$B$BI не хочу цього, $N. Тримай, викинь, мені все одно! Каблучка тепер для мене нічого не означає. Не без неї...",
},

[3823] = {
    en = "Extinguish the Firegut",
    T = "Загасити Вогнетривів",
    D = "Ми мусимо вдарити по наших ворогах, перш ніж вони вдарять по нас!$B$BЯ буду коротким, солдате.$B$BОгри Вогнетриви з Палаючих Степів — союзники орків Чорноскелі. Вони тісно співпрацюють із цими мерзенними орками, охороняючи багаті на мінерали Скелю Жахокруш і тримаючи лінії постачання завжди відкритими.$B$BЗалиш свій слід, $N. Ослаб їхні сили і повернися до мене, коли завдання буде виконано.$B$B<Ораліус хапає повітря і робить задушливий жест.>$B$Я ВБ’Ю ТЕБЕ, ВІНКІ!",
    O = "Убий 15 Магів-Огрів Вогнетривів, 7 Огрів Вогнетривів і 7 Брутальних Огрів Вогнетривів, а потім повернися до Ораліуса, коли закінчиш.",
    P = "На твоєму мундирі майже не вистачає крові, солдате!",
    C = "Відмінно, солдате! Орки та огри будуть боліти від цього удару хвилини, а може, й години!",
},

[3824] = {
    en = "Gor'tesh the Brute Lord",
    T = "Ґор’теш, Лорд-Брут",
    D = "Вони відступають, кажу тобі! Наш наступний удар мусить бути вирішальним.$B$BЛорд-брут, Ґор’теш, мусить бути убитий. Що ще важливіше, його голову треба принести мені, щоб я міг підготувати третю фазу нашого нападу на огрів Вогнетривів.$B$BПопереджаю, солдате, Ґор’теш править не зі Скелі Жахокруш, а з будівлі орків Чорноскелі на захід від Скелі Жахокруш.$B$BТвої накази прості. Знайди Ґор’теша і відрубай його товсту голову. Повернися до мене, коли завдання буде виконано.$B$BЗАМОВКНИ, ВІНКІ!",
    O = "Знайди Ґор’теша, десь на захід від Скелі Жахокруш. Убий Ґор’теша і потім принеси Відрубану Голову Ґор’теша назад до Ораліуса в Палаючих Степах.",
    P = "О славний день! Ти повернувся з головою?",
    C = "Ви тільки подивіться, солдате. Огидно! Коли огри, що залишилися, побачать цей товстий кухоль, застряглий на щуці, що сидить на вершині їхньої гори, почнеться масова істерія!$B$B<Ораліус дико регоче.>",
},

[3825] = {
    en = "Ogre Head On A Stick = Party",
    T = "Голова Огра на Палиці = Вечірка",
    D = "Лише одне останнє завдання, солдате.$B$BЯ взяв на себе сміливість насадити голову Ґор’теша на спис. Тепер усе, що тобі потрібно зробити, — це віднести цю голову на вершину Скелі Жахокруш і встромити її в землю. Як тільки ти це зробиш, спостерігай, як ці боягузливі огри розбігаються, рятуючи свої життя! Після того, як ти повеселишся, повернися до мене, і я винагороджу тебе за всю твою важку працю.$B$B<Ораліус, здається, втрачає зв’язок із реальністю.>",
    O = "Візьми Відрубану Голову Ґор’теша і розмісти її на вершині Скелі Жахокруш. Шукай м’який земляний насип, щоб увіткнути спис.",
    P = "так? Ви малювали якісь фотографії події?",
    C = "Чудова робота, солдате! Просто неймовірно! О, я отримаю за це медаль за хоробрість, е-е, я маю на увазі, що ти будеш щедро винагороджений за це!",
},

[3841] = {
    en = "An Orphan Looking For a Home",
    T = "Сирота шукає дім",
    D = "О, привіт, $N. Я так рада знову тебе бачити. Як пройшла твоя подорож до Дарнаса?$B$BТобі буде приємно дізнатися, що ми досягли значного прогресу, поки тебе не було. Ми навіть врятували гніздо з яйцями. На жаль, мати померла, перш ніж ми до неї дісталися.$B$BСкажи, чи не хотів би ти взяти одне яйце собі як улюбленця? Вони скоро вилупляться, тож їм потрібен хороший $Gбатько:мати;. Що скажеш?$B$BЯкщо тобі дійсно цікаво, візьми одне з яєць до Квентіна на гоночних трасах у Мерехтливих Рівнинах. Він розповість тобі більше.",
    O = "Поговори з Квентіном у Тисячі Голок.",
    P = "Привіт, $C.$B$BDon Нехай моє місцезнаходження вас не вводить в оману, я справді тут не для перегонів... якими б цікавими вони не були.$B$BI Насправді я тут, у Тисячі голок, досліджую все можливе, щоб дізнатися, наскільки можна врятувати землю. Це стало моїм своєрідним хрестовим походом, щоб оживити та поповнити територію новим, родючим ґрунтом. Можливо, я знайду, що поблизу є джерело води.$B$BTell ти не помітив, яким дивним є перехід між Фераласом і Тисячею голок. Коли це сталося, діяла дивна магія.",
    C = "Ах, яйце спрайт-дротика, і одне, яке майже дозріло, якщо я не помиляюся. Чудово, що ви знайшли один, не кажучи вже про такий гарний стан. Сьогодні їх рідко можна побачити у Фераласі. Я розумію, що в цьому районі були різні браконьєри, які намагалися зловити та вбити їх з багатьох причин. Дуже шкода... такі гарні створіння, коли вони досягають повноліття.$B$BHow Ви зустрічали таку знахідку?",
},

[3842] = {
    en = "A Short Incubation",
    T = "Коротка інкубація",
    D = "Місячні Ткачі, так? Дуже цікаво. Я б хотів, щоб спрайт-дартери по-справжньому оцінили, що означає мати таких двох опікунів. Вони обидва дуже здібні.$B$BОтже, вони подарували тобі яйце. Тоді ти маєш бути відповідальним за нього, поки цього бажаєш. Схоже, воно майже готове вилупитися, але ми повинні переконатися, що воно здорове і не зазнало жодних пошкоджень.$B$BМені потрібно лише два еліксири стійкості для невеликого заклинання, щоб захистити яйце. Усі інші компоненти у мене є.",
    O = "Принеси 2 Еліксири Стійкості до Квентіна в Тисячі Голок.",
    P = "Чим довше я залишаюся тут, тим більша спокуса взяти участь у цих перегонах, $N. Справді вражаюче...$B$BHave ви вже знайшли еліксири? Щойно я зможу визначити, чи яйце буде здоровим, я поверну його вам, щоб ви потримали його, поки воно не буде готове до вилуплення.$B$BLet я знаю.",
    C = "чудово Це буде добре. Дайте мені хвилинку, щоб змішати мої компоненти, і ми побачимо, наскільки вдасться це яйце.",
},

[3843] = {
    en = "The Newest Member of the Family",
    T = "Новий член сім’ї",
    D = "Чудовий екземпляр, $N. Якщо ця істота переживе виношування, то це буде дійсно здоровий улюбленець!$B$BЄ ще одна річ, яку я б порадив зробити, якщо ти плануєш довести це до кінця — вирушай до Пікової Вершини в Запоємних Землях. Поговори там із дворфом на ім’я Аґнар Звіролагід, він майстер поводження з тваринами і зможе направити тебе на останніх етапах інкубації.$B$BАле поспіш, $N, це яйце крихке і не протримається довго без належного догляду.",
    O = "Візьми своє Крихке Яйце Спрайт-Дартера до Запоємних Земель і поговори з Аґнаром Звіролагідом, але поспіш, у тебе лише 1 година, щоб знайти його, перш ніж пташеня в яйці загине.",
    P = "Вітання, $N. Як я можу бути тобі корисним?",
    C = "Ну, ну, ну... Я такого не бачив у епоху дракона. Феєричний дракон, якщо я не помиляюся... схоже на спрайт-дротик. Чудово, справді чудово.$B$BWell, якщо цей маленький хлопець вилупиться і доживе, щоб бути сильним і здоровим, тоді ми повинні отримати за це їжу. Добре, що ти вчасно це отримав.",
},

[3844] = {
    en = "It's a Secret to Everybody",
    T = "Це секрет для всіх",
    D = "Зруйнований пліт лежить уздовж берегової лінії. Оскільки це лише маленький ставок, незрозуміло, як він тут опинився, хоча, дивлячись на дерева, можна зрозуміти, що рівень води може бути нестабільним.$B$BМожливо, невелике дослідження в цій місцевості може розкрити більше підказок...",
