[3861] = {
    en = "CLUCK!",
    T = "КВО!",
    D = "«Кво... кво... кво... БАКАВ!$B$BКво... кво... кво.»$B$BКурка дивиться на тебе і починає дряпати кігтями по землі. Тобі здається, що вона виписує слово, але ти не впевнений, що це. Чи може це бути... С-А-Л-Д-І-Н? Перш ніж ти встигаєш запитати, курка відвертається і повертається до своїх справ.",
    O = "Знайди Особливий Курячий Корм і повернися до своєї дружньої курки. Коли знайдеш її, /cheer перед тим, як спробувати дати їй Особливий Курячий Корм.",
    P = "Курка дивиться на вас темними холодними очима. Він жадібно чекає на вас.$B$B",
    C = "",
},

[3881] = {
    en = "Expedition Salvation",
    T = "Порятунок експедиції",
    D = "Я не знаю, як ти сюди потрапив, але ти — приємна картина для втомлених очей! Я Вілліден Маршал, і я очолюю неафілійовану експедиційну групу. Наша остання і найвеличніша справа зазнала, здається, незліченних катастроф, найсерйозніша з яких — ми недооцінили дикість кратера Ун’Ґоро!$B$BКоли ми тікали з наших базових таборів у південно-західній і північно-східній частинах кратера, ми залишили важливі припаси. Ти виглядаєш досить здібним — чи можеш допомогти нам повернути їх?",
    O = "Принеси Ящик із Їжею та Дослідницьке Обладнання до Віллідена Маршала в кратері Ун’Ґоро.",
    P = "Якщо ми хочемо мати хоч якийсь шанс вибратися звідси живими, нам знадобиться наш великий ящик з продуктами.  Крім того, отримати принаймні частину нашого дослідницького обладнання було б благословенням у морі нещасть.",
    C = "Ви отримали і наші продукти харчування, і наше дослідницьке обладнання! Ви не тільки врятували експедицію, ви також врятували наші життя. Я та решта моєї команди не можемо вам достатньо подякувати; ми просто можемо протриматися тут на деякий час завдяки вам.$B$BWhile у нас небагато, я точно не збираюся залишати вас сухими за ту неоціненну допомогу, яку ви нам надали. Дякуємо, $N – у Marshal Expeditions у вас є друг!$B$B",
},

[3882] = {
    en = "Roll the Bones",
    T = "Кидання кісток",
    D = "Ти думаєш, що бути головним копачем експедицій Маршала означає, що мені подобається копати. Може, є й гірші заняття в цьому світі... але жодне не спадає на думку.$B$BМи мали копати в Жахобігу — до речі, ФАНТАСТИЧНА назва — за мертвими стегодонами і діаметрадонами. Ну, там також повно живих! Віл і Хол усе ще хочуть вивчати цю смертельну пастку, тож нам потрібні ці кістки динозаврів. Але між нами, принести їх від живих спрацює так само добре.",
    O = "Принеси 8 Кісток Динозаврів до Спарка Нілмайнера в кратері Ун’Ґоро.",
    P = "Думайте про мене що завгодно, але їх не хвилюватиме, чи кістки, які вони візьмуть на дослідження, належать до стародавніх стегодонів і діметрадонів чи тих, які мало не з’їли нас повністю, коли ми намагалися розбити свої табори.  Я буду радий, якщо ми виберемося звідси живими...",
    C = "Чудово, вони повинні зробити свою справу.  А тепер, якщо ви мені дозволите...$B$BTHANKS ЗА ТОГО, ЩО ВИКОПАЛИ ДЛЯ НАС УСІ ЦІ КІСТКИ З-ЗЕМЛІ І ЖОДНИМ ШЛЯХОМ НЕ ПОШКОДИЛИ РІДНИХ ЗВІРІВ.$B$BWhether ви справді зробили це чи ні, я не хочу знати.  Нехай так і залишиться, чи не так?  Ось - можливо, це триматиме ваші губи на цілій справі.  Все, щоб вибратися звідси живим, я кажу!",
},

[3883] = {
    en = "Alien Ecology",
    T = "Чужа екологія",
    D = "Те, що ми зазнали невдачі, не означає, що дослідження повинні зупинитися! Ми досліджували комах Ґорішів у південній частині кратера, перш ніж опинилися тут. Їхня присутність чужа для екології Ун’Ґоро, і ми хочемо з’ясувати чому.$B$BУ їхній мережі вуликів мають бути личинкові розплідники. Ти можеш визначити ці місця за їхніми висячими личинковими виводками. Використай цю склянку, щоб узяти зразок стіни вулика біля будь-якого з розплідників. Принеси його мені для вивчення, але будь обережний!",
    O = "Використай Склянку для Соскоблювання, щоб зібрати Зразок Стіни Вулика з одного з розплідників вуликів Ґорішів у кратері Ун’Ґоро. Шукай зали з висячими личинковими виводками.$B$BПринеси Зразок Стіни Вулика до Хол’аньї Маршал у кратері Ун’Ґоро.",
    P = "У вас є зразок вулика Горіші для вивчення, $N?",
    C = "Так, це буде добре. Ви дуже допомогли... Я хотів би дати вам більше, але те, що я фактично опинився посеред дикої землі, обмежує те, що я можу і не можу дати. Але будьте впевнені – дослідження, проведене тут, було б неможливим без вашої допомоги!",
},

[3884] = {
    en = "Williden's Journal",
    T = "Журнал Віллідена",
    D = "Ти виявив пошарпаний журнал. Частина його залишається читабельною, і Вілліден Маршал стверджує, що він є власником його вмісту. Якщо журнал точний, то Віллідена можна знайти десь у північній частині кратера; згідно з журналом, він і його супутники шукали вищу місцевість від диких звірів кратера, коли їхні базові табори були захоплені.",
    O = "Поверни журнал до Віллідена Маршала десь у кратері Ун’Ґоро.",
    P = "Привіт!  Я і мої товариші раді бачити тут ще якихось живих істот, крім зарослих диких звірів!  Що привело вас у кратер Ун'Горо?",
    C = "Ну подивіться на це - мій щоденник!  Я думав, що його загубили, як і майже все інше, що ми привезли в Ун'Горо.  Я щиро дякую, що повернули це мені!",
},

