},

[3924] = {
    en = "Samophlange Manual",
    T = "Посібник із Самофланґа",
    D = "Я думаю, що можу полагодити самофланґ, але спочатку мені потрібен посібник користувача. Коли я був у Компанії Венчур, у мене був суперник, Бос Куперплаґ, який приховував секрети самофланґа, видаючи маленькі шматочки знань про пристрій тим, кому він довіряв. Я не був одним із тих, кому він довіряв...$B$BБос Куперплаґ зазвичай залишався в шахті Валунового Рудника в північно-східних Степах. Дістань посібник від нього, і якщо він віддав сторінки з нього комусь іншому, тобі доведеться зібрати їх також.",
    O = "Принеси Посібник із Самофланґа до Ріллі Ґрісіґоба в Орґріммарі.",
    P = "У вас є посібник?",
    C = "Ви отримали посібник! Я не можу дочекатися, щоб прочитати це і дізнатися, як виправити Samophlange! Я розмовляв із Sputtervalve у Ratchet—він хотів подякувати вам за вашу допомогу та винагородити ваші зусилля.$B$BI теж хочу подякувати вам, і якщо я колись виправлю цю проблему, я дам вам знати...",
},

[3941] = {
    en = "A Gnome's Assistance",
    T = "Допомога гнома",
    D = "Думаю... Думаю... Я знаю, що прийшов сюди за чимось важливим...$B$BУ мене є ідея, $N. У печері там є гномка на ім’я Джей.Ді., яка була дуже доброю до мене, коли я тільки прибув сюди. Можливо, у моєму дезорієнтованому стані я міг щось їй згадати.$B$BЧому б тобі не піти запитати її, чи знає вона щось? О, але будь обережний — вона завжди возиться з тими божевільними сяючими кристалами, які я бачив у кратері. Я не зовсім впевнений, що вона там задумала!",
    O = "Знайди Джей.Ді. Коллі в печері в Притулку Маршала.",
    P = "",
    C = "Залишся на хвилинку... Я тестую нову комбінацію кристалів...",
},

[3942] = {
    en = "Linken's Memory",
    T = "Пам’ять Лінкена",
    D = "О... Лінкен? Так, він кумедний. Коли він тільки прибув сюди, він бурмотів про всякі дивні речі. Мабуть, добряче вдарився головою, я гадаю.$B$BАле щось, що він сказав, таки запам’яталося мені — що він робив якийсь тотем; сказав, що мусить поговорити з кимось на ім’я Ерідан Синьовітер... у місці, яке називається Сквернолісся, здається?$B$BСумніваюся, що він може тобі багато розповісти зараз. Якщо хочеш дізнатися більше, можливо, тобі варто самому шукати Ерідана?",
    O = "Знайди Ерідана Синьовітра в південному Сквернолісі.",
    P = "",
    C = "Привіт, $C. Я можу вам чимось допомогти?",
},

[3961] = {
    en = "Linken's Adventure",
    T = "Пригода Лінкена",
    D = "Подумати тільки, весь цей час Лінкен приходив сюди, щоб позбутися Пламеносця... Він здається таким звичайним хлопцем, але я помітив, що він зовсім не цікавиться моїми експериментами чи ґаджетами, як більшість гномів. Він, мабуть, справжній воїн у душі.$B$BВіднеси тотем до нього. Подивимося, чи допоможе це йому згадати, чому він сюди прийшов.",
    O = "Візьми Срібний Тотем Аквементаса до Лінкена в Притулку Маршала.",
    P = "Знову привіт, $N!",
    C = "Чи допоміг вам Дж.Д.?",
},

[3962] = {
    en = "It's Dangerous to Go Alone",
    T = "Небезпечно йти самому",
    D = "$N, я нарешті згадав... Я дійсно прийшов сюди, щоб битися з Пламеносцем. Я був у подорожі, і це мав бути останній крок.$B$BАле я більше не герой... Ти ним є. Усе, що ти зробив — ти мусиш завершити це зараз, не я.$B$BПламеносець охороняє артефакт, який називається Золоте Полум’я. Воно дає силу, більшу за все, що я коли-небудь знав, і воно небезпечне в руках того, хто має зле серце.$B$BТобі варто взяти з собою інших — небезпечно йти самому. Прийми це як мою пораду.",
    O = "Вирушай до Хребта Вогняного Пір’я, на південь від Притулку Маршала.$B$BЗнайди Пламеносця і використай тотем, щоб зняти його захисну ауру. Після того, як його буде переможено, добудь Золоте Полум’я з печери.",
    P = "Blazeru$b$ber майже непереможний за аурою, яку він створив за допомогою Золотого полум'я. Тільки у вас є сила видалити його за допомогою Срібного тотема Аквементаса.",
    C = "Дякую, $N.$B$BThe Золоте полум’я тепер буде повернуто на мою батьківщину, де воно може бути захищене, щоб ніколи більше не використовуватися для зла.$B$BSince ти так багато зробив для мене, я хотів би, щоб ти мав це. Без тебе я б і досі не знав, хто я!",
},

[3981] = {
    en = "Commander Gor'shak",
    T = "Командир Ґор’шак",
    D = "Бідолашний Ґарґал… навіть не побачив, що сталося. БАМ! Стріла влучила прямо в центр його голови. Він і раніше не був генієм, але тепер…$B$B<Ґаламав кривиться.>$B$BКоли ми витягли стрілу, ми помітили згорнуту записку, прикріплену до древка. На записці був грубо намальований малюнок орка за ґратами з підписом Командира Ґор’шака.$B$BЯкщо він ще живий у Глибинах Чорноскеля, тобі потрібно його знайти.$B$BКажеш, пастка? Ну, звісно, дурні копита! Саме тому ти й підеш!",
    O = "Знайдіть Командира Ґор’шака в Глибинах Чорноскеля.$B$BВи пригадуєте, що на грубо намальованому малюнку орка були зображені ґрати над портретом. Можливо, вам варто пошукати якусь в’язницю.",
    P = "",
    C = "Ми не маємо багато часу. Слухай уважно, $R. Те, що я маю вам сказати, є секретним і лише для ваших вух.",
},

[3982] = {
    en = "What Is Going On?",
    T = "Що Тут Відбувається?",
    D = "Мене сюди відправив Тралл. Ти справді думаєш, що ці дурні могли мене схопити? Я дозволив себе захопити, щоб зібрати інформацію.$B$B<Ґор’шак шепоче.>$B$BПринцеса Залізогарта була викрадена Імператором Тауріссаном. Принцеса Бронзобородих тут, у цьому місті! Гадаю, серце старого Маґні ледь не зупинилося, коли він почув цю новину.$B$B<Ґор’шак сміється.>$B$BТихше! Чуєш це? Варта наближається! ЗАХИЩАЙСЯ!",
    O = "Захистіть Ґор’шака.",
    P = "Захищайся, дурню!",
    C = "Це був близький виклик. Їх сповістили про вашу присутність... напевно прибуде більше.",
},

[4001] = {
    en = "What Is Going On?",
    T = "Що Тут Відбувається?",
    D = "Досі мої розмови з гномом Хараном у камері через коридор були обмеженими. Проте мені вдалося переконати його, що я, точніше — ми, не бажаємо йому зла.$B$BПоговори з ним і збери якомога більше інформації про Принцесу та її викрадачів. Передай цю інформацію Вождю.$B$BТралл не хоче, щоб Принцесу скривдили, натомість у нього є грандіозний план, який передбачає її безпечне повернення до Залізогарта. Харан уже все це знає… Рушай!",
    O = "Поговоріть із Хараном Могутньомолотом і зберіть інформацію про викрадення Принцеси Мойри Бронзобородих. Передайте цю інформацію Траллу в Оргріммарі.$B$BВи пригадуєте, що Ґор’шак згадував, що Харан утримується в камері неподалік.",
    P = "Що привело вас на ці священні землі?",
    C = "Це шанс для Орди назавжди змінити політичний клімат нашого розтерзаного війною світу. Слухайте уважно, $N.$B$BFailure цієї місії не є варіантом.",
},

[4002] = {
    en = "The Eastern Kingdom",
    T = "Східні Королівства",
    D = "Ти приніс чудові відомості, $N.$B$BЯк Вождь, мій обов’язок — робити те, що найкраще для Орди. Забезпечити, щоб покоління, які прийдуть після нас, не були приречені на безнадійне існування.$B$BМожливість сформувати наші майбутні альянси впала нам у руки. Допомога гномам може значно зміцнити наші відносини у Східних Королівствах. Ось чому ти не повинен зазнати невдачі!$B$BТи готовий?",
    O = "Поговоріть із Траллом, якщо ви готові взяти на себе місію, яку він запланував.",
    P = "",
    C = "За цю точку повернення назад немає, $N.",
},

[4003] = {
    en = "The Royal Rescue",
    T = "Королівський Порятунок",
    D = "Цей удар по Темних Залізняках, якщо він буде успішним, пошле ударну хвилю по всьому їхньому королівству.$B$BПринцеса Бронзобородих перебуває під контролем Імператора Тауріссана. Щоб звільнити її, ти мусиш убити Імператора. Попереджаю, твоє завдання подвійно небезпечне, адже Бронзоборода атакуватиме тебе без вагань, перебуваючи під контролем Імператора.$B$BНЕ КРИВДЬ ЇЇ!",
    O = "Убийте Імператора Даґрана Тауріссана і звільніть Принцесу Мойру Бронзобородих від його злих чарів.",
    P = "<Принцеса Мойра здригається від страху.>",
    C = "Що ти наробив!",
},

[4004] = {
    en = "The Princess Saved?",
    T = "Принцесу Врятовано?",
    D = "Ти зарубав мого чоловіка, $r! Моя дитина народиться в цьому світі без батька.$B$B<Принцеса Мойра вказує прямо на тебе.>$B$BЗапевняю тебе, ця дитина стане наступним правителем королівства Залізогарт. Ти і твій рід будете переслідувані до кінця днів за цей несправедливий вчинок.$B$B<Ти думаєш, що Принцеса Мойра може страждати від залишкових ефектів чарів Тауріссана.>$B$BЗалиш мене, $r. Я впевнена, що твій вождь прагне почути результати свого втручання.",
    O = "Поверніться до Тралла!",
    P = "",
    C = "<Тралл вражений інформацією, яку ви йому надали.>$B$BA нова загроза вже маячить на горизонті. Оскільки роки Магні спливають, цьому ненародженому Темному Залізу відкриється шлях стати правителем Стальгорну.$B$BYou виконали те, про що я вас просив, і за це ви отримаєте винагороду.$B$BNow залиште мене, $N! Я мушу порадитися із Сільваною та Керном.",
},

[4005] = {
    en = "Aquementas",
    T = "Аквементас",
    D = "Візьми цей мішок із припасами з собою до Танарісу. Подорожуй до Затоки Загублених Вітрил і шукай коло з каменів.$B$BНайсхідніший півострів — це секрет…$B$BЛише з цього кола читай із книги Аквора; виклич єдину істоту, яка може перетворити зібрані тобою предмети на тотем для боротьби з Полум’яником.$B$BАквементас не буде радий, що його розбудили, але пам’ятай, ти мусиш залишатися в колі, щоб він перетворив предмети.",
    O = "Візьміть Книгу Аквора, Сріблясті Кігті та Залізодеревне Серце до Танарісу.$B$BВикористайте Книгу Аквора, щоб викликати Аквементаса.$B$BПісля того, як у вас буде готовий тотем, віднесіть його до Дж.Д. Коллі в Притулку Маршала.",
    P = "Отже, ти повернувся, еге ж? Хм... Дозволь мені поглянути на це, $N.",
    C = "Blazeru$b$ber, ти кажеш...$B$BYes, я знаю, що сильний елементал живе в обвугленому центрі кратера. Ми всі просто тримаємося на відстані; ніхто не зміг проникнути в могутню ауру, яка його оточує. Багато хто був штовхнутий зі скелястих доріжок на землю під час спроби зустрітися з ним.",
},

[4021] = {
    en = "Counterattack!",
    T = "Контратака!",
    D = "Орда вітає твої успіхи проти Колкарів, але самі Колкари розлючені. У мене є звіти, що загін Колкарів прибув до Степів із їхнього дому в Спустошенні, щоб помститися. Мій останній звіт свідчить, що навіть зараз вони рухаються проти цих бункерів із заходу!$B$BЗіткнися з нападниками Колкарів і поклади край їхній загрозі в Степах. Убивай їх, доки не з’явиться їхній лідер, Воєвода Кром’зар. Переможи його і принеси мені шматок його прапора як доказ.$B$BМи розраховуємо на тебе, $N.",
    O = "Принесіть Шматок Прапора Кром’зара до Реґтара Смертебрами, на захід від Перехрестя.",
    P = "У вас є банер?",
    C = "Ви зробили це! Ви перемогли Колкар!$B$BI буде впевнений, що Тралл отримає інформацію про ваші дії тут, $N.$B$BStand зростом. Ти і собою, і Ордою пишаєшся.",
},

[4022] = {
    en = "A Taste of Flame",
    T = "Смак Полум’я",
    D = "Політ знає про твою роботу в Палаючій Ущелині.$B$BПокажи мені це, $r. Линьку, ідіоте.",
    O = "Покажіть Сайрусу Змієпентусу Линьку Чорного Драконячого Політу, яку ви отримали від Каллана Вітроклинка.",
    P = "<Очі Кіра утворюють дві палаючі кулі.>",
