[4024] = {
    en = "A Taste of Flame",
    T = "Смак Полум’я",
    D = "Я прагну відчути пекучі полум’я гори вогню. Дозволити розплавленим вогням Чорноскеля каскадом пройти через мою сутність. Ця сутність, це пекуче тепло — те, чого я жадаю.$B$BБаель’Ґар мешкає в Глибинах Чорноскеля: Істота з чистого полум’я, народжена з вогнів Раґнароса. Убий Баель’Ґара і з його тліючих залишків принеси мені частину його внутрішнього вогню.$B$BВикористовуй линьку на його залишках, щоб безпечно витягти внутрішнє полум’я.$B$BУспіх принесе тобі нагороду.",
    O = "Подорожуйте до Глибин Чорноскеля і вбийте Баель’Ґара.$B$BВи знаєте лише, що велетень мешкає всередині Глибин Чорноскеля. Не забудьте використати Змінену Линьку Чорного Драконячого Політу на залишках Баель’Ґара, щоб захопити Вогняну Сутність.$B$BПоверніть Ув’язнену Вогняну Сутність до Сайруса Змієпентуса.",
    P = "Велетня зрубали?",
    C = "<Сайрус вихоплює вогняну есенцію з ваших рук.>$B$BYES!$B$BTake ваш приз і геть. Негайно геть мій зір!",
},

[4041] = {
    en = "The Videre Elixir",
    T = "Еліксир Відере",
    D = "",
    O = "",
    P = "Принеси мені Evoroot, і я зможу зробити тобі еліксир Videre.$B$BI знаєш усілякі речі про трави та алхімію... Чому, дозволь мені розповісти тобі історію про те, як я трансмутував золото з сиру, який збирався їсти на обід... привіт... Куди ти збираєшся?",
    C = "Отже, ти швидко впорався зі старим Міблоном, еге ж?",
},

[4061] = {
    en = "The Rise of the Machines",
    T = "Повстання Машин",
    D = "Машини дали про себе знати під час наших перших вилазок до Палаючої Ущелини. Після подальшого розслідування ми виявили, що їх імпортували з Палаючих Степів, можливо, з Глибин Чорноскеля. Саме для цього ти нам потрібен, $N.$B$BТвоє перше завдання — вирушити до Палаючих Степів і зібрати уламки елементалів від кам’яних автоматів і менших кам’яних створінь цього регіону. Як тільки збереш достатню кількість, повертайся до мене, і я визначу їхнє походження.",
    O = "Вирушайте до Палаючих Степів і зберіть 10 Розколотих Уламків Елементалів для Ієрофанта Теодори Мулваданії.$B$BВи пригадуєте, що Теодора згадувала про големів і елементалів цього регіону як джерело цих уламків.",
    P = "Не сприймайте це завдання легковажно, $N!",
    C = "<Теодора розкладає перед собою фрагменти.>$B$B<Теодора уважно розглядає фрагменти з величезним моноклем.>$B$BInteresting. У структурній основі кожного з цих фрагментів викарбувано... ініціали.$B$B",
},

[4062] = {
    en = "The Rise of the Machines",
    T = "Повстання Машин",
    D = "Ґ.Л.А.$B$BЦе ‘ініціали’, викарбувані на уламках елементалів. Під ініціалами є якийсь знак рангу. Машини, які ти знищив у Палаючих Степах, мали ‘Ранг IV’. Я припускаю, що це низький ранг.$B$BВізьми цей зразок уламка до Лотвіла Веріатуса в таборі на сході. Він — відомий учений у галузі елементальних наук. Він може допомогти нам у наших пошуках.",
    O = "Віднесіть Зразок Уламка Елементаля до Лотвіла Веріатуса.$B$BВи пригадуєте, що Теодора казала, що Лотвіл розташувався в таборі на сході.",
    P = "Що у тебе там, $R?",
    C = "<Обличчя Лотвіла біліє.>$B$BI... Я знаю ці позначки.",
},

[4063] = {
    en = "The Rise of the Machines",
    T = "Повстання Машин",
    D = "Це не може бути Арґелмах! Арґелмах був убитий десять років тому. Як я можу бути впевнений? Я сам його зарубав.$B$BВін був мерзенним гномом, одержимим ідеєю перекрутити справу мого життя для своїх диявольських потреб. Схоже, що злі завжди знаходять спосіб уникнути справедливості.$B$BЯкщо це справа рук Арґелмаха, то його треба знищити. Мені потрібні зразки його останніх творінь. З правильними зразками я зможу зупинити це повстання. Ці творіння охороняють Арґелмаха в Глибинах Чорноскеля.",
    O = "Знайдіть і вбийте Лорда Големів Арґелмаха. Поверніть його голову до Лотвіла. Вам також потрібно зібрати 10 Цілих Ядер Елементалів із Големів-Розорителів та Конструктів-Війнопровісників, які охороняють Арґелмаха. Ви знаєте це, бо ви екстрасенс.",
    P = "Це був він? Чи справді він був живий?",
    C = "Що це?!? Ця голова не плоть. Це якесь творіння з темного заліза: Тінь Аргельмаха - ІНША машина! Я підозрюю, що ваше знищення Аргельмаха буде недовгим, оскільки незабаром на його місце з’явиться інший.",
},

[4081] = {
    en = "KILL ON SIGHT: Dark Iron Dwarves",
    T = "УБИТИ НА МІСЦІ: Темні Залізняки",
    D = "За наказом Воєводи Ґорзуба, командира Експедиційних Сил Карґата:$B$BУсі сили Генерала Анґерфорджа в Глибинах Чорноскеля мають бути знищені.$B$BСолдати Анґерфорджа — безжальні вбивці, відповідальні за масове вбивство 109-ї дивізії Експедиційних Сил Карґата. Героїв попереджено проявляти надзвичайну обережність при зіткненні з цими бандитами.$B$BБудь-яка особа, яка знищить першу лінію сил Генерала Анґерфорджа в Глибинах Чорноскеля, отримає нагороду.",
    O = "Вирушайте до Глибин Чорноскеля і знищить підлих нападників!$B$BВоєвода Ґорзуб хоче, щоб ви зарубали 15 Анвілрейджських Гвардійців, 10 Анвілрейджських Стражів і 5 Анвілрейджських Піхотинців. Поверніться до нього, коли завдання буде виконано.",
    P = "Що це таке, $r? Хіба ти не бачиш, що я маю командувати взводом?$B$B",
    C = "Цей перший удар має пом’яти штани Енгерфорджа. Тепер рухайся, солдат. Я маю роботу завершити, битви спланувати, ворогів розгромити!$B$BCheck потрібні знаки для додаткової роботи.",
},

[4082] = {
    en = "KILL ON SIGHT: High Ranking Dark Iron Officials",
    T = "УБИТИ НА МІСЦІ: Високопоставлені Чиновники Темного Заліза",
    D = "За наказом Воєводи Ґорзуба, командира Експедиційних Сил Карґата:$B$BГлава розвідувального підрозділу Е.С.К., Грандмастер Лекслорт, повернувся з новинами про місцезнаходження високопоставлених чиновників Темного Заліза. За замкненими воротами, біля серця міста, вони тренують свої сили, щоб знищити наших людей. Вирушайте до Глибин Чорноскеля і знищить їх!$B$BВиконання цієї місії принесе нагороду.",
    O = "Вирушайте до Глибин Чорноскеля і знищить підлих нападників!$B$BВоєвода Ґорзуб хоче, щоб ви зарубали 10 Анвілрейджських Медиків, 10 Анвілрейджських Солдатів і 10 Анвілрейджських Офіцерів. Поверніться до нього, коли завдання буде виконано.",
    P = "ти знову? Мушу сказати тобі, $N, ти наполегливий.",
    C = "Angerforge, безсумнівно,... злий. Поверніться до мене, коли отримаєте третю данину, і ми продовжимо операцію: Смерть Angerforge. Я не можу вдаватися в деталі того, що це означає, але будьте впевнені, це стосується чиєїсь смерті.",
},

[4083] = {
    en = "The Spectral Chalice",
    T = "Примарна Чаша",
    D = "",
    O = "",
    P = "Самоцвіти не видають звуку, коли падають у глибину чаші...",
    C = "Спектральна чаша ширяє в повітрі, сповільнюючи підйом і опускання... наче в такт вмираючого серця.",
},

[4084] = {
    en = "Silver Heart",
    T = "Срібне Серце",
    D = "Я не знаю того, про кого ти говориш, $N.$B$BАле не хвилюйся; якщо твій друг був у подорожі, щоб знайти мене, я знаю, чого він прагнув.$B$BУ самому серці Кратера Ун’Ґоро мешкає зло в найчистішій формі. Це зло має вигляд елементаля на ім’я Полум’яник… захищений аурою, яку ніхто не може розвіяти…$B$BНіхто… окрім тих, хто має достатню силу, щоб це зробити. Я можу навчити тебе цієї сили, $N.$B$BСпочатку зроби, як я прошу. Збери 11 Сріблястих Кігтів і 1 Залізодеревне Серце від істот у Сквернолісі, а потім повертайся.",
    O = "Зберіть 11 Сріблястих Кігтів і 1 Залізодеревне Серце для Ерідана Блакитновітра в Сквернолісі.",
    P = "Я можу розповісти тобі більше про силу, яка тобі знадобилася, щоб перемогти Blazer$b$bern, але спочатку тобі потрібно зібрати те, що мені потрібно.",
    C = "Дуже добре, $N. Я бачу, що ви серйозно налаштовані допомогти своєму другові.",
},

[4101] = {
    en = "Cleansing Felwood",
    T = "Очищення Сквернолісу",
    D = "Рослини дають життя Сквернолісу, але навіть вони страждають від скверни. Я знаю способи їх очищення, але не можу ділитися такими знаннями з тими, кого не знаю чи кому не довіряю. Доведи мені, що ти дійсно допоможеш справі Кенарійського Кола!$B$BНа півночі розташовані Залізодеревні Печери. Елементалі Сквернодерева, що там мешкають, уже не підлягають очищенню. Я прошу тебе принести мені їхній сік — його називають кривавим бурштином — щоб я могла вивчити його і, можливо, врятувати інші форми життя тут.",
    O = "Принесіть 15 Кривавих Бурштинів до Аратандріс Срібнонеба в Сквернолісі.",
    P = "Я знаю, що Фелвуд страждає, $N - я страждаю разом з ним!  Я повинен залишатися непохитним у своєму переконанні; якби знання, якими я володію, потрапили в чужі руки, це означало б катастрофу для всього Фелвуду.$B$BBring для мене кривавий бурштин, отриманий із убитих елементалів Варпвуду, і я довіряю тобі достатньо, щоб допомогти мені застосувати засоби для боротьби з корупцією.",
    C = "Цей кривавий бурштин буде використано, щоб знайти засіб перемогти корупцію, присутню в Фелвуді. Ти довів мені, що готовий зробити все можливе для Кола Кенаріону. Тепер я тобі довіряю, друже.$B$BIt може здатися дивним, що вбивство елементалів довело мені себе, але мета порятунку незліченних живих істот виправдовує наші засоби. Тепер ми з вами можемо зосередитися на збереженні життя за допомогою мазей, які я можу зробити.$B$B$N, настав час очистити Фелвуд.",
},

[4102] = {
    en = "Cleansing Felwood",
    T = "Очищення Сквернолісу",
    D = "Рослини дають життя Сквернолісу, але навіть вони страждають від скверни. Я знаю способи їх очищення, але не можу ділитися такими знаннями з тими, кого не знаю чи кому не довіряю. Доведи мені, що ти дійсно допоможеш справі Кенарійського Кола!$B$BНа півночі розташовані Залізодеревні Печери. Елементалі Сквернодерева, що там мешкають, уже не підлягають очищенню. Я прошу тебе принести мені їхній сік — його називають кривавим бурштином — щоб я могла вивчити його і, можливо, врятувати інші форми життя тут.",
    O = "Принесіть 15 Кривавих Бурштинів до Мейбес Річковітер у Сквернолісі.",
    P = "Я знаю, що Фелвуд страждає, $N - я страждаю разом з ним!  Я повинен залишатися непохитним у своєму переконанні; якби знання, якими я володію, потрапили в чужі руки, це означало б катастрофу для всього Фелвуду.$B$BBring для мене кривавий бурштин, отриманий із убитих елементалів Варпвуду, і я довіряю тобі достатньо, щоб допомогти мені застосувати засоби для боротьби з корупцією.",
    C = "Цей кривавий бурштин буде використано, щоб знайти засіб перемогти корупцію, присутню в Фелвуді.  Ти довів мені, що готовий зробити все можливе для Кола Кенаріону.  Тепер я тобі довіряю, друже.$B$BIt може здатися дивним, що вбивство елементалів довело мені себе, але мета порятунку незліченних живих істот виправдовує наші засоби.  Тепер ми з вами можемо зосередитися на збереженні життя за допомогою мазей, які я можу зробити.$B$B$N, настав час очистити Фелвуд.",
},

[4103] = {
    en = "Salve via Hunting",
    T = "Мазь через Полювання",
    D = "",
    O = "",
    P = "Володіння Маяком Кенаріону дозволяє побачити зіпсований осколок душі на тих зіпсованих звірах, яких принижують заради загального блага. Я подрібнюю осколки на придатний для використання реагент, який використовується для виготовлення рослинної мазі Cenarion. Ми використаємо цю мазь, щоб знову перетворити зіпсовані рослини на здорові.$B$BIn обміняйте на ці осколки, я дам вам кілька мазей для рослин Кенаріону, які я вже приготував.",
    C = "Тоді добре, ось ваші рослинні мазі Кенаріону. Очистіть Осквернений ліс у пошуках пошкоджених рослин, $n! Де б вони не були, використовуйте мазь, яку я дав вам, щоб очистити їх.",
},

[4104] = {
    en = "Salve via Mining",
    T = "Мазь через Видобуток",
    D = "",
    O = "",
    P = "Якщо ви володієте маяком Кенаріону під час видобутку в Оскверненому лісі, ви зможете побачити заплямований купорос, який руйнує жилу сирого металу. Я знаю, як очистити цей купорос і перетворити його на реагент, який використовується для виготовлення рослинної мазі Ценаріон. Потім ви використаєте цю мазь для знайдених у дикій природі рослин, які потребують збереження.$B$BIf якщо ви зібрали будь-який забруднений купорос, я дам вам мазь для рослин Кенаріон, яку я вже приготував.",
    C = "Тоді добре, ось трохи рослинної мазі Cenarion. Якщо під час видобутку у Фелвуді ви знайдете більше купоросу, не забувайте тримати його для мене! Що більше ти знайдеш, то більше мазі я зможу зробити.",
},

[4105] = {
    en = "Salve via Gathering",
    T = "Зцілення через збирання",
    D = "Є дещо, крім демонів, що турбує мій розум, друже. Мій рід, мої люди. Загублені в божевіллі поганої, дуже поганої вуду. Одного дня Лоа звернулися до нашого Промовця уві сні. Лоа попросили створити сильний моджо, Моджо Снів.$B$BТаке сильне моджо потребувало благословенної води, благословенної Драконами. Тож я вирушив до великого зеленого порталу. Там я знайшов демонів і забруднив руки їхньою кров’ю, коли Промовець утік! Коли я повернувся додому, мої люди зневажливо фиркали на мене. Вигнали мене. Не частина Тінескребів, сказали вони.$B$BПогане, дуже погане вуду заволоділо їхнім розумом, друже. Але щоб виправити погане вуду, треба заплатити кров’ю і хорошим моджо. І ціна крові, і моджо можуть бути сплачені в Зул’Гаті. Там ти знайдеш Ґан’готу Промовця з його Моджо Снів. Недалеко ти знайдеш воєначальника Ганзенто, чию кров треба пролити. Він причина цієї дурості, і це правильний шлях виправити все!",
    O = "",
    P = "Маяк Кенаріону дозволяє досвідченому травнику помітити підступного повзуна Скверни — зловмисного продукту корупції Фелвуда. Моя робота тут навчила мене знанням очищення фел-крипа в очищувальний реагент... який використовується в тому, що ми зараз називаємо рослинною маззю Кенаріону.$B$BWhen якщо ви збираєте трави у Сквернячому лісі, ви повинні зустрітися з фел-крипом, якщо у вас є маяк. В обмін на те, що ви мені принесете, я дам вам готову рослинну мазь Кенаріону.",
    C = "Чудова робота $n - кожен шматочок цього, щойно ми його очистимо, допоможе нам повернути Фелвуд. Тут візьміть кілька доз рослинної мазі Cenarion і вирушайте в ліс. Повернення землі у корупціонерів не чекає $r!",
},

[4106] = {
    en = "Salve via Ski$b$bing",
    T = "Мазь через Здирання Шкіри",
    D = "",
    O = "",
    P = "Маяк Кенаріону дозволить добре навченому шкуродеру помітити плями зіпсованої шкіри з нагород, зібраних у Спустошеному лісі. Я перетворюю ці, здавалося б, марні пластирі на густу пасту, яка служить прискорювачем для рослинної мазі Cenarion. Коли зніматимете шкіру зі своїх убитих тут, у Фелвуді, обов’язково майте на собі маяк!$B$BWhen ви збирайте зіпсовані плями, принесіть їх мені, і я дам вам кілька рослинних мазей Кенаріону, які я вже зробив.",
    C = "Це саме те, що мені потрібно. Ось — візьміть ці рослинні мазі та використовуйте їх, щоб відновити Фелвуд від корупції. Ми повинні вистояти, $n!",
},

[4107] = {
    en = "Salve via Disenchanting",
    T = "Мазь через Розщеплення",
    D = "",
    O = "",
    P = "Сила розчарованого магічного предмета відчувається есенцією, яку він створює. Я винайшов спосіб перетворити сиру есенцію, яку використовують чарівники, на відповідний реагент для створення рослинної мазі Кенаріону. Для цього вам не потрібен маяк Кенаріону; будь-який відповідним чином розчарований предмет, який дає менші есенції пустот, буде працювати.$B$BI потрібна лише одна менша есенція пустот; в обмін я дам тобі рослинні мазі Кенаріону. Есенція надзвичайно сильна - невелика кількість однозначно допоможе!",
    C = "Ось деякі рослинні мазі Кенаріону — для цього мені потрібна лише одна менша есенція Пустоти, $n. Есенція — це, безумовно, найпотужніший предмет, який я можу використати, щоб перетворити мечі на орала. Якщо вам потрібна ще мазь, то знайдіть мене тут!",
},

[4108] = {
    en = "Salve via Hunting",
    T = "Мазь через Полювання",
    D = "",
    O = "",
    P = "Володіння Маяком Кенаріону дозволяє побачити зіпсований осколок душі на тих зіпсованих звірах, яких принижують заради загального блага. Я подрібнюю осколки на придатний для використання реагент, який використовується для виготовлення рослинної мазі Cenarion. Ми використаємо цю мазь, щоб знову перетворити зіпсовані рослини на здорові.$B$BIn обміняйте на ці осколки, я дам вам кілька мазей для рослин Кенаріону, які я вже приготував.",
    C = "Тоді добре, ось ваші рослинні мазі Кенаріону. Очистіть Осквернений ліс у пошуках пошкоджених рослин, $n! Де б вони не були, використовуйте мазь, яку я дав вам, щоб очистити їх.",
},

[4109] = {
    en = "Salve via Mining",
    T = "Мазь через Видобуток",
    D = "",
    O = "",
    P = "Якщо ви володієте маяком Кенаріону під час видобутку в Оскверненому лісі, ви зможете побачити заплямований купорос, який руйнує жилу сирого металу. Я знаю, як очистити цей купорос і перетворити його на реагент, який використовується для виготовлення рослинної мазі Ценаріон. Потім ви використаєте цю мазь для знайдених у дикій природі рослин, які потребують збереження.$B$BIf якщо ви зібрали будь-який забруднений купорос, я дам вам мазь для рослин Кенаріон, яку я вже приготував.",
    C = "Тоді добре, ось трохи рослинної мазі Cenarion. Якщо під час видобутку у Фелвуді ви знайдете більше купоросу, не забувайте тримати його для мене! Що більше ти знайдеш, то більше мазі я зможу зробити.",
},

[4110] = {
    en = "Salve via Gathering",
    T = "Мазь через Збір",
    D = "",
    O = "",
    P = "Маяк Кенаріону дозволяє досвідченому травнику помітити підступного повзуна Скверни — зловмисного продукту корупції Фелвуда. Моя робота тут навчила мене знанням очищення фел-крипа в очищувальний реагент... який використовується в тому, що ми зараз називаємо рослинною маззю Кенаріону.$B$BWhen якщо ви збираєте трави у Сквернячому лісі, ви повинні зустрітися з фел-крипом, якщо у вас є маяк. В обмін на те, що ви мені принесете, я дам вам готову рослинну мазь Кенаріону.",
    C = "Чудова робота $n - кожен шматочок цього, щойно ми його очистимо, допоможе нам повернути Фелвуд. Тут візьміть кілька доз рослинної мазі Cenarion і вирушайте в ліс. Повернення землі у корупціонерів не чекає $r!",
},

[4111] = {
    en = "Salve via Ski$b$bing",
    T = "Мазь через Здирання Шкіри",
    D = "",
    O = "",
    P = "Маяк Кенаріону дозволить добре навченому шкуродеру помітити плями зіпсованої шкіри з нагород, зібраних у Спустошеному лісі. Я перетворюю ці, здавалося б, марні пластирі на густу пасту, яка служить прискорювачем для рослинної мазі Cenarion. Коли зніматимете шкіру зі своїх убитих тут, у Фелвуді, обов’язково майте на собі маяк!$B$BWhen ви збирайте зіпсовані плями, принесіть їх мені, і я дам вам кілька рослинних мазей Кенаріону, які я вже зробив.",
    C = "Це саме те, що мені потрібно. Ось — візьміть ці рослинні мазі та використовуйте їх, щоб відновити Фелвуд від корупції. Ми повинні вистояти, $n!",
},

[4112] = {
