[4224] = {
    en = "The True Masters",
    T = "Справжні господарі",
    D = "Що? Ти думав, що ти перший? Скільки солдатів ми мусимо втратити, перш ніж Штормовій діятиме?$B$BМи зібрали величезну кількість розвідданих про загрозу Чорноскелі, перш ніж втратили нашого командира, Маршала Віндсора. Разом із Маршалом Віндсором зникла вся наша цінна інформація.$B$BНам потрібна ця документація. Поговори з Пошарпаним Джоном, $N. Він був із Віндсором, коли на них напала рейдова група Чорноскелі. Востаннє його бачили в печері на півночі.",
    O = "Поговори з Пошарпаним Джоном, щоб дізнатися про долю Маршала Віндсора, і повернися до Маршала Максвелла, коли виконаєш це завдання.$B$BТи пригадуєш, як Маршал Максвелл казав шукати його в печері на півночі.",
    P = "Ви вже говорили з Джоном?",
    C = "Я міг вас попередити, але що це весело?",
},

[4241] = {
    en = "Marshal Windsor",
    T = "Маршал Віндсор",
    D = "То цей нікчемний боягуз каже, що Віндсор живий, так?$B$BГотуйся, заступнику, ти йдеш його шукати. Якщо Віндсор живий, ти мусиш привести його назад. Якщо він мертвий, я хочу доказів.$B$B<Максвелл сміється.>$B$BБ’юся об заклад, тобі набридло це чути, чи не так?",
    O = "Вирушай до гори Чорноскель на північному заході і увійди до Глибин Чорноскелі. Дізнайся, що сталося з Маршалом Віндсором.$B$BТи пригадуєш, як Пошарпаний Джон казав, що Віндсора відтягли до в’язниці.",
