},

[4242] = {
    en = "Abandoned Hope",
    T = "Залишена надія",
    D = "Болвар — дурень. Я збирав його дорогоцінні «докази», щоб засунути їх йому в горлянку.$B$BВін сліпий дурень. Докази стоять за два кроки від нього, а він їх не бачить.$B$BЩодо моїх даних, вони втрачені. Зникли. Неповерненні.$B$BЯкщо я коли-небудь знайду Залізозуб і виберуся з цього лабіринту, моїм першим пунктом буде Штормовій, щоб засунути мій молот між очі того плазуна.$B$BІди геть, $N.",
    O = "Повідом Маршалу Максвеллу погані новини.",
    P = "",
    C = "Мабуть, він збожеволів.$B$B<Максвелл опускає голову в жалобі.>$B$BIt шкодує, що колись гордий і благородний воїн перетворився на жахливу голову. Я ДУМАЮ, що ми зайшли в глухий кут... $B$BI має винагородити вас за ваші зусилля, $N.",
},

[4243] = {
    en = "Chasing A-Me 01",
    T = "Погоня за А-Мі 01",
    D = "На жаль, щось сталося з одним із моїх найкращих винаходів. Ти бачив механічних білок, так? Щоб наблизитися до мавп кратера Ун’Ґоро, я створив механічну мавпу, щоб вона зливалася з їхнім видом — я називаю її А-Мі 01.$B$BУ неї в очах скрижальні самоцвіти, щоб я могла бачити все, що вона бачить. Вона дісталася до Грибної Скелі — лігва мавп — на схід звідси, і тоді я втратила зв’язок. Останнє, що я бачила, — це як один із їхніх альфа-самців кинувся привітатися з нею!$B$BЧи можеш ти допомогти мені її знайти?",
    O = "Знайди А-Мі 01 у кратері Ун’Ґоро.",
    P = "",
    C = "Дивлячись на A-Me 01, ви бачите дві величезні вм’ятини, які тьмяніють те, що Карна, очевидно, вважає добре опрацьованим інженерним витвором. Одна вм’ятина прикрашає плече A-Me 01, інша знаходиться на її голові.$B$BNo сила, здається, проходить через її компоненти, поки ви досліджуєте далі.",
},

[4244] = {
    en = "Chasing A-Me 01",
    T = "Погоня за А-Мі 01",
    D = "Докладніше дослідження показує панель, яка відкривається. Чітко написано над якимись проводами: «Замініть міфриловий корпус і вимкніть, а потім увімкніть живлення.»$B$BЗамінивши панель, ти думаєш, чи буде так просто полагодити А-Мі 01 і повернути її до Карни Ремтревел біля Притулку Маршала.$B$BТільки спробувавши, дізнаєшся.",
    O = "Знайди Міфриловий Корпус і повернися до А-Мі 01 у кратері Ун’Ґоро.",
    P = "Панель, в яку входить міфрилова оболонка, все ще закрита. Решта A-Me 01 залишається інертною.",
    C = "Ви знову знімаєте панель зі спини A-Me 01 і обережно знімаєте старий міфріловий корпус, який, здається, вигорів. Новий легко стає на місце. Єдине, що залишилося зробити, припускаючи, що проблемою був міфріловий корпус, це перевести перемикач у положення ",
},

[4245] = {
    en = "Chasing A-Me 01",
    T = "Погоня за А-Мі 01",
    D = "Перевіряючи, чи готовий ти провести А-Мі 01 назад до Карни Ремтревел, ти перемикаєш важіль у положення «Вимкнено». Ще раз озираючись, щоб переконатися, що жодна з горил не наближається, ти готуєшся перевірити, що станеться, коли ти перемкнеш важіль назад у положення «Увімкнено».$B$BЦе твій останній шанс... ти впевнений, що хочеш це зробити?",
    O = "Супроводжуй А-Мі 01 назад до Карни Ремтревел у кратері Ун’Ґоро.",
    P = "Ви змогли допомогти A-Me? Та міфрілова оболонка, яку ви згадали про знищення, добре здогадалася про те, що не так. Я впевнений, що якщо ви заміните це, вона знову активується і зможе повернутися додому.",
    C = "О, ви зробили це! Чудово! Дякую, $N.$B$BOh, мій бідний, А-Я. Подивіться на всі ці вм'ятини. Ми забезпечимо її бездоганну роботу, лише трохи попрацювавши.$B$BThank знову ти, $N. Я дуже ціную це.",
},

[4261] = {
    en = "Ancient Spirit",
    T = "Стародавній дух",
    D = "Сквернолісся колись була мирною і спокійною землею... Доки легіон не захопив її. Інфернали, руйнування, хаос...$B$BЧереп Ґул’дана забезпечив, що ніхто тут не врятувався. Усі піддалися псуванню.$B$BНавіть зараз, як дух, я все ще відчуваю себе ув’язненим, несучи страждання цієї землі. Допоможи мені знайти шлях додому. Будь ласка, $N, скажи, що ти проведеш стародавнього духа звідси, де я нарешті зможу спочити.$B$BКоли я буду вільний, шукай Кайнета Стіллвінда, друїда, який мешкає в Лісопісні, на сході.",
    O = "Супроводжуй Арея до безпеки, а потім поговори з Кайнетом Стіллвіндом у Лісопісні, на сході Ясенедолу.",
    P = "",
    C = "Так, $N. Фелвуд пережив багато труднощів. Дякуємо вам за те, що ви зробили.$B$BOne день, можливо, ми зможемо відновити Фелвуд від корупції; кожна добра справа допомагає.",
},

[4262] = {
    en = "Overmaster Pyron",
    T = "Надмайстер Пірон",
    D = "Останні п’ятеро моїх магів, які пішли шпигувати в гору Чорноскель, повернулися підсмаженими з постійним помаранчевим гномським афро — або ще гірше.$B$B<Джалінда піднімає трохи попелу з землі і відпускає його в повітря.>$B$BОдин особливо мерзенний тип, Надмайстер Пірон, здається, завдає чимало проблем. Нам потрібно, щоб цього елементаля знищили, щоб наша експедиційна команда могла пробратися до Глибин Чорноскелі!$B$BВін охороняє вхід у кар’єрі Чорноскелі.",
    O = "Убий Надмайстра Пірона і повернися до Джалінди Спріґ.$B$BТи пригадуєш, як Джалінда говорила, що Пірон охороняє кар’єр. Можливо, тобі варто там пошукати?",
    P = "<Здається, Джалінда пильно дивиться на вашу голову.>",
    C = "Incendius? Боже...",
},

[4263] = {
    en = "Incendius!",
    T = "Інсендіус!",
    D = "Ти впевнений, що Пірон сказав «Інсендіус», коли помер?$B$B<Джалінда важко ковтає.>$B$BЛорд Інсендіус, як кажуть, є прислужником Раґнароса! О боже, о боже... що ж нам робити?$B$BЧи можеш ти взятися за ще одну місію? У мене немає нікого іншого, кого можна відправити, $N!$B$BМи ніколи не зможемо провести команду, якщо Інсендіус продовжуватиме воскрешати Пірона з попелу.$B$BТобі доведеться знайти і знищити Лорда Інсендіуса!",
    O = "Знайди Лорда Інсендіуса в Глибинах Чорноскелі і знищ його!",
    P = "Нечисть мертвий??",
    C = "Ой люба! Ви впевнені, що Інсендіус сказав «Рагнарос»? $B$B<Джалінда подає вам щось і поплескає вас по зап’ястку, замислюючись.>",
},

[4264] = {
    en = "A Crumpled Up Note",
    T = "Зіжмакана записка",
    D = "Записка вкрита плямами на поверхні. Текст ледве розбірливий, але ти розбираєш наступне:$B$B...солодка іронія...$B$B...падіння розколотого Альянсу...$B$B...якби не старанність Генерала Анґерфорджа, ми б ніколи не виявили шаблон шифрування...$B$B...Арґелмах майже закінчив розшифровку нотаток Віндсора.$B$BНаш лорд підніметься з глибин і розчавить усіх, хто залишиться...$B$B-Імператор Даґран Тауріссан.",
    O = "Ти, можливо, щойно натрапив на щось, що зацікавило б Маршала Віндсора. Зрештою, надія ще може бути.",
    P = "<Маршал Віндзор дивиться на записку у вашій руці.>$B$BWhat у вас там, $N?",
    C = "<Маршал Віндзор бере записку і починає читати.>",
},

[4265] = {
    en = "Freed from the Hive",
    T = "Втеча з вулика",
    D = "Кокон трохи розкривається, коли ти його торкаєшся, відкриваючи нічного ельфа-чоловіка, який, на диво, ще живий. Він здається здоровим, хоча глибоко приголомшеним. Допомагаючи йому спуститися з кокона, він оживає.$B$B«Дякую Елуні — ти врятував мене, друже! Я... Я Ращал, і я прокинувся паралізованим усередині цього кокона після того, як ці комахи мене здолали. Мені потрібна допомога, щоб вибратися звідси; після цього, чи не могли б ви повідомити Фортецю, що зі мною все гаразд? Я буду в порядку — нам просто потрібно швидко звідси піти!»",
    O = "Супроводжуй Ращала безпечно з вулика Зукк’аш.$B$BПовернися до Ґінро Гарткіндла у Фортеці Пір’яного Місяця і повідом, що Ращал живий і здоровий.",
    P = "Вам є про що повідомити, $n?",
    C = "Ласкаво просимо додому, $N.  Рашал нещодавно зайшов і розповів мені, що сталося.$B$BI... ні, уся Твердиня навіть не може подякувати вам за ваш великий вчинок; Рашал був би мертвий без вашої своєчасної допомоги, а ваша допомога прийшла до нас навіть без шепоту про гонорар найманця.  Ви носите тавро справжнього героя.  Знайте, що у Ginro Hearthkindle у вас завжди буде друг.",
},

[4266] = {
    en = "A Hero's Welcome",
    T = "Геройський прийом",
    D = "$N, Генерал Шандріс Пір’яний Місяць хотіла б поговорити з тобою особисто. Без сумніву, вона хоче подякувати тобі за службу Фортеці, але я також знаю, що вона хоче обговорити з тобою комахоподібних істот, з якими ти і Ращал зіткнулися в південному Фераласі. Звіти про цих комах Зукк’аш... м’яко кажучи, лякають.$B$BГенерал Пір’яний Місяць чекає на тебе в головному комплексі.",
    O = "Поговори з Шандріс Пір’яний Місяць у Фортеці Пір’яного Місяця.",
    P = "",
    C = "$N, я щиро дякую тобі за допомогу, яку ти нам надав.  Ваша хоробрість, незважаючи на величезні труднощі, гарантувала винагороду в тисячу разів більшу.  Тим не менше, я сподіваюся, що ви приймете це від імені всієї Твердині.$B$BNow, якщо можна... Я хотів би ще раз попросити вашої допомоги.  У світлі відкриття вулика Зукк'аш тут, у Фераласі, я думаю, що ти найкращий вибір для цієї місії.",
},

[4267] = {
    en = "Rise of the Silithid",
    T = "Повстання силітідів",
    D = "Я довіряю тобі копію звіту, який Ращал склав про зараження південно-східного Фераласу. Поки основний звіт відправляється до Дарнаса, я хочу, щоб ти віддав цю копію нашому соратнику з Протекторату. Її звати Ґраціна Спірітмайт; вона жриця, яка мешкає в Храмі Місяця в Дарнасі. Вона має широкі знання про таких істот, і передача їй цього звіту принесе користь нам усім.$B$BТи вільний — удачі, $N; нехай Елуна оберігає нас усіх.",
    O = "Візьми Звіт Ращала до Ґраціни Спірітмайт у Дарнасі.",
    P = "Ласкаво просимо в цей благословенний храм, друже.  Мені передбачили твій приїзд сюди з Цитадельного Місяця.  У вас є звіт, який просила вас принести Шандріс Перистий Місяць?",
    C = "Ми, нічні ельфи, знаємо про терор, описаний у цьому звіті.  Шандріс вчинив мудро, надіславши це і вас мені.$B$BThese істоти швидко поглинуть Фералас; вони не що інше, як одна з найбільших загроз, з якими ми всі коли-небудь зіткнемося.  Комахи, яких зустріли ви та кур’єр, відомі як силітиди.  Вони лише знаряддя однієї з найбільших загроз, з якими будь-коли стикалися як Орда, так і Альянс.$B$BI Моліться, щоб ми мали рішучість перемогти їх, перш ніж вони знищать нас.",
},

[4281] = {
    en = "Thalanaar Delivery",
    T = "Доставка до Таланаару",
    D = "Цей пакунок із товарами, який ти знайшов у таборах гнолів Вудпо, мав бути доставлений до маленької проміжної станції Таланаар у південно-східному Фераласі. Незалежно від долі зниклого кур’єра, завдання доставки пакунка залишається незавершеним.$B$BДетально оглянувши пакунок, ти помічаєш написане від руки ім’я «Фалфіндель Вейвордер» на зовнішній стороні упаковки. Можливо, це кінцевий одержувач пакунка.",
    O = "Візьми Недоставлений Пакунок до Фалфінделя Вейвордера в Таланаарі.",
    P = "Ласкаво просимо до Thalanaar, $C. Вам потрібна якась допомога?",
    C = "Слава Елуні, нарешті прибула доставка з Твердині Перинного Місяця!$B$BYour присутність тут вказує на те, що, можливо, якась лиха доля спіткала Рашала, нашого звичайного кур’єра. Сподіваюся, що все вийде. Я знаю, що нещодавно мокриця сильно схвилювалася з якогось південного джерела. Може, він там упав у нетрі; Я був би обережний, друже.$B$BRegardless, ще раз дякую. Ось оплата за доставку цієї посилки.",
},

[4282] = {
    en = "A Shred of Hope",
    T = "Криха надії",
    D = "<Маршал Віндсор схвильовано трясе запискою.>$B$BТи розумієш, що це означає, $N?$B$BМожливо, ще не все втрачено! З того, що я можу зрозуміти, інформацію утримують два дворфи Темного Заліза: Генерал Анґерфордж і лорд големів, Арґелмах. У мене є відчуття, що вони не віддадуть інформацію просто так, якщо ми ввічливо попросимо.$B$BСподіваюся, ти готовий до бою.$B$BВирушай і знайди цих двох лиходіїв! Знищ їх і поверни мені втрачену інформацію.",
    O = "Поверни втрачену інформацію Маршала Віндсора.$B$BМаршал Віндсор вважає, що інформацію утримують Лорд Големів Арґелмах і Генерал Анґерфордж.",
    P = "Незабаром ця грандіозна хитрість закінчиться.",
    C = "<Маршал Віндзор вириває дві таблички з ваших рук.>$B$BWe потрібно забиратися звідси!",
},

[4283] = {
    en = "FIFTY! YEP!",
    T = "П’ЯТДЕСЯТ! ТАК!",
    D = "Я відкрию тобі маленький секрет, солдате. Підійди ближче.$B$BЯ ЄДИНИЙ НОРМАЛЬНИЙ ТУТ!$B$BПоглянь на цих людей! Чи повіриш, що вони всі божевільні!? Так і є! Божевільні! З’їхали з глузду!$B$B<Ораліус знижує голос.>$B$BТримаймо це між мною, тобою і моїм другом Капітаном Вінкі.$B$B<Ораліус хапає повітря і стискає.>$B$BУ будь-якому разі... Я збираю значки до моєї колекції вух огрів. Орки — смак дня. П’ятдесят. ВПЕРЕД!$B$B<Ораліус дме в ріг.>$B$BВІДПРАВЛЯЙ!",
    O = "Ораліус хоче 50 Медальйонів Чорноскелі. Є велика ймовірність, що ці медальйони можна знайти на орках у Палаючих Степах.",
    P = "<Оралій говорить у досить велике відрізане огрове вухо.>$B$BBurning Контролювати степи, контролювати.",
    C = "Ви зробили це! Ваша нагорода: потріть мені живіт! ДАЛІ! ТРИТЬ ЦЕ!",
},

[4284] = {
    en = "Crystals of Power",
    T = "Кристали сили",
    D = "Я впевнений, ти їх помітив, $N. Вони всюди!$B$BПро що я говорю? Ну, про кристали, звісно!$B$BКристали... Вони розкидані по всьому кратеру. Більшість людей їх ігнорують, але у мене є дивне відчуття, що в них прихована сила. Я проводжу тут експерименти з ними вже деякий час, але не можу нічого знайти. Ну, поки що не знайшов.$B$BСкажи, у мене тут трохи закінчуються кристали — думаєш, ти міг би зібрати ще трохи для мене?",
    O = "Збери по 7 Силових Кристалів кожного кольору: червоного, синього, жовтого і зеленого. Принеси їх до Джей.Ді. Коллі в Притулку Маршала.",
    P = "Я просто знаю, що тут щось шукаю, $N!",
    C = "Тепер продовжу експерименти! Дякую, $N.",
},

[4285] = {
    en = "The Northern Pylon",
    T = "Північний пілон",
    D = "Для чого вони можуть бути? Я не можу викинути цю думку з голови!$B$BЦе зводить мене з розуму — що чутки, які я чув про кристалічні пілони, усі правдиві. Назви мене легковірним, але я зазвичай вірю всьому, що мені кажуть.$B$BУ будь-якому разі, я чув, що один із кристалічних пілонів є досить близько. Десь на півночі... Будь ласка, знайди його, $N. Я просто знаю, що вони існують.",
    O = "Вияви місце розташування Північного Кристалічного Пілона в кратері Ун’Ґоро.",
    P = "Ви відвідували пілон, $N?",
    C = "Я знаю, що історії правдиві, $N.",
},

[4286] = {
    en = "The Good Stuff",
    T = "Найкращі речі",
    D = "Капітан Вінкі каже мені, що Темні Залізняки в Глибинах мають усі найкращі речі. Чи не так, Вінкі?$B$B<Ораліус робить найкращу імітацію пірата.>$B$BАРРР, ДРУЖЕ! ЦЕ ПРАВДА!$B$BБачиш, що я кажу? Тобі потрібно пробратися туди і принести мені зразки найкращих речей.$B$BЗаходь туди і потряси своїм скарбом!",
    O = "Вирушай до Глибин Чорноскелі і добудь 20 Поясних Сумок Темного Заліза. Повернися до Ораліуса, коли виконаєш це завдання. Ти припускаєш, що дворфи Темного Заліза всередині Глибин Чорноскелі носять ці «поясні сумки».",
    P = "Мене зараз не можна турбувати, $N. Мені та Вінкі потрібна зустріч.",
    C = "<Ораліус починає нишпорити в купі поясних рюкзаків.>$B$BOH ЧУДОВО!$B$B<Ораліус пхає свій великий ніс у купу й вдихає повітря.>$B$BDELICIOUS! Подивіться на всі ці смаколики!$B$BTake одну для себе, $N. Тут є чим зайнятися.",
},

[4287] = {
    en = "The Eastern Pylon",
    T = "Східний пілон",
    D = "Під час мого перебування тут я чув дивні чутки про таємничі пілони, що існують у дикій природі кратера, $N. Кажуть, що вони досить великі, з кристалами, що вистилають їхні внутрішні поверхні.$B$BХоча я ніколи не бачив жодного, я не можу не думати, що чутки правдиві — і що пілони мають щось спільне з усіма кристалами, які ми знайшли.$B$BТо чому б тобі не допомогти мені заспокоїти мою цікавість? Кажуть, що один із них є в східній частині кратера. Думаєш, ти зможеш його знайти?",
    O = "Вияви місце розташування Східного Кристалічного Пілона в кратері Ун’Ґоро.",
    P = "Ви відвідували пілон, $N?",
    C = "Ун'Горо таке дивне місце, $N. Коли потрапляєш у кратер, ніби потрапляєш у зовсім інший світ...",
},

[4288] = {
    en = "The Western Pylon",
    T = "Західний пілон",
    D = "Мої експерименти поки що не дали позитивних результатів, $N. Я не можу не сподіватися, що ти знайдеш рішення, шукаючи один із пілонів, про які я чув, що вони існують.$B$BМожливо, якщо ми поєднаємо певні кольори біля них... але я забігаю наперед. Спочатку знайдімо їх!$B$B$N, пошукай у західній частині кратера; кажуть, що там десь є пілон.",
    O = "Вияви місце розташування Західного Кристалічного Пілона.",
    P = "Ви відвідували пілон, $N?",
    C = "Уздовж кратера багато прихованих ділянок. Спробуйте дослідити звивисті стежки, якщо ви не можете придумати, де ще шукати, $N.",
},

[4289] = {
    en = "The Apes of Un'Goro",
    T = "Мавпи Ун’Ґоро",
    D = "Цей кратер має багато дивних істот — вони здаються благороднішими версіями істот, знайдених по всій моїй батьківщині і за її межами. Я не можу цього пояснити, але це місце кричить про Матір-Землю. Я віддаю їй шану щоразу, коли вистежую одну з її прекрасних істот по його басейну.$B$BЯкщо ти також хочеш відчути просвітлення, яке супроводжує такий великий подвиг, то вирушай на північ. Там ти знайдеш великих мавп, які є випробуванням для сили будь-якого смертного. Принеси мені їхні шкури... доведи свою силу.",
    O = "Принеси 2 Шкури Горил Ун’Ґоро, 2 Шкури Топтунів Ун’Ґоро і 2 Шкури Громовіїв Ун’Ґоро до Торви Слідопита біля входу до кратера Ун’Ґоро.",
    P = "Чи створіння тут уже перемогли вас, $N?$B$BDo не можна так легко переконати. Вистежити та перемогти мавп Ун'Горо непросте завдання навіть для чудового мисливця.",
    C = "Отже, ти виявився сильним, достатньо сильним, щоб перемогти людиноподібних мавп Ун'Горо — це добре. Виклик був невеликим порівняно з Лар'корві, але я не відберу у вас такої великої перемоги.$B$BThese шкури стануть чудовим одягом для мого племені. Ви допомогли мені й виявилися гідними цього.$B$BBefore ви вирушили на інше завдання, давайте віддамо хвалу Матері-Землі та подякуємо духам тих мавп, яких ви вбили — вони повинні знати, що їхня смерть не буде марною.",
},

[4290] = {
    en = "The Fare of Lar'korwi",
    T = "Їжа Лар’корві",
    D = "Колись, давно, мій брат украв м’ясо з однієї з здобичей Лар’корві. Він не знав цього тоді, але Лар’корві бачив його з лісу. Лар’корві переслідував мого брата днями, знищуючи все, до чого той торкався. Мій брат, наляканий, нарешті вирішив утекти з кратера і залишити Лар’корві позаду.$B$BЛар’корві убив його неподалік від цього місця.$B$BЯкщо ти хочеш спровокувати Лар’корві, знайди його свіжу здобич і вкради трохи м’яса з неї.$B$BПовернися до мене після цього.",
    O = "Знайди тушу найсвіжішої здобичі Лар’корві і вкради Шматок Туші Трешадона, перш ніж повернутися до Торви Слідопита в кратері Ун’Ґоро.",
    P = "Не сприймай мої слова легковажно, $N. Якщо ви дійсно хочете зіткнутися з цією істотою, то вам слід бути обережним... і розумним. Знадобиться багато сили й проникливості, щоб витягнути Лар'корві й перемогти його.",
    C = "Це буде добре, $N. Здається, Лар'корві сьогодні добре їсть. Хоча, цікаво, де він знайшов threshadon у цій місцевості. Дивно.$B$BRegardless, я триматиму це, доки ти не будеш готовий до протистояння зі звіром. Не хвилюйтеся за мою безпеку — я впевнений, що ви настільки розлютили Лар'корві, що він не вб’є мене, доки не скуштує вашого м’яса.",
},

[4291] = {
    en = "The Scent of Lar'korwi",
    T = "Запах Лар’корві",
    D = "Я насправді здивований, що він ще не прийшов за тобою, $N. Але все гаразд, бо в мене є останній план, який приведе монстра до нас.$B$BБудучи домінантним самцем, Лар’корві має право паруватися з будь-якою самкою, яку він обере — і він обирає багатьох із них. На заході звідси ти знайдеш багато яєць равазаврів. Наблизься до них, і це має спровокувати атаку його подруг. Самки виділяють жахливий запах із залози в голові, який дозволяє самцям знати, що вони готові до розмноження. Принеси мені дві такі залози.",
    O = "Принеси 2 Феромонові Залози Равазавра до Торви Слідопита біля входу до кратера Ун’Ґоро.",
    P = "Будь обережний, $N. Наближення до будь-якого гнізда з яйцями, безумовно, спровокує матерів... навіть якщо ви вже вберегли від них залозу. Матері можуть бути такими ж смертоносними, як і сам Лар'корві, коли борються за захист своїх дитинчат. Але якщо вам вдасться, ми матимемо остаточний спосіб вивести Лар'корві з укриття.",
    C = "Ах, чудові екземпляри, $N. Дві частини, які ви знайшли, ідеально підходять для того, щоб виманити Лар'корві на відкритому повітрі. Я не можу дочекатися результату вашої боротьби з монстром. Він — величезна істота з кігтями, гострими як найтонші леза. Подивишся йому в очі і пізнаєш смерть.",
},

[4292] = {
    en = "The Bait for Lar'korwi",
    T = "Приманка для Лар’корві",
    D = "Це буде найскладніша частина, тому що план дещо складний. На півночі звідси ти знайдеш маленьку стежку в гори. Саме там я востаннє бачив Лар’корві. Ти знатимеш, що ти в правильному місці, через усі кістки від величезних істот, які колись блукали неподалік. Візьми м’ясо, яке ти здобув, і поклади його там. Потім натрі цю суміш, яку я створив, на м’ясо. Якщо обидва приманки разом не приведуть Лар’корві до тебе, то я не знаю нічого іншого, що могло б.",
    O = "Використовуючи вміст Мішка Торви, виклич Лар’корві і перемож його. Потім принеси Голову Лар’корві до Торви Слідопита біля входу до кратера Ун’Ґоро.",
    P = "Не дозволяй страху долати тебе, $N. Страх — великий зрадник... ти повинен залишатися сильним!$B$BTake м’ясо, поклади його в маленьку долину, а потім використай на ньому залозу. Тільки тоді смерть прийде за вами.",
    C = "Слава Матері Землі! Ви зробили це! Чесна гра тобі, $N. Ви самі по собі довели себе як чудовий $C. Твій дух сильний. Ваша хоробрість неперевершена. І твоя сила зміцнилася. Я схиляюся перед вашими навичками.$B$BOnly найбільший з моїх предків міг би досягти чогось такого неймовірного. Вітаю.",
},

[4293] = {
    en = "A Sample of Slime...",
    T = "Зразок слимака...",
    D = "Сквернолісся — це ліс далеко на півночі від Степів, ще далі, ніж Ясенеділ. Там слимаки зустрічаються навколо водойм, благословенних дотиком Скверни. Скара зруйнувала цю місцевість атаками інферналів та іншими демонічними магіями — кажуть, що слимаки виповзли з-під землі під час цих атак.$B$BЗбери зразки слимаків Скверноліссі, і ми використаємо тестове обладнання поруч зі мною, щоб створити контрольну групу для наших тестів проти інших зразків, які ти збереш.",
    O = "Збери Зразки Слимаків Скверноліссі з будь-яких слимаків у Сквернолісі. Потім, використовуючи Тестове Обладнання поруч із Хіміком Ф’юлі в Підмісті, визнач, які з твоїх зразків найбільш пошкоджені. Принеси 5 Пошкоджених Зразків Скверноліссі до Хіміка Ф’юлі.",
    P = "Мені знадобиться принаймні п’ять пошкоджених зразків для нашої контрольної групи, $N. Продовжуйте збирати зразки слизу Оскверненого лісу, доки не зможете дати мені те, що нам знадобиться. Леді Сільвана наказує...",
    C = "Ах, відмінно. Ці зразки підійдуть добре. Я дякую вам за вашу допомогу.$B$BOnce ми зібрали всі зразки слизу, ми зможемо визначити більше. Я починаю підозрювати, що передчуття леді Сільвани було не тільки правильним, але й більш проникливим, ніж вона могла передбачити. Ці зразки дуже цікаві. Просто дивлячись, як вони відреагували на мої сполуки... хм, так, нам обов’язково потрібно буде дослідити далі.",
},

[4294] = {
    en = "... and a Batch of Ooze",
    T = "...і партія слизу",
    D = "Чи чув ти про кратер Ун’Ґоро, $N? Він розташований біля пустелі Танаріс, і це чудове місце: пишне, жваве, повне істот і рослинного життя.$B$BСаме туди тобі потрібно вирушити. До мене дійшли чутки, що це місце здається повністю незайманим зовнішніми руками. Дослідники тільки зараз відкривають його таємниці.$B$BЯ хотів би протестувати слимаків або слизняків там. Якщо це правда — що вони незаймані — тоді я хотів би побачити, як такі істоти еволюціонували.",
    O = "Збери Зразки Слимаків Ун’Ґоро з будь-яких слимаків у кратері Ун’Ґоро. Потім, використовуючи Тестове Обладнання поруч із Хіміком Ф’юлі в Підмісті, визнач, які з твоїх зразків найчистіші. Принеси 5 Чистих Зразків Ун’Ґоро до Хіміка Ф’юлі.",
    P = "Так, $N? Як проходять ваші пошуки?",
    C = "Справді дивовижно, $N. Цей кратер Ун'Горо зберігає набагато більше таємниць, ніж я очікував. Цікаво, що ще ми виявимо під час подальшого тестування.$B$BSimply неймовірно... подивіться на чистоту цих зразків. Хм, мені цікаво, що це може означати. Вони ніби й елементарні за своєю суттю, але... щось більше. Вони нагадують мені... Старих богів. Ми знайшли їх сліди по всьому Азероту, і тепер мені цікаво, чи ці істоти не пов’язані з ними якимось чином.$B$BWe доведеться перевірити далі.",
},

[4295] = {
    en = "Rocknot's Ale",
    T = "Ель Рокнота",
    D = "",
    O = "",
    P = "О, але! Я б убив за трохи елю з темного заліза!! Швидше, я протверезію! Я знаю це, тому що тверезість затуманює мій зір... і це робить тебе схожим на $R, якого я вбив минулого тижня!",
    C = "Що це?  Ах!  Пахне елем з темного заліза!  Напій затуманив зір, але я можу сказати, що ви, сер, справжній друг!",
},

[4296] = {
    en = "Tablet of the Seven",
    T = "Табличка Сімох",
    D = "Я прийшов до Палаючих Степів, слідуючи легендам про Сімох. Вони були дворфами з великими знаннями і силою, а якщо у тебе є знання і сила, то багатство неодмінно прийде.$B$BОсь чого я хочу. Багатства!$B$BЯкщо ми зможемо дізнатися більше про Сімох, можливо, ми зможемо розбагатіти разом. У руїнах Тауріссана, за чутками, зберігається Табличка Сімох, яка містить знання стародавніх дворфів. Знайди цю табличку, перепиши її текст і принеси мені. Давай відкриємо її таємниці разом!",
    O = "Принеси Транскрипт Таблички до Максворта Уберґлінта в Палаючих Степах.",
    P = "У вас є писання Семи, $N? Ви дізналися секрети їхнього планшета?",
    C = "Ах, ви знайшли планшет! І ваша транскрипція чудова! Ви впевнені, що ви $C, а не писар?$B$BHere, ви $N. Ось платіж, який я обіцяв.",
},

[4297] = {
    en = "Food for Baby",
    T = "Їжа для малюка",
    D = "Спрайт-дартери — всеїдні, тобто вони їдять як м’ясо, так і рослинність. Якщо твоє яйце тут має вилупитися, нам краще бути готовими. Хороша їжа для цих малюків — це шматки м’яса, сирі і соковиті, хочеш вір, хочеш ні. Я ніколи не міг зрозуміти чому, але це має щось спільне з планом Елуни для ельфів... можливо, вони мали бути захисниками чи щось таке, я не знаю.$B$BЯ подбаю про яйце наразі, а ти принеси мені кілька хороших боків сталкерів Срібногрива для них, коли він вилупиться.",
    O = "Принеси 5 Боків Сталкерів Срібногрива до Аґнара Звіролагіда в Запоємних Землях.",
    P = "Знайшов це м’ясо, $N? Ваше маленьке яйце майже готове до вилуплення. If he don't have a good enough first meal, then he might not make it past his first week, and I'd hate for that to happen.$B$BCan't much lie to ya, $N. Я заздрю, що ти отримав це яйце. Не змушуй мене шкодувати, що я тобі так допоміг.",
    C = "Вони підійдуть чудово, і якщо я не помиляюся, ваше маленьке яйце ось-ось готове до вилуплення. як це відчуваєш Знаєш, ти збираєшся стати батьком? Ха-ха, не думав, що тобі доведеться мати справу з такою відповідальністю, чи не так?",
},

[4298] = {
    en = "Becoming a Parent",
    T = "Стати батьком",
    D = "Ого, воно було набагато готовіше, ніж я думав...",
    O = "Поговори з Аґнаром Звіролагідом у Запоємних Землях.",
    P = "",
    C = "Ось, візьміть яйце... краще, щоб воно було у вас, щоб воно прив’язалося до вас і виглядало, як ви його тато.$B$BCongrats, $N. Ти батько... начебто.",
},

[4299] = {
    en = "",
    T = "<НВ> <ТХТ> Гробниця Сімох",
    D = "Знайди Гробницю Сімох і розмісти там PX83-Еніґматрон.",
    O = "Розмісти PX83-Еніґматрон у Гробниці Сімох, а потім повернися до Максворта Уберґлінта.",
    P = "",
    C = "",
},

[4300] = {
    en = "Bone-Bladed Weapons",
    T = "Зброя з кістяних лез",
    D = "Хм, можливо, є дещо, що ти можеш зробити для Руки, тепер, коли я думаю про це. Так, Джес’рімон точно міг би скористатися твоєю допомогою.$B$BУ кратері Ун’Ґоро є раптори з смертоносними кігтями. Деякі з цих рапторів іноді мають білі кігті замість чорних, як смерть. У Руки є... клієнти... які люблять зброю, виготовлену з цих кігтів. Принеси мені багато цих білих кігтів, і я добре тобі заплачу. Зроби це досить швидко, і, можливо, я допоможу тобі в інших справах.",
    O = "Принеси 8 Білих Кігтів Равазавра до Джес’рімона в Орґріммарі.",
    P = "Мої клієнти не такі терплячі, $N. Ви вже отримали кігті?",
    C = "Ах, ці гарні. Дякую, $N. І ти опинишся тут задовго до того, як їм знадобиться... це добре.$B$BMaybe у нас є зброя, створена для тебе з пазурів. що ти кажеш",
},

[4301] = {
    en = "The Mighty U'cha",
    T = "Могутній У’ча",
    D = "Поки ти досліджував Ун’Ґоро, я бачив інші речі, які сподобалися б такому могутньому мисливцю, як ти. Одним із таких видовищ була величезна мавпа серед інших горил на півночі. Ти вже бував у тій печері раніше, але цього разу я цікавлюся, чи виживеш ти у сутичці, якщо приймеш моє завдання.$B$BЯ називаю його У’ча, і він один із найбільших синів Матері-Землі, у цьому ти можеш бути впевнений. Переможи У’ча і принеси мені його шкуру. Зроби це, і я захищу твоє право називати себе великим мисливцем.",
    O = "Принеси Шкуру У’ча до Торви Слідопита біля входу до кратера Ун’Ґоро.",
    P = "У'ча... звір був чудовий. Величезний і червоний, із зубами завбільшки з кинджали. Його руки товсті, як стовбури дерев, і швидкі, як будь-який гірський лев, якого я коли-небудь бачив. Вважайте, що вам пощастило знайти таке випробування хоробрості — мої люди пройшли б поколіннями, щоб не бачити такої істоти.",
    C = "Молодець, $N. Я задоволений. Ви сьогодні тут зробили велику справу.$B$BU'ча була однією з найбільших мавп, яких я коли-небудь бачив. Той факт, що ви перемогли його силу, добре говорить про вашу власну силу... і мужність.$B$BIt цілком доречно, що я віддаю вам це на знак поваги. Ви це заслужили.",
},

[4321] = {
    en = "Making Sense of It",
    T = "Осмислення",
    D = "Інформація, яку ти мені дав про пілони, дуже цікава...$B$BДай мені хвилинку, щоб зробити деякі розрахунки, $N. Поговори зі мною знову через мить, і я зможу дати тобі відповідь, яку ми шукали.",
    O = "Поговори з Джей.Ді. Коллі через мить.",
    P = "",
    C = "Добре, $N. Це захоплююче... Я можу тільки сподіватися, що мої діаграми правильні! Я зібрав усе в цьому посібнику, який ви можете отримати.$B$BI Вважаю, що зараз можу відповісти на будь-які ваші запитання щодо кристалів, $N.",
},

[4322] = {
    en = "Jail Break!",
    T = "Втеча з в’язниці!",
    D = "Нам потрібно вибратися звідси, $N. Допоможи мені повернути моє спорядження з зони постачання і звільнити моїх друзів. Якщо ми виберемося звідси, ти маєш вирушити до Дозору Моргана і поговорити з Маршалом Максвеллом. Він дасть тобі подальші інструкції.",
    O = "Допоможи Маршалу Віндсору повернути його спорядження і звільнити друзів. Повернися до Маршала Максвелла, якщо тобі це вдасться.",
    P = "Ти виглядаєш виснаженим, $n. Можливо, вам варто сісти біля вогнища й розслабитися.",
    C = "Чудово, $N. Просто неймовірно. Віндзор увірвався сюди не п'ять хвилин тому. Він висуває деякі грандіозні заяви, але стверджує, що вони підтверджуються його доказами. Зараз він прямує до Штормовія, щоб протистояти Болвару та... леді Престор.",
},

[4323] = {
    en = "",
    T = "<НВ> <ТХТ> Дістань тих гієн!!!",
    D = "Я хочу шкур гієни, і тільки найкращі підійдуть! Дістань мені плямисті шкури гієни, і я дам тобі круті нагороди, йо.",
    O = "Принеси 7 Плямистих Шкур Гієни до ТЕСТТАУРЕНА на Посту Вільного Вітру.",
    P = "",
    C = "",
},

[4324] = {
    en = "Yuka Screwspigot",
    T = "Юка Скрюспіґот",
    D = "Хоча мій молодший брат Рібблі все життя був нікчемним, я думаю, нарешті, він має якусь цінність! Але... нам може знадобитися твоя допомога, щоб скористатися новознайденою цінністю Рібблі.$B$BМоя сестра Юка тижнями його шукала і вистежила до Палаючих Степів. Вона надіслала мені повідомлення, просячи найняти кількох помічників.$B$BТо що скажеш? Хочеш допомогти? Якщо так, то поговори з моєю сестрою. Ти знайдеш її в Палаючому Пікові, печері на північний захід від Скелі Жахокруш.",
    O = "Поговори з Юкою Скрюспіґот у Палаючих Степах.",
    P = "",
    C = "Так, я шукаю свого брата.  Ми повинні знайти його та повернути, благослови його серце.$B$BBut якщо ми не зможемо привести його всього... то його голови вистачить.",
},

[4341] = {
    en = "Kharan Mighthammer",
    T = "Харан Майтгаммер",
    D = "Ти бував у палаючих руїнах Тауріссана? Чи не траплявся тобі там жалюгідний дурень на ім’я Харан Майтгаммер? Дворф, який нібито мав доглядати за моєю маленькою дівчинкою!$B$B<Король ридає.>$B$BА тепер її немає, $N!$B$BЯ наказав своїм людям перевернути Степи догори дном. Єдина підказка щодо місцезнаходження моєї доньки — що вона може бути в Глибинах. Я навіть не знаю, чи вона жива!$B$BХаран, кажуть, утримується там як в’язень... знайди його! Я хочу відповідей!",
    O = "Вирушай до Глибин Чорноскелі і знайди Харана Майтгаммера.$B$BКороль згадав, що Харан утримується там як в’язень — можливо, тобі варто пошукати в’язницю.",
    P = "",
    C = "Будь ласка, дозвольте мені пояснити.",
},

[4342] = {
    en = "Kharan's Tale",
    T = "Оповідь Харана",
    D = "Будь ласка, вислухай мене, перш ніж виносити суд!",
    O = "Вислухай історію Харана Майтгаммера.",
    P = "Дозвольте мені закінчити свою історію.",
    C = "Як бачите, я нічого не міг зробити.",
},

[4343] = {
    en = "Corrupted Windblossom",
    T = "Пошкоджений Вітроцвіт",
    D = "",
    O = "",
    P = "Ви знайшли хворобливу, зіпсовану версію того, що виглядає як вітроцвіт. Ягоди, що звисають з рослини, здаються гнилими та отруйними. Він відчайдушно потребує певної уваги, якщо хочеться повернути його до нормального стану.",
    C = "Ви наносите дві рослинні мазі Кенаріону на квітку вітру. Воно відразу починає скидати зіпсовану форму, перетворюючись на живу та здорову рослину.",
},

[4361] = {
    en = "The Bearer of Bad News",
    T = "Носій поганих новин",
    D = "Ти мусиш повернути цю інформацію до Короля Маґні, $N. Він знатиме, що робити!",
    O = "Повернися до Залізогарта і передай погані новини Королю Маґні Бронзобороду.",
    P = "",
