[4362] = {
    en = "The Fate of the Kingdom",
    T = "Доля королівства",
    D = "Здається, мій старий ворог, Даґран Тауріссан, тримає мене і королівство Залізогарт у своїй владі.$B$BТи можеш бути моєю останньою надією, $N. Ти мусиш врятувати мою дорогу доньку, Мойру!$B$BЄ лише один спосіб переконатися, що закляття, яке Тауріссан наклав на Мойру, зламане: убити його.$B$BІ $N, не завдай їй шкоди! Пам’ятай, вона під контролем Тауріссана! Те, що вона може робити чи казати, — результат злого закляття Тауріссана!",
    O = "Повернися до Глибин Чорноскелі і врятуй Принцесу Мойру Бронзобород з лихих кігтів Імператора Даґрана Тауріссана.",
    P = "",
    C = "<Принцеса Бронзоборода плаче через втрату імператора Даграна Тауріссана.>$B$BWhy???",
},

[4363] = {
    en = "The Princess's Surprise",
    T = "Несподіванка принцеси",
    D = "Тауріссан був великим і почесним дворфом. Ти зруйнував моє життя і життя моєї ненародженої дитини!$B$B<Ти думаєш, що Принцеса Бронзобород, можливо, все ще страждає від залишкового ефекту закляття Імператора.>$B$BПовернися до Залізогарта і скажи моєму батькові, що спадкоємець королівства Залізогарт буде дворфом Темного Заліза.$B$BСхвалює він це чи ні, так буде.",
    O = "Повернися до Залізогарта і поговори з Королем Маґні Бронзобордом.",
    P = "",
    C = "<Король Магні Бронзобородий помітно засмучений.>$B$BIt здається, навіть у смерті Тауріссан переміг.$B$BYou звільнено, $N. Перш ніж піти, ви можете вибрати свою нагороду з королівського сховища.$B$B<Король Бронзобород опускається на свій трон, щоб обміркувати цю дивну зміну подій.>",
},

