[4487] = {
    en = "Summon Felsteed",
    T = "Виклик Скверноконя",
    D = "Ага, добре, що ти тут. Я послав за тобою $g суккубу:інфернала;, щоб привернути твою увагу, але, здається, ти зміг дістатися сюди раніше, ніж він тебе знайшов. Неважливо.$B$BОстаннім часом ходять розмови про твою зростаючу силу — це добре для тебе, але, можливо, погано для інших. Але це несуттєві моменти. Суть у тому, що я вважаю, що ти довів свою цінність і тому заслуговуєш… хе-хе… своєрідного благословення.$B$BНад Ратчетом у Степах ти знайдеш людину на ім’я Страхад. Здається, ви вже перетиналися раніше.",
    O = "Поговоріть із Страхадом Фарсаном у Ратчеті.",
    P = "",
    C = "",
},

[4488] = {
    en = "Summon Felsteed",
    T = "Виклик Скверноконя",
    D = "Ах, $N, ти зволив вшанувати нас своєю присутністю. Як чудово!$B$BСподіваюся, ти не очікуєш, що ми будемо прислуговувати тобі на кожному кроці. Ти можеш швидко зростати в силі, але ти все ще щеня, коли йдеться про справжні знання та розуміння. Якщо не будеш обережним, скверна поглине тебе і твою слабку волю.$B$BАле перейду до суті: Страхад хоче поговорити з тобою. Він усе ще мешкає у своїй вежі над Ратчетом у Степах. Я б радив не затримуватися надто довго.",
    O = "Поговоріть із Страхадом Фарсаном у Ратчеті.",
    P = "",
