[4621] = {
    en = "Avast Ye, Admiral!",
    T = "Гей, Адмірале!",
    D = "Слухай уважно, морський вовче… влада Бухти Видобутку заважає нам, Кривавим Вітрилам, плавати, де нам заманеться, і брати те, що ми хочемо, як законне право на здобич. Якби ти зарубав Флотського Майстра Сігорна, ми б ніколи не мали проблем із суднами Бухти Видобутку. Якби ти зарубав Барона Ревілґаза, ми б ніколи не стикалися з їхнім законом на їхніх умовах.$B$BЯкщо ти хочеш бути почесним адміралом серед нас — так, АДМІРАЛОМ, тобі треба зарубати їх обох, як я сказав. Іди ж, $g хлопче:дівчино;, і повертайся до мене, коли виконаєш ці вчинки.",
    O = "Убийте Флотського Майстра Сігорна і Барона Ревілґаза з Бухти Видобутку, а потім поверніться до Флотського Майстра Фіраллона на борт «Червоного Серпанку» біля узбережжя Тернистої Долини.",
    P = "Ти вже повернувся, проклята смола! Ви зробили, як я наказав? Підведи нас, і ти будеш ходити по дошці.$B$BArrrrr...",
    C = "Avast ye... Admiral $N!  Ти пірат із піратів, дівчино!$B$BIt гріє моє серце, щоб подарувати тобі цей капелюх.  Ви ніколи й ніде не знайдете подібного, і кожен, хто подивиться на вас, побачить, що ви адмірал флоту «Кривавого вітрила»!",
},

[4641] = {
    en = "Your Place In The World",
    T = "Твоє місце у світі",
    D = "Нарешті ти досяг повноліття, $N... повноліття, щоб битися в ім’я Орди. Щоб перемагати заради слави Вождя.$B$BТак...$B$B<Калтунк оглядає тебе.>$B$BТи чудово підійдеш.$B$BБез сумніву, ти мрієш знайти величезного дракона чи демона і задушити його голими руками, але, можливо, варто почати з чогось менш... небезпечного.$B$B<Калтунк сміється.>$B$BДоповідай Ґорнеку, він зможе дати завдання, яке краще підійде молодому $c. Ти знайдеш Ґорнека в Лігві, на захід звідси.",
    O = "Поговори з Ґорнеком. Ти пригадуєш, як Калтунк позначив його місце на твоїй карті і згадав, що Ґорнек перебуває в Лігві, будівлі на заході.",
    P = "",
    C = "Ще один із новобранців Калтунка, хм?$B$BA жаль, у якому ми опинилися, якщо це найкраще, що може створити Орда. Не важливо. Коли ми подумаємо, що ти будеш готовий залишити Долину, ти будеш гордим $C Орди.",
},

[4642] = {
    en = "Melding of Influences",
    T = "Злиття впливів",
    D = "Ось трохи закапсульованого слизу, створеного з зразків зі Скверноліссі, які ти здобув. Візьми цю капсулу до кратера Ун’Ґоро і знайди чистого слимака... первісний різновид цілком підійде. Коли будеш достатньо близько, випусти слиз із капсули, і подивимося, що вони думають один про одного.$B$BПісля завершення експерименту принеси мені зразок того, що залишиться. Я чекатиму тебе тут, в Аптекаріумі.",
    O = "Принеси Зразок Злитого Слимака до Хіміка Ф’юлі в Підмісті.",
    P = "Як проходить експеримент, $N? Я продовжу вивчати зразки, які ви знайшли для мене, я починаю розуміти, чому леді Сільвана так цікавиться цими створіннями. Якщо вони справді є частиною Старих Богів, то хто знає, як це можна використати на нашу користь.",
    C = "О, чудово, $N. Це чудово.$B$BSuch казка. Хто б міг подумати, що вони будуть взаємодіяти одне з одним таким чином... Мені доведеться витратити більше часу на вивчення екологічних проблем, які викликають зміни в цих істотах.$B$BI поки що продовжу свої дослідження. Можливо, скоро ми знову поговоримо. А поки бажаю тобі добра.",
},

