[4906] = {
    en = "Further Corruption",
    T = "Дальша Скверна",
    D = "Другий табір сатирів загрожує землі Сквернолісу на півночі, під проводом жорстокого Ксаваріка. Підлі зрадники і шахраї живляться скверною місцевих істот Сквернолісу.$B$BКсаватрас і його поплічники були лише частиною більшого плану — виростити осквернений місячний колодязь, а потім передати здобич Ксаваріку.$B$BТепер, коли Ксаватраса немає, заверши це завдання, $N. Вирушай на північ і переможи Ксаваріка.",
    O = "Ерідан Блакитновітер у Сквернолісі хоче, щоб ви зарубали 8 Нефритових Пеклокличів, 8 Нефритових Зрадників, 8 Нефритових Шахраїв і Ксаваріка. Поверніться до Ерідана, коли завдання буде виконано.",
    P = "Будь ласка, покладіть край стражданням створінь Фелвуда.",
    C = "Дякуємо за все, що ви зробили, $N. Нехай Елуна захищає вас і направляє на майбутній шлях.",
},

[4907] = {
    en = "Tinkee Steamboil",
    T = "Тінкі Парокип",
    D = "Привіт, $N. Пам’ятаєш Тінкі Парокип? Що ж, вона тебе пам’ятає! Вона надіслала мені повідомлення, щоб я стежив за тобою, бо… їй знову потрібна твоя допомога. Думаю, це має щось спільне з її дослідженнями драконів.$B$BТобі варто поговорити з нею в Палаючих Степах, у Полум’яному Хребті.",
    O = "Поговоріть із Тінкі Парокип.",
    P = "",
    C = "Фельнок мав рацію! Мені знову потрібна ваша допомога, і цього разу... це буде дуже небезпечно.$B$BAre ви готові??",
},

[4921] = {
    en = "Lost in Battle",
    T = "Загублена в Битві",
    D = "Ми билися в маленькому тауренському таборі, коли нас розділили — вона сама стримувала трьох Шерстохряків. Але перевага почала переважати нас. Я відвів частину ворогів, але побачив, як її здолали нові нападники. У своїй люті я обернувся проти ворогів, але їхня чисельність легко мене здолала.$B$BЯ прокинувся, коли тауренський друїд лікував мої рани — він натрапив на мене на Золотому Шляху, коли я впав.$B$BБудь ласка, $c, знайди хоч якийсь знак моєї дружини.",
    O = "Знайдіть дружину Манкріка, а потім поверніться до нього на Перехрестя.",
    P = "Ви взагалі знайшли її ознаки? Біль у моїх грудях говорить мені, що сталося найгірше, але я сподіваюся, що ви знайдете її цілою та неушкодженою.",
    C = "я розумію Дякую, $C.",
},

[4941] = {
    en = "Eitrigg's Wisdom",
    T = "Мудрість Ейтріґґа",
    D = "Ренд живий?$B$BНеможливо!$B$BВважалося, що Ренд був зарубаний десятиліття тому.$B$BШукай мудрості Ейтріґґа, $N. Ніхто не знає справ Чорної Скелі краще за нього, і якщо те, що тут написано, є правдою, Ейтріґґа слід повідомити. Ніхто не повинен бути позбавлений права на помсту.$B$BТи знайдеш його в Оргріммарі.$B$BПісля того, як поговориш із Ейтріґґом, порадься з Вождем, щоб дізнатися, що він хоче зробити з цією проблемою.",
    O = "Поговоріть із Ейтріґґом в Оргріммарі. Після того, як обговорите справи з Ейтріґґом, порадьтеся з Траллом.$B$BВи пригадуєте, що бачили Ейтріґґа в покоях Тралла.",
    P = "Хіба ви не бачите, що мене не можна переривати?",
    C = "<Трал здається наляканим новинами, які ви принесли.>",
},

[4961] = {
    en = "Cleansing of the Orb of Orahil",
    T = "Очищення Сфери Орагіла",
    D = "Ах, сфера закликача — ось звідки походить скверна. Ми мусимо вигнати демона всередині неї, якщо ти хочеш її використовувати. Це я можу зробити легко.$B$BТвоя задача буде складнішою. Ти мусиш убити демона, щойно я його звільню.$B$BІ тобі доведеться поспішити. Якщо ти забаришся, він повернеться до сфери, і нам доведеться починати спочатку!$B$BТож готуйся, $N. Приготуй свої найсильніші закляття, тримай зілля під рукою, і візьми друга, якщо маєш. Бо це буде нелегко.",
    O = "Убийте Демона Сфери, а потім поговоріть із Табетою.",
    P = "Вам доведеться вбити цього демона, щоб назавжди видалити його присутність із сфери, $N.",
    C = "Чудово, $N!  Ти дав цьому демону урок, який він не скоро забуде. Ви показали велику силу та майстерність. Тепер я вважаю, що вам пора повернутися до Менари зі своєю очищеною кулею, щоб ви могли використати її з користю.$B$BGood удачі, $C. Можливо наші шляхи ще перетнуться.",
},

[4962] = {
    en = "Shard of a Felhound",
    T = "Уламок Сквернопса",
    D = "Отже, ти обрав захопити душу сквернопса, добре.$B$BВізьми цей рубін — з ним ти зможеш захопити душу істоти. Він працює подібно до заклять, які ти вже знаєш: коли істота буде близька до смерті, використай самоцвіт, і він має зробити решту роботи за тебе.$B$BЯ б порадив вирушити до Спустошення і спробувати свої сили на будь-якому зі сквернопсів там. Вони мають підійти.$B$BПісля успіху принеси захопленого духа і твій рубін до Менары.",
    O = "Візьміть Рубін Скверни і використайте його на одному зі Сквернопсів у Спустошенні. Після успіху принесіть Рубін Скверни і Ув’язненого Духа Сквернопса назад до Менары Порожньогляду в Степи.",
    P = "Так, $N? Ви вибрали? Пекельний чи гончий?$B$BEach вибір є особистим і має відображати ваші сильні та слабкі сторони. Це не дивно, коли $C покращує себе далі, замість того, щоб компенсувати ті сфери, яких їм бракує. Іноді здолати ворога є такою ж сильною тактикою, як стати більш збалансованим заклинателем.",
    C = "Ах, дух собаки. Молодець, $N.$B$BWhen У мене є і дух, і очищена сфера, я об’єднаю їх для вас, але тільки тоді.",
},

[4963] = {
    en = "Shard of an Infernal",
    T = "Уламок Інфернала",
    D = "Отже, ти обрав захопити душу інфернала, добре.$B$BВізьми цей смарагд — з ним ти зможеш захопити душу істоти. Він працює подібно до заклять, які ти вже знаєш: коли істота буде близька до смерті, використай самоцвіт, і він має зробити решту роботи за тебе.$B$BЯ б порадив вирушити до Спустошення і спробувати свої сили на будь-якому з інферналів там. Вони мають підійти.$B$BПісля успіху принеси захопленого духа і твій смарагд до Менары.",
    O = "Візьміть Смарагд Інфуза і використайте його на одному з Інферналів у Спустошенні. Після успіху принесіть Смарагд Інфуза і Ув’язненого Духа Інфернала назад до Менары Порожньогляду в Степи.",
    P = "Так, $N? Ви вибрали? Пекельний чи гончий?$B$BEach вибір є особистим і має відображати ваші сильні та слабкі сторони. Це не дивно, коли $C покращує себе далі, замість того, щоб компенсувати ті сфери, яких їм бракує. Іноді здолати ворога є такою ж сильною тактикою, як стати більш збалансованим заклинателем.",
    C = "Ах, дух пекельний. Молодець, $N.$B$BWhen У мене є і дух, і очищена сфера, я об’єднаю їх для вас, але тільки тоді.",
},

[4964] = {
    en = "The Completed Orb of Dar'Orahil",
    T = "Завершена Сфера Дар’Орагіла",
    D = "Я негайно почну створювати твою сферу і наповнювати її новим демоном. Коли все буде готово, ти зможеш обрати, чи хочеш її у вигляді посоха, чи сфери. Я завжди вважав важливим враховувати обрану зброю чаклуна… Я не бачу причин припиняти цю практику.",
    O = "Зачекайте, поки Менара Порожньогляд завершить Сферу Дар’Орагіла, а потім поговоріть із нею знову.",
    P = "",
    C = "Це зроблено, $N. Просто скажіть мені, що ви віддаєте перевагу: посох, який вимагатиме від вас використання обох рук, чи куля, щоб ви могли використовувати кинджал чи меч як свою зброю.$B$BTackling собака скверни була великим подвигом з вашого боку. Я впевнений, що ваш товар служитиме вам у майбутньому. Продовжуйте наполегливо працювати в мистецтві, $N. Я чекаю подробиць ваших подвигів.",
},

[4965] = {
    en = "Knowledge of the Orb of Orahil",
    T = "Знання про Сферу Орагіла",
    D = "Що ж, що ж, що ж… приємно бачити, що ти зростаєш у силі, $N. Я б сказав, що ти готовий поговорити з Менарою Порожньоглядом у Степах. Якщо ти ще не розмовляв із нею раніше, то скажу, що я не думаю, що коли-небудь зустрічав іншого експерта зі створення предметів — зокрема сфер — які можуть так легко ув’язнити демона, щоб він служив нашій волі.$B$BЯкщо тобі цікаво, вона в башті Страхада над Ратчетом у Степах.",
    O = "Поговоріть із Менарою Порожньоглядом у Степах.",
    P = "",
    C = "Ах, ти шукаєш чогось більшого... істотного. Що я можу вам допомогти, якщо ви справді готові.$B$BIt — приємна зміна — побачити одного з нас, який шукає більше сили в інших формах, ніж просто знання.$B$BSo, ви відчуваєте, що готові, $N?",
},

[4966] = {
    en = "Protect Kanati Greycloud",
    T = "Захищайте Канаті Сірогрива",
    D = "Але, можливо, кентаврів більше, ніж я думав, тому я прошу тебе, $n, битися разом зі мною проти цих мерзенних убивць.",
    O = "Захищайте Канаті Сірогрива від нападу кентаврів.",
    P = "",
    C = "Дякуємо за допомогу, $N. Я б не зміг їх утримати без вас.",
},

[4967] = {
    en = "Knowledge of the Orb of Orahil",
    T = "Знання про Сферу Орагіла",
    D = "Все ще дурень, і все ще шукаєш прикрас смертних. Так, я говорю з тобою з пихою. Я бачу тебе переді мною і сміюся. Ти жалюгідний!$B$BАле неважливо, що я думаю. Важливо лише, що думають ті, хто готовий мати з тобою справу! І в цьому випадку, проти мого кращого судження, ті, хто має певну частку влади, вважають, що ти заслуговуєш більшого.$B$BЯкщо це те, до чого ти прагнеш, то тобі варто поговорити з Менарою Порожньоглядом у башті над Ратчетом. Здається, ви вже колись зустрічалися раніше.",
    O = "Поговоріть із Менарою Порожньоглядом у Степах.",
    P = "",
    C = "Ах, ти шукаєш чогось більшого... істотного. Що я можу вам допомогти, якщо ви справді готові.$B$BIt — приємна зміна — побачити одного з нас, який шукає більше сили в інших формах, ніж просто знання.$B$BSo, ви відчуваєте, що готові, $N?",
},

[4968] = {
    en = "Knowledge of the Orb of Orahil",
    T = "Знання про Сферу Орагіла",
    D = "Хм, ти дійшов так далеко… справді вражаюче. Я б подумав, що скверна від каналювання арканної магії вже просочилася б у твою душу і звела б тебе з розуму. Як щодо того, щоб ми спробували підштовхнути тебе ще далі?$B$BЯкщо хочеш перевірити свої навички, шукай Менары Порожньогляду над Ратчетом у башті Страхада. Вона направить тебе.",
    O = "Поговоріть із Менарою Порожньоглядом у Степах.",
    P = "",
    C = "Ах, ти шукаєш чогось більшого... істотного. Що я можу вам допомогти, якщо ви справді готові.$B$BIt — приємна зміна — побачити одного з нас, який шукає більше сили в інших формах, ніж просто знання.$B$BSo, ви відчуваєте, що готові, $N?",
},

[4969] = {
    en = "Knowledge of the Orb of Orahil",
    T = "Знання про Сферу Орагіла",
    D = "Ха-ха! Ти дуже добре справляєшся, молодий $c.$B$BЗ часом інфернали і жахолорди схиляться перед тобою!$B$BАле до того часу ти все ще мусиш покладатися на зброю, створену руками смертних рас.$B$BТи здається готовий до ще одного такого творіння, і якщо ти бажаєш, Менара Порожньогляд поговорить із тобою! Вона біля башти Страхада, що височіє над портовим містом Ратчет. Вирушай туди, коли будеш готовий.",
    O = "Поговоріть із Менарою Порожньоглядом у Степах.",
    P = "",
    C = "Ах, ти шукаєш чогось більшого... істотного. Я можу вам допомогти, якщо ви справді готові.$B$BIt — приємна зміна — побачити одного з нас, який шукає більше сили в інших формах, ніж просто знання.$B$BSo, ви відчуваєте, що готові, $N?",
},

[4970] = {
    en = "Frostsaber Provisions",
    T = "Запаси для Крижанозубів",
    D = "Якщо ти хочеш довести свою цінність, можеш почати з виконання дуже простого, але дуже важливого завдання.$B$BЗбери м’ясо з химер і з ведмедів-осколкозубів у цій місцевості. Принеси його мені, щоб я міг використати його для годування крижанозубів, яких тренують.",
    O = "Зберіть 5 Шматків М’яса Осколкозубів і 5 Шматків М’яса Холодновітру для Ріверна Морозновітра в Зимових Ключах.",
    P = "Дисципліна і цілеспрямованість - ось ваша мета. Я можу попросити вас виконати просте завдання багато разів; ви повинні кожного разу працювати якнайкраще.",
    C = "Дякую за допомогу, $N. Моя думка про вас зростає з часом.",
},

[4971] = {
    en = "A Matter of Time",
    T = "Справа Часу",
    D = "Втручання в часову лінію зловісною силою — найімовірніше, Скарою — сталося в Андоґалі! Я можу спробувати зберегти плин часу тут недоторканим і виправити те, що було пошкоджено, але мені знадобиться твоя допомога, щоб зробити це без перешкод.$B$BЧасові паразити — падаль, що живиться зміненими потоками часу — тепер заполонили силоси Андоґала. Синій пульс спотворення — їхній єдиний візуальний маркер. Вони сповільнюють мої передбачення; будь ласка, $N, допоможи мені, використавши цей часовий зміщувач, щоб викорінити цих паразитів.",
    O = "Використайте Часовий Зміщувач біля одного з силосів Андоґала і виявіть Часових Паразитів.$B$BУбийте 15 Часових Паразитів, а потім поверніть Часовий Зміщувач до Хромі в Андоґальській Корчмі, Західні Зачумлені Землі.",
    P = "Скроневі паразити — поширена хвороба, яка присутня скрізь, де втручався в плин часу.  Я відчуваю, що багато присутніх, і це викликає занепокоєння.$B$BRooting те, що ви знайдете, допоможе мені краще впоратися з погіршенням тимчасової ситуації тут.  Я зможу відчути, коли це буде досягнуто.",
    C = "Здається, тепер час легше налагодити, дякую, $N. Хоча ви можете не повністю розуміти наслідки порушення хронології, я вдячний за те, що ви розумієте нагальність протидії тому, що, як я все більше й більше підозрюю, є злочином, спричиненим Бичем.$B$BI не бачу шкоди винагородити вас за вашу допомогу, смертний. Ваші найбільші подвиги попереду, і вручення дрібнички точно не змінить вашої подальшої долі. Однак ваша постійна допомога може стати в нагоді мені та драконячій зграї...",
},

[4972] = {
    en = "Counting Out Time",
    T = "Рахунок Часу",
    D = "Мені потрібно, щоб ти зазирнув у світ за межами цієї кімнати, $N. Дозволь мені пояснити.$B$BТи бачиш різницю в цій кімнаті порівняно з рештою Андоґала. Мій драконячий рід працює в багатьох різних способах і в багатьох різних часових лініях. Щоб виправити пошкодження Андоґала, я тепер дію з іншої часової лінії, щоб не забруднити її надмірно. Але щоб продовжити це, мені потрібні часові дрібнички, ті, що були захоплені, коли чума вразила місто. Знайди їх у скринях, що заховані серед руїн цього колись гордого міста.",
    O = "Знайдіть 5 Андоґальських Годинників у скринях серед руїн міста. Поверніться з ними до Хромі в Андоґальську Корчму, Західні Зачумлені Землі.",
    P = "Часові дрібнички, яких я шукаю, — це прості пристрої. Це переважно годинники, а їхні стрілки назавжди потрапили в пастку, коли чума вперше спустошила Андорал.$B$BTime ніколи не закінчується, і годинники, які ви приносите мені, незмінно повертатимуться до своїх домівок... тобто до тих пір, поки тут триватимуть заворушення.",
    C = "Це саме те, що мені потрібно, $N. Дякую.$B$BAllow щоб я відповідним чином винагородив вас цим. Ви можете не зрозуміти, що вам знадобиться з таким пристроєм. Ви можете навіть не знати, що це насправді. На жаль, я не можу сказати вам, коли ви знайдете це найбільш корисним; просто знайте, що в якийсь момент у майбутньому ви можете виявити, що цей предмет буде надзвичайно корисним і функціональним під час споживання. Незалежно від того, чи ви вирішите триматися цього до тих пір... це, друже, вирішувати вам.",
},

[4973] = {
    en = "Counting Out Time",
    T = "Рахунок Часу",
    D = "Якщо ти готовий допомогти ще раз, я з радістю прийму твою допомогу. Я охоче візьму ще годинники, які ти можеш знайти серед руїн Андоґала. Вони точно допомагають мені підтримувати баланс проти будь-якої зловісної сили, що втручається в часову лінію тут.$B$BВ обмін на ці годинники я дам тобі ще один предмет, який, я підозрюю, у майбутньому тобі дуже знадобиться.",
    O = "Знайдіть 5 Андоґальських Годинників серед руїн міста і поверніться з ними до Хромі в Андоґальську Корчму, Західні Зачумлені Землі.",
    P = "Годинники Андорала, як і великий годинник на руїнах ратуші, усі завмерли в часі о третій годині.  Це було тоді, коли наслідки чуми вперше поширилися над містом, заглушивши в ньому життя.$B$BAs Як би ми не шкодували про те, що сталося того дня, це сформувало плин часу, яким його сприймаєте ви, смертні.  Бронзові дракони мають наполегливо захищати шкалу часу!",
    C = "Знову ж таки, я думаю, що ви за вашу допомогу.  Будь ласка, прийміть цей подарунок.  Хоча ви все ще можете не знати, коли використовувати такий предмет, можливо, у майбутньому шлях часу розкриє вам його справжні наміри.  Можна сказати, що я бачив, як це відбувається з тобою, $N.",
},

[4974] = {
    en = "For The Horde!",
    T = "За Орду!",
    D = "Ренд наважується робити такі гучні заяви через захист, який йому забезпечує чорний драконячий рід.$B$BТи, $N, знайдеш спосіб пройти через Зали Вознесіння. Потім ти знайдеш ‘Вождя’ Ренда Чорну Длань і знищиш його — ЗА ОРДУ!$B$B<Тралл грюкає кулаком по своєму трону.>$B$BНаступного разу, коли ти повернешся до моїх покоїв, ти триматимеш його голову високо в тріумфі, а потім представиш її своєму Вождю. Зроби це і будь вшанований як герой Орди.",
    O = "Вирушайте до Шпиля Чорної Скелі і зарубайте Вождя Ренда Чорну Длань. Візьміть його голову і поверніться до Оргріммара.",
    P = "<Тралл бурчить.>",
    C = "Ви завдали руйнівного удару по силам Чорної Гори, $N. Після вбиття свого вождя легіон Чорної Гори знову кинутий у патрону хаосу.$B$BIn честь вашої героїки, люди Калімдору будуть винагороджені!",
},

[4975] = {
    en = "The Completed Orb of Noh'Orahil",
    T = "Завершена Сфера Но’Орагіла",
    D = "Я негайно почну створювати твою сферу і наповнювати її новим демоном. Коли все буде готово, ти зможеш обрати, чи хочеш її у вигляді посоха, чи сфери. Я завжди вважав важливим враховувати обрану зброю чаклуна… Я не бачу причин припиняти цю практику.",
    O = "Зачекайте, поки Менара Порожньогляд завершить Сферу Но’Орагіла, а потім поговоріть із нею знову.",
    P = "",
    C = "Це зроблено, $N. Просто скажіть мені, що ви віддаєте перевагу: посох, який вимагатиме від вас використання обох рук, чи куля, щоб ви могли використовувати кинджал чи меч як свою зброю.$B$BTackling інфернал був великим подвигом з вашого боку, і ця нагорода вам добре підійде. Бажаю тобі подальших успіхів у мистецтві, $N.",
},

[4976] = {
    en = "Returning the Cleansed Orb",
    T = "Повернення Очищеної Сфери",
    D = "Віднеси очищену сферу назад до Менары в Ратчет, $N. Передай їй мої вітання і будь обережний. Я щиро сподіваюся, що ти зможеш протистояти спокусі і скверні, які неодмінно прийдуть, коли ти підеш своїм шляхом.$B$BУдачі.",
    O = "Поверніть Очищену Інфернальну Сферу до Менары Порожньогляду в Степи.",
    P = "Як проходять ваші пошуки Табети та кулі, $N?$B$BTabetha було більш ніж корисним, коли справа доходить до таємничих питань. Я впевнений, що вона без проблем допоможе тобі, якщо ти зможеш її знайти.",
    C = "Молодець, $N. Це буде добре.$B$BThe Єдине, що вам залишилося зробити, це вирішити, якого демона ви хочете, щоб я ув’язнив у очищеній кулі. Зробіть це, і ви отримаєте чудовий новий предмет для володіння.",
},

[4981] = {
    en = "Operative Bijou",
    T = "Оперативниця Біжу",
    D = "Ніколи не довіряй гобліну. Ось до чого все зводиться, $N.$B$BЇї звати Біжу — одна з наших найхитріших оперативниць. Я дізнався, що вона працювала на якогось тіньового торговця екзотичними тваринами з Палаючих Степів на ім’я Кіблер, по суті, зраджуючи нас. Що гірше, вона використовувала кошти Орди для фінансування своїх операцій.$B$BЯ хочу, щоб її привели сюди живою.$B$BВостаннє її бачили, коли вона входила до Шпиля Чорної Скелі. Знайди її і поверни назад.$B$BІ $N, не дай їй заговорити тебе.",
    O = "Вирушайте до Шпиля Чорної Скелі і дізнайтесь, що сталося з Біжу.",
    P = "",
    C = "Я не буду тобі брехати, $R. Мені потрібні були гроші! Кіблер платить дуже, дуже добре - набагато краще, ніж K.E.F. коли-небудь міг.$B$BBut не сумнівайся в моїй відданості! Як ти думаєш, чому я тут? Щоб дістати цьому божевільному гобліну яйця екзотичних тварин чи щось таке ж безглузде? Ні, тільки хтось по-справжньому тупий прийшов би на Шпиль Чорної Гори збирати домашніх тварин. Так, я не думаю, що таких людей існує в цьому світі.$B$B<Bijou laughs.>$B$BThe останнє, що нам потрібно, — це розмноження таких людей.",
},

[4982] = {
    en = "Bijou's Belongings",
    T = "Речі Біжу",
    D = "Вночі, коли це місце слабо охороняється, я пробираюся містом, роблю нотатки і записую все, що бачу, що може мати стратегічну цінність для К.Е.Ф.$B$BАле минулої ночі все пішло жахливо не так. Я зачепив розтяжку і спрацювала сигналізація. Я заховала своє розвідувальне спорядження і втекла в укриття! На жаль, я не можу повернутися до того спорядження. Вони подвоїли, а то й потроїли патрулі! Уся та інформація втрачена.$B$BПоверни мої речі, і я мирно повернуся до К.Е.Ф.",
    O = "Знайдіть Речі Біжу і поверніть їх їй. Ви пригадуєте, що вона згадувала, що заховала їх на нижньому поверсі міста.",
    P = "Пощастило?",
    C = "Ви зробили це! Щойно у Лекслорта з’являться ці плани, він забуде про те, що хотів зі мною зробити.$B$B$N, ти мій герой!",
},

[4983] = {
    en = "Bijou's Reco$b$baissance Report",
    T = "Розвідувальний Звіт Біжу",
    D = "Віднеси цей звіт назад до Лекслорта. Це відновить моє добре ім’я і, без сумніву, дасть К.Е.Ф. стратегічну перевагу в боротьбі з цими орками.$B$BПіти з тобою? У мене занадто багато роботи. Рушай, їм потрібні ці звіти якомога швидше!",
    O = "Віднесіть Розвідувальний Звіт Біжу назад до Великого Майстра Лекслорта в Карґат.",
    P = "Де гоблін???",
    C = "Я повинен передати це їй; їй вдалося вийти з чергової складної ситуації! Ці звіти виявляться неоціненними в наших стосунках з орками Чорної Гори.$B$BOf Звичайно, ви отримаєте винагороду за свою важку працю.",
},

[4984] = {
    en = "The Wildlife Suffers Too",
    T = "Природа Теж Страждає",
    D = "Хоча я мало що міг зробити сам, щоб зупинити Скару, я все ж прийшов до цих земель, щоб спробувати зцілити шкоду, завдану природі. Тварини страждають від чуми, яка продовжує душити ці землі, не в змозі знайти милосердя і спокій. Я прошу тебе продовжити те, що я не зміг тут закінчити.$B$BДля страждаючих тварин немає спасіння, окрім милосердного і швидкого звільнення. Знайди хворих вовків поблизу і умертви їх. Будь ласка, $N, поклади край їхнім стражданням — це точно заспокоїть і мої.",
    O = "Знищте 8 Хворих Вовків, а потім поверніться до Мулґріса Глибокоріччя в Осередку Страждань, Західні Зачумлені Землі.",
    P = "Вовків, заражених чумою, треба знищити, $N.  Хворобу, яку вони переносять, неможливо вилікувати.  Намагався... Намагався, поки сам не піддався чумі.",
    C = "Я... я відчуваю, що душі тих вовків, яких ви знищили, тепер відпочили. Вони — і я — дякуємо вам за милосердне звільнення.$B$BThe вовки не самотні у своїх стражданнях у цьому проклятому місці, $N. Будь ласка, ви мені знову потрібні.",
},

[4985] = {
    en = "The Wildlife Suffers Too",
    T = "Природа Теж Страждає",
    D = "На сході від того місця, де ми зараз, біля початку Східних Зачумлених Земель, колись горді і величні грізлі блукали околицями. Чума, випущена Скарою, знищила і цих звірів. Вони бродять по землі, мучені заціпенінням м’язів і гниттям їхнього хутра та плоті.$B$BЯ прошу тебе покласти край їхнім стражданням. Єдиним ліком для їхньої муки є швидка смерть, яку ти мусиш завдати своєю рукою.",
    O = "Знищте 8 Хворих Грізлі, а потім поверніться до Мулґріса Глибокоріччя в Осередку Страждань, Західні Зачумлені Землі.",
    P = "Я чую твої кроки, $N. Моє бачення зникло, але я все ще можу відчувати речі навколо себе. Ви покінчили з стражданнями хворих грізлі?",
    C = "",
},

[4986] = {
    en = "Glyphed Oaken Branch",
    T = "Гліфована Дубова Гілка",
    D = "Млява рука тауренського друїда стискає напрочуд здорову на вигляд дубову гілку. Оглядаючи гілку, ви помічаєте гліфи друїдської природи, вирізані на корі.$B$BКоли ви берете гілку в руки, відчуваєте, що вона тепла на дотик, більше, ніж мала б бути. Образ дерева Тельдрассіл спливає у вашій свідомості — зокрема Дарнассус — і слова «Кенарійський Круг» крутяться на язиці. Схоже, що вказівка, куди віднести гілку, була вкладена в неї саму.",
    O = "Згідно з магією, зачарованою в Гліфованій Дубовій Гілці, її доставка до Кенарійського Кругу в Дарнассусі — це наступний крок, якого прагнув тауренський друїд. Зверніться до одного з друїдів там за допомогою.",
    P = "Від імені Кола Кенаріону я вітаю вас у цьому анклаві, $C.  Яке тобі до нас діло?",
    C = "Це... це досить дивно. Цей друїд — не менш цей друїд-таурен — довірив вам багато цінної інформації про масштаби чуми Бича. Я здивований, що таурен надав би $R таку інформацію, і при цьому вільно, якщо те, що ви говорите, правда. Ми добре використаємо це, я вам обіцяю. Можливо, таурени не відпали так далеко від Кенарія, як Фандрал думав би...$B$BErm, у будь-якому випадку, будь ласка - прийміть це як знак подяки від Кола Кенаріу.",
},

[4987] = {
    en = "Glyphed Oaken Branch",
    T = "Гліфована Дубова Гілка",
    D = "Млява рука тауренського друїда стискає напрочуд здорову на вигляд дубову гілку. Оглядаючи гілку, ви помічаєте гліфи друїдської природи, вирізані на корі.$B$BКоли ви берете гілку в руки, відчуваєте, що вона тепла на дотик, більше, ніж мала б бути. Образ Громового Бескиду в Мулґорі спливає у вашій свідомості — зокрема Вершина Старійшин — і слова «Кенарійський Круг» крутяться на язиці. Схоже, що вказівка, куди віднести гілку, була вкладена в неї саму.",
    O = "Згідно з магією, зачарованою в Гліфованій Дубовій Гілці, її доставка до Кенарійського Кругу в Громовому Бескиді — це наступний крок, якого прагнув тауренський друїд. Зверніться до одного з друїдів там за допомогою.",
    P = "Від імені Кола Кенаріону я вітаю вас у цьому анклаві, $C. Яке тобі до нас діло?",
    C = "Кажете, це від Малгріса? Ми чули, що він намагався служити істотам, які страждають у Чумних землях, але це дуже несподівано... і дуже сумно. Малгріс... був хорошим другом. Я глибоко оплакуватиму його смерть.$B$BHis Зусилля не пропали дарма завдяки вашій старанності. У цій гілці зберігається багато відомостей про чуму, яку Бич поширює на землі. Ми будемо його старанно вивчати. Що стосується вас, будь ласка, прийміть це. Це найменше, що ми можемо зробити для ваших благородних зусиль.",
},

[5001] = {
    en = "Bijou's Belongings",
    T = "Речі Біжу",
    D = "Зазвичай я не маю справ із $r, але здається, що я опинився між тролем і твердим місцем. Розумієш, моя місія тут має надзвичайну важливість для Орди. Однак інформація, яку я виявив, стосується також добробуту Альянсу. Повір мені, я не симпатизую Альянсу, але загроза Чорної Скелі більша, ніж просто купа орків.$B$BТи допоможеш мені, знайшовши мої речі, а я допоможу тобі інформацією, яка може бути корисною для твого народу.$B$BДомовились?",
    O = "Знайдіть Речі Біжу і поверніть їх їй. Удачі!",
    P = "Пощастило?",
    C = "Ну я буду! Де вони були??",
},

[5002] = {
    en = "Message to Maxwell",
    T = "Повідомлення Максвеллу",
    D = "Я — гоблін, який тримає своє слово, $r. Слухай уважно:$B$BЦі орки використовуються переважно як в’ючні тварини і гарматне м’ясо для чорного драконячого роду!$B$BЇхній справжній лідер — не хто інший, як Нефаріан, нащадок Смертокрила. Я також виявив місце перебування підлеглих Нефаріана в цій частині цитаделі.$B$BВіднеси цю мапу до Маршала Максвелла в Палаючих Степах. На ній позначені місця цих лиходіїв для легкої ідентифікації.",
    O = "Вирушайте до Палаючих Степів і передайте Інформацію Біжу Маршалу Максвеллу.",
    P = "Ах, $N. Пройшло багато часу.",
    C = "Це збігається з більшою частиною того, що ми вже знали. Незважаючи на це, це цікава і досить сумна інформація.$B$BThe позначки на цій карті стануть цінними для зменшення загрози Чорної гірки.",
},

[5021] = {
    en = "Better Late Than Never",
    T = "Краще Пізно, Ніж Ніколи",
    D = "«Посилку потрібно доставити… доставити, перш ніж я застрягну тут!»$B$BКрики наляканої жінки звучать майже як шепіт, що лунає будинком. У кутку нагорі, скорчившись, стоїть привид жінки. Вона, здається, не повністю усвідомлює своє оточення і лише смутно помічає тебе.$B$B«Ти тут, щоб доставити мою посилку? Будь ласка, поки не стало гірше! Я збиралася виїхати звідси. Вона має бути біля мого коня… чи я запізнилася?»",
    O = "Бурмотіння примарної жінки вказувало, що їй потрібно доставити посилку. Вона стверджувала, що та була там, де її кінь. Де саме кінь чи куди потрібно доставити посилку — привид залишається незрозумілим.",
    P = "",
    C = "Пакунок у сараї, який ви могли б не помітити, тепер виділяється серед занепаду та руїн. Можливо, це той, про який кричав привид Дженіс Фелстоун...",
},

[5022] = {
    en = "Better Late Than Never",
    T = "Краще Пізно, Ніж Ніколи",
    D = "Ви піднімаєте посилку, витираючи невеликий шар пилу і бруду, що осів на ній. Вона адресована поспішним почерком до Емми Фелстоун зі Штормовію; доставка посилки датована більш ніж чотири роки тому.$B$BХоча неясно, чи жива Емма Фелстоун, загальновідомо, що міська ратуша Штормовію веде облік населення міста. Це займаються Королівські Фактори перепису Штормовію.",
    O = "Перевірте у Королівських Факторів Штормовію, щоб дізнатися, де перебуває Емма Фелстоун. Зазвичай у ратуші є офіцер перепису.",
    P = "Ласкаво просимо до офісу перепису Штормовія. Якщо вам потрібна інформація про наше населення, я можу вам допомогти.",
    C = "Кажете, пакет для Емми Фелстоун? Остання відома адреса — Штормовій, чотири роки тому? Дозвольте мені поглянути...$B$BAccording Наскільки ми знаємо, приблизно чотири роки тому в місті була Емма Фелстоун. Ну, я повинен сказати, можливо, цей перепис, про який я говорю, зроблений п’ять років тому, і я не маю звіту про те, щоб вона залишила місто. Але це не означає, що вона все ще тут.$B$BWait секунду... цей пакунок не міг бути для старої Емми, чи не так?",
},

[5023] = {
    en = "Better Late Than Never",
    T = "Краще Пізно, Ніж Ніколи",
    D = "Ви піднімаєте посилку, витираючи невеликий шар пилу і бруду, що осів на ній. Вона адресована поспішним почерком до Джеремайї Фелстоуна з Лордерону; доставка посилки датована більш ніж чотири роки тому.$B$BХоча неясно, чи живий Джеремайя Фелстоун, загальновідомо, що Підмістя, раніше відоме як Лордерон, веде облік населення міста. Це займаються Королівські Наглядачі перепису Підмістя.",
    O = "Перевірте у Королівських Наглядачів Підмістя, щоб дізнатися, де перебуває Джеремайя Фелстоун. Зазвичай офіцер перепису знаходиться біля реєстрації гільдій і табардів.",
    P = "Ви тут, щоб звернутися за допомогою до перепису Підміського населення чи просто запитати мене, чи помер хтось, кого ви знали? Мене часто про це запитують.",
    C = "Пакунок для Джеремії Фелстоуна з його останньою відомою адресою як Лордерон... Я зможу вам допомогти.$B$BJeremiah Фелстоун був у місті до епідемії чуми. Ну, я мав би сказати, колишній Джеремія Фелстоун — деякі з Покинутих змінили свої прізвища, щоб позбутися свого колишнього вигляду. Цей випадок не є винятком; колишній Джеремія Фелстоун тепер відомий як Джеремія Пейсон.$B$BWait хвилинку... хіба він не продавець тарганів?",
},

