[5096] = {
    en = "Scarlet Diversions",
    T = "Відволікання Хрестоносців",
    D = "Перед Андоґалом ми мусимо впоратися із загрозою Червоного Хрестового Походу з Гартґлена. Вони розбили табір між Полем Фелстоуна і Сльозами Далсона, змушуючи нас ризикувати конфліктом одночасно з Плеттю і Хрестоносцями.$B$BМій план — змусити їх боротися один з одним, відправивши тебе знищити їхній командний намет; скористайся пляшкою з вогнем із цієї скрині з запалювальними засобами. Після знищення намету встанови там прапор Плеті. З трохи удачі, вони ігноруватимуть нас і зосередяться на помсті Плеті.",
    O = "Вирушай до базового табору Червоного Хрестового Походу між Полем Фелстоуна і Сльозами Далсона і знищ їхній командний намет.$B$BВстанови прапор Плеті в таборі, а потім повернися до Верховного Виконавця Деррінґтона на Бастіон, Західні Зачумлені Землі.",
    P = "Знищіть командний намет і встановіть у таборі прапор Плечі",
    C = "Прекрасно виконано, $N. Ваша атака на Багряний хрестовий похід виграє нам час. Я послав одного зі своїх найкращих розвідників стежити за табором і переконатися, що сили хрестового походу, які прибули на посилення позицій, захоплять наживку.$B$BWith тиск на нас зменшився, тепер ми нарешті маємо можливість ризикнути здійснити місію в Андорал, до того ж важливу. Я дуже хотів би, щоб ви виконали й цей, виходячи з ваших успіхів на сьогоднішній день.",
},

[5097] = {
    en = "All Along the Watchtowers",
    T = "Вздовж сторожових веж",
    D = "За допомогою магічного пристрою, відомого як смолоскип-маяк, ми можемо позначати цілі на наш вибір для майбутніх дій наших військ. Ми вважаємо, що Плеть використовує сторожові вежі Андоґалу для контролю за рухом своїх військ.$B$BТвоя місія: прорвати оборону Андоґалу і встановити маяки на всіх чотирьох сторожових вежах. Тобі потрібно бути у дверному отворі кожної вежі, щоб успішно встановити маяк; він позначить вежу. У смолоскипі-маяку лише п’ять зарядів, тож використовуй їх розумно!",
    O = "Використовуй Смолоскип-Маяк, щоб позначити кожну вежу в Андоґалі; тобі потрібно стояти у дверному отворі вежі, щоб успішно її позначити.$B$BКоли всі чотири вежі будуть позначені, поверни Смолоскип-Маяк до Командира Ашлама Велорфіста в Таборі Холодовітрів, Західні Зачумлені Землі.",
    P = "Щойно вежі буде позначено, вони стануть головними цілями для нашої атаки на Андорал. Я підозрюю, що коли ми нейтралізуємо вежі, з’явиться головна загроза Андорхалу. З цього моменту ми будемо вести пряму боротьбу за контроль над містом!$B$Byou повернулися, щоб повідомити про успіх, так? Не забудьте також про маяковий факел; ми повинні контролювати нашу техніку.",
    C = "Мої священики повідомляють, що наші радіомаяки вловлюють надзвичайно сильні сигнали на всіх чотирьох вежах! Смію це сказати, але я вважаю, що ви виконали ще одну місію з повним і повним успіхом! Знову гарно зіграно, $N!$B$BWith башти позначені, ми готові до атаки. Настав час вести бій з Бичом!",
},

[5098] = {
    en = "All Along the Watchtowers",
    T = "Вздовж сторожових веж",
    D = "За допомогою магічного пристрою, відомого як смолоскип-маяк, ми можемо позначати цілі на наш вибір для майбутніх дій наших військ. Ми вважаємо, що Плеть використовує сторожові вежі Андоґалу для контролю за рухом своїх військ.$B$BТвоя місія: прорвати оборону Андоґалу і встановити маяки на всіх чотирьох сторожових вежах. Тобі потрібно бути у дверному отворі кожної вежі, щоб успішно встановити маяк; він позначить вежу. У смолоскипі-маяку лише п’ять зарядів, тож використовуй їх розумно!",
    O = "Використовуй Смолоскип-Маяк, щоб позначити кожну вежу в Андоґалі; тобі потрібно стояти у дверному отворі вежі, щоб успішно її позначити.$B$BКоли всі чотири вежі будуть позначені, поверни Смолоскип-Маяк до Верховного Виконавця Деррінґтона на Бастіон, Західні Зачумлені Землі.",
    P = "Щойно вежі буде позначено, вони стануть головними цілями для нашої атаки на Андорал. Я підозрюю, що коли ми нейтралізуємо вежі, з’явиться головна загроза Андорхалу. З цього моменту ми будемо вести пряму боротьбу за контроль над містом!$B$BYou повернулися, щоб повідомити про успіх, так? Не забудьте також про маяковий факел; ми повинні контролювати нашу техніку.",
    C = "Мої священики повідомляють, що наші радіомаяки вловлюють надзвичайно сильні сигнали на всіх чотирьох вежах! Смію це сказати, але я вважаю, що ви виконали ще одну місію з повним і повним успіхом! Знову гарно зіграно, $N!$B$BWith башти позначені, ми готові до атаки. Настав час вести бій з Бичом!",
},

[5101] = {
    en = "",
    T = "Остаточний Тестовий Квест Лі... Прокляття!",
    D = "Ба! Що це, думаєш, якийсь тестовий квест? Я навіть припускаю, що в ньому є помилки!$B$BЯкщо ти думаєш, що мій квест буде легким, то тебе чекає сюрприз!$B$BУбий мені десять овець (1933) і не повертайся, поки не зробиш цього!",
    O = "Убий 6 овець для Бенні і потім тікай щосили!$B$B$B$B$BЖартую... щодо втечі.",
    P = "",
    C = "",
},

[5102] = {
    en = "General Drakkisath's Demise",
    T = "Загибель Генерала Драккісата",
    D = "Ми боремося з цими звірами на двох фронтах: із нашої столиці Штормовію ми воюємо зсередини назовні, а тут, у Палаючих Степах, ми несемо битву до їхнього порогу. Ми мусимо бути пильними, $N. Ніхто не має бути помилуваний від нашого гніву, як ніхто з наших не був помилуваний, коли вони нападали на наші домівки і сім’ї.$B$BЗнайди цього Генерала Драккісата і знищ його!$B$BЗавдання, звісно, не буде простим, але нагорода буде щедрою.",
    O = "Вирушай до Чорноскельного Шпиля і знищ Генерала Драккісата. Повернися до Маршала Максвелла, коли завдання буде виконано.",
    P = "Чи зроблено?",
    C = "Звичайно, наступним ударом ми вдаримо по їхніх володарів-драконів. Браво, відважний воїне Альянсу! Справді молодець.",
},

[5103] = {
    en = "Hot Fiery Death",
    T = "Гаряча вогняна смерть",
    D = "Від цього людини залишилися лише обгорілі кістки. Він, здається, помер, намагаючись дотягнутися до того, що шукав — ненадягнутих пластинчастих рукавиць.$B$BМожливо, тобі варто схопити рукавиці і вибратися з вогню?",
    O = "Хтось у цьому світі має знати, що робити з цими рукавицями. Удачі!",
    P = "",
    C = "Що за...",
},

[5121] = {
    en = "High Chief Winterfall",
    T = "Верховний Вождь Зимопадів",
    D = "Ми все ще мало знаємо про те, чому фурболги вживають цю дивну субстанцію, але я вважаю, що краще зупинити це, поки ситуація не вийшла з-під контролю.$B$BФурболги Зимопадів зазвичай не є агресивним плем’ям, і ця зміна в їхній поведінці змушує мене думати, що вони діють за наказом свого вождя. Ми, ймовірно, не зможемо скасувати шкоду, яка вже була завдана, але я вважаю, що якщо їхнього лідера знищити, ситуація не погіршиться.$B$BВирушай на схід до Села Зимопадів.",
    O = "Донова Сноуден у Зимоключі хоче, щоб ти переміг Верховного Вождя Зимопадів.",
    P = "Можливо, ви дізнаєтесь більше у Winterfall Village, $N.",
    C = "Дуже дякую, $N. Я сподіваюся повернутися до навчання, не хвилюючись, що мене чекає засідка. Будь ласка, прийміть це як нагороду.",
},

[5122] = {
    en = "The Medallion of Faith",
    T = "Медальйон Віри",
    D = "",
    O = "",
    P = "Сила цієї каплиці дає мені сили протистояти зіпсуванню мого серця. Якщо я покину це, я стану лицарем смерті. Але є медальйон, медальйон віри, який додасть мені сили, щоб піти.$B$BPlease, $N, візьміть медальйон. Його охороняє Малор Завзятий, божевільний член Багряного Братства, який живе глибоко в Багряному бастіоні в західному Стратхольмі.",
    C = "Ви знайшли медальйон! Тепер я зможу покинути каплицю та виконати свій обов’язок.$B$BThat обов’язок — убити звіра, який допоміг зіпсувати мене та багатьох моїх братів і сестер, барона Рівендера!",
},

[5123] = {
    en = "The Final Piece",
    T = "Остання частинка",
    D = "Щоденник, який ти знайшов на верховному вожді, виглядає об’ємним, але, проглянувши кілька сторінок, ти розумієш, що не можеш прочитати текст. Написи настільки грубі та погано сформовані, що ти не впевнений, чи хтось узагалі зміг би їх прочитати.$B$BАле, можливо, Донова зможе сказати тобі, що там написано...",
    O = "Принеси Грубозаписаний Щоденник до Донови Сноуден у Зимоключі.",
    P = "Що це таке, $N?",
    C = "Цікаво, що все це означає... Нічого не можу зрозуміти...",
},

[5124] = {
    en = "Fiery Plate Gauntlets",
    T = "Вогняні Пластинчасті Рукавиці",
    D = "На бороду Тауріссана!$B$BЗвідки ти їх узяв?$B$BЩо важливіше, чи готовий ти з ними розлучитися? Звісно, я заплачу тобі за такий благородний жест.$B$BОсь що я тобі пропоную, $N. Якщо ти віддаси мені ці ненадягнуті рукавиці, я навчу тебе, як зробити власну пару. Усе, що тобі потрібно, — зібрати для мене компоненти, щоб я міг точно визначити рецепт.$B$BДомовились?$B$BОсь список того, що мені потрібно, я сам забезпечу незачарований торій, оскільки ти надаєш рукавиці.",
    O = "Принеси Маліфусу Темномолоту 6 Зачарованих Торійових Злитків, 2 Сутності Вогню і 4 Зіркові Рубіни. Також тобі потрібно здати Ненадягнуті Пластинчасті Рукавиці.",
    P = "Час – це гроші, $N, і в мене його небагато.",
    C = "Як і обіцяв, $N, ось твій рецепт! Я також збираюся додати щось додаткове за всю вашу наполегливу працю та самовідданість. Що я буду з цими взагалі робити???",
},

[5125] = {
    en = "Aurius' Reckoning",
    T = "Розплата Ауріуса",
    D = "",
    O = "",
    P = "",
    C = "$N, я вмираю... але моя душа врятована.  За це я вам зобов’язаний більше, ніж можна сказати словами.  Будь ласка, візьми це... і борися далі, відважний $C!",
},

[5126] = {
    en = "Lorax's Tale",
    T = "Оповідь Лоракса",
    D = "Сатир ходить туди-сюди і розмовляє сам із собою. Бажаєш його розпитати?",
    O = "Поговори з Лораксом. Послухай, що він має сказати.",
    P = "",
    C = "Послухайте казку Лоракса",
},

[5127] = {
    en = "The Demon Forge",
    T = "Демонічна кузня",
    D = "Лоракс укладає угоди, він не приймає їх від нікчемних смертних.$B$BОднак угоду я з тобою укладу... візьми цей спис, він наповнений могутньою енергією скверни. Коли знайдеш Ґоралука Ковадлоколота, убий його і проший цим списом його вмираюче серце. Його душа була продана, і його душа буде моєю. Поверни спис і поверни нагрудник, який вкрав цей злодій, і я навчу тебе того, що він мав дізнатися.",
    O = "Вирушай до Чорноскельного Шпиля і знайди Ґоралука Ковадлоколота. Убий його, а потім застосуй Кривавий Спис на його трупі. Після того, як його душу висмокчуть, спис стане Заплямованим Душею.$B$BТакож ти мусиш знайти Некутий Нагрудник із Рунним Покриттям.$B$BПоверни і Заплямований Душею Спис, і Некутий Нагрудник із Рунним Покриттям до Лоракса в Зимоключі.",
    P = "Не спокушайте...",
    C = "Наш договір ви не порушили. Душу я забрав. Нагорода, яку я зроблю.",
},

[5128] = {
    en = "Words of the High Chief",
    T = "Слова Верховного Вождя",
    D = "Зимопади більше не становлять для мене загрози, але якщо ти все ще хочеш дізнатися, що змушувало фурболгів створювати і вживати цю дивну вогняну воду, я вважаю, що тобі слід звернутися до Келека Скайкіпера.$B$BВін є частиною групи, відомої як Смарагдове Коло, друїдів, які віддані своїй роботі в Сквернолісі, зцілюючи землю від псування.$B$BКелек має великий досвід із фурболгами в Сквернолісі і, можливо, зможе розповісти більше про цей щоденник.$B$BЩе раз дякую, $N.",
    O = "Візьми Грубозаписаний Щоденник до Келека Скайкіпера в південному Сквернолісі.",
    P = "Смарагдове коло дружнє до всіх, $R. Що я можу для вас зробити?",
    C = "Так, якщо ви дозволите мені розглянути це деякий час, я можу перекласти це для вас.$B$B<Келек гортає сторінки.>$B$BWhen Я можу переглянути це повністю, я надішлю вам повідомлення.$B$BThank за те, що ви поділилися цим зі мною, $N. Дуже мало відомо про фурболга Winterfall.",
},

[5141] = {
    en = "Dragonscale Leatherworking",
    T = "Робота зі шкірою драконячої луски",
    D = "Робота зі шкірою драконячої луски — нелегка справа, але вона надзвичайно винагороджується. Я навчу тебе, як виготовляти цю чудову кольчугу, але лише за певних умов.$B$BОбравши цей шлях, ти погоджуєшся ніколи не вивчати елементальну чи племінну роботу зі шкірою; є місце лише для одного з трьох на вершині ремесла. Крім того, мені потрібні зразки твоєї найкращої роботи зі скорпідною бронею. І нарешті, мені потрібен доказ твоєї здатності добувати основний матеріал торгівлі: луску драконів.",
    O = "Принеси 2 Міцні Скорпідні Нагрудники, 2 Міцні Скорпідні Рукавиці і 10 Зношених Драконячих Лусок до Пітера Ґалена в Азшарі.$B$BВиконання цього квесту надасть тобі доступ до мистецтва роботи зі шкірою драконячої луски.$B$BВиконання цього квесту унеможливить вивчення Елементальної Роботи зі Шкірою та Племінної Роботи зі Шкірою; переконайся, що це той шлях, який ти хочеш обрати, перш ніж це зробити.",
    P = "Якщо ви готові прийняти постійне рішення, ставши шкіряним майстром із драконячої луски, тоді я готовий взяти вас учні. Просто принеси мені те, що я просив, і ми почнемо твою освіту.",
    C = "Я передам це вам - потрібна сильна воля, щоб прийняти постійне рішення, як ви щойно зробили. Запевняю вас, шкіряна обробка драконячої луски стане для вас прибутковим і корисним шляхом.$B$BTo навчайтеся мистецтву на майбутнє, просто поговоріть зі мною, і я надам доступ до будь-яких знань, які ви ще маєте зробити своїми.",
},

[5142] = {
    en = "Little Pamela",
    T = "Маленька Памела",
    D = "Так багато з нас загинуло в битві за Дарроушир. Так багато загинуло... і ще гірше.$B$BКоли битва почалася, я заховав свою племінницю Памелу, і я не знаю, що з нею сталося. Я лише блукаючий дух, але моє серце все ще прагне дізнатися про долю Памели.$B$BБудь ласка, добрий $c. Чи підеш ти до Дарроушира і пошукаєш її? Це на схід, за В’януванням Ґаррона.",
    O = "Знайди Памелу Редпат.",
    P = "",
    C = "Здорові були.  Я Памела, як тебе звати?",
},

[5143] = {
    en = "Tribal Leatherworking",
    T = "Племінна Робота зі Шкірою",
    D = "Щоб вивчити племінну роботу зі шкірою, потрібно зрозуміти, наскільки первозданною є природа; я знаю, що ти вже оволодів мистецтвом створення дикого шкіряного обладунку, і я готовий завершити твоє навчання.$B$BЗнай, $c: обравши цей шлях, ти погоджуєшся ніколи не вивчати роботу зі шкірою драконячої луски чи елементальну роботу зі шкірою; є місце лише для одного з трьох мистецтв. Крім того, принеси мені найкращі зразки твого дикого шкіряного обладунку. Звідти ми почнемо твоє оволодіння.",
    O = "Принеси Дикий Шкіряний Жилет і Дикий Шкіряний Шолом до Кариссії Мунхантер у Фераласі.$B$BВиконання цього квесту надасть тобі доступ до мистецтва Племінної Роботи зі Шкірою.$B$BВиконання цього квесту унеможливить вивчення Роботи зі Шкірою Драконячої Луски та Елементальної Роботи зі Шкірою; переконайся, що це той шлях, який ти хочеш обрати, перш ніж це зробити.",
    P = "Природа — це сила, яку потрібно заспокоїти, перш ніж ви сподіваєтесь навчитися втілювати її волю у свій шкіряний одяг. Принесіть мені свою пропозицію цій силі, і я подбаю про те, щоб вас почули.",
    C = "Ви зробили свої найкращі пропозиції, і незабаром природа дозволить вам підпорядкувати її своїй волі. Щойно я закінчу своє опікування, ваша робота стане самостійною силою природи.$B$BTo навчайтеся мистецтву для майбутнього, просто поговоріть зі мною, і я надам доступ до будь-яких знань, які ви ще маєте передати як свої.",
},

[5144] = {
    en = "Elemental Leatherworking",
    T = "Елементальна Робота зі Шкірою",
    D = "Елементальна робота зі шкірою — це те, що я знаю, і якщо ти готовий відкрити свій розум для більших сил матерії, я поділюся з тобою всім, що можна вивчити.$B$BЗнай, $c: обравши цей шлях, ти погоджуєшся ніколи не вивчати роботу зі шкірою драконячої луски чи племінну роботу зі шкірою; є місце лише для одного з трьох мистецтв. Крім того, мені потрібен достатній доказ того, що ти в гармонії з елементами природи; для цього принеси мені найчистіші сутності вогню, води, землі та вітру.",
    O = "Принеси 4 Серця Вогню, 4 Кулі Води, 4 Ядра Землі і 4 Подихи Вітру до Сари Таннер у Палаючій Ущелині.$B$BВиконання цього квесту надасть тобі доступ до мистецтва Елементальної Роботи зі Шкірою.$B$BВиконання цього квесту унеможливить вивчення Роботи зі Шкірою Драконячої Луски та Племінної Роботи зі Шкірою; переконайся, що це той шлях, який ти хочеш обрати, перш ніж це зробити.",
    P = "Виготовлення такого роду шкіряних обладунків вимагає терпіння та самовіддачі. Після того, як ви зібралися зі стихіями, ви вже не відвернетеся від них. Принесіть мені докази вашої гідності, і ми почнемо.",
    C = "Ви склали свій жереб, і стихії приймають вас. Щойно я закінчу своє опікування, ти матимеш волю створювати найкращий шкіряний одяг.$B$BTo тренуйся в мистецтві на майбутнє, просто поговори зі мною, і я надам доступ до будь-яких знань, які тобі ще належить передати як свої.",
},

[5145] = {
    en = "Dragonscale Leatherworking",
    T = "Робота зі шкірою драконячої луски",
    D = "Робота зі шкірою драконячої луски — нелегка справа, але вона надзвичайно винагороджується. Я навчу тебе, як виготовляти цю чудову кольчугу, але лише за певних умов.$B$BОбравши цей шлях, ти погоджуєшся ніколи не вивчати елементальну чи племінну роботу зі шкірою; є місце лише для одного з трьох на вершині ремесла. Крім того, мені потрібні зразки твоєї найкращої роботи зі скорпідною бронею. І нарешті, мені потрібен доказ твоєї здатності добувати основний матеріал торгівлі: луску драконів.",
    O = "Принеси 2 Міцні Скорпідні Нагрудники, 2 Міцні Скорпідні Рукавиці і 10 Зношених Драконячих Лусок до Торкафа Драконяче Око в Безплідних Землях.$B$BВиконання цього квесту надасть тобі доступ до мистецтва роботи зі шкірою драконячої луски.$B$BВиконання цього квесту унеможливить вивчення Елементальної Роботи зі Шкірою та Племінної Роботи зі Шкірою; переконайся, що це той шлях, який ти хочеш обрати, перш ніж це зробити.",
    P = "Якщо ви готові прийняти постійне рішення, ставши шкіряним майстром із драконячої луски, тоді я готовий взяти вас учні. Просто принеси мені те, що я просив, і ми почнемо твою освіту.",
    C = "Я передам це вам - потрібна сильна воля, щоб прийняти постійне рішення, як ви щойно зробили. Запевняю вас, шкіряна обробка драконячої луски стане для вас прибутковим і корисним шляхом.$B$BTo навчайтеся мистецтву на майбутнє, просто поговоріть зі мною, і я надам доступ до будь-яких знань, які ви ще маєте зробити своїми.",
},

[5146] = {
    en = "Elemental Leatherworking",
    T = "Елементальна Робота зі Шкірою",
    D = "Елементальна робота зі шкірою — це те, що я знаю, і якщо ти готовий відкрити свій розум для більших сил матерії, я поділюся з тобою всім, що можна вивчити.$B$BЗнай, $c: обравши цей шлях, ти погоджуєшся ніколи не вивчати роботу зі шкірою драконячої луски чи племінну роботу зі шкірою; є місце лише для одного з трьох мистецтв. Крім того, мені потрібен достатній доказ того, що ти в гармонії з елементами природи; для цього принеси мені найчистіші сутності вогню, води, землі та вітру.",
    O = "Принеси 4 Серця Вогню, 4 Кулі Води, 4 Ядра Землі і 4 Подихи Вітру до Брумна Зимового Копита в Горах Араті.$B$BВиконання цього квесту надасть тобі доступ до мистецтва Елементальної Роботи зі Шкірою.$B$BВиконання цього квесту унеможливить вивчення Роботи зі Шкірою Драконячої Луски та Племінної Роботи зі Шкірою; переконайся, що це той шлях, який ти хочеш обрати, перш ніж це зробити.",
    P = "Виготовлення такого роду шкіряних обладунків вимагає терпіння та відданості. Після того, як ви зібралися зі стихіями, ви вже не відвернетеся від них. Принесіть мені докази вашої гідності, і ми почнемо.",
    C = "Ви склали свій жереб, і стихії приймають вас. Щойно я закінчу своє опікування, ти матимеш волю створювати найкращий шкіряний одяг.$B$BTo тренуйся в мистецтві на майбутнє, просто поговори зі мною, і я надам доступ до будь-яких знань, які тобі ще належить передати як свої.",
},

[5147] = {
    en = "Wanted - Arnak Grimtotem",
    T = "Розшукується — Арнак Ґрімтотем",
    D = "Розшукується: Арнак Ґрімтотем$B$BАрнак, вигнанець, розшукується за тяжкі злочини вбивства та викрадення. Щедрі нагороди будуть надані тим, хто досить хоробрий, щоб привести цього злочинця до правосуддя.$B$BОстаннє, що бачили Арнака, було на скелях біля Темнохмарного Піку. Покажи доказ свого вчинку Кліффвочеру Лонґгорну на Посту Вільного Вітру, щоб отримати нагороду.",
    O = "Убий Арнака Ґрімтотема і принеси доказ свого вчинку Кліффвочеру Лонґгорну на Посту Вільного Вітру.",
    P = "У вас є якісь новини про той вбивчий Арнак Гримтотем?",
    C = "ха! Ну, це чудова новина! Я почав думати, що він ніколи не постане перед судом!$B$BHere ти, $N... і дякую. Звістка про погані вчинки Анрака закипіла мою кров!",
},

[5148] = {
    en = "Tribal Leatherworking",
    T = "Племінна Робота зі Шкірою",
    D = "Щоб вивчити племінну роботу зі шкірою, потрібно зрозуміти, наскільки первозданною є природа; я знаю, що ти вже оволодів мистецтвом створення дикого шкіряного обладунку, і я готовий завершити твоє навчання.$B$BЗнай, $c: обравши цей шлях, ти погоджуєшся ніколи не вивчати роботу зі шкірою драконячої луски чи елементальну роботу зі шкірою; є місце лише для одного з трьох мистецтв. Крім того, принеси мені найкращі зразки твого дикого шкіряного обладунку. Звідти ми почнемо твоє оволодіння.",
    O = "Принеси Дикий Шкіряний Жилет і Дикий Шкіряний Шолом до Се’Джіба в Долині Тернового Шипа.$B$BВиконання цього квесту надасть тобі доступ до мистецтва Племінної Роботи зі Шкірою.$B$BВиконання цього квесту унеможливить вивчення Роботи зі Шкірою Драконячої Луски та Елементальної Роботи зі Шкірою; переконайся, що це той шлях, який ти хочеш обрати, перш ніж це зробити.",
    P = "Природа — це сила, яку потрібно заспокоїти, перш ніж ви сподіваєтесь навчитися втілювати її волю у свій шкіряний одяг. Принесіть мені свою пропозицію цій силі, і я подбаю про те, щоб вас почули.",
    C = "Ви зробили свої найкращі пропозиції, і незабаром природа дозволить вам підпорядкувати її своїй волі. Щойно я закінчу своє опікування, ваша робота стане самостійною силою природи.$B$BTo навчайтеся мистецтву для майбутнього, просто поговоріть зі мною, і я надам доступ до будь-яких знань, які ви ще маєте передати як свої.",
},

[5149] = {
    en = "Pamela's Doll",
    T = "Лялька Памели",
    D = "Моя тітонька Марлен сказала мені залишатися тут, у нашому будинку, бо мій тато мусив піти воювати. Мій тато — найхоробріший чоловік у цілому світі!$B$BАле я вже довго тут, і він не прийшов за мною. Іноді погані люди приходять і шепочуть мені, і я хочу, щоб тато їх прогнав, але його немає!$B$BА іноді, коли темніє, я хочу погратися зі своєю лялькою, але не можу, бо залишила її в місті.$B$BЧи знайдеш ти мою ляльку для мене?",
    O = "Знайди ляльку Памели.",
    P = "Ти знайшов мою ляльку?",
    C = "Ви знайшли його! Ти знайшов мою ляльку! О, дякую!",
},

[5150] = {
    en = "Dadanga is Hungry!",
    T = "Даданґа голодна!",
    D = "",
    O = "",
    P = "Даданга дивиться на вас, коли ви підходите до неї. Здається, вона на щось сподівається... $B$BShe, мабуть, голодний! $B$BThere, мабуть, у кратері росте щось таке, що стане ідеальною закускою для великої травоїдної тварини. Даданга — велика дівчина; Що б ви їй не принесли, цього повинно бути багато!",
    C = "Поклавши паростки перед нею, Даданга, здається, задоволений.$B$BShe штовхає до вас маленький пакунок у коричневій упаковці в обмін на частування!",
},

[5151] = {
    en = "Hypercapacitor Gizmo",
    T = "Гіперконденсатор",
    D = "Я єдиний, хто вижив після нападу кентаврів на наш караван! Рідкісна, але могутня пантера охороняє мій найкращий пристрій, який висить у неї на шиї. Ха! Навіть кентаври тремтять перед цією лютою звіриною!$B$BОсь ключ від клітки. Вони забрали все там, але залишили її в спокої. Убий цю звірину і поверни мій гіперконденсатор, і я винагороджу тебе.$B$BЗруйнований караван розташований трохи на північ звідси.",
    O = "Убий звіра і принеси Гіперконденсатор і Ключ від Клітки Пантери до Візло Берінґшінера.",
    P = "У вас є мій гіперконденсатор?",
    C = "Мій гіперконденсатор! Це займе мене деякий час, поки я не зрозумію, що це робить...",
},

[5152] = {
    en = "Auntie Marlene",
    T = "Тітонька Марлен",
    D = "Ох, як мені самотньо! Де моя сім’я? Тітонька Марлен сказала мені залишатися тут, але потім вона пішла і не повернулася! А мій тато... ти його бачив?$B$BМоже, тітонька Марлен знає, де він. Вона живе біля Андоґалу, у будинку на півдні. Здається, вона казала, що він на пагорбі...$B$BБудь ласка, $N. Ти мій новий друг! Чи поговориш із моєю тітонькою за мене?",
    O = "Поговори з Марлен на південь від Руїн Андоґалу.",
    P = "",
    C = "Ти бачив Памелу? як вона Вона жива?? О ні! Бідна Памела! Вона була такою маленькою і такою щасливою дитиною...$B$BShe не знає, що сталося з її батьком, чи не так? Мій брат, Джозеф?$B$BNo... вона не могла зрозуміти, що сталося з Джозефом. І навіть якби вона могла, я не маю серця сказати їй...",
},

[5153] = {
    en = "A Strange Historian",
    T = "Дивний історик",
    D = "Я б хотіла, щоб Джозеф знову був зі своєю донькою, але цього не може бути. Його душу спотворила Плеть, і він став чудовиськом. Ох, він приречений!$B$BАле, можливо, ми зможемо змінити його долю.$B$BПошукай серед могил надворі пам’ятник Джозефа. Його тіла там немає, адже воно було розтоптане і знищене багато років тому, але під пам’ятником є його обручка. Візьми цю каблучку до Хромі... дивної гномки з дуже незвичайними здібностями.$B$BХромі зупинилася в зруйнованій таверні в північно-західному куті Андоґалу.",
    O = "Принеси Обручку Джозефа до Хромі.",
    P = "У вашому візиті є щось актуальне. Ви ж не з майбутнього?",
    C = "Що це? Обручку? Дайте мені побачити...$B$BAh! Цей перстень колись був на руці великої людини, але в минулому цієї людини багато трагедій.$B$BAre ти тут, щоб допомогти йому? Зараз для нього занадто пізно... але, можливо, ми можемо допомогти йому в минулому!",
},

[5154] = {
    en = "The A$b$bals of Darrowshire",
    T = "Літописи Дарроушира",
    D = "Щоб урятувати Джозефа Редпата, ми спочатку мусимо дізнатися про його минуле. Це можна зробити через Літописи Дарроушира, книгу, що зберігається в ратуші Андоґалу.$B$BПринеси мені цю книгу. Тоді ми зможемо дізнатися про долю Джозефа і, з трохи удачі... змінити її!",
    O = "Принеси Літописи Дарроушира до Хромі в Андоґалі.",
    P = "Ти знайшов книгу, $N?",
    C = "Молодець, ви знайшли це!$B$BDid ви це прочитали? Чи згадується Джозеф Редпат? Якщо так, можливо, ми зможемо його врятувати!$B$BAh. «Аннали Дарроуширу» розповідають дуже тривожну історію. Там сказано, що під час битви Джозеф Редпат був зіпсований і приєднався до лав Бича! Потім він зрадив захисників Дарроуширу.$B$BThat — зла доля. Якщо ми можемо, ми повинні спробувати змінити цю долю, ви не думаєте?",
},

[5155] = {
    en = "Forces of Jaedenar",
    T = "Сили Джеденару",
    D = "Якщо я маю тобі довіряти в цій справі, ти спочатку мусиш довести себе.$B$BЯ мушу знати, що ти ворог Ради Тіней — тих, хто відповідальний за багато зла тут і за кордоном.$B$BВирушай глибше в Сквернолісся. На захід ти побачиш шлях, що веде до Джеденару. Саме там Рада планує з Палаючим Легіоном.$B$BУвійди в глибини одного з їхніх спотворених курганів і знищ їхніх прибічників. Повернися до мене після того, як зробиш це. Тоді я знатиму, що ти справді прагнеш нам допомогти.",
    O = "Увійди в Джеденар і знищ 4 Джеденарських Гончих, 4 Джеденарських Воїнів, 6 Джеденарських Адептів і 6 Джеденарських Культистів, перш ніж повернутися до Ґрети Мосшуф у Сквернолісі.",
    P = "Як проходить ваш бій, $N? Я знаю, що пролиття крові як доказ честі може бути огидним для декого, але ви повинні розуміти, що воно служить двом цілям: ви полегшуєте моє завдання, завдаючи шкоди їх кількості, і ми отримуємо повагу одне до одного, яка зробить нас тільки сильнішими в майбутні часи.$B$BI Сподіваюся, ви розумієте.",
    C = "Добре, $N! Оскільки їхня кількість слабшає, ми можемо ще більше тиснути на них.$B$BHow чи ви вперше відчули їхню силу? Чи були вони такими сильними, як ви думали? Сильніше? Або, можливо, вони взагалі не були для вас викликом. Хіба це не щось?$B$BWe може обговорити подробиці ваших подвигів пізніше. Зараз є інші речі, на які ми повинні зосередитися.",
},

[5156] = {
    en = "Verifying the Corruption",
    T = "Підтвердження псування",
    D = "На півночі, уздовж сходу дороги в місцевості, яку називають Долиною Розколотих Шрамів, є область, де під час останньої великої війни викликали інферналів — кратери все ще позначені, як і самі інфернали.$B$BМені цікаво дві речі. По-перше, чи все ще блукають там ентропічні елементалі? І по-друге, чи кратери все ще наповнені спотвореною, смердючою водою, яка зібралася там багато років тому? Чи допоможеш мені перевірити, $N? Будь обережний, адже інфернали знищують усе на своєму шляху.",
    O = "Знайди і знищ 2 Ентропічних Звірів і 2 Ентропічних Жахів, досліджуючи Долину Розколотих Шрамів. Після перевірки, чи кратери там усе ще наповнені спотвореною водою скверни, повернися до Таронна Червоного Пера в Сквернолісі.",
    P = "Сподіваюся, ваш пошук пройшов добре, $N. Я не почав йти так далеко на північ, але, зізнаюся, думка про те, що я колись перетну пекельний шлях, мене трохи лякає. Істоти безмозкі, але все одно досить лякаючі.",
    C = "Добре, що ти живий, $N. Погано, що вода ще є. Я сподівався знайти хоча б одне джерело чистої води тут, у Фелвуді. Схоже, мій пошук не вдався. Процес оздоровлення землі міг би бути значно легшим завдяки її існуванню.$B$BI мені доведеться подбати про порятунок усіх лісових створінь, які я можу, одночасно знищуючи тих, які стали настільки корумпованими, що загрожують собі так само, як мандрівники цим колись могутнім лісом.",
},

[5157] = {
    en = "Collection of the Corrupt Water",
    T = "Збір спотвореної води",
    D = "Глибоко в Джеденарі лежить Тіньова Твердиня — головна фортеця їхнього псування і зла.$B$BРада Тіней має захисні заклинання, що оточують їхній притулок у вигляді жаровень. Якщо я хочу дізнатися більше про нашого ворога через віщування, ці жаровні мусять бути погашені. Зробивши це, я зможу шпигувати за Радою і дізнатися, хто їх очолює.$B$BЯкщо можеш, візьми цю флягу і наповни її в Місячному Колодязі в центрі Джеденару. Повернися до мене після цього.",
    O = "Візьми Порожню Флягу до Місячного Колодязя в центрі Джеденару і наповни її, перш ніж повернутися до Ґрети Мосшуф у Сквернолісі.",
    P = "Коли ми отримаємо воду з Місячної криниці, ми очистимо її та використаємо для гасіння жаровень захисту в Тіньовій фортеці. Це дасть мені достатньо часу, щоб зазирнути в кімнати ще глибше й зрозуміти, хто насправді керує цим... культом.$B$BI моліться, щоб мати-земля була з нами.",
    C = "Це буде добре, $N.$B$BNow все, що нам потрібно зробити, окрім нанесення води на мангали, це очистити її. Це не повинно бути складно – потрібно лише трохи подорожувати.$B$BHopefully ми можемо зробити це швидко.",
},

[5158] = {
    en = "Seeking Spiritual Aid",
    T = "У пошуках духовної допомоги",
    D = "Віднеси цю спотворену воду до Степів, $N. На південь від Кабестану, захована вздовж берега, є моя давня подруга, шаманка на ім’я Іслен Водовидиця. Вона могутня шаманка, яка допоможе нам. Її зв’язок із духами води завжди був міцним. Наше завдання, будучи благородним, має переконати її і духів води допомогти нам у цій справі.$B$BТи знайдеш її в маленькому таборі прямо біля води. І, $N, ігноруй піратів... вони лише дрібна неприємність і не становлять для тебе загрози.",
    O = "Візьми Спотворену Воду Місячного Колодязя до Іслен Водовидиці в Степи.",
    P = "Я відчуваю, що ви не просто мандрівник, який шукає шлях до Ратчет. Приходьте, сядьте і відпочиньте в нашому таборі. Поговори зі мною, коли будеш готовий.",
    C = "Ах, вам потрібна вода з цього Місячного колодязя очищена. Зупинити цю силу злоби у Фелвуді здається досить шляхетним, але не мені вирішувати, чи буде вода очищена. Я запитаю духів води — вони вирішать, чи справедлива причина.$B$BGive хвилинку, і я розповім їм про ваше благання. Сподіваюся, вони так само прихильно ставляться до вашої справи, як і я.",
},

[5159] = {
    en = "Cleansed Water Returns to Felwood",
    T = "Очищена вода повертається до Скверноліссі",
    D = "Дякую духам, $N. Це вони прийшли тобі на допомогу, а не я.$B$BЯ даю тобі цю очищену воду. Будь ласка, передай мої вітання Ґреті і мої найкращі побажання. Вона бореться з чимось більшим, ніж багато хто з нас... як, я впевнена, вона незабаром дізнається.$B$BРада Тіней — це сила, з якою не варто жартувати, $N. Пам’ятай про це.$B$BІди тепер. Візьми воду і повернися до Ґрети.",
    O = "Візьми Очищену Воду Місячного Колодязя до Ґрети Мосшуф у Сквернолісі.",
    P = "Ах, я бачу, ти повернувся, $N. добре. Ви знайшли Айлен у Степлі? Або ми повинні знайти інший шлях для досягнення наших цілей?",
    C = "Цього має бути більш ніж достатньо води для наших цілей.$B$BI Радий чути, що Айлен змогла нам допомогти. Її сила з духами води завжди була сильною. Вона також мудра, і рідко буває, що духи не погоджуються з її метою. Той факт, що вони обидва благословили наше завдання, дає мені надію, що ми на правильному шляху.",
},

[5160] = {
    en = "The Matron Protectorate",
    T = "Матрона-Захисниця",
    D = "Вирушай до Калімдору, $r. Наш рід оселився в холодному ландшафті Зимоключа. Щойно ти дістанешся до Зимоключа, знайди печери Мазторілу.$B$BНа крижаних підлогах Мазторілу ти знайдеш кобальтові руни. Тримай одну з моїх лусок і стань на руну, і ти будеш перенесений до Галех, нашої матрони-захисниці.$B$BВіддай їй луску, щоб вона могла передбачити те, що я бачив і відчув тут, у цьому приреченому місці.",
    O = "Вирушай до Зимоключа і знайди Галех. Віддай їй луску Оубі.",
    P = "Радий тебе бачити, $N.",
    C = "Аспекти наполягають на тому, щоб ми не втручалися в справи смертних. Однак у цьому світі таке не завжди можливо - особливо коли хтось із наших презирливо ігнорує такі укази.",
},

[5161] = {
    en = "Wrath of the Blue Flight",
    T = "Гнів Синього Польоту",
    D = "Ми розуміємо, що намагається зробити проклятий рід Смертокрила, і знаємо, що цього не можна допустити.$B$BЧерез захист, який забезпечує гора Чорноскель, нам дедалі важче втручатися.$B$BОднак ми можемо наділити тебе силою, смертний — якщо ти цього забажаєш.$B$BШлях перед тобою повний небезпек. Ти мусиш вирішити, чи прийняти нашу допомогу. Обміркуй це і поговори зі мною знову, коли рішення буде прийнято.",
    O = "Поговори з Галех, якщо бажаєш продовжити.",
    P = "",
    C = "Так і буде...",
},

[5162] = {
    en = "Wrath of the Blue Flight",
    T = "Гнів Синього Польоту",
    D = "Це аркани, які я контролюю, і аркани відправлять тебе до наступного пункту призначення.$B$BКоли ти будеш готовий, подорож розпочнеться. Ти вирушиш до Зачумлених Земель і поговориш із Джезібою.$B$BВін смертний, мудрий, як прадавні, і терплячий, як непорушна земля. Знайди його в Андоґалі.",
    O = "Поговори з Джезібою в Зачумлених Землях. Він мешкає в Андоґалі.",
    P = "",
    C = "Я Джезіба, відома багатьом як Скульптор. Але я ліплю не статуї, а героїв.$B$B",
},

[5163] = {
    en = "Are We There, Yeti?",
    T = "Ми вже там, Єті?",
    D = "Усе готово, $N!$B$BЯ вже надіслав листи своїм друзям, повідомивши, що маю для них сюрприз. І тут ти вступаєш у гру!$B$BЯ дам тобі мого механічного єті, і тобі потрібно буде здивувати їх, відвідавши кожного з моїх друзів, увімкнувши єті і направивши його на них.$B$BКоли покажеш Легакі у Вічнозірі, Спрінкл у Ґаджетзані та Квіксилу в Притулку Маршала, повернися і розкажи мені, що сталося!$B$BБудь ласка, поверни мого єті мені тоді також.",
    O = "Візьми Механічного Єті Умі і налякай ним її друзів:$B$BЛегакі у Вічнозірі (Зимоключ)$BБСпрінкл у Ґаджетзані (Танаріс)$BБКвіксил у Притулку Маршала (Кратер Ун’Ґоро)$B$BКоли закінчиш, поверни Механічного Єті до Умі.",
    P = "Не можу дочекатися, як відреагують мої друзі!$B$BThey ніколи цього не очікую!",
    C = "ха! Вони двічі подумають, перш ніж знову висміювати мої ідеї!$B$BThanks за вашу допомогу, $N. Я не зміг би так весело провести час без вас!",
},

[5164] = {
    en = "Catalogue of the Wayward",
    T = "Каталог Заблудлих",
    D = "Галех не могла обрати кращого інструменту справедливості. Читай із каталогу заблудлих і просвітлюйся.$B$BЯкщо ти наполегливо йтимеш... якщо зробиш те, що від тебе просять... якщо виживеш... ти станеш героєм.",
    O = "Прочитай із Каталогу Заблудлих.",
