},

[5165] = {
    en = "Dousing the Flames of Protection",
    T = "Гасіння полум’я захисту",
    D = "Тепер ти мусиш повернутися до Джеденару. Жаровні, ймовірно, розкидані по всій Тіньовій Твердині. Погаси полум’я кожної з них, і захист, який встановила Рада, впаде принаймні на короткий час. Я чекатиму, коли це станеться. Коли це відбудеться, я зазирну глибоко в Твердиню і спробую дізнатися, хто є головою цієї змії. Тільки тоді ми зможемо подумати про прямий напад на них.",
    O = "Використовуючи Очищену Воду Місячного Колодязя, погаси полум’я чотирьох жаровень захисту в Тіньовій Твердині в Сквернолісі, а потім повернися до Ґрети Мосшуф у Смарагдовому Притулку.",
    P = "Жаровні треба погасити, якщо ми хочемо мати хоч якусь надію підготуватися до значно більшої битви. Зайти в лігво дракона без будь-якого знання — це дурна справа. А це набагато гірше за дракона. Тіньова Рада несе повну відповідальність за велику кількість злочинів і звірств. Нам доведеться працювати швидко, якщо ми хочемо їх зупинити.",
    C = "Я зміг побачити тебе з моїми чарами, щойно згас останній вогонь жаровні. Молодець, $N.$B$BI дізнався кілька речей, перш ніж чорнокнижники Ради тіней змогли перетворити свої заклинання. Сподіваюся, цього буде достатньо.$B$BFor тепер відпочинь. Я розповім вам, що я дізнався за мить.",
},

[5166] = {
    en = "Breastplate of the Chromatic Flight",
    T = "Нагрудник Хроматичного Роду",
    D = "Кування могутнього нагрудника для захисту від невпинних атак хроматичного роду — це справа, побудована на іронії.$B$BЛуска самих звірів, з якими ми боремося, мусить бути пришита до бездоганного панцира старшого хроматичного драка чи дракона. Наразі таких невідомо, і ми сподіваємося, що їх ніколи не буде.$B$BНарешті, мабуть, найскладніший із усіх компонентів: кров героїв.$B$BСкульптор мусить остаточно викувати це творіння.",
    O = "Щоб викувати Нагрудник Хроматичного Роду, тобі потрібно принести Джезібі, відомому як ‘Скульптор’, такі предмети:$B$B1 Хроматичний Панцир.$B$B10 Блискучих Хроматичних Лусок.$B$B10 Крові Героїв.$B$B10 Пошарпаних Швів Мерзоти.",
    P = "Ви зробили мудрий вибір, $R.",
    C = "Ви ще не розумієте? Подорож була пунктом призначення. Хіба ти не відчуваєш бойових шрамів? Біль, який ви зазнали?$B$BHaving пережили випробування, ви сильніша істота. Набагато потужніший. Цей нагрудник є лише відображенням ваших власних вроджених здібностей.",
},

[5167] = {
    en = "Legplates of the Chromatic Defier",
    T = "Наголінники Хроматичного Виклику",
    D = "Панцир зрілого хроматичного драка потрібен для створення основи понож. Блискучі хроматичні луски потім накладаються на дротяний каркас і зачаровуються в крові героїв. Нарешті, гнучка шкіра тіні мусить бути застосована до внутрішніх наголінників.",
    O = "Щоб викувати Наголінники Хроматичного Виклику, тобі потрібно принести Джезібі, відомому як ‘Скульптор’, такі предмети:$B$B1 Хроматичний Панцир.$B$B10 Блискучих Хроматичних Лусок.$B$B10 Крові Героїв.$B$B5 Шкір Тіні.",
    P = "Такого ще ніколи не створювали!",
    C = "Вони відчують запах своїх родичів, коли ви входите в їхні зали, $N. Роздавіть їх власним страхом!",
},

[5168] = {
    en = "Heroes of Darrowshire",
    T = "Герої Дарроушира",
    D = "Герої Дарроушира займають місце в моєму серці, і книга, яку ти приніс мені, Літописи Дарроушира, розповідає їхні історії.$B$BВона розповідає про паладина Давіла Світловогня і про те, як Хрестовий Похід забрав його лібрам до ратуші Гартґлена.$B$BЇї сторінки також говорять про мого брата, Капітана Редпата. Після його зради його щит був розколотий і викинутий, і тепер він лежить у найнесподіванішому місці — біля сараю В’янування Ґаррона.$B$BЗбери ці реліквії, $N. Бо доля і трагедія оточують їх.",
    O = "Принеси Лібрам Давіла і Щит Редпата до Карліна Редпата.",
    P = "У вас є реліквії, $N?",
    C = "У вас є лібрам і щит!$B$BTheir історія переплітається з історією Дарроуширу, і чомусь я знаю, що доля знову зведе їх разом.",
},

[5181] = {
    en = "Villains of Darrowshire",
    T = "Лиходії Дарроушира",
    D = "Літописи Дарроушира розповідають про лиходіїв тієї битви. Вони говорять, як лорд-ґуль Горґус Спустошник був знищений силами Альянсу під час битви. Його тіло кинули в озеро, на північний захід від Перехрестя Коріна, і його череп залишився там.$B$BМардук Чорний ніколи не був переможений, але його легендарний меч був розколотий і загублений. Він лежить на дні ущелини на захід від Перехрестя Коріна.$B$BЗбери ці предмети, $N. Я не знаю чому, але впевнений, що їхня доля пов’язана з тобою.",
    O = "Принеси Череп Горґуса і Розколотий Меч Мардука до Карліна Редпата в Каплиці Світла Надії.",
    P = "Ти знайшов череп і меч, $N?",
    C = "Ви їх знайшли! Молодець, $N! Ці реліквії містять силу, яку я не до кінця розумію, силу, яку ти колись використаєш.$B$BThey також викликають у моїй пам’яті темні спогади, спогади про смерть і зраду, а також про останню ніч у Дарроуширі...",
},

[5201] = {
    en = "Winterfall Intrusion",
    T = "Втручання Зимопадів",
    D = "Моя присутність залишається непоміченою для більшості, $N. Однак є одна прикрість, яка здається міцно вкоріненою тут, у Зимоключі: фурболги Зимопадів.$B$BХоча я ніколи не нападав на фурболгів безпосередньо, вони здаються божевільними, боячись усього на своєму шляху. Я бачив, як вони вбивали незліченну кількість істот, які просто опинилися не в тому місці не в той час.$B$BЯ втомився від їхнього втручання — будь ласка, допоможи мені, відбиваючись. Убий фурболгів і тримай їх подалі від Крижанозубої Скелі.",
    O = "Ріверн Крижаний Вітер хоче, щоб ти знищив 5 Шаманів Зимопадів і 5 Урс Зимопадів.",
    P = "Фурболги, здається, страждають від такої параної...",
    C = "Мені приємно почути, що на короткий час нам не доведеться хвилюватися про вторгнення Winterfall.$B$BYou починаєш демонструвати твою наполегливість, $N.",
},

[5202] = {
    en = "A Strange Red Key",
    T = "Дивний червоний ключ",
    D = "Маленький червоний ключ, здається, зроблений із якогось кістяного матеріалу. Він важкий у твоїй руці, але виглядає дуже крихким. Чому член Ради Тіней мав би таку річ? Можливо, в Джеденарі є щось, що цей дивний ключ відмикає.",
    O = "Досліди Джеденар, щоб з’ясувати, для чого потрібен Криваво-Червоний Ключ.",
    P = "Я починаю замислюватися, чи зможу я коли-небудь втекти з цієї клітки.$B$BIt Це лише питання часу, коли вони принесуть мене в жертву тим демонам, яким вони поклоняються. Монстри!",
    C = "Ключ, ви його знайшли! Будь ласка, дайте це мені, і я нарешті зможу втекти!",
},

[5203] = {
    en = "Rescue From Jaedenar",
    T = "Порятунок із Джеденару",
    D = "Але, як би мені не було боляче, спочатку потрібно зробити одну річ: я мушу знайти меч Трея Світлокузня і втекти з Тіньової Твердині, щоб повідомити моїх начальників, що тут відбувається. Чи можеш ти мені допомогти, $N?$B$BНаше спорядження неподалік звідси, і ти вже довів, що можеш вижити на шляху до вершини.$B$BПісля втечі я вирушу до Дарнаса, якщо ти знайдеш мою подругу Джессір біля кордону Ясенедолу. Вона мала зустріти нас у таборі Смарагдового Кола неподалік.$B$BЩо скажеш, $N? Чи можеш ти мені знову допомогти?",
    O = "Супроводжуй Арко’наріна до місця, де зберігаються Світлокузень і її спорядження, а потім захищай її, коли ви будете тікати з Тіньової Твердині. Після цього знайди Джессір Мунбоу в Сквернолісі, щоб повідомити її, що сталося з її друзями.",
    P = "Ти виглядаєш розгубленим, $n. З вами все гаразд, чи щось не так?",
    C = "Це ти допоміг Арко втекти? Я дуже радий, що ти знайшов мене. Не так давно вона проходила тут, прямуючи до Дарнасу. Вона мала Lightforge на буксирі, і навіть не знайшла часу, щоб поговорити з друїдами, щоб отримати зцілення. Вона сказала, що це надто терміново.$B$BBut вона розповіла мені про вашу зустріч із духом Трея. Яка жахлива доля лицаря Срібної руки. Вона не показувала цього, але я знаю, що це роздирає її всередині, думка про втрату одного з її найближчих друзів.",
},

[5204] = {
    en = "Retribution of the Light",
    T = "Відплата Світла",
    D = "Вона хотіла б удавати, що все гаразд. Їй би дуже хотілося, щоб я думав, що вона достатньо сильна, щоб упоратися з усім цим самостійно, але я знаю краще. Смерть Трея і розповіді про тортури, через які він пройшов, будуть переслідувати її довгий час, і ми нічого не можемо зробити, щоб це зупинити. Але ми можемо дати їй трохи спокою!$B$B$N, повернися до Тіньової Твердині, убий мучителя Трея і знайди його останки. Немає причин, чому ми не можемо завершити всі ці незавершені справи, поки Арко’наріна оплакує на свій лад.",
    O = "Повернися до Джеденару і убий суккубу Ракайю, перш ніж знайти Останки Трея Світлокузня.",
    P = "Ви оглядаєте тіло, і немає жодних сумнівів, що це останки Лицаря Срібної Руки Трея Лайтфорджа. На мить ви думаєте про Арко'наріна й сумніваєтеся, чи важив хтось у вашому житті так багато для вас, як цей чоловік для полоненого нічного ельфа, якому ви нещодавно допомогли втекти з Тіньової фортеці.$B$BAfter ще раз зібравшись з думками, ви знаєте, що ви не можете віднести останки паладина назад до Джесіра, не вбивши попередньо його мучителя.",
    C = "Ви збираєте останки паладина якомога обережніше, пам’ятаючи, що принаймні його дух був звільнений від будь-якого болю чи страждань, які могли бути нав’язані йому.",
},

