[5210] = {
    en = "Brother Carlin",
    T = "Брат Карлін",
    D = "Літописи Дарроушира, завдяки моїй магії, отримали додаткові сторінки в кінці, і тепер вони розширюють свою історію за межі битви. Одна з додаткових сторінок розповідає про іншого Редпата, Карліна, який пережив зраду Джозефа. Карлін зараз у Зачумлених Землях на сході, у Каплиці Світла Надії.$B$BВізьми книгу і поговори з ним.",
    O = "Принеси Розширені Літописи Дарроушира до Карліна Редпата в Східних Зачумлених Землях.",
    P = "Ви прийшли із заходу? Як живе решта Лордерону? Я знаю, що Андорал загинув, але чи Бич уже досяг прекрасного Тірісфалю?",
    C = "Що це за книга? Аннали Дарроуширу? Це був мій дім до війни... мій дім до битви, яка його зруйнувала! Чому ви принесли мені цю книгу?$B$BBut Подивіться сюди! Наприкінці є сторінки, які розповідають про дні після битви! Ось уривок про мене! І про мого брата Джозефа! Чи правдива ця книга?$B$BWe повинен відкрити правду!",
},

[5211] = {
    en = "Defenders of Darrowshire",
    T = "Захисники Дарроушира",
    D = "Багато захисників загинуло в битві за Дарроушир. І багато хто з них знову блукає як жахливі слуги Плеті! Знайди ці бідолашні душі і поклади край їхнім стражданням!$B$BПолюй на ґулів-людожерів, белькотливих ґулів і заражених живодерів. Багато з цих чудовиськ колись були добрими людьми Дарроушира, і знищення їхніх тіл тепер звільнить їхні душі.$B$BТи знайдеш їх у Чумоліссі та Перехресті Коріна, а також в інших твердинях Плеті в Східних Зачумлених Землях.",
    O = "Звільни 15 Духів Дарроушира і повернися до Карліна Редпата.",
    P = "Бідні захисники Дарроуширу кричать мені уві сні: $N. Ви повинні звільнити їх!",
    C = "Приємно чути, що ви знайшли замучені душі моїх братів і звільнили їх. Моє серце буде менше плакати, коли я знаю, що принаймні деякі захисники Дарроуширу більше не занурюються в мерзенне підпорядкування Бича.",
},

[5212] = {
    en = "The Flesh Does Not Lie",
    T = "Плоть не бреше",
    D = "Аптекарі Покинуті — не єдині істоти в цьому світі, які знаються на науках.$B$BЯ роками вивчала чуму, $r. Раніше ми вважали, що сила чуми слабшає, але те, що я виявила тут, у Зачумлених Землях, приголомшує. Чума, здається, набирає сили!$B$BМені потрібно провести більше тестів! Найпотужніше джерело чуми — це заражена плоть найсвіжіше інфікованих. Вирушай до Стратгольма і принеси мені зразки, $N.",
    O = "Збери 20 Зразків Зачумленої Плоті зі Стратгольма і поверни їх до Бетінни Біґґлезінк. Ти підозрюєш, що будь-яка істота в Стратгольмі може мати такий зразок.",
    P = "Дехто каже, що я надто хвилююся, а я кажу їм: «Ви недостатньо хвилюєтеся!»",
    C = "Щось змінилося в хімічній структурі діючих агентів чуми. Потрібні додаткові дані.",
},

[5213] = {
    en = "The Active Agent",
    T = "Активний агент",
    D = "Тобі доведеться заглибитися в Стратгольм, $N.$B$BЗа першими воротами ти знайдеш зіґґурати. Ми знаємо, що Плеть черпає велику силу з цих структур. Досліди зіґґурати і повернися з будь-якою інформацією, яку ти можеш виявити.",
    O = "Вирушай до Стратгольма і досліди зіґґурати. Знайди і поверни нові дані Плеті до Бетінни Біґґлезінк.",
    P = "Ми на порозі відкриття, що може бути цим новим активним збудником чуми!",
    C = "Дивно! На розбір і аналіз цього знадобляться місяці. Серебряний світанок дякує вам за ваші зусилля, $B$BWith наше благословення, вибирайте між цією печаткою світанку або цією руною світанку. Ви можете використовувати будь-який із них замість стандартної комісії Аргентського світанку, щоб збирати каміння бича від нашого імені. Якщо ви втратите свій, поговоріть зі мною, і я дам вам заміну.",
},

[5214] = {
    en = "The Great Fras Siabi",
    T = "Великий Фрас Сіабі",
    D = "Жахлива річ... те, що сталося з Фрасом. Бачиш, місто було розграбоване, і Фрас не хотів залишати свої дорогоцінні товари. Останнє, що я пам’ятаю, як він казав: «Я спалю кожен листок, перш ніж вони дістануть до них свої прокляті, брудні руки!»$B$BЯ можу любити хорошу сигару, але я не дурень. Я покинув Фраса і його чудову крамницю того дня. Я припускаю, що він згорів у полум’ї, але якщо є шанс, що хоча б одна коробка його знаменитого тютюну залишилася цілою...$B$BЩо скажеш, $N? Знайдеш коробку для старого Смокі?",
    O = "Знайди тютюнову крамницю Фраса Сіабі в Стратгольмі і поверни коробку Преміального Тютюну Сіабі. Повернися до Смокі ЛаРю, коли завдання буде виконано.",
    P = "Я не можу цього прийняти, $N! Ви повинні мені допомогти! я вмираю!",
    C = "О милий, милий стогі, як я скучила за тобою...",
},

[5215] = {
    en = "The Scourge Cauldrons",
    T = "Казани Плеті",
    D = "У землях колишнього Лордерона є вісім казанів — чотири тут, на заході, і ще чотири на сході. Ці казани вивергають отруту в повітря, поширюючи чуму по всій землі для Плеті.$B$BНекромантська міць Кел’Тузада занадто велика, щоб просто вимкнути ці казани, але ми думаємо, що можемо знайти спосіб обернути їх на нашу користь. Моя заступниця, Верховна Жриця МакДоннелл, буде твоїм координатором у цьому завданні; вона продовжить інструктаж звідси.",
    O = "Поговори з Верховною Жрицею МакДоннелл у Точці Холодовітрів, Західні Зачумлені Землі.",
    P = "",
    C = "Нехай сила Світла засяє на вас у ці темні часи, $c.  Мені приємно служити вашим координатором нашого плану зі саботування котлів Бича.$B$BOur метою буде змінити склад чуми, яку створюють котли, на щось, що негативно впливає на Бич.  Щоб вплинути на цю зміну, вам потрібно буде забезпечити доступ до кожного з чотирьох котлів, наявних у Західних Чумних землях.$B$BStand готовий герой, бо на вас чекає славетна битва проти мерзенного Бича!",
},

[5216] = {
    en = "Target: Felstone Field",
    T = "Ціль: Поле Фелстоуна",
    D = "Із чотирьох казанів тут, на заході, той, що розташований на Полі Фелстоуна, може бути найлегшим для доступу. Плеть розмістила тут зеленіші війська, хоча їх не слід недооцінювати.$B$BВирушай до Поля Фелстоуна, на північний захід від Андоґалу, і вступи в бій із лордом казана там. Ми вважаємо, що в нього є ключ, який відкриє доступ до казана. Коли казан буде відімкнено, використай цю пляшку, щоб отримати зразок отрут усередині казана; він нам потрібен для вивчення, щоб розробити контрзасіб.",
    O = "Вирушай до Поля Фелстоуна в Західних Зачумлених Землях, щоб знайти і перемогти Лорда Казана, який там присутній. У нього може бути ключ, який дозволить отримати доступ до казана. У тебе має бути Порожня Пляшка з Поля Фелстоуна, щоб зібрати зразок отрут, використаних у казані.",
    P = "Панель доступу до казана залишається надійно закріпленою.  Щоб його відкрити, вам потрібно буде знайти ключ.",
    C = "Ключ, взятий у Cauldron Lord Bilemaw, ідеально підходить для розблокування панелі доступу.  Неприємний сморід виходить із відкритої панелі, оскільки невідома суміш концентрованих речовин вирує всередині котла.$B$BThere — це невеликий кран, під який досить добре підходить пляшка, що дозволяє взяти зразок для Верховної Жриці МакДоннелл назад у Chillwind Point.",
},

[5217] = {
    en = "Return to Chillwind Camp",
    T = "Повернення до Табору Холодовітрів",
    D = "Ти наповнив пляшку достатньою кількістю отруйної суміші з казана для відповідного зразка, який можна вивчити.$B$BЗ отрутою в руках настав час повернутися до Верховної Жриці МакДоннелл у Табір Холодовітрів, щоб завершити місію.",
    O = "Принеси Наповнену Пляшку з Поля Фелстоуна до Верховної Жриці МакДоннелл у Табір Холодовітрів, Західні Зачумлені Землі.",
    P = "Ласкаво просимо назад у відносну безпеку Chillwind Camp, $N.  Про який прогрес у котлах ви маєте повідомити?",
    C = "Молодець $N – алхіміку Арбінґтону не знадобиться часу, щоб проаналізувати це та розробити контрагент, щоб ввести його в котел.  Якщо ми зможемо викачати його достатньо в повітря, ми зможемо послабити весь присутній тут Бич.$B$BThis, безсумнівно, буде випробуванням, яке триватиме; нам потрібно буде постійно натискати на ці котли та вводити наші реагенти в їх суміш.  І все-таки, якщо ми зможемо продовжити це, ми матимемо величезну перевагу над Скорджем, коли прийде час битви!",
},

[5218] = {
    en = "Felstone Field Cauldron",
    T = "Котел на Полі Фелстоун",
    D = "",
    O = "",
    P = "Чумний котел Бича стоїть перед вами, викидаючи величезну кількість токсинів у повітря.  Невелика панель доступу, яка не має жодного опису, розташована в основі величезної платформи казана.$B$BHaving вже перемогли володаря казана та отримали його ключ, ви можете додати відповідні реагенти до казана, щоб створити засіб боротьби з чумою.",
    C = "Додавання реагентів до суміші в казані починає змінювати колір і текстуру хмари, яку вона вивергає.  Напасті, які навіть віддалено знаходяться біля казана, здається, відштовхуються від введення нових компонентів у навколишнє середовище.",
},

[5219] = {
    en = "Target: Dalson's Tears",
    T = "Ціль: Сльози Далсона",
    D = "Один із чумних котлів розташований на полі колишньої ферми, яку тепер називають Сльозами Далсона. Що ж, ми не проллємо сліз цього дня, коли зірвемо плани Скари і змусимо їх захлинутися власними випарами!$B$BВирушай до Сліз Далсона, майже прямо на північ від Андоґала, і знищ тамтешнього лорда котла. У нього має бути ключ, як і в попереднього, що дозволить тобі отримати доступ до котла. Використовуй цю пляшку, щоб зібрати зразок із вмісту котла; кожен котел має свій унікальний набір токсинів.",
    O = "Вирушайте до Сліз Далсона в Західних Зачумлених Землях, щоб знайти і перемогти тамтешнього Лорда Котла, і використайте його ключ, щоб отримати доступ до котла. У вас має бути з собою Порожня Пляшка Сліз Далсона, щоб зібрати зразок отрут, які використовуються в котлі.",
    P = "Панель доступу до казана залишається надійно закріпленою. Щоб його відкрити, вам потрібно буде знайти ключ.",
    C = "Жахливий ключ, знайдений на володарі казана, легко ковзає в замкову щілину, а потім зникає, надаючи вам постійний доступ до нього.  Грубий, в’язкий іхор пульсує крізь звивисті трубки всередині котлів.$B$BThere — це невеликий патрубок, під який досить добре вставляється пляшка, що дає змогу брати зразок для Верховної Жриці МакДоннелл у Пойнт Холодного Вітру.",
},

[5220] = {
    en = "Return to Chillwind Camp",
    T = "Повернення до Табору Холодновітру",
    D = "Ти обережно наповнюєш пляшку достатньою кількістю гнилі з котла, щоб отримати зразок відповідного розміру.$B$BЗ отрутою в руках настав час повернутися до Верховної Жриці МакДоннелл у Табір Холодновітру, щоб завершити місію.",
    O = "Принесіть Наповнену Пляшку Сліз Далсона до Верховної Жриці МакДоннелл у Табір Холодновітру, Західні Зачумлені Землі.",
    P = "Ми знаємо, що в кожному котлі використовується різна суміш реагентів для генерації токсину, що викликає чуму; так само ми знаємо, що нам потрібно буде розробити контрагент, унікальний для кожного котла. Ваш зразок із «Сльоз Далсона» стане ключем до того, як визначити потребу в реагенті цього казана.",
    C = "Ах, тут є багато чого для навчання. Молодець, $N!$B$BFor, тепер наступний крок у наших руках. Нам потрібно буде створити список реагентів, які в поєднанні з тим, що вже є в котлі, діятимуть як його лічильник.$B$BThe Єдиний спосіб, яким ми зможемо ввести це, помістивши реагенти безпосередньо в котел. Алхімік Арбінґтон матиме більше інформації про це, тому не забудьте поговорити з ним якнайшвидше.",
},

[5221] = {
    en = "Dalson's Tears Cauldron",
    T = "Котел Сліз Далсона",
    D = "",
    O = "",
    P = "Чумний котел Бича стоїть перед вами, викидаючи величезну кількість токсинів у повітря.  Невелика панель доступу, яка не має жодного опису, розташована в основі величезної платформи казана.$B$BHaving вже перемогли володаря казана та отримали його ключ, ви можете додати відповідні реагенти до казана, щоб створити засіб боротьби з чумою.",
    C = "Додавання реагентів до суміші в казані починає змінювати колір і текстуру хмари, яку вона вивергає. Напасті, які навіть віддалено знаходяться біля казана, здається, відштовхуються від введення нових компонентів у навколишнє середовище.",
},

[5222] = {
    en = "Target: Writhing Haunt",
    T = "Ціль: Осередок Страждань",
    D = "Два котли успішно відкрито; хоча ти зможеш отримувати до них доступ необмежено, ми все ще хочемо відкрити два, що залишилися. Це дасть нам більше можливостей для введення протиотрути!$B$BЦього разу ти вирушиш до котла в Осередку Страждань. Він розташований майже прямо на схід від Андоґала, відносно близько до зруйнованих міських стін; знову ж таки, знищ тамтешнього лорда котла, щоб отримати його ключ. Використовуй цю пляшку, щоб зібрати зразок із котла.$B$BУспішного полювання, $N!",
    O = "Вирушайте до Осередку Страждань у Західних Зачумлених Землях, щоб знайти і перемогти тамтешнього Лорда Котла, і використайте його ключ, щоб отримати доступ до котла. У вас має бути з собою Порожня Пляшка Осередку Страждань, щоб зібрати зразок отрут, які використовуються в котлі.",
    P = "Панель доступу до казана залишається надійно закріпленою. Щоб його відкрити, вам потрібно буде знайти ключ.",
    C = "Ключ володаря котла відкриває панель доступу до цього котла, а потім зникає, подібно до інших ключів від двох попередніх котлів, з якими ви мали справу.  Під платформою казана бурхливо бурхить гнильно пахнуча речовина.$B$BThere — це маленький кран, під який досить добре вставляється пляшка, що дозволяє взяти зразок для Верховної Жриці МакДоннелл у Пойнт Холодного вітру.",
},

[5223] = {
    en = "Return to Chillwind Camp",
    T = "Повернення до Табору Холодновітру",
    D = "Ти обережно наповнюєш порожню пляшку; зразок мерзенної субстанції, що хлюпається під платформою котла, тепер гойдається в тендітній скляній посудині.$B$BЗ отрутою в руках настав час повернутися до Верховної Жриці МакДоннелл у Табір Холодновітру, щоб завершити місію.",
    O = "Принесіть Наповнену Пляшку Осередку Страждань до Верховної Жриці МакДоннелл у Табір Холодновітру, Західні Зачумлені Землі.",
    P = "Щойно ми успішно проаналізуємо зразок, взятий із котла Writhing Haunt, це дасть нам третій шлях для доставки нищівного контрагента на Бич!",
    C = "Ще одна чудово виконана місія, $N! Це робить три котли доступними для боротьби з Бичем. Якби некромантичне панування Кел'Тузада над цими землями не було таким сильним, як зараз, я б насмілився сказати, що ви б їх повністю закрили!$B$BAlchemist Арбінґтон матиме звіт про те, що цей котел — як і інші підірвані казани — вимагатимуть, щоб доставити нашого контрагента до чуми. Таким чином, настав час поставити під наш вплив останній котел заходу!",
},

[5224] = {
    en = "Writhing Haunt Cauldron",
    T = "Котел Осередку Страждань",
    D = "",
    O = "",
    P = "Чумний котел Бича стоїть перед вами, викидаючи величезну кількість токсинів у повітря.  Невелика панель доступу, яка не має жодного опису, розташована в основі величезної платформи казана.$B$BHaving вже перемогли володаря казана та отримали його ключ, ви можете додати відповідні реагенти до казана, щоб створити засіб боротьби з чумою.",
    C = "Додавання реагентів до суміші в казані починає змінювати колір і текстуру хмари, яку вона вивергає. Напасті, які навіть віддалено знаходяться біля казана, здається, відштовхуються від введення нових компонентів у навколишнє середовище.",
},

[5225] = {
    en = "Target: Gahrron's Withering",
    T = "Ціль: В’янення Гаррона",
    D = "Останній котел, що залишився, розташований на фермі, яку тепер називають В’яненням Гаррона. Його охороняють одні з найсильніших слуг Скари — зокрема, привиди і фантоми. З ними жартувати не варто, $N.$B$BВ’янення Гаррона розташоване на північний схід від нашої позиції, близько до початку Східних Зачумлених Земель; знову ж таки, знищ тамтешнього лорда котла, щоб отримати його ключ. Ось твоя порожня пляшка для зразків; принеси її мені наповненою. Нехай Світло захистить тебе в цій небезпечній місії, $c.",
    O = "Вирушайте до В’янення Гаррона в Західних Зачумлених Землях, щоб знайти і перемогти тамтешнього Лорда Котла, і використайте його ключ, щоб отримати доступ до котла. У вас має бути з собою Порожня Пляшка В’янення Гаррона, щоб зібрати зразок отрут, які використовуються в котлі.",
    P = "Панель доступу до казана залишається надійно закріпленою.  Щоб його відкрити, вам потрібно буде знайти ключ.",
    C = "Ключ Cauldron Lord Soulwrath розпадається, коли він торкається замка на панелі доступу біля основи платформи котла.  Всередині чується легкий стукіт, і панель доступу відкривається, щоб виявити більше в’язких токсинів усередині казана.$B$BThere — це невеликий кран, під який досить добре підходить пляшка, дозволяючи взяти зразок для Верховної Жриці МакДоннелл назад у Chillwind Point.",
},

[5226] = {
    en = "Return to Chillwind Point",
    T = "Повернення до Табору Холодновітру",
    D = "Ти обережно закриваєш кран на панелі керування, спостерігаючи, як гнила рідина котла крапає в порожню пляшку.$B$BЗ отрутою в руках настав час повернутися до Верховної Жриці МакДоннелл у Табір Холодновітру, щоб завершити місію.",
    O = "Принесіть Наповнену Пляшку В’янення Гаррона до Верховної Жриці МакДоннелл у Табір Холодновітру, Західні Зачумлені Землі.",
    P = "Тут, на заході, у В’ялі Ґаррона зберігається останній котел, до якого нам потрібен доступ. Коли ми отримаємо зразок чуми, яку вона вивергає, ми зможемо ввести наші реагенти в навколишнє середовище через чотири окремі посудини! Бичу буде важко не допустити нас до всіх чотирьох, навіть якщо за ними стоїть сила Кел'Тузада.",
    C = "Вітаємо $N, ви відкрили для нас останній котел! Алхімік Арбінґтон незабаром дізнається, що потрібно для цього котла щодо реагентів, необхідних для суміші.$B$BAs для вас, я впевнений, що командир Валорфіст захоче особисто подякувати вам за допомогу, яку ви нам надали. Без вас наша боротьба з Бичем була б майже нездоланною. Спасибі, герою!",
},

[5227] = {
    en = "Gahrron's Withering Cauldron",
    T = "Котел В’янення Гаррона",
    D = "",
    O = "",
    P = "Чумний котел Бича стоїть перед вами, викидаючи величезну кількість токсинів у повітря.  Невелика панель доступу, яка не має жодного опису, розташована в основі величезної платформи казана.$B$BHaving вже перемогли володаря казана та отримали його ключ, ви можете додати відповідні реагенти до казана, щоб створити засіб боротьби з чумою.",
    C = "Додавання реагентів до суміші в казані починає змінювати колір і текстуру хмари, яку вона вивергає. Напасті, які навіть віддалено знаходяться біля казана, здається, відштовхуються від введення нових компонентів у навколишнє середовище.",
},

[5228] = {
    en = "The Scourge Cauldrons",
    T = "Котли Скари",
    D = "На землях колишнього Лордерону є вісім котлів — чотири на заході і ще чотири, укріплені на сході. Ці котли вивергають отруту в повітря, поширюючи чуму по всій землі для Скари.$B$BНекромантська міць Кел’Тузада занадто велика, щоб просто вимкнути ці котли, але ми вважаємо, що можемо використати їх на нашу користь. Моя заступниця, Жриця Тіней Вандіс, буде твоїм контактним пунктом у цьому завданні; вона продовжить інструктаж звідси.",
    O = "Поговоріть із Жрицею Тіней Вандіс на Бастіоні, Західні Зачумлені Землі.",
    P = "",
    C = "З тіні, брате $R, вітаю тебе. Я маю стати вашим координатором нашого плану зі саботування котлів Бича.$B$BOur метою буде змінити склад чуми, яку створюють котли, на щось, що негативно впливає на Бич. Щоб вплинути на цю зміну, вам потрібно буде забезпечити доступ до кожного з чотирьох котлів тут, у Західних Чумних землях.$B$BThe настав час, щоб ви очолили атаку на Бич, герою.",
},

[5229] = {
    en = "Target: Felstone Field",
    T = "Ціль: Поле Фелстоун",
    D = "Із чотирьох котлів у Західних Зачумлених Землях той, що на Полі Фелстоун, можливо, найлегше отримати доступ. Скара розмістила тут молодших бійців, хоча їх не варто недооцінювати.$B$BВирушай до Поля Фелстоун, прямо на схід звідси і на північний захід від Андоґала, і вступи в бій із тамтешнім лордом котла. У нього є ключ, який відкриє доступ до котла. Коли котел буде розблоковано, використай цю пляшку, щоб зібрати зразок токсинів котла; нам це потрібно для вивчення, щоб розробити протиотруту.",
    O = "Вирушайте до Поля Фелстоун у Західних Зачумлених Землях, щоб знайти і перемогти тамтешнього Лорда Котла. У нього може бути ключ, який дозволить отримати доступ до котла. У вас має бути з собою Порожня Пляшка Поля Фелстоун, щоб зібрати зразок отрут, які використовуються в котлі.",
    P = "Панель доступу до казана залишається надійно закріпленою.  Щоб його відкрити, вам потрібно буде знайти ключ.",
    C = "Ключ, взятий у Cauldron Lord Bilemaw, ідеально підходить для розблокування панелі доступу, хоча він зникає після використання.  Все-таки ви думаєте, що тепер можна відкрити панель без ключа.  Неприємний сморід виходить із відкритої панелі, оскільки невідома суміш концентрованих речовин вирує всередині котла.$B$BThere — це невеликий кран, під який досить добре підходить пляшка, що дозволяє взяти зразок для жриці Тіні Вандіс, яка повертається до Оплоту.",
},

[5230] = {
    en = "Return to the Bulwark",
    T = "Повернення на Бастіон",
    D = "Ти наповнюєш пляшку достатньою кількістю отруйної суміші котла, щоб отримати зразок для вивчення.$B$BЗ отрутою в руках настав час повернутися до Жриці Тіней Вандіс на Бастіон, щоб завершити місію.",
    O = "Принесіть Наповнену Пляшку Поля Фелстоун до Жриці Тіней Вандіс на Бастіон, Західні Зачумлені Землі.",
    P = "Ласкаво просимо назад у відносну безпеку Бастиону, $N. Про який прогрес у котлах ви маєте повідомити?",
    C = "Молодець $N – Аптекарю Дітерсу не знадобиться часу, щоб проаналізувати це та розробити протидіючий засіб, щоб ввести його в котел. Якщо ми зможемо викачати його достатньо в повітря, ми зможемо послабити весь присутній тут Бич.$B$BThis, безсумнівно, буде випробуванням, яке триватиме; нам потрібно буде постійно натискати на ці котли та вводити наші реагенти в їх суміш. І все-таки, якщо ми зможемо продовжити це, ми матимемо величезну перевагу над Скорджем, коли прийде час битви!",
},

[5231] = {
    en = "Target: Dalson's Tears",
    T = "Ціль: Сльози Далсона",
    D = "Один із чумних котлів розташований на полі колишньої ферми, яку тепер називають Сльозами Далсона. Сліз цього дня не буде, $c; ми мусимо вдарити по цьому котлу і отримати до нього доступ!$B$BВирушай до Сліз Далсона, майже прямо на північ від Андоґала, і знищ тамтешнього лорда котла. У нього має бути ключ, як і в попереднього, що дозволить тобі зазирнути всередину котла. Використовуй цю пляшку, щоб зібрати зразок із вмісту котла; кожен котел має свій унікальний набір токсинів.",
    O = "Вирушайте до Сліз Далсона в Західних Зачумлених Землях, щоб знайти і перемогти тамтешнього Лорда Котла, і використайте його ключ, щоб отримати доступ до котла. У вас має бути з собою Порожня Пляшка Сліз Далсона, щоб зібрати зразок отрут, які використовуються в котлі.",
    P = "Панель доступу до казана залишається надійно закріпленою. Щоб його відкрити, вам потрібно буде знайти ключ.",
    C = "Скелетний ключ, знайдений на володарі казана, легко ковзає в замкову щілину, а потім зникає, надаючи вам постійний доступ до нього. Грубий, в’язкий іхор пульсує крізь звивисті трубки всередині котлів.$B$BThere — це невеликий патрубок, під який досить добре вставляється пляшка, дозволяючи взяти зразок для жриці Тіні Вандіс у Бастион.",
},

[5232] = {
    en = "Return to the Bulwark",
    T = "Повернення на Бастіон",
    D = "Ти обережно наповнюєш пляшку достатньою кількістю гнилі з котла, щоб отримати зразок відповідного розміру.$B$BЗ отрутою в руках настав час повернутися до Жриці Тіней Вандіс на Бастіон, щоб завершити місію.",
    O = "Принесіть Наповнену Пляшку Сліз Далсона до Жриці Тіней Вандіс на Бастіон, Західні Зачумлені Землі.",
    P = "Ми знаємо, що в кожному котлі використовується різна суміш реагентів для генерації токсину, що викликає чуму; так само ми знаємо, що нам потрібно буде розробити контрагент, унікальний для кожного котла. Ваш зразок із «Сльоз Далсона» стане ключем до того, як визначити потребу в реагенті цього казана.",
    C = "Ах, тут є багато чого для навчання. Молодець, $N!$B$BFor, тепер наступний крок у наших руках. Нам потрібно буде створити список реагентів, які в поєднанні з тим, що вже є в котлі, діятимуть як його лічильник.$B$BThe Єдиний спосіб, яким ми зможемо ввести це, помістивши реагенти безпосередньо в котел. Аптекар Дізерс матиме більше інформації про це, тому не забудьте поговорити з ним якнайшвидше.",
},

[5233] = {
    en = "Target: Writhing Haunt",
    T = "Ціль: Осередок Страждань",
    D = "Два котли успішно відкрито; хоча ти зможеш отримувати до них доступ необмежено, ми все ще хочемо відкрити два, що залишилися. Це дасть нам більше можливостей для введення протиотрути!$B$BЦього разу ти вирушиш до котла в Осередку Страждань. Він розташований майже прямо на схід від Андоґала, відносно близько до зруйнованих міських стін; знову ж таки, знищ тамтешнього лорда котла, щоб отримати його ключ. Використовуй цю пляшку, щоб зібрати зразок із котла.$B$BУспішного полювання, $N!",
    O = "Вирушайте до Осередку Страждань у Західних Зачумлених Землях, щоб знайти і перемогти тамтешнього Лорда Котла, і використайте його ключ, щоб отримати доступ до котла. У вас має бути з собою Порожня Пляшка Осередку Страждань, щоб зібрати зразок отрут, які використовуються в котлі.",
    P = "Панель доступу до казана залишається надійно закріпленою.  Щоб його відкрити, вам потрібно буде знайти ключ.",
    C = "Ключ володаря казана відкриває панель доступу до цього казана, а потім зникає, подібно до інших ключів від попередніх, якими ви мали справу.  Під платформою казана бурхливо бурхить гнильно пахнуча речовина.$B$BThere — це невеликий кран, під який досить добре підходить пляшка, що дозволяє взяти зразок для жриці Тіні Вандіс, яка повертається на Бастион.",
},

[5234] = {
    en = "Return to the Bulwark",
    T = "Повернення на Бастіон",
    D = "Ти обережно наповнюєш порожню пляшку; зразок мерзенної субстанції, що хлюпається під платформою котла, тепер гойдається в тендітній скляній посудині.$B$BЗ отрутою в руках настав час повернутися до Жриці Тіней Вандіс на Бастіон, щоб завершити місію.",
    O = "Принесіть Наповнену Пляшку Осередку Страждань до Жриці Тіней Вандіс на Бастіон, Західні Зачумлені Землі.",
    P = "Щойно ми успішно проаналізуємо зразок, взятий із котла Writhing Haunt, це дасть нам третій шлях для доставки нищівного контрагента проти Бича!",
    C = "Ще одна чудово виконана місія, $N! Це робить три котли доступними для боротьби з Бичем. Якби некромантичне панування Кел’Тузада над цими землями не було таким сильним, як зараз, я б насмілився сказати, що ви б їх повністю закрили!$B$BApothecary Дізерс матиме звіт про те, що цей котел — як і інші підірвані котли — вимагатимуть, щоб доставити нашого контрагента до чуми. Таким чином, настав час поставити під наш вплив останній котел заходу!",
},

[5235] = {
    en = "Target: Gahrron's Withering",
    T = "Ціль: В’янення Гаррона",
    D = "Останній котел, що залишився, розташований на фермі, яку тепер називають В’яненням Гаррона. Його охороняють одні з найсильніших слуг Скари — зокрема, привиди і фантоми. З ними жартувати не варто, $N.$B$BВ’янення Гаррона розташоване далеко на схід від Бастіону, близько до початку Східних Зачумлених Земель; знову ж таки, знищ тамтешнього лорда котла, щоб отримати його ключ. Ось твоя порожня пляшка для зразків; принеси її мені наповненою. Нехай тіні приховають тебе в безпеці під час цієї небезпечної місії, $c.",
    O = "Вирушайте до В’янення Гаррона в Західних Зачумлених Землях, щоб знайти і перемогти тамтешнього Лорда Котла, і використайте його ключ, щоб отримати доступ до котла. У вас має бути з собою Порожня Пляшка В’янення Гаррона, щоб зібрати зразок отрут, які використовуються в котлі.",
    P = "Панель доступу до казана залишається надійно закріпленою. Щоб його відкрити, вам потрібно буде знайти ключ.",
    C = "Ключ Cauldron Lord Soulwrath розпадається, коли він торкається замка на панелі доступу біля основи платформи котла. Всередині чути легкий стукіт, і панель доступу відкривається, щоб виявити більше в’язких токсинів у каркасі казана.$B$BThere — це невеликий кран, під який досить добре підходить пляшка, що дозволяє взяти зразок для жриці Тіні Вандіс, яка повертається до Оплоту.",
},

[5236] = {
    en = "Return to the Bulwark",
    T = "Повернення на Бастіон",
    D = "Ти обережно закриваєш кран на панелі керування, спостерігаючи, як гнила рідина котла крапає в порожню пляшку.$B$BЗ отрутою в руках настав час повернутися до Жриці Тіней Вандіс на Бастіон, щоб завершити місію.",
    O = "Принесіть Наповнену Пляшку В’янення Гаррона до Жриці Тіней Вандіс на Бастіон, Західні Зачумлені Землі.",
    P = "У В’янучі Ґаррона зберігається останній котел, до якого нам потрібно отримати доступ тут, на заході. Коли ми отримаємо зразок чуми з того казана, ми зможемо ввести наші реагенти в навколишнє середовище через чотири окремі посудини! Бичу буде важко не допустити нас до всіх чотирьох, навіть якщо за ними стоїть сила Кел'Тузада.",
    C = "Вітаємо $N, ви відкрили для нас останній котел! Аптекар Дізерс незабаром дізнається, що потрібно для цього котла щодо реагентів, необхідних для суміші.$B$BAs для вас, я впевнений, що верховний виконавець Деррінгтон захоче подякувати вам особисто за допомогу, яку ви нам надали. Без вас наша боротьба з Бичем була б майже нездоланною. Я дякую тобі, могутній $C.",
},

[5237] = {
    en = "Mission Accomplished!",
    T = "Місія Виконана!",
    D = "",
    O = "",
    P = "",
    C = "$N, твоя успішна реконструкція котлів — це величезна перемога для нас!$B$B<Верховний виконавець відкашлюється й починає голосно ревети.>$B$BLet всі в моїй присутності чують: за службу Покинутим і Орді в цілому понад очікуване — перед обличчям величезні шанси та неймовірна небезпека, я можу додати - я даю $N це, і я поширююся на $Ghis:her; наша безмежна вдячність як справжньому герою Орди. Хаза!",
},

[5238] = {
    en = "Mission Accomplished!",
    T = "Місія Виконана!",
    D = "",
    O = "",
    P = "",
    C = "$N, твоя успішна реконструкція котлів — це величезна перемога для нас!$B$B<Командир відкашлюється й починає голосно реготати.>$B$BLet всі в моїй присутності чують: за службу Королівству Штормовію та Альянсу понад обов’язки — перед обличчям величезні шанси та неймовірна небезпека, я можу додати - я даю $N це, і я поширююся на $Ghis:her; наша безмежна вдячність як справжнього героя Альянсу. Здоров я кажу!",
},

[5241] = {
    en = "Uncle Carlin",
    T = "Дядько Карлін",
    D = "Іноді, коли настає ніч, я чую, як мій дядько Карлін плаче. Звучить так, ніби він далеко, на сході.$B$BСподіваюся, він не плаче через мене! $N, чи не могли б ви знайти мого дядька і сказати йому, що зі мною все гаразд?$B$BЯкщо ви знайдете його, скажіть, що я чекаю на нього, і хочу почути історію, яку він розповідав… ту, про кроликів і ягідне варення! Ця історія така смішна!",
    O = "Знайдіть Карліна Редпата.",
    P = "",
    C = "Ви бачили Памелу? Вона жива?$B$BShe мертва? ні! О, Памела! Чому твій дух ще страждає в цьому світі. Чому ти загинув, а мене доля тримає? В одну мить я б помінявся з тобою місцями й блукав мертвим Дарроуширом, привид і самотній!$B$BAh, але ця новина не може змінити долю. Дякую, $N. Тепер мій обов’язок, мій обов’язок помститися, палає як ніколи.",
},

[5242] = {
    en = "A Final Blow",
    T = "Останній Удар",
    D = "На жаль, я бачу єдиний спосіб зупинити цю загрозу для Сквернолісу — це фронтальна атака. Немає інших шляхів до Тіньової Фортеці, і я не маю засобів телепортувати тебе всередину. Прямий шлях униз до самого дна — єдиний спосіб… і я також знаю, кого тобі варто шукати. Його звати Фел’дан… Тіньовий Лорд Фел’дан. Він смертний, що тримає владу внизу… він — голова змії. Убий його та двох його слуг-суккубів і повертайся до мене. Фел’дан — той, хто укладає угоди з Легіоном. Його треба зупинити.",
    O = "Убийте Муру і Салію, і принесіть Голову Тіньового Лорда Фел’дана до Ґрети Мохохуфа в Сквернолісі.",
    P = "Сподіваюся, без Фел’дана Рада Тіней втратить концентрацію та почне ворожнечу. Вони будуть боротися один з одним за контроль і накопичувати активи для майбутніх планів. Це буде сприятливий час, щоб спустошити їх та їхніх рабів-демонів.",
    C = "Слава матері-землі, $N! дякую! Це справді чудовий день!$B$BThe Тіньовій Раді буде важко досягти тих самих рівнів влади, які вони мали, завдяки цьому удару по їхній ієрархії. Цього дня ви зробили велику справу!",
},

[5243] = {
    en = "Houses of the Holy",
    T = "Доми Святого",
    D = "Я дивлюся на свою нежить як на хворобу, $r. Хвороба, яка потребує лише лікування; однак, це також велике благословення для Світанку Срібла. Який кращий інструмент для знищення язичників Скари, ніж через нежить?$B$BМої колеги шанують мене за жертви, які я приніс, але похвала для мене нічого не значить.$B$BЯкщо ти зацікавлений у допомозі Світанку Срібла, я можу запропонувати тобі завдання.$B$BВирушай до Стратгольма і поверни наші запаси святої води. Шукай у ящиках із припасами.",
    O = "Вирушайте до Стратгольма, на північ. Перегляньте ящики з припасами, розкидані по місту, і зберіть 5 одиниць Святої Води Стратгольма. Поверніться до Леоніда Барталом’ю Шанованого, коли зберете достатньо благословенної рідини.",
    P = "Будьте обережні, не всі ящики з припасами переживуть руйнування міста. Бич не наважується торкатися води, але свята вода точно не захистить від паразитів.$B$B",
    C = "Молодець, $R. Ви довели, що, будучи терпимими до інших, ви не зупинитеся ні перед чим, щоб знищити прихильників Кел'Тузада.$B$B",
},

[5244] = {
    en = "The Ruins of Kel'Theril",
    T = "Руїни Кел’Теріла",
    D = "Історія Кел’Теріла — це історія проклятої раси, прив’язаної до місця, де вони намагалися провести невдалий ритуал…$B$BВищевроджені, яких ти там знайдеш, колись викрали священний артефакт, вважаючи, що зможуть висмоктати його силу для себе, ставши ще могутнішими. У своїх зусиллях реліквія розкололася у величезному вибуху, загнавши уламки під лід озера…$B$BПоговори з Джароном Кам’яноформою, якщо хочеш дізнатися більше; він нещодавно відвідав цю місцевість і може розповісти тобі більше.",
    O = "Поговоріть із Джароном Кам’яноформою в селі Зорепад.",
    P = "",
    C = "Ну, звичайно, я можу розповісти тобі більше про Кел'Теріл. Зауважте, я не історик, але можу розповісти вам про те, що я там побачив...",
},

[5245] = {
    en = "Troubled Spirits of Kel'Theril",
    T = "Неспокійні Духи Кел’Теріла",
    D = "Духи вищевроджених — жалюгідні створіння, це точно. Вони все ще шукають уламки того самого, що прокляло їх у Кел’Терілі назавжди — викраденої реліквії.$B$BЯкщо ти так зацікавлений, візьми мій кайло і вирушай на південь до озера, подивися, чи зможеш зібрати її уламки з-під льоду.$B$BТепер я не можу тобі нічого сказати про те, що ти знайдеш, але я знаю когось, хто може… Аврора Небокличка; вона мешкає біля Вежі Північного Перевалу в північній частині Східних Зачумлених Земель.",
    O = "Використовуйте Кайло Джарона, щоб знайти чотири Уламки Реліквії Вищевроджених. Принесіть їх до Аврори Небоклички в Східних Зачумлених Землях.",
    P = "Чому ти сюди прийшов?",
    C = "Я не хочу обговорювати минуле вищих ельфів, $N. Будь ласка, мені боляче думати про все, що сталося... І що немає способу виправити ситуацію.",
},

[5246] = {
    en = "Fragments of the Past",
    T = "Уламки Минулого",
    D = "Я не усвідомлювала… Пробач мої різкі слова, $c.$B$BПомилки моїх предків — це не те, на чому я хочу зосереджуватися, але якщо твоє прохання щире, я допоможу тобі.$B$B<Аврора оглядає уламки.>$B$BЯ вважаю, що це Кристал Зін-Малора, артефакт, який може утримувати і контролювати потужні арканні сили. Його могли б використати на благо, але злі наміри тих, хто його вкрав, спричинили його розкол.$B$BВирушай до Храму Зін-Малора в Азшарі — я можу лише сподіватися, що книга все ще там.",
    O = "Знайдіть Священні Писання Вищевроджених у Храмі Зін-Малора в Азшарі і принесіть їх до Аврори Небоклички біля Вежі Північного Перевалу в Східних Зачумлених Землях.",
    P = "Лише на сторінках священних писань я зможу зрозуміти, чи можу я тобі допомогти чи ні...",
    C = "Сторінки залишилися недоторканими протягом багатьох років...",
},

[5247] = {
    en = "Fragments of the Past",
    T = "Уламки Минулого",
    D = "Я зможу тобі допомогти, якщо відтворення артефакту — це дійсно те, що ти хочеш зробити.$B$BЩоб склеїти уламки разом, мені знадобляться предмети з сильними магічними властивостями. Зачарований торієвий злиток і п’ять кристалів відновлення… Також тобі потрібно зібрати воду з місця, яке може здатися незвичним… Знайди жахливу водойму вздовж Алеї Елдрета в Жахливому Молотові в Фераласі, і наповни цю флягу.$B$BПоки тебе не буде, я спробую отримати з цих сторінок знання, необхідні для відновлення пошкодженої реліквії.",
    O = "Принесіть Зачарований Торієвий Злиток, 5 Кристалів Відновлення і Флягу Жахливої Води до Аврори Небоклички біля Вежі Північного Перевалу в Східних Зачумлених Землях.",
    P = "Реліквію потрібно віддати в руки тільки найнадійнішим. Його не можна знову вкрасти...",
    C = "Використовуючи ці елементи, я зможу об’єднати фрагменти... щоб, сподіваюся, стати тим, чим вони колись були.",
},

[5248] = {
    en = "Tormented By the Past",
    T = "Тортури Минулого",
    D = "$N, я плачу за те, що сталося в минулому. Як і цей кристал, ельфи, як раса, були розбиті. Я не знаю, чи зможуть колись ці уламки знову стати єдиним цілим, але мій смуток полегшився тим, що я змогла допомогти тобі з цим маленьким завданням. $B$BМи не повинні забувати минуле, $N…$B$BБудь ласка, віднеси Кристал Зін-Малора назад до озера Кел’Теріл. Ти мусиш знайти духа вищевродженого, який усвідомлює помилку того, що було зроблено так давно. Покажи духу, що ми все виправили.",
    O = "Віднесіть Кристал Зін-Малора до озера Кел’Теріл у Зимових Ключах і знайдіть духа вищевродженого, який захоче з вами поговорити.",
    P = "Currrrrsed... Forevvvverrrr...",
    C = "Будь ласка, відпусти менеееее...",
},

[5249] = {
    en = "To Winterspring!",
    T = "До Зимових Ключів!",
    D = "У Зимових Ключах, на північ звідси, є багато стародавніх ельфійських руїн. Це сувора земля, але вона приховує багато таємниць і місць для дослідження.$B$BЗ усією моєю роботою тут у Сквернолісі, у мене не було можливості поїхати до Зимових Ключів. Але немає причин, чому б тобі туди не вирушити!$B$BПоки ти там, шукай Вінда Ночегонця. Він проводить більшу частину часу в селі Зорепад і знає багато про цю місцевість.",
    O = "Знайдіть село Зорепад у Зимових Ключах і поговоріть із Віндом Ночегонцем.",
    P = "",
    C = "Друг Айві Лістобіг? Приємно познайомитися, $N.",
},

[5250] = {
    en = "Starfall",
    T = "Зорепад",
    D = "У Зимових Ключах, на північ від Сквернолісу, є багато стародавніх ельфійських руїн. Це сувора земля, але вона приховує багато таємниць і місць для дослідження.$B$BМої дослідження тут настільки мене займають, що я давно не мав можливості поїхати до Зимових Ключів. Але немає причин, чому б тобі не вирушити туди і не дослідити руїни.$B$BПоки ти там, шукай Вінда Ночегонця. Він проводить більшу частину часу в Зорепаді і знає багато про цю місцевість.$B$BСкажи йому, що ти мій учень…",
    O = "Знайдіть Зорепад у Зимових Ключах і поговоріть із Віндом Ночегонцем.",
    P = "",
    C = "Учень Даріна Лайтвінда? Приємно познайомитися, $N.",
},

[5251] = {
    en = "The Archivist",
    T = "Архіваріус",
    D = "Будь-що, доведене до крайності, становить небезпеку для нашого світу, $N. Візьмімо, наприклад, Багряний Хрестовий Похід. Чи вважаєш ти, що їхня сліпа фанатичність служить вищому благу? Скількох невинних вони знищили в ім’я Світла?$B$BБогохульники, усі до одного!$B$BОдин із них особливо мене цікавить; Архіваріус Ґалфорд зі Стратгольма: людина, яка охороняє найцінніші документи Хрестового Походу. Знищ його і спали його архіви! Якщо тобі це вдасться, повертайся до мене, і я винагороджу тебе.",
    O = "Вирушайте до Стратгольма і знайдіть Архіваріуса Ґалфорда з Багряного Хрестового Походу. Знищте його і спаліть Багряний Архів.",
    P = "Пам’ятайте, $N – ми повинні бути толерантними, але незмінними у своїх переконаннях!",
    C = "Чудово, $N! Роки розвідки, втрачені! Багряний хрестовий похід напевно відчує цей удар найближчими тижнями.",
},

[5252] = {
    en = "Remorseful Highborne",
    T = "Каяття Вищевродженої",
    D = "…Кристал…$B$BВищевроджені тут затуманені власним нещастям…$B$BЯ сповнена скорботи, але я усвідомлюю помилку того, що сталося так давно. Хоча немає способу змінити минуле, я тепер у мирі, знаючи, що ти повернув Кристал Зін-Малора…$B$BТи мусиш повернути його…$B$BВін мусиить бути повернутий.",
    O = "Поговоріть із Віндом Ночегонцем у селі Зорепад і запитайте про належне місце для Кристала Зін-Малора.",
    P = "Минув деякий час, як ти пішов, $N. Як у вас справи?",
    C = "Це... те, що я думаю?",
},

[5253] = {
    en = "The Crystal of Zin-Malor",
    T = "Кристал Зін-Малора",
    D = "Дуже вражаюче, $N.$B$BКристал Зін-Малора ніколи не може бути повернутий до храму, який, як ти знаєш, лежить у руїнах. Але я вважаю, що твої зусилля виправити зло минулого не повинні залишитися без винагороди.$B$BЗнайди Верховного Друїда Фандрала Оленерога в Дарнассусі і принеси кристал йому, $N. Він має бути в руках тих, хто не зловживатиме його силою. Судячи з усього, лише небагато з найсильніших магів зможуть контролювати таку силу.",
    O = "Доставте Кристал Зін-Малора до Верховного Друїда Фандрала Оленерога в Дарнассусі.",
    P = "Так, $R?",
    C = "Я чув про кристал Зін-Малор; користувач кристала стає здатним до неймовірної таємничої сили, але тільки якщо він справді гідний. Мене вразило те, що ви не лише знайшли кристал, але й усвідомили власні обмеження та не намагалися використати кристал самостійно.$B$BThank за те, що принесли його мені, $N. Ми збережемо його в безпеці, і нехай прокляті духи, які колись охороняли розбитий кристал, нарешті заспокояться.",
},

[5261] = {
    en = "Eagan Peltski$b$ber",
    T = "Еаґан Шкуродер",
    D = "Еаґан Шкуродер шукає когось, хто полюватиме на вовків для нього. Це добра новина, адже останнім часом ми бачимо все більше вовків у Долині Північнокраю.$B$BЯкщо тобі цікаво, поговори з Еаґаном. Він біля абатства, зліва.",
    O = "Поговоріть із Еаґаном Шкуродером.",
    P = "",
    C = "Це правда.  Я шукаю когось, щоб вполювати мені вовків!  Ви та людина?",
},

[5262] = {
    en = "The Truth Comes Crashing Down",
    T = "Правда Виходить на Світло",
    D = "Ти намагаєшся зібрати свої думки, коли пил осідає в залі. Ти перебираєш у пам’яті події, що щойно відбулися, і все ще не можеш осягнути всю серйозність ситуації.$B$BВеликий Хрестоносець Багряного Хрестового Походу — демон? І не просто демон, а брат Варімтраса, архлорда Підмістя?$B$BТи обережно ховаєш відрубану голову жахолорда у свій наплічник. Безперечно, ніхто не повірить твоїй розповіді без доказів.$B$BГерцог Ніколас Зверенгофф мусить дізнатися про це негайно!",
    O = "Віднесіть Голову Балназзара до Герцога Ніколаса Зверенгоффа в Східних Зачумлених Землях.",
    P = "Що у тебе там, $N?",
    C = "Що це означатиме для Хрестового походу? Чи можливо, що вони були під контролем цього демона? Мимоволі слугувати пішаками більшого зла?",
},

[5263] = {
    en = "Above and Beyond",
    T = "Понад Усе",
    D = "Ти демонструєш природний хист до руйнування, і ти виконуєш накази. Рідко можна побачити ці дві риси разом. Я починаю думати, що ти можеш стати чудовим інструментом божественного правосуддя.$B$B<Зверенгофф стискає руки перед своїм обличчям.>$B$BПомічник Кел’Тузада править Стратгольмом. Доведи мені, що ти — мій чемпіон. Знищ Барона Рівендера і повернися до мене з його головою.",
    O = "Вирушайте до Стратгольма і знищте Барона Рівендера. Візьміть його голову і поверніться до Герцога Ніколаса Зверенгоффа.",
    P = "Барон убив більше людей, ніж ви, ймовірно, бачили за своє життя.",
    C = "Минуло багато років з тих пір, як я прийняв чемпіона в наші лави. Ви перший, хто отримав аудієнцію з лордом Максвеллом за багато років.",
},

[5264] = {
    en = "Lord Maxwell Tyrosus",
    T = "Лорд Максвелл Тірос",
    D = "Я збираюся удостоїти тебе великої честі, $N.$B$BЛорд Максвелл бажає винагородити тебе за твою службу Світанку Срібла!$B$BМинули роки відтоді, як Максвелл давав аудієнцію чужинцям.",
    O = "Поговоріть із Лордом Максвеллом Тіросом. Він усередині церкви.",
    P = "",
    C = "Ти гідний союзник, $N. Ви пожнете плоди своєї відданості.",
},

[5265] = {
    en = "The Argent Hold",
    T = "Сховище Світанку",
    D = "Протягом років Сховище Світанку залишалося замкненим. Ніхто не був гідний зазирнути всередину і взяти звідти силу Світанку Срібла — до сьогодні.$B$BСховище Світанку тепер відкрите для тебе, $N.",
    O = "Відкрийте Сховище Світанку і отримайте свою нагороду.",
    P = "",
    C = "ой...",
},

[5281] = {
    en = "The Restless Souls",
    T = "Неспокійні Душі",
    D = "Є ті, хто трагічно загинув під час падіння Стратгольма. Багато хто сам забрав своє життя, кинувшись у незліченні полум’я палаючого міста, замість того, щоб стати одним із Скари.$B$BТепер вони блукають вулицями Стратгольма як неспокійні духи.$B$BМи мусимо допомогти їм, $N!$B$BУ мене є знайомий на ім’я Еґан, який творив дива з привидами і душами. Знайди його. Він блукає Східними Зачумленими Землями, поблизу Стратгольма, випробовуючи свої винаходи.",
    O = "Знайдіть Еґана. Ви знаєте лише, що востаннє його бачили біля Стратгольма.",
    P = "",
    C = "Ален нарешті знайшов когось досить сміливого, еге ж?",
},

[5282] = {
    en = "The Restless Souls",
    T = "Неспокійні Душі",
    D = "Я черпаю свою силу — мою волю продовжувати жити і дихати — з безмежної ненависті до Скари і всього, що вони зробили. Однак я не фанатик. Є ті, як Багряний Хрестовий Похід, які швидше знищать невинних нежитей, ніж виявлять до них хоч краплю співчуття.$B$BЦе приводить мене до ось чого: Мій бластер. Він звільнить замучені душі зі Стратгольма.$B$BВикористовуй його на привидах, що блукають розграбованими вулицями. Звільни їхні душі.",
    O = "Використовуйте Бластер Еґана на примарних і спектральних жителях Стратгольма. Коли неспокійні душі вирвуться зі своїх примарних оболонок, використайте бластер ще раз — і свобода буде їхньою!$B$BЗвільніть 15 Неспокійних Душ і поверніться до Еґана.",
    P = "Співчуття – це те, що відрізняє нас від тварин, $N. Пам'ятайте, що...",
    C = "<Еган витирає сльозу з очей.>$B$BDid ти бачиш мою маму, $N? Ви звільнили її?$B$BYou є яскравим прикладом порядності. За твої біди...",
},

[5283] = {
    en = "The Art of the Armorsmith",
    T = "Мистецтво Бронника",
    D = "Отже, ти зробив розумний вибір.$B$BМіж мною та старим Іронусом немає ніякої любові. Цей нікчемний іграшковий майстер знає, хто тут справжній ремісник.$B$BСправжні великі війни виграються завдяки добрій обороні. Коли настане час діяти, ніякий напад тобі не допоможе.$B$BГаразд, давай до роботи. Усе, що тобі потрібно зробити, — це показати мені, що в тебе є природний талант. Після цього я витягну всі нечистоти, що в тобі залишилися, і сформую з тебе бронника. Ти ж знаєш, як робити вишуканий міфрил, чи не так?",
    O = "Щоб стати Бронником, ви мусите виготовити наступні предмети і повернути їх до Ґрумнуса: 4 Вишукані Міфрилові Шоломи, 2 Вишукані Міфрилові Черевики, 1 Вишукана Міфрилова Кіраса.",
    P = "А, ніщо не схоже на гарний ковальський загар. Ви можете визначити, хто має справді гарну засмагу, за лініями фартуха.",
    C = "Хай буде так, $N. Після цього вже немає можливості повернутися назад. Ще не пізно стати виробником іграшок, е-е, майстром зброї.$B$BI вірю, ти приймеш правильне рішення.",
},

[5284] = {
    en = "The Way of the Weaponsmith",
    T = "Шлях Зброяра",
    D = "Як зброяр ти виявиш, що найчастіше герої та шукачі пригод приходитимуть до тебе за спорядженням. Хоча робоче навантаження іноді може бути нестерпним, багатства більш ніж компенсують біль у спині та попіл у легенях.$B$BО так, $N, зброярі — це ті, у кого все золото!$B$BЯкщо ти хочеш приєднатися до наших лав, тобі потрібно показати мені, що ти можеш заробити мені срібло чи два — я маю на увазі, показати мені, що ти маєш усе, щоб бути тим, до кого звертаються, коли потрібна зброя вищої якості. До роботи!",
    O = "Щоб стати Зброярем, ви мусите виготовити наступні предмети і повернути їх до Іронуса: 4 Місяцесталеві Широкі Мечі, 4 Масивні Залізні Сокири, 2 Важкі Міфрилові Сокири і 2 Великі Чорні Булави.",
    P = "<Айронус зайнятий складанням золотих монет у акуратні купки.>",
    C = "На часі! Мене чекають клієнти.$B$BGive хто тут і зверніть увагу. Ви збираєтеся зробити перший крок у своїй кар'єрі майстра зброї.",
},

[5301] = {
    en = "The Art of the Armorsmith",
    T = "Мистецтво Бронника",
    D = "Задоволення. Це те, що я отримую від молота і ковадла. Бачити гордого воїна Орди, захищеного моєю сталлю, нагадує мені, що таке бути живим. Це залежність, від якої я не наважуся відмовитися, $N.$B$BЯ не можу дати тобі це задоволення, лише направити на шлях. Як і в усіх життєвих починаннях, шлях бронника — це подорож.$B$BЯкщо ти хочеш бути одним із небагатьох обраних, тобі потрібно лише попросити, і я навчу тебе, але спочатку ти мусиш виконати завдання.",
    O = "Щоб стати бронником, ви мусите виготовити наступні предмети і повернути їх до Окотоса: 4 Вишукані Міфрилові Шоломи, 2 Вишукані Міфрилові Черевики, 1 Вишукана Міфрилова Кіраса.",
    P = "Буду стукати по сталі, аж дихання перехопить.",
    C = "Це останній крок перед початком нової кар’єри майстра зброї, $N. Якщо ви вирішите відмовитися, це буде ваш останній шанс. В іншому випадку приготуйтеся до славного життя.",
},

[5302] = {
    en = "The Way of the Weaponsmith",
    T = "Шлях Зброяра",
    D = "Одного дня я створю легендарний молот. Молот, гідний Вождя!$B$BЦе справа мого життя, $N. Моя пристрасть. Я бачу, що ти маєш потенціал бути серед нас, одним із нас — зброярем. Я той, хто може допомогти тобі розкрити цей потенціал.$B$BПросте завдання — усе, що тобі потрібно виконати. Просте для когось із твоїми винятковими навичками.",
    O = "Щоб стати Зброярем, ви мусите виготовити наступні предмети і повернути їх до Борґоша: 4 Місяцесталеві Широкі Мечі, 4 Масивні Залізні Сокири, 2 Важкі Міфрилові Сокири і 2 Великі Чорні Булави.",
    P = "На славу Орди!",
    C = "Це останній крок перед початком нової кар’єри майстра зброї, $N. Якщо ви вирішите відмовитися, це буде ваш останній шанс. В іншому випадку готуйтеся бути поглиненими знаннями!",
},

[5305] = {
    en = "Sweet Serenity",
    T = "Солодка Безтурботність",
    D = "У стінах Багряного Бастіону лежить солодка Безтурботність. Багряний Молотник охороняє рецепт своїм життям. Переможи його і принеси мені його фартух. За це я навчу тебе стати молотником.$B$BЗрозумій: обравши шлях молотника, ти більше не зможеш обрати шлях мечника чи сокирника.",
    O = "Вирушайте до Стратгольма і вбийте Багряного Молотника. Заберіть Фартух Багряного Молотника і поверніться до Ліліт.",
    P = "Його фартух! Де це?",
    C = "Нехай ти розіб'єш багато мізків, $N!",
},

[5306] = {
    en = "Snakestone of the Shadow Huntress",
    T = "Зміїний Камінь Тіньової Мисливиці",
    D = "Не дай її красі обдурити тебе, $c. Тіньова Мисливиця Вош’ґаджін — смертельно небезпечна і божевільна.$B$B<Кілрам вказує на шрам на своєму обличчі.>$B$BТак, це вона мені дала — назвала це любовним дотиком.$B$BНастав час для помсти.$B$BТи можеш знайти Вош’ґаджін у Шпилі Чорної Скелі. Убий її і повернися до мене з її зміїним каменем. Зроби це, і я навчу тебе шляхів сокирника.",
    O = "Вирушайте до Шпиля Чорної Скелі і вбийте Тіньову Мисливицю Вош’ґаджін. Заберіть Зміїний Камінь Вош’ґаджін і поверніться до Кілрама.",
    P = "Легенда свідчить, що одне використання зміїного каменю Вош'гаджина збереже гостроту бритви сокири протягом 1000 років!",
    C = "Знання - це сила!",
},

[5307] = {
    en = "Corruption",
    T = "Псування",
    D = "Якщо я різкий із тобою, це з причини. Плани створення великого клинка, Псування, були вкрадені Чорною Гвардією: елітними скелетними одиницями Барона Рівендера.$B$BТак, Барона Рівендера зі Стратгольма.$B$BМечник Чорної Гвардії тепер охороняє ці плани своєю… нежиттю.$B$BУбий його і поверни доказ цього вчинку, і я навчу тебе шляхів мечника.",
    O = "Знайдіть Мечника Чорної Гвардії в Стратгольмі і знищте його. Заберіть Знак Чорної Гвардії і поверніться до Серіла Скаражича.",
    P = "Ти забув, що тобі доручили, $N?",
    C = "Має бути очевидно, що меч завжди є найкращим вибором.",
},

[5321] = {
    en = "The Sleeper Has Awakened",
    T = "Сплячий Прокинувся",
    D = "Я прямував до Фортеці Маестри, щоб зустрітися з Ліладріс Місяцерікою, але вирішив зупинитися тут і трохи подрімати. Відтоді, як я прокинувся з Смарада Сну, я весь час такий сонний…$B$B<позіхає>$B$BЧи не могли б ви показати мені дорогу? Я розумію, що Фортеця Маестри на південь звідси, уздовж дороги в Ясенедолі. Це може бути небезпечно, тож я сподіваюся, у вас є друзі, які приєднаються до нас.$B$BНаостанок, я можу заснути, тож якщо вам потрібно буде мене розбудити, будь ласка, використайте мій ріг. Ви знайдете його в скрині тут.",
    O = "Супроводіть Керлоніана Вічнотінь до Ліладріс Місяцеріки у Фортеці Маестри в Ясенедолі.",
    P = "Керлоніан прибув?",
    C = "О, я такий щасливий, що Kerlonian це зробив! І я впевнений, що знайду його спить десь тут, чи не так?$B$BThank тобі за те, що ти показав йому дорогу, $N.",
},

[5341] = {
    en = "Barov Family Fortune",
    T = "Спадщина Родини Барових",
    D = "У Школі Некромантії лежить спадщина родини Барових. Я, Алексі Барів, один із двох останніх спадкоємців дому Барових. Мій брат, Велдон, — другий.$B$BВелдон, жалюгідний боягуз, втік під час війни і таким чином зберіг своє нікчемне існування як людина.$B$BТепер він шукає документи, щоб привласнити спадщину собі. Поверни документи раніше, ніж мій брат, і я зроблю тебе багатим понад твої найсміливіші мрії!",
    O = "Вирушайте до Школи Некромантії і поверніть спадщину родини Барових. Чотири документи складають цю спадщину: Документ на Каер Дарроу; Документ на Брілль; Документ на Млин Таррен; і Документ на Південнобережжя. Поверніться до Алексі Барова, коли виконаєте це завдання.",
    P = "Схиліть голову в моїй присутності, $r. Я все-таки дворянин, а ти безмідний селянин.",
    C = "Чудова робота, $R. Тепер, щоб забезпечити свою спадщину...",
},

[5342] = {
    en = "The Last Barov",
    T = "Останній Барів",
    D = "Звісно, з моїм братом, який все ще живий, можуть виникнути суперечки щодо головного спадкоємця сімейної спадщини. Такого не можна допустити.$B$BТакий низький пройдисвіт, як ти, сподіваюся, не цурається холоднокровного вбивства.$B$BЦе просте завдання, і я очікую, що ти його виконаєш; якщо, звісно, ти хочеш отримати свою нагороду.$B$BВелдон сидить під захистом Альянсу в Таборі Холодновітру, на сході. Убий його, принеси його голову.$B$B<Алексі позіхає.>$B$BПоспіши.",
    O = "Вирушайте до Табору Холодновітру — території Альянсу — і вбийте Велдона Барова. Візьміть його голову і поверніться до Алексі Барова.$B$BПопереджаю, Велдон, ймовірно, буде добре захищений покидьками Альянсу.",
    P = "Забезпечте мою долю і поділіться здобиччю.",
    C = "Чудово! Тепер тільки я володію владою та багатством будинку Барових!$B$B<Alexi кидає в тебе велику сумку.>$B$BAnd тримай здачу, ти брудна тварина.",
},

[5343] = {
    en = "Barov Family Fortune",
    T = "Спадщина Родини Барових",
    D = "Мій дорогий брат Алексі. Яким дурнем я був, що пощадив його життя. Я дивився в обличчя ворога, одного з нежиті, і відпустив його.$B$B<Велдон плює.>$B$BТепер він шукає МОЮ спадщину. Цього просто не можна допустити.$B$BЗнайди документи моєї родини раніше, ніж цей мерзенний виродок покладе на них свої кістляві руки, і я винагороджу тебе величезними багатствами. Вони лежать у руїнах Школи Некромантії. Поспіши!",
    O = "Вирушайте до Школи Некромантії і поверніть спадщину родини Барових. Чотири документи складають цю спадщину: Документ на Каер Дарроу; Документ на Брілль; Документ на Млин Таррен; і Документ на Південнобережжя. Поверніться до Велдона Барова, коли виконаєте це завдання.",
    P = "Схиліть голову в моїй присутності, $R. Я все-таки дворянин, а ти безмідний селянин.",
    C = "Чудова робота, $R. Тепер, щоб забезпечити свою спадщину...",
},

[5344] = {
    en = "The Last Barov",
    T = "Останній Барів",
    D = "З документами в руках залишилося зробити лише одну річ. Алексі мусить бути убитий. З його смертю мені більше не доведеться хвилюватися, що якась безпринципна банда найманців полюватиме за моєю головою.$B$BЦе просте завдання. Алексі ховається під захистом Орди — на Бастіоні.$B$BНі, я не очікую, що ти просто підійдеш і зарубав його, я хочу його голову! Як ти її добудеш… що ж, це залежить від тебе. Така поведінка нижче моєї благородної натури.",
    O = "Вирушайте на Бастіон — територію Орди — і вбийте Алексі Барова. Візьміть його голову і поверніться до Велдона Барова.$B$BПопереджаю, Алексі, ймовірно, буде добре захищений брудом Орди.",
    P = "Ви ж хочете оплатити, чи не так?",
    C = "Це славний день! Нарешті віспину хати Барових усунули і мою долю захищено!$B$BTake це й покинь мене з очей, селянино.",
},

[5361] = {
    en = "Family Tree",
    T = "Родинне Дерево",
    D = "Мій брат Натака розміщений у Фортеці Примарного Вартівника в Спустошенні. Я хотів би попросити тебе… чи не могли б ви передати йому цей звіт? Минуло вже більше року відтоді, як я востаннє писав, відтоді спостерігається незвична активність кентаврів, і він має бути повідомлений.$B$BВирушай до Кам’янешпичкової Гори на північ від Перехрестя, а потім на захід до Обвугленої Долини. Звідти прямуй на південь до Спустошення; там ти знайдеш дорогу, що веде на південь до Фортеці Примарного Вартівника.",
    O = "Доставте Звіт Скелебійця Довгорога до Натаки Довгорога у Фортеці Примарного Вартівника в Спустошенні.",
    P = "Які у вас новини, $C! Кажете, повідомлення від мого брата? Ну тоді здавай звіт!",
    C = "Я не знаю, який зв’язок у вас з моїм братом, але, здається, він довіряє вам, $C.$B$BI, я Натака Лонгхорн, і я хотів би вітати вас у Ghost Walker Post, у нас багато потреб у $C! Поговоріть з іншими, можливо, ви тут потрібні.",
},

[5381] = {
    en = "Hand of Iruxos",
    T = "Рука Іруксоса",
    D = "Палаючий Клинок володіє Демоновим Ящиком. Усередині нього лежить могутня Рука Іруксоса. Палаючий Клинок використовує її, щоб відкривати демонічні портали в Ковені Маннорок. Ми мусимо зупинити потік демонів, що входять у наш світ, $N!$B$BВикористовуй цей демонічний кайло на червоному кристалі у Фортеці Громової Сокири, щоб отримати доступ до Демонового Ящика.",
    O = "Заберіть Демонів Ящик із Фортеці Громової Сокири і поверніть його разом із Демоновим Кайлом до Тайґи Мудрошерсті в селі Тіньового Полювання.",
    P = "$n, у вас є Скринька Демона?",
    C = "Ах, Скринька Демона. Дай це мені, $C, і я відкрию... і таким чином відкрию тобі Руку Іруксоса.$B$B",
},

[5382] = {
    en = "Doctor Theolen Krastinov, the Butcher",
    T = "Доктор Теолен Крастинов, М’ясник",
    D = "Крастинов відповідальний за смерть тисяч. Він мусить бути покараний, справедливість має бути звершена.$B$BЗнайди його і завдай йому тих страждань, які він заподіяв незліченним невинним. Після того, як він буде знищений, спали наші останки. Перетвори їх на попіл, $N.",
    O = "Знайдіть Доктора Теолена Крастинова в Школі Некромантії. Знищте його, а потім спаліть Останки Еви Саркгофф і Останки Люсьєна Саркгоффа. Поверніться до Еви Саркгофф, коли завдання буде виконано.",
    P = "М'ясника треба зупинити!",
    C = "Я відчуваю, як мій дух зцілюється, $N. Ви зробили мені і моєму чоловікові велику послугу, але я впевнена, що потрібно зробити ще більше.",
},

[5383] = {
    en = "",
    T = "Сумка Жахів Крастинова",
    D = "Ти відкриваєш сумку і знаходиш різні інструменти для тортур. Серед цього начиння твою увагу привертає дивний предмет: флакон із кров’ю — досі теплий на дотик.$B$BТи думаєш, що Саркгоффи могли б зацікавитися твоїм відкриттям.",
    O = "Віднесіть Сумку Жахів до Еви Саркгофф на Каер Дарроу.",
    P = "",
    C = "",
},

[5384] = {
    en = "Kirtonos the Herald",
    T = "Кіртонос, Вісник",
    D = "Ось воно, $N.$B$B<Ева вказує на флакон у сумці.>$B$BКров невинних. Найчистіша кров, що використовується для заспокоєння господаря Крастинова.$B$BСаме з цією кров’ю можна викликати Кіртоноса. Тож саме з цією кров’ю Кіртонос мусить бути знищений.$B$BВізьми кров на ґанок. Постав її на жаровню. Кіртонос прийде — він не зможе встояти. Коли він з’явиться, розв’яжи на нього лють і гнів тисячі невинних смертей.$B$BЯкщо тобі це вдасться, ти отримаєш більше, ніж просто нашу вдячність.",
    O = "Поверніться до Школи Некромантії з Кров’ю Невинних. Знайдіть ґанок і покладіть Кров Невинних у жаровню. Кіртонос прийде поласувати твоєю душею.$B$BБийся відважно, не поступайся ні на крок! Знищ Кіртоноса і повернися до Еви Саркгофф.",
    P = "Будьте обережні, Кіртонос - досвідчений боєць.",
    C = "Зі смертю Кіртоноса завершується розділ у жахливій історії про Схоломантію. Однак є ще багато чого, що потрібно зробити. Інші тут тепер знають про ваші хоробрі вчинки. Візьми це, $N. Це частинка нашої власної сутності. Це дозволить вам спілкуватися з іншими загубленими душами Каер Дарроу.",
},

[5385] = {
    en = "The Remains of Trey Lightforge",
    T = "Останки Трея Світлокованого",
    D = "Ти обережно піднімаєш мішок і готуєшся повернутися до Джессір Місяцедужки на межі Сквернолісу та Ясенедолу. Сподіваюся, паладину віддадуть належну шану, коли ти передаси його останки його друзям.",
    O = "Поверніть Останки Трея Світлокованого до Джессір Місяцедужки в Сквернолісі.",
    P = "Як справи пройшли в Джеденарі, $N?",
    C = "Ви зробили це! Слава Елуні та будь-яким силам, яким ви поклоняєтеся, $N. Цього дня ви зробили почесну і благородну справу. Я впевнений, що Арко'нарін буде радий, що ви не лише знайшли час, щоб врятувати її, але й убити істоту, яка катувала одного з її найкращих друзів.$B$BI хотів би я зробити для вас більше, але, будь ласка, візьміть це.",
},

[5386] = {
    en = "Catch of the Day",
    T = "Улов дня",
    D = "Запах смаженої риби давно не відчувався тут, на Посту Примарного Воїна. Тролі в Селі Тінелову найкраще ловлять рибу... але, на жаль, через активність кентаврів у мене мало часу, щоб вирушити до них. Хм...$B$BЗроби мені послугу і вирушай до Села Тінелову. Поговори з місцевим рибалкою Джинаром'Зілленом і принеси мені мою улюблену рибу — кривобрюшку. Дорога на південь звідси приведе тебе на захід до села тролів.",
    O = "Поговори з Джинаром'Зілленом у Селі Тінелову, а потім принеси Натаці Довгорогу 2 рибини кривобрюшки.",
    P = "Коли я згадую про смажену рибу Кровавку, у мене поколює, і з рота тече сльоза... Маєш щось при собі?",
    C = "Ти рятівник, $N! Цю рибу Кровочереву можна їсти сирою.$B$B<Натака починає слиновидіти.>$B$BHere ви йдете — виберіть один із цих продуктів як плату за цю рибу.",
},

[5401] = {
    en = "Argent Dawn Commission",
    T = "Посвідчення Світанку Аргенту",
    D = "",
    O = "",
    P = "",
    C = "Усі, хто бореться зі злом від імені Сріблястої Зорі, повинні отримати наше доручення.  Одягнувши їх, ви отримаєте право вимагати нагороди, які можуть запропонувати наші квартирмейстери.$B$BWhile за дорученням ви зможете отримати Камені Бича від убитого Скорджа; це знаки розрізнення, якими вони іноді володіють.  Придбайте ці знаки відмінності і принесіть їх мені.  За кожен набір, який ви здасте, ви отримаєте наш маркер героїзму — жетон доблесті Сріблястого світанку.$B$BAchieve ваша доля, $c — приєднуйтеся до бою сьогодні!",
},

[5402] = {
    en = "Minion's Scourgestones",
    T = "Камені Плеті слуг",
    D = "",
    O = "",
    P = "Камінь Плеча Міньйона — знак розрізнення рядового складу Плеча.  Іноді їх можна знайти на слабших військах, розташованих у Чумних землях, хоча термін ",
    C = "Вітаю, $N – я радий нагородити вас жетоном доблесті Срібного світанку! $B$BThe жетони служать двом цілям. По-перше, вони можуть бути використані для посилення вашого становища в межах Серебряної Зорі; щоб зробити це, ви можете скористатися варіантами та нагородами, які зарезервовані для наших почесних і шанованих союзників. По-друге, їх можна передати нашим квартирмейстерам разом із монетами як плату за деякі з найцінніших предметів Світанку.$B$BWhatever ви вирішуєте, знайте, що ви заробляєте свою комісію. молодець!",
},

[5403] = {
    en = "Invader's Scourgestones",
    T = "Камені Плеті загарбників",
    D = "",
    O = "",
    P = "Камінь Плеча Загарбника — знак розрізнення елітних військ Плета.  Іноді їх можна знайти на сильніших військах, розташованих у Чумних землях.  Вбити таку істоту – справді непросте завдання, але воно має насолоджуватися разом із дорученням подолати зло.$B$BThe Argent Dawn наразі пропонує жетон доблесті в обмін на десять таких символів.  Принесіть їх мені сюди, і я подбаю, щоб ви отримали свою справедливу винагороду.",
    C = "Вітаю, $N – я радий нагородити вас жетоном доблесті Срібного світанку! $B$BEach жетон доблесті, розданий гідним одержувачам, є ознакою того, що хвиля повертається проти Бича. Оскільки все більше і більше героїв борються з Бичем на їхніх власних землях, Аргентський світанок безсумнівно буде на передовій, коли прийде час вести війну з найбільшим злом Бича. Я сподіваюся, що мужність, яку ви продемонстрували, щоб отримати свій жетон, також матиме успіх!",
},

[5404] = {
    en = "Corruptor's Scourgestones",
    T = "Камені Плеті спотворених",
    D = "",
    O = "",
    P = "Камінь Плеча Розбещувача — знак розрізнення володарів Плеча.  Могутня істота, яка займає владну позицію над Бичем, завжди матиме таку владу.  Убити таку зловмисну ​​істоту, безперечно, сприяло б справі Сріблястої Зорі та всім благим цілям!$B$BOn від імені Сріблястої Зорі, я дам тобі знак доблесті в обмін на один-єдиний цей знак.  Будьте обережні, купуючи його, $N — з такими могутніми істотами не можна жартувати.",
    C = "Вітаю, $N – я радий нагородити вас жетоном доблесті Срібного світанку!$B$BTo отримання жетона доблесті таким чином означає, що ви справжній герой у справі добра. Ми цінуємо всі зусилля, докладені для боротьби з Бичем, але знищити одного з їхніх лідерів означає справді завдати їм нищівної поразки!$B$BFor Світанок, моя $Gbrother:сестро;!",
},

