[5421] = {
    en = "Fish in a Bucket",
    T = "Риба у відрі",
    D = "",
    O = "",
    P = "Я винагороджу кожного, хто трохи полегшить моє життя... Мені подобається робити якомога менше, мій!$B$BBelow у доках тут, у Shadowprey Village, у мене багато пасток для молюсків.  Якщо ви досить люб’язні, щоб виконати мою роботу і зібрати мені моїх молюсків, тоді я винагороджу вас чимось, чого ви хочете... отримати мій дрифт, mon?  За кожні п’ять молюсків, які ви мені принесете, я дам вам чудову рибу Кровочереву!",
    C = "Дорогий мій, ніщо не може зрівнятися з роботою, особливо якщо її виконує хтось інший... а?",
},

[5441] = {
    en = "Lazy Peons",
    T = "Ліниві пеони",
    D = "Прокляті пеони! Вони старанно працюють, збираючи деревину з долини, але постійно дрімають! Мені потрібен хтось, хто допоможе тримати пеонів у строю.$B$BТи виглядаєш підходящим $r для цього завдання. Ось, візьми цю дубинку і використовуй її на лінивих пеонах, які сплять на роботі. Добрий удар змусить їх одразу повернутися до праці! Поверни дубинку, коли закінчиш.$B$BНікчемні, ліниві пеони...",
    O = "Використовуй Дубинку Наглядача на лінивих пеонах, коли вони сплять. Розбуди 5 пеонів, а потім поверни Дубинку Наглядача до Наглядача Тазз'ріла в Долині Випробувань.",
    P = "Немає ледачих...$B$B А? У вас є мій блекджек? Ви спіймали якихось пеонів, які спали на роботі?!",
    C = "Добре, добре. Можливо, наступного разу вони двічі подумають, перш ніж розслабитися! Дякуємо за допомогу!",
},

[5461] = {
    en = "The Human, Ras Frostwhisper",
    T = "Людина, Рас Морозошелест",
    D = "Нежить боїться життя так само, як живі бояться смерті. Не рідкість, коли розумна нежить повністю знищує всі залишки свого попереднього життя після перетворення.$B$BНа жаль, щоб створити артефакт, здатний повернути Раса Морозошелеста до смертного стану, нам потрібен пам’ятний предмет із його людських років.$B$BТи мусиш вирушити до зруйнованого міста Стромґард, дому Морозошелеста, і пошукати такий предмет. Нехай удача буде з тобою, $N.",
    O = "Вирушай до Нагір’я Араті, до руїн Стромґарду. Пошукай у Стромґарді Пам’ятний Предмет. Якщо знайдеш такий предмет, повернися з ним до Маґістрата Мардука.",
    P = "Пам’ятний сувенір — рідкісна знахідка, $N.",
    C = "Я сумнівався в можливості існування такого предмета. Це, безсумнівно, відкриває неймовірну можливість — яку ми не повинні змарнувати.$B$BPrepare ти сам, $N, бо те, що я збираюся попросити тебе, заведе тебе в глибини пекла.",
},

[5462] = {
    en = "The Dying, Ras Frostwhisper",
    T = "Вмираючий, Рас Морозошелест",
    D = "На оскверненій землі пам’ятний предмет мусить бути налаштований.$B$BПодейкують, що у Стратгольмі Морозошелест піддався Королю-Личу. На тих закривавлених землях він віддав своє життя — добровільно і з мотивом — щоб стати одним із безсмертних.$B$BСаме ці землі потрібно знайти.$B$BЄ один, нежить-дисидент Плеті, звільнений Королевою Банші, але вірний справі Світанку Аргенту. Знайди його: Леоніда Бартоломея Преподобного. Він може знати більше. Шукай Каплицю Світла Надії, $N.",
    O = "Вирушай до Каплиці Світла Надії в Східних Зачумлених Землях і знайди Леоніда Бартоломея Преподобного. Покажи йому Пам’ятний Предмет і розкажи все, що ти дізнався.",
    P = "Не ставте питань, на які не хочете отримати відповіді.",
    C = "<Леонід дивиться на сувенір.>$B$BYour неприємність викликає спогади, які, як я сподівався, ніколи не відновляться.",
},

[5463] = {
    en = "Menethil's Gift",
    T = "Дар Менетіла",
    D = "Я бачив, як людина, Рас Морозошелест, присягнув своєю безсмертною душею Королю-Личу. Він приставив кинджал до свого горла і, посміхаючись, розрізав від вуха до вуха. Його тіло впало всередині пентаграми. Король-Лич стояв над поваленим магом, і одним рухом Рас Морозошелест, лич, народився.$B$B<Леонід дивиться на землю, а потім піднімає погляд на тебе.>$B$BТак, $r, я пам’ятаю. Те, що ти шукаєш, має назву — Дар Менетіла: земля, благословенна Королем-Личем, свята земля для Плеті.",
    O = "Вирушай до Стратгольма і знайди Дар Менетіла. Помісти Пам’ятний Предмет на нечисту землю.",
    P = "Місцевість навколо Менетилового дару надзвичайно холодна.",
    C = "Ви кладете сувенір на спотворену землю.",
},

[5464] = {
    en = "Menethil's Gift",
    T = "Дар Менетіла",
    D = "Душа полеглого чіпляється за те, що символізує її попереднє життя, і перетворює предмет на зв’язаний із душею пам’ятний предмет. Ти піднімаєш предмет і кладеш його до своєї сумки.",
    O = "Віднеси Зв’язаний із Душею Пам’ятний Предмет до Леоніда Бартоломея в Східних Зачумлених Землях.",
    P = "<Леонід здригається.>",
    C = "Як душа чіплялася за сувенір, так вона чіплятиметься і за фізичну форму Раса Морозного Шепоту.",
},

[5465] = {
    en = "Soulbound Keepsake",
    T = "Зв’язаний із Душею Пам’ятний Предмет",
    D = "Повернися до Мардука з пам’ятним предметом, $N. Він пояснить, як його використовувати.",
    O = "Повернися до Маґістрата Мардука в Каер Дарроу. Покажи йому Зв’язаний із Душею Пам’ятний Предмет.",
    P = "Ви зробили неможливе?",
    C = "Я був упевнений, що ти приєднаєшся до мене як ще один нещасний дух.",
},

[5466] = {
    en = "The Lich, Ras Frostwhisper",
    T = "Лич, Рас Морозошелест",
    D = "Залишилося лише одне завдання, $N. Зустрінься з личем, Расом Морозошелестом, у його лігві.$B$BВикористай силу пам’ятного предмета проти цього чудовиська — будь невблаганним у своїх діях! Витримай удари, які неминуче завдасть ця істота. Не піддавайся болю!$B$BКоли ритуал завершиться, Рас знову стане смертним. Саме тоді його потрібно зарубати. Удар його і забери його людську голову.",
    O = "Знайди Раса Морозошелеста в Схоломансі. Коли знайдеш його, використай Зв’язаний із Душею Пам’ятний Предмет на його подобі нежиті. Якщо тобі вдасться повернути його до смертного стану, зарубай його і забери Людську Голову Раса Морозошелеста. Віднеси голову назад до Маґістрата Мардука.",
    P = "Ви несете тягар десяти тисяч неспокійних душ, $N.",
    C = "Десять тисяч душ кричать в унісон, $N! Ви завдали смертельного удару Бичу та їхнім володарям.",
},

[5481] = {
    en = "Gordo's Task",
    T = "Завдання Ґордо",
    D = "Хазяїн хоче бур’янів. У нас великі руки, і ми не вміємо їх збирати. Ти допоможеш нам, і ми тебе не зачепимо. Нам потрібен морок-бур’ян. Багато бур’янів тут і біля дороги.$B$BКоли збереш морок-бур’ян, віднеси його Хазяїну Голланду на цвинтар у Бріллі.",
    O = "Збери 3 морок-бур’яни і віднеси їх Молодшому Аптекарю Голланду на цвинтар у Бріллі.",
    P = "Де та марна гидота? Або у вас є те, що мені потрібно, або вам краще піти туди й знайти це.",
    C = "Що це? Похмурий бур'ян?! Мені не потрібна марна трава! Ця безглузда маса плоті збирає ромашки та переконує Леді знає, скільки таких дурнів, як ти, робити те саме. Без образ.$B$BVery Ну, ти зараз тут, і це все, що має значення. Оскільки я не збираюся намагатися пояснити речі цій гидоті, як щодо того, щоб ви зібрали те, що мені справді потрібно... траву дум!",
},

[5482] = {
    en = "Doom Weed",
    T = "Лихо-бур’ян",
    D = "Ти бачиш, у якій я ситуації, $N. Ця істота там збирає не ті бур’яни! Я зроблю так, щоб твої зусилля вартували. Принеси мені достатньо лихо-бур’янів, і я дам тобі гідну нагороду.$B$BМені відомо, що вони люблять рости серед рослин біля масового поховання, на північ від цвинтаря в Бріллі. Поспіши і будь обережним із ґноллами в тій місцевості.",
    O = "Збери 10 лихо-бур’янів і поверни їх Молодшому Аптекарю Голланду.",
    P = "Краще б це було добре. Я вірю, що у вас є вся трава Doom, яка мені потрібна?",
    C = "Ах, моя приречена трава. Чудово!$B$B<Молодший аптекар Холланд жадібно потирає руки.>$B$BThese стане в нагоді. Ви зробили мені, леді, чудову послугу сьогодні $N. Як і обіцяно, ось винагорода, яку ви заслуговуєте.",
},

[5501] = {
    en = "Bone Collector",
    T = "Збирач кісток",
    D = "Ми сидимо на золотій жилі, кажу тобі — на золотій жилі! Кістки кодів змінять світ назавжди... У мене є клієнти, які роблять із них меблі, музичні інструменти і навіть вибуховий порох.$B$BКараван забирає мої кістки кодів і продає їх у Селі Тінелову. Якщо ти вирушиш на кладовище кодів на південь звідси і принесеш мені десять кісток кодів, я дам тобі щось у нагороду. Домовились?",
    O = "Принеси 10 Кісток Кодів із Кладовища Кодів до Бібблі Ф’утцбакла в Хатині Кормека.",
    P = "У вас є кістки?  Караван буде тут щохвилини.  Мені потрібно ще десять кісток кодо, щоб досягти вершини кар’єри.  Вершина кар'єри, я вам кажу!",
    C = "Ах, добра!  Мої кістки!$B$BI не можу дочекатися, поки хлопці вдома побачать моє обличчя на першій обкладинці Goblin'preneur.  Я стану найбагатшим гобліном у світі... і мій учитель фізкультури сказав, що я ніколи нічого не досягну.",
},

[5502] = {
    en = "A Warden of the Horde",
    T = "Опікун Орди",
    D = "Ти був надзвичайно добрим до мене, $N. Я ніколи не мріяв, що мені буде так весело під час Тижня Дітей. Дякую. Я не сумуватиму за тим, що зі мною сталося — мої батьки завжди казали мені підніматися над будь-якими негараздами. Я стану героєм... як ти.$B$BМені сумно це казати, але час повертатися додому. Ходімо назад, і я розповім матроні, яка ти чудова людина!",
    O = "Поверни свого підопічного до притулку в Орґріммарі, віддавши Оркський Свисток Сироти Матроні Бойового Кличу в Долині Честі.",
    P = "Мені приємно бачити вас знову, $N. Чи виконали ви свої обов’язки під час Тижня захисту дітей?",
    C = "Нехай духи благословлять вас, $N. Ви зробили для Ґрунта більше, ніж більшість може подумати зробити для нього. Дякуємо, ви є втіленням того, що означає бути героєм Орди.$B$BPlease — якщо можете приділити час, поверніться до нас. Я знаю, що Ґрунт хотів би цього, як і я.",
},

[5503] = {
    en = "Argent Dawn Commission",
    T = "Посвідчення Світанку Аргенту",
    D = "",
    O = "",
    P = "",
    C = "Усі, хто бореться зі злом від імені Сріблястої Зорі, повинні отримати наше доручення. Одягнувши їх, ви отримаєте право вимагати нагороди, які можуть запропонувати наші квартирмейстери.$B$BWhile за дорученням ви зможете отримати Камені Бича від убитого Скорджа; це знаки розрізнення, якими вони іноді володіють. Придбайте ці знаки відмінності і принесіть їх мені. За кожен набір, який ви здасте, ви отримаєте наш знак героїзму — жетон доблесті Сріблястого світанку.$B$BAchieve ваша доля, $C приєднайтеся до бою сьогодні!",
},

[5504] = {
