[5521] = {
    en = "Chromatic Mantle of the Dawn",
    T = "Хроматична Мантія Світанку",
    D = "$GБрате:Сестро; $N, твої подвиги на благо Світанку Аргенту занадто численні, щоб їх легко перелічити. Як належну данину, я віддам тобі одну з наших особливих Хроматичних Мантій Світанку — версію, яка захищає власника від усіх форм магії, що можна протистояти, одночасно. Хроматичні Мантії Світанку призначені лише для наймогутніших героїв Світанку!$B$BПринеси мені двадцять п’ять жетонів доблесті як знак данини, і я дам тобі найкращу з усіх наших мантій.",
    O = "Принеси 25 Жетонів Доблесті Світанку Аргенту до Квартирмейстера Лайтспарка в Таборі Холодовітрів, Західні Зачумлені Землі.",
    P = "Вітання, могутній $C! Ви принесли знаки доблесті, які я просив у вас? Коли ви передасте їх мені, я видам вам вашу власну Хроматичну Мантію Світанку.",
    C = "Найбільш вражаюче, $N — Хроматична мантія Зорі тепер у вас!$B$BAs, поки ви зберігаєте Піднесений статус у Сріблястому світанку, ви зможете придбати додаткові хроматичні мантії. Вони будуть доступні для вас негайно від будь-якого з інтендантів Зорі.",
},

[5522] = {
    en = "Leonid Barthalomew",
    T = "Леонід Бартоломей",
    D = "Я отримав повідомлення від мого господаря, Вектуса. Ну, повідомлення було не зовсім від Вектуса... його надіслав хтось на ім’я Леонід Бартоломей. Я не знаю Леоніда, але він знав мого господаря, а ніхто не знає мого господаря, якщо він цього не дозволяє.$B$BЛеонід каже, що Вектус хоче отримати яйця драконів. Він хоче, щоб ти доставив їх йому до Каплиці Світла Надії в Східних Зачумлених Землях.$B$BЦе боляче! Чому ти? Хіба Вектус мені не довіряє? Ох, неважливо... просто візьми яйця і скажи Леоніду, що я виконав наказ нашого господаря.",
    O = "Принеси Заморожені Яйця до Леоніда Бартоломея в Східних Зачумлених Землях.",
    P = "Це ти той, хто чинить лихо в Шпилі Чорної Гори, так? У вас є те, що я просив?",
    C = "Ах, дуже добре. Ви не знаєте злої сили, для якої ви працювали, але тепер ви дізнаєтеся правду. І не бійтеся — я не слуга цього господаря. Я Леонід Барталомью, відомий як ",
},

