},

[5654] = {
    en = "Hex of Weakness",
    T = "Прокляття Слабкості",
    D = "Настав час тобі зустрітися з Ур’кіо, $N. Він у Долині Духів у місті орків. Іди туди і поговори з ним. Час тобі дізнатися більше про старі звичаї нашого народу. Час тобі бути введеним у коло і стати справжнім жерцем нашого племені.",
    O = "Поговори з Ур’кіо в Оргріммарі.",
    P = "",
    C = "Тобі було б добре прислухатися до цього уроку, юначе. Прокляття Слабкості стане для вас великим благом у бою. Пізніше я проведу для вас випробування, щоб удосконалити себе та довести свою цінність племені.",
},

[5655] = {
    en = "Hex of Weakness",
    T = "Прокляття Слабкості",
    D = "Мене послали сюди, щоб переконатися, що ти не блукаєш надто далеко від дому, $N. Мене послали, щоб ти повернувся додому, бо Ур’кіо, найбільший із наших жерців, хоче поговорити з тобою. Іди туди. Іди до Долини Духів у місті орків і поговори з Ур’кіо. Він чекає на тебе зараз.",
    O = "Поговори з Ур’кіо в Оргріммарі.",
    P = "",
    C = "Тобі було б добре прислухатися до цього уроку, юначе. Прокляття Слабкості стане для вас великим благом у бою. Пізніше я проведу для вас випробування, щоб удосконалити себе та довести свою цінність племені.",
