[5659] = {
    en = "",
    T = "Дотик Слабкості",
    D = "Це не місце для тебе, $N. Тобі слід вирушити до Військового Кварталу в Підмісті якомога швидше. Аелталісте скликала всіх своїх жерців і жриць туди, щойно вони будуть готові. Час їм дізнатися більше про їхню силу і як її опанувати.$B$BВона не терпітиме запізнень чи виправдань, тож тобі краще поспішити.",
    O = "Поговори з Аелталістею в Підмісті.",
    P = "",
    C = "",
},

[5660] = {
    en = "Touch of Weakness",
    T = "Дотик Слабкості",
    D = "Ти далеко від дому, $c. Тебе потребують там, назад у твоєму місті під землею. Твоя пані, яку ти називаєш Аелталістею, потребує твого повернення. Як і моє плем’я, є речі, які ти можеш дізнатися лише від неї. Не залишайся тут надто довго. Тобі слід вирушити до Військового Кварталу так швидко, як тільки це може зробити цепелін.",
    O = "Поговори з Аелталістею в Підмісті.",
    P = "",
    C = "А, добре, ще один прийшов. Можливо, для мене час не має значення, але для вас він має важливе значення. Вам є чому навчитися, і я хочу багато чого вас навчити. Ви просто повинні довести свою цінність. Зробіть це, і ви отримаєте велику винагороду.",
},

[5661] = {
    en = "Touch of Weakness",
    T = "Дотик Слабкості",
    D = "Ти далеко від дому тут, у Селі Кривавого Копита, $N. Мене послали сюди, щоб знайти жерців мого власного племені і відправити їх назад до наших лідерів, але це не означає, що я не можу допомогти і тобі.$B$BЯ чув, що твоя головна жриця-дух хоче, щоб усі Покинуті прийшли до неї — є речі, які тобі потрібно дізнатися.$B$BІди на зустріч із Аелталістею у Військовому Кварталі в твоєму місті.",
    O = "Поговори з Аелталістею в Підмісті.",
    P = "",
    C = "А, добре, ще один прийшов. Можливо, для мене час не має значення, але для вас він має важливе значення. Вам є чому навчитися, і я хочу багато чого вас навчити. Ви просто повинні довести свою цінність. Зробіть це, і ви отримаєте велику винагороду.",
},

[5662] = {
    en = "Touch of Weakness",
    T = "Дотик Слабкості",
    D = "Моя повага тобі і твоєму народу, $N. Зазвичай я навчаю лише тих, хто належить до мого племені. Твої уроки надходять від Аелталісти в місті, яке колись називалося Лордероном.$B$BТобі слід повернутися до неї, якщо ти хочеш дізнатися ті здібності, які відрізняють тебе від інших вірувань.$B$BІди до Військового Кварталу в Підмісті і знайди там свою пані.",
    O = "Поговори з Аелталістею в Підмісті.",
    P = "",
    C = "А, добре, ще один прийшов. Можливо, для мене час не має значення, але для вас він має важливе значення. Вам є чому навчитися, і я хочу багато чого вас навчити. Ви просто повинні довести свою цінність. Зробіть це, і ви отримаєте велику винагороду.",
},

