[5673] = {
    en = "Elune's Grace",
    T = "Благодать Елуни",
    D = "Ти знаєш, що маєш доступ до будь-якого з наших наставників у будь-який час, $N, але є деякі речі, які ми не можемо тобі передати. Однією з таких речей є вчення твоєї богині Елуни. Вона дарує особливі здібності своїм вірним, і якщо я не помиляюся, настав час тобі повернутися додому до Храму Місяця, щоб пройти випробування.$B$BПовертайся туди, коли зможеш, і поговори з Жрицею Алатеєю.",
    O = "Поговори з Жрицею Алатеєю в Дарнассусі.",
    P = "",
    C = "Хай благословить вас Елуна за те, що ви так швидко повернулися до нас. Це важливий час у вашому навчанні, і час, до якого весь наш орден ставиться дуже серйозно. Коли ви відпочинете від подорожі сюди, будь ласка, дайте мені знати. Потім ми можемо обговорити продовження вашого навчання та куди ваш шлях приведе вас далі.",
},

[5674] = {
    en = "Elune's Grace",
    T = "Благодать Елуни",
    D = "Чудовий день настав, $N. Ти досяг віку, коли наші $gжерці:жриці; навчаються здібностям, відомим лише Нічним Ельфам. Але не мені тебе навчати. Ти мусиш повернутися до Храму Місяця і поговорити з Жрицею Алатеєю, щойно твої справи тут будуть завершені. Вона випробує тебе, щоб переконатися, що ти готовий, і лише тоді навчить тебе Благодаті Елуни.",
    O = "Поговори з Жрицею Алатеєю в Дарнассусі.",
    P = "",
    C = "Присвятивши себе Елуні та нашому народу, ви досягли такого стану, якого не кожен з нас може досягти. Згідно з традицією, ви потім отримуєте ще більші здібності за вашу відданість. Ви приймаєте?",
},

[5675] = {
    en = "Elune's Grace",
    T = "Благодать Елуни",
    D = "Часу обмаль, $gхлопче:дівчино;. Настав час тобі повернутися додому до Дарнассуса. Жриця Алатея надіслала сюди повідомлення, що тобі слід повернутися туди для навчання. Здається, вони вважають, що ти готовий пройти випробування, подібно до тих, хто служить Світлу. Тобі варто вирушити, коли зможеш. У повідомленні Алатеї сказано, що вона чекатиме на тебе в Храмі Місяця. Удачі.",
    O = "Поговори з Жрицею Алатеєю в Дарнассусі.",
    P = "",
    C = "Хай благословить вас Елуна за те, що ви так швидко повернулися до нас. Це важливий час у вашому навчанні, і час, до якого весь наш орден ставиться дуже серйозно. Коли ви відпочинете від подорожі сюди, будь ласка, дайте мені знати. Потім ми можемо обговорити продовження вашого навчання та куди ваш шлях приведе вас далі.",
},

