},

[5713] = {
    en = "One Shot. One Kill.",
    T = "Один Постріл. Один Убитий.",
    D = "Я подорожував до Аубердіна з важливим повідомленням, коли на мене напав фурболг Марош і його слідопити. Під час нападу мене отруїли, залишивши ледь здатним стояти. Я можу зробити протиотруту, але це займе час, перш ніж вона буде готова.$B$BЯ попросив би тебе захистити мене, доки я не зможу застосувати протиотруту. Я допомагатиму тобі своїм луком, наскільки зможу.$B$BЯкщо ми виживемо, я зможу доставити своє повідомлення до Аубердіна, а ти поговори з Онеєю у Фортеці Маестри, щоб повідомити її про цей інцидент.",
    O = "Захистіть Вартівницю Айнашу, а потім поговоріть із Онеєю у Фортеці Маестри в Ясенедолі.",
    P = "Ви бачили Sentinel Aynasha на дорозі? Вона пішла з важливою місією, але досі не повернулася.",
    C = "Ви приносите найприємніші новини $C. Приємно чути, що Айнаша жива і здорова завдяки вам. Я сподіваюся, що ви приймете нагороду за вашу доблесть. Нехай Елуна стереже вас і освітлює ваш шлях.",
},

[5721] = {
    en = "The Battle of Darrowshire",
    T = "Битва за Даррошір",
    D = "Тепер, $N, ти візьмеш участь у битві за Даррошір і врятуєш Джозефа Редпата.$B$BПостав цей набір реліквій на площі Даррошіра, і духи Даррошіра повстануть. Приєднайся до їхньої битви і переконайся, що відбудуться дві речі: Давіл мусить вижити після смерті Горґуса, а Редпат мусить вижити, щоб бути спотвореним, а потім переможеним.$B$BПісля перемоги над спотвореним Редпатом його дух буде врятований. Поговори з ним, а потім повернися до його доньки Памели.",
    O = "Поставте Набір Реліквій на площі Даррошіра.$B$BЗапобігайте смерті Давіла Світловогня до смерті Горґуса.$B$BЗапобігайте смерті Капітана Редпата до появи Спотвореного Редпата.$B$BПереможіть Спотвореного Редпата.$B$BПоговоріть із духом Джозефа Редпата, коли він з’явиться на площі, а потім поговоріть із Памелою в її домі.",
    P = "Здається, я чув привидів надворі. Вони нашіптують мені страшні речі...",
    C = "Бої закінчені!  Я почув, як тато шепоче мені.  Він усіх привидів відлякав і каже, що повертається додому!  Я такий щасливий!$B$BHe також сказав, що я вітаю вас, якщо ви прийдете до нас додому, тому я зробив чай!$B$BI сподіваюся, ви любите багато цукру!",
},

[5722] = {
    en = "Searching for the Lost Satchel",
    T = "Пошук Загубленої Торби",
    D = "Трогги — не єдине, що зацікавило Маґату в Печері Лютого Полум’я. Вона чула, що один із її слуг, Маур Гримтотем, знайшов щось незвичайне в Печері, але він так і не вибрався, щоб показати їй, що саме. Вона хоче, щоб тіло Маура знайшли — якщо воно ще існує — і будь-які ознаки того, що він знайшов, коли намагався говорити з троггами.$B$BПоверни Маґаті будь-які цікаві предмети, і я впевнений, що вона буде дуже щедрою у своїй нагороді.$B$BЗнову ж таки, шукай Печеру в найтемніших закутках Оргріммара.",
    O = "Дослідіть Печеру Лютого Полум’я в пошуках тіла Маура Гримтотема і обшукайте його на наявність цікавих предметів.",
    P = "",
    C = "Тіло виглядає серйозно побитим киями чи кулаками, але більша частина одягу та спорядження трупа все ще виглядає присутніми. Здається, трогги не надто дбають про матеріальне багатство.$B$BYou починають шукати в тілі щось цікаве, що могло б допомогти Магаті.",
},

[5723] = {
    en = "Testing an Enemy's Strength",
    T = "Випробування Сили Ворога",
    D = "Під містом Оргріммаром міцні створіння, відомі як трогги, почали вибиратися на поверхню з глибоких лавових тунелів. У своїй безмежній доброті Маґата намагалася укласти мир із цими створіннями, але вони напали на її дипломатів, убивши їх. Вона не дозволить так поводитися з народом тауренів і тепер вважає цих створінь загрозою для всієї Орди.$B$BВона просить покласти край цій загрозі троггів, перш ніж вона захлине Орду знизу. Знайди Печеру Лютого Полум’я і знищ їх усіх.",
    O = "Дослідіть Оргріммар у пошуках Печери Лютого Полум’я, а потім убийте 8 Троггів Лютого Полум’я і 8 Шаманів Лютого Полум’я, перш ніж повернутися до Рахауро в Громовий Бескид.",
    P = "Як проходять ваші пошуки Безодні? А трогги?$B$BThe загрозі не можна дозволити існувати - вона лише поранить наших братів-орків, якщо буде тривати.",
    C = "Я радий бачити, що ви серйозно поставилися до завдання Магати. Дякую, $N. Я впевнений, що троггам буде важче вийти на поверхню, оскільки їхня кількість настільки зменшилася.$B$BМожливо у майбутньому ми можемо витратити час, щоб зрозуміти, звідки взялися такі істоти та чого вони насправді хочуть.",
},

[5724] = {
    en = "Returning the Lost Satchel",
    T = "Повернення втраченої сумки",
    D = "Ти знаходиш сумку під тілом таурена. Вона все ще міцно затиснута в його руках, ніби він намагався захистити її, коли на нього нападали троги.$B$BВивільнивши сумку з його міцної хватки, ти кладеш її до свого спорядження і готуєшся вийти з тунелів, щоб повернутися до Рагауро в Громовий Бескид.",
    O = "Віднеси Сумку Мракокронів до Рагауро в Громовий Бескид.",
    P = "Ви змогли щось знайти, $N? Будь-які підказки щодо того, чому один із членів її клану мав померти без потреби, будуть корисні.",
    C = "Відмінно, $N. Дякую.$B$BMagatha сказала мені, що якщо вам вдасться знайти члена її клану, ви отримаєте це. Будь ласка, візьміть його в подяку.",
},

[5725] = {
    en = "The Power to Destroy...",
    T = "Сила руйнування...",
    D = "Багато створінь Легіону дарують подарунки своїм послідовникам, як ти, мабуть, знаєш. Деякі з цих подарунків Темна Леді вважає за краще тримати у своїх руках, а не в руках тих, хто має... менш амбітне бачення.$B$BСекта Ради Тіней, що ховається в печерах під Орґріммаром і відома як Палаючий Клинок, є яскравим прикладом. Леді повідомила мені, що члени Палаючого Клинка заволоділи двома могутніми книгами заклинань — вона хоче «позичити» ці книги. Ти добудеш їх для неї.",
    O = "Принеси книги «Заклинання Тіні» та «Закляття з Порожнечі» до Варімата в Підмісто.",
    P = "Сто інших завдань чекають на мою увагу, $C. У вас є книги?",
    C = "Добре, $C. Ви добре послужили темній леді. Ваша незмінна наполегливість і амбіції будуть дуже корисні для підданих Леді. Повертайся до мене знову в майбутньому. Можливо, у мене будуть інші завдання для вас, які допоможуть Темній Леді в її спробах наздогнати Короля-Ліча та повністю звільнити Бич.",
},

[5726] = {
    en = "Hidden Enemies",
    T = "Приховані вороги",
    D = "Я не терпітиму зрадників серед нас, $N. Але я був би дурнем, якби розкрив свої карти так рано — це не викорінить корупцію в наших землях, а лише погіршить заразу.$B$BАле ти, молодий шукачу пригод, можеш піти туди, куди мої агенти не можуть... дізнатися правду... знайти справжню голову чудовиська.$B$BЯкщо ти достатньо хоробрий, вирушай до Скельної Печери на схід від Орґріммара, добудь відзнаку лейтенанта з одного з членів Палаючого Клинка і повернися до мене.",
    O = "Принеси Відзнаку Лейтенанта до Тралла в Орґріммар.",
    P = "У вас уже є знаки розрізнення, $N?$B$BIt стане життєво важливим інструментом для проникнення в те, що, на мою думку, є найбільшою загрозою для Орди та для того, щоб ми нарешті знайшли мир у нашому новому домі.$B$BYou дізнаєтеся, яку заплутану мережу можуть плести як люди, так і орки, коли їх спонукає жадібність і влада. Приховані наміри, корупція, все це стане явним. Ви опинитеся в центрі війни, про існування якої навіть не підозрювали.",
    C = "Добре, $N! Хвала духам, можливо, саме ти розвієш мої найбільші страхи! Хто б міг запідозрити, що хтось такий молодий і такий сміливий підніметься і захистить нашу справу? Ти нагадуєш мені мене самого, коли я був молодшим. Я подбаю про те, щоб ви отримали справедливу винагороду за ваші зусилля, якщо ми обоє переживемо майбутню бурю.$B$BBut пізніше буде час для більшої похвали. Ви нічого не досягли порівняно з тим, з чим вам доведеться зіткнутися... але це хороший початок.",
},

[5727] = {
    en = "Hidden Enemies",
    T = "Приховані вороги",
    D = "Тепер подивимося, чи варта ця відзнака, яку ти знайшов, наших зусиль.$B$BУ місті є чаклун, який вважає, що має мою довіру. Він не знає, що я розумію, де лежить його справжня відданість. Насправді він є лідером Палаючого Клинка. Але не поспішай вступати з ним у бій; він має своє призначення, і ми використаємо його проти наших ворогів.$B$BВіднеси цю відзнаку до нього в Розщелину Тіней тут, в Орґріммарі, поговори з ним і перевір, чи повірить він, що ти один із його. Потім повернися до мене.",
    O = "Віднеси Відзнаку Лейтенанта до Нееру Вогнеклинка і поговори з ним. З’ясуй, чи повірить він, що ти член Палаючого Клинка, а потім повернися до Тралла в Орґріммар.",
    P = "Ну що, $c? Чи вірить він у нашу хитрість, чи все гірше, ніж я спочатку припускав? $B$BProving Цінність для Ніру значно полегшить наше проникнення в Раду тіней. У нього буде багато інформації, яку ми зможемо використати, щоб вивести тих, хто хоче зруйнувати все, що ми побудували в Дуротарі.",
    C = "Чудово! Чудово, $C!$B$BWhat те, що ви зробили цього дня, є лише першим кроком у набагато ширшому фундаменті--фундаменті, на якому ми побудуємо знищення Тіньової ради раз і назавжди.$B$BTell мені все, що він сказав... і не пропускайте жодного слова--це може бути важливішим, ніж ви уявляєте.",
},

[5728] = {
    en = "Hidden Enemies",
    T = "Приховані вороги",
    D = "Хм, лідери Палаючого Клинка... це турбує мене найбільше. Якщо вони цінні для Нееру, то саме їх ми мусимо знищити першими. Цей сатир... Баззалан, і той інший, про якого згадував Нееру — здається, чаклун? — мусять бути вбиті.$B$BПовернися до Розщелини Тіней і увійди в Печеру Лютої Вогняної, $N. Знайди цих двох лідерів Палаючого Клинка і знищ їх. Але будь обережним, щоб Нееру не дізнався, що це зробив ти. Ти мусиш зберегти свою роль одного з його $gбратів:сестер; по зброї.",
    O = "Убий Баззалана і Джерґоша Заклинателя, перш ніж повернутися до Тралла в Орґріммар.",
    P = "Ти вже знайшов їх, $N? Лідери Пекучого Клинка.$B$BI знали, що Рада Тіней хоче відібрати в мене Оргріммар і всю Орду, але я не усвідомлював, як швидко вони змогли проникнути в місто. У цього звіра стільки рук... ми можемо відрізати їх, поки не настане виснаження, але ми не підемо далі, ніж на початку. Мені доведеться змусити моїх шпигунів подвоїти свої зусилля.",
    C = "Я радий, що ти повернувся, $N. Дехто з тих, хто мені відданий, негайно повідомив, що в печерах під Оргріммаром панує безлад, оскільки їхні вожді вбиті. Я навіть чув повідомлення, що Ніру був більш ніж схвильований. Здається, ми пробили його броню. Не можу сказати, що я незадоволений... навіть такою незначною перемогою.",
},

[5729] = {
    en = "Hidden Enemies",
    T = "Приховані вороги",
    D = "Я думаю, наступним кроком буде наблизити тебе до Нееру. Якщо він так схвильований, як повідомляють, ми можемо досягти двох цілей. По-перше, ти зможеш отримати глибші знання про Раду або принаймні про Палаючий Клинок, а по-друге, він може почати тобі довіряти настільки, що попросить допомогти йому. Він цілком може розглядати тебе як того, хто заповнить прогалину, адже лідерство тепер у хаосі.$B$BПовернися до Розщелини і поговори з ним знову, але не будь надто відвертим.",
    O = "Поговори з Нееру Вогнеклинком в Орґріммарі.",
    P = "",
    C = "Що таке?! О, ти, $C... мої вибачення. Мій гнів конкурує з гнівом скаженого бика кодо... але, можливо, це моя власна вина. Відправляючи мандрівників у Ragefire Chasm, я мав бачити ймовірність того, що це завдасть певної шкоди. Здається, і Баззалан, і Джергош були захоплені зненацька та вбиті декількома благодійниками Тралла. Дуже невідповідний час, але зараз з цим нічого не поробиш.",
},

[5730] = {
    en = "Hidden Enemies",
    T = "Приховані вороги",
    D = "Ти один із моїх лейтенантів! Готуйся, $c. Я скоро покличу тебе.$B$BМій час, витрачений на Палаючий Клинок, можливо, майже марний, але це не означає, що плани Ради Тіней деінде мають постраждати. Я зроблю все можливе, щоб мінімізувати шкоду тут, у Печері Лютої Вогняної. Тим часом я доручу моїм агентам у Степах і Ясенедолі розпочати роботу над нашим новим порядком денним. Повертайся до мене незабаром.",
    O = "Поговори з Траллом в Орґріммарі і розкажи йому, що ти дізнався.",
    P = "",
    C = "Ashenvale? Хм, я не чув про присутність Ради чи Палаючого Клинка в Ясеневому лісі. Мої шпигуни проведуть розслідування, $N. Ви добре впоралися.$B$BFor тепер відпочиньте та займіть себе іншими завданнями. Незабаром я зателефоную вам знову.$B$BLok-Тар Огар!",
},

[5741] = {
    en = "Sceptre of Light",
    T = "Скіпетр Світла",
    D = "Подейкують, що Палаючий Клинок у Фортеці Громового Топора на сході заволодів Скіпетром Світла від наґ. Легенда свідчить, що цей скіпетр здатен затопити цілі міста під великими морями. Палаючому Клинку не можна дозволити володіти такою силою.$B$BТому ти мусиш сам здобути скіпетр! Його тримає віщун Палаючого Клинка, який вивчає скіпетр на вершині однієї з оглядових веж Громового Топора.",
    O = "Здобудь Скіпетр Світла і поверни його до Азора Альдаморта у вежі в Етель Реторі.",
    P = "У вас є Скіпетр Світла?$B$B",
    C = "Невловимий Скіпетр Світла! Ваше придбання усунуло серйозну загрозу для світу. Молодець, $C, молодець.$B$B",
},

[5742] = {
    en = "Redemption",
    T = "Спокута",
    D = "Ти наполегливо працював, друже. Відпочинь свої втомлені кістки і дозволь мені належним чином представитися.",
    O = "Послухай, що має сказати Тіріон Фордрінґ.",
    P = "Будь ласка, друже; сиди і слухай мою казку.",
    C = "Викуп Fordring буде непростим завданням. Ви готові?",
},

[5761] = {
    en = "Slaying the Beast",
    T = "Знищення чудовиська",
    D = "Головне завдання, яке поклав на мене наш великий Вождь, — викорінити створінь, відповідальних за зараження нашого славного міста демонічним впливом. Палаючий Клинок — одна з загроз, але є й інші; наприклад, Палаючий Клинок, що оселився в Печері Лютої Вогняної, таємно намагається підірвати невинних членів Орди.$B$BЩоб зупинити їх, потрібно знищити їхнього лідера — фелґарда на ім’я Тараґаман Голодуючий.$B$BУбий його, і його серце, я впевнений, заспокоїть Тралла.",
    O = "Увійди в Печеру Лютої Вогняної, убий Тараґамана Голодуючого і принеси його серце назад до Нееру Вогнеклинка в Орґріммар.",
    P = "Ви вбили звіра? Він, безперечно, має бути лідером Пекучого клинка в Ragefire Chasm.",
    C = "Ха! Ви зробили це! Тралл буде дуже радий.$B$BI подбає про належний догляд за цим серцем.$B$BFor А тепер ви повинні святкувати свою перемогу. Я повідомлю Тралла про ваш успіх.$B$BThank вам за допомогу, $C.",
},

[5762] = {
    en = "Hemet Nesingwary",
    T = "Гемет Несінґвері",
    D = "У мене є посилка для мого давнього клієнта, дворфа на ім’я Гемет Несінґвері. Посилка йшла тижнями, і Гемет уже давно поїхав. Він казав, що вирушить до Тернистої Долини полювати на тамтешніх звірів, але залишив мені трохи грошей, щоб я надіслав йому доставку, коли зможу.$B$BГемет — багатий дворф, і підтримувати стосунки з багатими завжди корисно, правда? Тож... хочеш доставити цю посилку за мене?$B$BЯ чув, що Гемет має табір у Тернистій Долині, на північ від табору Ґром’ґол.",
    O = "Віднеси Ящик Кравела до Гемета Несінґвері в Тернисту Долину.",
    P = "Це пустельний пил на твоєму комірі?$B$BHm... якби мій ніс сказав правду, я б сказав, що це не пустельний пил, а пустельна сіль!  Ви були в Shimmering Flats?",
    C = "Чудово, мій пакет від Koalbeard! Дякую $N. Цей ящик містить боєприпаси спеціального калібру, і він добре прислужиться нам у джунглях!$B$BHere — ваша плата, і скажіть мені, як зараз старий Кравел? Я б тримався об заклад, що все ще нічого доброго...",
},

[5763] = {
    en = "Hunting in Stranglethorn",
    T = "Полювання в Тернистій Долині",
    D = "Давно один дворф прийшов до цієї землі. Його звали Гемет, і він прагнув полювати на великих звірів. Його вміння зі зброєю були вражаючими, і ми провели багато днів, полюючи разом. Навіть ворожнеча між нашими народами була забута.$B$BКоли він покинув Спустошення заради Тернистої Долини, я присягнув одного дня запросити його назад, щоб ми могли полювати знову. Цей час настав.$B$BВіднеси цей ріг кодо до Гемета. Він знатиме, що це від мене. Ти знайдеш його в Тернистій Долині, на північ від табору Ґром’ґол.",
    O = "Віднеси Ріг Кодо Руна до Гемета Несінґвері в Тернисту Долину.",
    P = "Сиди, $C. Невдовзі ви потрапите у відповідь у джунглі.",
    C = "Ах, цей ріг належить таурену, Руну Дикогривому. Ми з ним добре провели час, полюючи на звірів Пустощі. Отже, Рун запрошує мене повернутися, чи не так?$B$BWe зараз ти по шиї в джунглях, але дякую тобі, $N. Можливо, моя наступна експедиція поверне мене до Пустощі, країни кентаврів.",
},

[5781] = {
    en = "Of Forgotten Memories",
    T = "Про забуті спогади",
    D = "Щоб допомогти Таелану повернути те, що він втратив, ти мусиш зібрати предмети з його минулого.$B$BПерший такий предмет — іграшка, яку я подарував йому на його сьомий день народження. Це була його найцінніша річ: мініатюрний бойовий молот, точна копія мого власного.$B$BПісля того, як мене вигнали за зраду, його мати сказала йому, що я помер. Його відвели до моєї фальшивої могили в Підземній Криниці, де він закопав молот разом із пам’яттю про мене — назавжди.$B$BТи мусиш вирушити до Підземної Криниці і повернути молот Таелана.",
    O = "Вирушай до Підземної Криниці — у найпівденнішій частині Східних Зачумлених Земель — і поверни Молот Таелана. Повернися до Тіріона Фордрінґа після виконання завдання.",
    P = "Він повинен бути викуплений.",
    C = "<Тіріон моргає, щоб стримати сльози.>$B$BIt була доля, яку ми зустріли, $N. Ти благословив мене своєю добротою.",
},

[5801] = {
    en = "Fire Plume Forged",
    T = "Вогняний Шлейф",
    D = "Для кування основи ключа тобі потрібні два торієвих злитки і дуже гаряче джерело тепла. За торій відповідаєш ти, але з теплом я можу допомогти.$B$BНа заході, в кратері Ун’Ґоро, є Вогняний Шлейф — тліючий вулкан. Озеро лави на його вершині досить гаряче, щоб сплавити торій і кістки разом. Твої золоті купили тобі форму, яку потрібно лише занурити в лаву на вершині; лава зробить решту.$B$BЦе все з мого боку. Щоб завершити ключ, тобі потрібно знову поговорити з Арбінґтоном.",
    O = "Візьми Форму Скелетного Ключа і 2 Торієвих Злитки на вершину Вогняного Шлейфу в кратері Ун’Ґоро. Використай Форму Скелетного Ключа біля озера лави, щоб викувати Незавершений Скелетний Ключ.$B$BПринеси Незавершений Скелетний Ключ до Алхіміка Арбінґтона в Точці Холодовітрів, Західні Зачумлені Землі.",
    P = "Ви закінчили ніжку скелетного ключа? Мені щиро шкода, що вам довелося взяти на себе основний тягар гонорару, щоб придбати форму, але ми всі повинні зробити свій внесок у протистояння Бичу. Щойно ви передасте мені незавершений ключ, ви будете готові до останнього предмета, необхідного для завершення його будівництва.$B$BIt буде зовсім непросто, але робота, яку ви виконали на сьогоднішній день під час підготовки до нападу на Андорал, тепер почне окупатися. Ви побачите.",
    C = "У нас там досить дорогий скелетний ключ, чи не так $N? І все ж він залишається незавершеним; настав час зосередитися на нашому створенні. З цією метою вам доведеться зіткнутися з головним ворогом, проти якого ми намагалися зіткнутися в Андоралі... істотою, яка керує шоу серед зруйнованих міських стін.$B$BI Я говорю про Араджа Призивача — лича та одну з наймогутніших істот, яких Бич називає своєю.",
},

[5802] = {
    en = "Fire Plume Forged",
    T = "Вогняний Шлейф",
    D = "Для кування основи ключа тобі потрібні два торієвих злитки і дуже гаряче джерело тепла. За торій відповідаєш ти, але з теплом я можу допомогти.$B$BНа заході, в кратері Ун’Ґоро, є Вогняний Шлейф — тліючий вулкан. Озеро лави на його вершині досить гаряче, щоб сплавити торій і кістки разом. Твої золоті купили тобі форму, яку потрібно лише занурити в лаву на вершині; лава зробить решту.$B$BЦе все з мого боку. Щоб завершити ключ, тобі потрібно знову поговорити з Дітерсом.",
    O = "Візьми Форму Скелетного Ключа і 2 Торієвих Злитки на вершину Вогняного Шлейфу в кратері Ун’Ґоро. Використай Форму Скелетного Ключа біля озера лави, щоб викувати Незавершений Скелетний Ключ.$B$BПринеси Незавершений Скелетний Ключ до Аптекаря Дітерса на Бастіоні, Західні Зачумлені Землі.",
    P = "Ви закінчили ніжку скелетного ключа? Мені щиро шкода, що вам довелося взяти на себе основний тягар гонорару, щоб придбати форму, але ми всі повинні зробити свій внесок у протистояння Бичу. Щойно ви передасте мені незавершений ключ, ви будете готові до останнього предмета, необхідного для завершення його будівництва.$B$BIt буде зовсім непросто, але робота, яку ви виконали на сьогоднішній день під час підготовки до нападу на Андорал, тепер почне окупатися. Ви побачите.",
    C = "У нас там досить дорогий скелетний ключ, чи не так $N? І все ж він залишається незавершеним; настав час зосередитися на нашому створенні. З цією метою вам доведеться зіткнутися з головним ворогом, проти якого ми намагалися зіткнутися в Андоралі... істотою, яка керує шоу серед зруйнованих міських стін.$B$BI Я говорю про Араджа Призивача — лича та одну з наймогутніших істот, яких Бич називає своєю.",
},

[5803] = {
    en = "Araj's Scarab",
    T = "Скарабей Арая",
    D = "Арай Заклинатель панує над Андоґалом із прихованого місця. Ми знаємо, що він був попереднім лідером Схоломансу, перш ніж захопив місто. Щоб завершити ключ, нам потрібен його перстень — так званий скарабей — який стане головкою ключа.$B$BУ місті є чотири кристали виклику, по одному в кожній вежі, які ти раніше позначив для нас. Знищ усі чотири кристали, щоб зруйнувати його владу над містом і виманити його на відкрите місце. Після цього забери його скарабея з його знищеного філактерію!",
    O = "Знищ чотири Кристали Виклику Плеті в Андоґалі, щоб викликати Арая Заклинателя. Знищ Арая Заклинателя і принеси Скарабея Арая до Алхіміка Арбінґтона в Точці Холодовітрів, Західні Зачумлені Землі.",
    P = "Ви зайшли так далеко $N — лише знищення фізичної форми Араджа Прикликача дасть нам можливість закінчити ключ. Здобудь скарабея Араджа всіма неправдами й неправдами й принеси його мені — я сплавлю його як головку ключа.",
    C = "Так, це все! Я... знову ж таки, я абсолютно вражений глибиною вашої хитрості та хоробрості. Це просто вражає, на що ви готові піти, щоб досягти перемоги.$B$BAllow зараз я хочу зіграти свою маленьку роль у цьому. Я підготував спеціальний розчинник, який повинен дозволити мені закріпити скарабея як головку ключа, наповнивши його силою, щоб зламати замкнені двері Шоломантії.$B$BThis це займе хвилинку...",
},

