[5844] = {
    en = "Welcome!",
    T = "Вітаємо!",
    D = "Ласкаво просимо до світу World of Warcraft!$B$BЯк особливу подяку за покупку Колекційного Видання World of Warcraft, здай цей подарунковий ваучер Ворну Небесному Провидцю в Таборі Нараче. Тобі дадуть подарунок: маленького супутника, який приєднається до тебе у твоїх пригодах і славі.$B$BЩе раз дякуємо, і насолоджуйся своїм перебуванням у світі World of Warcraft!",
    O = "Принеси Подарунковий Ваучер Табору Нараче до Ворна Небесного Провидця.",
    P = "вітаю! Дуже приємно з вами познайомитися!$B$BI бачу, що у вас є спеціальний ваучер. Віддайте мені, і я запропоную вам щось в обмін.",
    C = "Ти справді особливий герой, $N. Ми вітаємо вас у світі Азероту та пропонуємо вам один із цих унікальних подарунків!",
},

[5845] = {
    en = "Of Lost Honor",
    T = "Про втрачену честь",
    D = "Орден Срібної Долоні був повністю знищений, коли Утер був убитий.$B$BХлопець тримався, скільки міг. Відтіснений до зруйнованого селища Нортдейл, він зробив свій останній бій.$B$BЧи залишився хтось із Ордену живим, думав він — і чи мало це значення?$B$BСаме з цією думкою Таелан кинув штандарт Ордену і відрікся від усього, що знав. Його честь залишилася на просякнутій кров’ю землі Нортдейлу.$B$BТи мусиш вирушити до Нортдейлу і повернути цей символ втраченої честі.",
    O = "Вирушай до Нортдейлу, у північно-східній частині Східних Зачумлених Земель, і поверни Символ Втраченої Честі. Повернися до Тіріона Фордрінґа після виконання завдання.",
    P = "Моя віра буде вести тебе, $N. Світло не знає меж.",
    C = "Зараз він такий же чудовий — навіть у своєму пошарпаному стані — як того дня, коли я подивився на нього й присягнув на вірність.$B$BHis спокута приходить і, можливо, моя з нею...",
},

[5846] = {
    en = "Of Love and Family",
    T = "Про любов і сім’ю",
    D = "Коли Таелан був дитиною, ми часто відвідували Каер Дарроу під час сімейних подорожей. Під час нашого останнього візиту художниця на ім’я Ренфрей намалювала наш портрет на березі моря. Це мій найтепліший спогад про Таелана і Карандру. Бо саме в той момент, тримаючи дружину і сина в обіймах, я відчув зв’язок любові і сім’ї, якого більше ніколи не зазнаю.$B$BЯкщо цей портрет досі існує, ти мусиш його знайти.$B$BВирушай до зруйнованого острова Каер Дарроу і перевір, чи залишилися портрет або художниця.",
    O = "Вирушай на острів Каер Дарроу, у південно-центральній частині Зачумлених Земель, і пошукай будь-які підказки щодо місця знаходження портрета.",
    P = "",
    C = "Як я міг забути? Багато духів на цьому острові прокляті, щоб знову пережити свій останній щасливий спогад, перш ніж зустріти свій трагічний кінець.$B$BI я теж проклятий, але не так, як вони - я один із небагатьох, хто пам’ятає все...$B$BМожливо ця річ, про яку ви мене запитуєте, чому я переслідую ці руїни. Можливо, те, що я вам скажу, звільнить мене.",
},

[5847] = {
    en = "Welcome!",
    T = "Вітаємо!",
    D = "Ласкаво просимо до світу World of Warcraft!$B$BЯк особливу подяку за покупку Колекційного Видання World of Warcraft, здай цей подарунковий ваучер Клер Вілловер у Смертекличі. Тобі дадуть подарунок: маленького супутника, який приєднається до тебе у твоїх пригодах і славі.$B$BЩе раз дякуємо, і насолоджуйся своїм перебуванням у світі World of Warcraft!",
    O = "Принеси Подарунковий Ваучер Смертекличу до Клер Вілловер у Смертекличі.",
    P = "вітаю! Дуже приємно з вами познайомитися!$B$BI бачу, що у вас є спеціальний ваучер. Віддайте мені, і я запропоную вам щось в обмін.",
    C = "Ти справді особливий герой, $N. Ми вітаємо вас у світі Азероту та пропонуємо вам один із цих унікальних подарунків!",
},

[5848] = {
    en = "Of Love and Family",
    T = "Про любов і сім’ю",
    D = "Портрет... Він висів на стіні моєї майстерні — всередині казарм Ордену — роками.$B$BПісля суду над Тіріоном я зрозумів, що більше не можу тримати портрет на видноті. Я сховав його там, де ніхто б не подумав шукати.$B$BВирушай до Стратгольма і проберися глибоко в те, що тепер є Бастіоном Багряного Походу, пошукай картину із зображенням наших двох місяців. Відколи фарбу, поки не знайдеш мій шедевр, «Про любов і сім’ю». $B$BХай Світло скеровує твої дії.",
    O = "Вирушай до Стратгольма, у північній частині Зачумлених Земель. У Бастіоні Багряного Походу ти знайдеш картину «Про любов і сім’ю», сховану за іншою картиною, що зображує два місяці нашого світу.$B$BПоверни картину до Тіріона Фордрінґа.",
    P = "Картина, $N. У вас є картина?",
    C = "<Тіріон ледь не впав, коли побачив картину.>$B$B<Він починає майже несамовито ридати.>",
},

[5861] = {
    en = "Find Myranda",
    T = "Знайди Міранду",
    D = "$N, ти виконав усе, що я просив досі. Залишився лише один крок у твоєму пошуку спокути.$B$BТи мусиш доставити зібрані предмети до Таелана. На жаль, Таелан і його Багряні Хрестоносці нападуть на тебе, щойно побачать.$B$BЄ лише один спосіб передати моє повідомлення — через обман.$B$BНа півдні ти знайдеш могилу Утера. Там тепер живе моя давня і вірна подруга Міранда — розшукай її. Покажи їй предмети, і вона тобі допоможе.",
    O = "Вирушай до Могили Утера, розташованої в південних Зачумлених Землях. Покажи Міранді Подарунок Тіріона.",
    P = "Я знав, що цей день настане.",
    C = "Я був найбільш довіреним радником Тіріона, коли він мав ранг лорда Марденхольда. Я відкрито не погоджувався з вироком, ухваленим Орденом Срібної Руки, і був вигнаний за свою зухвалість.$B$BHe пережив багато душевного болю та розчарувань у своєму житті, $R. Чи готові ви виправити помилки, завдані Fordrings?",
},

[5862] = {
    en = "Scarlet Subterfuge",
    T = "Багряний обман",
    D = "Я те, що можна назвати ілюзіоністкою. Хоча я можу створити ілюзію, яка дозволить тобі увійти до Гартґлена, попереджаю: мої сили мають свої межі.$B$BЯкщо ти відійдеш надто далеко від цих земель, ефект ілюзії припиниться. Саме заклинання вимагає від мене величезної концентрації і сили, тому я можу підтримувати його лише короткий час.$B$BПоговори зі мною знову, коли будеш готовий.",
    O = "Поговори з Мірандою, щоб отримати Багряну Ілюзію. Вирушай до Гартґлена під Багряною Ілюзією і передай Подарунок Тіріона Верховному Лорду Таелану Фордрінґу.$B$BГартґлен на півночі, Таелан має бути в Твердині Марденгольд.",
    P = "Ви підкріплення з Руки Тира?",
    C = "Що це, солдате?$B$B<Таелан відкриває коробку й починає розглядати її вміст.>$B$BThis... це не може бути правдою. Але все, що ти мені показав...$B$B<Телан падає на одне коліно, його серце б’ється частіше. Лют віків ось-ось обрушиться на це місто.>",
},

[5863] = {
    en = "The Dunemaul Compound",
    T = "Табір Дюнебій",
    D = "Нещодавно в Танарісі з’явилася велика група кочових оґрів. На південь звідси вони захопили велику частину пустелі і створили табір. Кілька менших груп зараз блукають пустелею, деякі з них вторглися до старих трольських руїн.$B$BТабір Дюнебій мусять знищити! Ми не можемо дозволити цим оґрам зібрати сили.$B$BЛідером цієї групи є Ґор’марок Спустошник; я вірю, що припинення його правління стане початком кінця для оґрів.",
    O = "Енді Лінн у Ґаджетзані хоче, щоб ти знищив Табір Дюнебій, убивши 10 Дюнебійських Бруталів, 10 Дюнебійських Виконавців і Ґор’марока Спустошника.",
    P = "я так хвилююсь! Будь ласка, будьте обережні!",
    C = "Я дуже радий, що ти зміг зробити це для мене, $N! Дякуємо за допомогу!",
},

[5881] = {
    en = "Calling in the Reserves",
    T = "Заклик резервів",
    D = "Орда добре справляється з підтримкою свіжих військ... після Великої Війни ми процвітали тут, у Калімдорі.$B$BМені потрібна твоя допомога. У мене є хлопець на ім’я Ґріш Довгобіг, який охороняє Великий Підйомник у південних Степах. Передай йому цього листа; він повідомить йому, що я направив резервного воїна, щоб звільнити його від служби, щоб він міг відвідати свою сім’ю. Він просив про це давно, і буде радий почути ці новини.",
    O = "Маґґран хоче, щоб ти доставив листа до Ґріша Довгобіга на Великий Підйомник у Степи.",
    P = "У вас є новини від Maggran Earthbinder?",
    C = "Це чудова новина; Я надто довго сиджу тут, охороняючи цей шматок лісу. Тепер я можу провести деякий час зі своєю родиною... Ура!",
},

[5882] = {
    en = "Salve via Hunting",
    T = "Мазь через полювання",
    D = "",
    O = "",
    P = "Володіння Маяком Кенаріону дозволяє побачити зіпсований осколок душі на тих зіпсованих звірах, яких принижують заради загального блага. Я подрібнюю осколки на придатний для використання реагент, який використовується для виготовлення рослинної мазі Cenarion. Ми використаємо цю мазь, щоб знову перетворити зіпсовані рослини на здорові.$B$BIn обміняйте на ці осколки, я дам вам кілька мазей для рослин Кенаріону, які я вже приготував.",
    C = "Тоді добре, ось ваші рослинні мазі Кенаріону. Очистіть Осквернений ліс у пошуках пошкоджених рослин, $n! Де б вони не були, використовуйте мазь, яку я дав вам, щоб очистити їх.",
},

[5883] = {
    en = "Salve via Mining",
    T = "Мазь через видобуток",
    D = "",
    O = "",
    P = "Якщо ви володієте маяком Кенаріону під час видобутку в Оскверненому лісі, ви зможете побачити заплямований купорос, який руйнує жилу сирого металу. Я знаю, як очистити цей купорос і перетворити його на реагент, який використовується для виготовлення рослинної мазі Ценаріон. Потім ви використаєте цю мазь для знайдених у дикій природі рослин, які потребують збереження.$B$BIf якщо ви зібрали будь-який забруднений купорос, я дам вам мазь для рослин Кенаріон, яку я вже приготував.",
    C = "Тоді добре, ось трохи рослинної мазі Cenarion. Якщо під час видобутку у Фелвуді ви знайдете більше купоросу, не забувайте тримати його для мене! Що більше ти знайдеш, то більше мазі я зможу зробити.",
},

[5884] = {
    en = "Salve via Gathering",
    T = "Мазь через збирання",
    D = "",
    O = "",
    P = "Маяк Кенаріону дозволяє досвідченому травнику помітити підступного повзуна Скверни — зловмисного продукту корупції Фелвуда. Моя робота тут навчила мене знанням очищення фел-крипа в очищувальний реагент... який використовується в тому, що ми зараз називаємо рослинною маззю Кенаріону.$B$BWhen якщо ви збираєте трави у Сквернячому лісі, ви повинні зустрітися з фел-крипом, якщо у вас є маяк. В обмін на те, що ви мені принесете, я дам вам готову рослинну мазь Кенаріону.",
    C = "Чудова робота $n - кожен шматочок цього, щойно ми його очистимо, допоможе нам повернути Фелвуд. Тут візьміть кілька доз рослинної мазі Cenarion і вирушайте в ліс. Повернення землі у корупціонерів не чекає $r!",
},

[5885] = {
    en = "Salve via Ski$b$bing",
    T = "Мазь через здирання шкіри",
    D = "",
    O = "",
    P = "Маяк Кенаріону дозволить добре навченому шкуродеру помітити плями зіпсованої шкіри з нагород, зібраних у Спустошеному лісі. Я перетворюю ці, здавалося б, марні пластирі на густу пасту, яка служить прискорювачем для рослинної мазі Cenarion. Коли зніматимете шкіру зі своїх убитих тут, у Фелвуді, обов’язково майте на собі маяк!$B$BWhen ви збирайте зіпсовані плями, принесіть їх мені, і я дам вам кілька рослинних мазей Кенаріону, які я вже зробив.",
    C = "Це саме те, що мені потрібно. Ось — візьміть ці рослинні мазі та використовуйте їх, щоб відновити Фелвуд від корупції. Ми повинні вистояти, $n!",
},

[5886] = {
    en = "Salve via Disenchanting",
    T = "Мазь через розщеплення",
    D = "",
    O = "",
    P = "Сила розчарованого магічного предмета відчувається есенцією, яку він створює. Я винайшов спосіб перетворити сиру есенцію, яку використовують чарівники, на відповідний реагент для створення рослинної мазі Кенаріону. Для цього вам не потрібен маяк Кенаріону; будь-який відповідним чином розчарований предмет, який дає менші есенції пустот, буде працювати.$B$BI потрібна лише одна менша есенція пустот; в обмін я дам тобі рослинні мазі Кенаріону. Есенція надзвичайно сильна - невелика кількість однозначно допоможе!",
    C = "Ось деякі рослинні мазі Кенаріону — для цього мені потрібна лише одна менша есенція Пустоти, $n. Есенція — це, безумовно, найпотужніший предмет, який я можу використати, щоб перетворити мечі на орала. Якщо вам потрібна ще мазь, то знайдіть мене тут!",
},

