[6221] = {
    en = "",
    T = "Мертводреви Півночі",
    D = "Прямо на південний захід від нас є табір фурболгів Мертводревів. Скверна пронизує цей табір, і я хочу покласти цьому край, перш ніж вони стануть проблемою.$B$BПлем’я Мертводревів зле, але це вплив фелу псує їхні розуми. Їхня ворожість не є природною, але їм уже не допоможеш. Через це мені дуже боляче воювати з власними братами.$B$BБудь ласка, $N, зроби те, що необхідно, і не розповідай подробиць; вони надто мене засмучують.",
    O = "Нафієн хоче, щоб ти убив 5 вартових Мертводревів, 5 месників Мертводревів і 5 шаманів Мертводревів.",
    P = "",
    C = "",
},

[6241] = {
    en = "",
    T = "Активність Зимопадів",
    D = "Плем’я Зимопадів дедалі більше ворогує з нами. Вони, здається, охоплені люттю, повністю поглинені власним страхом і ненавистю до всього, що їм незрозуміле.$B$BЯкщо ти зменшиш їхню чисельність, це дуже нам допоможе, $N.",
    O = "Салфа хоче, щоб ти убив 6 тотеміків Зимопадів, 6 вартових Зимопадів і 6 слідопитів Зимопадів.",
    P = "",
    C = "",
},

[6261] = {
    en = "Dungar Longdrink",
    T = "Дунґар Довгопий",
    D = "$N, я зібрав у цю скриню все, що просив Льюїс. Чи можеш ти віднести її йому?$B$BЯкщо ти вже говорив із Тором у Західному Краї, то можеш узяти грифона назад до нього. Дунґар Довгопий — наш господар грифонів, він у торговому районі.$B$BПоговори з Дунґаром, а потім достав цю скриню до Льюїса якнайшвидше. Ми не хочемо, щоб наші воїни та воїтельки в Західному Краї залишилися без свіжого спорядження!",
    O = "Віднеси скриню Осріка до господаря грифонів Дунґара Довгопия.",
    P = "Це піт на твоєму чолі, хлопче? Ти забагато бігав. Наступного разу візьміть грифона!",
    C = "Ящик для Westfall, еге ж? Ви вже були в Westall? Якщо так, то це не проблема, друже. У мене є багато грифонів, навчених літати цим маршрутом!",
},

[6281] = {
    en = "Continue to Stormwind",
    T = "Продовжуй до Штормовію",
    D = "За невелику плату ти можеш узяти грифона до Штормовію, щоб доставити записку Льюїса до Осріка. Немає швидшого способу дістатися туди.$B$BЯкщо тобі це підходить, поговори зі мною ще раз, коли будеш готовий до польоту. Я візьму трохи монет, але повір мені; воно того варте!",
    O = "Купи політ на грифоні у господаря грифонів Тора, а потім віднеси записку Льюїса до Осріка Странґа в крамниці «Обмежений Імунітет» у Старому Місті Штормовію.",
    P = "Ви подорожували, еге ж? Ви десь цікаво були?",
    C = "А, записка від інтенданта Льюїса? Я не здивований, що йому потрібно більше спорядження. Пагорб Сентинел далеко, у країні, про яку Штормовій майже забув.$B$BWell дякую, $N. Ось трохи грошей, щоб покрити витрати на дорогу.",
},

[6282] = {
    en = "Harpies Threaten",
    T = "Загроза гарпій",
    D = "Таурети пишаються тим, що є захисниками цих земель. Без сумніву, ти можеш здогадатися, чому я стурбований кількістю гарпій, які тут оселилися в Кам’яних Кігтях.$B$BКривавопір’ї — джерело зростання числа гарпій у Калімдорі; вони загрожують усьому живому, не даючи невинним залишити свої межі.$B$BМені потрібно, щоб ти прорідив гарпій, $N!",
    O = "Маґґран Землебinder у Притулку Сонячної Скелі хоче, щоб ти убив 7 гарпій Кривавопір’їв, 7 засідальниць Кривавопір’їв, 7 убивць Кривавопір’їв і 7 шахрайок Кривавопір’їв.",
    P = "Не втомлюйтеся від Обвугленої долини; на цих пагорбах мешкає багато злих створінь. Будь сильним $N, і ти переможеш над цією загрозою для нашого народу. Іди зараз і бий сильно - наші діти ніколи не дізнаються про зло того, що було.",
    C = "Це чудова новина! Розкажи мені ще раз, як ти вселив страх у холодні серця цих мерзенних гарпій. Криваві люті завдали серйозного удару!",
},

[6283] = {
    en = "Bloodfury Bloodline",
    T = "Родовід Кривавопір’їв",
    D = "Проріджування числа гарпій Кривавопір’їв недостатньо. Єдиний справжній засіб від їхньої зарази — убити їхню лідерку, Кривавопір’ю Різницю!$B$BВона для тих бридких істот ніби королева. Убий її, і їхня чисельність точно зменшиться.$B$BПовернися до Обвугленої Долини, і ти знайдеш її вздовж західних пагорбів. Її нелегко здолати, але нагорода буде щедрою.",
    O = "Маґґран у Притулку Сонячної Скелі бажає, щоб ти убив Кривавопір’ю Різницю і приніс її рештки як доказ твого подвигу.",
    P = "Bloodfury Ripper - неприємна істота! Вам вдасться знайти її вздовж західної лінії пагорба в Обвугленій долині.$B$BThe криваві люті будуть безпорадні без... ми, звичайно, можемо перемогти їх назавжди!",
    C = "Я вже відчуваю, як гнів покидає мене. Що я буду робити зі своїм часом? Знання злих ходів біля моєї землі тримало мої думки в русі, хоча тепер вони мовчать. Можливо, це добре... можливо, тепер я можу зосередитися на хорошому, як і повинні всі таурени.$B$BPlease прийміть це як нагороду за ваші проблеми.",
},

[6284] = {
    en = "Arachnophobia",
    T = "Арахнофобія",
    D = "Попередження: заходь до каньйону Сішир на захід звідси на власний ризик.$B$BБесселет і її восьминогі діти лісу захопили цей каньйон, зробивши його своїм павутинним лігвом.$B$BМаґґран Землебinder у Притулку Сонячної Скелі оголосив нагороду за Бесселет. Убий її і принеси доказ убивства до Маґґрана; там ти отримаєш свою нагороду за знищення цієї восьминогої загрози.",
    O = "Убий Бесселет і принеси її ікло до Маґґрана у Притулку Сонячної Скелі.",
    P = "Бесселет — безжальний хижак... Я боюся за тих, хто мандрує Шляхом Павутини вночі. Саме тоді вона та її діти полюють на невинних мандрівників. Я сам став жертвою її двофутового ікла смерті, але, на щастя, мені вдалося відбити її та втекти в безпечне місце. Я віддав би все, щоб цього монстра знищили.",
    C = "Гарного полювання, $N! Бесселет — стара хижачка в цих краях... Я не сумуватиму за нею. Прийміть цю нагороду як символ того, що ви є чемпіоном у лісі.$B$B<Маґгран розтирає рану, завдану Бесселетом.>$B$BМожливо тепер ще багато людей відправляться до Sun Rock Retreat, не боячись того, що ховається в темряві.",
},

[6285] = {
    en = "Return to Lewis",
    T = "Повернення до Льюїса",
    D = "Господар грифонів у Західному Краї — Тор. Якщо ти вже говорив із ним раніше, то можеш узяти одного з моїх грифонів до нього.$B$BЦе хороший урок: грифони завжди навчені літати до столиці, але вони повезуть тебе до віддаленого господаря грифонів лише після того, як ти там побував.$B$BТи вже був у Тора, тож просто поговори зі мною ще раз, коли будеш готовий узяти грифона до Західного Краю. Там ти зможеш доставити скриню Осріка до квартирмейстера Льюїса.",
    O = "Купи політ на грифоні до Сторожового Пагорба у господаря грифонів Дунґара Довгопия, а потім віднеси скриню Осріка до Льюїса на Сторожовому Пагорбі.",
    P = "Ти повернувся зі Штормовія? Осрік надіслав броню?",
    C = "Чудово, ти приніс броню! Ми негайно передамо це тим, хто цього потребує.$B$BThank ти, $N. Ваші зусилля дуже допомогли нам. І тепер, коли грифони вам не чужі, я сподіваюся, що ви часто приходитимете на допомогу Сентинел Хілл!",
},

[6301] = {
    en = "Cycle of Rebirth",
    T = "Цикл відродження",
    D = "Промислова жадоба і безперервна війна спустошили землі Кам’яних Кігтів. Лише благословення Матері-Землі можуть зцілити такі рани.$B$B$N, мені потрібне особливе насіння, насіння Ґеї. Його можна знайти лише тут, у горах Кам’яних Кігтів, на північ від Притулку Сонячної Скелі, біля озера Міркфаллон, поблизу берега.$B$BКоли принесеш мені насіння, я наділю їх шаманською силою, щоб прискорити їхній ріст.",
    O = "Таммра Віндфілд у Притулку Сонячної Скелі хоче, щоб ти зібрав 10 насінин Ґеї.",
    P = "Безперервне руйнування, спричинене війною та тими, хто шукає прибутку від деревини, мене глибоко болить. Найменше, що я можу зробити, це виконати цикл відродження та посіяти насіння Геї, щоб поповнити землі новим лісом. У вас є необхідні насіння Gaea, $C?",
    C = "а? $N, у вас є насіння Gaea. Дивіться, і ви побачите силу, яку ці насіння принесуть землі. Лише ті чисті та правдиві можуть зцілити землю?$B$B<Таммра починає співати.>",
},

[6321] = {
    en = "Supplying the Sepulcher",
    T = "Постачання Сепульхра",
    D = "Екзекутор Гадрек попросив мене перевірити наше спорядження в Сепульхрі. З Плетивою і ще гіршими створіннями, що ховаються в лісах, він не хоче, щоб Смертостражі залишилися без потрібного обладнання.$B$BЯ виявив, що загалом ми добре забезпечені, але нам бракує зброї, щоб замінити втрачену в бою.$B$BОсь замовлення на те, що потрібно, для торговця зброєю Ґордона Вендгама в Мертвому Місті. Віднеси замовлення до нашого господаря кажанів, Кароса Разока, і поговори з ним про транспорт до Мертвого Міста.",
    O = "Віднеси замовлення Подріґа до Кароса Разока.",
    P = "Ви, здається, у службових справах...",
    C = "Ах, замовлення на припаси.  Безсумнівно, ви захочете взяти це з собою в Підмісто.  І швидко, тому що гріб не повинен залишатися недоповненим.",
},

[6322] = {
    en = "Michael Garrett",
    T = "Майкл Ґаррет",
    D = "Я склав припаси Сепульхра в цю скриню. Якщо ти вже був у Сепульхрі і говорив із їхнім господарем кажанів, то можеш полетіти назад до нього на кажані.$B$BПоговори з господарем кажанів Мертвого Міста, Майклом Ґарретом. Він може надати тобі кажана до Сепульхра.",
    O = "Віднеси скриню Ґордона до Майкла Ґаррета.",
    P = "Якщо вам потрібно подорожувати на велику відстань, то кажан — найкращий варіант.",
    C = "Цей ящик має дістатися до гробниці в Сільверпайні? Це легко зробити; наші кажани літають туди щодня.",
},

[6323] = {
    en = "Ride to the Undercity",
    T = "Політ до Мертвого Міста",
    D = "Один із моїх кажанів може відвезти тебе до Мертвого Міста за невелику плату. Поговори зі мною ще раз, коли будеш готовий, щоб ми могли організувати твій транспорт.$B$BТи знайдеш Ґордона Вендгама в Торговому Кварталі Мертвого Міста. Це той самий квартал, де приземлиться мій кажан.",
    O = "Купи політ на кажані до Мертвого Міста у господаря кажанів Кароса Разока, а потім віднеси замовлення Подріґа до Ґордона Вендгама в Мертвому Місті.",
    P = "Я зберігаю свою зброю в ідеальному стані. Вони очищені та готові до використання.",
    C = "Наказ від Гробу? Дуже добре. Це честь служити тим, хто служить нашій Темній Леді.",
},

[6324] = {
    en = "Return to Podrig",
    T = "Повернення до Подріґа",
    D = "Господар кажанів у Сепульхрі — Карос Разок. Якщо ти вже зустрічався з ним, то я можу дати тобі кажана, щоб полетіти назад до нього.$B$BНаші кажани завжди літають до Мертвого Міста, але для подорожей до віддаленіших місць їхній вершник спершу мусить відвідати те місце і поговорити з тамтешнім господарем кажанів.$B$BТи зустрічав Кароса в Сепульхрі, тож тепер можеш літати туди на кажанах. Поговори зі мною, коли будеш готовий.",
    O = "Купи політ на кажані до Сепульхра у господаря кажанів Майкла Ґаррета, а потім віднеси скриню Ґордона до Смертостража Подріґа в Сепульхрі.",
    P = "$N, ти повертаєшся. У вас є наші запаси з Підміста?",
    C = "Гарна робота, $N. Ця зброя гарантує, що наші Охоронці смерті не будуть спіймані непідготовленими.$B$BYou зробили цінну послугу для нашої Темної Леді.",
},

[6341] = {
    en = "The Bounty of Teldrassil",
    T = "Дари Тельдрассіля",
    D = "Рибалки села Рут’теран дуже успішні, адже риба тут надзвичайно велика і численна. Я хотів би порівняти багатство тут із тим, що на материку.$B$BУ мене є колекція риб’ячих кісток і луски, яку я хотів би передати своєму колезі в Темнобережжі. Його звати Лейрд, він торговець рибою в селі Аубердін.$B$BВіднеси мою колекцію до нашого господаря гіпогрифів, Веспрістуса, і поговори з ним про подорож до Аубердіна.",
    O = "Віднеси колекцію Несси до Веспрістуса.",
    P = "Чим я можу вам допомогти? Вам потрібен транспорт?",
    C = "А, ти хочеш передати це Обердіну? Дуже добре...",
},

[6342] = {
    en = "Flight to Auberdine",
    T = "Політ до Аубердіна",
    D = "З Рут’терану до Аубердіна є два способи подорожі: поромом і гіпогрифом. Обидва швидкі й надійні, але якщо ти ще не літав до Аубердіна на гіпогрифі, я раджу спробувати.$B$BЦе розумна порада — говорити з господарем гіпогрифів у кожному місті, де він є. Після розмови з господарем ти зможеш літати туди з інших міст.$B$BОсь колекція Несси. Поговори зі мною ще раз, коли будеш готовий полетіти до Аубердіна і доставити колекцію Несси до Лейрда.",
    O = "Полети на гіпогрифі до Аубердіна від господаря гіпогрифів Веспрістуса, а потім віднеси колекцію Несси до Лейрда.",
    P = "Ви прийшли з Тельдрассила? Розкажи, як там рибалка?",
    C = "Пакунок від Несси? Дякую, $N! Вона сказала мені, що надішле мені зразки риби, виловленої біля села Рут'теран. Вона вважає, що вони можуть сильно відрізнятися від риби, спійманої тут...$B$BMy! Ця щелепна кістка майже вдвічі більша за ту саму рибу, що тут знайдена. А ці луски великі, як кулак! Дивовижно!",
},

[6343] = {
    en = "Return to Nessa",
    T = "Повернення до Несси",
    D = "Я мушу надіслати відповідь Нессі. Їй буде дуже цікаво дізнатися, наскільки відрізняється риба тут від тієї, що вздовж узбережжя Тельдрассіля. Ми можемо лише здогадуватися про причину, але я підозрюю, що саме світове дерево впливає на дику природу навколо!$B$BБудь ласка, віднеси цю відповідь Нессі. Якщо хочеш повернутися до Рут’терану на гіпогрифі, поговори з господинею гіпогрифів Кейлайс Мунфезер. Якщо віддаєш перевагу порому, він регулярно відпливає від пристані на північний захід.",
    O = "Віднеси відповідь Лейрда до Несси Шедоусонґ.",
    P = "$N, ти повернувся з Auberdine? Ви розмовляли з Лердом?",
    C = "Це дуже цікаво. Риба тут велика, але я не думав, що різниця в нагородах між тут і материком така велика. Для цього має бути причина...$B$BWell дякую, $N. Я обговорю з селянами новини, які ви принесли. Можливо, колись ми знайдемо корінь цієї дивацтва. Але до того часу ми будемо пожинати його плоди!",
},

[6344] = {
    en = "Nessa Shadowsong",
    T = "Несса Шедоусонґ",
    D = "Моя подруга, Несса Шедоусонґ, — рибна торговка в селі Рут’теран. Їй потрібно доставити посилку до Темнобережжя, і вона шукає когось, хто б допоміг.$B$BЯкщо тобі цікаво, то, щоб дістатися до Несси, тобі потрібно пройти через портал у Дарнассі до села Рут’теран. Портал розташований на захід від Садів Храму.",
    O = "Поговори з Нессою Шедоусонґ.",
    P = "",
    C = "Так, мені потрібен кур'єр, який відвезе посилку в Даркшор. Ви мені допоможете?",
},

[6361] = {
    en = "A Bundle of Hides",
    T = "В’язка шкур",
    D = "У мене є в’язка шкур із тварин Степів, і я мушу доставити їх до Громового Бескиду. Мій колега там, Агану, використає шкури для створення шкіряних виробів.$B$BЧи віднесеш ти ці шкури до нього для мене?$B$BНайшвидший шлях до Громового Бескиду — на спині вітрокрила. Віднеси в’язку шкур до Деврака, нашого господаря вітрокрилів у Перехресті, і поговори з ним про транспорт до Громового Бескиду.",
    O = "Віднеси в’язку шкур до господаря вітрокрилів Деврака в Перехресті.",
    P = "Ви тут заради вітряного вершника? Маєш що транспортувати?",
    C = "Якщо вам потрібно віднести ці шкури до Громового Утесу, тоді ви розмовляєте з правильним орком!",
},

[6362] = {
    en = "Ride to Thunder Bluff",
    T = "Політ до Громового Бескиду",
    D = "За невелику плату я дам тобі вітрокрила до Громового Бескиду. Немає швидшого способу дістатися до міста!$B$BЯкщо це тобі підходить, поговори зі мною ще раз, коли будеш готовий.$B$BЯкщо ти везеш ці шкури до Агану, то, здається, він у Зброярні Геви, біля основи вежі вітрокрилів у Громовому Бескиді. І саме туди ти приземлишся!",
    O = "Купи політ на вітрокрилі до Громового Бескиду у господаря вітрокрилів Деврака, а потім віднеси в’язку шкур до Агану в Громовому Бескиді.",
    P = "На твоїх плечах лежить порох, який, мабуть, із Степлі. Ви говорили з моїм другом Джаханом?",
    C = "Ах, нова пачка шкур. Я негайно приступлю до них!$B$BThank ти, брате. Ви зробили мені велику послугу. Ось кілька монет для оплати вашого часу та витрат на дорогу.",
},

[6363] = {
    en = "Tal the Wind Rider Master",
    T = "Тал, господар вітрокрилів",
    D = "Я підготував шкіряні вироби для Джагана, щоб він продавав їх у Перехресті. Чи віднесеш ти їх до нього?$B$BЯкщо ти вже був у Перехресті і говорив із їхнім господарем вітрокрилів, то можеш полетіти назад до нього на одному з наших вітрокрилів Громового Бескиду.$B$BВіднеси шкіряні вироби до Тала, нашого господаря вітрокрилів у Громовому Бескиді, і поговори з ним, щоб організувати транспорт до Перехрестя.",
    O = "Віднеси шкіряні вироби Агану до Тала в Громовому Бескиді.",
    P = "Вітаю, $C. Що я можу для вас зробити?",
    C = "Вам потрібно віднести це на Перехрестя, еге ж? Це не біда. Якщо ви вже були там і розмовляли з Девраком, то можете відвезти до нього одного з моїх вітряних вершників.",
},

[6364] = {
    en = "Return to Jahan",
    T = "Повернення до Джагана",
    D = "Щоб полетіти до міста, ти мусиш уже побувати там і поговорити з тамтешнім господарем вітрокрилів. Ти був у Перехресті і говорив із їхнім господарем вітрокрилів Девраком, тож за невелику плату ти можеш узяти вітрокрила до нього звідси.$B$BПоговори зі мною ще раз, коли будеш готовий. У Перехресті ти зможеш доставити шкіряні вироби до Джагана Гоквінґа.",
    O = "Купи політ на вітрокрилі до Перехрестя у господаря вітрокрилів Тала, а потім віднеси шкіряні вироби Агану до Джагана Гоквінґа.",
    P = "$N, ти повернувся з Thunder Bluff? Ти доставив шкури Ахану?",
    C = "Ахану прислав мені готову продукцію? Дуже добре. Зараз на Перехресті багато мисливців і шукачів пригод, і бізнес йде жваво. Я впевнений, що дуже скоро продам ці товари.$B$BThank за всі ваші зусилля, $N. Я у вашому боргу.",
},

[6365] = {
    en = "Meats to Orgrimmar",
    T = "М’ясо до Оргріммара",
    D = "У мене є відбірні шматки м’яса, які я хочу відправити подрузі. Її звати Ґришка, вона корчмарка в Оргріммарі. Чи доставиш ти це м’ясо для мене?$B$BНайшвидший шлях до Оргріммара — на вітрокрилі. Віднеси м’ясо до господаря вітрокрилів у Перехресті, Деврака, і поговори з ним про транспорт до Оргріммара.",
    O = "Віднеси м’ясо Зарґа до Деврака в Перехресті.",
    P = "Вам потрібно кудись швидко дістатися? Тоді ти розмовляєш із правильним орком!",
    C = "Ви повинні доставити це м'ясо в Оргріммар? Це не проблема. За невелику плату мій вітряк може доставити вас туди.",
},

[6381] = {
    en = "New Life",
    T = "Нове життя",
    D = "Як ти бачив, $c, хоч земля і страждає, цикл життя — потужна річ. Тепер ми мусимо зробити свій внесок, щоб допомогти йому. Ти мусиш посадити ці насінини в центрі руйнувань, на захід, в Обвугленій Долині. Будь обережний, адже гарпії та розлючені вогняні елементалі все ще терзають цю понівечену землю.$B$B$N, візьми ці зачаровані насінини Ґеї і посади їх у родючі купи ґрунту. Цикл життя мусить тривати!",
    O = "Посади 10 насінин Ґеї в купи ґрунту Ґеї, а потім поверни решту зачарованих насінин Ґеї до Таммри у Притулку Сонячної Скелі.",
    P = "Ці насіння, які ви садите, є сильними, протистоять корупції та створюють опору для іншого життя. Вони будуть рости й рости, спершу запобігаючи корупції та зцілюючи пошкоджену землю, а потім одного дня знову відновлюючи Стонеталон у пишний ліс.$B$BHave ви посіяли все насіння Геї?",
    C = "Це велика перемога для краю. Згодом станеться інше: Венчурна компанія запакує свої пили та сокири, розлючені духи вогню заспокояться, а гарпії будуть витіснені землею.$B$BOnly потім $N, чи Кам’яний Кігтень справді заспокоїться.$B$BYou зробили добре $C; візьміть один із цих предметів як подяку за нове життя, яке ви створили тут сьогодні.",
},

[6382] = {
    en = "The Ashenvale Hunt",
    T = "Полювання в Ясенедолі",
    D = "Твоя сила вражає мене, $c. Твоя готовність прийняти полювання дає мені впевненість, що ти можеш перейти до більшої здобичі... і більших викликів.$B$BЛіси Ясенедолу являють собою величезну дику природу, яку Орда прагне підкорити своєю волею, як політично, так і духовно. Якщо ти прагнеш довести себе в незвіданій землі, шукай настанови Сенані Тандергарт у Посту Сплінтертрі. Форпост розташований на північ від шляху, що веде зі Степів.",
    O = "Поговори з Сенані Тандергарт у Посту Сплінтертрі, Ясенедол.",
    P = "",
    C = "Ласкаво просимо на новий кордон, $N.  Ashenvale — це країна можливостей, де такий молодий $C, як ти, може знайти безмежні шанси довести свою мужність.  Огляньте форпост тут і обов’язково вирушайте на Зорам-Странд, оскільки там також є ще один форпост Орди.$B$BYour присутність тут говорить мені, що ви прийшли дізнатися більше про полювання.  Слухайте уважно, і я з радістю поділюся з вами тим, що вам потрібно знати.",
},

[6383] = {
    en = "The Ashenvale Hunt",
    T = "Полювання в Ясенедолі",
    D = "",
    O = "",
    P = "",
    C = "Є три легендарні істоти, які складають полювання на Ясеневий ліс; ви можете шукати їх і випробувати себе проти їхньої хитрості та могутності.  У процесі ви, сподіваюся, дізнаєтесь щось про себе.  Ці істоти: ведмідь Урсангус, нічний кіт Шадумбра та гіпогриф Гострий Кігтець.$B$BThe істоти Полювання на Ясеневий ліс є могутніми, і вам може знадобитися допомога, щоб знищити їх.  Якщо ти переможеш їх, принеси мені доказ свого вчинку.",
},

[6384] = {
    en = "Ride to Orgrimmar",
    T = "Політ до Оргріммара",
    D = "За кілька монет я відправлю вітрокрила до Оргріммара. Там ти зможеш віднести м’ясо Зарґа до Ґришки. Її корчма в Долині Сили, недалеко від Небовежі, де приземлиться мій вітрокрил.$B$BПоговори зі мною ще раз, коли будеш готовий до подорожі.",
    O = "Купи політ на вітрокрилі до Оргріммара у господаря вітрокрилів Деврака, а потім віднеси м’ясо Зарґа до Ґришки в Оргріммарі.",
    P = "Щось добре пахне! У вас же немає сирого м'яса?",
    C = "О, чудово! Це гарні порізи! Це з Зарга, чи не так? Цей орк точно знає свій шлях до серця жінки...$B$BOh, я не можу дочекатися, щоб це приготувати. Але не дуже! М’ясо найкраще подавати рідким, чи не так?",
},

[6385] = {
    en = "Doras the Wind Rider Master",
    T = "Дорас, господар вітрокрилів",
    D = "Я написав листа подяки Зарґу. Чи доставиш ти його для мене? Якщо ти вже був у Перехресті і говорив із їхнім господарем вітрокрилів, то можеш полетіти назад до нього на вітрокрилі.$B$BВіднеси мого листа до Дораса, господаря вітрокрилів Оргріммара, і поговори з ним про транспорт до Перехрестя.",
    O = "Віднеси лист Ґришки до Дораса в Оргріммарі.",
    P = "Вам потрібен один із моїх вітряних вершників?",
    C = "Ви повинні доставити це до Перехрестя в Степлі? Так, я можу доставити вас туди...",
},

[6386] = {
    en = "Return to the Crossroads.",
    T = "Повернення до Перехрестя",
    D = "Мої вітрокрили навчені літати до багатьох різних місць, якщо ти вже побував у тих місцях і говорив із тамтешнім господарем вітрокрилів.$B$BТи був у Перехресті і говорив із їхнім господарем вітрокрилів Девраком, тож тепер можеш полетіти прямо до нього звідси. У Перехресті ти зможеш доставити лист Ґришки до Зарґа.$B$BПоговори зі мною, коли будеш готовий.",
    O = "Купи політ на вітрокрилі до Перехрестя у господаря вітрокрилів Дораса, а потім віднеси лист Ґришки до Зарґа в Перехресті.",
    P = "Ти повернувся з Оргріммару? Чи сподобалось Гришку м'ясо, яке я їй прислав?",
    C = "ха! Мабуть, їй сподобалось! Ніщо так не червоніє на щоках жінки, як великий соковитий стейк!$B$BThank ти, $N. Ви зробили мені велику послугу. Ось трохи грошей на ваші клопоти, і не дивуйтеся, якщо я запросю вас на своє весілля!",
},

[6387] = {
    en = "Honor Students",
    T = "Почесні студенти",
    D = "Я бачу багато молодих дворфів біля моїх дверей, які прагнуть навчитися гірничої справи. А якщо є щось, що гірнику потрібно більше за все, — це кирка!$B$BУ мене є список студентів-гірників, які отримали високі бали на заняттях і заслужили почесну кирку. Віднеси мій список до Ґолніра Боулдертоу в Залізогарті. Він підготує кирки.$B$BНайшвидший шлях до Залізогарту — на грифоні, тож віднеси список до нашого господаря грифонів, Торґрума Боррелсона, і поговори з ним про транспорт до Залізогарту.",
    O = "Віднеси список Брока до Торґрума Боррелсона в Тельсамарі.",
    P = "Ти так скоро наситився Телсамаром? Ви готові виїхати в інше місто?",
    C = "Ви повинні доставити це в Стальгорн, еге ж? За невелику плату я можу посадити вас на спину одного зі своїх грифонів, і він довезе вас туди. Як це звучить?",
},

[6388] = {
    en = "Gryth Thurden",
    T = "Ґріт Турден",
    D = "Ось почесні кирки для студентів Брока. Якщо ти вже був у Тельсамарі, тобі варто полетіти назад туди на грифоні!$B$BВіднеси кирки до нашого господаря грифонів, Ґріта Турдена, і поговори з ним про політ назад до Тельсамара.",
    O = "Віднеси почесні кирки до Ґріта Турдена в Залізогарті.",
    P = "Ви виглядаєте так, ніби вам є куди піти. Потрібен один із моїх грифонів?",
    C = "Ви повинні доставити це Телсамару, еге ж? Це не буде проблемою. Якщо ти вже був у Телсамарі та говорив із Торґрумом Боррельсоном, то ти можеш повернути йому одного з моїх грифонів.",
},

[6389] = {
    en = "A Plague Upon Thee",
    T = "Чума на вас",
    D = "Ти оглядаєш лісопильню в пошуках чогось, чим можна відкрити бочку. Ти знаходиш лом, який, здається, підійде.$B$BТи міцно впираєшся ногами і молишся, щоб встигнути вибратися з лісопильні, перш ніж терміти доберуться до тебе.",
    O = "Випусти Зачумлених термітів у лісопильні Північногір’я, а потім повернися з бочкою Зачумлених термітів до Натаніеля Думаха в таборі Промозклому в Західних Зачумлених землях.",
    P = "Ти зробив це, $N? Ви випустили термітів? Світло допоможе нам, якщо Багряний хрестовий похід зможе втримати і млин, і Глен. Вони не повинні мати ні того, ні іншого. Вони просто заробляють на жертвах останньої війни і їх треба знищувати як скажених тварин!",
    C = "Ха-ха! Дякую, $N! Ви зробили це! Тепер дух мого батька може відпочити, а я можу жити в мирі.$B$BThank ти знову. Якщо я можу щось для вас зробити, будь ласка, просто запитайте.",
},

[6390] = {
    en = "A Plague Upon Thee",
    T = "Чума на вас",
    D = "Ти оглядаєш лісопильню в пошуках чогось, чим можна відкрити бочку. Ти знаходиш лом, який, здається, підійде.$B$BТи міцно впираєшся ногами і молишся, щоб встигнути вибратися з лісопильні, перш ніж терміти доберуться до тебе.",
    O = "Випусти Зачумлених термітів у лісопильні Північногір’я, а потім повернися з бочкою Зачумлених термітів до Міккі Левіна на Бастіоні в Тірісфальських Гаях.",
    P = "Ти зробив це, $N? Ви випустили термітів на лісокомбінаті?$B$BIt було настільки погано, що моя сім’я втратила роботу та життя, але потім побачити місце, де пройшло моє дитинство, захоплене тими огидними так званими святими людьми... пфах!!",
    C = "Дякую, $N. Ось, візьміть цю монету. Мені шкода, що це не більше, але спробуйте отримати трохи радості, допомагаючи знищити зусилля Багряного хрестового походу!",
},

[6391] = {
    en = "Ride to Ironforge",
    T = "Політ до Залізогарту",
    D = "За кілька монет один із моїх грифонів відвезе тебе до Залізогарту. Звідти достав список Брока до Ґолніра Боулдертоу. Ти знайдеш його в Гільдії Глибокогірних Гірників. Це у районі Великої Кузні Залізогарту, куди приземлиться мій грифон!$B$BПоговори зі мною ще раз, коли будеш готовий до подорожі.",
    O = "Купи політ на грифоні до Залізогарту у господаря грифонів Торґрума Боррелсона, а потім віднеси список Брока до Ґолніра Боулдертоу в Залізогарті.",
    P = "Що я можу для вас зробити, сер?",
    C = "Ах, останній список найкращих учнів Брока. У мене є готова партія почесних кирок. Мені просто потрібно врізати імена студентів...",
},

[6392] = {
    en = "Return to Brock",
    T = "Повернення до Брока",
    D = "За невелику плату ти можеш купити політ на грифоні до Тельсамара... якщо ти вже там був. Грифони літають лише до тих місць, де ти вже побував, тож не забудь поговорити з кожним господарем грифонів, якого побачиш, щоб потім могти літати до нього.$B$BТи вже був у Торґрума, господаря грифонів Тельсамара, тож тепер можеш повернутися до нього. А в Тельсамарі ти зможеш доставити кирки до Брока Стоунсікера.$B$BПоговори зі мною, коли будеш готовий.",
    O = "Купи політ на грифоні до Тельсамара у господаря грифонів Ґріта Турдена, а потім віднеси почесні кирки до Брока Стоунсікера в Тельсамарі.",
    P = "Ах, $N. Ви повернулися з Айронгорна?",
    C = "Ви принесли кирки. Чудово! Я віддам це своїм студентам-гірникам. Я впевнений, що вони прагнуть використати їх на рудних родовищах озера Лох-Модан.$B$BThank вам за допомогу, $N. Я у вашому боргу, але я сподіваюся, що ці гроші принаймні покриють ваші витрати на дорогу.",
},

[6393] = {
    en = "Elemental War",
    T = "Війна елементалів",
    D = "Трибунал Припливів відправив мене вести війну з вогняними елементалями тут, у горах Кам’яних Кігтів. Нептулон Мисливець за Припливами, Повелитель усіх водяних елементалів, особисто зацікавлений у тому, щоб наші вогняні родичі були знищені.$B$B$N, ти можеш допомогти мені здобути прихильність Трибуналу, знищуючи вогняних елементалів в Обвугленій Долині. Після знищення вогняні елементалі залишають запальники. Поверни їх мені, і ти будеш нагороджений.",
    O = "Принеси 10 запальників до Цунаман у Притулку Сонячної Скелі.",
    P = "Трибунал Припливів починає терпіти. Вони прагнуть покласти край цій війні, яка вирувала в усіх вимірах століттями. Мої брати з нетерпінням чекають новин про славетну перемогу над ненависними елементалями вогню. Чи є у вас потрібні мені заповіти?",
    C = "Водяні духи всередині мене киплять від хвилювання. $N, ти дав мені славетну перемогу, щоб звітувати перед Трибуналом Припливів.$B$BFor за твої зусилля, я винагороджую тебе вибором мого цінного майна.",
},

[6394] = {
    en = "Thazz'ril's Pick",
    T = "Кирка Тазз’ріла",
    D = "$N, ти надійний $r. Чи можу я розраховувати на тебе ще в одному завданні?$B$BДеякий час тому я досліджував печеру на півночі в пошуках мінералів і залишив там свою улюблену кирку. Коли я повернувся, щоб забрати її, печера була повна лютих звірів! Чи підеш ти до печери, Ковену Палаючого Клинка, і забереш мою кирку?$B$BЯ залишив її в залі з водоспадами. Моя кирка зачарована, тож ти побачиш її в темряві, тож не хвилюйся про те, як її знайти... лише про те, що її охороняє!",
    O = "Принеси кирку Тазз’ріла до бригадира Тазз’ріла.",
    P = "Ви входили в ковен Burning Blade, $N? Ви знайшли мій вибір?",
    C = "Чудово, ви зрозуміли! Дуже дякую, $N. Це мій улюблений вибір! Тепер, якщо мої люди коли-небудь закінчать рубати ці дерева, можливо, ми знайдемо гарну печеру для шахти!",
},

[6395] = {
    en = "Marla's Last Wish",
    T = "Останнє бажання Марли",
    D = "Моя подруга Марла Фіппс жила зі своїм чоловіком Самуелем до чуми, але коли прийшла чума, Самуель піддався і приєднався до лав Плетиви.$B$BМарла уникла нежиті, але загинула від рук свого тепер бездушного чоловіка. Така сильна була її любов, що її останнім бажанням було бути похованою разом із коханим Самуелем.$B$BСамуель Фіппс блукає в зруйнованому таборі на північний схід від Смертозвону. Переможи його і виконай бажання Марли: поховай його на її могилі, у першому ряду нашого кладовища.",
    O = "Принеси рештки Самуеля Фіппса до могили Марли, а потім повернися до послушниці Ельрет.",
    P = "Ми повинні поважати наших мертвих, $N. Це один із способів, чим ми відрізняємось від Бича...",
    C = "Ти сьогодні зробив добру справу, $N. Незважаючи на те, що наша боротьба з Бичем триває, будемо сподіватися, що Марла та Семюель знайдуть мир разом у місці свого останнього спочинку.",
},

[6401] = {
    en = "Kaya's Alive",
    T = "Кая жива",
    D = "Скажи Таммрі Віндфілд, тітці Каї, яка в Притулку Сонячної Скелі, радісну новину! Кая жива! Ми думали, що вона загинула після жорстокого нападу на наше село. Іди шляхом на захід, щоб дістатися до Притулку Сонячної Скелі.",
    O = "Повідом Таммрі Віндфілд у Притулку Сонячної Скелі радісну новину.",
    P = "",
    C = "Господи, моя племінниця Кая жива! Це справді гарна новина. Дякую, $N.",
},

[6402] = {
    en = "Stormwind Rendezvous",
    T = "Зустріч у Штормовії",
    D = "Тобі потрібно зустрітися з Віндзором біля воріт Штормовію.$B$BТе, що Віндзор збирається розкрити, потрясе самі основи королівства!$B$BНе намагайся вирушити туди сам, $N. Ти мусиш зібрати армію! Збери своїх товаришів. До зброї!",
    O = "Вирушай до міста Штормовію і підійди до міських воріт. Маршал Віндзор зустріне тебе одразу за міськими кордонами.",
    P = "",
    C = "Перш ніж почати, я прошу вас спочатку зібрати армію. Зрештою, ми стикаємося з драконом!",
},

[6403] = {
    en = "The Great Masquerade",
    T = "Великий маскарад",
    D = "Це була справжня пригода, друже. Я в великому боргу перед тобою. Можливо, коли все закінчиться...$B$BЯк ти, без сумніву, вже здогадався, леді Престор — це Оніксия: виводок Смертокрила, сестра-близнючка тирана Шпиля, Нефаріана.$B$BНадто довго вона тримала наше королівство під своїм чарівним поглядом. Навіть Верховний Лорд — лише маріонетка в її руках. Сьогодні все закінчиться... Чари будуть зламані.$B$BНе хвилюйся, адже разом ми переможемо!$B$BТи готовий?",
    O = "Слідуй за Реґінальдом Віндзором через Штормовій. Захисти його від небезпеки!",
    P = "Я... я... я був безсилий.",
    C = "<Болвар тримає розбитий медальйон.>$B$BThe магію, що зберігається всередині, потрібно відновити. Око дракона має бути налаштовано. Жертва PH2__$BWindsor звільнила наше Королівство, але загроза Оніксії та її родичів постійно нависає.$B$BThis медальйон — це те, що тримало в полоні мій розум і тіло. Це також те, що дало мені доступ до розуму Оніксії — до її таємниць. Хоча бачення зараз заплутані, деякі речі я пам’ятаю.",
},

[6421] = {
    en = "Boulderslide Ravine",
    T = "Ущелина Каменепаду",
    D = "Щось негаразд тут, у Кам’яних Кігтях. Чи відчуваєш ти напругу в повітрі, $N?$B$BНа південь звідси є глибока печера в Ущелині Каменепаду. Кобольди там несамовито видобувають рідкісний кристал, що зветься резоніт. Мені потрібні зразки цієї руди, щоб зрозуміти, що відбувається в тій печері. А ще мені потрібно, щоб ти дослідив глибину тієї печери.$B$BІди, юний $c, мені вкрай важливо знати, яке зло ховається під цими горами.",
    O = "Досліди глибоку печеру в Ущелині Каменепаду і принеси 10 резонітових кристалів для Мор’роґала у Притулку Сонячної Скелі для дослідження.",
    P = "Які новини ви дізналися з Boulderslide Ravine? Я пригадую легенду про резоніт... Я просто не можу поставити своє копито на нього. Можливо, знання того, що лежить на дні печери, прояснить їхні підступні наміри.",
    C = "Ах... Так! Ось і все; Кристали резоніту мають відбиток земної магії. Кобольди, мабуть, копали глибоко, знаходячи землян.$B$BLegend стверджує, що земляни — це істоти, створені титанами. Вони були використані для створення землі, по якій ходять наші ноги. Безумовно, це загроза, яку не можна ігнорувати.$B$B<Мор'рогал хитає головою.>$B$BМожливо Я можу зачарувати ці зразки руди, щоб використати їх проти цієї змови Кобольда.",
},

[6441] = {
    en = "Satyr Horns",
    T = "Роги сатирів",
    D = "Гей! Я мандрував через Ясенедол, прямуючи до Ратчета, і вирішив зупинитися тут, у Сплінтертрі. Я завжди шукаю можливості, і, здається, роги сатирів нині дуже потрібні в Ратчеті.$B$BПоговоривши тут, я дізнався, що сатири в Нічному Бігу, Сатирнаарі та Ксавіані мають саме ті роги, які мені потрібні. Я не рівня тим сатирам... але ти виглядаєш так, ніби можеш із ними впоратися!$B$BСкажу так: ти збереш роги для мене, і я зроблю так, щоб твій час вартував того.",
    O = "Збери 16 рогів сатирів для Пікселя в Посту Сплінтертрі.",
    P = "Сподіваюся, ти швидко отримаєш ці роги, $N. Я незабаром повертаюся до Ratchet!",
    C = "Вони ідеальні, $N! Дякую, що допомогли мені!$B$BOh, це ваш час...",
},

[6442] = {
    en = "Naga at the Zoram Strand",
    T = "Наги на березі Зораму",
    D = "Тут, уздовж узбережжя, ховається зло, $r.$B$BЦе місце спочинку приреченого міста Зорам, давно зруйнованого і затопленого морями. Загублене і майже забуте.$B$BТепер наги повернулися, і ми не знаємо, з якою метою. Але мета не має значення; ми мусимо захистити землю, яку так важко здобули як свою.$B$BПовернися до мене з 20 їхніми головами! Скинь наг назад у глибини!",
    O = "Принеси 20 голів Гнівохвостів до Марукай уздовж берега Зораму.",
    P = "Чисельність нага збільшується, $n. Будь ласка, виконайте це завдання за мене.",
    C = "Нам би знадобилося більше твого роду тут, $N. Дякуємо за вашу допомогу.",
},

[6461] = {
    en = "Blood Feeders",
    T = "Криваві пожирачі",
    D = "Ми, тролі, тут, у Малака’Джині, процвітали завдяки цій землі; гори Кам’яних Кігтів дають чудові можливості для полювання, щоб ми могли жити.$B$BОстаннім часом ми привабили не тих гостей на вечерю... павуки в цих горах ночами нападають на наші табори, намагаючись украсти нашу здобич.$B$BЯкби ти допоміг нам позбутися цих огидних істот, ми в Малака’Джині були б твоїми боржниками. Павуки всюди в Кам’яних Кігтях — просто вирушай на північ звідси, і ти побачиш, про що я.",
    O = "Ксен’зілла в Малака’Джині потребує, щоб ти убив 10 повзунів Глибокого Моху і 7 отрутоплюйок Глибокого Моху.",
    P = "Гей, чувак, ти вбив волохатих кровогодителів? Я не боюся, що нікого тут, у Stonetalon, але я не гуляю тут уночі... якщо ти розумієш, що я маю на увазі, моє!$B$BAs поки я не буду там тарілки, тоді все буде добре.$B$BGood удачі тобі, $C!",
    C = "Мило, мон! Хороші новини, можливо, сьогодні ввечері у нас буде менше небажаних поривів вечері.$B$BAs Раніше я казав, ми у вашому боргу... можливо, ви б подбали про один із них за свій вчинок?",
},

[6462] = {
    en = "Troll Charm",
    T = "Трольський амулет",
    D = "Мої родичі подорожували сюди з багатьма священними трольськими амулетами, але фурболги Чортополохів напали і вбили їх, перш ніж вони дісталися до Зорам’ґару! Ці мерзенні фурболги!$B$BЯ сумую за братами і сестрами, які загинули, але ми зустрінемося знову в потойбіччі. Однак їхні трольські амулети мають велику цінність у цьому світі. Це обурливо, що фурболги їх забрали!$B$B$N, ти мусиш повернути амулети! Вони в скринях у Твердині Чортополохів, печері в кінці села Чортополохів, на північ від Астранаара.",
    O = "Принеси 8 трольських амулетів до Міцуви у форпості Зорам’ґар.",
    P = "Ти знайшов чари, $N?  Щомиті фурболги володіють цими священними предметами, моя кров кипить від люті!",
    C = "Ви їх знайшли! дякую! Дякую, $N! Ви не уявляєте, яку велику справу ви для мене зробили.$B$BA троль без своєї чарівності схожий на орка без бойових шрамів...$B$BWorthless.",
},

[6481] = {
    en = "Earthen Arise",
    T = "Землянин прокидається",
    D = "Ти виявив темну загрозу для цієї землі, $c. Резонітова скриня, яку ти знайшов у тій печері, містить сплячого Землянина на ім’я Ґоґґерок.$B$BЯ змінив суміш резонітових кристалів, які ти зібрав, своєю шаманською силою. Візьми зачарований резонітовий кристал і розбий резонітову скриню, в якій перебуває Землянин.$B$BКоли Ґоґґерок прокинеться, він буде ослабленим... Убий його, $N!",
    O = "Відкрий резонітову скриню зачарованим резонітовим кристалом, а потім убий Ґоґґерока. Повернися до Мор’роґала з новинами і зачарованим резонітовим кристалом.",
    P = "Я боюся, що якщо ми негайно не позбудемося цієї загрози, весь Каменетелон буде втрачено. Міцність землянина не зрівняється жодним способом. Прокинувшись, Ґоґгерок буде слабким від довгого сну. Це буде можливість, якою ви повинні скористатися... йдіть зараз $N!",
    C = "Гарні новини, $C! Я боюся можливостей того, що землянин означатиме для Калімдору.$B$BSlaying Ґоґґерок був завданням для когось іншого, ніж героя. Ви добре зробили; увесь Кам’яний Кігтець і Калімдор у боргу перед тобою, шляхетний $C.$B$BAccept це твоя найпочесніша нагорода.",
},

[6482] = {
    en = "Freedom to Ruul",
    T = "Свобода для Руула",
    D = "Хто ти такий?$B$B$N? Ти не фурболг. Вони прокляті! Вони думали, що я ведмідь, і схопили мене, а тепер морить голодом! Мої сили слабшають...$B$BДопоможи мені втекти, а потім поговори з моєю сестрою Ямою в Посту Сплінтертрі на схід звідси.$B$B$N! Я мушу втекти!",
    O = "Супроводжуй Руула, а потім поговори з Ямою Сноухуф у Посту Сплінтертрі.",
    P = "Ти бачив мого брата Руула? Він кілька днів тому пішов у ліс і не повернувся...",
    C = "Ти знайшов мого брата!  Він потрапив у полон до Чистопухових?  Це жахлива новина, бо хоча багато фурболгів є благородними створіннями, Будякошерсті зіпсовані.$B$BThank тобі за те, що ти врятував мого брата, $N.  Я не хочу думати про те, як вони поводилися з бідним Руулом.  Ймовірно, він довго спатиме після цього випробування...",
},

[6501] = {
    en = "The Dragon's Eye",
    T = "Око Дракона",
    D = "Уламок розбитого медальйона — це все, що я можу тобі запропонувати.$B$BТи мусиш знайти іншого, із драконячою кров’ю, хто захоче допомогти тобі викувати новий ключ. Щойно ти здобудеш цей ключ, тобі доведеться вирушити до Вирмоболота в Пилосмугових Болотах. Саме там ти знайдеш її лігво, $N.$B$BДе знайти інших драконячих родів, готових допомогти? На жаль, я не знаю... Кажуть, вони існують. Деякі, можливо, навіть живуть і працюють серед нас, замасковані під одну з гуманоїдних рас. Бажаю тобі удачі.",
    O = "Ти мусиш обшукати світ у пошуках істоти, здатної відновити силу Уламка Ока Дракона. Єдина інформація, яку ти маєш про таку істоту, — це те, що вона існує.",
    P = "Я відчуваю, як від тебе випромінюється аура зла, $R. Що ви можете тримати, що випромінює таку ауру?",
    C = "Я повинен був знати - шматок матері чорного дракона, Оніксії. Як огидно...",
},

[6502] = {
    en = "Drakefire Amulet",
    T = "Амулет Драковогню",
    D = "Це частина дракона; луска — зачарована і перетворена. Цілою вона могла б відкрити доступ до лігва звіра. Розбитою вона марна.$B$BЇї можна відремонтувати, але для цього потрібна кров чемпіона чорних драконів. Є один такий... Його звати Генерал Драккісат, правитель армій драконячих виводків Нефаріана. Може, ти чув про нього?$B$BПовернися з його кров’ю, $r, і я зачарую уламок у щось, що дасть тобі доступ до лігва Оніксії.",
    O = "Ти мусиш добути Кров Чемпіона Чорних Драконів у Генерала Драккісата. Драккісата можна знайти в його тронній залі за Залами Вознесіння в Чорноскельному Шпилі.",
    P = "Потік часу не зупиняється і не сповільнюється, $R. Хоча моє життя вічне, твоє ні. Не витрачайте час, який у вас є...",
    C = "Цей амулет надасть вам доступ, який ви шукаєте. Лігво Оніксії можна знайти в Пилових болотах. Поки ви тримаєте амулет, її охорона не зможе перешкодити вам увійти.$B$BThe Blue Flight бажає вам удачі, $N.",
},

[6503] = {
    en = "Ashenvale Outru$b$bers",
    T = "Вивідувачі Ясенедолу",
    D = "Ми отримали повідомлення, що вивідувачі Ясенедолу нещодавно покинули форпост Срібнокрилих і тепер крадуться біля наших територій у лісі. Ми не хочемо, щоб вони збирали розвіддані про нашу оборону!$B$BПрокрадися лісами на південь від нашого посту тут і на схід від форпосту Альянсу Срібнокрилих. Знайди і убий вивідувачів, а потім повернися до мене.",
    O = "Убий 9 вивідувачів Ясенедолу, а потім повернися до Курай’бін у Посту Сплінтертрі.",
    P = "Я чекаю звітів про твої вбивства, $N.",
    C = "Дуже добре, $N. Ваші мисливські навички вражають...$B$BThe втрата тих, хто втікає, допомагає засліпити Альянс, а коли їм бракує розуму, вони з меншою ймовірністю атакуватимуть.",
},

[6504] = {
    en = "The Lost Pages",
    T = "Загублені сторінки",
    D = "Я щойно забрав цей подрібнювач із Ратчета і прямував назад до лісозаготівельного табору Пісні Війни, де я мав бути на чергуванні. Мені дали посібник із керування подрібнювачем, але дорогою назад сильний порив вітру вирвав його з моїх рук. Сторінки розлетілися всюди, і в мене залишилася лише обкладинка.$B$BСторінки тепер можуть бути де завгодно, гадаю... але я не знаю, як керувати подрібнювачем без них! Чи знайдеш їх для мене?",
    O = "Знайди 12 загублених сторінок Посібника з експлуатації подрібнювача і склади їх у розділи 1, 2 і 3. Поверни сторінки до Ґурди Рейджскар біля Посту Сплінтертрі.",
    P = "Сподіваюся, ти скоро знайдеш ці сторінки, $N! Мені справді потрібно повернутися до роботи!",
    C = "Читання не моя сильна сторона... але тепер я зможу повернутися до роботи! Дякую, $N!",
},

[6521] = {
    en = "An Unholy Alliance",
    T = "Нечестивий союз",
    D = "Малсін стверджує, що він перебуває біля Брашпильних Нетрів. Цього посла потрібно знищити — його місія має провалитися в очах Короля Лича.$B$BЙого присутність там пояснює багато з того, що ми виявили в цій місцевості — деякі щетиноспини стали страхітливо могутніми, водночас проявляючи ознаки Чуми по-своєму. Це, безумовно, свідчить про якусь угоду, яку вони уклали.$B$BЗнайди Малсіна і убий його, $N. Повернися до мене, коли справу буде зроблено.",
    O = "Принеси голову посла Малсіна до Варіматраса в Мертвому Місті.",
    P = "Ви знайшли посла, $N? Він мертвий?$B$BWe не може дозволити Бичу закріпитися на Калімдорі. Вони є достатньою загрозою для наших власних кордонів, щоб мати справу з ними на двох фронтах.$B$BThe Єдиним оптимістичним свідченням тих подій, про які ви мені розповідали, є те, що старина здавалася незіпсованою. Вона повинна глибоко в собі знати, що Бич може принести велику силу, але Степлі не будуть їй належати, якщо вона погодиться на їхню угоду.",
    C = "добре. Молодець, $C.$B$BNow, що Малсін мертвий, ми принаймні можемо знати, що просування Бичів буде зупинено. Темна Леді дякує вам за ваші зусилля та бажає винагородити вас подарунком.$B$BAlthough ми не знаємо, наскільки впливають Бичі на Даунс, я впевнений, що незабаром ми розкриємо їхні плани.",
},

[6522] = {
    en = "An Unholy Alliance",
    T = "Нечестивий союз",
    D = "Моя пані,$B$BВи прекрасно знаєте, що ми пропонуємо. Можливість захопити Степи та землі за ними — це величезна нагода. Ми лише хочемо вашої допомоги взамін. Під допомогою ми маємо на увазі лише свободу дій у цій місцевості.$B$BБудь ласка, дозвольте нам обговорити це детальніше. Ми володіємо великою силою і готові ділитися з тими, хто достатньо мудрий, щоб приєднатися до нас. Я тимчасово залишуся біля входу до Гострокидних Курганів.$B$BЗ найкращими побажаннями,$BПосол Мальцин",
    O = "Віднеси Маленький Сувій до Варімата в Підмісто.",
    P = "Про яку справу ви хочете поговорити, $N? Ви повинні відчувати, що це важливо, якщо ви продовжуєте дошкуляти мені.",
    C = "Я впізнаю знак розрізнення на цьому сувої, $N. Ви знайшли це на тій старові, яка панує над Резорфеном Краулом? Цікаво.$B$BThe Здається, Scourge не задовольняються одним континентом. Цей посол Малсін — той, хто написав записку — є одним із заражених слуг Бича, людським дипломатом у королівстві Лордерон до того, як усе... змінилося.$B$BIf Бич намагається закріпитися в Калімдорі, тоді ми повинні діяти.",
},

[6523] = {
    en = "Protect Kaya",
    T = "Захисти Каю",
    D = "Дякую, що врятував мене! Ми мусимо швидко тікати, поки вони не виявили, що я на свободі. Будь ласка, супроводь мене до табору Апарахе. Звідти я знаю дорогу.$B$BМій батько, Макаба Пласкокопито, буде в розпачі, якщо не дізнається, що я в безпеці.",
    O = "Супроводь Каю Пласкокопито до табору Апарахе, а потім повернися до Макаби Пласкокопита біля південно-східного краю Кам’яного Кігтя.",
    P = "Кая супроводжується до табору Апарадже",
    C = "Кая жива! $N, я маю подякувати тобі за її порятунок.",
},

[6541] = {
    en = "Report to Kadrak",
    T = "Доповісти Кадраку",
    D = "Ти коли-небудь був у Ясенедолі, на півночі? Орда нещодавно заснувала там форпост на узбережжі Зорам, і нам завжди потрібні нові рекрути, щоб захищати наші нові рубежі.$B$BЯкщо вважаєш, що впораєшся, звернися до Кадрака в північних Степах, біля сторожової вежі. Він очолює кампанію в Ясенедолі і може дати тобі подальші накази.",
    O = "Доповіси Кадраку біля сторожової вежі в північних Степах.",
    P = "",
    C = "Ясеневий ліс — розділена земля, але наші останні зусилля були дуже успішними. У нас є не лише форпост на узбережжі Зорам, але й інший на північ звідси під назвою Сплінтертре.",
},

