},

[6581] = {
    en = "Warsong Saw Blades",
    T = "Пилкові Леза Пісні Війни",
    D = "",
    O = "",
    P = "Прямо від Ratchet, пильні леза Warsong! Так, я маю їх прямо тут.$B$B..Але який вид оплати у вас для мене? Ви не можете просто взяти їх, знаєте! Мій час коштує недешево!$B$BWhat Мені справді потрібна хороша зброя, щоб брати її з собою в мої подорожі. Дівчина повинна захищати себе, розумієш? Є рушниця, яка мені дуже подобається, і я впевнений, що у інженера не виникне проблем із виготовленням.$B$BSo, якщо ти привезеш мені смертоносний куш, я віддам тобі вантаж пилки. Ми домовилися?",
    C = "Це ідеально - саме те! Ну ось відправка.",
},

[6582] = {
    en = "The Test of Skulls, Scryer",
    T = "Випробування черепів, Провидець",
