[6847] = {
    en = "Master Ryson's All Seeing Eye",
    T = "Всевидяче Око Майстра Райсона",
    D = "Ваша війна в серці Альтерака нічого не означає для Синдикату, $c. Ми робитимемо те, що завжди робили: чекатимемо, поки з попелу і руїн цього божевілля не з’явиться явний переможець, а тоді вдаримо.$B$BОднак, це не причина, чому ми тут зараз. Всевидяче Око було втрачено — його забрали тролі Зимового Топора цього регіону.$B$BПоверни Око, і наші послуги будуть твоїми — на той час, що залишиться твоїй стороні.$B$BПовертайся до мене, коли здобудеш око, щоб я міг тебе оглянути.$B$B<Майстер Райсон посміхається.>",
    O = "Поверни Всевидяче Око Майстра Райсона з печер Зимового Топора і поверни його Майстру Райсону.$B$BПопереджаю, кажуть, що Всевидяче Око Майстра Райсона несе з собою страшне прокляття!",
    P = "",
    C = "Всевидюче око майстра Райсона відновлено",
},

[6848] = {
    en = "Master Ryson's All Seeing Eye",
    T = "Всевидяче Око Майстра Райсона",
    D = "Ваша війна в серці Альтерака нічого не означає для Синдикату, $c. Ми робитимемо те, що завжди робили: чекатимемо, поки з попелу і руїн цього божевілля не з’явиться явний переможець, а тоді вдаримо.$B$BОднак, це не причина, чому ми тут зараз. Всевидяче Око було втрачено — його забрали тролі Зимового Топора цього регіону.$B$BПоверни Око, і наші послуги будуть твоїми — на той час, що залишиться твоїй стороні.$B$BПовертайся до мене, коли здобудеш око, щоб я міг тебе оглянути.$B$B<Майстер Райсон посміхається.>",
