[7181] = {
    en = "The Legend of Korrak",
    T = "Легенда про Коррака",
    D = "Вторгнення Бурешпильних — не єдина загроза в цій місцевості, солдате. Війна в долині ведеться на два фронти. Канібали Зимосоки також прагнуть влади.$B$BЇх очолює Коррак Кровожер — жорстокий і хитрий звір.$B$BУдар по Корраку може стати нищівним для клану Зимосоків. Убий цього звіра і отримай нагороду!",
    O = "Згідно з легендою, лідер могутніх тролів Зимосоків з’являється за власним бажанням, щоб сіяти хаос серед мешканців долини Альтераку.$B$BЯкщо Коррак покаже себе, знищ його і повернися до Воєначальника Лаґґронда.",
    P = "",
    C = "",
},

[7201] = {
    en = "The Last Element",
    T = "Остання стихія",
    D = "Є робота для тих, хто наважується спуститися в глибини, $N.$B$BТемні Залізняки опанували створення надзвичайно потужних големів.$B$BПочаткові звіти наших шпигунів свідчать, що дворфи використовують унікальне джерело енергії, щоб надати своїм творінням неперевершену силу вбивства.$B$BУяви, що ми могли б зробити з нашими мерзотниками, якби отримали цю есенцію стихій! Переверни це місто догори дном, якщо треба, але не повертайся, поки не знайдеш есенцію! Винагорода варта ризику.",
    O = "Вирушай до Глибин Чорноскелі і добудь 10 Есенцій Стихій. Твій перший здогад — шукати серед големів та їхніх творців. Ти також пам’ятаєш, як Вівіан Лаґрейв бурмотіла щось про елементалів.",
    P = "Покажіть їх мені!",
    C = "Чудово! Я негайно надішлю їх кур’єром до Андерсіті!$B$BAs для вас — ось оплата, як і обіцяв. Тримайте здачу, мерзенна скотина!",
},

[7202] = {
    en = "Korrak the Bloodrager",
    T = "Коррак Кровожер",
    D = "Місцеві тролі Зимосоки — безжальні дикуни, які нічого так не хочуть, як додати наші кістки до їхнього мерзенного рагу.$B$BМи мусимо показати їм нашу міць!$B$BМи знайшли фоліанти в їхніх печерах, які описують їхню ієрархію лідерства. Артефакти вказують, що їхній лідер, Коррак Кровожер, зазвичай ховається, поки не з’явиться причина показати себе.$B$BСмерть Корраку означатиме смерть клану Зимосоків! Убий його і повернися.",
    O = "Згідно з легендою, лідер могутніх тролів Зимосоків з’являється за власним бажанням, щоб сіяти хаос серед мешканців долини Альтераку.$B$BЯкщо Коррак покаже себе, знищ його і повернися до Лейтенанта Гаґґердіна в горах Альтераку.",
    P = "",
    C = "",
},

[7221] = {
    en = "Speak with Prospector Stonehewer",
    T = "Поговори з Проспектором Стоунг’юером",
    D = "А, $N, з’явився на службу, чи не так? Чудово, Бурешпильним потрібен кожен, кого ми можемо зібрати!$B$BПоговори з Проспектором Стоунг’юером у Дун Балдарі. Вона набирає людей для важливої місії на ворожу територію. Ти знайдеш Стоунг’юера внизу гарнізону Дун Балдара.$B$BІ будь уважним, проходячи через Дун Балдар. Там багато роботи для працьовитого $c, який не боїться забруднити руки.",
    O = "Поговори з Проспектором Стоунг’юером у гарнізоні Дун Балдара.",
    P = "",
    C = "",
},

[7222] = {
    en = "Speak with Voggah Deathgrip",
    T = "Поговори з Воґґою Смертозахватом",
    D = "$c? Чудово! Ми раді бачити тебе в Альтераку, $N. Дворфи-злодії та їхні союзники вторглися в нашу долину, і ми вітаємо всіх в Орді, хто приєднається до нас у праведній різанині!$B$BПоговори з Воґґою Смертозахватом. Він шукає агентів для важливої місії в твердиню Альянсу в долині Альтераку!$B$BТи знайдеш Воґґу в Твердині Морозних Вовків.",
    O = "Поговори з Воґґою в Твердині Морозних Вовків.",
    P = "",
    C = "",
},

[7223] = {
    en = "Armor Scraps",
    T = "Уламки обладунків",
    D = "Битви постійно вирують у долині Альтераку, і припаси, які ми отримуємо з Залізогарту, недостатні, щоб екіпірувати наших досвідчених воїнів.$B$BЯкщо ти знайдеш уламки обладунків на полі бою, допоможи війні і принеси ці уламки мені!",
    O = "Принеси 20 уламків обладунків до Мурґота Глибоковаря в Дун Балдарі.",
    P = "Ти приніс уламки броні, $N?",
    C = "Це кілька хороших творів, $N. Я можу використовувати їх, щоб створити нове спорядження для наших військ.$B$BIf мій рівень постачання стане достатньо високим, тоді, можливо, наші досвідчені бойові підрозділи вийдуть на поле!",
},

[7224] = {
    en = "Enemy Booty",
    T = "Ворожа здобич",
    D = "Коли ти б’єшся з ворогом, збирай уламки їхніх обладунків і принось їх мені. Я використаю ці уламки, щоб зробити обладунки для наших власних воїнів!",
    O = "Принеси 20 уламків обладунків до Коваля Реґзара в селі Морозних Вовків.",
    P = "Як проходить полювання, $N. У вас є для мене обрізки броні?",
    C = "Це буде добре. Я їх розплавлю й залатаю, і ти ніколи не дізнаєшся, що вони прийшли від тих боягузів Грозової Верхи!$B$BThanks, $N. І дозволь мені відшліфувати твій обладунок...",
},

[7241] = {
    en = "In Defense of Frostwolf",
    T = "На захист Морозних Вовків",
    D = "Барабани війни звучать у далекій землі, $c. Улюблений клан твого Вождя зазнає нападу від підступної Варти Бурешпильних із Залізогарту.$B$BСудячи з твого вигляду, я бачу, що ти справді загартований у боях і готовий узятися за справу Морозних Вовків.$B$BСаме ти тепер мусиш зробити наступний крок у своїй еволюції.$B$BНа північ від Тарренського Млина, в Альтераку, ти знайдеш вхід до долини Альтераку. Там ти знайдеш Воєначальника Лаґґронда. Поспіши, $c, адже битва вже почалася!",
    O = "Вирушай до долини Альтераку, розташованої в горах Альтераку. Знайди і поговори з Воєначальником Лаґґрондом — він стоїть біля входу в тунель — щоб почати свою кар’єру солдата Морозних Вовків. Долину Альтераку ти знайдеш на північ від Тарренського Млина біля підніжжя гір Альтераку.",
    P = "",
    C = "Щоб стати солдатом Крізного Вовка, потрібно спочатку пройти випробування...",
},

[7261] = {
    en = "The Sovereign Imperative",
    T = "Суверенний наказ",
    D = "Ми ведемо жорстоку битву в долинах Альтераку. Канібалістичні тролі Зимосоки атакують нас з одного боку, а дикі Морозні Вовки — з іншого. Обидва мусять бути знищені в ім’я Короля Магні Бронзоборода! Захоплення, винищення і освоєння цієї землі — це суверенний і територіальний наказ королівства Залізогарту.$B$BНа жаль, солдати не ростуть на деревах! Доповідай Лейтенанту Гаґґердіну біля долини Альтераку, щоб почати свою службу і честь серед Бурешпильних.",
    O = "Вирушай до долини Альтераку в передгір’ях Гіллсбраду. Знайди і поговори з Лейтенантом Гаґґердіном біля входу в тунель.$B$BЗа славу Бронзоборода!",
    P = "",
    C = "Давайте до роботи!",
},

[7281] = {
    en = "Brotherly Love",
    T = "Братня любов",
    D = "Трагедія... Мій брат протистоїть мені на полі бою: Командир Бурешпильних.$B$BЗ-поміж чотирьох командирів Бурешпильних він, безсумнівно, найнебезпечніший. Можливо, якщо його вбити, Королева Банші зможе повернути його, як повернула мене — показати йому, як він помилявся...$B$BГлибоко на ворожій території ти знайдеш мого брата. Убий його і повернися до мене. Я вірю, що ти здатний виконати цю місію, солдате.$B$BІ, солдате, не йди сам.",
    O = "Вирушай на територію Бурешпильних і убий Командира Карла Філіпса. Повернися до Командира Луї Філіпса, коли завдання буде виконано.",
    P = "Як йому, мабуть, боляче залишатися одним із живих, поки його улюблений брат досяг досконалості.",
    C = "Ваша героїчність не залишиться непоміченою, $N.$B$BI не втрачай часу, якщо хочеш врятуватися. З Сільваною треба зв'язатися!",
},

[7282] = {
    en = "Brotherly Love",
    T = "Братня любов",
    D = "Його треба звільнити від страждань, солдате! Він не знає, що робить. Він став бездумним слугою жахливої Королеви Банші.$B$BВирушай через Поле Розбрату вглиб території Морозних Вовків. Знайди мого брата і знищ його. Його муки мусять закінчитися.",
    O = "Вирушай на територію Морозних Вовків і убий Командира Луї Філіпса. Повернися до Командира Карла Філіпса, коли завдання буде виконано.",
    P = "З важким серцем віддаю такий наказ, солдате.",
    C = "Ти пам’ятав спалити труп, чи не так?",
},

[7301] = {
    en = "Fallen Sky Lords",
    T = "Полеглі небесні лорди",
    D = "Ми тримаємо їх у полоні, $r. Я говорю про їхніх Командирів Крила. Це була люта битва в небесах, але вони нарешті впали! На жаль, наших найкращих пілотів збили під час контратаки на Твердиню Морозних Вовків. Ти мусиш дізнатися, що з ними сталося.$B$BПошукай у Західній Точці Вежі та Твердині Морозних Вовків. Це їхні останні відомі місця. Ретельно обшукай ці території.",
    O = "Вирушай на територію Морозних Вовків і шукай Командира Крила Слайдора, Командира Крила Віпора і Командира Крила Ічмена. Повернися до Командира Даффі, якщо виконаєш свою місію.",
    P = "Хочу щось почути?",
    C = "Неймовірно! Ви їх звільнили, так? правильно??? Ну, принаймні, ми знаємо, де їх тримали.",
},

[7302] = {
    en = "Fallen Sky Lords",
    T = "Падіння Небесних Лордів",
    D = "Наша повітряна підтримка в розрусі, $N. Командири крил були збиті над ворожою територією. Ти мусиш з’ясувати, що з ними сталося, щоб ми могли спробувати їх врятувати!$B$BҐуз бачили востаннє, коли він пролітав над бункером Льодокрила. Військового вершника Джезтора помітили біля лісопильні Бурешпилів. Мулверік... цей безрозсудний дурень, як бачили, розбився біля північного бункера Дун’Балдара.$B$BЦе вся інформація, яку я маю. Рушай! Ретельно обшукай ці території.",
    O = "Дізнайся, що сталося з Командиром Крила Ґузом, Командиром Крила Джезтором і Командиром Крила Мулверіком. Повернися до Командира Мулфорта, коли виконаєш завдання.",
    P = "Статус полювання, солдат?",
    C = "молодець! Відновлена ​​вами інформація буде безцінною для нашої справи.",
},

[7321] = {
    en = "Soothing Turtle Bisque",
    T = "Заспокійливий Черепаший Біск",
    D = "Хто сказав, що нежить нічого не знає про кулінарію? Візьми, наприклад, мій секретний рецепт Черепашачого Біску. Я знав людей, які поверталися з мертвих, щоб насолодитися мискою цього супу! Ха-ха...$B$BДо речі, останнім часом я не міг його готувати. Раніше я сам ходив до озера Лордамер полювати на щелепохватів, цих мерзенних створінь, але тепер не можу відірватися від роботи тут.$B$BЯкщо принесеш мені черепашаче м’ясо від щелепохватів і заспокійливі спеції, я покажу тобі, як це робиться!",
    O = "Принеси 10 шматків Черепашачого М’яса і трохи Заспокійливих Спецій до Крістофа Джеффкоута в Таррен Мілл.",
    P = "Чи вдалося знайти інгредієнти?  Скажу тобі, личинок альянсу зараз надто багато в цій місцевості... На мій погляд, вони вже підійшли занадто близько...",
    C = "Мій заспокійливий черепаховий бісквіт зігріє вас у холодну ніч... якщо ви дбаєте про це.",
},

[7341] = {
    en = "A Fair Trade",
    T = "Справедлива угода",
    D = "",
    O = "",
    P = "Вітаю, $r. Я Коларк, мисливець за головами з Тандерблефа. Більшу частину світу я об’їздив і багато чого побачив.$B$BMy мандрівки Південними морями привели до відкриття цих дивовижних торієвих стріл. На жаль, у мене є нескінченний запас стріл, але я вичерпав свій запас снарядів. Бах, жоден поважаючий себе таурен ніколи не буде спійманий мертвим, використовуючи неміцний лук. Стріли марні!$B$BI запропонує обмін: рівномірний обмін торієвих оболонок на мої торієві стріли. Угода?",
    C = "Чудово! Я Таурен від слова, $r. Стрілки твої.",
},

[7342] = {
    en = "Arrows Are For Sissies",
    T = "Стріли для слабаків",
    D = "",
    O = "",
    P = "Ви можете повірити цьому сміття?! Остання партія боєприпасів з Харанос була зіпсована! Єдине, що у нас зараз є боєприпасами, — це хлипкі, ні до чого не придатні стріли! Що я буду робити з 500 000 торієвих стріл?$B$BI Ось що тобі скажу, хлопче. Якщо ти зможеш принести мені торієві снаряди, я продам тобі торієві стріли — прямо вгору! Угода?",
    C = "Зроблена справа, якщо я коли-небудь бачив її! Стрілки твої.",
},

[7361] = {
    en = "Favor Amongst the Darkspear",
    T = "Прихильність Темного Списа",
    D = "<Наджак гарчить.>$B$BЩе до існування нічних ельфів були тролі. Саме від тролів пішли нічні ельфи.$B$BЇхні бунтівні атаки проти мого народу не будуть толеруватися. Стагхелм прагне знищити нас — не залишити й сліду від тих, хто породив його та його рід. Цього не станеться!$B$BЗа кожного вбитого і обезглавленого нічного ельфа Наджак даруватиме тобі прихильність серед Темного Списа. Слух про твої подвиги пошириться Калімдором і Східними Королівствами. Іди і служи Темному Спису!",
    O = "Тобі доручено вбивати ворожих гравців-нічних ельфів у Долині Альтерака.$B$BУбий нічного ельфа і повернися до Наджака Хексена у Фортеці Морозного Вовка з Відрізаною Головою Нічного Ельфа.",
    P = "Вони прагнуть нас винищити? Саме вони будуть знищені.",
    C = "$N, це лише одне з тисяч. Тим не менш, робота виконана добре.",
},

[7362] = {
    en = "Ally of the Tauren",
    T = "Союзник Тауренів",
    D = "Старша Крона відправила мене в цю зону бойових дій, щоб дослідити інші раси. Зокрема, я маю зібрати зразки гномів. Маґата особливо цікавиться їхньою витривалістю. Так, гноми — хоч і жалюгідно слабкі та крихітні — виявляють велику стійкість як у бою, так і поза ним.$B$BНа щастя для тебе, я шукаю головорізів, які виконають волю Маґати. Повернися до мене з пучками гном’ячого волосся, і тебе визнають союзником тауренів.",
    O = "Тобі доручено вбивати ворожих гравців-гномів у Долині Альтерака.$B$BУбий гнома і повернися до Равака Гримтотема у Фортеці Морозного Вовка з Пучком Гном’ячого Волосся.",
    P = "Мені байдуже, звідки волосся, $R.",
    C = "Так, це точно гном. Молодець, $R, але попереду ще багато роботи.",
},

[7363] = {
    en = "The Human Condition",
    T = "Людська хвороба",
    D = "Люди настільки огидні.$B$B<Командир Філіпс кривиться.>$B$BХоч я і солдат Морозного Вовка, я залишаюся слугою Сільвани.$B$BПід час моєї служби я виконую додаткову роботу для Темних Аптекарів Підміста.$B$BМені доручено збирати людські кісткові уламки, які будуть використані для лікування людської хвороби.$B$BЯ уповноважений передати це завдання своїм підлеглим.$B$BЗнайди їх. Убий їх. Поверни їхні кісткові уламки мені.",
    O = "Тобі доручено вбивати ворожих гравців-людей у Долині Альтерака.$B$BУбий людину і повернися до Командира Луї Філіпса (який блукає між передовими позиціями та Фортецею Морозного Вовка) з Людським Кістковим Уламком.$B$BЛіки від людської хвороби вже близько!",
    P = "Так, це правда. Мій брат - людина. Ганебно... Пляма на моєму майже бездоганному досьє.",
    C = "Було б легше, якби вони просто прийняли свою хворобу і піддалися вашому цілющому дотику. Також, мабуть, було б менше весело. Продовжуйте! Ми їх вилікуємо, так чи інакше.",
},

[7364] = {
    en = "Gnomeregan Bounty",
    T = "Нагорода Гномеріґана",
    D = "Сам Верховний Механік відправив мене на це поле бою, щоб захистити моїх гном’ячих братів і сестер. Ми отримали повідомлення, що таурени вибирають і вбивають гномів. Найгірше, вони знімають пучки чудового гном’ячого волосся з тіл загиблих. Ці звірства повинні бути зупинені. Ми мусимо відповісти тим самим!$B$BЯ хочу, щоб їх позбавили копит, $c. Принеси мені їхні копита! Покажи себе як союзник гномів.",
    O = "Тобі доручено вбивати ворожих гравців-тауренів у Долині Альтерака.$B$BУбий таурена і повернися до Дірка Свіндла в Дун’Балдарі з Копитом Таурена.",
    P = "",
    C = "",
},

[7365] = {
    en = "Staghelm's Requiem",
    T = "Реквієм Стагхелма",
    D = "Стагхелм віддав наказ. Усі тролі на полі бою повинні бути знищені. Їхні абсурдні заяви про те, що вони породили нічних ельфів, повинні бути зустрінуті силою і належною упередженістю.$B$BУбий їх і повернися до мене з їхнім моджо. Повторюю: я хочу, щоб ти вкрав їхнє моджо.",
    O = "Тобі доручено вбивати ворожих гравців-тролів у Долині Альтерака.$B$BУбий троля і повернися до Атраманіс у Дун’Балдарі з Моджо Темного Списа.",
    P = "",
    C = "",
},

[7366] = {
    en = "The Archbishop's Mercy",
    T = "Милосердя Архієпископа",
    D = "Архієпископ такий же добрий, як і мудрий. Для людини дивитися милосердно на такий жалюгідний народ...$B$B<Командир Філіпс з недовір’ям хитає головою.>$B$BЗанадто добрий... Просто занадто добрий.$B$BАрхієпископ просить, щоб ми пожаліли нежить і дарували їм швидку і остаточну смерть. Для цього великого прояву милосердя ми лише вимагаємо їхні чорні, хворобливі серця.$B$BПринеси мені серця Покинутих, щоб їх можна було урочисто спалити в Соборі Світла. Поспіши, $N!",
    O = "Тобі доручено вбивати ворожих гравців-Покинутих у Долині Альтерака.$B$BУбий Покинутого і повернися до Командира Карла Філіпса (який блукає між лісопильнею і шахтою) з Серцем Покинутого.",
    P = "Бенедиктус! Я лише цятка в тіні його величі. Хваліть його!",
    C = "Слава Бенедикту! Ще одна загублена душа, яку скоро врятує біле гаряче полум’я Світла!$B$BGo так, о солдате Світла! Треба більше економити!",
},

[7367] = {
    en = "Defusing the Threat",
    T = "Знешкодження загрози",
    D = "Морозні Вовки замінували свої передові позиції та бази, $c. Ти мусиш бути обережним, вторгаючись на ворожу територію.$B$BЯкщо хочеш завдати їм серйозного удару, ти мусиш знищити їхнє джерело протипіхотних боєприпасів — я говорю про їхнього експерта з вибухівки. Якщо ти вб’єш його, ти зможеш безпечно знешкодити міни. Поки він не повернеться, міни також залишаться знешкодженими.$B$BЙмовірно, ти знайдеш його у вежі біля Гарнізону Крижанокровки. Успіхів!",
    O = "Знайди Експерта з Вибухівки Морозного Вовка і вбий його. Повернися до Експерта з Вибухівки Бурешпилів, коли завдання буде виконано.",
    P = "",
    C = "",
},

[7368] = {
    en = "Defusing the Threat",
    T = "Знешкодження загрози",
    D = "Я знаю все про наземні міни. Зрештою, саме я розміщую всі міни на передових позиціях тут.$B$BЯкщо хочеш знешкодити мінні поля Бурешпилів, все, що тобі потрібно зробити, — це вбити їхнього експерта з вибухівки. Цей боягузливий дворф, безсумнівно, ховається у першій вежі на Полі Боротьби. Прибери його, і ці наземні міни не повернуться після знешкодження.$B$BЯкщо тобі вдасться його вбити, повертайся сюди і дай мені знати. Жоден добрий вчинок не повинен залишитися без нагороди.",
    O = "Знайди Експерта з Вибухівки Бурешпилів і вбий його. Повернися до Експерта з Вибухівки Морозного Вовка, коли завдання буде виконано.",
    P = "",
    C = "",
},

[7381] = {
    en = "The Return of Korrak",
    T = "Повернення Коррака",
    D = "Хоч Коррак і був убитий, залишається одне питання: чи залишиться він мертвим? Тролі відомі своїми потойбічними племінними магіями. Я не здивуюся, якщо загиблого лідера воскресять, щоб знову правити своїм кланом.$B$BТи знаєш, що робити, якщо це станеться.$B$B<Воєначальник Лаґґронд проводить пальцем по шиї, імітуючи різання.>$B$BІ цього разу я хочу його череп. Просто тримай очі відкритими, солдате.$B$BВідбій!",
    O = "Якщо Коррак Кровожер повернеться на Поле Боротьби, розшукай його і знищ його.$B$BПоверни Череп Коррака до Воєначальника Лаґґронда в Передгір’ях Гіллсбрада.",
    P = "",
    C = "",
},

[7382] = {
    en = "Korrak the Everliving",
    T = "Коррак Вічно Живий",
    D = "Щось тут не так... Хтось подумав спалити тіло Коррака? Ці тролі не зупиняться ні перед чим, щоб воскресити свого загиблого лідера — як це часто роблять синьошкірі язичницькі людозвірі.$B$BПросто будь напоготові, $N. Не дивуйся, якщо Коррак несподівано з’явиться; і якщо це станеться, я хочу, щоб його стратили — а його тіло спалили на попіл.$B$BДля певності відріж йому голову і принеси мені його череп, перш ніж спалити безживну масу.",
    O = "Якщо Коррак Кровожер повернеться на Поле Боротьби, розшукай його і знищ його.$B$BПоверни Череп Коррака до Лейтенанта Гаґґердіна в Передгір’ях Гіллсбрада.",
    P = "",
    C = "",
},

[7383] = {
    en = "Crown of the Earth",
    T = "Корона Землі",
    D = "Однак із Тельдрассілом не все було гаразд. Ретельно продумані плани Стагхелма щодо нового Світового Древа виправдалися, як він сподівався, але була одна невелика проблема, якій можна приписати багато бід на Тельдрассілі.$B$BОднак я ще не буду вдаватися в це. Ти мусиш відвідати останню місячну криницю, на північному заході в Оракульській Галявині. Під кроною Оракульського Древа лежить перша і наймогутніша з наших криниць. Набери флакон її води і повернися до мене.",
    O = "Наповни Аметистовий Флакон і поверни його до Корітраса Місячної Пісні в Доланаарі.",
    P = "Разом з друїдами дерево Оракул і друїд-архів ретельно стежили за ростом Тельдрассила. Але хоча ми маємо новий дім, наше безсмертне життя не відновилося.",
    C = "Перебувати в присутності Дерева Оракула... це майже відчувати, як мудрість набуває форми. Дозвольте мені продовжити розповідь...$B$BWith Виріс Тельдрассіл, архидруїд звернувся до драконів за їхнім благословенням, як дракони надали Нордрасілу в давнину. Але Ноздорму, Володар часу, відмовився дати своє благословення, докоряючи друїду за його зарозумілість. За погодженням з Ноздорму Алекстраза також відмовилася від Оленевого Гельма, і без її благословення ріст Тельдрассила був неповноцінним і непередбачуваним...",
},

[7385] = {
    en = "A Gallon of Blood",
    T = "Галон Крові",
    D = "",
    O = "",
    P = "Ви повинні вразити наших ворогів і принести мені їхню кров.",
    C = "Пролилася кров наших ворогів. Я змішаю цю кров із рештою, яку зібрали. Щойно приношення буде завершено, Льодовий Лорд покаже на цих собак Грозової Верхи весь гнів Клану Крізного Вовка!",
},

[7386] = {
    en = "Crystal Cluster",
    T = "Кришталевий Кластер",
    D = "",
    O = "",
    P = "Солдати Крізного Вовка носять елементарні чари, які називаються грозовими кристалами. Ми можемо використати чари, щоб заклинати Івуса. Вирушай вперед і забери кристали, $N!",
    C = "Молодець, $N. Я використаю силу цих чар, щоб посилити вже зібрану магію. Коли буде накопичено достатньо сил, я зосереджу зібрану енергію та покличу Володаря Лісу допомогти нашій справі.",
},

[7401] = {
    en = "Wanted: DWARVES!",
    T = "Розшукуються: ДВОРФИ!",
    D = "За наказом Сержанта Язри Кровосмока, усіх дворфів на полі бою слід убивати на місці.$B$BЯкщо ти вб’єш дворфа в бою, вирви його хребет, залишивши безхребетну купу смороду і гнилі, щоб це стало попередженням для всіх, хто насмілиться протистояти могутності Морозного Вовка.$B$BПовернися до Сержанта Язри Кровосмока з доказами твоїх героїчних вчинків.",
    O = "Тобі доручено вбивати ворожих гравців-дворфів у Долині Альтерака.$B$BУбий дворфа і вирви його хребет. Віднеси Дворфійський Хребет до Сержанта Язри Кровосмока у Фортеці Морозного Вовка.",
    P = "Я займаюся оптовою іронією, солдате.",
