[7441] = {
    en = "Pusillin and the Elder Azj'Tordin",
    T = "Пусіллін і Старійшина Аж’Тордін",
    D = "Я втратив пильність лише на мить, чужинцю. У поспіху, рятуючись від полону занепалого Принца, мене пограбували. Найогидніший демон, біс Пусіллін, викрав мою книгу заклинань і ключ до колись величних залів Елдре’Таласа.$B$BЯ більше не цікавлюся ключем, адже я обміняв своє безсмертя на свободу, але мені відчайдушно потрібна моя книга заклинань.$B$BЗнайди біса Пусілліна і поверни мою книгу.$B$BШукай Пусілліна в Кварталі Криводрева в Жахливому Молотові.",
    O = "Вирушай до Жахливого Молота і знайди біса Пусілліна. Переконай Пусілліна віддати тобі Книгу Заклинань Аж’Тордіна будь-якими необхідними засобами.$B$BПовернися до Аж’Тордіна в Павільйоні Ларісс у Фераласі, якщо тобі вдасться повернути Книгу Заклинань.",
    P = "Ні про що не шкодую, незнайомець. Королева вже давно померла. Роботи Шен'Дралара були зіпсовані божевіллям принца Тортелдрина. Я шукаю лише свободи... Втечі...",
    C = "Ви знайшли це! Прокляття на цього жалюгідного імп. На жаль, мої матеріальні статки в кращому випадку мізерні. Ви можете вибрати з того, що я пропоную.",
},

[7461] = {
    en = "The Madness Within",
    T = "Божевілля всередині",
    D = "Ти чув достатньо? Ти $gлюдина:жінка; дії?$B$BЦе божевілля мусить закінчитися. Ера безсмертних давно минула. Знищ охоронців, що оточують пілони, щоб вимкнути силове поле. Коли це буде зроблено, знищ Іммол’тара. Зі значно послабленою силою Принца, атакуй і покінчи з ним. Поховай духів цього міста, шукачу пригод.",
    O = "Ти мусиш знищити охоронців, що оточують 5 Пілонів, які живлять В’язницю Іммол’тара. Після того, як пілони будуть відключені, силове поле, що оточує Іммол’тара, розсіється.$B$BУвійди до В’язниці Іммол’тара і знищ мерзенного демона, що стоїть у її серці. Нарешті, протистань Принцу Тортелдріну в Атенеумі.$B$BПовернися до Стародавнього Шен’дралара у дворі, якщо виконаєш це завдання.",
    P = "Будь обережний, авантюрист. Принц... переконливий.",
    C = "Ми дякуємо тобі, герою.",
},

[7462] = {
    en = "The Treasure of the Shen'dralar",
    T = "Скарб Шен’дралара",
    D = "У бібліотеці, Атенеумі, ти знайдеш стародавню скриню, заховану під сходами. Візьми з неї те, що забажаєш.",
    O = "Повернися до Атенеума і знайди Скарб Шен’дралара. Отримай свою нагороду!",
    P = "",
    C = "Ви відкриваєте скриню, щоб знайти...",
},

[7463] = {
    en = "Arcane Refreshment",
    T = "Арканне Оновлення",
    D = "$r маг! Яке диво. Я не бачив когось із твого роду... о, скільки це вже? 500 років!$B$BУ мене є дещо, що втамує твою спрагу, але спочатку ти мусиш виконати для мене завдання.$B$B<Лідрос хихикає.>$B$BВ Елдре’Таласі є аномалія. Водяний елементаль оселився в східному крилі. Його присутність мусить бути зафіксована!$B$BВирушай до Кварталу Криводрева і добудь частину елементальної сутності Гідроспавна. Поверни її мені, і я навчу тебе корисному заклинанню.",
    O = "Вирушай до Кварталу Криводрева Жахливого Молота і знищ водяного елементаля, Гідроспавна. Повернися до Хранителя Знань Лідроса в Атенеумі з Сутністю Гідроспавна.",
    P = "Так? я тебе знаю",
    C = "Чудово! хто ти знову? О, це не має значення. Що я мав тобі дати? Хм... добре, ти $C, можливо, це буде для тебе корисним.",
},

[7478] = {
    en = "",
    T = "Ліберам Швидкості",
    D = "Майстер Вінталус втратив Ліберам Швидкості в східному крилі. Ліберам дозволить накласти незначне заклинання прискорення на твоє спорядження. Дрібничка, справді...$B$BНезалежно від цього, якщо тобі цікаво, тобі потрібно буде пред’явити Ліберам разом із деякими базовими реагентами.$B$BГм... здається, також потрібна кров героїв, бездоганний чорний діамант і великі блискучі уламки. Я можу помилятися!$B$B<Лідрос знизують плечима.>",
    O = "Принеси Ліберам Швидкості, 1 Бездоганний Чорний Діамант, 2 Великих Блискучих Уламки і 2 Крові Героїв до Хранителя Знань Лідроса в Жахливому Молотові, щоб отримати Арканум Швидкості.",
    P = "",
    C = "",
},

[7479] = {
    en = "",
    T = "Ліберам Фокусу",
    D = "Цей ліберам майже викликав інтерес у одного з молодших фамільярів Хранителя Знань. Бідолаха, йому було лише кілька тижнів.$B$BТі з вас, хто більше схильний до магії, можуть знайти цей предмет цікавим.$B$BЛіберам Фокусу був втрачений у цьому крилі. Я можу лише припустити, що один із духів Вищероджених тримає його у своєму володінні.$B$BПринеси Ліберам разом із кількома великими блискучими уламками, шкірою тіні та бездоганним чорним діамантом, і я викличу Арканум.",
    O = "Принеси Ліберам Фокусу, 1 Бездоганний Чорний Діамант, 4 Великих Блискучих Уламки і 2 Шкіри Тіні до Хранителя Знань Лідроса в Жахливому Молотові, щоб отримати Арканум Фокусу.",
    P = "",
    C = "",
},

[7480] = {
    en = "",
    T = "Ліберам Захисту",
    D = "Він плакав, як немовля, через втрату цього лібераму. Зрозумійте, я сам плакав над текстами — немає більшої втрати, ніж втрата знань і історії — але плакати над цією майже марною купою заклинань? Нісенітниця! Це змусило мене повірити, що Принц робив йому послугу, здираючи плоть із його кісток.$B$BПринеси Ліберам разом із бездоганним чорним діамантом, великими блискучими уламками і зношеною шитвою мерзоти, і я відтворю Арканум.$B$BО, і перевір північне крило.",
    O = "Принеси Ліберам Захисту, 1 Бездоганний Чорний Діамант, 2 Великих Блискучих Уламки і 1 Зношену Шитву Мерзоти до Хранителя Знань Лідроса в Жахливому Молотові, щоб отримати Арканум Захисту.",
    P = "",
    C = "",
},

[7481] = {
    en = "Elven Legends",
    T = "Ельфійські Легенди",
    D = "Кілька років тому самотній ельфійський майстер на ім’я Каріел Вінталус утік від спустошення своєї батьківщини з кількома стародавніми ельфійськими артефактами.$B$BНаші пошуки цього втраченого майстра привели нас від руїн Кель’Таласа через Палаючі Степи, через великі простори моря до Фераласа.$B$BМи підозрюємо, що ельф шукав притулку в залах Елдре’Таласа (те, що нині відоме як Жахливий Молот).$B$BТи мусиш знайти його, шукачу пригод. Живого чи мертвого, знання, які він ніс, повинні бути повернуті!",
    O = "Обшукай Жахливий Молот у пошуках Каріела Вінталуса. Доповіси Вченому Королуску в таборі Моджаче з будь-якою інформацією, яку ти знайдеш.",
    P = "Моя напарниця, дослідниця нічних ельфів Рунеторн, набирає своїх союзників для виконання цього завдання.",
    C = "Ганьба... трагедія. Кажете, речі втрачені? Ні сліду від нього, еге ж?",
},

