[7486] = {
    en = "A Hero's Reward",
    T = "Нагорода героя",
    D = "$N, твої послуги для Воєначальників перевершили всі наші очікування від мешканців цього світу.$B$BМи не розуміємо понять вашого народу про вдячність чи нагороду за добрі справи, але в цьому випадку... можливо, нагорода виправдана.$B$BПід хвилями на південній основі цього острова ти знайдеш скриню. У ній буде твоя... нагорода.$B$BІди, $N. Отримай свою нагороду.",
    O = "Отримай свою нагороду зі Скрині Гідраксіса.",
    P = "",
