[7507] = {
    en = "Foror's Compendium",
    T = "Компендіум Форо’ра",
    D = "Ти розкрив щось надзвичайно важливе. Ця книга не схожа на жодну, яку ти бачив.$B$BСхоже, хтось або щось зумів розбити печатку Атенеума. Текст усередині спотворений і ледь читабельний.",
    O = "Поверни Компендіум Форо’ра про Вбивство Драконів до Атенеума.",
    P = "О, одна з наших найкращих збірок. Цей був відсутній протягом століть.",
    C = "Ви могли отримати чимало золота за цю книгу на чорному ринку, $N. Особливо після того, як захисну печатку було зламано, залишивши таємниці вбивства драконів доступними для будь-кого, хто має необхідний інтелект, щоб отримати знання, що зберігаються на священних сторінках.$B$BМожливо чекає велика нагорода... Що ж, нагорода, для отримання якої знадобляться величезні зусилля.$B$B<Лідрос посміхається.>",
},

[7508] = {
    en = "The Forging of Quel'Serrar",
    T = "Кування Квель’Серрара",
    D = "Якщо ти бажаєш взятися за це завдання, пред’яви Лідросу тьмяне лезо.",
    O = "Віддай Тьмяне і Пласке Ельфійське Лезо Хранителю Знань Лідросу.",
    P = "Чудово, почнемо...",
    C = "Якщо тобі вдасться увійти в лігво дракона, розігріти лезо під її вогненним диханням і, зрештою, загартувати його в її крові, я зв’яжу лезо для твого використання.",
},

[7509] = {
    en = "The Forging of Quel'Serrar",
    T = "Кування Квель’Серрара",
    D = "Віднеси незгартоване стародавнє лезо до лігва Онікії і вступи з нею в бій.$B$BПотрібна певна хитрість, щоб нагріти лезо. Під час бою вона неодмінно спробує спалити тебе своїм вогняним диханням. Ти мусиш встановити незгартоване стародавнє лезо неподалік і сподіватися, що вогняне дихання нагріє лезо. Якщо тобі вдасться вижити, підбери тепер нагріте стародавнє лезо і добий дракона.$B$BПроколи нагрітим стародавнім лезом її тліючий труп, щоб створити оброблене стародавнє лезо.",
    O = "Ти мусиш змусити Онікію дихнути вогнем на Незгартоване Стародавнє Лезо. Після цього підбери тепер Нагріте Стародавнє Лезо. Попереджаю, Нагріте Стародавнє Лезо не залишатиметься нагрітим вічно — час має значення.$B$BОстанній крок перед поверненням до мене — убити звіра і встромити Нагріте Стародавнє Лезо в її труп.$B$BЗроби це, і Квель’Серрар буде твоїм.",
    P = "Можливо, одного дня призматичним клинком володітиме інший.",
    C = "<Лідрос бурмоче щось нерозбірливе.>$B$BAs обіцяв, $C, клинок Кель'Серрара.",
},

[7521] = {
    en = "",
    T = "Тандерран Шукач Вітру",
    D = "Я розповів тобі все, що знаю, $N. Тобі належить знайти елементій. Тобі належить знищити тілесну форму Вогняного Лорда.$B$BЗроби це і отримай благословення Тандеррана.",
    O = "Щоб звільнити Тандеррана Шукача Вітру з його в’язниці, ти мусиш пред’явити праву і ліву половини Зв’язків Шукача Вітру, 10 злитків Елементію і Сутність Вогняного Лорда до Верховного Лорда Демітріана.",
    P = "",
    C = "",
},

[7541] = {
