},

[7562] = {
    en = "Mor'zul Bloodbringer",
    T = "Мор’зул Кровоприймач",
    D = "$N, твої занурення в темні мистецтва глибокі. Твоє панування над потойбічними створіннями стало настільки сильним... можливо, ти готовий зв’язати з собою одного з сумнозвісних жахокіней.$B$BРитуал для виклику звіра з його домівки вимагає великої сили і ресурсів, але якщо ти прагнеш підкорити цього епічного скакуна, поговори з Мор’зулом Кровоприймачем. Він розташувався табором біля Вівтаря Бур у Палаючих Степах.$B$BІди, $N. Ця місія буде небезпечною, але чаклун твого рівня не уникає небезпек!",
    O = "Поговори з Мор’зулом Кровоприймачем у Палаючих Степах.",
    P = "",
    C = "Вітаю, $N, і ласкаво просимо.  Ви тут, щоб навчатися біля Вівтаря Бурі, як і я, можливо, використовувати його енергію для якоїсь прихованої мети...$B$BOr... ви тут, щоб поговорити зі мною?  Так, я вважаю, що ви.$B$BYou бажаєте опанувати дредом?  Це непросте завдання.  Це коштуватиме вам немалої кількості крові, поту... і, звичайно, золота.  Але кіт жаху Ксорота — це нагорода, яку варто виграти, тому, якщо вам цікаво, слухайте...",
},

[7563] = {
    en = "Rage of Blood",
    T = "Лють Крові",
    D = "Жахокіні мешкають в іншому світі, на вогняних Рівнинах Ксорота, і щоб зв’язати одного з цих славетних звірів, тобі потрібно викликати могутні гліфи. Я можу накреслити гліфи на пергаменті для тебе, але спочатку мені потрібне особливе чорнило.$B$BУ далекому Зимоключі мешкає раса совозвірів. Колись чисті створіння, вони збожеволіли від демонічних еманацій Темношепотної Ущелини і тепер блукають снігами в шаленстві.$B$BЇхня кров — це те, що мені потрібно для чорнила твого пергаменту. Принеси її мені.",
    O = "Принеси 30 флаконів Крові Шаленої Звірини до Мор’зула Кровоприймача в Палаючих Степах.",
    P = "Ти бачив лютих сов, $N? Магія цих створінь сильна, і вона зосереджена в крові, що тече через їхні катовані форми.",
    C = "Ах, дуже добре. Я накажу цю кров перегнати на чорнило й використати для пергаменту, який я тобі обіцяв. І, мабуть, я трохи заощаджу для себе, бо я чую, що смак у нього досить ейфоричний...",
},

[7564] = {
    en = "Wildeyes",
    T = "Дикоглаз",
    D = "Мій слуга, Ґорзіккі, є алхіміком певної майстерності. Він може приготувати чорнило, яке мені потрібне для твого пергаменту. Я зібрав кров, яку ти добув; віднеси її до Ґорзіккі, щоб він міг розпочати роботу.",
    O = "Віднеси Ящик із Кров’ю до Ґорзіккі Дикоглаза в Палаючих Степах.",
    P = "Маєш щось для мене?  Це не великий соковитий павук, чи не так?  А може плотва?  Сподіваюся, воно ще живе... Я так люблю їх гризти, коли вони ще живі...",
    C = "О, це кров. Тоді це має бути від майстра Мор'зула. Він так закоханий у речі, і любить бачити, як це розливається. Я, однак, віддаю перевагу, щоб воно текло венами маленького гризуна. Таким чином він залишається теплим... доки ви цього не захочете.$B$BThis — потужна кров. Мор'зул, мабуть, створює ще один пергамент, щоб викликати жахливого скакуна! Як захоплююче!$B$BIf це правда, і ти збираєшся провести ритуал, тоді... тобі знадобиться набагато більше, ніж кров, друже.",
},

[7581] = {
    en = "The Prison's Bindings",
    T = "Зв’язки в’язниці",
    D = "Тобі потрібно добути зв’язки для в’язниці Стражника Долі від менших демонів.$B$BКров сатирів Дикородів, що населяють Жахливий Молот, підійде ідеально. Згорнута кров зв’яже уламки Гедеріну і живитиме кристальну в’язницю.",
    O = "Вирушай до Жахливого Молота в Фераласі і добудь 15 Крові Сатирів від сатирів Дикородів, що населяють Квартал Криводрева. Повернися до Дайо в Забрудненому Шрамі, коли це буде зроблено.",
    P = "Вистачить лише крові сатира Wildspawn.",
    C = "Ах, чудове одужання. Кров придушить магічну оборону Doomguard.",
},

[7582] = {
    en = "The Prison's Casing",
    T = "Оболонка в’язниці",
    D = "Демони Гедеріну, що населяють передгір’я гори Хіджал, виділяють потужні пекельні отрути, які, якщо дати їм дозріти, затвердівають у щільний антимагічний кристал. Ці кристали стали відомими як Сльози Гедеріну.$B$BНавіть величезна сила Стражника Долі не змогла б зруйнувати стіни в’язниці, створеної з цього матеріалу.$B$BВирушай до Темношепотної Ущелини в Зимоключі і добудь Сльози.",
    O = "Вирушай до Темношепотної Ущелини в Зимоключі і добудь 5 Сліз Гедеріну від демонів Гедеріну, що населяють ущелину. Повернися до Дайо в Забрудненому Шрамі, коли виконаєш це завдання.",
    P = "Гедерін не віддасть свої дорогоцінні камені без бою, $N.",
    C = "Мені потрібно лише з’єднати кров Wildspawn із цими кристалами, і в’язниця буде готова до використання.",
},

[7583] = {
    en = "Suppression",
    T = "Придушення",
    D = "В’язниця готова. Тепер найскладніша частина цього завдання.$B$BТи мусиш знайти і захопити Командира Стражників Долі в Забрудненому Шрамі, використовуючи цю кристальну в’язницю.$B$BПопереджаю! Стражник Долі — хитрий і смертельно небезпечний противник і намагатиметься знищити тебе, коли ти почнеш ритуал ув’язнення. Він шалено борсатиметься, намагаючись уникнути ув’язнення.$B$BВін зосередиться лише на тобі, $N. Через це я настійно рекомендую взяти з собою товаришів, здатних зберегти тобі життя!",
    O = "Вирушай до Забрудненого Шраму і знайди Командира Стражників Долі.$B$BВикористай Сяючу Кристальну В’язницю на Командирі Стражників Долі. Будь готовий до лютої атаки, коли демон намагатиметься уникнути захоплення.$B$BЯкщо тобі вдасться, поверни Ув’язненого Стражника Долі до Дайо в Забрудненому Шрамі.",
    P = "Хрм? добре?",
    C = "Ви зробили, як я просив. Ви готові отримати знання, щоб заклинати звіра та контролювати його.",
},

[7601] = {
    en = "What Niby Commands",
    T = "Що наказує Ніби",
    D = "Якщо я маю навчити тебе секретам виклику пекельного слуги, ти мусиш знищити Крошія і принести мені пекельне ядро з його палаючих залишків. Однак це не так просто, як звучить. Крошій майже повністю вигорів. Ти мусиш знову запалити його труп і підняти його з руїн. Для цього тобі потрібно зібрати деякі компоненти від інших демонічних сутностей.$B$BМій біс, Імпсі, направить тебе на шлях.",
    O = "Поговори з Імпсі в Фелвуді.",
    P = "",
    C = "О, хлопче, ми знову.",
},

[7602] = {
    en = "Flawless Fel Essence",
    T = "Бездоганна Пекельна Сутність",
    D = "Якщо ти збираєшся оживити Крошія, тобі потрібен пекельний вогонь. Я можу створити пекельний вогонь, але це вимагатиме деяких компонентів.$B$BТобі потрібно принести мені бездоганні пекельні сутності з трьох різних регіонів світу.$B$BСатири Леґаші в Азшарі матимуть перший тип сутності; легіонери Джеденара в Джеденарі — другий тип; а вартові пекельної варти в Спустошених Землях — третій.$B$BПринеси мені по одній сутності кожного типу, і я створю пекельний вогонь, що дозволить тобі оживити Крошія.",
    O = "Імпсі в Фелвуді просив, щоб ти приніс йому три Бездоганні Пекельні Сутності з трьох різних локацій.$B$BСатири Леґаші в Азшарі мають Бездоганну Пекельну Сутність свого регіону. Легіонери Джеденара в Джеденарі мають Бездоганну Пекельну Сутність свого регіону. Вартові Пекельної Варти в Спустошених Землях мають Бездоганну Пекельну Сутність свого регіону.$B$BДобудь Бездоганні Пекельні Сутності і повернися до Імпсі в Фелвуді.",
    P = "Не кажи нікому цього, але Нібі нерозумний.",
    C = "Дайте мені хвилину, і я об’єднаю есенції у вогонь Скверни.",
},

[7603] = {
    en = "Kroshius' Infernal Core",
    T = "Пекельне Ядро Крошія",
    D = "Крошій лежить у купі на північному сході, у Долині Розколотих Шрамів. Візьми цей Пекельний Вогонь і використай його на його залишках. Вогонь повинен оживити занепалого пекельника.$B$BНа цьому етапі я повністю очікую, що він уб’є тебе і всіх друзів, яких ти, можливо, взяв із собою — і повір мені, ти захочеш взяти з собою кількох друзів.$B$BЯкщо якимось дивом тобі вдасться вбити Крошія, забери його пекельне ядро і поверни його до Ніби.",
    O = "Обшукай Долину Розколотих Шрамів у Фелвуді у пошуках залишків Крошія. Коли знайдеш залишки, використай Пекельний Вогонь біля них і чекай повернення Крошія. Коли пекельник прокинеться, убий його і забери з його трупа Пекельне Ядро Крошія.$B$BПоверни Пекельне Ядро Крошія до Ніби Всемогутнього в Фелвуді.",
    P = "Ви заблукали?",
    C = "Угода є угода! Швидко візьміть це і запишіть це. Я не маю часу! Моє найбільше заклинання над нами!",
},

[7604] = {
    en = "A Binding Contract",
    T = "Обов’язковий контракт",
    D = "Підписант цим засвідчує, що злиток Сульфурона, який він доставляє до Братства Торію (ТБ Лтд.), є справжнім і не є його копією. Підписант також визнає, що будь-яка шкода, яка може статися з $gним:нею; внаслідок спроби побудувати, викувати, знайти, створити, продати або з’їсти Сульфурас, не є відповідальністю чи виною ТБ Лтд.$B$BПідписуючи цей контракт, ви погоджуєтеся з усіма умовами, викладеними тут.$B$B_________________$B$BPідпис",
    O = "Здай Контракт Братства Торію до Лохтоса Темноторговця, якщо хочеш отримати плани для Сульфурона.",
    P = "Ми домовилися?",
    C = "Мені було приємно співпрацювати з вами, $N!$B$BOn від імені TB Ltd., я бажаю вам успіхів у пошуку Sulfuras!",
},

[7621] = {
    en = "A Warning",
    T = "Попередження",
    D = "",
    O = "",
    P = "",
    C = "$C, ти збираєшся пройти сувору серію подій, які мають перевірити всі твої здібності.$B$BI пропоную тобі послухати історію, яку я маю розповісти.$B$BBe попереджаю, ти повинен виконати це завдання сам. Рекомендується, щоб ваші союзники залишалися на відстані. Втручання сторонніх агентів призведе до найсуворішого покарання.$B$BDestiny привів вас сюди, і тільки ви. Битва з честю. Використовуйте світло.",
},

[7622] = {
    en = "The Balance of Light and Shadow",
    T = "Баланс Світла і Тіні",
    D = "Ти мусиш зробити те, що я не зміг: врятувати селян, яких зарубали під час втечі зі Стратгольма.$B$BВони йтимуть до світла, ти мусиш забезпечити їхнє виживання. Якщо занадто багато загине, наше прокляте існування триватиме — ти зазнаєш невдачі.$B$BКожна здатність, молитва і заклинання, які ти вивчив, будуть випробувані. Нехай Світло захистить тебе, $N.",
    O = "Врятуй 50 Селян, перш ніж 15 будуть убиті. Поговори з Еріс Гавенфайр, якщо виконаєш це завдання.$B$BТи можеш переглянути Пост Смерті, щоб дізнатися, скільки селян було вбито.",
    P = "",
    C = "Ваша наполегливість і мужність вражають, жрице. Ви заслужили право тримати Осколок Нордрасіла. Залишається лише одне завдання: потрібно відновити Око Тіні. Очистити світ.",
},

[7623] = {
    en = "Lord Banehollow",
    T = "Лорд Бейнхоллоу",
    D = "Мор’зул каже, що ти хочеш відкрити портал до Ксорота. Для цього тобі потрібен ксоротський зоряний пил. Його нелегко знайти в Азероті!$B$BЄ одна істота, яка може його мати: Лорд Бейнхоллоу в Джеденарі, осередку Ради Тіней! Поговори з ним, і він може віддати тобі зоряний пил.$B$BАле якщо ти йдеш до Джеденара, тобі потрібно приховати себе в ароматі зла Ради Тіней. Для цього знадобляться мої тіньові зілля, і це коштуватиме тобі...",
    O = "Придбай Тіньові Зілля у Ґорзіккі в Палаючих Степах.$B$BВикористай зілля, щоб пройти через Джеденар, і поговори з Лордом Бейнхоллоу.",
    P = "",
    C = "Моє терпіння охоплює тисячоліття, $C.  Але не думайте, що це дасть вам більше, ніж мить мого часу...",
},

[7624] = {
    en = "Ulathek the Traitor",
    T = "Улатек Зрадник",
    D = "Ти бажаєш заслужити мою прихильність? Тоді вбий для мене.$B$BМій слуга, Улатек, жалюгідний, як він гне спину переді мною, весь час змовляючись із Лордом Хел’нуратом на Ксороті. Хел’нурат планує узурпувати мою владу тут, а Улатек — його шпигун...$B$BДоведи, що ти служиш мені, а не моїм суперникам. Зустрінь Улатека в його покоях, у Тіньовій Твердині на заході. Скажи йому, що я знаю його секрет, і спостерігай, як страх охоплює його. Потім принеси мені серце зрадника!",
    O = "Зустрінь Улатека і принеси Серце Зрадника до Лорда Бейнхоллоу в Джеденарі.",
    P = "Я вже відчуваю смак серця Улатека на своїх губах. Така солодка плоть зрадника...",
    C = "Ах, як чудово! Після тижня гниття це серце стане соковитим ласощами! Можливо, я пошлю за головою Улатека і покладу її перед собою, коли буду їсти...$B$BYou зробили мені послугу, $C, і тому моє терпіння до вас виросло. Маргінально.",
},

[7625] = {
    en = "Xorothian Stardust",
    T = "Ксоротійський Зоряний Пил",
    D = "То ти прийшов до мене за ксоротійським зоряним пилом? Хочеш відкрити портал до Ксороту, володінь мого суперника Гел’нурата? Може, плануєш викрасти одного з його дорогоцінних жахокопитів?$B$BГаразд. Мій слуга Ур’дан має запас ксоротійського зоряного пилу. Ти можеш отримати його... якщо заплатиш ціну.",
    O = "Купи Ксоротійський Зоряний Пил у Ур’дана. Принеси його до ҐорзікІ Дикоглаза в Палаючому Степовищі.",
    P = "Ви були в Jaedenar, $N? Ви отримали зоряний пил від лорда Бейнхоллоу?",
    C = "Ось воно! Мені важко повірити, що ти це отримав! Ви, мабуть, уклали велику угоду з тим Володарем жаху, або заплатили велику суму, або і те, і інше!$B$BMor'зул дуже скоро отримає чорнило, і тоді він нарешті зможе зробити пергамент для гліфів, тож ви зможете відкрити портал до Ксорота та протягнути через нього одного зі знаменитих дредистів!",
},

[7626] = {
    en = "Bell of Dethmoora",
    T = "Дзвін Детмури",
    D = "Дзвін Детмури, названий на честь покійного чаклуна Детмури Темноокого, — один із трьох інструментів, потрібних для створення Кола Великого Виклику. Якщо правильно налаштувати його разом із Колесом і Свічкою, ці предмети проводять величезні запаси магічної сили.$B$BМій слуга ҐорзікІ може виготовити такий дзвін, але для цього йому знадобиться велика кількість еліксирів тіньової сили. Дістань ці еліксири в алхіміка та принеси їх ҐорзікІ.",
    O = "Принеси 10 Еліксирів Тіньової Сили до ҐорзікІ Дикоглаза в Палаючому Степовищі.",
    P = "У вас є ці еліксири, $N? Мор'зул сказав мені, що тобі потрібен Дзвін Детмура, і для створення такого потрібно багато сили тіні!",
    C = "Дуже добре! Сподіваюся, ці еліксири було не надто важко дістати. Іноді алхіміки можуть бути такими скупими на своїх витворах...$B$BI зробить дзвін і збереже його, доки ви не будете готові до ритуалу.",
},

[7627] = {
    en = "Wheel of the Black March",
    T = "Колесо Чорного Походу",
    D = "Колесо Чорного Походу утримує та спрямовує бурхливі енергії, необхідні для Кола Великого Виклику. Щоб ҐорзікІ виготовив колесо, йому знадобляться великі блискучі уламки від чародія та руда темного заліза від майстра-гірника.$B$BДістань ці речі та принеси їх моєму слузі.",
    O = "Принеси 6 Великих Блискучих Уламків і 25 Руди Темного Заліза до ҐорзікІ в Палаючому Степовищі.",
    P = "Колесо Чорного походу зробити нелегко, для цього потрібно багато матеріалів. Ви вже їх зібрали?",
    C = "Ось вони! Я чув, що темну залізну руду знаходять лише в глибинах Чорної гірки, і я впевнений, що ці осколки також було непросто знайти. Мене часто вражає ваша відданість, чорнокнижники. Якщо ви натомість спрямуєте всю свою енергію на мистецтво ловити жуків, ох... таке свято вам сподобається!$B$BSorry, невеликий відступ. Я створю колесо і збережу його для вас, поки ви не будете готові до свого ритуалу.",
},

[7628] = {
    en = "Doomsday Candle",
    T = "Свічка Судного Дня",
    D = "Свічка Судного Дня зберігає вогонь і спрямовує його на тих, хто може порушити твій ритуал. Під час створення Кола Великого Виклику, якщо твоя свічка запалена, будь-які блукаючі демони будуть спалені її полум’ям!$B$BУтримати цей вогонь непросто, і для цього потрібна есенція, що міститься в лусці чорного дракона. Дістань цю луску у шкіродера та принеси її до ҐорзікІ Дикоглаза.",
    O = "Принеси 35 Лусок Чорного Дракона до ҐорзікІ Дикоглаза в Палаючому Степовищі.",
    P = "Ти приніс драконячу луску, $N? Я не хочу починати зі свічки, доки я їх не отримаю... інакше я можу підірвати весь табір!",
    C = "Ах, дуже добре. Мені це знадобиться, щоб стримати вогонь свічки. Тепер, коли у мене є ваги, я зроблю свічку і тримаю її, доки ви не будете готові розпочати свій ритуал для Кола Великого Прикликання.",
},

[7629] = {
    en = "Imp Delivery",
    T = "Доставка Біса",
    D = "Для пергаменту Мор’зула потрібен ще один процес: папір, просочений ксоротійським зоряним пилом. І... боюся, я не можу зробити це тут. У мене немає потрібного обладнання!$B$BПроте є алхімічна лабораторія, де є все необхідне. Вона в Схоластії, на острові Каер Дарроу в Чумних Землях.$B$BЯ не можу вирушити туди, але ось — візьми цю банку. У ній біс, який досить розумний. Випусти його в алхімічній лабораторії, і він просочить пергамент.",
    O = "Принеси Банку з Бісом до алхімічної лабораторії в Схоластії. Після створення пергаменту поверни банку до ҐорзікІ Дикоглаза.",
    P = "Ви були на Шоломантії, $N? Чи чорт уже просякнув пергамент зоряним пилом?",
    C = "Ах, добре. J'eevee створив пергамент. Як пройшла Шоломантія? Чарівно, вам не здається? А жуки там... Я чув, вони смачні!$B$BWell готово, $N, і дякую, що повернув мою банку. У мене давно... і не продається!",
},

[7630] = {
    en = "Arcanite",
    T = "Арканіт",
    D = "Тепер, коли Дзвін, Колесо та Свічка виготовлені, я повинен зробити чорний магнітний камінь. Під час твого ритуалу цей камінь знадобиться, щоб підтримувати інші ритуальні предмети, якщо вони вийдуть з ладу.$B$BДля створення магнітного каменя потрібен арканіт. У тебе є? Якщо ні, то... тобі доведеться дістати арканіт у алхіміка.$B$BПовертайся до мене, коли матимеш арканіт, і тоді я виготовлю чорний магнітний камінь.",
    O = "Принеси 3 Арканіти до ҐорзікІ в Палаючому Степовищі.",
    P = "У вас є арканіт, $N? Як тільки я його отримаю, я зможу зробити для вас чорний магніт.",
    C = "Ви зрозуміли! Гарно зроблено! Тепер я можу створити камінь. Коли ви нарешті будете готові до свого ритуалу, щоб створити Коло Великого Прикликання, вам знадобиться магнітний камінь, щоб переконатися, що ритуал не зіпсується!",
},

[7631] = {
    en = "Dreadsteed of Xoroth",
    T = "Жахокопит Ксороту",
    D = "Усі приготування завершено. Тепер ти повинен провести ритуал, щоб створити Коло Великого Виклику, а потім використати пергамент, просочений ксоротійським зоряним пилом, щоб відкрити портал до Ксороту.$B$BЯ записав інструкції для ритуалу на сувої. Вивчи його уважно, адже кожен крок треба виконати точно, якщо хочеш досягти успіху.$B$BУдачі тобі, $N. І нехай душі твоїх ворогів швидко опиняться у твоїй торбинці з уламками.",
    O = "Прочитай Інструкції Мор’зула. Виклич Ксоротійського Жахокопита, переможи його, а потім прив’яжи його дух до себе.",
    P = "",
    C = "Дух Ксоротського Дредстеда побитий.  Хоча гнів пульсує його примарними боками, ви знаєте, що душа звіра належить вам... $B$BIt шепоче темну магію у ваш розум і вселяє у вас знання, як викликати дредиста.",
},

[7632] = {
    en = "The Ancient Leaf",
    T = "Стародавній Листок",
    D = "Епідерміс листка світиться яскраво-зеленим. Його поверхня надзвичайно горбиста, з видимими венами та зморшками.$B$BЯкщо припустити, ти б сказав, що цей листок походить від чогось стародавнього та могутнього.$B$BМожливо, варто знайти первісного власника цього листка?",
    O = "Знайди власника Стародавнього Скам’янілого Листка. Удачі, $N; світ великий.",
    P = "<Вартрус стогне.>",
    C = "Звичайно, я впізнаю своє листя. Подивіться на це! Він у ідеальному стані.$B$BHow добре з вашого боку, що повернули його, $C.$B$BМожливо ви могли б бути корисними нам, а ми вам.",
},

[7633] = {
    en = "An Introduction",
    T = "Вступ",
    D = "",
    O = "",
    P = "",
    C = "Вашу старанність і порядність було відзначено, $C.$B$BWe є Стародавніми: захисниками цього колись великого лісу. Наші фізичні форми були знищені 10 000 років тому, коли Архімонд і Палаючий Легіон рушили на Хіджал. Однак наш дух залишається незмінним.$B$BThere — це завдання, які ми можемо запропонувати. Завдання, виконання яких відкриє вам таємниці Стародавніх.$B$BKnow якщо ви виконаєте ці завдання, просто поверніться до цієї скелі, і ми відповімо на покликання.",
},

[7634] = {
    en = "Ancient Sinew Wrapped Lamina",
    T = "Стародавній Сагайдак із Жилами",
    D = "Вітаю, $c. Я Гастат, Стародавній Знань. Я володію мудрістю, втраченою тисячоліття тому.$B$BЗ належним зв’язком один із моїх листків може стати сагайдаком, якого не бачили вже 10 000 років. Сагайдак, який разом із луком Стародавніх може наділити невимовною силою.$B$BПовернися сюди з жилами дорослого синього дракона, і цей сагайдак буде твій.",
    O = "Гастат Стародавній просить принести йому Жили Дорослого Синього Дракона. Якщо знайдеш ці жили, поверни їх до Гастата в Смерколіссі.",
    P = "З поверненням, молодий $C.",
    C = "Нехай моє листя захистить твої стріли від зла. Нехай твої стріли влучають вірно. Хай будуть розбиті вороги нашого світу.",
},

[7635] = {
    en = "A Proper String",
    T = "Належна Тятива",
    D = "Вартрюс може запропонувати тобі посох для створення лука Стародавніх, але лише я можу зачарувати тятиво, необхідну для завершення лука.$B$BЦе просте завдання, нікчемо. Убий дорослого чорного дракона та видали жили з його кісток. Принеси ці жили мені, і я зачарую матеріал у майже незнищенну тятиво для лука.",
    O = "Стома Стародавній просить принести йому Жили Дорослого Чорного Дракона. Якщо знайдеш ці жили, поверни їх до Стоми в Смерколіссі.",
    P = "Я впевнений, що тобі не буде важко знайти та вбити чорного дракона, $N. Не витрачайте мій час на балачки.",
    C = "Цей був наймерзенніший дракон. Сухожилля тхне злом.$B$BGive мені дати час, щоб очистити цю плоть від бруду та застосувати відповідні чари.",
},

[7636] = {
    en = "Stave of the Ancients",
    T = "Посох Стародавніх",
    D = "Агенти Палаючого Легіону все ще діють у нашому світі, $c. Ці агенти псують усе, до чого торкаються. Природа в’яне і плаче в їхній присутності.$B$BТи повинен вистежити цих демонічних осквернителів і знищити їх, $N. Будь обережний, ти маєш битися з ними самотужки, інакше вони втечуть. Поки ти один, вони намагатимуться знищити тебе. Ти мусиш ударити першим, обернувши їхню пиху на страждання.$B$BЯ дарую тобі шматок моєї кори, написи на ній вкажуть тобі на цілі. Принеси їхні голови.",
    O = "Ти повинен знайти та знищити чотирьох демонічних осквернителів:$B$BСимона Спокусниця.$B$BКлінфран Божевільний.$B$BСоленор Убивця.$B$BАрторіус Згубоносець.$B$BЗнищ цих створінь і повернися до Вартрюса Стародавнього в Смерколіссі з їхніми головами.$B$BЗвертайся до Скам’янілої Кори у твоєму інвентарі, щоб знайти підказки про їхнє місце перебування.$B$BТи ПОВИНЕН виконати це завдання самотужки.",
    P = "Нехай вас не обманюють їхні маскування!",
    C = "Ви добре послужили нам, $N! Візьміть цей держак і поєднайте його з тятивою лука, яку може створити Стома. Разом вони утворюють найстрашнішу зброю.",
},

[7637] = {
    en = "Emphasis on Sacrifice",
    T = "Наголос на Жертві",
    D = "Щоб підготуватися до цього завдання, ти спершу мусиш показати належну жертву та розсудливість... із наголосом на жертві.$B$BТи повинен здобути кадильницю для екзорцизму Верховного Жерця Рогана для твого завдання. Хоча її використання буде заради доброї та справедливої мети, за неї потрібно дати належну компенсацію.$B$BВирушай до Залізогарта та поговори з Верховним Жерцем. Принеси достатньо золота, щоб компенсувати втрату його кадильниці, це покаже твою належну жертву.$B$BІди зараз, $N, час не чекає.",
    O = "Вируш до Залізогарта та отримай Кадильницю для Екзорцизму Верховного Жерця Рогана. Тобі потрібно зробити пожертву в 150 золотих, щоб її отримати.",
    P = "Вітаю, шляхетний $C! Я підготував свою надійну кадильницю з найсвіжішим ладаном і тричі освятив її для вашого використання. Ваша пожертва допоможе нам у Стальгорні не лише створити нову кадильницю, а й збільшити запаси їжі для потребуючих.",
    C = "Благословення тобі, друже $C! Ваша пожертва значно перевищує те, що було потрібно. Ваша жертва не лише допоможе нам відновити те, що ми втратили, але й допоможе нам допомогти тим, хто найбільше потребує тут, у Стальгорні.$B$BNow, дозвольте мені переконатися, що я належним чином підготував цю кадильницю для ваших майбутніх потреб...",
},

[7638] = {
    en = "Lord Grayson Shadowbreaker",
    T = "Лорд Ґрейсон Тінеломець",
    D = "Час настав, $N, щоб ти дізнався, що потрібно для здобуття того, чого ти, без сумніву, давно чекав... твого бойового коня.$B$BПоговори з Лордом Ґрейсоном Тінеломцем у Соборному Окрузі Штормовію. Саме він проведе тебе не лише через хитрощі найвірнішого скакуна паладина, але й через завдання, які тобі належить виконати, щоб здобути власного.$B$BЯ бажаю тобі успіху в цьому випробуванні. За Світло, благородний $G брате : сестро;!",
    O = "Поговори з Лордом Ґрейсоном Тінеломцем у Соборному Окрузі Штормовію.",
    P = "",
    C = "Я радий тебе бачити $N. Я знаю, що ви чекали повідомлення про те, як придбати свій зарядний пристрій, і тепер цей час настав. $B$BYou, безперечно, буде перевірено багатьма різними способами, але найголовніше — вашою готовністю піднятися над численними перешкодами, які стоять перед вами. Вони не виконуються як навчальна вправа - ваш зріст виходить за межі простих навчальних тестів. Ви повинні врятувати свого майбутнього супутника з лап зла, з яким ви боролися все життя.$B$BTake Увага, ваш час настав!",
},

[7639] = {
    en = "To Show Due Judgment",
    T = "Показати Належну Розсудливість",
    D = "З моїм благословенням, бери кадильницю. Я сам використовував її в кількох екзорцизмах, і вона добре послужить тобі в нелегких завданнях, що попереду.$B$BПовертайся тепер до Лорда Ґрейсона Тінеломця в Штормовій, $N. Твій квест триває з ним.",
    O = "Поверни Кадильницю для Екзорцизму до Лорда Ґрейсона Тінеломця в Соборному Окрузі Штормовію.",
    P = "З поверненням, $N. Ви придбали кадильницю для екзорцизму?",
    C = "Так, підійде. Під час цього процесу ви будете покликані кілька разів зробити акт жертви; Я радий бачити, що ви готові це зробити. Жертовність є ключовим компонентом того, що потрібно для виконання обов’язків паладина... але я не маю повчати вас про це.$B$BNow $N, вам потрібно буде виявляти належну розсудливість у своїх діях. З цією метою ця кадильниця виступатиме як ваша посудина для винесення такого вироку над замученими духами втрачених для нас земель.",
},

[7640] = {
    en = "Exorcising Terrordale",
    T = "Екзорцизм Терордолу",
    D = "Я додав щіпку землі з осквернених земель Терордолу в Східних Чумних Землях до кадильниці. Тепер ти використовуватимеш цю кадильницю, щоб знайти місця там, де є ознаки духовного неспокою та порушень. Шукай зелені аури, що пронизують землю, коли фізичний світ тріщить під тиском духовного царства, і використовуй кадильницю, щоб вигнати злих духів.$B$BКоли ти винесеш достатній суд над духами там, ти будеш готовий рухатися далі.",
    O = "Використай Кадильницю для Екзорцизму, щоб вигнати духів, що мучать Терордол. Коли ти знищиш 25 Духів Терордолу, повернися до Лорда Ґрейсона Тінеломця в Соборному Окрузі Штормовію.",
    P = "Приємно бачити тебе знову $N. Ваша робота виконана в Terrordale?",
    C = "Молодець, $N. Здійснити вирок Світла над тими, хто живе в темряві, є завданням, до якого ми повинні підійти з енергією та ревністю; ви зробили саме це завдяки своїй жертві в Стальгорні та своїм судам над духами в Терордейлі.$B$BYour наступні кроки знову вимагатимуть жертв і осуду, оскільки тепер ви намагаєтеся відновити дух загиблого нападника, який тепер служить Лицарю Смерті, відомому як Darkreaver.",
},

[7641] = {
    en = "The Work of Grimand Elmore",
    T = "Робота Ґрімана Ельмора",
    D = "Бойовий кінь паладина — це лише тяглова тварина без належного обладунку. Обладунок для твого коня має бути не лише з найкращих матеріалів, але й, через особливі обставини, достатньо налаштованим на духовне царство.$B$BПерше діло, $N — давай виготовимо твій обладунок. У Гномському Окрузі Штормовію живе один із найкращих майстрів сучасності, Ґріман Ельмор. Його робота недешева, але ми шукаємо саме його якість. Поговори з ним.",
    O = "Поговори з Ґріманом Ельмором у Гномському Окрузі Штормовію.",
    P = "",
    C = "Привіт! Лорд Тінерозбійник заздалегідь повідомив мене, що ти підеш сюди, щоб побачитися зі мною. Я готовий зробити бардинг, який вам потрібен, але це буде недешево і не легко; Перш за все, давайте розкажемо про це відкрито.$B$BI скаже так багато, і Грейсон підтримає мене, коли я зроблю цю заяву... ніде в Азероті ви не знайдете кращого бардингу, ніж тут.",
},

[7642] = {
    en = "Collection of Goods",
    T = "Збір Матеріалів",
    D = "Для обладунку тобі знадобиться чотири речі: рунна тканина для підкладки, арканіти для пластин, Сльози Артаса для духовного налаштування та свята вода зі Стратгольму для духовного просочення. Насправді, п’ять речей... золото за мою роботу. Ця плата включає всю працю, а також виготовлені вручну сідло та стремена.$B$BКоли збереш усе це, я зможу завершити твій обладунок. А до того я можу почати дещо для тебе, поки ти збиратимеш потрібні речі.",
    O = "Принеси 40 Рунної Тканини, 6 Арканітів, 10 Сліз Артаса, 5 Флаконів Святої Води зі Стратгольму та 150 золотих до Ґрімана Ельмора в Гномському Окрузі Штормовію.",
    P = "Ах, $C. Я не зможу закінчити твій бардинг без речей, про які я згадав. Ви все зібрали?",
    C = "Це... ну це саме те, що мені було потрібно.  Ви досить винахідливий $C, чи не так?$B$BAll, тоді давайте закінчимо цю бардингу для вас!",
},

[7643] = {
    en = "Ancient Equine Spirit",
    T = "Стародавній Кінний Дух",
    D = "Твій обладунок потребує особливого благословення, від відповідного духа. У Кривих Могилах є такий дух — Стародавній Кінний Дух. Наразі його утримує зіпсований деревень, Тендріс Криводрев. Винеси суд над цією мерзенною істотою, $N.$B$BЗнай, що самої свободи недостатньо. Ти мусиш заспокоїти дух, перш ніж отримати його благословення. Для цього потрібен особливий корм для коней. Спершу вируш до Південнобережжя та поговори з Мередіт Карлсон про це... і готуйся до нових жертв.",
    O = "Дістань особливий корм для коней, який використовується для годування духовного коня. Мередіт Карлсон у Південнобережжі, здається, є джерелом такого корму.$B$BВируш до підземелля Кривих Могил у Фераласі та знищ Тендріса Криводрева. Це звільнить Стародавнього Кінного Духа. Нагодуй його особливим кормом, щоб заспокоїти дух. Нарешті, дай йому Арканітовий Обладунок, щоб він його благословив.",
    P = "Стародавній Конячий Дух дивиться на вас з очікуванням, наче чогось від вас хоче.",
    C = "Стародавній дух коней приймає пропозицію корму для коней, збагаченого манною, торкаючись контейнера, коли він допомагає собі спеціальний овес і зерно. Після того, як він трохи поїв, він дивиться на бардинг, яким ви володієте, і позиціонується так, ніби хоче, щоб ви поклали його йому на спину...",
},

[7644] = {
    en = "Blessed Arcanite Barding",
    T = "Благословенний Арканітовий Обладунок",
    D = "Коли обладунок лежить на спині Стародавнього Кінного Духа, він ледь помітно світиться. Повітря на мить наповнюється силою, а потім обладунок зникає зі спини коня і опиняється у твоїй торбі.$B$BЗдається, обладунок благословенний. Як наказав Лорд Тінеломець, тепер ти повинен повернутися з ним до нього в Штормовій.",
    O = "Поверни Благословенний Арканітовий Обладунок до Лорда Ґрейсона Тінеломця в Соборному Окрузі Штормовію.",
    P = "$N, ти повернувся! Чи вдалося вам успішно впоратися з Мерідет Карлсон і Тендріс Варпвуд?  Чесно кажучи, часом я не впевнений, хто з них є більшою загрозою...",
    C = "Ти далеко зайшов, друже. Ваш бардинг тепер належним чином підготовлений до останнього завдання.$B$BYou використовуватиме цей бардинг, щоб використовувати ваш зарядний пристрій, коли завдання викупу буде виконано. Однак перед цим вам доведеться подолати величезну боротьбу. Твій час наближається - ох!$B$BThere — це останній елемент, який потрібно зробити, перш ніж ми почнемо це, $N. Сподіваюся, ваша винахідливість не залишила вас після того, як ви зробили бардинг...",
},

[7645] = {
    en = "Ma$b$ba-Enriched Horse Feed",
    T = "Манно-Збагачений Кінний Корм",
    D = "Срібна Рука вважала мене БОЖЕВІЛЬНОЮ, коли я сказала, що можу зробити особливий корм для коней, який живитиме духовних коней. УСІ вважали мене божевільною! Що ж, тепер час розплати!$B$BЯ зроблю те, що тобі потрібно, ПАЛАДИНЕ... так званий ЧЕМПІОНЕ... але це тобі коштуватиме. Мені потрібні особливі бісквіти — Збагачені Манні Бісквіти, які продає лише Срібний Світанок — для цієї суміші. Я також ВИМАГАЮ, так, ВИМАГАЮ золото як компенсацію за страждання, які я пережила!$B$BПокажи мені ту жертву, про яку ти так хвалишся, ПАЛАДИНЕ.",
    O = "Дістань 20 Збагачених Манні Бісквітів — ключовий інгредієнт для створення Манно-Збагаченого Корму для Коней — для Мередіт Карлсон у Південнобережжі в Передгір’ях Гіллзбраду. Відомо, що Срібний Світанок є єдиним постачальником цих бісквітів.$B$BТакож тобі потрібно дати їй 50 золотих, щоб заспокоїти її роздратовані почуття.",
    P = "Так, тепер я довів, що ти неправий, чи не так? Я довів, що вони всі неправі! Я ВЕСЬ БУВ ПРАВИЙ!!!",
    C = "ТАК, ТЕПЕР ХТО - почекай - ти теж віддаєш мені золото? Не ти назвав мене божевільним (насправді вони назвали мене дурнем із фруктового торта)... все-таки ти готовий пожертвувати собою навіть за те, чого не робив?$B$BI... Я неправильно оцінив тебе, $N.  Якщо вам знадобиться більше корму для коней, приходьте до мене. Віддам безкоштовно. Дякую... шляхетний $C.$B$BI я збираюся залишити гроші - я не такий божевільний, щоб відмовлятися від стану.",
},

[7646] = {
    en = "The Divination Scryer",
    T = "Провидницький Візерунок",
    D = "Тепер ми повинні зібрати Провидницький Візерунок — це розпочне випробування, яке дозволить тобі викупити занепалого бойового коня. Твій візерунок, власне, майже готовий. Кадильниця для екзорцизму, використана в Терордолі, є каталізатором для нього, і я виготовлю відповідний корпус для пристрою.$B$BОстанні потрібні компоненти — це два діаманти. Вони повинні бути такими ж контрастними за блиском, як і за призначенням — Азеротський і Незайманий Чорний. Ці два стануть маяком, за допомогою якого візерунок проб’є тіні!",
    O = "Принеси Азеротський Діамант і Незайманий Чорний Діамант до Лорда Ґрейсона Тінеломця в Соборному Окрузі Штормовію.",
    P = "Ви зайшли так далеко, $N. Ваш останній акт жертвоприношення мирськими речами стане основою для одного з ваших найбільших досягнень. Я відчуваю це самою фіброю свого єства!",
    C = "Це чудові екземпляри, $N – останні частини вже на місці. Нарешті ваш час настав!$B$BIn глибини Великого Осуарію Шоломантії — це скелети багатьох істот. Серед них – колись благородний зарядний пристрій. Випорожнена душа цього зарядного пристрою тепер служить конем для лицаря смерті Темнокрадача. Саме з ним ви зіткнетеся, і саме цього коня ви винесете суд. Тільки ти, $N, можеш спокутувати його душу і врятувати від мук рабства.",
},

[7647] = {
    en = "Judgment and Redemption",
    T = "Суд і Викуплення",
    D = "Візьми цю торбу — в ній предмети, які тобі знадобляться для твого завдання.$B$BВикористай Провидницький Візерунок у самому серці підвалу Великої Осарії, щоб викликати проклятих духів, яких ти повинен судити. Мудро використовуй свої суди під час цього випробування — вони виявляться потужнішими, ніж ти думаєш. Після духів з’явиться лицар смерті; переможи його та поверни втрачену душу бойового коня. Тільки тоді, $N, ти зможеш викупити його та надіти свій обладунок на нового скакуна!$B$BУдачі!",
    O = "Використай Провидницький Візерунок у самому серці підвалу Великої Осарії в Схоластії. Це викличе духів, яких ти повинен судити. Перемігши цих духів, ти викличеш Лицаря Смерті Темножнеця. Переможи його та поверни втрачену душу занепалого бойового коня.$B$BДай Врятовану Душу Бойового Коня та Благословенний Зачарований Обладунок Занепалому Бойовому Коню Темножнеця.",
    P = "Дух загиблого зарядника дивиться на вас скорботним поглядом. Сумні, майже порожні очі дивляться на вас так, наче втрачено будь-яку надію.",
    C = "Проблиск життя, якого довго не було від бідолашного звіра, сяє в його очах, коли ви повертаєте йому його засуджену душу. Ви відчуваєте святий приплив енергії навколо себе, коли кладете бардинг на спину, вважаючи зарядний пристрій погашеним. Зарядний пристрій торкається вашої руки, коли тягарі минулого знімаються зі звіра. Тепер ви відчуваєте, ніби можете попросити цього звіра стати вашим конем, якщо виникне потреба.$B$BYou заволоділи вашим епічним зарядним пристроєм, $C! Щиро вітаю!",
},

[7648] = {
    en = "Grimand's Finest Work",
    T = "Найкраща Робота Ґрімана",
    D = "<Ґріман витирає піт із чола, сяючи від гордості.>$B$BОсь ти де, мій друже. Це одна з моїх найкращих робіт — така ж добра, як обладунок, який я особисто виготовив для Лорда Тінеломця, коли він здобував свого бойового коня. Дякую тобі за довіру, що дозволила мені зробити для тебе найкраще.$B$BБез сумніву, Ґрейсон захоче сам побачити цю роботу. Віднеси свій обладунок до нього та передай мою подяку за його чесний бізнес.",
    O = "Віднеси Арканітовий Обладунок до Лорда Ґрейсона Тінеломця в Соборному Окрузі Штормовію для огляду.",
    P = "Ти чудово просуваєшся, $N. Після того, як ви зробите бардинг, ви будете на шляху до наступного завдання.",
    C = "Це найбільш вражаюча робота. Здається, у міру того, як Гріманд стає старшим, його майстерність продовжує вдосконалюватися. Це справжнє досягнення, коли його робота вже була однією з найкращих, які ви можете знайти, коли він зробив мій бардинг у той час.$B$BWhile цей бардинг був би чудовим доповненням до будь-якого звичайного коня, ми не маємо справу з таким приземленим звіром. Вам знадобиться, щоб цей бардинг був благословенний відповідним джерелом, щоб він гідно ставився на зарядний пристрій $C. Я буду тримати його для вас до тих пір.",
},

