[7701] = {
    en = "WANTED: Overseer Maltorius",
    T = "РОЗШУК: Наглядач Малторій",
    D = "За наказом його величності, наглядача Ойлфіста, зрадника Братства Торію, а нині новопризначеного командира загону Темного Заліза в Ямі Шлаків у Котлі, наглядача Малторія, слід убити, а його голову принести як доказ виконання завдання.$B$BЗвернися до капітана-розвідника Лоло Довгостріла за нагородою за цю голову.",
    O = "Глибоко в Ямі Шлаків у Котлі, що в Палаючому Степовищі, ти знайдеш зрадливого гнома Темного Заліза, наглядача Малторія.$B$BУбий наглядача Малторія та візьми його голову. Поверни голову до капітана-розвідника Лоло Довгостріла в Палаючому Степовищі за нагородою.",
    P = "Хіба не можеш зрозуміти, що я пухнастий? Чого *hic* ти хочеш? *хік*",
    C = "Я ніколи не подумаю, що знову подивлюсь на цю потворну чашку!$B$BHe Зазвичай виглядає краще без прикріпленого до нього листа.$B$BHere Ваша нагорода *hic*, $R.",
},

[7703] = {
    en = "Unfinished Gordok Business",
    T = "Незавершена Справа Ґордоків",
    D = "Тепер ти король, тож, може, тобі вдасться повернути цінний артефакт Ґордоків від моторошного ельфа, що називає себе Принцем! Король до тебе зазнав невдачі, як і всі інші королі після того, як Тортелдрін — той моторошний ельф — вкрав його в давнього короля Ґордоків!$B$BАртефакт зветься Рукавиця Сили Ґордоків. Давні історії кажуть, що лише справжній король Ґордоків може її повернути. Також у тих історіях сказано, що моторошний ельф досі десь тут — знайди його, і рукавиця стане твоєю могутньою зброєю назавжди! Яр, я покажу тобі!",
    O = "Знайди Рукавицю Сили Ґордоків і поверни її до капітана Кромкраша в Кривих Могилах.$B$BЗа словами Кромкраша, «давня історія» каже, що Тортелдрін — «моторошний» ельф, який називав себе принцем — вкрав її в одного з королів Ґордоків.",
    P = "Ха, ти не знайшов, бос? Можливо, стара історія погана історія... важко повірити, що моторошний ельф може вкрасти короля Гордока!",
    C = "Ого... ти справжня $gking:королева;! Я не думаю, що ніколи в житті бачу цю рукавичку! Схоже, у нього більше не залишилося жодного моджо... можливо, той моторошний ельф намагається зруйнувати рукавицю. Ну, я кажу йому «ХАР-ХАР»!$B$BLook — цей знак на рукавичці старий старий СТАРИй магічний знак, кажуть, старший за та Гордока. Що ж, як капітан da Gordok, ми всі знову і знову вчимося одному — як оживити позначку та повернути силу рукавичці!$B$BI зроби це за тебе, $gking:королева;! Ось візьміть рукавичку і правіть НАЗАВЖДИ!",
},

[7704] = {
    en = "Look at the Size of It!",
    T = "Поглянь, Якого Розміру!",
    D = "Ну й ну... Хіба це не сюрприз. Покоївка мала величезну оздоблену подушку, і тепер вона твоя. Евоніс Сутсмокер точно захоче дістати свої брудні рученята до цього предмета. Віднеси її до неї та подивися, чи запропонує вона тобі щось смачненьке за твої старання.",
    O = "Віднеси Подушку Покоївки Піллаклінчер до Евоніс Сутсмокер у Палаючому Степовищі.",
    P = "",
    C = "Це краще, ніж я міг подумати! Чарівна подушка покоївки — моя! Тобі краще вірити, що ти отримаєш гарну винагороду за це досягнення, $N!",
},

[7721] = {
    en = "Fuel for the Zapping",
    T = "Паливо для Зменшення",
    D = "Якщо я, попри власну розсудливість, залишуся керувати інженерною крамницею вздовж Забутого Узбережжя, мені доведеться розібратися з цими надокучливими елементалями. Прокляття неконтрольованої стихійної сили, кажу я!$B$BНа щастя для мене, а тепер і для тебе, мій сподіваний агенте-провокаторе, елементалі є ідеальним джерелом сирої енергії для вдосконалення мого Ультра-Зменшувача — дай їм жару, кажу я! Але при цьому обов’язково збережи для мене ядра водяних елементалів!",
    O = "Збери 10 Ядер Водяних Елементалів із Морських Елементалів і Морських Бризок уздовж Забутого Узбережжя Фераласу та принеси їх до Зорбіна Фанзела, що біля причалу там.",
    P = "Хоча я міг би втомити вас технічними деталями утиліти, що стоїть за елементарними ядрами, натомість я спокуслю вас виконати це важливе завдання, пропонуючи цінні монети та призи за це.  Справді, ти закінчив?",
    C = "Scrumdillyriff!  Ці ядра дозволять мені працювати деякий час.  Додайте до цього те, що на узбережжі тепер менше елементалів, і я, можливо, більше не буду плакати до сну від перспективи створити магазин у, можливо, найгіршому місці, яке тільки можна уявити!$B$BThank вам, $N, за ваші зусилля від мого імені.  Хоча це, безумовно, обтяжує мене фінансово, дозвольте мені висловити вам подяку, яку ви, можливо, зрозумієте та оціните... бабло!",
},

[7722] = {
    en = "What the Flux?",
    T = "Що за Потік?",
    D = "Коли той виродок Малторій покинув наш клан, він забрав із собою щось цінніше за чистий магічний кристал: наш рецепт вогняного потоку! Б’юся об заклад, що цей рецепт був частиною угоди для його нового підвищення серед Темного Заліза.$B$BЯ хочу, щоб ти повернув наші секретні плани, $N. Я впевнений, вони десь біля Малторія, глибоко в Ямі Шлаків.",
    O = "Десь у Ямі Шлаків у Котлі ти знайдеш Секретні Плани: Вогняний Потік, які вкрав наглядач Малторій. Знайди ці плани та поверни їх до Майстра Коваля Бурніната в Палаючому Степовищі.",
    P = "Ви знайшли плани?",
    C = "Сподіваюся, ти теж вдарив йому зуби, $N. Рагнарос знає, він це заслужив.$B$BNow ми можемо приступати до справи.",
},

[7723] = {
    en = "Curse These Fat Fingers",
    T = "Прокляття Цих Товстих Пальців",
    D = "На жаль, я вже не можу так гамселити, як раніше, через цю проблему з товстими пальцями. Бачиш, клімат тут у поєднанні з низьким тиском повітря змушує мої пальці розбухати. Вони наче величезні телсамарські криваві ковбаски, їй-богу...$B$BТобі доведеться виконувати мої доручення та все таке.$B$BПерше в моєму списку: розтрощити до чортів важких бойових големів у Степовищі. Берися до роботи.",
    O = "Гансель Важкорук хоче, щоб ти знищив 20 Важких Бойових Големів.$B$BВажкі Бойові Големи блукають околицями Котла в Палаючому Степовищі. Коли знищиш достатньо, повернися до Ганселя в Палаючому Степовищі.",
    P = "Ви їх товкли?",
    C = "Ти хороший хлопець, так. Я маю маленький подарунок для ваших проблем.",
},

[7724] = {
    en = "Fiery Menace!",
    T = "Вогняна Загроза!",
    D = "Хіба не знаєш, щоразу, коли старий Гансель хоче хвилинку розслабитися та поміркувати про своє життя, начальство дає йому нову роботу.$B$BМені треба думати, ну ж бо! Ти розумієш, що я кажу? Ну. Ж бо.$B$BОтже, ці великі лавові павуки влаштовують якийсь переполох. Ойлфіст каже, що вони вистрілюють вогонь із... гм, ну, в будь-якому разі, це лякає дітей.$B$BГадаю, ми мусимо їх убити. Точніше, ти муситимеш їх убити.",
    O = "Гансель Важкорук хоче, щоб ти знищив 20 Великих Лавових Павуків у Палаючому Степовищі. Великих Лавових Павуків можна знайти на плато та в лавових басейнах Палаючого Степовища.$B$BПовернися до Ганселя Важкорука в Палаючому Степовищі, коли знищиш достатньо Великих Лавових Павуків.",
    P = "Чи мав він рацію? Це виходить з їхніх огузків?",
    C = "<Гензель чхає.>$B$BI думаю, що я застуджуся. До біса цей холодний клімат!",
},

[7725] = {
    en = "Again With the Zapped Giants",
    T = "Знов із Зменшеними Гігантами",
    D = "Я знаю, ти вже збирав для мене залишки... але якщо тобі закортить повторити цю веселу розвагу, я завжди можу використати ще трохи залишків.$B$BХоча я не можу запропонувати таку ж щедру винагороду знову, я із задоволенням розкажу всім своїм гоблінським друзям із вухами про твої заслуги.$B$BПовір мені, $g пане : пані;, коли я кажу, що в цих гоблінів дуже великі вуха.",
    O = "Використай Ультра-Зменшувач Зорбіна, щоб зменшити будь-якого гіганта в Фераласі до керованих розмірів. Принеси 10 Залишків Мініатюризації, знайдених на зменшених версіях цих гігантів, до Зорбіна Фанзела на причалі Забутого Узбережжя, Фералас.",
    P = "Ах, плоди досліджень і використання у вигляді солодкого, солодкого залишку.  Ну, тобто я не смакую цього чи нічого, коли вивчаю це.$B$BMuch.",
    C = "Неймовірно фантастично, $N!  Ви знову підійшли до мене, і я вам за це дякую.$B$BThank вам!$B$BWhile ви можете виявити, що ця монета трохи менша, ніж ви звикли, будьте впевнені, що ваші великі вчинки на ниві гобліну відлунюють у залах влади в картелі Steamwheedle.  Якщо тобі потрібно ще щось зробити, то неодмінно поговори зі мною!",
},

[7726] = {
    en = "Refuel for the Zapping",
    T = "Поповнення Палива для Зменшення",
    D = "Ще роботи, кажеш? Невже моє героїчне завдання зі збору шматочків слизу з елементальних істот не втамувало твою жагу до пригод? Може, ще трохи того ж самого марно спробує заповнити бездонну криницю твоїх пошуків...$B$BГаразд, без мелодрами, мені дійсно потрібні ще ядра водяних елементалів. Я відчайдушно намагаюся налагодити тут крамницю, тож нагороди будуть не такими великими... але я обіцяю, що розкажу всім, хто мене почує, як ти мені допомагав. Довіряй мені — я знаю людей у Картелі!",
    O = "Збери 6 Ядер Водяних Елементалів із Морських Елементалів і Морських Бризок уздовж Забутого Узбережжя Фераласу та принеси їх до Зорбіна Фанзела, що біля причалу там.",
    P = "Вам вдалося знайти потрібні мені елементарні ядра?",
    C = "На найвищому рівні, $N, на найвищому рівні!  Хоча монета, яку я вам даю, може бути не найбільшою, яку ви коли-небудь отримаєте за таку роботу, будьте впевнені, що мої товариші з картелю Steamwheedle почують про ваші зусилля!$B$BIf ви шукаєте щось інше, тоді дайте мені знати.  Я завжди можу використовувати більше елементарних ядер тощо.",
},

[7727] = {
    en = "Incendosaurs? Whateverosaur is More Like It",
    T = "Інцендозаври? Скоріше Якийсьзаври",
    D = "Мозолі, $g хлопче : дівчино;. Мої мозолі мають свої мозолі. Як я можу щось убивати, коли мої ноги в такому безладі? Ось чому ти мені допоможеш.$B$BСкрендж і Бурнінат доручили мені знищити цих істот, щоб вони могли відправити експедиційні команди до лавових басейнів Ями Шлаків для досліджень. Нібито якісь інцендозаври чи ще якась нісенітниця там створюють купу проблем. А тепер гайда, і не повертайся, поки популяція інцендозаврів не зникне.",
    O = "Гансель Важкорук хоче, щоб ти знищив 20 Інцендозаврів.$B$BІнцендозаврів можна знайти в лавових басейнах усередині Ями Шлаків. Яма Шлаків розташована в Котлі Палаючого Степовища.$B$BПовернися до Ганселя Важкорука в Палаючому Степовищі, коли знищиш достатньо Інцендозаврів.",
    P = "<Гензель завзято натирає свої шишки.>$B$BDon Не просто стояти, візьміть трохи олії та луффу та почистіть ці шишки.$B$BYe у вас немає луффи? Ну тоді! Можливо, настав час послати вас знайти луффу?%$B$BHey, куди ви йдете?",
    C = "Ой, у мене болять ноги.$B$BI я подумав, оскільки у вас не було луффи...",
},

[7728] = {
    en = "STOLEN: Smithing Tuyere and Lookout's Spyglass",
    T = "ВКРАДЕНО: Ковальський Сопел і Підзорна Труба Розвідника",
    D = "Наступні предмети були вкрадені:$B$B*Один Сопел Темного Заліза.$B$B*Одна Підзорна Труба Розвідника.$B$BПропонується нагорода тим, хто знайде та поверне ці вкрадені предмети.$B$BБратство Торію впевнене, що ці предмети вкрали безпринципні та заздрісні гноми Темного Заліза, що населяють Палаюче Степовище.$B$BЗгадана підзорна труба була чудовим інструментом для розвідників, а сопел — незамінним ковальським знаряддям.$B$BЯкщо знайдеш ці зниклі предмети, поверни їх до Скренджа.",
    O = "Знайди та поверни Ковальський Сопел і Підзорну Трубу Розвідника до Майстра Завдань Скренджа в Палаючому Степовищі.$B$BЄдина інформація про ці предмети така: їх точно вкрали гноми Темного Заліза. Ковальський Сопел — це ковальський інструмент, що використовується ковалями, а Підзорна Труба Розвідника — незамінний інструмент для спостереження розвідниками.",
    P = "Якщо ти тут заради винагороди, тобі доведеться віддати мені вкрадене.",
    C = "Фантастична робота! Тепер ваша винагорода.",
},

[7729] = {
    en = "JOB OPPORTUNITY: Culling the Competition",
    T = "МОЖЛИВІСТЬ РОБОТИ: Прорідження Конкуренції",
    D = "Майстер Завдань Скрендж шукає кількох добрих чоловіків і жінок, щоб допомогти «прорідити конкуренцію» в Палаючому Степовищі.$B$BЯкщо ти зацікавлений у цій посаді, вируш до Палаючого Степовища та знищуй кожного Майстра Завдань Темного Заліза та Работоргівця Темного Заліза, якого побачиш.$B$BПовернися до Майстра Завдань Скренджа, коли твій одяг буде достатньо закривавлений.$B$BТи знатимеш, коли він достатньо закривавлений, тож не питай.",
    O = "Убий 15 Майстрів Завдань Темного Заліза та 15 Работоргівців Темного Заліза. Повернися до Майстра Завдань Скренджа в Палаючому Степовищі, коли виконаєш це завдання.",
    P = "Нам потрібно буде зважити вас з одягом і без нього, щоб переконатися.",
    C = "15,9 фунтів! Це може бути новий рекорд за вагою крові та кишківника на одязі! Вітаємо, $C!",
},

[7730] = {
    en = "Zukk'ash Infestation",
    T = "Зараження Зукк’аш",
    D = "З того, що нам вдалося розвідати, ми вважаємо, що ворог на південь від гнолів — це комахоподібна раса. Відверто кажучи, неважливо, чи вони розумні. Якщо вони змушують гнолів божеволіти проти нас, то вони становлять таку ж загрозу — якщо не більшу — як і гноли.$B$BПробийся глибоко туди, де живуть ці комахи Зукк’аш; це місце відоме як Глибокий Звив. Проріди їхні лави та доповідай мені, що знайдеш, принісши їхні панцирі як доказ твоєї роботи.",
    O = "Принеси 20 Панцирів Зукк’аш до Хадокена Стрімрайдера в таборі Моджахе, Фералас.",
    P = "Як проходить полювання, $N?  Ви тут, щоб повідомити про свій успіх?",
    C = "Молодець, $C.  Хоча масштабність присутності Зукк'аша не буде перешкоджати нічим іншим, ніж повномасштабне вторгнення, ви виграли у нас трохи часу, щоб ми могли розробити правильну стратегію.$B$BI обов’язково проаналізує ці панцири; нам потрібно буде дізнатися все про них, перш ніж мати справу з тим, що, на жаль, перетворилося на набагато більшу проблему, ніж ми очікували.",
},

[7731] = {
    en = "Stinglasher",
    T = "Жалоріз",
    D = "Під час розвідки Глибокого Звиву один із наших розвідників повідомив, що бачив гігантську комаху — набагато більшу за інших комах, яких помітили — що блукає викривленою місцевістю. Вона не лише більша, але й, здається, виділяє якусь ауру, якої немає в інших комах. Ми дали їй ім’я — Жалоріз.$B$BНутрощі цієї істоти були б неоціненними для вивчення, щоб знайти найкращий спосіб боротьби з цією новою загрозою. Виріж її секреторні залози та негайно принеси їх мені!",
    O = "Переможи Жалоріза в Глибокому Звиві, принісши його залози до Хадокена Стрімрайдера в таборі Моджахе, Фералас.",
    P = "Вам уже вдалося збити Стінґлешера?",
    C = "Вражаюче, $C... дуже вражаюче!  Якщо Стінглешер справді одна з їхніх найсильніших істот, вивчення звіра з часом виявиться дуже цінним.  Тепер я зобов’язаний переконатися, що ми захищаємось достатньо довго, щоб скористатися цим.$B$BPlease прийми цю винагороду монетами на знак подяки всього табору, $N.  молодець",
},

[7732] = {
    en = "Zukk'ash Report",
    T = "Звіт про Зукк’аш",
    D = "Ти двічі добре впорався із загрозою, яку становлять комахи Зукк’аш для табору Моджахе. Але ця загроза далека від завершення, і я хочу попросити тебе про останнє завдання від імені Орди.$B$BЦе документ, що детально описує всю інформацію, яку ми дізналися про цих комах Зукк’аш. Я хочу, щоб ти доставив його до Зілзібіна Драмлора в Провулку Оргріммара. Він експерт із чужорідних створінь, як ці; сподіваюся, він зможе щось зробити з цими знаннями.",
    O = "Достав Звіт про Зукк’аш із табору Моджахе до Зілзібіна Драмлора. Він мешкає в Провулку Оргріммара.",
    P = "Вітаю, друже... ти виглядаєш так, наче у тебе термінові справи.  Я можу вам чимось допомогти?",
    C = "Ах, я цього чекав.  Ці істоти, з якими ви зіткнулися... це давня загроза, яку Орда продовжує ігнорувати.  Хадокен вчинив мудро, принісши це — і вас — мені.$B$BThe Зукк'аш — це не що інше, як істоти, які називаються силітідами.  Дехто міг би подумати, що вони безглузді клопоти, але дозвольте запевнити вас: вони є набагато, набагато гіршою загрозою, ніж будь-що, що може створити Альянс.$B$BIf ви готові й достатньо сильні, мені знадобиться ваша допомога, щоб висвітлити цю загрозу.",
},

[7733] = {
    en = "Improved Quality",
    T = "Покращена Якість",
    D = "У мене є інформація про ще КРАЩЕ джерело шкур, якщо це взагалі можливо повірити! У північних частинах Фераласу — глибоко в Твердині Лютого Шраму — є ще одна зграя єті. Вони набагато сильніші за тих, із якими ти мав справу раніше, тож якщо ти готовий до більшого виклику, краще будь напоготові!$B$BЯ щедро винагороджу тебе за пачку з десяти їхніх шкур; принеси їх мені сюди, і ми завершимо нашу угоду.",
    O = "Принеси 10 Шкур Єті Лютого Шраму до Пратта МакҐруббена у Фортеці Пір’яного Місяця, Фералас.",
    P = "Якщо ці шкури єті від Шраму люті схожі за якістю, ніж їхні аналоги від Шраму дикого, вони цілком можуть бути такими ж стійкими, як торій!$B$BImagine це!",
    C = "Відмінно, відмінно!  Вони працюватимуть неймовірно добре – я вже можу сказати, що їх буде набагато складніше, якщо їх правильно вилікувати.$B$BThanks знову за вашу допомогу $N.  Ось, будь ласка, візьміть одне з моїх останніх творінь.",
},

[7734] = {
    en = "Improved Quality",
    T = "Покращена Якість",
    D = "У мене є інформація про ще КРАЩЕ джерело шкур, якщо це взагалі можливо повірити! У північних частинах Фераласу — глибоко в Твердині Лютого Шраму — є ще одна зграя єті. Вони набагато сильніші за тих, із якими ти мав справу раніше, тож якщо ти готовий до більшого виклику, краще будь напоготові!$B$BЯ щедро винагороджу тебе за пачку з десяти їхніх шкур; принеси їх мені сюди, і ми завершимо нашу угоду.",
    O = "Принеси 10 Шкур Єті Лютого Шраму до Джанґдора Стрімрайдера в таборі Моджахе, Фералас.",
    P = "Якщо ці шкури єті від Шраму люті схожі за якістю, ніж їхні аналоги від Шраму дикого, вони цілком можуть бути такими ж стійкими, як торій!$B$BImagine це!",
    C = "Відмінно, відмінно!  Вони працюватимуть неймовірно добре – я вже можу сказати, що їх буде набагато складніше, якщо їх правильно вилікувати.$B$BThanks ще раз за вашу допомогу, $N.  Ось, будь ласка, візьміть одне з моїх останніх творінь.",
},

[7735] = {
