[7828] = {
    en = "Stalking the Stalkers",
    T = "Полювання на мисливців",
    D = "Багато хоробрих тролів загинуло в суворих диких землях Внутрішніх Земель, $r. Вовки Срібної Гриви — одна з найбільших загроз для наших мисливців. Вони чатують, ховаючись серед кущів і ландшафту, а потім нападають, коли з’являється нагода.$B$BТака лють не залишиться безкарною!$B$BТи мусиш думати, як Срібна Грива. Полюй на мисливців! Знищ їх усіх!",
    O = "Мисливець Маркор у селищі Ревантуск у Внутрішніх Землях хоче, щоб ти убив 15 Срібногривих Слідопитів і 15 Срібногривих Витіячів. Повернися до нього, коли завдання буде виконано.$B$BМаркор згадав, що вовки ховаються в диких землях Внутрішніх Земель.",
    P = "Покажіть їм могутність Revantusk!",
    C = "Добре виконана робота, $R. Revantusk дякує вам за ваш внесок.",
},

[7829] = {
