[7902] = {
    en = "Vibrant Plumes",
    T = "Яскраві Пера",
    D = "",
    O = "",
    P = "Уява людини — неймовірна річ. Завдяки цьому найменший пагорб може здаватися найбільшою горою. Це може зробити найнешкідливішу тінь від жахливого кошмару!$B$BWe на виставці Darkmoon Faire нехай розквітне уява наших відвідувачів! Але щоб розвинути їхню уяву... інколи нам доводиться вдаватися до хитрощів.$B$BI потрібні яскраві шлейфи для одного з моїх атракціонів. Ви можете отримати їх від птахів з більш небезпечних районів Азероту. Принесіть мені шлейфи, і багато квитків будуть у вас!",
    C = "Ах, шлейфи! Вони дивовижні, вам не здається! Такою красою було б легко розпалити уяву!$B$BYou займайтеся такою благодійністю, $N. Посмішка на обличчях наших відвідувачів, коли вони бачать шоу, — це справді велика плата, але, будь ласка, візьміть і ці квитки.",
},

[7903] = {
    en = "Evil Bat Eyes",
    T = "Злі Очі Кажанів",
    D = "",
    O = "",
    P = "Ви коли-небудь блукали печерою пізно ввечері в пошуках пригод? Ви робите? справді? Ну, тоді ви бачили моторошні очі кажанів, які дивилися на вас з висоти, чекаючи, поки ви ослабите свою пильність, щоб вони могли висмоктати вашу кров!$B$BScary подумала, чи не так? звичайно! Безперечно, очі кажана страшні!$B$BWill ти приніс мені злі очі кажана, $N? Я хочу їх для... чогось, що я проектую. Щось страшне.$B$BYou можна отримати їх від кажанів зі Східних Чумних земель.",
    C = "Чудово!  У вас є очі!  Я сподіваюся, що полювання на цих кажанів налякало вас, тому що якщо воно налякало такого сміливого $C, як ви, то ці очі точно налякають наших відвідувачів Faire.$B$BTake ці квитки, $N, і дякую за вашу службу.",
},

