[8042] = {
    en = "Strength of Mount Mugamba",
    T = "Сила Гори Мугамба",
    D = "",
    O = "",
    P = "Приємно бачити вас здоровим, $n. Славетні битви, які ви розпочали, впливають на все життя на цій планеті. Хаккар ніколи не повинен залишати межі Зул'Ґуруба, оскільки світ неодмінно завалиться від його жахливого голоду.$B$BGive я, ваш талісман, і я посилю його силу. Використовуйте силу Мугамби, щоб покарати наших ворогів!",
    C = "Наші шляхи знову перетнуться, $c.",
},

[8043] = {
    en = "Strength of Mount Mugamba",
    T = "Сила Гори Мугамба",
    D = "",
    O = "",
    P = "Майстер $n, ти повертаєшся! Молтор надіслав королю інформацію про ваші вчинки. Твоє ім'я знають навіть у південних морях. Можливо, одного дня ти станеш легендарним $c - історією на віки.$B$BGive мені твій талісман, щоб я міг ще раз посилити його силу.",
    C = "Використовуйте свою нову силу, щоб знищити Гурубаші!",
},

[8044] = {
    en = "The Rage of Mount Mugamba",
    T = "Лють Мугамба",
    D = "",
    O = "",
    P = "Король Растахан передає привіт, Майстер $n. Такої честі ніколи не було надано нікому за межами племені Зандалар.$B$B<Джін'рокх вклоняється.>$B$BGive мені твій талісман, щоб я міг його ще раз покращити. Знайте, що Rage of Mugamba тепер нерозривно пов’язана з вашою душею.",
    C = "Зул'джин позаздрив би, $c. Іди вперед і перемагай!",
},

[8045] = {
