[8053] = {
    en = "Paragons of Power: The Freethinker's Armguards",
    T = "Зразки Сили: Наручі Вільнодумця",
    D = "Ти — язичник. Язичники мають місце в племені. Язичники — це вільнодумці Зандалару. Вільнодумці не бояться гніту. Вільнодумці вмирають за те, у що вірять. Ми знаємо, що ти помреш за свої переконання. Це заслуговує на наше визнання. Це дає тобі шанс довести свою цінність.$B$BНам потрібні Зразки Сили. Вирушай до Зул’Ґуруба. Убий прислужників Гаккара. Повертайся, коли матимеш те, що мені потрібно. Отримай перше бойове спорядження вільнодумця Зандалару.$B$BІди.",
    O = "Принесіть Джин’року Руйнівнику Первісні Наручники Гаккарі. Ви також повинні мати репутацію не нижче Дружньої з племенем Зандалар.$B$BДжин’рок Руйнівник знаходиться на Острові Йоджамба, Терниста Долина.",
    P = "Ви повернулися?  У вас є зразки сили?  Ти марнуєш мій час?$B$BI Сподіваюся, ні, погане.",
    C = "Ви робите багато для нашої честі.  Ваші руки стікають кров'ю прихильників Хаккара.  Ви друг племені.$B$BWear ці наручі.  Вони обереги вільнодумця.  Ось що я маю на увазі щодо справжньої влади.",
},

[8054] = {
    en = "Paragons of Power: The Freethinker's Belt",
    T = "Зразки Сили: Пояс Вільнодумця",
    D = "Твої переконання чужі нам, язичнику. Стародавні Зандалари колись вважалися єретиками. Це було за часів могутності Імперії Ґурубаші. Язичники наважилися кинути виклик жерцям Гаккара. Тоді язичників полювали і вбивали як шкідників. Але ті язичники ніколи не вагалися у своїй боротьбі проти Бога Крові. Ми вшановуємо ціну, яку вони заплатили. Вони — вільнодумці.$B$BЗнищ прислужників Гаккара в Зул’Ґурубі. Принеси мені Зразки Сили, які я шукаю. Успіх буде щедро винагороджений.$B$BІди.",
    O = "Принесіть Джин’року Руйнівнику Первісну Накидку Гаккарі. Ви також повинні мати репутацію не нижче Шанованої з племенем Зандалар.$B$BДжин’рок Руйнівник знаходиться на Острові Йоджамба, Терниста Долина.",
    P = "Ваша присутність означає перемогу?  У вас є Paragons?  Ви капаєте в останки своїх ворогів?",
    C = "Ваша честь забезпечена в племені.  Ви заявляєте про багатьох смертей у Зул'Ґурубі.  Вороги падають перед вашими переконаннями.  Вороги падають перед вашою силою.$B$BThis — це пояс вільнодумця.  Це символ честі.  Це потужний моджо.  Тепер воно ваше.",
},

[8055] = {
    en = "Paragons of Power: The Freethinker's Breastplate",
    T = "Зразки Сили: Нагрудник Вільнодумця",
    D = "Бойове спорядження дає тобі силу в племені. Вільнодумці шануються таким чином. Вони — фанатики. Вони наповнюють свої нагрудники могутньою магією. Якщо їхні переконання похитнуться перед ворогом, їхній нагрудник — ні.$B$BТи мусиш бути шанованим серед нас, щоб володіти таким нагрудником. Вирушай до Зул’Ґуруба. Візьми Зразки Сили, які мені потрібні. Візьми їх найболючіше у дурнів усередині. Принеси їх мені. Доведи свою цінність як вільнодумець раз і назавжди.",
    O = "Принесіть Джин’року Руйнівнику Первісний Табард Гаккарі. Ви також повинні мати репутацію не нижче Поважної з племенем Зандалар.$B$BДжин’рок Руйнівник знаходиться на Острові Йоджамба, Терниста Долина.",
    P = "У вас є Paragons?  У них є моджо всередині них.  Ми повинні їх мати.  Ви нам допоможете.",
    C = "Ви зробили те, що мало хто міг.  Ви поставили прихильників Хаккара на коліна.  Ви показали їм, на що здатний вільнодумець.  Ви показали нам, як єретика можна шанувати в племені.  У вас більше, ніж справжня влада.  Ти справжня сила.$B$BTake нагрудник, вільнодумець.  Розбийте тих, хто протистоїть вам.",
},

[8056] = {
    en = "Paragons of Power: The Augur's Bracers",
    T = "Зразки Сили: Наручі Віщуна",
    D = "Віщуни нашого племені шануються за їхні божественні дари передбачення, брате. Вони не відьмаки; вони проводять свій час, кидаючи кістки чи читаючи листя для осяяння — не проклинаючи людей. Як шаман, ти вже знаєш дещо про силу віщування; ми, Зандалари, цінуємо мудрість, яку вони дарують племені.$B$BПринеси мені дари Зразків Сили зсередини Зул’Ґуруба і доведи свою цінність для нас. Зроби це, і я дам тобі наручі, які наші віщуни цінують понад усе!",
    O = "Принесіть Майвікі з Зулдазара Первісні Наручі Гаккарі. Ви також повинні мати репутацію не нижче Дружньої з племенем Зандалар.$B$BМайвікі з Зулдазара знаходиться на Острові Йоджамба, Терниста Долина.",
    P = "Отримав потрібні мені зразки сили від Зул'Гуруба?  Ці наручі варті будь-яких зусиль, які вам доведеться докласти!",
    C = "Здається, у вас є трохи зандаларського авгура.  Ми знаємо про справи, які ти робиш у Зул'Ґурубі від нашого імені, мон.  Ці Взірці Сили зроблять довгий шлях, щоб допомогти племені Зандалар — племені, я можу додати, до якого ви можете звернутися як до друзів.  Візьми ці наручі, $N; я заробив їх, а потім ще трохи!",
},

[8057] = {
    en = "Paragons of Power: The Haruspex's Bracers",
    T = "Зразки Сили: Наручі Гаруспіка",
    D = "Гаруспік — ключовий член нашого племені; тобі варто прислухатися до їхніх пророцтв. Через спілкування з тваринами та жертвоприношення духам, коли це потрібно, вони дають нам божественне наставництво. У минулі часи мудрість і осяяння гаруспіків давали нам перевагу у війнах проти розколотих племен Ґурубаші.$B$BПринеси мені дари Зразків Сили зсередини Зул’Ґуруба і доведи свою цінність для нас. Зроби це, і я дам тобі наручі, які прагне кожен гаруспік Зандалару.",
    O = "Принесіть Майвікі з Зулдазара Первісну Опору Гаккарі. Ви також повинні мати репутацію не нижче Дружньої з племенем Зандалар.$B$BМайвікі з Зулдазара знаходиться на Острові Йоджамба, Терниста Долина.",
    P = "Ви отримали зразки сили від Зул'Гуруба?  Ці браслети варті зусиль, $N.  Повір мені, чувак!",
    C = "Ах, я відчуваю силу, що виходить від цих Взірців Сили, $N.  Я виявився кимось, кого ми в племені можемо назвати ",
},

[8058] = {
    en = "Paragons of Power: The Vindicator's Armguards",
    T = "Зразки Сили: Наручі Месника",
    D = "Помста — це сила. Зандаларський месник — це втілення такої сили. У племені багато ворогів. Месник вершить відплату над ними. Жоден злочин проти нас не залишається безкарним. Месник виконує це покарання. Наші вороги бояться нашої помсти. І повинні. Вони боятимуться вічно.$B$BСтань одним із наших месників. Шукай Зразки Сили в Зул’Ґурубі. Убий прислужників Гаккара і здобудь помсту від імені племені. Ти будеш винагороджений.",
    O = "Принесіть Джин’року Руйнівнику Первісні Наручі Гаккарі. Ви також повинні мати репутацію не нижче Дружньої з племенем Зандалар.$B$BДжин’рок Руйнівник знаходиться на Острові Йоджамба, Терниста Долина.",
    P = "Ви привезли Образці Сили?  Чи була помста від імені Зандалара?",
    C = "Ви багато помстилися сьогодні.  Ви прийняли образ борця.  Ви поставили прихильників Кровавого Бога на коліна.$B$BTake це.  Це підживить вашу помсту на майбутнє.  Тепер ти друг зандаларів.",
},

[8059] = {
    en = "Paragons of Power: The Demoniac's Wraps",
    T = "Зразки Сили: Обгортки Демоніака",
    D = "Чорнокнижники ступають на небезпечну стежку, коли мають справу з демонами, але наші демоніаки йдуть ще далі. Через стародавній і таємничий ритуал вони дозволяють демону увійти в їхню сутність. Але замість того, щоб дозволити йому заволодіти собою, вони поневолюють демона зсередини, поглинаючи його силу для власного використання. Це подвиг, який мало хто здатен опанувати.$B$BЩоб осягнути силу демоніака, я потребую Зразків Сили з Зул’Ґуруба. Вирушай туди і здобудь те, що ми шукаємо.",
    O = "Принесіть Ал’табіму Всевидящему Первісну Опору Гаккарі. Ви також повинні мати репутацію не нижче Дружньої з племенем Зандалар.$B$BАл’табім Всевидящий знаходиться на Острові Йоджамба, Терниста Долина.",
    P = "Ви повернулися з Образцями Сили?  Перемігши диявольських міньйонів Хаккара, ви не тільки доведете нам себе, але й свою готовність пізнати шляхи демонічного.",
    C = "Молодці... безсумнівно, вони були змушені заплатити нестерпними способами, перш ніж вони відмовилися від Образців Сили.  Візьміть це - обгортки демонічного.  Виготовлений із потужного моджо, який використовується для виклику здобичі демоніків, він є потужним інструментом у набутті влади.",
},

[8060] = {
    en = "Paragons of Power: The Illusionist's Wraps",
    T = "Зразки Сили: Обгортки Ілюзіоніста",
    D = "Маги нашого племені відомі як ілюзіоністи. Вони використовують могутню магію у своїх заклинаннях, часто збиваючи з пантелику і вводячи в оману ворогів племені!$B$B<Ал’табім зловісно сміється.>$B$BЦе вражаюче видовище — спостерігати, як могутній ілюзіоніст працює, змушуючи наших ворогів падати на коліна від їхнього власного божевілля!$B$BЩоб осягнути шлях наших ілюзіоністів, вирушай до Зул’Ґуруба і принеси мені обрані Зразки Сили. За це я дам тобі обгортки, які наші ілюзіоністи використовують для плетіння своїх заклять.",
    O = "Принесіть Ал’табіму Всевидящему Первісні Наручники Гаккарі. Ви також повинні мати репутацію не нижче Дружньої з племенем Зандалар.$B$BАл’табім Всевидящий знаходиться на Острові Йоджамба, Терниста Долина.",
    P = "$N - ти вже повернувся?  Чи вдалося вам отримати потрібні мені зразки сили?",
    C = "Вражаюче... ви могли відчути моджо, що тече крізь них?  Взірці сили використовувалися як своєрідна валюта, коли цими землями правила Імперія Гурубаші.  Тепер ми, зандалари, використовуватимемо приховане моджо в них, щоб боротися з другим піднесенням Кровавого бога Хаккара!$B$BYou сьогодні добре впоралися — вважайте, що у вас є друг у Зандаларі.  Для цього я обіцяв обгортки ілюзіоніста!",
},

[8061] = {
    en = "Paragons of Power: The Confessor's Wraps",
    T = "Зразки Сили: Обгортки Сповідника",
    D = "Ми, Зандалари, наділяємо силою тих, хто говорить із божественним авторитетом. Наші жерці — це не просто зцілителі, вони наші сповідники. Зло приходить як із зовнішніх загроз — таких як Гаккар, — так і зсередини племені. Наші сповідники діють як судді серед нас, захищаючи нас від того ж зла, яке знищило Ґурубаші зсередини.$B$BВирушай до Зул’Ґуруба і принеси Зразки Сили від Ґурубаші. Дізнайся, що означає бути сповідником, і захищай нас від зла.",
    O = "Принесіть Ал’табіму Всевидящему Первісну Опору Гаккарі. Ви також повинні мати репутацію не нижче Дружньої з племенем Зандалар.$B$BАл’табім Всевидящий знаходиться на Острові Йоджамба, Терниста Долина.",
    P = "Ти повернувся із Зул'Гуруба?  Чи вдалося вам відібрати зразки сили у прислужників Хаккара?",
    C = "Чудово, $N!  Це було не маленьким подвигом принести їх мені.  Безсумнівно, ви виступили сьогодні як сповідник нашого племені, щоб захистити нас від загрози Хаккара.  Ці обгортки личать такому другу племені, як ти!",
},

[8062] = {
    en = "Paragons of Power: The Predator's Bracers",
    T = "Зразки Сили: Наручі Хижака",
    D = "У темні часи після падіння Імперії Ґурубаші мисливці Зандалару використовували свою майстерність, щоб забезпечувати плем’я їжею. Мисливці стверджують, що вони подібні до хижаків нашого племені — полювати означає втілювати сутність хижака, так. Твоє полювання в Зул’Ґурубі покаже нам, наскільки ти справді можеш зрівнятися з нашими найкращими хижаками.$B$BПринеси мені зразки Зразків Сили зсередини Зул’Ґуруба. Зроби це, і ти зробиш перші кроки до того, щоб стати верховним хижаком.",
    O = "Принесіть наступні Зразки Сили з Зул’Ґуруба до Фалтіра Безочого: Первісні Наручники Гаккарі. Ви також повинні мати репутацію не нижче Дружньої з племенем Зандалар.$B$BФалтір Безочий знаходиться на Острові Йоджамба, Терниста Долина.",
    P = "Полюйте на тих у Зул'Ґурубі, хто володів би Взірцями Сили, $N.  Вони ваша здобич; вони володіють тим, що повинні мати ми обидва.",
    C = "Так... Мені не потрібне бачення, щоб відчути присутність Взірців Сили.  Ваш успіх у Зул'Гурубі вразив багатьох у племені.  Ми не тільки вважаємо вас другом Зандалара, але й вважаємо, що ви достатньо гідні володіти наручами хижака — потужними предметами та символом того, що означає бути хижаком.  Молодець, $N.",
},

[8063] = {
    en = "Paragons of Power: The Madcap's Bracers",
    T = "Зразки Сили: Наручі Шаленця",
    D = "Шаленці Зандалару подібні до розбійників, але понад усе вони приймають божевілля… хаос… непередбачуваність існування. Вони були жахливим видовищем на полі бою, сіючи зерна плутанини та хаосу серед наших ворогів у дикі часи після розколу племен. Ми б не вижили до сьогодні без них.$B$BПринеси мені Зразки Сили з Зул’Ґуруба, які я шукаю, і я дам тобі першу з цінних обладунків шаленця. Прийми божевілля!",
    O = "Принесіть Фалтіру Безочому Первісні Наручі Гаккарі. Ви також повинні мати репутацію не нижче Дружньої з племенем Зандалар.$B$BФалтір Безочий знаходиться на Острові Йоджамба, Терниста Долина.",
    P = "Шукайте божевілля в Зул'Ґурубі та затьмарюйте його своїм власним, $N!  Зробити це означає успіх, а успіх означає винагороду!  Нехай Кривавий Бог знову не панує!",
    C = "Молодець, $N... завдяки своїм досягненням у Зул'Ґурубі ти отримав право називати плем’я Зандалар своїм другом.  Я подбаю про розташування Парагонів; за ваші зусилля, будь ласка, прийміть цю нагороду!",
},

[8064] = {
    en = "Paragons of Power: The Haruspex's Belt",
    T = "Зразки Сили: Пояс Гаруспіка",
    D = "Ми, Зандалари, не знаємо друїдських шляхів; природа має формуватися за нашими потребами, а не навпаки. Проте гаруспік — це той із нас, хто найбільше налаштований на природу, і це правильно. Віддати дух звіра означає знати, що означає бути одним із них. Це справжня сила природи.$B$BПринеси мені дари Зразків Сили зсередини Зул’Ґуруба, довівши свою цінність для нас. Зроби це, і я дам тобі могутній предмет — пояс, який використовують багато гаруспіків Зандалару.$B$BСильна магія, брате!",
    O = "Принесіть Майвікі з Зулдазара Первісний Пояс Гаккарі. Майвікі з Зулдазара знаходиться на Острові Йоджамба, Терниста Долина. Ви також повинні мати репутацію не нижче Шанованої з Зандаларом.",
    P = "Маю потрібні зразки сили від Зул'Гуруба?  Пояс гаруспекса буде вашим, якщо він у вас є.",
    C = "Я дякую вам - прихована сила в цих предметах буде скарбом для них самих.  Ти не тільки зробив те, про що я просив, але й довів, що ти шанобливий для нас тут, у племені.  Як і обіцяли, ось ваша винагорода!",
},

[8065] = {
    en = "Paragons of Power: The Haruspex's Tunic",
    T = "Зразки Сили: Туніка Гаруспіка",
    D = "Найвищий символ сили гаруспіка — це те, що вони носять, $N. З-поміж цього туніка символізує зв’язок між ними та божественною мудрістю, яку вони шукають. У туніку часто вплітають частини звірів, яких вони приносять у жертву; це нагадує їм про зв’язок із їхніми дарами.$B$BПринеси мені дари Зразків Сили зсередини Зул’Ґуруба і доведи свою цінність для нас. Зроби це, і туніка, просякнута справжньою силою гаруспіка, буде твоєю.",
    O = "Принесіть Майвікі з Зулдазара Первісний Табард Гаккарі. Майвікі з Зулдазара знаходиться на Острові Йоджамба, Терниста Долина. Ви також повинні мати репутацію не нижче Поважної з Зандаларом.",
    P = "Отримали необхідні зразки сили від Зул'Гуруба?  Туніка гаруспекса варта всіх зусиль, які вам доведеться докласти.",
    C = "Вражає... ви успішно зібрали необхідні образи сили, $N.  Ваші досягнення в Зул'Гурубі для Зандалара легендарні; відтепер ти будеш шанований серед племені.  Ось твоя туніка, могутній $C!",
},

[8066] = {
    en = "Paragons of Power: The Predator's Belt",
    T = "Зразки Сили: Пояс Хижака",
    D = "Хижак знає, як вистежувати свою здобич, але успішний хижак знає, як атакувати її, коли дистанція скорочується. Ти мусиш опанувати обидва вміння, щоб мати шанс на успіх у Зул’Ґурубі… і шанс стати подібним до хижаків Зандалару.$B$BПринеси мені вибрані частини Зразків Сили зсередини Зул’Ґуруба. Моя нагорода — це сила, яку дають ці дрібнички, а твоєю буде пояс хижака Зандалару — спорядження, яке варте цієї угоди.",
    O = "Принесіть наступні Зразки Сили з Зул’Ґуруба до Фалтіра Безочого: 5 Монет Раззаші, 5 Монет Гаккарі, 2 Зелені Самоцвіти Гаккарі та Первісну Накидку Гаккарі. Ви також повинні мати репутацію не нижче Шанованої з племенем Зандалар.$B$BФалтір Безочий знаходиться на Острові Йоджамба, Терниста Долина.",
    P = "Вдарте по божевільним міньйонам Хаккара в Зул'Гурубі — саме вони володіють Взірцями Сили, $N.  Доведіть свій успіх їм - і племені - як претендент на хижака.",
    C = "Я відчув твій прихід кілька хвилин тому, $N, але не надто легко.  Те, що відкрився мені, це образи сили, які ви принесли.  Я можу відчувати силу без необхідності бачити дрібнички; їхня прихована магія — чиста магія, якщо хочете — продовжуватиме підживлювати наші зусилля з подолання диявольських схем Кривавого Бога Хаккара.$B$BYou заслуговують похвали — і винагороди — за ваш успіх.  Ви користуєтеся пошаною серед племені, і ви гідні носити пояс хижака.",
},

[8067] = {
    en = "Paragons of Power: The Predator's Mantle",
    T = "Зразки Сили: Мантія Хижака",
    D = "Ми, Зандалари, цінуємо те, що носимо, як символ досягнень. Тобі не потрібно бачити, що хтось носить, щоб відчути, що випромінюється від цього — сила перевершує зір. Обладунки хижака Зандалару саме такі, і найдорожчим для них є мантія, яку вони носять. Вона допомагає приховувати їх від очей… і виявляти їхню присутність, коли вони цього хочуть.$B$BЗразки Сили чекають на тебе в Зул’Ґурубі. Принеси мені те, що я шукаю, і мантія хижака буде твоєю.",
    O = "Принесіть наступні Зразки Сили з Зул’Ґуруба до Фалтіра Безочого: 5 Зуліанських Монет, 5 Монет Ґурубаші, 2 Срібні Самоцвіти Гаккарі та Первісний Еґіс Гаккарі. Ви також повинні мати репутацію не нижче Поважної з племенем Зандалар.$B$BФалтір Безочий знаходиться на Острові Йоджамба, Терниста Долина.",
    P = "Ваші удари по Зул'Ґурубу принесли успіх, $N?  Лише тоді, коли ти принесеш мені те, чого я шукав, — і повністю доведеш себе племені, — ти отримаєш мантію, рівноцінну серед зандаларів.",
    C = "Успіху... ти будеш шанований серед племені, $N.  Здобути зразки сили, необхідні для мантії, було немалим подвигом, але ви впоралися з цим у стилі найсмертоноснішого з наших хижаків.  Ви заслужили своє місце серед них і, безсумнівно, заслужили право носити їхню мантію.",
},

[8068] = {
    en = "Paragons of Power: The Illusionist's Mantle",
    T = "Зразки Сили: Мантія Ілюзіоніста",
    D = "Магія — це сира, первісна сила, яку формують ті, хто досить сильний, щоб це зробити. Магія — це наше продовження цієї сили; одним із таких потужних маніпуляцій є ілюзія. Як можна сподіватися перемогти ворога, якого насправді навіть немає? Ми, Зандалари, знаємо силу цього, і тому ілюзіоністи займають почесне місце в племені.$B$BЗдобудь потрібні Зразки Сили з Зул’Ґуруба — за це ти отримаєш пошану від племені та могутню мантію, яку використовують наші найкращі ілюзіоністи!",
    O = "Принесіть наступні Зразки Сили з Зул’Ґуруба до Ал’табіма Всевидячого: 5 Монет Ґурубаші, 5 Монет Раззаші, 2 Помаранчеві Самоцвіти Гаккарі та Первісну Накидку Гаккарі. Ви також повинні мати репутацію не нижче Шанованої з племенем Зандалар.$B$BАл’табім Всевидящий знаходиться на Острові Йоджамба, Терниста Долина.",
    P = "Яким був ваш набіг на Зул'Гуруб?  Ви звели своїх ворогів з розуму силою ілюзії?  Ілюзія чи ні, але їхня смерть і Взірці Сили, відібрані в них, допоможуть перешкодити піднесенню Хаккара.",
    C = "Успіх!  Відтепер вас шануватимуть у племені!  Сьогодні Зул'Ґуруб безсумнівно відчув на собі могутність Зандалара, завдяки вам $N.$B$BWith благословення племені, візьміть мантію зандаларського ілюзіоніста.  Нехай він служить тобі добре.",
},

[8069] = {
    en = "Paragons of Power: The Illusionist's Robes",
    T = "Зразки Сили: Мантії Ілюзіоніста",
    D = "Плем’я визначає статус і силу через те, що ми носимо. Наші шати зроблені з найкращих матеріалів і просякнуті магією, яка робить нас могутніми. Ілюзіоністи не виняток; їхні мантії, як кажуть, втілюють суть ілюзії у своєму вигляді. Легенда свідчить, що їхні стародавні мантії ніколи не виглядали однаково двічі.$B$BЯ дам тобі мантію ілюзіоніста, $N… але спочатку заслужи своє місце пошани серед племені! Принеси мені Зразки Сили з Зул’Ґуруба!",
    O = "Принесіть наступні Зразки Сили з Зул’Ґуруба до Ал’табіма Всевидячого: 5 Монет Піщанобурів, 5 Зуліанських Монет, 2 Срібні Самоцвіти Гаккарі та Первісний Козак Гаккарі. Ви також повинні мати репутацію не нижче Поважної з племенем Зандалар.$B$BАл’табім Всевидящий знаходиться на Острові Йоджамба, Терниста Долина.",
    P = "Ви повернулися з Взірцями Сили, які нам потрібні?  Я знаю, що це буде нелегко... але я давно передбачав, що сторонній прийде на допомогу нам у боротьбі з Хаккаром.  Хай буде тобі, кажу!",
    C = "Нарешті хтось гідний одягнути мантію ілюзіоніста!  Ваш успіх у Зул'Ґурубі забезпечив вам пошану серед племені на віки.  Носи це з гордістю, $N!",
},

[8070] = {
    en = "Paragons of Power: The Confessor's Bindings",
    T = "Зразки Сили: Наручники Сповідника",
    D = "Невдовзі після падіння Ґурубаші ми, Зандалари, ледь не зазнали остаточної поразки від зла всередині нашого племені. Тоді серед нас з’явилися сповідники, які зберегли плем’я, вигнавши тих, хто знищив би своїх побратимів. Вони не лише підтримують зв’язок із духами, але й зберігають плоть.$B$BВирушай до Зул’Ґуруба і на власні очі побачи розпусту Гаккара та Ґурубаші. Відбери у них Зразки Сили, які ми шукаємо; успіх буде винагороджений!",
    O = "Принесіть наступні Зразки Сили з Зул’Ґуруба до Ал’табіма Всевидячого: 5 Монет Гаккарі, 5 Зуліанських Монет, 2 Помаранчеві Самоцвіти Гаккарі та Первісний Пояс Гаккарі. Ви також повинні мати репутацію не нижче Шанованої з племенем Зандалар.$B$BАл’табім Всевидящий знаходиться на Острові Йоджамба, Терниста Долина.",
    P = "Образці сили... вони у вас є?  Лише тоді, коли вони у нас є, ми зможемо використовувати приховану силу, що зберігається в них.  Було б добре перевернути міньйонів Кровавого Бога...",
    C = "Успіх!  Це значною мірою допоможе зміцнити нашу силу проти піднесення Хаккара.  З вашою допомогою ми зробили важливий крок у тому, щоб Кровавий Бог не знищив нас усіх.$B$BYou сьогодні, $N, плем’я заслужило честь.  Прийміть це - сповідальні перев'язки - як символ нашої подяки.",
},

[8071] = {
    en = "Paragons of Power: The Confessor's Mantle",
    T = "Зразки Сили: Мантія Сповідника",
    D = "Усі сповідники Зандалару носять особливу мантію, яка позначає їх як захисників племені. Ці мантії просякнуті могутньою магією, яка допомагає їм судити тих, хто загрожує нашому племені. Як жрець, ти також мусиш судити тих, хто гідний і негідний; така мантія стане для тебе справжнім благословенням.$B$BВ обмін на бій із прислужниками Гаккара в Зул’Ґурубі та принесення мені Зразків Сили, які я шукаю, я дам тобі мантію, гідну наших найкращих сповідників.",
    O = "Принесіть наступні Зразки Сили з Зул’Ґуруба до Ал’табіма Всевидячого: 5 Монет Раззаші, 5 Монет В’ялошкурих, 2 Бронзові Самоцвіти Гаккарі та Первісний Еґіс Гаккарі. Ви також повинні мати репутацію не нижче Поважної з племенем Зандалар.$B$BАл’табім Всевидящий знаходиться на Острові Йоджамба, Терниста Долина.",
    P = "У вас є зразки сили від Зул'Гуруба?",
    C = "Молодець, $N – міньйони Хаккара напевно відчули сьогодні відплату Зандалара завдяки тобі.  Ваші дії дали вам постійне місце шанування в племені.  З нашого благословення прийміть цю мантію сповідника як свою!",
},

[8072] = {
    en = "Paragons of Power: The Madcap's Mantle",
    T = "Зразки Сили: Мантія Шаленця",
    D = "Одним із легендарних шаленців Зандалару був Хар’ваксал Тріснутий. Легенда свідчить, що, вперше зіткнувшись із ворогами племені, Хар’ваксал використовував свою мантію, спеціально виткану з «плетива божевілля». Його форма була прихована не лише мантією, але й сліпучою швидкістю його подвійних кинджалів. Сьогодні шаленці цінують свою мантію як знак їхнього місця в племені.$B$BПринеси мені Зразки Сили, які я шукаю, і така мантія буде твоєю, щоб ти міг насилати божевілля на своїх ворогів.",
    O = "Принесіть наступні Зразки Сили з Зул’Ґуруба до Фалтіра Безочого: 5 Зуліанських Монет, 5 Монет Раззаші, 2 Фіолетові Самоцвіти Гаккарі та Первісний Пояс Гаккарі. Ви також повинні мати репутацію не нижче Шанованої з племенем Зандалар.$B$BФалтір Безочий знаходиться на Острові Йоджамба, Терниста Долина.",
    P = "Ви повернулися – чи є у вас потрібні Взірці Сили?$B$BThe Легенда про Хар’ваксала Потрісканого служить нам сьогодні як нагадування, що жодного ворога – якою б великою загрозою він не був – неможливо подолати.  Хаос поставить усіх на коліна, це точно... і, можливо, найбільш нехаотичні елементи хаосу.",
    C = "Перемога сьогодні за нами, завдяки безумству, яке ви посіяли на наших спільних ворогів!  Ви повинні бути шанованими серед Зандаларів, і немає кращого способу виявити вдячність за ваші вчинки, ніж пропонувати вам мантію божевільного!",
},

[8073] = {
    en = "Paragons of Power: The Madcap's Tunic",
    T = "Зразки Сили: Туніка Шаленця",
    D = "Мої очі давно мене підвели, але я не сумую за ними. Навіть у такому племені, як наше — де одяг символізує статус і мету — наймогутніші обладунки випромінюють силу, яку прості очі не можуть побачити. Улюблена туніка шаленців Зандалару — не виняток, вона випромінює сиру силу хаосу та божевілля, яку вони здатні спрямовувати.$B$BЗразки Сили, які мені потрібні, знаходяться в Зул’Ґурубі; принеси мені те, що я шукаю, і я винагороджу тебе власною легендарною тунікою… гідною того, хто плете божевілля.",
    O = "Принесіть наступні Зразки Сили з Зул’Ґуруба до Фалтіра Безочого: 5 Монет Гаккарі, 5 Монет Черепорізів, 2 Золоті Самоцвіти Гаккарі та Первісний Еґіс Гаккарі. Ви також повинні мати репутацію не нижче Поважної з племенем Зандалар.$B$BФалтір Безочий знаходиться на Острові Йоджамба, Терниста Долина.",
    P = "Ласкаво просимо назад на Острів, $N... ти тріумфально повернувся з Взірцями Сили на буксирі?",
    C = "Вражаюче... сьогодні ви досягли того, що мало хто вважав можливим.  Ваша пошана в племені гарантована на все життя, $N.  Ви заслужили право надіти туніку божевільного — зробіть це з нашого благословення.",
},

[8074] = {
    en = "Paragons of Power: The Augur's Belt",
    T = "Зразки Сили: Пояс Віщуна",
    D = "Віщуни знають магію елементів, брате. Вони використовують її, щоб вести плем’я до слави. У темні дні після того, як Імперія Ґурубаші розвалилася, наші віщуни привели нас до безпечного притулку в Південних Морях. Вони також привели нас назад сюди, до Долини, прямо до серця зла, що зароджується в Зул’Ґурубі.$B$BПринеси мені дари Зразків Сили зсередини Зул’Ґуруба і доведи свою цінність для нас. Зроби це, і я дам тобі пояс, який використовують наші віщуни — з могутньою магією всередині!",
    O = "Принесіть наступні Зразки Сили з Зул’Ґуруба до Майвікі з Зулдазара: 5 Монет Черепорізів, 5 Монет Ґурубаші, 2 Фіолетові Самоцвіти Гаккарі та Первісний Пояс Гаккарі. Ви також повинні мати репутацію не нижче Шанованої з племенем Зандалар.$B$BМайвікі з Зулдазара знаходиться на Острові Йоджамба, Терниста Долина.",
    P = "Взірці сили — це те, що мені потрібно, мон — ми вичерпаємо силу прямо з них у нашій боротьбі зі злом із Зул'Ґуруба.  У вас є вони для мене?",
    C = "Я відчуваю на тобі запах переможеного зла, $N.  Це солодкий запах, моє... я думаю, ти його добре знаєш.$B$BI знаю, що це не маленький подвиг — принести мені Образці Сили, необхідні для пояса.  Ваші вчинки принесли честь не тільки племені, але й вам у моєму племені.  Ось, візьміть пояс авгура і одягніть його як свій!",
},

[8075] = {
    en = "Paragons of Power: The Augur's Hauberk",
    T = "Зразки Сили: Хауберк Віщуна",
    D = "Усі віщуни Зандалару носять особливий нагрудник, який називається хауберком. Він виготовлений із найкращих шовків і тканин, переплетених із міцним ланцюгом. Це символ не лише їхньої божественності, але й їхнього авторитету, брате. Ніколи не варто перечити тому, чиє життя присвячене спілкуванню з духами…$B$BПринеси мені дари Зразків Сили зсередини Зул’Ґуруба і доведи свою цінність для нас. Зроби це, і я дам тобі один із найкращих хауберків, про які коли-небудь мріяли наші віщуни!",
    O = "Принесіть наступні Зразки Сили з Зул’Ґуруба до Майвікі з Зулдазара: 5 Монет В’ялошкурих, 5 Монет Гаккарі, 2 Золоті Самоцвіти Гаккарі та Первісний Табард Гаккарі. Ви також повинні мати репутацію не нижче Поважної з племенем Зандалар.$B$BМайвікі з Зулдазара знаходиться на Острові Йоджамба, Терниста Долина.",
    P = "Взірці сили є ключовим джерелом магічної сили — тієї самої сили, яка використовується для виготовлення кольчуги авгура.  Принесіть мені те, що мені потрібно, і я зможу поділитися найкращим одягом, який будь-який зандаларський авгур забажав би собі.",
    C = "Я знаю, через що тобі довелося пройти, щоб принести мені образи сили, $N.  Це було нелегко, чоло — перемогти зло, яке сочиться із Зул'Ґуруба, як мерзенний слиз, — але тепер, коли все сказано й зроблено, я можу легко сказати, що ти будеш шанований серед зандаларів у майбутньому!$B$BHere — візьми кольчугу авгура й носи її з гордістю!",
},

[8076] = {
    en = "Paragons of Power: The Demoniac's Mantle",
    T = "Зразки Сили: Мантія Демоніака",
    D = "Демоніак прагне втілювати силу напряму, а не просто володіти нею. Не один із наших демоніаків програв у боротьбі з демоном; із нашими ворогами, які загрожують нам — особливо в Зул’Ґурубі, — сила, яку демоніак може випустити на наших ворогів, варта цієї жертви. Наше виживання залежить від знищення тих, хто прагне нас знищити; падіння Імперії Ґурубаші навчило нас цього.$B$BВирушай до Зул’Ґуруба і здобудь Зразки Сили, які нам потрібні. Зроби це, і цінний предмет демоніака буде твоїм.",
    O = "Принесіть наступні Зразки Сили з Зул’Ґуруба до Ал’табіма Всевидячого: 5 Монет В’ялошкурих, 5 Монет Гаккарі, 2 Помаранчеві Самоцвіти Гаккарі та Первісний Пояс Гаккарі. Ви також повинні мати репутацію не нижче Шанованої з племенем Зандалар.$B$BАл’табім Всевидящий знаходиться на Острові Йоджамба, Терниста Долина.",
    P = "Отримав зразки сили з Зул'Гуруба?  Хоча ми візьмемо приховану силу цих предметів і зробимо їх своїми, ми дамо вам вашу власну винагороду сили, якщо ви досягнете успіху...",
    C = "Молодець, $N.  Взірці сили з Зул'Ґуруба повинні діяти як нагадування про втрачену силу.  Ґурубаші були сильними на своїй висоті, але вони дозволили собі поглинути це.  Демонічні знають, що гра, в яку вони грають, дуже схожа, але вивільнена сила часто потрібна для виживання.$B$BUse ця мантія почесного союзника Зандалара... вона вам добре послужить.",
},

[8077] = {
    en = "Paragons of Power: The Demoniac's Robes",
    T = "Зразки Сили: Мантії Демоніака",
    D = "Найвищий символ сили серед племені — це обладунки, які ми носимо в бою. Мантії демоніака поєднують у собі тонкий рунотканий матеріал і надзвичайно могутню магію в єдину тканину. Кажуть, що вигляд цієї мантії вселяє страх у серця всіх, хто її бачить… особливо демонів, яких демоніак зрештою підкорить.$B$BІз Зул’Ґуруба ти мусиш принести мені дуже специфічний набір Зразків Сили. Це буде важко… але твій успіх гарантує тобі здобуття мантії для себе.",
    O = "Принесіть наступні Зразки Сили з Зул’Ґуруба до Ал’табіма Всевидячого: 5 Монет Черепорізів, 5 Монет Кровискалпів, 2 Срібні Самоцвіти Гаккарі та Первісний Козак Гаккарі. Ви також повинні мати репутацію не нижче Поважної з племенем Зандалар.$B$BАл’табім Всевидящий знаходиться на Острові Йоджамба, Терниста Долина.",
    P = "Взірці сили... ти повернувся з ними?  Лише коли ми їх отримаємо, ми поділимося з тобою найвищим символом демонічної сили, $N.",
    C = "Вражаюче — ваша перемога в Зул'Гурубі запевнила нас — ні, світ — що Хаккар не переможе.  Може настати час, коли ви прямо зіткнетеся з Кровавим Богом... і якщо це станеться, знайте, що плем’я Зандалар має ваше шанування.$B$BOh, і ця проста мантія, я думаю, також має допомогти.$B$B<Аль'табім свідомо підморгує вам.>",
},

[8078] = {
    en = "Paragons of Power: The Vindicator's Belt",
    T = "Зразки Сили: Пояс Месника",
    D = "Найвища помста чекає в Зул’Ґурубі. Гаккар не повинен воскреснути. Гаккар знищив Імперію Ґурубаші зсередини. Жодна жертва не була достатньою. Тролі — лише тінь колишньої слави. Я знаю, що це через Гаккара.$B$BСтань месником, яким тобі судилося бути. Сій хаос серед прислужників зла. Зул’Ґуруб має відчути помсту Зандалару. Принеси мені доказ у вигляді Зразків Сили. Ти отримаєш пояс месника. Ти отримаєш справжню силу.$B$BІди.",
    O = "Принесіть наступні Зразки Сили з Зул’Ґуруба до Джин’рока Руйнівника: 5 Монет Зловілля, 5 Монет Черепорізів, 2 Зелені Самоцвіти Гаккарі та Первісний Пояс Гаккарі. Ви також повинні мати репутацію не нижче Шанованої з племенем Зандалар.$B$BДжин’рок Руйнівник знаходиться на Острові Йоджамба, Терниста Долина.",
    P = "Ви привезли Образці Сили?  Чи вразив ти ворогів племені?  Хаккар повинен пізнати гнів виправника!",
    C = "Шлях винника тепер вам відомий.  Ви принесли честь племені.  Ти приніс собі честь.  Ви завдали болю нашим ворогам.$B$BThe пояс рятувальника ваш.  Ви, безсумнівно, стаєте єдиним цілим шляхом захисника.",
},

[8079] = {
    en = "Paragons of Power: The Vindicator's Breastplate",
    T = "Зразки Сили: Нагрудник Месника",
    D = "Символ сили месника — це нагрудник. Він викуваний із могутньою магією. Його довіряють лише тим, кого ми поважаємо. Це символ помсти Зандалару.$B$BСтати месником — означає стати самою помстою. Візьми Зразки Сили, які нам потрібні, з Зул’Ґуруба. Принеси їх нам. Ми заберемо магію, яку у нас вкрали. Ми змусимо прислужників Гаккара заплатити. Ми винагородимо тебе нагрудником месника.$B$BІди. Будь нашою помстою, $N.",
    O = "Принесіть наступні Зразки Сили з Зул’Ґуруба до Джин’рока Руйнівника: 5 Монет Кровискалпів, 5 Монет Піщанобурів, 2 Бронзові Самоцвіти Гаккарі та Первісний Козак Гаккарі. Ви також повинні мати репутацію не нижче Поважної з племенем Зандалар.$B$BДжин’рок Руйнівник знаходиться на Острові Йоджамба, Терниста Долина.",
    P = "Ваша присутність означає перемогу?  У вас є зразки сили?  Розкажи мені про помсту, яку ти здійснив сьогодні!",
    C = "Вас шанують за ваші справи.  Плем'я нагороджує своїх героїв.  Зул'Ґуруб відчув смак зандаларської помсти, як ніколи раніше.$B$BYour вчинки передвіщатимуть вчинки інших.  Вони дивитимуться на вас як на ознаку справжньої влади.  Вони дивитимуться на вас як на уособлення помсти!",
},

[8080] = {
    en = "Arathi Basin Resources!",
    T = "Почесний Знак Ущелини Араті!",
    D = "Війну треба вести солдатами, це скаже тобі будь-який солдат. Вони також скажуть, що битва, проведена з поганим спорядженням чи на голодний шлунок, програна ще до її початку!$B$BОсь чому Ущелина Араті важлива. У цій долині є ключові точки, які містять необхідні ресурси. Метали, зброя, їжа, деревина — усе це потрібно, і все це можна здобути там.$B$BЦе те, що я хочу від тебе, $N. Увійди до Ущелини Араті, виграй битву, утримуючи більше баз, ніж ворог, і повернися до мене з Почесним Знаком.",
    O = "Виграйте битву за Ущелину Араті, отримайте Почесний Знак Ущелини Араті і поверніться до Сержанта Макліра в Табір Прихистку.",
    P = "У вас є ящик із ресурсами, $N? Ліга Аратору не може вести гідну битву без них...",
    C = "У вас є ресурси! Чудова робота! Я надішлю ресурси нашим квартирмейстерам, які можуть швидко розпорошити їх серед наших військ.$B$BThank ти, $N. Дійсно, виконання успішних місій, подібних до вашої, — це те, як справді виграються війни.",
},

[8081] = {
    en = "More Resource Crates",
    T = "Більше Скринь із Ресурсами",
    D = "Війну треба вести солдатами, це скаже тобі будь-який солдат. Вони також скажуть, що битва, проведена з поганим спорядженням чи на голодний шлунок, програна ще до її початку!$B$BОсь чому Ущелина Араті важлива. У цій долині є ключові точки, які містять необхідні ресурси. Метали, зброя, їжа, деревина — усе це потрібно, і все це можна здобути там.$B$BЦе те, що я хочу від тебе, $N. Увійди до Ущелини Араті, виграй битву, утримуючи більше баз, ніж ворог, і повернися до мене зі скринею ресурсів.",
    O = "Виграйте битву за Ущелину Араті, отримайте Скриню Ресурсів Араті і поверніться до Сержанта Макліра в Табір Прихистку.",
    P = "$N, Ліга Аратора має постійну місію, щоб ви знову увійшли в басейн Араті, роздобули більше ящиків із ресурсами та принесли їх мені.",
    C = "Дуже добре. Я негайно передам їх нашим інтендантам, а подяка за ваші дії буде надіслана моєму начальству.$B$BOnce ще раз, дякую $N. Ваш внесок у нашу боротьбу помічений і лакеєм, і фельдмаршалом.",
},

[8101] = {
    en = "The Pebble of Kajaro",
    T = "Галька Каджаро",
    D = "",
    O = "",
    P = "NULL",
    C = "$R, камінчик, що міститься в рамці цього талісмана, походить з гори Каджаро в Південних морях. Гора Каджаро — це територія, яка страждає від нестабільності, позначена бурхливими й часто магічними виверженнями вулканів.$B$BAs ваш зв’язок із тролями Зандалару зростатиме, як і сила цієї гальки. Використовуйте силу камінчика, щоб вразити наших ворогів. Будь як гора: швидкий, вибуховий, смертельний...",
},

[8102] = {
    en = "The Pebble of Kajaro",
    T = "Галька Каджаро",
    D = "",
    O = "",
    P = "З поверненням, $c. Я бачу, що камінчик знайшов багато користі. Багато наших ворогів впали через ваші потойбічні здібності. Їхні страждання були великими. Настав час підвищити силу камінчика. Дай це мені.",
    C = "Будьте нестримними, як розплавлені фронти Каджаро.",
},

[8103] = {
    en = "The Pebble of Kajaro",
    T = "Галька Каджаро",
    D = "",
    O = "",
    P = "Хаккарі боїться тебе, $n. Вони говорять про жахи, які, на їхню думку, міг вчинити лише їхній безликий Бог. Ви спалили їх силою Каджаро. Тепер вони знають страх у двох місцях.$B$BIt час ще більше зміцнити камінчик. Дай мені талісман.",
    C = "Продовжуйте знищувати тролів Зул'Гуруба. Хаккар повинен переконатися, що світ не прогнуться під його незламною волею.",
},

[8104] = {
    en = "The Jewel of Kajaro",
    T = "Коштовність Каджаро",
    D = "",
    O = "",
    P = "Дай мені талісман, $n. Я повинен тобі дещо показати.",
    C = "<Аль'табім розбиває камінчик із потужною невидимою силою.>$B$BDo бачите? Камінчик - це те, що ми називаємо жеодою. Усередині гальки знаходяться потужні кристали, які просочуються прихованою енергією нашого світу. Розрізавши камінчик навпіл, я нарешті дозволив повністю реалізувати його потенціал. Використовуйте його, щоб спустошити наших ворогів.",
},

[8105] = {
    en = "The Battle for Arathi Basin!",
    T = "Битва за Ущелину Араті!",
    D = "$N, битва за Ущелину Араті — це битва за ресурси та територію. Ключові точки в цій зоні потрібно утримувати і використовувати, щоб забезпечити наші війська необхідними сировиною та припасами. Я доручаю тобі атакувати точки, найвіддаленіші від нашої бази в Ущелині Араті.$B$BАтакуй ферму, копальню, лісопилку та кузню, коли їх контролює ворог. Знайди ворожий прапор і вирви його зі стовпа!$B$BКоли ти зробиш це з усіма чотирма точками, повертайся до мене.",
    O = "Атакуйте копальню, лісопилку, кузню та ферму, а потім поверніться до Фельдмаршала Ослайта в Табір Прихистку.",
    P = "Напад на шахту",
    C = "",
},

[8106] = {
    en = "Kezan's Taint",
    T = "Пляма Кезана",
    D = "",
    O = "",
    P = "",
    C = "Прийми цей талісман, $c. Прийміть це та використовуйте його силу, щоб знищити наших спільних ворогів.$B$BKnow що на шиї ви носите шматок історії. Колись Кезан був великою територією імперії Зандалар. На жаль, пляма торгових принців гоблінів витіснила б моїх гордих братів і сестер.$B$BKezan тепер є домом для гоблінської столиці Підкопу; але знайте, що до осквернення воно мало велич. Досі Кезан вважається священною землею для мого народу.",
},

[8107] = {
    en = "Kezan's Taint",
    T = "Пляма Кезана",
    D = "",
    O = "",
    P = "Зандаларські тролі заслужили честь, $n. З честю приходить нагорода - дружба, союз...$B$BHand мені талісман, щоб я міг посилити його силу.",
    C = "Малюй з темряви, $c. Обійняти тіні. Нехай Kezan's Taint доповнить ваше темне втручання.",
},

[8108] = {
    en = "Kezan's Taint",
    T = "Пляма Кезана",
    D = "",
    O = "",
    P = "Я готовий до тебе, $c. Я ще раз покращу ваш талісман. Я лише прошу, щоб ви продовжували знищувати Хаккара та його прихильників.$B$BGive мені талісман.",
    C = "Лише спільними зусиллями ми зможемо зупинити Винищувача душ.",
},

[8109] = {
    en = "Kezan's Unstoppable Taint",
    T = "Нестримна Пляма Кезана",
    D = "",
    O = "",
    P = "Виклич своїх демонів, $c. Дозвольте їм погрітися в енергії Kezan's Taint. Керуйте ними на полі бою! Знищуйте ворога!$B$BYes... Настав час застосувати останнє покращення до Kezan's Taint. Дай мені талісман.",
    C = "Здерти м'ясо з їхніх трупів. Дивіться, як тіні поглинають Хаккарі. Черпайте силу з їхнього страху, $c. Нехай Kezan's Taint посилить цю силу...",
},

[8110] = {
    en = "Enchanted South Seas Kelp",
    T = "Зачаровані Водорості Південних Морів",
    D = "",
    O = "",
    P = "NULL",
    C = "Бачиш тут морські водорості, чувак? Це з південних морів. Ми просто додаємо трохи магії та чарівництва, і він набуває властивостей, які найбільше підходять для його власника.$B$BYou a $c, тож нехай буде легко, чувак. Просто оберніть його навколо шиї та подумайте про природу чи білок чи щось інше, що вам подобається.",
},

[8111] = {
    en = "Enchanted South Seas Kelp",
    T = "Зачаровані Водорості Південних Морів",
    D = "",
    O = "",
    P = "Гей, мон! Буду радий побачити тебе знову. Плем'я говорить про те, що ти вбив Хаккарі та все таке. Мольтор дав мені слово додати більше моджо до вашого талісмана. Просто дайте це сюди, і Maywiki зробить це краще.",
    C = "Шия не для куріння, чоловіче! Ви повинні використовувати його для боротьби зі злом.",
},

[8112] = {
    en = "Enchanted South Seas Kelp",
    T = "Зачаровані Водорості Південних Морів",
    D = "",
    O = "",
    P = "Як цей талісман, човече? Схоже, настав час додати до його листя трохи більше магії та магії. Йому потрібно трохи розквітнути. Дайте це сюди, і Maywiki це виправить.",
    C = "Тепер ти візьми злих тролів у Zul'Gurub і покажи їм, на що здатні твої природні сили, човече!",
},

[8113] = {
    en = "Pristine Enchanted South Seas Kelp",
    T = "Незаймані Зачаровані Водорості Південних Морів",
    D = "",
    O = "",
    P = "$n! Я вас давно не бачив. Чи знаєте ви, що сам король Растахан дав мені наказ додати останній шматочок моджо та магії до вашого талісмана? Нехай це буде правда, мон! Я б не повірив, якби не бачив на власні очі. Дай сюди.",
    C = "$n, це була гарна подорож. Продовжуйте вбивати та придушувати Хаккара та його прихильників.",
},

[8114] = {
    en = "Control Four Bases",
    T = "Контролюйте Чотири Бази",
    D = "$N, ти переніс битву за Ущелину Араті до наших ворогів і здобув великі почесті на цьому полі бою. Ти показав нам свою цінність як $c, і ти показав нашим ворогам, що ми не скоримося їхній підлості!$B$BЗавдяки твоїй доведеній цінності для нас, у мене є складне завдання для тебе. Я хочу, щоб ти захопив і утримував щонайменше чотири бази в Ущелині Араті. Якщо ти зможеш це зробити, ми не лише забезпечимо критичні ресурси, але й покажемо Орді наше панування!$B$BІди, $N, і нехай удача буде з тобою.",
    O = "Увійдіть до Ущелини Араті, захопіть і утримуйте чотири бази одночасно, а потім поверніться до Фельдмаршала Ослайта в Табір Прихистку.",
    P = "",
    C = "Контролюйте чотири бази.",
},

[8115] = {
    en = "Control Five Bases",
    T = "Контролюйте П’ять Баз",
    D = "$N, битва за ресурси Ущелини Араті — це кривава справа. Твої послуги для Ліги Аратору потрібні так само, як вони цінуються.$B$BІ у нас є ще одне завдання для тебе.$B$BЛіга хоче зробити потужний наступ проти окупації Ущелини Араті Сквернителями. Ми хочемо, щоб їх витіснили з усіх стратегічних точок на полі бою!$B$BЦе буде нелегко, але якщо хтось і може це зробити, то це ти.",
    O = "Контролюйте 5 баз в Ущелині Араті одночасно, а потім поверніться до Фельдмаршала Ослайта в Табір Прихистку.",
    P = "",
    C = "Візьміть п'ять баз.",
},

[8116] = {
    en = "Vision of Voodress",
    T = "Видіння Вудресса",
    D = "",
    O = "",
    P = "NULL",
    C = "Ви з Майвікі маєте щось спільне, мон. Ми обидва будемо $c! Хоча Майвікі — це більше містика, а ти більше скраб. Тим не менш, ми обоє знаємо, що приносять великі духи.$B$BAs подарунок, я даю тобі цю кулю, щоб носити її на шиї. Зазирніть глибоко всередину та побачте село Вудресс у Південних морях! Нехай це піднімає вам настрій!",
},

[8117] = {
    en = "Vision of Voodress",
    T = "Видіння Вудресса",
    D = "",
    O = "",
    P = "Гарні новини, $n. Останнім часом Мольтор співає вам дифірамби. Він сказав, що ти перетворюєшся на справжнього героя Зандалару.$B$BHe також сказав, щоб Мейвікі ще відшліфував твою кулю! Дайте це сюди, щоб Maywiki міг скрасити зір.",
    C = "Стережіться злих духів Хаккарі, мон. Чесно кажучи, вони моторошні.",
},

[8118] = {
    en = "Vision of Voodress",
    T = "Видіння Вудресса",
    D = "",
    O = "",
    P = "Ша-мон! Мейвікі жартує!$B$B<Майвікі сміється.>$B$BSo, ти використовував духів і стихії проти наших ворогів у Зул'Ґурубі, еге ж? Слава духам!$B$BMaywiki освітлить вашу кулю. Дай сюди, $n.",
    C = "Подивіться на це зараз, $n. Voodress став ще зрозумілішим, правда? Нехай первісна сила тече крізь вас, мо.",
},

[8119] = {
    en = "The Unmarred Vision of Voodress",
    T = "Незатьмарене Видіння Вудресса",
    D = "",
    O = "",
    P = "<Мейвікі вказує на ваш талісман.>$B$BLook на нього, $n! Воно ожило. Духи танцюють навколо кулі.$B$BGive до Мейвікі, щоб вона могла зробити останнє налаштування.",
    C = "Одного разу, $n, ти зможеш використовувати цю кулю, щоб безпосередньо спілкуватися зі мною. Щоразу, коли ця битва з Хаккаром закінчиться, і Мейвікі повернеться додому. Давайте покличемо духів і попросимо їх, щоб цей день настав швидше.",
},

[8120] = {
    en = "The Battle for Arathi Basin!",
    T = "Битва за Ущелину Араті!",
    D = "Як ти, без сумніву, чув, Ліга Аратору відправляє великі війська до Ущелини Араті. Ці дурні з Альянсу, прагнучи їжі та припасів, мають намір захопити і контролювати багаті ресурси цього краю. Ми повинні показати їм, що Араті ніколи знову не стане домом для людей!$B$BВирушай до Ущелини Араті і атакуй копальню, лісопилку, кузню та стайні. Зірви ворожі прапори, оголосивши ці території землями Орди.$B$BІди, $N. Доповіси мені, коли завдання буде виконано.",
    O = "Атакуйте копальню, лісопилку, кузню та стайні в Ущелині Араті, а потім поверніться до Смертоносця Двайра в Молотозгуб.",
    P = "Напад на шахту",
    C = "",
},

[8121] = {
    en = "Take Four Bases",
    T = "Захопіть Чотири Бази",
    D = "$N, коли битви за Ущелину Араті тривають, звістки про твої дії дійшли до багатьох вух. Ти високо цінуєшся серед нас, і це дає мені впевненість, що ти виконаєш завдання, яке я тобі зараз доручаю.$B$BНастав час послати повідомлення Лізі Аратору. Ми повинні показати їм, що їхні позиції в Ущелині Араті хиткі і легко втрачаються. Ми зробимо це, утримуючи одночасно чотири стратегічні точки в Ущелині Араті.$B$BУспішно виконай це, $N, і здобудь велику повагу серед Сквернителів.",
    O = "Утримуйте чотири бази одночасно в Ущелині Араті, а потім поверніться до Смертоносця Двайра в Молотозгуб.",
    P = "",
    C = "Тримайте чотири бази.",
},

[8122] = {
    en = "Take Five Bases",
    T = "Захопіть П’ять Баз",
    D = "Важко побачити, адже ми так глибоко в конфлікті, але наші шпигуни повідомляють про послаблення рішучості Ліги Аратору. Ми повинні скористатися цією можливістю і завдати їм нищівного удару! Повертайся до Ущелини Араті і кинься на наших ворогів. Проклинай їх, убивай і контролюй усі п’ять стратегічних баз! Змусь їхніх солдатів тікати з передової, кричачи та стікаючи кров’ю, з розповідями про твою жорстокість на їхніх жалісних вустах.$B$BЗроби це, і здобудь велику перемогу для Сквернителів.",
    O = "Утримуйте п’ять баз одночасно в Ущелині Араті, а потім поверніться до Смертоносця Двайра в Молотозгуб.",
    P = "",
    C = "Тримайте п'ять баз.",
},

[8123] = {
    en = "Cut Arathor Supply Lines",
    T = "Переріжте Лінії Постачання Аратору",
    D = "Ліга Аратору не шкодує зусиль у своїй спробі повернути Араті. Вони, разом з усіма расами Альянсу, нині стікаються до цього віддаленого регіону, маючи намір розширити свій вплив із Табору Прихистку. Ми повинні зупинити їх, і найкращий спосіб це зробити — забрати їхні припаси.$B$BТи можеш нам допомогти, $N. Увійди до Ущелини Араті, відомої своїми багатими копальнями, родючими землями та вправними ремісниками. Захоплюй і контролюй усі бази, які зможеш, виграй битву і повертайся до мене з ресурсами, які ти здобудеш.",
    O = "Виграйте битву за Ущелину Араті, отримайте Скриню Ресурсів Араті і поверніться до Смертоносця Мортіса в Молотозгуб.",
    P = "",
    C = "",
},

[8124] = {
    en = "More Resource Crates",
    T = "Більше Скринь із Ресурсами",
    D = "Ліга Аратору не шкодує зусиль у своїй спробі повернути Араті. Вони, разом з усіма расами Альянсу, нині стікаються до цього віддаленого регіону, маючи намір розширити свій вплив із Табору Прихистку. Ми повинні зупинити їх, і найкращий спосіб це зробити — забрати їхні припаси.$B$BТи можеш нам допомогти, $N. Увійди до Ущелини Араті, відомої своїми багатими копальнями, родючими землями та вправними ремісниками. Захоплюй і контролюй усі бази, які зможеш, виграй битву і повертайся до мене з ресурсами, які ти здобудеш.",
    O = "Виграйте битву за Ущелину Араті, отримайте Скриню Ресурсів Араті і поверніться до Смертоносця Мортіса в Молотозгуб.",
    P = "$N, Осквернителі мають постійну місію, щоб ви знову увійшли в басейн Араті, роздобули більше ящиків із ресурсами та принесли їх мені.",
    C = "Дуже добре. Я негайно передам їх нашим інтендантам, а подяка за ваші дії буде надіслана моєму начальству.$B$BOnce ще раз, дякую $N. Ваш внесок у нашу боротьбу помічають як бурчання, так і верховний воєначальник.",
},

[8141] = {
    en = "Zandalrian Shadow Talisman",
    T = "Зандаларський Талісман Тіні",
    D = "",
    O = "",
    P = "",
    C = "Ти швидко прогресуєш, молодий $c. Можливо, настав час посвятити вас у Шера Алі’х — Зандаларі для Руки Смерті. Тисячі років ми грали роль вбивці Зандаларської імперії. Занадто довго ми сиділи склавши руки, дозволяючи Хаккарі зростати в силі. Ми знову зіткнулися з Хаккаром, але цього разу без підтримки об’єднаного фронту $r. Саме ви та ваші союзники повинні допомогти в подоланні Кривавого Бога та його прихильників!$B$BWear цей талісман і нехай він допоможе вам у ваших подорожах.",
},

[8142] = {
