[8181] = {
    en = "Confront Yeh'kinya",
    T = "Протистояння Єх’кіньї",
    D = "Мої дослідження Табличок Мош’ару принесли похмурі новини, $N. Справжня форма Гаккара, сам бог, може відродитися через те саме яйце, в яке ти його заточив. Єх’кінья сказав тобі, що це для стримування його зла, але насправді це для його відтворення! Троль ввів тебе в оману!$B$BІди до Єх’кіньї і вимагай яйце від нього. Молися, щоб ще не було запізно зупинити повернення Гаккара!",
    O = "Поговоріть із Єх’кіньєю.",
    P = "",
    C = "Отже, ви розмовляли з тим старим гномом Залізним Чоботом і знайшли втрачені таблички Мошару, чи не так?  Цей втручаючийся старатель...$B$BNo має значення.  Надто пізно рятувати цей світ.  Хаккар відродився, і навіть тепер його сила зростає... глибоко в стародавньому королівстві тролів Зул'Гуруб!  Він прийшов!  І він правитиме в крові та терору!$B$BThank ти, $N.  Ваша допомога прискорила повернення Винищувача душ!",
},

[8182] = {
    en = "The Hand of Rastakhan",
    T = "Рука Растакана",
    D = "$N, наші найгірші побоювання справдилися. Легенда говорить про Душоздира, який правив стародавнім світом тролів через зло і терор, і його сила була абсолютною. Якщо його не зупинити зараз, то його нове правління може поширитися на весь Азерот!$B$BЄ загін зандаларських тролів, які можуть допомогти нам стримати цю хвилю темряви. Вони розташувалися табором на Острові Йоджамба, біля узбережжя Тернистої Долини, на захід від руїн Зул’Кунди. Поговори з їхнім лідером, Молтором, і молися, щоб він знав, як перемогти Гаккара.",
    O = "Поговоріть із Молтором у Тернистій Долині.",
    P = "",
    C = "Вас прислав золотошукач, Залізний Чобіт?  Його рід мудрий і ще розумніший, щоб привести вас до мене, тому що я та зандаларські тролі, можливо, знаємо спосіб перемогти Винищувача душ.$B$BSpeak з тролями цього острова, прислухайся до їхніх слів і готуйся, $N, до завдання, яке стоїть перед тобою, просякнуте кров’ю.",
},

