[8201] = {
    en = "A Collection of Heads",
    T = "Колекція Голів",
    D = "Це правда. Гаккар тепер мешкає в Зул’Ґурубі, купаючись у силі наших богів. Зачаровані верховні жерці тепер спрямовують енергію наших найсвятіших божеств у Душоздира, який скоро матиме силу, що перевершить будь-яку істоту Азероту. Його потрібно зупинити!$B$BВізьми цю священну мотузку і нанизай на неї голови верховних жерців, відповідальних за спрямування енергії наших богів, а також голову їхнього лідера, Джін’до Проклинача.$B$BКоли ти це зробиш, повертайся до мене.",
    O = "Нанизайте 5 голів Каналів і голову Проклинача на Священну Мотузку, потім поверніть Колекцію голів тролів до Екзала на Острові Зандалар.",
    P = "У вас є колекція голів, $N?  Ми повинні не дати Хаккару отримати більше влади!",
    C = "Ви набрали голови!  Ви зупинили грабування сили наших богів і послабили Хаккара!$B$BYour дії справді героїчні, $N.  Нехай голови цих рабів-тролів благатимуть вас про пощаду ще довго після того, як їхня кров холоне.",
},

[8221] = {
    en = "Rare Fish - Keefer's Angelfish",
    T = "Рідкісна Риба - Ангельська Риба Кіфера",
    D = "",
