[8232] = {
    en = "The Green Drake",
    T = "Зелений Дракон",
    D = "Тепер я відправляю тебе на небезпечне полювання, щоб убити зеленого дракона, Морфаза, і принести мені його зуб. Морфаз мешкає глибоко в Храмі Атал’Гаккара, вхід до якого розташований у Болоті Скорбот.$B$BЯкщо ти хочеш перемогти його, ти не повинен іти сам. Цей дракон — ворог багатьох — шукай інших, хто бажає його знищити.$B$BЗуб дракона символізує силу, яку мисливець знайде в компанії інших. Принеси його мені, і ти багато чого навчишся.",
    O = "Принесіть Зуб Морфаза до Оґтінка в Азшарі. Оґтінк мешкає на вершині скель на північний схід від Руїн Елдарата.",
    P = "Я бачу мудрість у твоїх очах, $N. Ваше полювання закінчилося?",
    C = "Ти навчився старих способів, $N, і за це я пропоную тобі подарунок з моїх мисливських днів.",
},

[8233] = {
    en = "A Simple Request",
    T = "Просте Прохання",
    D = "Лорд Джорак Рейвенхолдт просить твоєї присутності. Справа секретна, і я не можу сказати більше.$B$BСадиба Рейвенхолдта розташована в Передгір’ях Гіллзбраду — шукай стежку в горах на північний захід від Фортеці Дарнхолд.",
    O = "Поговоріть із Лордом Джораком Рейвенхолдтом у Садибі Рейвенхолдта.",
    P = "",
    C = "Ласкаво просимо, ласкаво просимо!  Будь ласка, $N, сядьте та обговоріть зі мною просту справу.$B$BYou бачите, $N, нещодавно я втратив щось дороге для мене, і, прямо кажучи, я хочу повернути це будь-якою ціною.  У цьому є щось для вас, не хвилюйтеся про це!  О так, щось дуже приємне.$B$BNow, що скажеш, $N... ти готовий до пригод?",
},

[8234] = {
    en = "Sealed Azure Bag",
    T = "Запечатаний Блакитний Мішок",
    D = "Перш за все. Те, що я втратив, — це маленький блакитний мішок, вміст якого є приватною справою.$B$BНе турбуйся про переслідування злодіїв, адже вони вже мертві. Ми знаємо, що ці дурні не змогли відкрити мішок, тож вони продали його якомусь шаману Деревородів в Азшарі як священну реліквію. Хитро.$B$BМені потрібно, щоб ти вирушив до Азшари і забрав його у шамана хитрістю... або силою. Я б поставив на перший метод, удачі тобі. Як тільки отримаєш, віднеси його до Архіма Xylema.",
    O = "Дістаньте Запечатаний Блакитний Мішок у Шамана Деревородів в Азшарі. Потім віднесіть мішок до Архіма Xylema, якого також можна знайти в Азшарі.",
    P = "я тебе знаю",
    C = "Я бачу, що у вас є сумка лорда Рейвенхолдта. Чому ти не сказав, хлопче?",
},

[8235] = {
    en = "Encoded Fragments",
    T = "Закодовані Фрагменти",
    D = "Лорд Рейвенхолдт попросив нас обох про послугу. Він хоче зняти чари з цього мішка.$B$BНа жаль, деякі мої книги про зняття чар нещодавно були вкрадені, а потім знищені дикунами. Залишки моїх книг все ще мають для мене цінність.$B$BЯкщо ти зможеш принести мені достатньо закодованих фрагментів, я зможу зібрати їх докупи. Твій найкращий шанс — убивати лісових слизнів, адже вони мають тенденцію підбирати майже все. Ти знайдеш їх на північному сході Азшари.",
    O = "Принесіть 10 Закодованих Фрагментів до Архіта Xylema в Азшарі.",
    P = "Ви знайшли достатньо фрагментів, щоб продовжити мою роботу?",
    C = "Здається, ви підібрали кілька кращих фрагментів. Можливо, ви все-таки не нікчемні.",
},

[8236] = {
    en = "The Azure Key",
    T = "Блакитний Ключ",
    D = "Розшифрування фрагментів і зняття чар займе деякий час. Коли я закінчу, я особисто доставлю мішок до Лорда Рейвенхолдта.$B$BЗалишається ще справа ключа, який, кажуть, тримає зелений дракон на ім’я Морфаз. Дракон оселився глибоко в Храмі Атал’Гаккара, вхід до якого розташований у Болоті Скорбот.$B$BЗбери своїх друзів і вирушай до його лігва. Лорд Рейвенхолдт чекатиме твого повернення з ключем.",
    O = "Поверніть Блакитний Ключ до Лорда Джорака Рейвенхолдта.",
    P = "Сумка вже надійшла від архімага Ксилема, ти знайшов ключ?",
    C = "Ключ! Я думав, що втрачено назавжди. Будь ласка, візьміть зачарований одяг із моїх магазинів — вони зарезервовані для шахраїв із винятковою майстерністю та вірністю. Треба знати, що з $N не можна жартувати!$B$B<Йорах відкриває сумку, і його зсередини омиває золоте сяйво. Його очі розширюються і він дивиться...>",
},

