[8273] = {
    en = "Oran's Gratitude",
    T = "Подяка Орана",
    D = "",
    O = "",
    P = "",
    C = "Хіба це не цікаво? Ви кажете, що знайшли цю табличку на маленькому безлюдному острові на Скелях Оверлук у Внутрішніх Землях, $C? Справді дуже цікаво. <Оран обережно відкладає планшет і потирає руки.>$B$BI дякую за ваші зусилля в цій справі. Наша Темна Леді буде дуже рада цьому відкриттю. Ось дозвольте винагородити вас пропорційно.",
},

[8274] = {
    en = "",
    T = "Тестове Завдання на Убивство",
    D = "Маєте трохи вільного часу? Убийте мені кількох мурлоків, і я дам вам щось блискуче!",
    O = "Убийте 5 мурлоків і поверніться до тестового персонажа.",
    P = "",
    C = "",
},

[8275] = {
    en = "Taking Back Silithus",
    T = "Повернення Сілітісу",
    D = "Увага, герої Альянсу! Загроза сілітідів залишалася без належного контролю занадто довго. Не стримувані жодним серйозним опором, вони весь цей час готувалися до масштабного розширення.$B$BСили Кенарійського Кругу збираються в Сілітісі, щоб виступити проти цих мерзенних створінь, і всі здатні до бою авантюристи закликаються приєднатися до нас!$B$BНе чекайте, доки буде запізно! Допоможіть нам у захисті Азероту! Доповідайте до Закликача Вітру Гордогрива у Фортеці Кенарія для отримання конкретних інструкцій!",
    O = "Поговоріть із Закликачем Вітру Гордогривом у Фортеці Кенарія в Сілітісі.",
    P = "",
    C = "Чудово, новобранець відповідає на заклик до зброї проти силітідів. Ласкаво просимо до Крепості Кенаріону, $C. Мені приємно бачити, що слова наших емісарів доходять до героїв вашого рівня. Тут у вас не бракує можливостей допомогти нам у наших зусиллях, і я сподіваюся, що ви швидко станете цінним союзником у нашій справі.",
},

[8276] = {
    en = "Taking Back Silithus",
    T = "Повернення Сілітісу",
    D = "Увага, чемпіони Орди! Є загроза, яку ми залишали без уваги занадто довго. Тремтіння землі поблизу гнізд сілітідів по всьому Азероту сповістили нас про великі пересування в їхніх лавах, коли вони готуються до розширення.$B$BСили Кенарійського Кругу збираються в Сілітісі, щоб виступити проти сілітідів, доки не стало запізно! Більше вони не осквернятимуть наші землі!$B$BУсі здатні до бою воїни мають доповісти Закликачу Вітру Гордогриву у Фортеці Кенарія! Сілітіди будуть знищені!",
    O = "Поговоріть із Закликачем Вітру Гордогривом у Фортеці Кенарія в Сілітісі.",
    P = "",
    C = "Чудово, новобранець відповідає на заклик до зброї проти силітідів. Ласкаво просимо до Крепості Кенаріону, $C. Мені приємно бачити, що слова наших емісарів доходять до героїв вашого рівня. Тут у вас не бракує можливостей допомогти нам у наших зусиллях, і я сподіваюся, що ви швидко станете цінним союзником у нашій справі.",
},

[8277] = {
    en = "Deadly Desert Venom",
    T = "Смертельна Пустельна Отрута",
    D = "Бітікс Фіклеспраґ до ваших послуг! Мій кузен Ноґґл заробляє на життя, збираючи рідкісні трави для алхіміків Фортеці Кенарія. Точніше, заробляв. Він повернувся з останньої подорожі з сильною отрутою, що тече в його жилах.$B$BМені вдалося сповільнити дію отрути, але щоб повністю її нейтралізувати, мені потрібні зразки отрути від того, що його вжалило.$B$BНоґґл прибув із півночі, тож я б поставив свою сорочку на те, що це зробили скорпиди кам’яного хвоста або піщані бродяги. Принеси мені кілька жало та іклів, і я спробую зробити протиотруту для нього.",
    O = "Бітікс Фіклеспраґ у Фортеці Кенарія в Сілітісі хоче, щоб ви зібрали 8 Жало Скорпида Кам’яного Хвоста та 8 Іклів Піщаного Бродяги. Поверніться до неї, коли виконаєте завдання.",
    P = "Ви закінчили збирати ці зразки?  Ми можемо втратити Ноґля будь-якої хвилини!",
    C = "Хрести пальці, друже!  Сподіваюся, ми зможемо врятувати Ноґла!",
},

[8278] = {
    en = "Noggle's Last Hope",
    T = "Остання Надія Ноґґла",
    D = "Прокляття! Протиотрута не подіяла. Ноґґла, мабуть, ужалила одна з сильніших істот на далекому півдні.$B$BМені потрібно, щоб ти вирушив туди і добув мені ще зразків, $N. Хороша новина в тому, що через більшу силу їхньої отрути мені не знадобиться так багато. Погана новина — у південній зоні повзає більше видів отруйних створінь, тож тобі доведеться брати зразки з різних джерел.",
    O = "Бітікс Фіклеспраґ у Фортеці Кенарія в Сілітісі хоче, щоб ви зібрали 3 Жала Скорпида-Клешнехвоста, 3 Жала Скорпида-Шкуродера та 3 Ікла Скельного Переслідувача.",
    P = "Це наш останній шанс врятувати Ноґля!  Поспішайте!",
    C = "так!  Здається, це працює, Ноггл приходить до тями.  Ми вам у великому боргу!",
},

[8279] = {
    en = "The Twilight Lexicon",
    T = "Лексикон Сутінків",
    D = "Молот Сутінків не надто добрий до тих, хто покидає їхні лави. Вони полюють на мене й досі, наче я якась звірина! Зайве казати, що ворог їхній — мій друг!$B$BЩоб розшифрувати цю табличку, мені потрібна книга, яку використовують їхні писарі для кодування таємних повідомлень: Лексикон Сутінків. Це настільки важливий інструмент, що вони тримають його три розділи в різних місцях! Офіцери, яким довірено Лексикон, відомі як Хранителі Сутінків, шукай їх у таборах Молота Сутінків.",
    O = "Принесіть три розділи Лексикону Сутінків до Відлюдника Ортелла в Сілітісі.",
    P = "Хто туди йде?  О, це ти!  Ви вже знайшли всі розділи Лексикону?",
    C = "так! Це частини книги!  Тоді давайте почнемо, $N.$B$BSwap кожне третє слово зі словами з другого розділу... потім поміняйте кожне інше слово словами з першого розділу... Зачекайте, я зрозумів це навпаки?",
},

[8280] = {
    en = "Securing the Supply Lines",
    T = "Захист Лінії Постачання",
    D = "Фортеця Кенарія — це місце надзвичайної стратегічної важливості. Я переконаний, що доки ми її утримуємо, наша перемога над сілітідами гарантована. За умови, звичайно, що ми зможемо підтримувати приплив припасів.$B$BПустельні черви виявилися більшою загрозою для наших караванів із припасами, ніж навіть самі сілітіди. Лише цього ранку велика партія ранкової роси була знищена групою піщаних ударників. Мені потрібно, щоб ти прорідив їхні лави, щоб наші припаси не опинилися під загрозою.",
    O = "Закликач Вітру Гордогрив у Фортеці Кенарія в Сілітісі хоче, щоб ви зарубали 15 Піщаних Ударників.",
    P = "Земснаряди є серйозною загрозою, і з ними потрібно швидко боротися!",
    C = "Вам моя щира подяка.  Ваші зусилля, спрямовані на допомогу Крепості Кенаріону, показали справжню мужність.",
},

[8281] = {
    en = "Stepping Up Security",
    T = "Посилення Безпеки",
    D = "Твої дії досі були справді зразковими, $N. Проте наші лінії постачання ще не в повній безпеці. Без піщаних ударників їхні більші південні родичі неодмінно займуть їхнє місце на півночі.$B$BТобі доведеться зарубати чимало піщаних дробильників, щоб стримати їх, але ми не можемо залишати безпеку наших ліній постачання на волю випадку.",
    O = "Закликач Вітру Гордогрив у Фортеці Кенарія в Сілітісі хоче, щоб ви зарубали 20 Піщаних Дробильників.",
    P = "Земснарядні дробарки становлять серйозну загрозу, з якою потрібно боротися негайно!",
    C = "Чудово!  Ви виявилися цінним союзником у підготовці до війни проти силітідів.",
},

[8282] = {
    en = "Noggle's Lost Satchel",
    T = "Загублена Сумка Ноґґла",
    D = "Де я? Де моя сумка? *зітхає* Мабуть, я загубив її, коли тікав від Смертоклешня, гігантського скорпида. У поспіху я влетів прямо в гніздо кам’янохвостих шкуродерів.$B$BУ тій сумці було багато рідкісних реагентів. Без них ми з Бітікс не зможемо зробити зілля, які потрібні Фортеці Кенарія. Я ще занадто слабкий, щоб піднятися, але можу зробити так, щоб твої зусилля того вартували, якщо ти повернеш мої реагенти.$B$BЯ зіткнувся зі Смертоклешнем у південному гірському хребті, позаду табору Бронзобородих.",
    O = "Добудьте Сумку Ноґґла з гір на півдні Сілітісу та поверніть її до нього у Фортецю Кенарія.",
    P = "Все ще не знайшли свою сумку?  Що ж, я повинен порахувати свої щасливі зірки, принаймні отруту очистили.",
    C = "так!  Ти повернув мій ранець.  І всі мої рідкісні реактиви тут!  Я довго буду у вашому боргу.",
},

[8283] = {
    en = "Wanted - Deathclasp, Terror of the Sands",
    T = "Розшукується - Смертоклешень, Жах Пісків",
    D = "Жахливий скорпид, Смертоклешень, вважається, що відступив до південного гірського хребта через зростання активності сілітідів. Він становить велику загрозу для патрулів та експедицій у південних регіонах. Особи, які візьмуть участь у його знищенні, будуть щедро винагороджені. Зверніться до Капітана Віша Козуса, на вершині Вартівлі Фортеці Кенарія, щодо нагороди.",
    O = "Принесіть Клешню Смертоклешня до Віша Козуса, Капітана Варти.",
    P = "Мені знадобляться кліщі істоти як доказ вчинку. Ні кліщів, ні винагороди.",
    C = "Чудово! Коли Deathclasp зник, ми можемо використовувати південний гірський хребет як стратегічний шлях для обходу вуликів силітидів. Ваша робота дуже цінується.",
},

[8284] = {
    en = "The Twilight Mystery",
    T = "Таємниця Сутінків",
    D = "Табір культу Молота Сутінків колись процвітав на північний захід звідси. Якби ти вирушив туди зараз, ти б побачив, що місцевість кишить елементалями, а від табору залишилися лише розкидані шматки дерева та полотна.$B$BЯ знайшов кілька уламків глиняної таблички на тому місці, але їх занадто мало, щоб скласти щось корисне. Спробуй знайти решту уламків таблички, щоб ми могли пролити світло на присутність Молота Сутінків тут, у Сілітісі.",
    O = "Геолог Ларкбейн у Фортеці Кенарія в Сілітісі хоче, щоб ви зібрали 8 Уламків Таблички Сутінків.",
    P = "Зруйнований табір можна знайти на північний захід звідси.  Поверніться, коли будете мати всі фрагменти.",
    C = "Як я і підозрював.  Я можу розшифрувати окремі слова на табличках, але вони здаються позбавленими будь-якої логіки чи сенсу.  Невідомо, що секти Сутінкового молота використовують код, щоб приховати значення своїх текстів; нам доведеться звернутися до когось, хто знає більше про такі речі.",
},

[8285] = {
    en = "The Deserter",
    T = "Дезертир",
    D = "Ходять чутки, що член Молота Сутінків на ім’я Ортелл дезертирував із їхнього культу. Кажуть, він переховується в горах на південь від Південновітрового Селища, де живе відлюдником. Можливо, ти зможеш заручитися його допомогою у розшифруванні таблички.$B$BВізьми відновлену табличку та знайди Ортелла.",
    O = "Віднесіть відновлену табличку до Відлюдника Ортелла в Сілітісі.",
    P = "Ви!  Як ти мене знайшов?  ти хто  За вами не стежили, чи не так?  говори!",
    C = "Я бачу, що ви знайомі з моєю старою організацією.  Ви маєте бути з Кенарійської форти.  $B$BYou шукати інформацію для використання проти них?  Підходь ближче, можливо, ми зможемо взаємно допомогти.",
},

[8286] = {
    en = "What Tomorrow Brings",
    T = "Що Принесе Завтра",
    D = "Обійми смерті майже повністю поглинули мою сутність, коли він втрутився. Він лише раз дихнув на моє понівечене тіло і терпляче чекав, доки піски часу зцілять мої рани.$B$B«Ти залишишся назавжди, якщо мусиш», — сказав він, і цими словами я був зв’язаний як Спостерігач.$B$BПоглянь тепер на пустелю. Друга війна наближається. Ти мусиш знайти місце спочинку Бронзових. Вирушай до Печер Часу і перевір, чи повернувся господар. Я мушу бути впевненим, перш ніж зможу продовжити.",
    O = "Вирушайте до Печер Часу в Танарісі та знайдіть Анахроноса, нащадка Ноздорму.",
    P = "Анахрон повернувся?",
    C = "Так і має бути — великий воскрес. Мій годинник добігає кінця...",
},

[8287] = {
    en = "A Terrible Purpose",
    T = "Жахлива Мета",
    D = "Гаразд, ось ми... досить цінна інформація, мушу сказати! Я бачив, як сили Кенарійського Кругу прибули до Сілітісу. Вони планують вигнати Молот Сутінків, чи не так? Це допоможе.$B$BВіднеси цей пергамент їхньому лідеру, Командиру Мар’аліт. Незабаром Молот Сутінків буде знищений, і я нарешті буду поза їхньою досяжністю назавжди!",
    O = "Віднесіть Розшифрований Пергамент Таблички до Командира Мар’аліта.",
    P = "Що це ти приніс мені, $N?",
    C = "Це справді дуже цікава інформація, $N.  Це проливає світло на присутність Сутінкового Молота в Сілітусі та, безсумнівно, допоможе нам у боротьбі з ними.  Ваші зусилля будуть щедро винагороджені, $C.",
},

[8288] = {
    en = "Only One May Rise",
    T = "Лише Один Може Піднятися",
    D = "Немає часу гаяти! Треба знайти героя! Завдання, яке я дам, потребуватиме цілої армії, але лише один може піднятися з натовпу охочих чемпіонів, щоб узяти на себе тягар і відповідальність союзника Виводу.$B$BУ лігві Володаря Чорнокаменя ховається надзвичайно жорстока істота. Лорд Виводу Плетохльост охороняє Зали Суперечок, блокуючи шлях до внутрішнього святилища Нефаріана. Убий цього мерзенного виродка і принеси мені його голову. Зроби це, і ти зможеш розпочати наступний етап своєї подорожі.",
    O = "Поверніть Голову Лорда Виводу Плетохльоста до Барістольта Перемінних Пісків у Фортеці Кенарія в Сілітісі.",
    P = "Ви повинні заслужити прихильність Роду Ноздорму.",
    C = "Чи можете ви бути першим, хто заслужить прихильність серед Бронзової Ватаги ЗА тисячу років?",
},

[8289] = {
    en = "Talismans of Merit",
    T = "Талісмани Заслуг",
    D = "",
    O = "",
    P = "",
    C = "",
},

[8290] = {
    en = "Vanquish the Invaders",
    T = "Здолайте Загарбників",
    D = "За цим тунелем ти знайдеш поле боротьби та хаосу, юний $c. Орда продовжує нищити наш священний ліс, вирубуючи вічнозелену рослинність, щоб живити свої машини війни.$B$BУвійди до Ущелини Пісні Війни та захисти Форт Срібнокрилих. Відкинь війська Орди, що вторглися!$B$BЗроби це і здобудь талісман заслуг. Принеси мені такий талісман, $N, і я винагороджу тебе.",
