[8297] = {
    en = "Arathi Basin Resources!",
    T = "Ресурси Ущелини Араті!",
    D = "Війну потрібно вести солдатами, це тобі скаже будь-який солдат. Вони також скажуть, що битва, проведена з поганим спорядженням або на голодний шлунок, програна ще до її початку!$B$BОсь чому Ущелина Араті така важлива. У цій долині є ключові точки, що містять необхідні ресурси. Метали, зброя, їжа, деревина — усе це потрібно, і усе це можна здобути там.$B$BЦе те, що я хочу від тебе, $N. Увійди до Ущелини Араті, виграй битву, утримуючи більше баз, ніж ворог, і повернись до мене зі скринею ресурсів.",
    O = "Виграйте битву за Ущелину Араті, отримайте Скриню Ресурсів Араті і поверніться до Сержанта Макліра в Табір Прихистку.",
    P = "У вас є ящик із ресурсами, $N? Ліга Аратору не може вести гідну битву без них...",
    C = "У вас є ресурси! Чудова робота! Я надішлю ресурси нашим квартирмейстерам, які можуть швидко розпорошити їх серед наших військ.$B$BThank ти, $N. Дійсно, виконання успішних місій, подібних до вашої, — це те, як справді виграються війни.",
},

[8298] = {
    en = "More Resource Crates",
    T = "Більше Скринь із Ресурсами",
    D = "Війну потрібно вести солдатами, це тобі скаже будь-який солдат. Вони також скажуть, що битва, проведена з поганим спорядженням або на голодний шлунок, програна ще до її початку!$B$BОсь чому Ущелина Араті така важлива. У цій долині є ключові точки, що містять необхідні ресурси. Метали, зброя, їжа, деревина — усе це потрібно, і усе це можна здобути там.$B$BЦе те, що я хочу від тебе, $N. Увійди до Ущелини Араті, виграй битву, утримуючи більше баз, ніж ворог, і повернись до мене зі скринею ресурсів.",
    O = "Виграйте битву за Ущелину Араті, отримайте Скриню Ресурсів Араті і поверніться до Сержанта Макліра в Табір Прихистку.",
    P = "$N, Ліга Аратора має постійну місію, щоб ви знову увійшли в басейн Араті, роздобули більше ящиків із ресурсами та принесли їх мені.",
    C = "Дуже добре. Я негайно передам їх нашим інтендантам, а подяка за ваші дії буде надіслана моєму начальству.$B$BOnce ще раз, дякую $N. Ваш внесок у нашу боротьбу помічений і лакеєм, і фельдмаршалом.",
},

[8299] = {
    en = "Cut Arathor Supply Lines",
    T = "Переріжте Лінії Постачання Аратору",
    D = "Ліга Аратору не шкодує зусиль у своїй спробі повернути Араті. Вони, разом з усіма расами Альянсу, нині стікаються до цього віддаленого регіону, маючи намір розширити свій вплив із Табору Прихистку. Ми повинні зупинити їх, і найкращий спосіб це зробити — забрати їхні припаси.$B$BТи можеш нам допомогти, $N. Увійди до Ущелини Араті, відомої своїми багатими копальнями, родючими землями та вправними ремісниками. Захоплюй і контролюй усі бази, які зможеш, виграй битву і повертайся до мене з ресурсами, які ти здобудеш.",
    O = "Виграйте битву за Ущелину Араті, отриміть Скриню Ресурсів Араті і поверніться до Смертоносця Мортіса в Молотозгуб.",
    P = "",
    C = "",
},

[8300] = {
    en = "More Resource Crates",
    T = "Більше Скринь із Ресурсами",
    D = "Ліга Аратору не шкодує зусиль у своїй спробі повернути Араті. Вони, разом з усіма расами Альянсу, нині стікаються до цього віддаленого регіону, маючи намір розширити свій вплив із Табору Прихистку. Ми повинні зупинити їх, і найкращий спосіб це зробити — забрати їхні припаси.$B$BТи можеш нам допомогти, $N. Увійди до Ущелини Араті, відомої своїми багатими копальнями, родючими землями та вправними ремісниками. Захоплюй і контролюй усі бази, які зможеш, виграй битву і повертайся до мене з ресурсами, які ти здобудеш.",
    O = "Виграйте битву за Ущелину Араті, отриміть Скриню Ресурсів Араті і поверніться до Смертоносця Мортіса в Молотозгуб.",
    P = "$N, Осквернителі мають постійну місію, щоб ви знову увійшли в басейн Араті, роздобули більше ящиків із ресурсами та принесли їх мені.",
    C = "Дуже добре. Я негайно передам їх нашим інтендантам, а подяка за ваші дії буде надіслана моєму начальству.$B$BOnce ще раз, дякую $N. Ваш внесок у нашу боротьбу помічають як бурчання, так і верховний воєначальник.",
},

[8301] = {
    en = "The Path of the Righteous",
    T = "Шлях Праведних",
    D = "Вивід Ноздорму за своєю природою не довіряє нижчим расам. Хоча ти довів мені, що маєш задатки героя, настав час довести це моєму господарю.$B$BВулик’Аші, Вулик’Зора, Вулик’Реґал: усі кишать активністю і всі становлять загрозу нашому існуванню. Убивай сілітідів у цих вуликах і бери з них фрагменти їхнього панцира. Коли не зможеш нести більше, повертайся до мене, і я зміцню твою рішучість.",
    O = "Зберіть 200 Фрагментів Панцира Сілітідів і поверніться до Барістольта.",
    P = "Є багато історії, що корениться в їх недовірі до смертних рас; але, на жаль, таку історію краще залишити для Виводка, щоб вона розказала, коли настане відповідний час.",
    C = "Ти не один, герой. Тепер я дам вам можливість заміщати інших, щоб допомогти вам у ваших пошуках. Якщо ви хочете бути захисником свого народу, вам знадобиться допомога у виконанні завдань і обов’язків.",
},

[8302] = {
    en = "The Hand of the Righteous",
    T = "Рука Праведних",
    D = "Обирай своїх помічників мудро, смертний. Щоразу, коли ти повертатимешся із виконаним завданням, ти зможеш обрати нового помічника.$B$BЗ урахуванням цього, мені потрібно більше фрагментів панцира. Не гай часу!",
    O = "Зберіть 200 Фрагментів Панцира Сілітідів і поверніться до Барістольта.",
    P = "Можливо, одного дня під вашим командуванням буде працювати весь Кенарійський холд.",
    C = "Молодець, герой. Тепер вам буде надано можливість замінити іншого агента Ноздорму.",
},

[8303] = {
    en = "Anachronos",
    T = "Анахронос",
    D = "Настав час, $N.$B$BМушу вибачитися за те, що тримав стільки в таємниці. Вороги чатують скрізь, навіть під нашим носом. Прошу, прочитай цей том і навчись. Візьми знання, які я тобі даю, і знайди нашого господаря.",
    O = "Знайдіть Анахроноса в Печерах Часу в Танарісі.",
    P = "",
    C = "Ти надія Калімдору, $N.",
},

[8304] = {
    en = "Dearest Natalia",
    T = "Найдорожча Наталія",
    D = "Моя дорога Наталія зникла.$B$BПравду кажучи, вона поводилася дивно протягом кількох тижнів перед своїм зникненням. Я не раз застав її за розмовою із собою, коли нікого не було поруч. Вона наполягала, що все гаразд і що їй потрібно дозволити продовжувати свої дослідження.$B$BОстаннє, що я чув, вона вирушила до табору Бронзобородих на південь.$B$BМої солдати надто розпорошені, $N. Мені потрібно, щоб ти вирушив до табору Бронзобородих і розпитав тих дворфів.",
    O = "Командир Мар’аліт у Фортеці Кенарія в Сілітісі хоче, щоб ви розпитали мешканців Табору Бронзобородих. Ви знайдете Табір Бронзобородих на південь від Фортеці Кенарія.$B$BКоли зберете потрібну інформацію, поверніться до Командира Мар’аліта.",
    P = "Не гайте часу, $N!",
    C = "<Командир Мар'аліт задумливо опускає голову.>$B$BWhether жива вона чи мертва, я повинен робити те, що правильно. Її треба знайти. На жаль, я пов'язаний обов'язком з цим форпостом. Допоможеш мені ще раз, $N?",
},

[8305] = {
    en = "Long Forgotten Memories",
    T = "Давно Забуті Спогади",
    D = "У південній пустелі Сілітісу, біля священного бар’єру, існує єдина кристальна сльоза. Ця сльоза є символом великих втрат, яких ми зазнали під час Війни Перемінних Пісків. Знайди цю сльозу і вдивися в її глибини, щоб отримати просвітлення.",
    O = "Знайдіть Кристальну Сльозу в Сілітісі та вдивіться в її глибини.",
    P = "",
    C = "Ви можете відчути велике горе, що обертається навколо цього кристала. Сила настільки потужна, що ви відчуваєте, ніби можете впасти й померти від смутку.",
},

[8306] = {
    en = "Into The Maw of Madness",
    T = "У Пасть Божевілля",
    D = "Мені потрібно, щоб ти вирушив до Вулика’Реґал і дізнався, що сталося з моєю найдорожчою Наталією, $N. Це завдання буде нелегким, якщо ти підеш сам. Рекомендую взяти із собою друзів. Перш ніж кинутися стрімголов у пащу божевілля, обов’язково повернись і поговори з тими дворфами. Вони можуть дати тобі кілька порад, як впоратися із сілітідами, що населяють той вулик.$B$BІ $N, якщо вона дійсно така божевільна, як кажуть... зроби те, що мусиш.$B$B<Командир Мар’аліт відвертається від тебе.>",
    O = "Командир Мар’аліт у Фортеці Кенарія в Сілітісі хоче, щоб ви знайшли його кохану Наталію. Інформація, яку ви зібрали, вказує на Вулик’Реґал на півдні як місце, де ви можете знайти Пані Наталію Мар’аліт.$B$BНе забудьте відвідати дворфів у таборі Бронзобородих перед тим, як вирушити до вулика. У них можуть бути додаткові завдання та поради для вас.$B$BІ $N, пам’ятайте слова Командира: «Зроби те, що мусиш...»",
    P = "Наталя?",
    C = "<Командир Мар'аліт хапається за груди.>$B$BC'Тун? ЯКИЙ у всьому цьому сенс? Що таке C'Thun? Як цей диявол міг перетворити мою милу Наталю на монстра, якого ти описав?",
},

[8307] = {
    en = "Desert Recipe",
    T = "Пустельний Рецепт",
    D = "Пристосуватися до життя в пустелі було, м’яко кажучи, нелегко. Мені не вистачає птахів і дерев Обердіна, але наш вибір їжі серйозно обмежений цим посушливим середовищем. Я намагаюся дізнатися про пустельні трави, але їх тут небагато.$B$BЯ бачила, як групи Молота Сутінків із табору на захід звідси полюють на піщаних червів заради їжі. М’ясо піщаних червів таке гірке, що я не можу уявити, як вони роблять його їстівним. Тримай очі відкритими, якщо підеш до їхнього табору, і дай мені знати, якщо щось дізнаєшся.",
    O = "Шукайте інформацію про приготування М’яса Піщаного Червяка в таборі Молота Сутінків на захід від Фортеці Кенарія.",
    P = "",
    C = "Ця книга містить кілька поширених рецептів і кілька незвичайних. Переглядаючи його кілька секунд, ви бачите рецепт із м’ясом піщаного хробака.",
},

[8308] = {
    en = "Bra$b$b Bronzebeard's Lost Letter",
    T = "Загублений Лист Бранна Бронзобородого",
    D = "До Кого Це Може Стосуватися:$B$BЯкщо ви читаєте це, я або мертвий, або скоро буду мертвим. Важко сказати. Більшість команди вже загинула.$B$BЗнайшов інформацію про Титана. Велика битва між ним і Старим Богом. Так, справжнім Старим Богом. Знайшов стародавній тунель, що веде до Ан’Кіража. Беру його.$B$BВіднесіть цього листа до мого старого табору. Переконайтеся, що моя мавпа отримує достатньо їжі, води та обіймів.$B$B-Бранн Бронзобородий, Екстремальний Дослідник$B$P.S. Остерігайтеся божевільної нічної ельфійки, що поклоняється Старому Богу.",
    O = "Віднесіть Лист Бранна Бронзобородого до Табору Бронзобородих у південному Сілітісі.",
    P = "О, боже!",
    C = "Ну, це багато чого пояснює. Якщо ви коли-небудь знайдете дорогу в Ан'Кіраж, стежте за старим Бранном. Я боюся, що він буде безсилий без своєї мавпи.",
},

[8309] = {
    en = "Glyph Chasing",
    T = "Погоня за Гліфами",
    D = "Після нашого першого рейду до вуликів і подальшого божевілля Пані Мар’аліт три вулики почали вивергати комах! Зростання активності може бути пов’язане з гліфами, що покривають ці дивні кристали.$B$BМи мусимо отримати відбитки з кристалів у всіх трьох вуликах. Якщо ми зможемо дістати ці відбитки, ми, можливо, зможемо розібратися в цьому божевіллі.$B$BВізьми цей набір для транскрипції та кількох друзів і вирушай до тих вуликів, $N. Не повертайся, доки не отримаєш копії з кожного вулика.",
    O = "Рутґар Гліфошейпер у Таборі Бронзобородих у Сілітісі хоче, щоб ви вирушили до Вулика’Аші, Вулика’Зора та Вулика’Реґал і здобули Гліфовані Відбитки з Гліфованих Кристалів кожного вулика.$B$BВикористовуйте Набір для Транскрипції Геолога, щоб зробити прийнятну копію стародавніх гліфів. Поверніться до Рутґара Гліфошейпера, коли виконаєте це завдання.",
    P = "Якщо ви знайдете божевільну дівчину нічного ельфа в одному з вуликів, не забудьте дати їй стусан за нас.",
    C = "Я не можу зробити голови чи хвости цих гліфів. Я ніколи не бачив нічого подібного! Я сподіваюся, що дослідження Франкала проллють світло на цей безлад.",
},

[8310] = {
    en = "Breaking the Code",
    T = "Розшифровка Коду",
    D = "Я думаю, що можу створити еліксир, який дозволить нам легше розшифровувати гліфи та мову сілітідів і Кіраджі! Що мені потрібно? Радий, що ти запитав! Мені потрібні мізки! А саме, по одному мозку від кожного типу сілітідів, що населяють вулики. Принеси мені мізки, і праця Рутґара не буде марною.",
    O = "Франкал Кам’яний Міст у Таборі Бронзобородих у Сілітісі хоче, щоб ви здобули Мозок Сілітіда Вулика’Зора, Мозок Сілітіда Вулика’Аші та Мозок Сілітіда Вулика’Реґал. Поверніться до Франкала, коли виконаєте це завдання.",
    P = "Іди пограйся з мавпою, хлопче. У мене немає на це часу.",
    C = "Видатний! Не відходь надто далеко, дитино. Можливо, вам знадобиться виконати ще одне чи два завдання.",
},

[8311] = {
    en = "Hallow's End Treats for Jesper!",
    T = "Ласощі Гелловіну для Джеспера!",
    D = "Я хочу піти на солодощі чи пустощі, але не можу, бо я хворий. Якщо ти підеш за мене, я обміняю цукерки, які ти збереш, на ті, що в мене вже є! Думаю, тобі сподобаються ці цукерки — вони змушують тебе перетворюватися на кумедні та страшні речі!$B$BКожен із трактирників у великих містах має цукерки, які вони дають на Гелловін — поговори з ними та виконай трюки, які вони просять! Також маленький гном на ім’я Талваш у Залізогарті роздає цукерки. Коли збереш усі цукерки, принеси їх мені сюди!",
    O = "Поговоріть із трактирниками Штормовію, Залізогарта та Дарнаса, а також із Талвашем дель Кісселем у Залізогарті. Виконайте трюки, які вони просять, в обмін на ласощі, які вони пропонують.$B$BПоверніться до Джеспера в Притулок Штормовію з Дарнаським Марципаном, Ґномреґанською Карамелькою, Штормовійським Нугою та Залізогартською М’ятою.",
    P = "Ви вже покінчили з пригощанням?  Мені сумно, що я не можу піти, тому що я хворий, але завдяки тому, що ти мені допомагаєш, я відчуваю себе трохи краще...",
    C = "Ого, ти їх усіх отримав!  Ви чудові!$B$BThank за те, що ви потішили мене.  Ось візьміть ці гарбузові ласощі – я думаю, вони вам дуже сподобаються!$B$BHappy Hallow's End, $N!",
},

[8312] = {
    en = "Hallow's End Treats for Spoops!",
    T = "Ласощі Гелловіну для Спупса!",
    D = "Я хочу піти на солодощі чи пустощі, але не можу, бо я хворий. Якщо ти підеш за мене, я обміняю цукерки, які ти збереш, на ті, що в мене вже є! Думаю, тобі сподобаються ці цукерки — вони змушують тебе перетворюватися на кумедні та страшні речі!$B$BКожен із трактирників у великих містах має цукерки, які вони дають на Гелловін — поговори з ними та виконай трюки, які вони просять! Також троль на ім’я Калі Ремік у Селі Сен’джін роздає цукерки. Коли збереш усі цукерки, принеси їх мені сюди!",
    O = "Поговоріть із трактирниками Орґріммара, Підмістя та Громового Бескиду, а також із Калі Реміком у Селі Сен’джін. Виконайте трюки, які вони просять, в обмін на ласощі, які вони пропонують.$B$BПоверніться до Спупса в Притулок Орґріммара з Марципаном Громового Бескиду, Карамелькою Темного Списа, Нугою Орґріммара та М’ятою Підмістя.",
    P = "Ви вже покінчили з пригощанням?  Мені сумно, що я не можу піти, тому що я хворий, але завдяки тому, що ти мені допомагаєш, я відчуваю себе трохи краще...",
    C = "Ого, ти їх усіх отримав!  Ви чудові!$B$BThank за те, що ви потішили мене.  Ось візьміть ці гарбузові ласощі – я думаю, вони вам дуже сподобаються!$B$BHappy Hallow's End, $N!",
},

[8313] = {
    en = "Sharing the Knowledge",
    T = "Ділитися Знаннями",
    D = "Хоча рецепт приготування м’яса піщаного червяка читається, він містить згадки про трави та спеції, про які ти ніколи не чув. Каландрат, можливо, має достатньо знань про рослини, що ростуть у пустелі, щоб розібратися в цьому.",
    O = "Принесіть Порваний Аркуш Рецепту до Каландрат у таверні Фортеці Кенарія.",
    P = "Ви вивчили рецепт?  Сподіваюся, ви не будете тримати це в собі!",
    C = "Давайте подивимося на це...$B$BThis здається досить простим.  Вони мають власні назви для деяких трав, але їх досить просто зрозуміти.  Ось, дай я тобі покажу!",
},

[8314] = {
    en = "Unraveling the Mystery",
    T = "Розгадка Таємниці",
    D = "Ми на порозі прориву, $N! Відбитки, які ти здобув, дозволили нам відтворити гліфи на цьому кристальному призматі. Вони, очевидно, є засобом для Кіраджі та інших невідомих істот спілкуватися із сілітідами.$B$BНа жаль, це все, що ми змогли витягти з гліфів. Нам потрібно знайти спосіб розкрити повідомлення, приховані в кристалах.$B$BВіднеси гліфовану кристальну призму до Геолога Ларкбейна у Фортеці Кенарія. Вона, можливо, зможе допомогти.",
    O = "Рутґар Гліфошейпер у Таборі Бронзобородих хоче, щоб ви доставили Гліфовану Кристальну Призму до Геолога Ларкбейна у Фортеці Кенарія в Сілітісі.",
    P = "боже! Що у вас там, $N?",
    C = "Причина, чому гноми не змогли розшифрувати гліфи, полягає в тому, що нема чого розшифровувати. Зміщення зовнішнього шару призми має належним чином вирівнятися з маркуванням внутрішнього кристала, щоб повідомлення було передано. Розумно...$B$BWhile ми зможемо перекласти ці дані, спершу потрібно розблокувати код. На поверхні призми є лише одна підказка - якщо припустити, що тертя було передано правильно - і вона виглядає похмуро.",
},

[8315] = {
    en = "The Calling",
    T = "Виклик",
    D = "Гліфи зображують емісара Кіраджі, який зустрічається з трьома сілітідами біля кісток великого дракона. Над гліфами є те, що я можу припустити, якийсь код. Цей код, найімовірніше, є ключем до виклику емісара.$B$BЯ створю копію коду гліфів, яку ти мусиш використати в піску біля Кісток Ґраккаронда. Якщо я правий, Над правителі прийдуть, думаючи, що нові дані готові до передачі. Удар по них і протистань емісару. Він має ключ до кристалів...",
    O = "Геолог Ларкбейн у Фортеці Кенарія в Сілітісі хоче, щоб ви здобули Механізм Розблокування Кристалу у Емісара Кіраджі.$B$BВам доручено взяти Гліфи Виклику до Кісток Ґраккаронда, на південь від Фортеці Кенарія, і накреслити їх у піску. Якщо з’явиться Емісар Кіраджі, зарубайте його і здобудьте Механізм Розблокування Кристалу. Поверніться до Геолога Ларкбейна, якщо вам це вдасться.$B$BЗберіть армію для цього завдання, $N!",
    P = "Ви повинні скористатися можливістю, як вона представляється, і вдарити!",
    C = "Я тримаю в руках 20 000 років історії, $N!",
},

[8316] = {
    en = "Armaments of War",
    T = "Озброєння Війни",
    D = "",
    O = "",
    P = "",
    C = "Приходить війна, $N, а з нею приходять невимовні жахи. Ви зробили все, що від вас могли попросити, і за це ви маєте бути винагороджені.$B$BShould це... це пророцтво коли-небудь здійсниться...$B$B<Геолог Ларксбейн блідне.>$B$BThe майбутньому для нас усіх може бути кінець.$B$BThese озброєння виявиться неоціненним для вашої кампанії в ця пустеля.",
},

[8317] = {
    en = "Kitchen Assistance",
    T = "Допомога на Кухні",
    D = "Цей рецепт точно стане в пригоді. Краще я візьмуся до роботи, щоб сьогодні приготувати трохи копчених пустельних галушок. Мені не завадить допомога в їх приготуванні, і я зроблю так, щоб твої зусилля того вартували.",
    O = "Каландрат у Фортеці Кенарія потребує партію з 10 Копчених Пустельних Галушок.",
    P = "Як ці вареники?",
    C = "Чудово! Ти рятуєш життя. Ці вареники вийшли досить непоганими. Не очікував такого смаку від Сутінкового молота.",
},

[8318] = {
    en = "Secret Communication",
    T = "Таємне Спілкування",
    D = "Деякі культисти Молота Сутінків носять із собою маленькі папірці з написаною на них нісенітницею. Я хочу, щоб ти приніс мені купу таких, $c.$B$BЯ не можу розібратися, що означає ця нісенітниця, але справа не в тому! Ці папірці — це спосіб, яким їхні різні групи таємно спілкуються. Що більше текстів ми вилучимо з обігу, то менше вони зможуть спілкуватися!",
    O = "Принесіть 10 Зашифрованих Текстів Сутінків до Бора Дикогрива у Фортеці Кенарія.",
    P = "Ти приніс мені кілька текстових повідомлень?",
    C = "Чудово!  Я заховаю їх, можливо, вони знадобляться пізніше.",
},

[8319] = {
    en = "Encrypted Twilight Texts",
    T = "Зашифровані Тексти Сутінків",
    D = "",
    O = "",
    P = "Продовжуйте приносити мені повідомлення.  Незабаром ми виженемо Сутінковий Молот із Сілітуса.",
    C = "Відмінна робота!  Я скажу за вас добре слово.",
},

[8320] = {
    en = "Twilight Geolords",
    T = "Геоволодарі Сутінків",
    D = "Молот Сутінків, божевільний культ, що прагне руйнування, влаштував табори в Сілітісі та проводить ритуали вдень і вночі. Ми ще не знаємо їхніх планів, але вважаємо, що вони якось пов’язані з пульсуючими червоними кристалами, розкиданими по пустелі.$B$BХоча їхню таємницю одного дня може бути розкрито, ми спочатку мусимо впоратися з їхньою безпосередньою загрозою. Вирушай до їхніх таборів на захід і шукай Геоволодарів Сутінків. Вони — голови цих змій; саме туди ми мусимо вдарити!",
    O = "Убийте 10 Геоволодарів Сутінків, потім поверніться до Гуума Дикогрива у Фортеці Кенарія.",
    P = "Увійдіть у пустелю та знайдіть Сутінкових геологів, $N. Повернись до мене після того, як їх уб’ють.",
    C = "Це було добре виконане завдання, $N.  Ваше вбивство сутінкових геолордів, мабуть, завдало тяжкого удару культу.  Будемо сподіватися, що їхні плани сповільняться...",
},

[8321] = {
    en = "Vyral the Vile",
    T = "Вірал Поганець",
    D = "Ми виявили ще одну базу операцій Молота Сутінків. Вона називається Сутінковим Бігом; це печера, захована в північно-східному куті Сілітісу. Місцевий лідер культу, Вірал Поганець, переховується в тій печері — саме його ти мусиш перемогти наступним. Коли зробиш це, принеси мені його перстень-печатку.$B$BУдачі тобі, $N. Жахи Сутінкового Бігу справді грізні.",
    O = "Принесіть Перстень-Печатку Вірала до Гуума Дикогрива у Фортеці Кенарія.",
    P = "$N, ти вже переміг Вірала Мерзенного?  У вас є його перстень з печаткою?",
    C = "Ви зробили це!  Вірал убитий!  Це може означати лише загибель для операцій Сутінкового Молота в Сілітусі. Можливо, їх снує більше, але удар, який ви сьогодні завдали культу, є таким, від якого їм нелегко оговтатися.",
},

[8322] = {
    en = "Rotten Eggs",
    T = "Гнилі Яйця",
    D = "Люди Південнобережжя люблять своє ель, і тому вони дуже цінують ель, який подають у таверні Південнобережжя. З хаосом Гелловіну, що нині охопив їх, ми можемо використати це, щоб зіпсувати їхню останню партію напоїв на тижні — якщо не на місяці!$B$BВізьми ці гнилі яйця і поклади їх у головний бочонок із пивом усередині таверни Південнобережжя. Твоя присутність сама по собі викличе конфлікт, тож будь готовий захищатися!$B$BКоли ти даси Південнобережжю смак, який вони незабаром не забудуть, повертайся до мене тут, на фестивалі!",
    O = "Покладіть Гнилі Яйця в головний бочонок із пивом усередині таверни Південнобережжя.",
    P = "",
    C = "Бочонок наповнений елем.$B$BHaving успішно пробився всередину трактиру, тепер ви кладете яйця в бочку. Ви можете відчути неприємний запах, що пронизує повітря...",
},

[8323] = {
    en = "True Believers",
    T = "Справжні Віруючі",
    D = "Тепер, коли Лексикон Сутінків у моїх руках, я хотів би попросити тебе про невеличку послугу.$B$BМоя колишня організація має секретний закодований бюлетень, який вони поширюють щомісяця.$B$BЯкщо вони досягнуть якогось прогресу в пошуках мене або якщо припинять пошуки, інформація про це буде опублікована в «Справжньому Віруючому».$B$BХоча ця інформація, очевидно, цінна для мене, видання містить й іншу корисну інформацію, якою я можу поділитися. Принось мені будь-які закодовані тексти, які знайдеш у членів Молота Сутінків.",
    O = "Відлюдник Ортелл хоче, щоб ви принесли йому 10 Зашифрованих Текстів Сутінків.",
    P = "Ви знайшли якісь зашифровані тексти?  Мені дуже цікаво прочитати True Believer цього місяця.",
    C = "Чудово!  Я приступлю до їх розшифровки якомога швидше.  Якщо я знайду щось цікаве, я знайду спосіб передати вам інформацію.",
},

[8324] = {
    en = "Still Believing",
    T = "Все Ще Віруючий",
    D = "",
    O = "",
    P = "Знайти ще якісь зашифровані тексти? Принесіть мені їх хорошу партію, ця робота з декодування потребує деякого часу.",
    C = "Чудово!  Я не можу дочекатися, щоб прочитати це. Будь ласка, продовжуйте приносити сюди зашифровані тексти, якщо ви їх знайдете.",
},

[8331] = {
    en = "Aurel Goldleaf",
    T = "Аурель Золотолист",
    D = "$N, хоча ми сподівалися, що операції Молота Сутінків у Сілітісі сповільнюються... ми, на жаль, помилилися. Завдяки продовженню нападів на культ ми дізналися, що ще темніша сила, Рада Безодні, контролює Молот через магічні вітрові камені, розкидані серед таборів культу. Твоя наступна дія, $N, буде спрямована проти Ради Безодні.$B$BПоговори з ремісницею Аурель Золотолист у східній частині Фортеці Кенарія. Її майстерність знадобиться для цього наступного кроку.",
    O = "Поговоріть із Аурель Золотолист у Фортеці Кенарія.",
    P = "",
    C = "$N, доброго дня. Мені сказали, що ти будеш протистояти Раді безодні? Якщо це так, то уважно слухайте мої наступні слова...",
},

[8332] = {
    en = "Dukes of the Council",
    T = "Герцоги Ради",
    D = "Ми вважаємо, що можливо використати вітровий камінь, щоб влаштувати засідку на герцога Ради Безодні. Для цього, однак, потрібно поспілкуватися через вітровий камінь і переконати раду, що ти — лідер середнього рангу Молота Сутінків.$B$BТакий маневр вимагає копії медальйона культу, що позначає статус. Я можу створити медальйон, але мені знадобиться великий блискучий уламок і герби, які носять Хранителі Безодні.$B$BПринеси мені це, і я зроблю решту.",
    O = "Принесіть 1 Великий Блискучий Уламок і 3 Герби Безодні до Аурель Золотолист у Фортеці Кенарія.",
    P = "У тебе є осколок і гребені, Демоношу? Вони мені знадобляться, щоб зробити медальйон станції сутінкового культиста.",
    C = "Ах, дуже добре. Я працював над медальйоном – тепер із цими останніми інгредієнтами я закінчу за кілька секунд...$B$BThere ми. Ось медальйон, $N.$B$BYou потрібно буде носити його, коли ви активуєте один із каменів вітру Сутінкового молота. Одягніть це разом із рештою сутінкових атрибутів, і Рада Безодні побачить у вас одного зі своїх підлеглих культистів.",
},

[8333] = {
    en = "Medallion of Station",
    T = "Медальйон Становища",
    D = "",
    O = "",
    P = "Якщо вам потрібен ще один медальйон станції сутінкового культиста, я з радістю зроблю це. Однак мені знадобиться ще один блискучий осколок і кілька гребенів безодні...",
    C = "Ось ти, $N. Ще один Сутінковий медальйон станції. Використовуйте це добре, і я бажаю вам успіху проти Ради Безодні!",
},

[8341] = {
    en = "Lords of the Council",
    T = "Лорди Ради",
    D = "Лордів Ради Безодні можна викликати лише через великі вітрові камені, і лише найвищі члени Ради Сутінків можуть із ними спілкуватися. Але... я знайшла спосіб удосконалити твою маскування і обдурити Лордів Безодні!$B$BМаскування вимагає персня влади, який носять лише найвищі члени культу. Я створю перстень для тебе, якщо ти принесеш мені великі блискучі уламки та знаки безодні.",
    O = "Принесіть 5 Великих Блискучих Уламків і 3 Знаки Безодні до Аурель Золотолист у Фортеці Кенарія.",
    P = "У вас є осколки та печатки, $N? Вони мені знадобляться, щоб створити перстень панування.",
    C = "дякую Лише одну хвилинку, і я приготую ту каблучку для вас...$B$BThere так і є. Тепер ви готові.$B$BBe обов’язково одягніть цей перстень разом із медальйоном станції та іншими атрибутами сутінків, коли ви активуєте більший камінь вітру. Зробіть це, і Рада безодні вважатиме вас одним із своїх слуг. Тоді, можливо, вам вдасться заманити одного в засідку!",
},

[8342] = {
    en = "Twilight Ring of Lordship",
    T = "Сутінковий Перстень Влади",
    D = "",
    O = "",
    P = "$N, якщо ти плануєш знову йти до Вищої ради безодні, тобі знадобиться ще один Сутінковий перстень панування. Принеси мені ще черепків і печаток, і я зроблю один для тебе.",
    C = "Ах, я бачу, ваші переконання сильні. Не багато хто зіткнеться з цією радою недоброзичливців!$B$BHere твій перстень, $N. Нехай ваша воля і ваша доля міцні.",
},

[8343] = {
    en = "Goldleaf's Discovery",
    T = "Відкриття Золотолист",
    D = "$N, Аурель Золотолист вважає, що вона знайшла спосіб викликати і перемогти правлячого члена Ради Безодні! Таке завдання буде небезпечним, але ти заслужив велику повагу серед Кенарійського Кругу. Ми знаємо, що якщо хтось і може це зробити, то це ти.$B$BНехай удача супроводжує тебе, $N. Поговори з Аурель, коли будеш готовий.",
    O = "Поговоріть із Аурель Золотолист у Фортеці Кенарія.",
    P = "",
    C = "Те, що говорить Хуум, правда. Я вважаю, що знаю, як викликати лорда Ради безодні! Послухайте, я поясню...",
},

[8348] = {
    en = "Signet of the Dukes",
    T = "Знак Герцогів",
    D = "Гуум сказав мені, що ти розгадав, як викликати Герцогів Безодні! Це велике досягнення.$B$BЗнаєш, що ще було б великим досягненням? Добре розтрощити одного з них. Це справить враження на їхніх підлеглих, якщо ти розумієш, про що я. Принеси його знак як доказ подвигу.",
    O = "Принесіть Знак Безодні до Бора Дикогрива у Фортеці Кенарія.",
    P = "Як це було з безоднім герцогом? Це сильно вдарило?",
    C = "Я знав, що ти жорсткий $C тієї хвилини, коли побачив, як ти заходиш у форт Кенаріону. Так тримати!",
},

[8349] = {
    en = "Bor Wildmane",
    T = "Бор Дикогрив",
    D = "Тепер, коли у тебе є медальйон і ти можеш викликати Герцога Безодні, поговори з Бором Дикогривом. Він дасть тобі завдання проти Ради Безодні.$B$BУдачі, $N. А якщо тобі знадобляться ще медальйони, повертайся до мене.",
    O = "Поговоріть із Бором Дикогривом у Фортеці Кенарія.",
    P = "",
    C = "Радий знову тебе бачити, $C! Отже, ви зробили медальйон? Добре – це знадобиться для вашого наступного квесту...",
},

[8351] = {
    en = "Bor Wishes to Speak",
    T = "Бор Бажає Поговорити",
    D = "Тепер, коли ти можеш замаскуватися під правлячого члена Ради Сутінків, я впевнена, що Бор Дикогрив захоче поговорити з тобою. Іди до нього і готуйся до дуже складного завдання...",
    O = "Поговоріть із Бором Дикогривом у Фортеці Кенарія.",
    P = "",
    C = "Так, саме так, $N. Попереду у мене дуже важке завдання...",
},

[8352] = {
    en = "Scepter of the Council",
    T = "Скіпетр Ради",
    D = "Ми з Гуумом щойно говорили про тебе. Він сказав мені, що ти майже готовий спробувати свої сили в бою з Лордом Безодні!$B$BМушу попередити, що це дуже небезпечне завдання. Краще візьми підкріплення. І я маю на увазі не одного чи двох друзів, а справжню, готову до бою бойову силу. Якщо твої друзі такі ж вправні, як ти, ви навіть можете його перемогти!$B$BЯкщо тобі це вдасться — і я, як завжди, захочу доказів — я дам тобі по-справжньому велику нагороду.",
    O = "Принесіть Скіпетр Безодні до Бора Дикогрива у Фортеці Кенарія.",
    P = "Ну як все пройшло? Я б зробив усе, щоб залишити свій пост і сам боротися з однією з цих речей!",
    C = "Ти... ти зробив це! Ти зробив це, $N! тут! Візьміть це. Це найбільша скриня, яка у нас була, і я наповнив її найкращими речами, які ми знайшли.",
},

[8353] = {
    en = "Chicken Clucking for a Mint",
    T = "Кудкудакання за М’яту",
    D = "О, ти займаєшся солодощами чи пустощами для хворої дитини, так? Я вже думав сказати, що ти трохи завеликий, щоб ганятися за цукерками...$B$BЩо ж, за мій ласощі — Залізогартську М’яту — тобі потрібно... кудкудакати, як курка! Так, кури люблять м’яти... ну гаразд, можливо, вони не ДУЖЕ їх люблять... але я не дам тобі м’яту, доки ти не кудкудакнеш для мене!$B$BНу $c, готовий до виклику чи ні?! Час заробити свій ласощі!",
    O = "Виконайте емоцію курки перед Трактирником Файрбрю, і в обмін ви отримаєте Залізогартську М’яту!",
    P = "Кудахтайте, як курка, для Inkeeper Firebrew",
    C = "Надто смішно!  Молодець, $N! Ось вам частування.$B$BHappy Hallow's End!",
},

[8354] = {
