},

[8360] = {
    en = "Dancing for Marzipan",
    T = "Танці за Марципан",
    D = "Хоча ти займаєшся солодощами чи пустощами для хворої дитини, тобі все одно потрібно виконати трюк за ласощі! Ми ж не можемо змінити традицію, чи не так...$B$BГадаю, ціна шматочка марципану нині — це станцювати! Саме так, покажи мені свої рухи! Станцюй для мене, і я дам тобі смачний марципан!",
    O = "Виконайте емоцію танцю перед Трактирницею Палою, і в обмін ви отримаєте Марципан Громового Бескиду!",
    P = "Ви вмієте танцювати, чи не так? Спробуйте поставити праву ногу... потім праву ногу назовні... праву ногу... потрясти нею...",
    C = "Ви справжня танцювальна машина, $N!$B$BHere — це ваша насолода за те, що ви такий хороший спорт. Щасливого святого кінця, і я вітаю вашого хворого маленького друга! Сподіваюся, скоро їм стане краще.",
},

[8361] = {
    en = "Abyssal Contacts",
    T = "Контакти Безодні",
    D = "Ми бачили, як культисти Молота Сутінків проводять ритуали для виклику могутніх елементальних вельмож. Ми не знаємо, чи це ті істоти, яким поклоняються культисти, чи вони діють як посередники для ще могутніших сил. Одне ми знаємо точно: вони отримують накази від цих елементалів.$B$BЯ хочу, щоб ти знайшов спосіб зв’язатися з Хранителем Безодні та добряче його побив! Ніщо так не вносить розлад у війська, як знищення ланцюга командування. Принеси докази, коли зробиш це.",
    O = "Бор Дикогрив у Фортеці Кенарія в Сілітісі хоче, щоб ви знищили Хранителя Безодні і принесли йому Герб Безодні як доказ подвигу.",
    P = "Ви закінчили роботу?",
    C = "ха! Ти зробив це, $N! Сутінковий молот скоро буде розчавлено!",
},

[8362] = {
    en = "Abyssal Crests",
    T = "Герби Безодні",
    D = "",
    O = "",
    P = "Ти довів, що можеш впоратися з собою в бійці, $N. Давайте продовжувати тиск на Сутінковий молот. Ідіть, бийтеся ще з кількома безодневими тамплієрами, я винагороджу вас деякими речами, які ми з Гуумом знайшли в битві.",
    C = "Ви добре зробили! Це менше тамплієрів, про які я можу хвилюватися.$B$BHere ти йди, $N. Сподіваюся, там є щось корисне для вас.",
},

[8363] = {
    en = "Abyssal Signets",
    T = "Знаки Безодні",
    D = "",
    O = "",
    P = "Ви показали, що більш ніж здатні протистояти Безодневому герцогу, $N. Я завжди пропагую хороші звички. Принеси мені більше печаток, і я дам тобі нагороду.",
    C = "Чудово, $N!  Перемога над цими герцогами призведе до того, що Сутінковий Молот на деякий час закрутиться. Як і обіцяли, ось ваша винагорода. Це одні з кращих речей, які ми з Хуумом знайшли.",
},

[8364] = {
    en = "Abyssal Scepters",
    T = "Скіпетри Безодні",
    D = "",
    O = "",
    P = "Ви справді перевершили всі мої очікування, $N. Ви змагаєтеся з противниками, над якими ми з Хуумом довго думали б, перш ніж вступити в бій.$B$BAt найкраще, що я можу зробити, — це продовжувати винагороджувати ваші зусилля в боротьбі проти Сутінкового Молота та їхніх володарів.$B$BBring мені більше безодні скіпетрів, і я зроблю все можливе, щоб дати вам відповідну винагороду.",
    C = "Я знав, що ти впораєшся, $N! Ось вам винагорода.",
},

[8365] = {
    en = "Pirate Hats Ahoy!",
    T = "Піратські капелюхи на горизонті!",
    D = "Ти той, кого прислав Картель? Гадаю, зійдеш. Слухай уважно, $c. Як ти знаєш, я постачаю модний одяг для еліти Азеротського суспільства. Королі та королеви, вожді і... ну, як там Орда називає своїх королев, усі носять те, що я вважаю стильним. І платять за це шалені гроші, що є найкращою частиною.$B$BОтже, ось що буде. Ти вирушиш до Затоки Загублених Вітрил і добудеш купу піратських капелюхів будь-яким способом. Думаєш, впораєшся?",
    O = "Горда Модистка хоче, щоб ти зібрав 20 Південноморських піратських капелюхів і повернув їх їй у Порт Парокіп у Танарісі.",
    P = "У вас є всі 20 капелюхів? Я тобі не вірю, дай мені їх побачити. Краще, щоб вони були в первозданному стані!",
    C = "О, ти любий, навіть якщо це зайняло тобі більше часу, ніж я звик. Ця доставка повинна принести мені чимало грошей, коли я почистю та персоналізую ці капелюхи. І оскільки я завжди готовий винагороджувати добре виконану роботу, ось дещо для вас. Я пропоную вам витратити частину на ванну, солоденька.",
},

[8366] = {
    en = "Southsea Shakedown",
    T = "Розгром Південного моря",
    D = "Арр! Вони вимагають від мене неможливого!$B$BКартель Парокіп хоче, щоб я провчив піратів Південного моря. Проблема в тому, що я не можу бути в двох місцях одночасно; мені треба залишатися тут, щоб підтримувати мир.$B$BОстаннім часом пірати ігнорують гроші за захист, які Картель регулярно сплачує. Тож я хочу тимчасово уповноважити тебе піти туди і показати їм, де раки зимують.$B$BТи знайдеш їх у Затоці Загублених Вітрил, це недалеко на південь. Дякую, $N, я твій боржник!",
    O = "Начальник охорони Жабокрут із Порту Парокіп у Танарісі хоче, щоб ти знищив 10 Південноморських піратів, 10 Південноморських вільних стрільців, 10 Південноморських портових робітників і 10 Південноморських головорізів.",
    P = "Так скоро повернутися? Сподіваюся, ти навчив тих хуліганів із Саутсі уроку, який вони не скоро забудуть.",
    C = "$N! Ти справжня людина!!!$B$BI Я впевнений, що Картель пом’якшить мене тепер, коли ти впорався з цими покидьками Саутсі. Подивимося, що я можу дати тобі в нагороду? Як щодо маленької монети, і ви виберете одну з них для своїх проблем?",
},

[8367] = {
    en = "For Great Honor",
    T = "За велику честь",
    D = "Служба Орді в одній із великих битв проти Альянсу — це джерело великої честі! Проте лише небагато тих, хто служив Орді на ВСІХ наших активних фронтах, є по-справжньому великими воїнами. Ми знищимо наших ворогів не через ізольовані сутички, а через добре скоординовану війну.$B$BВирушай і розгроми Альянс в Аратійській Низині, Долині Альтерак і Ущелині Пісні Війни! За честь! За Орду!",
    O = "Принеси 3 Знаки Честі Долини Альтерак, 3 Знаки Честі Аратійської Низини та 3 Знаки Честі Ущелини Пісні Війни до Воєначальника Орди поза полями битв.",
    P = "Араті все ще мокрий від крові великих воїнів, а зіткнення сталі все ще лунає по всьому Альтераку.  Не гайте мого часу, якщо не принесете звісток з фронту!",
    C = "Ваші випробування були нелегкими, але не оминула вас мужність і сила не ослабла. Розлучіться з минулими символами перемоги, $C. Вони нікому не знадобляться як нагадування про вашу цінність. Встань прямо, $N. Сьогодні ти будеш йти з великою гордістю за те, що ти герой!",
},

[8368] = {
    en = "Battle of Warsong Gulch",
    T = "Битва в Ущелині Пісні Війни",
    D = "Битва в Ущелині Пісні Війни проти Срібнокрилих Вартів має велике значення. Під приводом захисту лісу, який їм не належить, Альянс намагається позбавити Орду одного з наших найбільших джерел деревини.$B$BНе дозволь цьому статися, $N! Повернися до мене з доказом гідної служби Орді!",
    O = "Принеси 3 Знаки Честі Ущелини Пісні Війни до Воєначальника Орди поза полями битв.",
    P = "Битва в Ущелині Пісні Війни проти Срібнокрилих Вартових має велике значення. Під виглядом захисту лісу, який їм не належить, Альянс намагається позбавити Орду одного з наших найбільших джерел деревини.$B$BDo Не дозволяй цьому статися, $N! Повернися до мене з доказом гідного служіння Орді!",
    C = "Чудово! Ви показали свою цінність, захищаючи наші операції в Ущелині Пісні Війни! Нехай про твою честь далеко розійдеться по наших землях.",
},

[8369] = {
    en = "Invaders of Alterac Valley",
    T = "Загарбники Долини Альтерак",
    D = "Слухай, $N. Хоч би що ти чув про битву в Долині Альтерак, одна річ залишається правдою: Експедиція Буревісників вторглася на територію Морозних Вовків. День, коли ми дозволимо Альянсу вторгатися на землі Орди без рішучої відповіді, буде днем, коли я повішу свою сокиру і житиму в ганьбі до кінця життя. Вирушай і вижени загарбників!",
    O = "Принеси 3 Знаки Честі Долини Альтерак до Воєначальника Орди поза полями битв.",
    P = "Які новини ви приносите із земель Морозних Вовків? Як проходить битва за Альтеракську долину?",
    C = "Ви виявили велику хоробрість, захищаючи наші землі в долині Альтерак! Я розповім начальству про ваші вчинки.",
},

[8370] = {
    en = "Conquering Arathi Basin",
    T = "Підкорення Аратійської Низини",
    D = "Наш конфлікт із Альянсом переріс у справжню війну. Більше не використовуються і не очікуються фальшиві приводи для битви з жодної сторони.$B$BБитва за Аратійську Низину — це боротьба за ресурси, чисто і просто. Або Альянс отримує ресурси і використовує їх проти нас, або ми отримуємо їх і використовуємо для підтримки наших військових зусиль. Допоможи Осквернителям забезпечити потік потрібних нам ресурсів, $N!",
    O = "Принеси 3 Знаки Честі Аратійської Низини до Воєначальника Орди поза полями битв.",
    P = "Ви повернулися з новинами з Араті, $C?",
    C = "Захист наших ресурсів в Араті є важливим завданням! Ти добре впорався, $N.",
},

[8371] = {
    en = "Concerted Efforts",
    T = "Спільні зусилля",
    D = "Ми більше не ведемо ізольовані битви проти Орди, $g юначе:дівчино;.$B$BПеремога на одному фронті означає позбавлення Орди ресурсів, які вони могли б використати проти нас в іншій битві. Так само поразка в будь-якій битві може дати перевагу нашому ворогу десь в іншому куточку світу.$B$BАльянсу потрібні бійці з таким глобальним розумінням... справжні загартовані ветерани! $N, повернися до мене після того, як ти послужиш проти Орди на всіх наших активних полях битв.",
    O = "Принеси 3 Знаки Честі Долини Альтерак, 3 Знаки Честі Аратійської Низини та 3 Знаки Честі Ущелини Пісні Війни до Бригадирного Генерала Альянсу поза полями битв.",
    P = "Як проходять ваші подорожі, хлопче?",
    C = "Ти не той, хто розчарує, $N! Те, чого ви навчилися, виходить за рамки дрібних медалей і похвал. Те, чого ви навчилися, — це те, що можна отримати лише з досвідом і загартовуванням свого характеру на полі бою.$B$BYou все добре, $C. Ти справжній герой Альянсу!",
},

[8372] = {
    en = "Fight for Warsong Gulch",
    T = "Боротьба за Ущелину Пісні Війни",
    D = "Срібнокрилі Вартові воюють із Вершниками Пісні Війни через руйнування, яке орки чинять у лісі. Однак є й інші причини захищати цей ліс, окрім простої любові до природи.$B$BЛіс створює стратегічний бар’єр, який робить Ясенеділ захищеним від великомасштабного нападу. Без нього Астранаар протримався б день чи два, перш ніж бути приєднаним до Степів.$B$BЗроби свій внесок у боротьбу з Вершниками Пісні Війни, $N! За Альянс!",
    O = "Принеси 3 Знаки Честі Ущелини Пісні Війни до Бригадирного Генерала Альянсу поза полями битв.",
    P = "Ви повернулися з новинами з фронту, $N?",
    C = "Молодець, $N! Ви добре послужили Альянсу.",
},

[8373] = {
    en = "The Power of Pine",
    T = "Сила сосни",
    D = "Найбільше, що я ненавиджу в Святі Врожаю, — це смердючі бомби, які Покинуті кидають на Південнобережжя. Хто б міг подумати, що святкування визволення буде таким смердючим?$B$BПід час Свята Врожаю використовуй цей очищувач, щоб прибрати будь-які смердючі бомби Орди, які можуть з’явитися в селі. Він використовує силу сосни для боротьби з неприємними запахами.$B$BДопоможи тримати Південнобережжя в чистоті, і я дам тобі кілька ласощів до Свята Врожаю, які тобі точно сподобаються. Домовились?",
    O = "Використовуй Очищувач Смердючих Бомб, щоб прибрати будь-яку Смердючу Бомбу Покинутих, кинуту в Південнобережжі. Повернися до Сержанта Гартмана в Південнобережжі, коли закінчиш.",
    P = "Приберіть смердючу бомбу, яку скинули на південний берег!",
    C = "Ах, тут уже майже краще пахне. Майже.$B$BThanks тобі, $N, Southshore може пройти через ще один Hallow's End. Ось вам частування, з моєю подякою! Якщо у вас закінчаться цукерки, я думаю, що в Стальгорні є гном на ім’я Катріна Шиммерстар, який може продати вам більше; я вважаю, що вона тут лише під час Хеллоуз Енд.",
},

[8374] = {
    en = "Claiming Arathi Basin",
    T = "Захоплення Аратійської Низини",
    D = "Перемога у війні — це не лише про те, щоб перехитрити чи перемогти ворога. Часто перемога зводиться до того, щоб просто виробляти більше, ніж твій супротивник.$B$BВ Аратійській Низині ми маємо значний запас ресурсів для тієї сторони, яка перша їх захопить.$B$BЯкщо Альянс переможе, це означатиме більше мечів і списів для наших військ. Якщо Орда виграє, ці мечі та списи все одно будуть зроблені, але вони будуть спрямовані на нас! Зараз час допомогти Альянсу в Аратійській Низині, $N.",
    O = "Принеси 3 Знаки Честі Аратійської Низини до Бригадирного Генерала Альянсу поза полями битв.",
    P = "Скажіть, які новини з фронту?",
    C = "Браво, солдате! Так тримати, і ми змусимо Орду бігти аж до Оргріммару.",
},

[8375] = {
    en = "Remember Alterac Valley!",
    T = "Пам’ятай про Долину Альтерак!",
    D = "Не помиляйся, $N. Орда має рацію, коли каже, що Долина Альтерак — це територія Морозних Вовків.$B$BЕкспедиція Буревісників прибула як мирні гості в пошуках руди та реліквій. Морозні Вовки відповіли найжорстокішим і найнецивілізованішим актом агресії, який зазнав Альянс.$B$BНіколи не забувай про хоробрих дворфів, які загинули під час цього боягузливого несподіваного нападу. Вирушай, $c, зроби свій внесок у битву за Долину Альтерак. За Альянс!",
    O = "Принеси 3 Знаки Честі Долини Альтерак до Бригадирного Генерала Альянсу поза полями битв.",
    P = "Які новини ви приносите із земель Грозових Пайків? Як проходить битва за Альтеракську долину?",
    C = "Ви виявили велику хоробрість, захищаючи наші землі в долині Альтерак! Я розповім начальству про ваші вчинки.",
},

[8376] = {
    en = "Armaments of War",
    T = "Озброєння війни",
    D = "",
    O = "",
    P = "",
