},

[8412] = {
    en = "Spirit Totem",
    T = "Духовний Тотем",
    D = "Елементальні духи цього місця більше не люблять мене.$B$BТи знаєш про тотеми більше за всіх, і мені потрібен духовний тотем, щоб захистити себе. Ми вже маємо елементи, але тепер нам потрібно щось більш природне. Більш первозданне.$B$BУ Західних Зачумлених Землях ти можеш вбивати ведмедів за їхні кігті та павуків за їхні очі. Птахи-падальщики їдять усе, тож у них може бути і те, і інше.",
    O = "Принесіть частини для духовного тотема до Бат’ри Вітроглядача.",
    P = "Духи знають, що ми задумали, і вони намагалися мене вбити! Сподіваюся, ви отримали запчастини.",
    C = "Чудово, мон! Давайте спробуємо...",
},

[8413] = {
    en = "Da Voodoo",
    T = "Вуду",
    D = "Духовного тотема недостатньо. Нам потрібна магія вуду, щоб усе запрацювало як слід.$B$BТролі в затопленому храмі мають пір’я, сповнені магії вуду. Вирушай туди і вбий Ґашера, Міджана, Золо, Гукку, Зул’лора та Лоро. Тоді у нас буде достатньо магії для справжнього духовного тотема.",
    O = "Принесіть пір’я вуду до Бат’ри Вітроглядача.",
    P = "Де пір'я, мон?",
    C = "Настав час цьому тролю повноцінно відпочити! Духовний тотем наглядатиме за мною.$B$BI довго збирав речі, можливо, ти хочеш щось за всі свої проблеми?",
},

[8414] = {
    en = "Dispelling Evil",
    T = "Розвіювання Зла",
    D = "Вітаю, $c. Такі хрестоносці, як ти, — бажане видовище в цих спустошених краях.$B$BТвоя свята сила потрібна, щоб допомогти боротися з нескінченною нежиттю тут. Нам потрібно, щоб ти зібрав велику кількість каменів мору і приніс їх Верховному Жерцеві Тел’данісу. Верховного Жерця можна знайти біля Гробниці Утера на Пагорбі Скорботи, неподалік звідси.$B$BТільки той, хто має Мандат Світанку Аргенту, може сподіватися знайти камені мору, тож поговори з Офіцером Чистосердом, якщо ти ще цього не зробив.",
    O = "Зберіть 20 Каменів Мору Слуг і принесіть їх Верховному Жерцеві Тел’данісу в Західних Зачумлених Землях.",
    P = "Яке зло ти мені приніс?",
    C = "Розвіювати зло з каменю бича ризиковано, адже він привертає увагу нежиті за незліченні милі. Але ти сильний у Світлі, $N, і я не боюся за тебе...",
},

[8415] = {
    en = "Chillwind Point",
    T = "Точка Прохолодного Вітру",
    D = "Командир Ашлам Доблеслав видав заклик до паладина з твоєю чистотою та доблестю, $N. Ти можеш знайти його в Точці Прохолодного Вітру в південній частині Західних Зачумлених Земель. Знайди його і допоможи в його справі за Світло!",
