},

[8419] = {
    en = "An Imp's Request",
    T = "Прохання Імпа",
    D = "$N, імп у Сквернолісі на ім’я Імпсі запросив твоєї присутності. Це дещо дивно, адже він попросив принести шматок пеклотканини як знак доброї волі. Враховуючи силу, якою ти вже володієш як чаклун, я припускаю, що ти знаєш, що сатири Сквернолісу мають цю пеклотканину.$B$BТи можеш знайти Імпсі на північ від Водоспаду Кривавого Отруту, який, як я чув, у цю пору року виглядає надзвичайно гарно.",
    O = "Принесіть шматок пеклотканини до Імпсі в Сквернолісі.",
    P = "У вас є моє полотно?",
    C = "Який ти чудовий $C!$B$B<Імпсі тримає склянну тканину на обличчі.>$B$BOh як мені подобається це відчуття, те, як воно обпікає твою шкіру та плете злі думки в розумі...",
},

[8420] = {
    en = "Hot and Itchy",
    T = "Гаряче і Свербляче",
    D = "Можливо, це звучить дивно від імпа, але я б хотів мати власного улюбленця. Справді хотів би. Це просто несправедливо, що Нібі має мене, а я не маю нікого!$B$BНасправді, це навіть не мусить бути живий улюбленець. Мені потрібно щось, із чого я можу почати його створювати, наприклад, пеклотканину. Сатири тут, у Сквернолісі, іноді мають пеклотканину, тож тобі просто потрібно вбити достатньо їх, щоб знайти трохи. Це не звучить так страшно, правда?",
    O = "Принесіть шматок пеклотканини до Імпсі в Сквернолісі.",
    P = "У вас є моє полотно?",
    C = "Вау! Ви надто добрий. Спеціально для $C!$B$B<Імпсі тримає скраб до свого обличчя.>$B$BOh як мені подобається це відчуття, те, як воно обпікає вашу шкіру та плете злі думки в розумі...",
},

[8421] = {
    en = "The Wrong Stuff",
    T = "Неправильний Матеріал",
    D = "Тепер, коли у мене є пеклотканина, я можу почати створювати *свого* улюбленця.$B$BАле йому потрібні очі. Можеш вирвати трохи гнилої деревини у залізодревного народу, щоб я вирізав із неї чудові очі. Вони на півночі, у Залізодревних Лісах.$B$BТакож мені знадобиться трохи есенції кривавого отруту, щоб надати йому запах нового демона. Заражені слимаки мають цю есенцію, і вони тусуються прямо тут, біля Нібі та мене.",
    O = "Принесіть 10 Гнилої Деревини та 4 Есенції Кривавого Отруту до Імпсі в Сквернолісі.",
    P = "У вас є товар?",
    C = "Це буде дуже добре працювати.",
},

[8422] = {
    en = "Trolls of a Feather",
    T = "Тролі з Одного Пір’я",
    D = "Мій улюбленець майже готовий. Тепер мені потрібно щось, чим його набити.$B$BТільки пір’я вуду від тролів у затопленому храмі підійдуть. Їх звуть Ґашер, Міджан, Золо, Гукку, Зул’лор і Лоро. Убий їх. Убий усіх.$B$BЦе нелегке завдання, $N, тож я зроблю його вартим твоїх зусиль, давши тобі дещо з речей Нібі — йому, мабуть, це й не потрібно.",
    O = "Принесіть загалом 6 Пір’їн Вуду від тролів у затопленому храмі.",
    P = "Ти приніс пір'я? Цю ляльку потрібно набити!",
    C = "Чудово, тепер мій улюбленець готовий!$B$B<Імпсі швидко запихає ляльку й демонічно обіймає її.>$B$BOh, який дивний побічний ефект мають ці пір’я вуду...",
},

[8423] = {
    en = "Warrior Kinship",
    T = "Спорідненість Воїнів",
    D = "<Герой оглядає тебе.>$B$BТи, без сумніву, $c. Я попросив би тебе виконати почесне завдання, але спочатку мушу перевірити твою силу.$B$BКажуть, що Рексар перевіряв гостроту своїх клинків, убиваючи пеклокабана одним швидким ударом. Тепер я перевірю твою силу, убиваючи їх.",
    O = "Убийте 7 Пеклокабанів у Спустошених Землях і поверніться до Полеглого Героя Орди.",
    P = "Пекучі колючки черемхи залишають жахливі шрами. Не бійся болю й спотворення, воїне, вони ніщо порівняно з в’язницею, до якої я прикутий.",
    C = "Мені не потрібні докази, щоб знати, що ти зробив, $C.  Я бачу рішучість, закарбовану у вашому виразі обличчя.",
},

[8424] = {
