[8446] = {
    en = "Shrouded in Nightmare",
    T = "Огорнутий Кошмаром",
    D = "Корупція просочується з цього предмета.$B$BМожливо, є зв’язок між цим предметом і драконами, що виходять із Сну. Тобі потрібно знайти когось, хто зможе розшифрувати значення цього предмета. Можливо, друїди Місячної Галявини або Фортеці Кенарія зможуть тобі допомогти.",
    O = "Знайдіть когось, хто здатен розшифрувати значення Предмета, Огорнутого Кошмаром.$B$BМожливо, могутній друїд зможе тобі допомогти.",
    P = "Так, $R?",
    C = "Я повинен видалити пляму з цього предмета. Це може пролити світло на мої нещодавні невдачі заглибитися в Сновидіння. Дай це мені.",
},

[8447] = {
    en = "Waking Legends",
    T = "Пробудження Легенд",
    D = "Води озера Елуне’ара мають розчинити кошмари, що огортають цей предмет. Дай мені хвилинку, щоб провести очищення, $N.",
    O = "Зачекайте, поки Хранитель Ремулос у Місячній Галявині очистить Предмет, Огорнутий Кошмаром.",
    P = "Легенди пробудження.",
    C = "Візьми його каблучку, $N. Для Малфуріона він виконав своє призначення. Тепер він служитиме для вас новій меті...",
},

[8458] = {
    en = "",
    T = "<НЕВИКОРИСТАНИЙ>",
    D = "Я вірю, що можу знайти цього демонічного лорда, якщо матиму потрібні реагенти.$B$BЯкщо він справді такий могутній, як я підозрюю, мені знадобляться предмети, зібрані з небезпечних створінь. Але ти дієш від імені Вождя, тож я впевнений, що ти приймеш моє завдання.$B$BСпочатку мені потрібно зламати будь-які захисні чари, які він має проти ясновидіння. Для цього мені потрібен скальп сатира — але не будь-якого сатира. Скальп має бути від тінеслідувача Гнівопекла.$B$BШукай їх серед стародавніх руїн на північному сході Безпліддя.",
    O = "Принесіть Скальп Тінеслідувача до Моріна Кістколома в Безплідді.",
    P = "",
    C = "",
},

