[8499] = {
    en = "The Alliance Needs Thorium Bars!",
    T = "Альянсу потрібні торієві зливки!",
    D = "Дуже мило з твого боку цікавитися потребами Альянсу. Окрім усіх інших зборів, нам потрібно багато торієвих зливків, і я відповідаю за це завдання. Торій буде використаний для створення багатьох речей для війни, зокрема для будівництва батальйону парових танків, які будуть доставлені в Сіліт повітряним шляхом, щойно їх завершать. Чи можеш ти допомогти нам у цій справі, $c?",
    O = "Принеси 20 торієвих зливків дамі Двоплеті у Військовому кварталі Залізогарта.",
    P = "О, посилка від мого брата? Чудово! Фортуна справді світить мені сьогодні!",
    C = "Отже, Гноарн не довіряє моїм розвідувальним здібностям? Цікаво чому...",
},

[8500] = {
    en = "The Alliance Needs More Thorium Bars!",
    T = "Альянсу потрібні ще торієві зливки!",
    D = "Радий бачити тебе знову, $N. Сподіваюся, у тебе все гаразд. Це правда, що нам все ще потрібні торієві зливки. Якщо у тебе є зайві, я збираю їх для війни в Ан'Кіражі.",
    O = "Принеси 20 торієвих зливків дамі Двоплеті на аеродром у Дун-Морозі.",
    P = "Дуже приємно знову бачити тебе, $N. Я сподіваюся, що у вас все добре. Це правда, що нам все ще потрібні торієві злитки. Якщо у вас є їх у запасі, я збираю їх для військових дій у Ан'Кіражі.",
    C = "Чудово, $C! Добре виконана робота. Я подбаю про те, щоб ці бруски потрапили на піддон і в руки ковалів та інженерів, які наполегливо працюють над створенням запасів для нашої армії. Ще раз дякую, і якщо ви натрапите на інші злитки торію, обов’язково зайдіть.",
},

[8501] = {
    en = "Target: Hive'Ashi Stingers",
    T = "Ціль: Жала Вул’Аші",
    D = "Зі зростанням військових зусиль присутність сілітідів у цій місцевості становить дедалі більшу загрозу для наших операцій. Тебе обрано для участі в штурмі Вул’Аші, де твоєю основною ціллю будуть повітряні жала Вул’Аші.$B$BПовернися до командира Мар’аліта після виконання завдання.",
    O = "Убий 30 жал Вул’Аші та повернися до командира Мар’аліта у Ценарійській Фортеці в Сіліті. Також принеси Бойове завдання XII, щоб завершити цей квест.",
    P = "Ти хочеш мені щось сказати, $N?",
    C = "Чудова робота, $N. Вашу участь у нападі на Хів'Аші помітили.",
},

[8502] = {
    en = "Target: Hive'Ashi Workers",
    T = "Ціль: Робітники Вул’Аші",
    D = "Зі зростанням військових зусиль присутність сілітідів у цій місцевості становить дедалі більшу загрозу для наших операцій. Тебе обрано для участі в штурмі Вул’Аші, де твоєю основною ціллю будуть робітники Вул’Аші.$B$BПовернися до командира Мар’аліта після виконання завдання.",
    O = "Убий 30 робітників Вул’Аші та повернися до командира Мар’аліта у Ценарійській Фортеці в Сіліті. Також принеси Бойове завдання III, щоб завершити цей квест.",
    P = "Ти маєш мені щось сказати, $C?",
    C = "Чудова робота, $N. Без своїх робітників силітидам буде важко відновити будь-які пошкодження, завдані структурі їхнього вулика.",
},

[8503] = {
    en = "The Alliance Needs Stranglekelp!",
    T = "Альянсу потрібна душогубка!",
    D = "Отже, $c, я вже розповідав тобі про всі чудові застосування душогубки? Розповідав? Ну гаразд... у будь-якому разі, нам потрібно багато, і коли я кажу багато, я маю на увазі ДУЖЕ БАГАТО! Думаєш, ти можеш нам допомогти? Я знаю, що це означає відмовитися від усіх тих чудових речей, які можна з неї зробити, але це для доброї справи!",
    O = "Принеси 20 душогубок рядовому Драксельгейджу у Військовому кварталі Залізогарта.",
    P = "Це неправда! Я б ніколи не зняв жодної водорослі з гори тут. У когось може виникнути спокуса, враховуючи, що це практично панацея від утилітарної користі. *кашляє* Ви, мабуть, не маєте ту душку, про яку ми говорили раніше?",
    C = "ура! Це ще двадцять менше. ти найкращий Я вважаю, що мені слід все це запакувати, перш ніж вони зів’януть. Так багато stranglekelp, так мало часу!$B$BThanks знову, $C!",
},

[8504] = {
    en = "The Alliance Needs More Stranglekelp!",
    T = "Альянсу потрібна ще душогубка!",
    D = "Знову привіт... як там тебе? А, точно, $N! Прийшов перевірити, чи потрібна мені ще душогубка, так? Ну, тобі пощастило, бо відповідь на це дуже важливе питання — однозначне ТАК! Думаєш, зможеш зібрати ще двадцять?",
    O = "Принеси 20 душогубок рядовому Драксельгейджу на аеродром у Дун-Морозі.",
    P = "",
    C = "",
},

[8505] = {
    en = "The Alliance Needs Purple Lotus!",
    T = "Альянсу потрібна пурпурова лотоса!",
    D = "$C, пурпурова лотоса — це квітка з безліччю застосувань. Я тут за дорученням Альянсу як експерт із цих застосувань, щоб зберегти зібрані трави та забезпечити, щоб військові зусилля Альянсу отримали достатньо пурпурової лотоси для їхніх потреб.$B$BЯ хочу, щоб ти вирушив у світ і повернувся до мене з цими квітами. Це тобі під силу?",
    O = "Принеси 20 пурпурових лотосів майстру Ночепісні у Військовому кварталі Залізогарта.",
    P = "У вас є трави фіолетового лотоса, які я просив?",
    C = "Ми дуже вдячні за ваш внесок, $c. Лише завдяки об’єднаним зусиллям усіх ми зможемо відбити безжальний наступ силітідів і будь-якої сили, що їх спонукає. Навіть Орда збирає власну колекцію фіолетового лотоса. Якщо ви знайдете більше, поверніться до мене сюди.",
},

