[8507] = {
    en = "Field Duty",
    T = "Польова служба",
    D = "Вітаю, $N. Перш ніж я доручу тобі складніші завдання у війні, тобі потрібно виконати свою частку польової служби.$B$BТи знайдеш бригаду Залізогарта капітана Чорноковадла біля Вул’Зори.$B$BЗвітся йому або його лейтенанту, Джанелі Міцномолоту, і повернися до мене. Я матиму для тебе складніше завдання.$B$BО, і будь ласка, тримайся подалі від Орґріммарського легіону. Нам довелося тримати ці дві сили окремо через взаємну ворожнечу.",
    O = "Звітся на службу до посту бригади Залізогарта біля Вул’Зори. Підготуй свої Непідписані Польові Документи та отримай Підписані Польові Документи від капітана Чорноковадла і повернися до Вітрозова Калдона у Ценарійській Фортеці в Сіліті.$B$BПримітка: Зцілення або накладання корисних заклинань на члена бригади Залізогарта позначить тебе для PvP.",
    P = "Ви знайдете сили капітана Блекканвіла, розміщені за межами Вулика Зора.  Поговоріть з його лейтенантом Джанелою Стаутхаммер, якщо ви не можете його знайти.",
    C = "Чудово, $N я підготував набір завдань, які повинні оптимально використовувати ваші навички.$B$BWith завдяки постійним зусиллям вас і таких, як ви, наш ворог скоро буде переможений раз і назавжди!$B$BShould вам потрібен новий брифінг місії, поверніться до капітана Чорного ковача.",
},

[8508] = {
    en = "Field Duty Papers",
    T = "Польові документи",
    D = "",
    O = "",
    P = "Я так розумію, що ти хочеш, щоб ці документи були підписані, $Glad:lass;?",
    C = "Так, я думаю, ця невелика сутичка сьогодні пройде як польове чергування. Віднесіть їх назад у Крепость Кенаріону, я впевнений, що вони приготують для вас легку роботу.$B$BOff вперед!",
},

[8509] = {
    en = "The Alliance Needs Arthas' Tears!",
    T = "Альянсу потрібні Сльози Артаса!",
    D = "Я зроблю це просто і зрозуміло, $c. Альянсу потрібно зібрати велику кількість Сліз Артаса для війни в Ан'Кіражі. Не питай, для чого; я лише виконую накази. Але я хочу, щоб ти зібрав якомога більше цих трав і приніс їх мені сюди. Ти готовий це зробити?",
    O = "Принеси 20 Сліз Артаса сержант-майору Джермейн у Військовому кварталі Залізогарта.",
    P = "Що це? Говори, $C! У вас є ту партію сліз Артаса, яку я просив?",
    C = "Гарна робота, $C. Треба сказати, що я приємно здивований. Ви не повірите, скільки людей приходило, пропонувало допомогу, але ніколи не поверталося. Дозволь мені просто поставити їх у ящик і позначити на ньому твоє ім’я, а потім ми знову поговоримо про те, чи потрібні мені ще ці рослини.",
},

[8510] = {
