[8572] = {
    en = "Veteran's Battlegear",
    T = "Спорядження Ветерана",
    D = "Значки, які ти збираєш за виконання бойових, логістичних і тактичних завдань для Фортеці Кенарія, — це не просто для показу, $N.$B$BТобі варто їх зберігати. У міру того, як ти доводитимеш свою відданість нашій організації, я зможу запропонувати тобі спорядження, яке ми резервуємо для наших найближчих союзників, в обмін на ці значки.",
    O = "Принесіть 7 Бойових Значків Кенарія, 4 Логістичні Значки Кенарія і 4 Тактичні Значки Кенарія до Варґуса у Фортеці Кенарія в Силіті. Для виконання цього завдання також потрібна Шанована репутація з Кенарійським Кругом.",
    P = "Це в наших інтересах, щоб наші найвідданіші союзники були добре споряджені, $N.$B",
    C = "Чудова робота, $n. Будь ласка, прийміть це від імені Кола Кенаріону. Ти точно заслужив це, друже!",
},

[8573] = {
    en = "Champion's Battlegear",
    T = "Спорядження Чемпіона",
    D = "Значки, які ти збираєш за виконання бойових, логістичних і тактичних завдань для Фортеці Кенарія, — це не просто для показу, $N.$B$BТобі варто їх зберігати. У міру того, як ти доводитимеш свою відданість нашій організації, я зможу запропонувати тобі спорядження, яке ми резервуємо для наших найближчих союзників, в обмін на ці значки.",
    O = "Принесіть 15 Бойових Значків Кенарія, 20 Логістичних Значків Кенарія, 20 Тактичних Значків Кенарія і 1 Знак Кенарія до Варґуса у Фортеці Кенарія в Силіті. Для виконання цього завдання також потрібна Возвеличена репутація з Кенарійським Кругом.",
    P = "У наших інтересах, щоб наші найвідданіші союзники були добре споряджені, $N.",
    C = "Чудова робота, $N. Будь ласка, прийміть це від імені Кола Кенаріону. Ти точно заслужив це, друже!",
},

[8574] = {
    en = "Stalwart's Battlegear",
    T = "Спорядження Стійкого",
    D = "Значки, які ти збираєш за виконання бойових, логістичних і тактичних завдань для Закликача Вітру Гордогорна, — це не просто для показу, $N.$B$BТобі варто їх зберігати. У міру того, як ти доводитимеш свою відданість нашій організації, я зможу запропонувати тобі спорядження, яке ми резервуємо для наших найближчих союзників, в обмін на ці значки.",
    O = "Принесіть 15 Бойових Значків Кенарія, 20 Логістичних Значків Кенарія, 17 Тактичних Значків Кенарія і 1 Знак Ремулоса до Варґуса у Фортеці Кенарія в Силіті. Для виконання цього завдання також потрібна Поважна репутація з Кенарійським Кругом.",
