},

[8588] = {
    en = "The Horde Needs Heavy Leather!",
    T = "Орда Потребує Грубої Шкіри!",
    D = "Оскільки ми готуємося до війни, чи не здається тобі, що спочатку варто зібрати всі потрібні нам матеріали, мон? Один із основних матеріалів для війни, які ми виробляємо, — це груба шкіра. Ми використаємо її для всього: від укріплення до обладунків, і навіть для звичайних брезентів.$B$BАле спочатку нам потрібно дістати більше шкіри. Це твоє завдання, $c. Гостри свій ніж і принеси мені зв’язку. Тоді ми поговоримо далі.",
    O = "Принесіть 10 одиниць Грубої Шкіри до Здирача Джамані в Долині Духів в Орґріммарі.",
    P = "У мене немає часу на ігри, якщо ти тут просто лепетати, $C. Надто багато стосів важкої шкіри, які потребують обробки. Повертайся, коли матимеш для мене хоча б десять.",
    C = "Просто неймовірно... подивіться на чистоту цих зразків. Хм, мені цікаво, що це може означати. Вони ніби й елементарні за своєю суттю, але... щось більше. Вони нагадують мені... Старих богів. Ми знайшли їх сліди по всьому Азероту, і тепер мені цікаво, чи ці істоти не пов’язані з ними якимось чином.$B$BWe доведеться перевірити далі.",
},

[8589] = {
    en = "The Horde Needs More Heavy Leather!",
    T = "Орда Потребує Більше Грубої Шкіри!",
    D = "",
    O = "",
    P = "",
    C = "Ти, човече, човече! Дуже дякую за важку шкіру. Кожна дрібниця робить нас набагато ближчими. Я просто зберу їх на купу, щоб інші шкіряні майстри могли працювати над ними.$B$BThanks ще раз, $N, і якщо ви натрапите на інші стоси важкої шкіри, ви знаєте, де мене знайти.",
},

[8590] = {
    en = "The Horde Needs Thick Leather!",
    T = "Орда Потребує Товстої Шкіри!",
    D = "Я радий, що ти вирішив поговорити зі мною про це, $c. Схоже, підготовка Орди до війни в Ан'Кіражі йде повним ходом. Але ми з тобою все ще мусимо зробити свою частину.$B$BМене попросили зібрати велику кількість товстих шкір для використання в різноманітних військових матеріалах, і мені потрібна твоя допомога, щоб піти і зібрати їх. За це ти отримаєш честь і вдячність Орди, якщо вирішиш допомогти. Ти згоден?",
    O = "Принесіть 10 одиниць Товстої Шкіри до Сержанта Умали в Долині Духів в Орґріммарі.",
    P = "$C, ти так скоро повернувся з десятьма товстими шкіряними виробами, про які ми говорили?",
    C = "Гарна робота, $C. Я впевнений, що ці товсті шкіряні шкури будуть використані для зміцнення цепелінів і виготовлення всілякої броні та зброї. Тобі моя подяка і Орда. Поверніться ще раз, якщо під час подорожі натрапите на більш товсту шкіру, і нехай вам пощастить.",
},

[8591] = {
    en = "The Horde Needs More Thick Leather!",
    T = "Орда Потребує Більше Товстої Шкіри!",
