},

[8599] = {
    en = "Love Song for Narain",
    T = "Пісня Кохання для Нараїна",
    D = "Нечасто до мене приходять гості. Насправді, востаннє у мене був гість, коли я врятувала того милого, дорогого гнома з уламків розбитої літаючої машини.$B$B<Мерідіт дивиться в нікуди, загубившись у спогадах.>$B$BТи знаєш його? Нараїна? Нараїна Добромисла? Ох, як багато б це значило для мене, якби хтось передав йому моє повідомлення. Я мушу сказати йому, що я відчуваю! Я знаю, що це кохання! Я просто знаю!$B$BЧи не могли б ви передати повідомлення Нараїну? Я була б вам вічно вдячна!",
    O = "Віднесіть Любовний Лист Мерідіт до Нараїна Добромисла в Танарісі.",
    P = "Ти пахнеш рибою!",
    C = "Що!?$B$B<Нараїн починає вередувати.>$B$BWell, гм... Що ти хочеш, щоб я зробив??? Вона риба! РИБА Я тобі кажу! А я гномик. Це ніколи не могло вийти.",
},

[8600] = {
    en = "The Horde Needs Rugged Leather!",
    T = "Орда Потребує Міцної Шкіри!",
    D = "Я вважаю, що зручність ножа в твоїй долоні важливіша за його гостроту. Навіть найтупіше лезо можна змусити різати, якщо правильно прикласти силу, чи не згоден, $c? Але ми з тобою не маємо таких проблем, адже ми тримаємо леза найгострішими, так?$B$BАле неважливо, у мене є завдання для тебе. На службі Орді та для твого внеску у війну в Ан'Кіражі я хочу, щоб ти повернувся до мене з кількома міцними шкірами. Це те, що ти зробиш, чи не так?",
    O = "Принесіть 10 одиниць Міцної Шкіри до Доктора Серратуса в Долині Духів в Орґріммарі.",
    P = "Вам не могло знадобитися стільки часу, щоб відрізати для мене десять грубих шкір! Можливо, вам варто нагострити свій ніж для зняття шкіри? Чи, можливо, я помиляюся, і вони у вас у рюкзаку?",
    C = "Дуже добре, здається, ви зробили досить пристойну роботу, хоча деякі з цих оболонок виглядають дещо пошарпаними по краях. Неважливо, завдання виконано, і ви заслужили винагороду. Якщо ви натрапите на ще один стос грубої шкіри, не забудьте поспішно принести їх мені.",
},

[8601] = {
    en = "The Horde Needs More Rugged Leather!",
    T = "Орда Потребує Більше Міцної Шкіри!",
    D = "",
    O = "",
    P = "",
    C = "Практика, практика, практика. Добре відточений ніж і вміння ним користуватися заведуть вас далеко в цьому світі, $N. Схоже, краї цих оболонок кращі, ніж попередні. Ви купили новий ніж?$B$BIn в будь-якому випадку ми дякуємо вам за ваші зусилля. Вашу пожертву прийнято до уваги, і я можу вас запевнити, і її буде використано з користю. Якщо ви знайдете більш міцну шкіру, обов’язково поверніться та поговоріть зі мною, оскільки вона мені, мабуть, знадобиться.",
},

[8602] = {
    en = "Stormcaller's Pauldrons",
    T = "Наплічники Закликача Бурі",
    D = "Кажуть серед нас, що вишукані наплічники, які носять смертні раси, почалися як спроба імітувати крила дракона.$B$BПринеси мені пута, які носять найвищі лідери кіраджі, і я сформую з них наплічники, страшніші за крила самого Нефаріана!",
    O = "Принесіть Кіраджські Пута Домінування, 2 Ідоли Життя, 5 Золотих Скарабеїв і 5 Кришталевих Скарабеїв до Андорґоса в Ан'Кіражі. Для виконання цього завдання також потрібна Нейтральна репутація з Родом Ноздорму.",
    P = "Ви зібрали потрібні мені компоненти?",
    C = "З матеріалів, які ви принесете, і з луски наших полеглих ворогів-кіраджів я створю вам ці наплечники, смертний. Нехай вони нададуть вам потрібний захист і нехай їхній вигляд вселяє страх у наших ворогів.",
},

[8603] = {
    en = "Vestments of the Oracle",
    T = "Вбрання Оракула",
    D = "Неназваний Старий Бог повільно прокидається від свого сну під Ан'Кіражем. Жахлива доля, що чекає на Азерот, може настати за дні чи роки; час не має значення для істот його сили.$B$BКоли зірки будуть сприятливими, він ударить по всіх живих істотах із жахливим гнівом. Ти мусиш знайти його до того часу і знайти спосіб покласти край його існуванню.$B$BЗроби це і принеси мені шматок його оболонки. Я дарую тобі обладунки, яких ще не носив жоден смертний... обладунки, гідні того, хто зарубав бога!",
    O = "Принесіть Оболонку Старого Бога, 2 Ідоли Смерті, 5 Кам'яних Скарабеїв і 5 Кришталевих Скарабеїв до Ветсери в Ан'Кіражі. Для виконання цього завдання також потрібна Шанована репутація з Родом Ноздорму.",
    P = "У його оселі в Ан'Кіражі жахливий К'Тун чекає уві сні.",
    C = "Я не очікував, що ти повернешся після своєї спроби, $N.$B$BYou виконав долю, більшу, ніж доля більшості безсмертних істот.$B$BBy, убивши К'Туна, ти не лише врятував увесь Азерот, ти також схилив терези космічних подій, які неможливо зрозуміти.$B$BAccept ці шати є символом слави й тягаря, який стане наслідком твоїх дій.$B$BMay їхня сила допоможе тобі в випробуваннях, що чекають на тебе, вбивце богів!",
},

[8604] = {
    en = "The Horde Needs Wool Bandages!",
    T = "Орда Потребує Вовняних Бинтів!",
    D = "Вітаю, $c. У рамках підготовки до війни в Ан'Кіражі я координую зусилля Орди зі збору вовняних бинтів. На жаль, у полі наші солдати не можуть розраховувати на присутність цілителя, щоб вижити. Повір, я знаю це з власного досвіду. Тому ми готуємо всі ці аптечки для них.$B$BЯкщо у тебе є час, мені потрібно багато вовняних бинтів. Принеси їх мені сюди, і я подбаю, щоб ти отримав належну нагороду.",
    O = "Принесіть 20 Вовняних Бинтів до Цілителя Далекобіга в Долині Духів в Орґріммарі.",
    P = "Земснаряди є серйозною загрозою, і з ними потрібно швидко боротися!",
    C = "Вам моя щира подяка. Ваші зусилля, спрямовані на допомогу Крепості Кенаріону, показали справжню мужність.",
},

[8605] = {
    en = "The Horde Needs More Wool Bandages!",
    T = "Орда Потребує Більше Вовняних Бинтів!",
    D = "",
    O = "",
    P = "",
    C = "Ви шановний $C, $N! Я подбаю про те, щоб ці бинти потрапили в потрібні руки. Тобі моя вдячність і вдячність Орди.$B$BGo з миром і повернися до мене знову, якщо ти опинишся з надлишком вовни. Ми можемо використати всю допомогу, яку ми можемо отримати тут.",
},

[8606] = {
    en = "Decoy!",
    T = "Приманка!",
    D = "Я придумав! Ось що ми зробимо. Я наповню мішок камінням, а ти зробиш передачу. Я знаю, там сказано, що я маю зробити доставку, і я зроблю — ну, більш-менш.$B$B<Нараїн оглядає тебе з ніг до голови.>$B$BТак, ти цілком підійдеш. Візьми цю тюрбан, мантію і мішок із камінням і вирушай до точки передачі в Зимоключі.$B$BЯ додав усе необхідне в цей спеціальний набір. Коли вони з’являться, щоб забрати товар, знищ їх! Це навчить їх не зв’язуватися з Нараїном!",
    O = "Нараїн Добромисл у Танарісі хоче, щоб ти вирушив до Зимоключа і поклав Мішок із Золотом у точку передачі, вказану викрадачами книги.",
    P = "",
    C = "Я думаю, ми, можливо, недооцінили цих книгокрилів.",
},

[8607] = {
    en = "The Horde Needs Mageweave Bandages!",
    T = "Орда Потребує Маготканинних Бинтів!",
    D = "Сподіваюся, ти розмовляєш зі мною, тому що збираєшся допомогти зі збором, який мені довірили? Чудово! Будь-якими засобами, і я маю на увазі будь-якими, я хочу, щоб ти зібрав хорошу кількість маготканинних бинтів. Свіжі були б ідеальними, але не обов’язково. Принеси їх мені сюди, $c, і я особисто подбаю, щоб ти отримав належну нагороду.",
    O = "Принесіть 20 Маготканинних Бинтів до Леді Каллов у Долині Духів в Орґріммарі.",
    P = "Не підводь і не примушуй мене виглядати погано, $C! Повертайся сюди якомога швидше з пов’язками з магічної тканини, про які ми говорили.",
    C = "Дивно, але прийнятно. Можливо, я недооцінив ваші «здібності», $C. Можливо. Ви виконали дуже просте завдання, і за це ви отримаєте непропорційну винагороду. Але нехай це вам не в голову. Якщо ти справді хочеш проявити себе, ти маєш піти туди і принести мені ще один оберемок бинтів із магічної тканини.",
},

[8608] = {
    en = "The Horde Needs More Mageweave Bandages!",
    T = "Орда Потребує Більше Маготканинних Бинтів!",
    D = "",
    O = "",
    P = "",
    C = "Дивовижно, $C, ти справді зробив це знову! Що ж, вони дійсно кажуть, що я маю гарний смак щодо тих, кого я вирішив поставити на службу. Дуже добре, ваш внесок буде відзначено, і ви отримаєте соціальні переваги, які дали ваші зусилля. Проте я пропоную тобі повернутися та зібрати ще один оберемок бинтів з магічної тканини, якщо ти справді хочеш довести свою цінність.",
},

[8609] = {
    en = "The Horde Needs Runecloth Bandages!",
    T = "Орда Потребує Рунотканинних Бинтів!",
    D = "Схоже, війна між Ордою та Альянсом в Ан'Кіражі неминуча. Дивно, але це не війна між собою, а радше із сілітідами та силою, що ними керує. Також дивно, що обидві сторони роблять свій внесок у збір ресурсів, необхідних для успішної війни.$B$BЯ збираю рунотканинні бинти для роздачі солдатам, але без твоєї допомоги я не впораюся. Чи можеш ти мені допомогти, $c?",
    O = "Принесіть 20 Рунотканинних Бинтів до Кам’яного Стража Глинокопита в Долині Духів в Орґріммарі.",
    P = "Ви отримали отруту?",
    C = "Мила, ти зрозумів!",
},

[8610] = {
