[8728] = {
    en = "The Good News and The Bad News",
    T = "Гарні Новини і Погані Новини",
    D = "Що ж, це зайняло трохи більше часу, ніж я очікував. Тепер дай-но подивлюся, що написано в цій книзі.$B$B<Нараїн мовчки читає книгу, час від часу бурмочучи собі під ніс.>$B$BГарна новина в тому, що я на 99% впевнений, що можу створити арканитовий буй, який відповідатиме твоїм вимогам. Але це, звісно, залежить від поганої новини.$B$BПогана новина в тому, що мені знадобиться багато арканіту, елементієвої руди та рідкісних самоцвітів.$B$BПринеси мені те, що потрібно, і я зроблю буй.",
    O = "Нараїн Добромисл у Танарісі хоче, щоб ти приніс йому 20 Арканитних Злитків, 10 Елементієвої Руди, 10 Азеротських Діамантів і 10 Синіх Сапфірів.",
    P = "Арканітові буї не роблять самі, $N. І НІ, ви не можете позичити трохи грошей.",
    C = "Угода є угода. Сподіваюся, ти знаєш, у що втягуєшся, $N. Це дуже багато клопоту, щоб порибалити.",
},

[8729] = {
    en = "The Wrath of Neptulon",
    T = "Гнів Нептулона",
    D = "Чи я згадував уже про погані новини? Її звати Паща: 100 футів смерті й руйнування. Здається, я міг забути про цю маленьку деталь.$B$BЗгідно з моїм вищим психо-псіонічним ясновидінням, найкраще місце для запуску цього буя — біля узбережжя Азшари, у Затоці Штормів.$B$BШукай вируючий водоворот, найімовірніше, захаращений уламками.$B$BДо речі, сподіваюся, у тебе є друзі.$B$BЯкщо тобі якимось дивом вдасться це зробити, віднеси уламок скіпетра до Анахроноса.",
    O = "Використайте Арканитовий Буй у Вируючому Водовороті в Затоці Штормів в Азшарі.",
    P = "Час спливає, чемпіоне.",
    C = "Молодець, $N. Невдовзі я зможу відновити Скіпетр плинних пісків.",
},

[8730] = {
    en = "Nefarius's Corruption",
    T = "Псування Нефаріуса",
    D = "Чемпіоне, це ти? Тисячу років минуло з того часу, як мені довірили цей уламок, і саме в мою найтемнішу годину з’являється той, хто має звільнити мене від нього... Але що таке трагедія без жорстокості?$B$B<Веластраз слабко кашляє.>$B$BНе... Нефаріус тепер володіє уламком скіпетра.$B$BЧас має значення. Нефаріус планує знищити уламок. Ти мусиш поспішити!",
    O = "Убийте Нефаріана і добудьте Червоний Уламок Скіпетра. Поверніть Червоний Уламок Скіпетра до Анахроноса в Печерах Часу в Танарісі. У вас є 5 годин, щоб виконати це завдання.",
    P = "Ще один наш герой програв породженню Смертокрила. Ми будемо прокляті цими стражданнями назавжди...",
    C = "На душі Ваеластраза спокійно, чемпіоне. Аспекти з великим інтересом спостерігають за вашим прогресом. Знайте, що у вас є могутні союзники.$B$BI отримав наказ надати вам щось, що допоможе вам у цій боротьбі. Використовуйте це добре...",
},

[8731] = {
    en = "Field Duty",
    T = "Польовий Обов’язок",
    D = "Вітаю, $N. Перш ніж я дам тобі складніші завдання у війні, тобі потрібно виконати свою частину польових обов’язків.$B$BТи знайдеш Легіон Орґріммару Капітана Череполама біля Вулика Реґал.$B$BДоповідай йому і повертайся до мене з доказом твоєї польової служби. Я матиму для тебе складніше завдання.$B$BОх, і будь ласка, тримайся подалі від Бригади Залізогарта. Напруга між нашими добровольцями з Альянсу та Орди висока.",
    O = "Доповідай Круґу Череполаму на посту Легіону Орґріммару перед Вуликом Реґал. Підготуй свої Непідписані Польові Папери, отримай Підписані Польові Папери і принеси їх Закликачу Вітру Калдону у Фортеці Кенарія.$B$BПримітка: Зцілення або використання корисних заклинань на членах Легіону Орґріммару позначить вас для PvP.",
    P = "Ви завершили своє польове чергування, $N?  Captain Skullsplit можна знайти за межами Hive'Regal.",
    C = "Я можу сказати, що Krug мало користі від паперової роботи. Він підписав це силітідською кров’ю!$B$BVery добре, $N. Я підготував набір завдань, які повинні добре використовувати ваші навички як $c.$B$BWith постійних зусиль вас і таких, як ви, наш ворог незабаром буде розгромлений!",
},

[8732] = {
    en = "Field Duty Papers",
    T = "Польові Папери",
    D = "",
    O = "",
    P = "Я так розумію, ти хочеш, щоб ці документи були підписані, $Gboy:дівчино;?",
    C = "Так, гадаю, ця невелика сутичка сьогодні пройде як польове чергування. Віднесіть їх назад у Крепость Кенаріону, я впевнений, що вони приготують для вас легку роботу.$B$BOff вперед!",
},

[8733] = {
    en = "Eranikus, Tyrant of the Dream",
    T = "Еранік, Тиран Сну",
    D = "Це подорож спокути, герою. Якби мене зарубали сьогодні, я б помер за справедливу і праведну справу. Ти мусиш добути зелений уламок скіпетра. Ти мусиш очистити Ераніка від скверни, накладеної на нього Старими Богами.$B$BВирушай до Дарнассуса. Біля міських стін ти знайдеш одного з моїх агентів. Цей агент розпочне підготовку і повідомить Тиранду про наші плани, не викликаючи підозр у Стагхелма.$B$B<Малфуріон зітхає.>$B$BПадіння з благодаті, яке триває тисячу років...",
    O = "Вирушайте на континент Телдрассіл і знайдіть агента Малфуріона десь за стінами Дарнассуса.",
    P = "",
    C = "Струмок тихий, за винятком тихого дзижчання. Як не дивно, він здатний спілкуватися з вами за допомогою думок.",
},

[8734] = {
    en = "Tyrande and Remulos",
    T = "Тиранда і Ремулос",
    D = "Тиранда буде повідомлена, смертний. Шан’до Бурешторм підготував мене до цього випадку.$B$BТепер ти мусиш вирушити до Місячної Галявини і поговорити з Ремулосом. Він дасть подальші вказівки щодо виклику Ераніка.$B$BМи всі бажаємо тобі удачі.",
    O = "Вирушайте до Місячної Галявини і поговоріть із Хранителем Ремулосом.",
    P = "",
    C = "Якщо він відмовиться, буде неможливо витягнути Еранікуса зі Сну. Однак його наміри вимагають, щоб він увійшов у наш світ. Він прагне знищити живий прояв Малфуріона. Зробити це успішно означатиме кінець одному з найпотужніших союзників Мрії. Кошмар повністю знищить усе, що залишиться, якщо Малфуріон впаде...",
},

[8735] = {
    en = "The Nightmare's Corruption",
    T = "Скверна Кошмару",
    D = "Ти мусиш вирушити до чотирьох порталів Сма Сма в Азероті. З кожного ти маєш добути фрагмент скверни Кошмару. Драконячі родичі, що населяють ці зони, матимуть такі фрагменти. Повертайся до мене, коли збереш ці фрагменти.",
    O = "Відвідайте чотири портали Сма Сма в Азероті і зберіть по Фрагменту Скверни Кошмару з кожного. Поверніться до Хранителя Ремулоса в Місячній Галявині після виконання цього завдання.",
    P = "<Ремулос глибоко задумався.>",
    C = "Ви готові? Чи готовий світ до того, що ми збираємося викликати? Я не знаю... Я пов'язаний обов'язком перед Малфуріоном. Обов'язок і честь...",
},

[8736] = {
    en = "The Nightmare Manifests",
    T = "Кошмар Матеріалізується",
    D = "Ми мусимо діяти стримано проти Ераніка. Ми маємо спокутувати його, а не знищити.$B$BТиранда вже на шляху, щоб допомогти нам у цьому завданні. Ми мусимо витримати удари дракона і врятувати Ночегавань від певного знищення.$B$BБудь напоготові! Ти і твої союзники — наша єдина надія.",
    O = "Захистіть Ночегавань від Ераніка. Не дайте Хранителю Ремулосу загинути. Не вбивайте Ераніка. Захищайтеся. Чекайте на Тиранду.",
    P = "",
    C = "Він викуплений, $n. Тепер він повертається до Мрії, щоб виправити те, що він один зробив не так. Еранікус стане могутнім союзником Малфуріона та мого батька.$B$BThese зброя для вас, $n; подарована мені самою Ізерою. Тобі було б добре використати їх у битвах проти кіражів.",
},

[8737] = {
    en = "Azure Templar",
    T = "Лазурний Храмовник",
    D = "Молот Сутінків та елементальні вельможі, яких вони шанують, становлять серйозну загрозу для наших операцій у Силіті. З новими ворогами, з якими ми стикаємося в Ан'Кіражі, ми не можемо дозволити собі послабити пильність щодо зовнішніх ворогів.$B$BЗнайди спосіб викликати і знищити Лазурного Храмовника та доповідай Бору Дикогриву.",
    O = "Викличте і знищіть Лазурного Храмовника, а потім доповідайте Бору Дикогриву у Фортеці Кенарія. Для виконання цього завдання також необхідно принести Тактичний Інструктаж I.",
    P = "Твоє завдання вже виконано, $N?",
    C = "Гарна робота, $N. Ось ваше наступне завдання.",
},

[8738] = {
