[8746] = {
    en = "Metzen the Reindeer",
    T = "Метцен, Північний Олень",
    D = "КАТАСТРОФА! Метцена, північного оленя, викрали!$B$BМетцен — один із восьми північних оленів Великого Зимового Діда та власність Smokywood Pastures. Ми отримали не один, а ДВА листи з вимогами викупу від груп, які стверджують, що тримають Метцена. У розпал святкового сезону ми обмежені в коштах! Будь ласка, знайди Метцена та поверни його нам!$B$BПереглянь листи з вимогами викупу для підказок і посип його пилом північного оленя — це звільнить його від будь-яких пут!$B$BБудь ласка, поспіш!",
    O = "Знайди Метцена, північного оленя. Використовуй надані тобі нотатки для підказок, де його тримають.$B$BКоли знайдеш Метцена, май при собі Мішок із Пилом Північного Оленя, щоб посипати його пилом; це має звільнити Метцена від пут полону.$B$BПоверни Мішок із Пилом Північного Оленя до Кеймарда Міднокопита в Оргріммарі після звільнення Метцена.",
    P = "$N!  Ви його знайшли?  Чи було достатньо інформації в нотатках у сумці, яку я вам дав, щоб знайти Метцена?  Мені неприємно думати про те, що ці жорстокі бандити можуть зробити з ним... але ми не можемо дозволити собі заплатити такий непомірний викуп!",
    C = "Ви це зробили!  Ой!$B$BMetzen полетів назад у стайні Прабатька Зими - так, Метцен дійсно може літати - зовсім недавно!  Пил працював як чарівність; Я знав, що буде.  Ви врятували від катастрофи Свято Зимового Покрову, а також Пасовища Димного лісу.  Дякую, $N.$B$BListen... через те, що ти тут зробив, я хочу, щоб ти мав це.  Це щось ДУЖЕ особливе; якщо у вас є маунт, я думаю, ви отримаєте від нього задоволення.  Щасливого зимового покрову!",
},

[8747] = {
