    C = "",
},

[8783] = {
    en = "Extraordinary Materials",
    T = "Незвичайні Матеріали",
    D = "Варгус, коваль Ценаріонської Фортеці, запросив зачаровані матеріали для створення потужної зброї для наших сил. Отримай ці матеріали та принеси їх безпосередньо до Варгуса, щоб війська Ценаріонської Фортеці залишалися добре екіпірованими.",
    O = "Принеси 2 Зачарованих Торієвих Злитки та 2 Зачарованої Шкіри до Варгуса у Ценаріонській Фортеці в Сіліті. Також для виконання цього квесту тобі потрібно принести Логістичне Завдання IX.",
