[8784] = {
    en = "Secrets of the Qiraji",
    T = "Таємниці Кіраджі",
    D = "Ти знайшов стародавній артефакт кіраджі! Можливо, один із драконів біля входу до храму знайде застосування цій реліквії.",
    O = "Віднеси Стародавній Артефакт Кіраджі до драконів, що ховаються біля входу до храму.",
    P = "Ти сяєш! Я знаю, що це означає...",
    C = "Виняткова знахідка, $N. Просто чудово! Це, безумовно, дасть нам трохи зрозуміти спотворені уми наших ворогів.",
},

[8785] = {
    en = "The Orgrimmar Legion Needs Mojo!",
    T = "Легіон Оргріммара Потребує Моджо!",
    D = "Легіон Оргріммара подав запит на кілька незвичайних інгредієнтів. З огляду на їхню поточну діяльність у Сіліті, ми хочемо якомога швидше виконати їхній запит. Збери матеріали та принеси їх до троля на ім’я Шай.",
    O = "Принеси 6 Потужних Моджо, 6 Фляг Великого Моджо та 8 Олій Спалення до Жриці Тіней Шай біля Гнізда Регал у Сіліті. Також для виконання цього квесту тобі потрібно принести Логістичне Завдання IV.",
    P = "У вас є мої матеріали, $N?",
    C = "Ах, так. Саме те, що мені було потрібно! Я зроблю з цього особливу суміш. Силітіду це зовсім не сподобається!",
},

[8786] = {
    en = "Arms for the Field",
    T = "Зброя для Поля",
    D = "Легіон Оргріммара подав запит на додаткову зброю, яку ми наразі не можемо надати. Отримай запитану ними зброю та принеси її до Мерока Довгокрокого біля Гнізда Регал.",
    O = "Принеси 3 Масивні Залізні Сокири до Мерока Довгокрокого в таборі Легіону Оргріммара біля Гнізда Регал. Також для виконання цього квесту тобі потрібно принести Логістичне Завдання VI.",
    P = "Маєш щось для мене, $N?",
    C = "Відмінна робота. У нас їх не вистачало, $N.",
},

[8787] = {
    en = "Armor Kits for the Field",
    T = "Броньові Набори для Поля",
    D = "Хоробрі добровольці Легіону Оргріммара прибули до Сіліті, щоб допомогти нам у нашій справі. Їхні запаси броньових наборів були втрачені під час подорожі. Отримай партію броньових наборів і достав її до Мерока Довгокрокого в табір Легіону Оргріммара.",
    O = "Принеси 8 Міцних Броньових Наборів і 8 Важких Броньових Наборів до Мерока Довгокрокого біля Гнізда Регал. Також для виконання цього квесту тобі потрібно принести Логістичне Завдання VII.",
    P = "Маєш щось для мене, $N?",
    C = "Ах, так... Я роздам це військам, $N. Легіон Оргріммар дякує вам!",
