},

[8789] = {
    en = "Imperial Qiraji Armaments",
    T = "Імперські Обладунки Кіраджі",
    D = "Ми не сиділи склавши руки тисячу років, $N.$B$BМи спостерігали, як ці звірі пожирають своїх, коли вони втрачали свою корисність. Ми слухали, як вони планували та задумували знищення нашого світу. І ми дізналися про їхню внутрішню зраду.$B$BСлабкості існують, і ми знаємо, як використати ці слабкості на нашу користь.$B$BЗнайди та принеси мені їхні церемоніальні обладунки: у поєднанні з елементом, створеним із нестабільності їхнього власного Бога, вони стануть силою розплати.",
    O = "Аріґос у Храмі Ан'Кірадж створить Обладунки, Просочені Елементієм, якщо ти принесеш йому Імперські Обладунки Кіраджі та 3 Руди Елементію.",
    P = "Шукайте те, що я просив. Ти станеш більшим за суму своїх частин, чемпіоне.",
    C = "Наповнена елементієм, ця зброя з неймовірною легкістю проріже кіражів та їхнього Бога.",
},

[8790] = {
    en = "Imperial Qiraji Regalia",
    T = "Імперське Вбрання Кіраджі",
    D = "Аріґос припускає, що елемент, який народжується з конфліктів між Старими Богами та їхніми прислужниками, також надзвичайно смертельний для них за правильних умов. Я говорю про Елементій, смертний.$B$BЗнайди та принеси мені Імперське Вбрання Кіраджі та токсичний елемент, і я просочу зброю великої сили.",
    O = "Мерітра зі Сну в Храмі Ан'Кірадж створить Обладунки, Просочені Елементієм, якщо ти принесеш їй Імперське Вбрання Кіраджі та 3 Руди Елементію.",
    P = "Ви знищите їх і звільните нас від цих пут.",
    C = "Використовуйте предмет добре, $N. Дозвольте їм відчути біль, який вони так бажають заподіяти іншим.",
},

[8791] = {
    en = "The Fall of Ossirian",
    T = "Падіння Оссіріана",
    D = "Жахлива загроза була знищена. Жорстокий Оссіріан зазнав поразки.$B$BЖителі Калімдору з полегшенням дізнаються про цю перемогу. Візьми голову Оссіріана та покажи її командиру Мар’аліту у Ценаріонській Фортеці.",
    O = "Достав Голова Оссіріана Незраненого до Командира Мар’аліта у Ценаріонській Фортеці в Сіліті.",
    P = "Ах, $N, ти повернувся! І одним шматком, я можу додати. Які новини ви привезли з Ahn'Qiraj?",
    C = "Я пропоную вам мою найвищу подяку та ваш вибір предмета сили, $N. Ви зробили людям Калімдору велику послугу.",
},

[8792] = {
    en = "The Horde Needs Your Help!",
    T = "Орді Потрібна Твоя Допомога!",
