[8798] = {
    en = "A Yeti of Your Own",
    T = "Твій Власний Єті",
    D = "",
    O = "",
    P = "",
    C = "Скажи! Знаєте що?! Ти теж інженер! Отже, оскільки ви допомогли мені провчити моїх друзів, я збираюся навчити вас, як зробити свого власного механічного єті! Тепер веселощі можуть тривати вічно, і ви можете налякати кого завгодно! За умови, що ви можете налякати компоненти, щоб зробити це так. $B$BWhat ти кажеш, $N? Хочете дізнатися секрет створення механічного єті?",
},

[8799] = {
    en = "The Hero of the Day",
    T = "Герой Дня",
    D = "Слухай... Я не повинен тобі це розповідати, але оскільки ти герой дня і все таке...$B$BУ цю пору року всюди повно свіжої падуби, але вона ніколи не зберігається. У нас є машина, яка консервує падубу — вона ніколи не псується! Ми використовуємо її, щоб додати святкового настрою... і прибутків улітку!$B$BЯ дозволю тобі скористатися консерватором, але тільки якщо ти майстер кулінарії. Тобі знадобиться глибокоскельна сіль і, скажімо, п’ять золотих. Це дасть тобі гарну партію, яку ти зможеш залишити собі.",
    O = "Принеси 1 Глибокоскельну Сіль і 5 золотих монет до Машини для Консервації Падуби, після чого ти отримаєш 5 Консервованої Падуби.",
    P = "Машина ",
    C = "Коли машина починає працювати, вона видає легкий гуркіт і невелику кількість пари. Незадовго після цього він зупиняється, сповіщаючи про те, що з нього виривається ще один невеликий струмінь пари. Дверний люк відчиняється, показуючи партію консервованого падуба!",
},

[8800] = {
    en = "Cenarion Battlegear",
    T = "Ценаріонське Бойове Спорядження",
    D = "Виконуючи завдання у війні, тобі варто поговорити з Варгусом, ковалем. Покажи йому будь-які значки, які ти здобув. Він надасть тобі спорядження, яке відповідає твоєму рівню відданості нашій справі.",
    O = "Поговори з Варгусом у Ценаріонській Фортеці в Сіліті.",
    P = "",
    C = "Тебе прислав Калдон? Добре, давайте подивимося, що ми можемо для вас зробити.",
},

[8801] = {
    en = "C'Thun's Legacy",
    T = "Спадщина К’Туна",
    D = "Стіни Ан'Кірадж тремтять. Сила зла, старша за сам світ, була знищена.$B$BДивлячись на залишки колосальної гидоти, твоє серце ледь не завмирає. Навіть у смерті ти відчуваєш спадщину зла К’Туна навколо себе.$B$BТи зробив те, що вважалося неможливим.$B$BТи хапаєш очний стебель чудовиська, надійно ховаючи його у свій наплічник.$B$BВіднеси Око К’Туна до драконів у наступній залі.",
    O = "Віднеси Око К’Туна до Цаеластраза у Храмі Ан'Кірадж.",
    P = "Леді $N, ви звільнили нас від його рук.",
    C = "Ми залишимо це місце самостійно, леді $N, як тільки ми переконаємося, що зло всередині було повністю знищено. Ваша легендарна подорож майже добігає кінця.",
},

[8802] = {
    en = "The Savior of Kalimdor",
    T = "Рятівник Калімдору",
    D = "До Печер Часу тобі, $G Лорде:Леді; $N. Анахронос чекає на твоє повернення. Дай йому Око К’Туна, адже він, безсумнівно, захоче додати його до колекції свого господаря.",
    O = "Віднеси Око К’Туна до Анахроноса у Печерах Часу.",
    P = "Господи $N! Це кінець...",
    C = "Майстер залишив це для вас, чемпіоне. З позачасового сховку: колекція артефактів, що охоплюють тисячі років – вибір за вами.",
},

[8803] = {
    en = "A Festive Gift",
    T = "Святковий Подарунок",
    D = "",
    O = "",
    P = "",
    C = "Примітка на цьому подарунку говорить:$b$bTo $n,$b$bIn, сподіваючись, що це допоможе вам поширити теплі новини та святковий настрій у всьому Азероті.$b$bFrom Прабатько Зима",
},

[8804] = {
    en = "Desert Survival Kits",
    T = "Набори Виживання в Пустелі",
    D = "З прибуттям нових рекрутів до Ценаріонської Фортеці постає проблема їхнього виживання в пустелі. Зневоднення та численні отруйні створіння становлять серйозну загрозу для недосвідчених добровольців. Збери необхідні припаси для набору виживання в пустелі та принеси їх до Каландрати у Ценаріонській Фортеці.",
    O = "Принеси 4 Кулі Води, 4 Потужні Антиотрути та 4 Копчені Пустельні Пельмені до Каландрати в таверні Ценаріонської Фортеці в Сіліті. Також для виконання цього квесту тобі потрібно принести Логістичне Завдання I.",
    P = "",
    C = "",
},

[8805] = {
    en = "Boots for the Guard",
    T = "Чоботи для Охорони",
    D = "Кінний загін охорони Ценаріонської Фортеці відчуває нестачу оздоблених міфрилових чобіт. Отримай партію та негайно достав її до капітана Віша Козуса у Ценаріонській Фортеці.",
    O = "Принеси 3 Оздоблені Міфрилові Чоботи до Віша Козуса, капітана охорони Ценаріонської Фортеці в Сіліті. Також для виконання цього квесту тобі потрібно принести Логістичне Завдання II.",
    P = "",
    C = "",
},

[8806] = {
    en = "Grinding Stones for the Guard",
    T = "Точильні Камені для Охорони",
    D = "Охорона Ценаріонської Фортеці відчуває нестачу точильних каменів. Отримай партію та негайно достав її до капітана Віша Козуса у Ценаріонській Фортеці.",
    O = "Принеси 10 Щільних Точильних Каменів, 10 Твердих Точильних Каменів і 10 Важких Точильних Каменів до Віша Козуса, капітана охорони Ценаріонської Фортеці в Сіліті. Також для виконання цього квесту тобі потрібно принести Логістичне Завдання III.",
    P = "",
    C = "",
},

[8807] = {
    en = "Scrying Materials",
    T = "Матеріали для Ворожіння",
    D = "Дослідження геолога Ларксбейна виявилися надзвичайно цінними для наших операцій у Сіліті. Вона нещодавно запросила матеріали для ворожіння, які потрібні для її досліджень.$B$BБудь ласка, збери ці матеріали та достав їх безпосередньо до неї, щоб вона могла продовжити свої дослідження.",
    O = "Принеси 1 Великий Сяючий Уламок, 1 Великий Променистий Уламок і 1 Величезний Смарагд до Геолога Ларксбейна у Ценаріонській Фортеці в Сіліті. Також для виконання цього квесту тобі потрібно принести Логістичне Завдання V.",
    P = "",
    C = "",
},

[8808] = {
    en = "Uniform Supplies",
    T = "Запаси Уніформи",
    D = "Останній приплив добровольців спричинив нестачу уніформи. Отримай партію матеріалів для уніформи та принеси їх до Вітрозова Гордоклика.",
    O = "Принеси 1 Місячну Тканину, 2 Відрізки Рунної Тканини та 1 Залізопавутинний Шовк до Вітрозова Гордоклика у Ценаріонській Фортеці в Сіліті. Також для виконання цього квесту тобі потрібно принести Логістичне Завдання VIII.",
    P = "",
    C = "",
},

[8809] = {
    en = "Extraordinary Materials",
    T = "Незвичайні Матеріали",
    D = "Варгус, коваль Ценаріонської Фортеці, запросив зачаровані матеріали для створення потужної зброї для наших сил. Отримай ці матеріали та принеси їх безпосередньо до Варгуса, щоб війська Ценаріонської Фортеці залишалися добре екіпірованими.",
    O = "Принеси 2 Зачарованих Торієвих Злитки та 2 Зачарованої Шкіри до Варгуса у Ценаріонській Фортеці в Сіліті. Також для виконання цього квесту тобі потрібно принести Логістичне Завдання IX.",
    P = "",
    C = "",
},

[8810] = {
