[8827] = {
    en = "Winter's Presents",
    T = "Зимові Подарунки",
    D = "Я чув, що Великий Зимовий Дід — за щедрої підтримки Smokywood Pastures — поклав подарунки для всіх під ялинку в Залізогарті. Хотів би я піти, але я мушу доглядати за PX-238 Зимовим Чудо-вольтом.$B$BАле тобі точно варто це перевірити. Я впевнений, що Великий Зимовий Дід має подарунки з твоїм ім’ям.",
    O = "Поговори з Великим Зимовим Дідом. Він розташований біля торгової зони Smokywood Pastures у Залізогарті.",
    P = "",
    C = "Ой, привіт! Ви можете бути тут лише з однієї причини: відкрити свої подарунки Winter Veil.$B$BNow, не хвилюйтеся, Дід Зима не забув про свого улюбленця $R $C. Подивіться під ялинку, і ви знайдете свої подарунки.$B$BDuring у цей сезон дарувань, можливо, вашим друзям також сподобається отримати деякі чудові продукти Smokeywood Pasture?",
},

[8828] = {
    en = "Winter's Presents",
    T = "Зимові Подарунки",
    D = "Я чув, що Великий Зимовий Дід — за щедрої підтримки Smokywood Pastures — поклав подарунки для всіх під ялинку в Оргріммарі. Хотів би я піти, але я мушу доглядати за PX-238 Зимовим Чудо-вольтом.$B$BАле тобі точно варто це перевірити. Я впевнений, що Великий Зимовий Дід має подарунки з твоїм ім’ям.",
    O = "Поговори з Великим Зимовим Дідом. Він розташований біля торгової зони Smokywood Pastures в Оргріммарі.",
    P = "",
    C = "Ой, привіт! Ви можете бути тут лише з однієї причини: відкрити свої подарунки Winter Veil.$B$BNow, не хвилюйтеся, Дід Зима не забув про свого улюбленця $R $C. Подивіться під ялинку, і ви знайдете свої подарунки.$B$BDuring у цей сезон дарувань, можливо, вашим друзям також сподобається отримати деякі чудові продукти Smokeywood Pasture?",
},

[8829] = {
    en = "The Ultimate Deception",
    T = "Найвищий Обман",
    D = "Сутінковий Молот діє через незліченні шари секретності та обману. Хоча їхні дії здійснюються в нашому світі, вони плануються в місці, до якого ми ще не змогли дістатися.$B$BМи дійшли висновку, що камені, які Сутінковий Молот використовує для виклику своїх зверхників, дозволяють двонаправлене транспортування. Щоб спробувати використати їх у такий спосіб, ми мусимо відтворити — до найдрібніших деталей — мантію сутінкового емісара.$B$BЗбери необхідні матеріали та принеси їх до Аурела Золотолиста, $N.",
    O = "Принеси 1 Шкіру Тіні, 3 Пошматовані Шви Мерзоти та 1 Мантію Культиста Сутінків до Аурела Золотолиста у Ценаріонській Фортеці в Сіліті. Також для виконання цього квесту тобі потрібно принести Логістичне Завдання XI.",
    P = "",
    C = "",
},

[8830] = {
    en = "One Commendation Signet",
    T = "Один Знак Визнання",
    D = "",
    O = "",
    P = "Для тих авантюристів, у яких є лише одна печатка подяки, я обміняю її на невелику кількість визнання зі Штормовієм.$B$BPlease майте на увазі, що краще передати стопку з десяти печаток одночасно; при цьому ваші зусилля отримають більше визнання. Ми пропонуємо обмін одним підписом як послугу для тих, у кого недостатньо для повного стосу з десяти.$B$BWith Зважаючи на це, я готовий допомогти вам, якщо ви все ще бажаєте здати один підпис.",
    C = "Дуже добре - ваші справи були внесені до протоколів, і ви належним чином відзначені за ваші зусилля. Продовжуйте працювати так само, $C.$B$BIf у вас є ще якісь підписи для здачі, тоді я зможу допомогти вам у цьому.",
},

