[8857] = {
    en = "Secrets of the Colossus - Ashi",
    T = "Таємниці Колоса - Аші",
    D = "Я шукаю загартованих у боях шукачів пригод, готових і здатних отримати свіжий зразок оболонки з поваленого Колоса Аші до Оглеторпа в Піратській Бухті. Ні, ні, я б не хотів, щоб ти наближався до трупа цієї штуки. Просто візьми один із моїх зразків і поспіш. Ці штуки не принесуть йому користі, якщо зіпсуються!",
    O = "Віднеси Оболонку Колоса Аші до Оглеторпа Обнотикса в Піратській Бухті.",
    P = "Так? Що у вас там?",
    C = "Ох, які курчата я зліплю з цієї чудової лушпиння! Молодець, моя $gboy:дівчинка; !",
},

[8858] = {
    en = "Secrets of the Colossus - Regal",
    T = "Таємниці Колоса - Регал",
    D = "Немає нічого, що я хотів би більше, ніж засунути цю оболонку комахи в товсте обличчя Ойлфіста... Але я застряг тут, збираючи зразки з цього гігантського таргана. Я буду тут до пізньої ночі, враховуючи розмір цієї штуки.$B$BВізьми цей зразок до Ойлфіста за мене і зроби це швидко, $c. Він платить ВЕЛИКІ ГРОШІ!$B$BЯр, Торієвий Пункт — це в Палаючій Ущелині.",
    O = "Віднеси Оболонку Колоса Регал до Наглядача Ойлфіста в Палаючій Ущелині.",
    P = "Хмм...",
    C = "Чудово. З цього хітину ми напевно могли б створити неймовірно потужну броню. Ось багатство, яке тобі обіцяли.",
