},

[8860] = {
    en = "New Year Celebrations!",
    T = "Святкування Нового Року!",
    D = "Штормовій святкує Новий рік! Цілий день сьогодні можна отримати безкоштовне пиво, а ввечері влаштують шоу феєрверків! Це має бути досить гарно... але Піратська Бухта також влаштовує вечірку сьогодні; я впевнений, що вона буде ще кращою!$B$BТак чи інакше, шинкарка Аллісон у Штормовії потребує припасів від Smokywood Pastures, щоб нагодувати всіх гостей вечірки. Чи не могли б ви зробити мені послугу і доставити їх?$B$BДякую, $N! Шинкарка Аллісон знаходиться в таверні «Золота Троянда» у Торгівельному районі Штормовія.",
    O = "Достав Припаси Smokywood до Шинкарки Аллісон у Штормовії.",
    P = "вітаю! Ви тут на вечірку! Або, можливо, вам просто потрібно відпочити своїм стомленим ногам...",
    C = "О, мої запаси Smokywood! Чудово! Це мені знадобиться, щоб нагодувати всіх людей у ​​місті на святкування!$B$BThank ти, $N. Будь ласка, прийміть це як оплату та не забудьте випити й потанцювати з гуляками на вулиці!",
},

[8861] = {
    en = "New Year Celebrations!",
    T = "Святкування Нового Року!",
    D = "Громовий Бескид святкує Новий рік! Цілий день там можна отримати безкоштовне пиво, а ввечері влаштують шоу феєрверків!$B$BЦе має бути досить гарно... але Піратська Бухта також влаштовує вечірку сьогодні; я впевнений, що вона буде ще кращою!$B$BТак чи інакше, шинкарка Пала в Громовому Бескиді потребує припасів від Smokywood Pastures, щоб нагодувати всіх гостей вечірки. Чи не могли б ви зробити мені послугу і доставити їх?$B$BДякую, $N! Шинкарка Пала знаходиться в таверні біля мосту до Сходження Мисливців.",
    O = "Достав Припаси Smokywood до Шинкарки Пали в Громовому Бескиді.",
    P = "Доброго дня, $C! Ви прийшли в Тандер Блафф на наші святкування?  Або ти тут, щоб відпочити втомленому копиту між полюваннями?",
    C = "О, дуже добре! Ці запаси допоможуть нагодувати всіх наших людей, які тут святкують новий рік!$B$BI дякую, $N. Ви в моєму боргу. Будь ласка, візьміть ці монети... і прислухайтесь до моєї поради — пийте від душі з бочок надворі та приєднуйтесь до наших гуляк у святковому танці!",
},

[8862] = {
    en = "Elune's Candle",
    T = "Свічка Елуни",
    D = "",
    O = "",
    P = "Свічка Елуни є артефактом великої пошани для послідовників Місячного свята. У свічці зберігається справжнє місячне світло, готове до виходу на волю!$B$BThis світло нешкідливе для більшості істот, але ви побачите, що Омен і його слуги обпалені та засліплені ним.",
    C = "Тоді добре — я приймаю ці монети походження. Будь ласка, візьміть свічку Елуни з мого благословення. Також, будь ласка, насолоджуйтеся цими безкоштовними феєрверками.$B$BMay нехай ваш Місячний фестиваль буде радісним і сповненим веселощів, $N.$B$BAnd якщо ви вирішите зіткнутися з Оменом і його прихильниками, свічка Елуни буде вам дуже корисна...",
},

[8863] = {
    en = "Festival Dumplings",
    T = "Фестивальні Пельмені",
    D = "",
    O = "",
    P = "",
    C = "Чудово - будь ласка, насолоджуйтеся цими варениками з моїми компліментами. Хоча вони лише невеликий знак вдячності за честь, яку ви принесли собі своїми діями, я думаю, ви все одно будете насолоджуватися ними.$B$BShould у вас є ще монети предків, я готовий запропонувати вам широкий спектр предметів в обмін.",
},

[8864] = {
    en = "Festive Lunar Dresses",
    T = "Фестивальні Місячні Сукні",
    D = "",
    O = "",
    P = "У мене є добірка суконь, які можуть вас зацікавити.  Такі сукні носили в минулі часи під час Місячного фестивалю, і вибір, який я маю сьогодні, мабуть, найкращий, який я коли-небудь бачив.  Кожен виготовлений вручну лише з найкращих і найм’якших компонентів.$B$BIn обміняйте на кілька монет походження, я дозволю вам вибрати один із трьох стилів, які я маю зберегти як ваші.  Це прийнятно для вас?",
    C = "Тоді добре — я приймаю ці монети походження. Будь ласка, візьміть свою сукню з мого благословення. Також, будь ласка, насолоджуйтеся цими безкоштовними феєрверками.$B$BAs ви вшанували своїх старших, ви вшановуєте мене своєю простою присутністю. Дякую, і нехай ваше Місячне свято буде радісним.",
},

[8865] = {
    en = "Festive Lunar Pant Suits",
    T = "Фестивальні Місячні Костюми",
    D = "",
    O = "",
    P = "Хочу повідомити вам, що я маю чудовий вибір святкових брючних костюмів, які ви можете придбати... але лише в обмін на монети предків.  Якщо для вас важлива мода, то це те, що ви шукаєте!  Я запевняю вас, що ви більше ніде не знайдете подібних брючних костюмів.$B$BIn обміняйте на монети предків, я дозволю вам вибрати один із трьох стилів, які я маю зберегти як ваші.  Це прийнятно для вас?",
    C = "Тоді добре — я приймаю ці монети походження. Будь ласка, візьміть свій брючний костюм з мого благословення. Також, будь ласка, насолоджуйтесь цим безкоштовним феєрверком.$B$BShould у вас є більше монет походження, щоб обміняти, тоді поговоріть зі мною знову. Я буду пропонувати різні предмети протягом усього Місячного фестивалю.",
},

[8866] = {
    en = "Bronzebeard the Elder",
    T = "Бронзобород Старший",
    D = "",
    O = "",
    P = "",
    C = "Приємно знати, що люди цієї землі все ще віддають шану давнім расам. Я пропоную тобі добре, $N, і пропоную тобі цей жетон...",
},

[8867] = {
    en = "Lunar Fireworks",
    T = "Місячні Феєрверки",
    D = "Щороку друїди Місячної Галявини влаштовують святкування великого тріумфу нашого міста над стародавнім злом.$B$BМи вшановуємо мудрість наших старійшин, ділимося чудовими бенкетами і, звісно... запускаємо феєрверки!$B$BЗа невеликий внесок ти можеш придбати барвисті ракети у нашого торговця. Спробуй використати деякі пускові установки тут, $N.",
    O = "Запусти 8 Місячних Феєрверків і 2 Скупчення Феєрверків та повернися до Вісника Місячного Фестивалю в будь-якому столичному місті.",
    P = "Ти знайшов пускові установки, $N?",
    C = "Молодець, $N.$B$BNow, що ти в дусі речей, чому б тобі не прийняти це запрошення на фестиваль у Місячній поляні.$B$BIt дуже приємне святкування, якщо у тебе є вільний час.  Ми ділимося їжею, напоями, історіями і, звичайно,... ще феєрверками!$B$BOpen запрошення, стоячи в колі більшого місячного світла, і ви потрапите до Місячної поляни.",
},

[8868] = {
    en = "Elune's Blessing",
    T = "Благословення Елуни",
    D = "Звір Омен колись був героєм цього світу. Вовк великої сили та удачі, Омен боровся пліч-о-пліч із героями Війни Стародавніх, поки не піддався демонічним чарам. Повернувшись проти своїх союзників, він лютував по Азероту, несучи смерть і жах за собою.$B$BНарешті переможений тут, у Місячній Галявині, Омен тепер спить серед мулу озера Елуне’ара. Але щороку, під час фестивалю, він ворушиться...$B$BЗбери товаришів, $N, і виклич та перемож звіра Омена. Здобудь благословення Елуни!",
    O = "Виклич Омена, переможи його та отримай Благословення Елуни. Повернися до Валадара Зіркоспіва у Ночегавані.",
    P = "",
    C = "Отримайте благословення Елуни.",
},

