[8883] = {
    en = "Valadar Starsong",
    T = "Валадар Зіркоспів",
    D = "Тепер, коли у тебе є запрошення на Місячний Фестиваль, ти можеш вирушити до Місячної Галявини! Там ти знайдеш багато гуляк, а в селі Ночегавань Валадар Зіркоспів та його сестра Фаріель чекають на тих, хто прагне взяти участь у святкуванні.$B$BВирушай до Місячної Галявини через велике місячне світло та поговори з Валадаром Зіркоспівом; подивися, які нагороди ти можеш отримати під час фестивалю!",
    O = "Використай своє Запрошення на Місячний Фестиваль у місячному світлі, щоб вирушити до Місячної Галявини. Поговори з Валадаром Зіркоспівом у Ночегавані, коли прибудеш.",
    P = "",
    C = "$N, ласкаво просимо до Nighthaven, хоста Місячного фестивалю!  Хоча наше село зазвичай віддалено й ізольовано від людей Азероту, у цей час святкування ми відкриваємо свої обійми й серця для всіх.$B$BEnjoy ваш візит, $n, і поговоріть зі мною чи моєю сестрою знову, коли будете готові.",
},

[8893] = {
    en = "The Super Egg-O-Matic",
    T = "Супер Яйце-О-Матик",
    D = "",
