[8921] = {
    en = "The Ectoplasmic Distiller",
    T = "Ектоплазматичний Дистилятор",
    D = "Ах, тобі потрібен мій останній проєкт... позавимірний виявляч привидів! На жаль, у мене закінчилися кошти та робоча сила.$B$BТи готовий допомогти? Чудово! Наше перше завдання — створити пристрій для збирання самої тканини смерті! Створити ектоплазматичний дистилятор — нелегка справа, $N.$B$BТобі потрібно принести мені арканітовий конвертер, кілька великих вічних есенцій та олію каменелусків. Також мені знадобиться трохи вулканічного попелу з лавових басейнів у Палаючих Степах для створення фільтра.",
    O = "Повернися до Мукса Манаскрамблера в Ґаджетзані з 1 Тонким Арканітовим Конвертером, 4 Великими Вічними Есенціями, 10 Оліями Каменелусків, 25 Вулканічним Попелом і 40 золотими.",
    P = "Я розумію, що матеріали дещо дорогі... але я обіцяю вам, що всі вони знадобляться!",
    C = "Це саме ті матеріали, які мені були потрібні. Досить вчасно, $N!$B$BIn за хвилину я підготую ваш дистилятор до роботи! Тим часом сприймайте це як нагороду за допомогу мені в моєму проекті.",
},

[8922] = {
    en = "A Supernatural Device",
    T = "Надприродний Пристрій",
    D = "Я мушу знайти спосіб поговорити з Антіоном Гармоном... або, точніше, з його привидом!$B$BЯ знаю інженера з дивним інтересом до надприродного. Він стверджує, що може створити машину, яка дозволить спілкуватися з мертвими!$B$BКров, яку ти зібрав, призначена для нього; вируш до Ґаджетзана та принеси її йому як плату за його послуги!",
    O = "Принеси Запечатаний Контейнер із Кров’ю до Мукса Манаскрамблера в Ґаджетзані, Танаріс.",
    P = "Маєш щось для мене?",
    C = "Чудово! Якраз коли я закінчився!$B$BYou скажи, що тебе прислала Деліана?",
},

[8923] = {
    en = "A Supernatural Device",
    T = "Надприродний Пристрій",
    D = "Ти доволі сміливий, якщо залишився після цього. Або ж я зацікавив тебе частиною броні, яку тобі дав. Є ще більше, звідки вона взялася, якщо ти все ще хочеш допомагати мені.$B$BЗразки отрути, які ти зібрав, призначені для мого знайомого, Мукса Манаскрамблера, інженера з інтересом до надприродного. Його останній проєкт — це пристрій, який дозволяє спілкуватися з мертвими! Моя остання надія — зв’язатися з Антіоном і дізнатися більше про мою ситуацію.",
    O = "Принеси Запечатаний Контейнер із Отрутою до Мукса Манаскрамблера в Ґаджетзані.",
    P = "Ви хочете поговорити зі мною?",
    C = "Чудово! Так само, як я закінчився!$B$BYou скажи, що тобі прислав Моквар?",
},

[8924] = {
    en = "Hunting for Ectoplasm",
    T = "Полювання за Ектоплазмою",
    D = "Чудовий витвір інженерії, якщо я сам так скажу! Боюся, тобі доведеться трохи помандрувати, щоб знайти потрібних нам безтілесних мерців.$B$BРізні кліматичні умови надають різної консистенції спектральній тканині мертвих. Замучені нічні ельфи Силіта, духи вищих ельфів із Зимоключа та привиди й банші зі Східних Зачумлених Земель дадуть нам різні типи ектоплазми, які нам потрібні. Не забудь розмістити дистилятор поблизу, перш ніж збирати їх!",
    O = "Використовуй Ектоплазматичний Дистилятор біля безтілесних мерців, щоб зібрати 12 Обпалених Ектоплазм у Силіті, 12 Заморожених Ектоплазм у Зимоключі та 12 Стабільних Ектоплазм у Східних Зачумлених Землях. Принеси їх разом із Ектоплазматичним Дистилятором назад до Мукса Манаскрамблера в Ґаджетзані.",
    P = "Ти вже зібрав ектоплазму, $R?",
    C = "Так, вони чудово підійдуть!$B$BBy використовуючи потойбічні енергії, що містяться в цих речовинах, ми зможемо достукатися до тих, чиї душі ще не покинули цей світ!",
},

[8925] = {
    en = "A Portable Power Source",
    T = "Портативне Джерело Енергії",
    D = "Далі нам потрібно знайти стабільне та портативне джерело енергії, щоб підтримувати ектоплазму активною. Я чув чутки про могутнього елементаля на ім’я Лорд Магми Бокк, чиє серце — це потужне магмове ядро, нескінченне джерело тепла!$B$BКажуть, його можна знайти в Палаючих Степах, на південь від Чорноскельної Гори. Принеси мені магмове ядро, і ми матимемо достатньо енергії для живлення позавимірного виявляча привидів!",
    O = "Знайди Лорда Магми Бокка в Палаючих Степах, отримай його Магмове Ядро та принеси його до Мукса Манаскрамблера в Ґаджетзані.",
    P = "Ти знайшов Володаря Магми, $N?",
    C = "Ви зробили це! Це, безсумнівно, забезпечить достатньо енергії, щоб активувати надвимірний розкривач привидів!",
},

[8926] = {
    en = "Just Compensation",
    T = "Справедлива Компенсація",
    D = "Ти дотримав слова і приніс пристрій, створений Муксом. Я вважаю, що нагорода доречна, якщо я хочу, щоб ти залишався зацікавленим у порятунку моєї шкури. Принеси мені пояс і пару рукавиць, які ти хочеш покращити. Я обіцяю, що ті, які я дам натомість, будуть значно кращими.",
    O = "Принеси Пояс Дикого Серця та пару Рукавиць Дикого Серця до Деліани в Залізогарт.",
    P = "Ви готові здійснити торгівлю?",
    C = "Ви виконали свою частину угоди, я виконаю свою.$B$BJust пам’ятайте, що я тримаю найкращі речі, доки ваша робота не буде завершена.",
},

[8927] = {
    en = "Just Compensation",
    T = "Справедлива Компенсація",
    D = "Ти виявився дуже надійною особою, $N. Хоч я й вірю, що ти допоможеш мені в цій скруті, було б розумно винагороджувати тебе відповідно до твоїх зусиль.$B$BНаразі я обміняю твій пояс і рукавиці. Якщо ми обоє доведемо це до кінця, я зроблю решту частин доступними для тебе.",
    O = "Принеси Пояс Дикого Серця та пару Рукавиць Дикого Серця до Моквара в Орґріммар.",
    P = "Ви готові здійснити обмін?",
    C = "Наша домовленість залишається в силі. Тільки пам’ятайте, це лише смак того, що вас чекає. Звільни мене від цієї проклятої долі, і я винагороджу тебе предметами справді великої сили.",
},

[8928] = {
    en = "A Shifty Merchant",
    T = "Хитрий Торгівець",
    D = "Ядро дасть нам достатньо енергії для живлення нашого пристрою; тепер нам лише потрібно створити стрижень, який зможе спрямовувати цю енергію, не розплавляючись.$B$BЯ зустрів біса в Зимоключі, який продавав усілякі екзотичні товари. У нього був елементальний стрижень, який ідеально підійшов би. Я досі картаю себе за те, що не купив його.$B$BВін живе в печері біля входу до Темношепотної Ущелини. Прокрадися туди і спробуй його знайти.$B$BПереконайся, що він візьме лише сорок золотих; це ціна, яку він мені назвав!",
