[8977] = {
    en = "Return to Deliana",
    T = "Повернення до Деліани",
    D = "Співпраця з тобою була чудовою, $N. Ось готовий виріб.$B$BСподіваюся, він допоможе тобі в твоїх поточних справах. І, якщо не заперечуєш, розкажи про мене іншим. Я не проти мати більше клієнтів!",
    O = "Принеси Надпросторовий Виявник Привидів до Деліани в Залізогарті.",
    P = "Ти повернувся?",
    C = "Чудово! Ти добре впорався, $N. Я не впевнений, що довіряю майстерності гобліна, але в мене не залишається іншого вибору.",
},

[8978] = {
    en = "Return to Mokvar",
    T = "Повернення до Моквара",
    D = "Співпраця з тобою була чудовою, $N. Ось готовий виріб.$B$BСподіваюся, він допоможе тобі в твоїх поточних справах. І, якщо не заперечуєш, розкажи про мене іншим. Я не проти мати більше клієнтів!",
    O = "Повернися до Моквара в Оргріммарі з Надпросторовим Виявником Привидів.",
    P = "Ви повернулися з пристроєм?",
    C = "Ви повернулися з пристроєм! Я вражений вашою відданістю, $N. Відмінна робота.",
},

[8979] = {
    en = "Fenstad's Hunch",
    T = "Передчуття Фенстада",
    D = "Я вважаю, що знаю причину цієї нещодавньої поведінки. Чи відчув ти новий аромат у повітрі, що перебиває сморід каналів? Нові одеколони та парфуми, які стали модними?$B$BНаші думки затьмарені якоюсь мерзенною алхімією.$B$BЄ лише один спосіб переконатися — принеси флакон одеколону та парфумів до мого друга, аптекаря Зінге. Королівське Аптекарське Товариство дізнається правду.$B$BЯ відшкодую тобі витрати на їхню покупку, коли повернешся.",
    O = "Принеси 1 Флакон Одеколону та 1 Флакон Парфумів до Аптекаря Зінге в Аптекаріумі Мертвого Міста.",
    P = "Як я можу вам служити?",
    C = "Як я бачу, ще одна з одержимостей Фенстада. Невже він вважає, що Королівське аптекарське товариство не має нічого кращого, ніж проводити його невеликі дослідження?$B$BVery що ж, я ще раз потішу його.",
},

[8980] = {
    en = "Zinge's Assessment",
    T = "Оцінка Зінге",
    D = "Це несподівано. Схоже, Фенстад таки натрапив на щось. Я виявив сліди речовин, що використовуються в зіллях контролю розуму.$B$BНе рідкість, коли парфуми містять дещо з цього, але деякі інгредієнти, які я виявив... Це серйозна алхімія, на рівні здібностей члена Королівського Аптекарського Товариства.",
    O = "Повернися до Фенстада Арґайла біля банку в Мертвому Місті.",
    P = "",
    C = "Отже, я мав рацію. Ми не повинні гаяти часу. Ми повинні визначити джерело цих зіпсованих ароматів.$B$BHere, щоб відплатити вам за покупку одеколону та парфумів.",
},

