[9015] = {
    en = "The Challenge",
    T = "Виклик",
    D = "Слухай уважно, $N. Щоб прапор спрацював так, як потрібно, тобі доведеться увійти до Кільця Закону в Чорнокам’яних Надрах. Дозволь Верховному Судді Грімстоуну винести тобі вирок і міцно встанови Прапор Провокації на землі як знак зухвалості.$B$BТвоя жертва не зможе стриматися й кинеться в бій, сповнена бажання битися з тобою. Після того, як ти отримаєш те, що шукаєш, повертайся до Антіона.",
    O = "Вируш до Кільця Закону в Чорнокам’яних Надрах і розмісти Прапор Провокації в його центрі, коли Верховний Суддя Грімстоун виноситиме тобі вирок. Убий Тельдрена та його гладіаторів і повернися до Антіона Гармона в Східних Зачумлених Землях із першою частиною амулета Лорда Валталака.",
    P = "Ти повернувся, $N!",
    C = "Ви знайшли частину медальйона, $N?",
},

[9016] = {
    en = "Anthion's Parting Words",
    T = "Прощальні Слова Антіона",
    D = "Душа Валталака була захована в цьому амулеті. У своїй жадібності ми нерозумно розділили його на три частини, не знаючи, яке прокляття на нас чекає.$B$BЄдиний спосіб зупинити закляття Валталака — це знову зібрати амулет. Повертайся до Моквара та скажи йому, що Бодлі — його єдина надія знайти решту частин. Поговори з ним про будь-які нагороди, які ти домовився отримати.$B$BЯ, нарешті, спочину з миром. Бажаю тобі найкращої удачі; вона тобі знадобиться!",
    O = "Повернися до Моквара в Оргріммарі з Чоботами Дикого Серця, Кілтом Дикого Серця та Наплічниками Дикого Серця.",
    P = "Ти повернувся, і я бачу в твоїх очах, що ти маєш багато мені розповісти, $N.  Дозвольте нам спочатку подбати про вашу винагороду.",
    C = "Це прокляття було накладено на нас, але лише за медальйон. Лорд Валталак точно вміє тримати в собі образу.$B$BWe докладу зусиль, щоб знайти залишки — сподіваюся, до того, як я зустріну передчасну смерть. Але перед цим давайте подивимося про вашу нагороду.",
},

