[9023] = {
    en = "The Perfect Poison",
    T = "Ідеальна Отрута",
    D = "Мій брат і я керуємо операціями з отрутами з маєтку Рейвенхолдт.$B$BЛорд Рейвенхолдт доручив мені відстежити нову та надзвичайно ефективну отруйну суміш, яку можна створити з отруйних мішечків мешканців Зул’Гуруба та Руїн Ан’Кіражу.$B$BУ тих проклятих руїнах мешкають два особливо отруйних звірі, які мають те, що нам потрібно, $c. Принеси мені отруйний мішечок від звірів Куріннакса та Веноксіса, і ми будемо вічно вдячні.",
    O = "Дірк Громодрев у Ценаріонській Фортеці хоче, щоб ти приніс йому Отруйний Мішечок Веноксіса та Отруйний Мішечок Куріннакса.",
    P = "Це не робота, $N. Вам потрібно буде взяти з собою друзів.",
    C = "Ravenholdt дякує тобі, герою! Вибирайте!",
},

[9024] = {
    en = "Aristan's Hunch",
    T = "Передчуття Арістана",
    D = "Я зрозумів! Чи відчув ти новий аромат у повітрі? Нові одеколони та парфуми, які стали модними? Наші вартові не нехтували б своїми обов’язками так легко.$B$BХіба що їхні думки не затьмарила якась мерзенна алхімія.$B$BЄ лише один спосіб переконатися — принеси флакон одеколону та парфумів до Моргана Пестла і розкажи йому про мої підозри. Я відшкодую тобі витрати на їхню покупку, коли повернешся.",
    O = "Принеси 1 Флакон Одеколону та 1 Флакон Парфумів до Моргана Пестла в Торгівельному Районі Штормовію.",
    P = "Чимось я можу вам допомогти?",
    C = "Я розумію занепокоєння Арістана, але справді думаю, що він надмірно реагує. Нехай юнаки й дівчата роблять, що хочуть. Я думаю, що Арістан забув, що означає бути молодим і закоханим.$B$BBut було б краще не говорити йому про це. Ми розсмішимо його.",
},

[9025] = {
    en = "Morgan's Discovery",
    T = "Відкриття Моргана",
    D = "Хай йому грець, схоже, Арістан таки натрапив на щось. Я виявив сліди речовин, що використовуються в любовних зіллях та підступних настоях, що змінюють розум.$B$BНе рідкість, коли парфуми містять дещо з цього, але деякі інгредієнти, які я виявив... Щось тут нечисто.",
    O = "Повернися до Арістана Моттара біля банку в Торгівельному Районі Штормовію.",
    P = "",
    C = "Хоча я думав, що так і буде, те, що мої підозри виправдалися, мене все одно тривожить. Ми повинні ретельно обміркувати наш наступний крок.$B$BHere, щоб відплатити вам за покупку одеколону та парфумів.",
},

[9026] = {
    en = "Tracing the Source",
    T = "Відстеження Джерела",
    D = "Ми мусимо знайти джерело. Я помітив, що набагато більше людей, ніж зазвичай — включно з вартовими — заходять і виходять із Золотої Троянди. Поговори з Аллісон. Якщо вона їх продає, вона може сказати, звідки вони взялися.",
    O = "Поговори з Шинкаркою Аллісон у Золотій Троянді в Торгівельному Районі Штормовію.",
    P = "",
    C = "О так, нещодавно я отримав парфуми та одеколон на складі. Він так добре продається, що я не знаю, як довго я зможу тримати його на полицях.$B$BIf Ви запитаєте мене, це трохи нудно. Усі пахнуть однаково? Пахне чудово, але все ж.",
},

[9027] = {
    en = "Tracing the Source",
    T = "Відстеження Джерела",
    D = "Щось не так з одеколоном? Можливо. Я ще ніколи не бачила, щоб стільки людей так сильно хотіли один продукт.$B$BСлухай, якщо з ним щось не так, я теж хочу знати. Я придбала свої запаси у торговця на ім’я Еверт Сорісам. Він нещодавно приїхав до міста.$B$BВін згадував, що має доставити деякі товари до Найтоншої Нитки.",
    O = "Поговори з Евертом Сорісамом у Найтоншій Нитці вздовж Каналів Штормовію.",
    P = "",
    C = "Так, звичайно. Ці аромати є найпопулярнішими продуктами цього сезону. Ви, мабуть, п’ята чи шоста людина за цю годину, яка запитує про них.$B$BI Боюся, що всі мої запаси розпродані. Якщо ви хочете трохи, вам слід поговорити з Еллісон, власником корчми «Позолочена троянда».$B$BYou, однак не варто витрачати час. Я думаю, ви побачите, що духи будуть чарівними.",
},

[9028] = {
    en = "The Source Revealed",
    T = "Джерело Виявлено",
    D = "Що? Зрада? Ні, ні. Запевняю тебе, мої наміри абсолютно невинні.$B$BХіба це злочин — допомагати тим, хто хоче полегшити болісний ритуал залицяння? Ну ж бо, це не злочин.$B$BІ щоб довести, що я не маю злого умислу, я навіть скажу тобі своє джерело.$B$BМені їх надіслав Стаффрон Лерент, якийсь аптекар. Я ніколи з ним не розмовляв.$B$BНаш гоблін-посередник сказав, що він працює в передгір’ях над Гіллсбрадом за таємничим маєтком Рейвенхолдт. Бажаю тобі удачі в його пошуках.",
    O = "Знайди Аптекаря Стаффрона Лерента в Передгір’ї Гіллсбраду за маєтком Рейвенхолдт.",
    P = "",
    C = "Так, я зробив ці аромати. Чудовий запах, чи не так? Непереборно.$B$BOnce воїни Альянсу та Орди однаково охоплені цими почуттями любові, вони будуть безсилі зупинити підйом Ради Тіней.$B$BThey будуть ослаблені, непідготовлені. Переживаючи за своїх близьких, вони втратять перевагу.$B$BThe рішення було таким простим. Чому мені знадобилося так багато часу, щоб натрапити на це? Слабкість усіх через серце. І ви нічого не можете зробити, щоб зупинити неминуче.",
},

[9029] = {
    en = "A Bubbling Cauldron",
    T = "Киплячий Казан",
    D = "",
    O = "",
    P = "",
    C = "Від казана приємний запах.",
},

[9030] = {
    en = "",
    T = "Прощальні Слова Антіона",
    D = "Душа Валталака була захована в цьому амулеті. У своїй жадібності ми нерозумно розділили його на три частини, не знаючи, яке прокляття на нас чекає.$B$BЄдиний спосіб зупинити закляття Валталака — це знову зібрати медальйон. Повертайся до Деліани та скажи їй, що Бодлі — її єдина надія знайти решту частин.$B$BЯ, нарешті, спочину з миром. Бажаю тобі найкращої удачі, і вона тобі знадобиться!",
    O = "Поговори з Деліаною в Залізогарті.",
    P = "",
    C = "",
},

[9032] = {
    en = "Bodley's Unfortunate Fate",
    T = "Нещаслива Доля Бодлі",
    D = "Медальйон містив душу Валталака? Не дивно, що він був захищений таким потужним прокляттям.$B$BЗнайти Бодлі — це певна проблема. Востаннє я чув про нього, він готувався повернутися до Чорнокам’яного Шпиля. Після того про нього більше не було звісток.$B$BШукай його в Чорнокам’яній Горі, хоча, боюся, він уже мертвий. Пропоную взяти з собою пристрій гобліна, друже.",
    O = "Вируш до Чорнокам’яної Гори та використай Надпросторовий Виявник Привидів, щоб знайти Бодлі біля Чорнокам’яного Шпиля.",
    P = "",
    C = "Я дуже радий, що ви мене бачите. Нарешті є з ким поговорити!$B$BWill ти допомагаєш нам, $N? Допомогти виправити помилку, яку ми вчинили, і виправити ситуацію? Якщо це правда, що у вас уже є верхня частина амулета лорда Валталака, то я думаю, що я можу направити вас у правильному напрямку, щоб придбати дві інші частини, об’єднати їх і покласти всьому цьому край.$B$BOh, до речі, привіт, мене звуть Бодлі. Приємно познайомитися!",
},

[9033] = {
    en = "Echoes of War",
    T = "Відлуння Війни",
    D = "П’ять років від останньої війни...$B$BДесятки тисяч життів було втрачено, і заради чого? Загроза так і не була повністю знищена.$B$BІ ось Король-Ліч знову ворушиться... Його права рука, Кел’Тузад, збирає сили для нового нападу на наші землі.$B$BМи не дозволимо цього! Доведи свою відданість. Доведи, що ти готовий ризикнути життям, щоб зупинити це божевілля, і поєднана міць Світанку та Хрестового Походу буде на твоїй службі.$B$BУвійди до Наксрамаса та знищ Плеть усередині...",
    O = "Командир Елігор Світанконосець у Каплиці Світла Надії в Східних Зачумлених Землях хоче, щоб ти знищив 5 Живих Чудовиськ, 5 Кам’яношкірих Гаргуйль, 8 Капітанів Лицарів Смерті та 3 Отруйних Слідопитів.",
    P = "Обов'язок, честь, відданість... Що означають для вас ці слова?",
    C = "Добре виконана робота! Ви отримаєте винагороду через послуги чоловіків і жінок у Light's Hope.",
},

