[9120] = {
    en = "The Fall of Kel'Thuzad",
    T = "Падіння Кел’Тузеда",
    D = "Філактерія — це все, що залишилося від господаря Наксрамаса. Твій здоровий глузд підказує, що потрібно знищити філактерію, щоб лік не міг відродитися. На щастя, ти рідко слухаєш цей внутрішній голос розуму.$B$BХтось у Каплиці Світла Надії щедро заплатить за цей артефакт. Кого хвилює, якщо Кел’Тузед відновить свою повну силу?",
    O = "Віднеси Філактерію Кел’Тузеда до Каплиці Світла Надії в Східних Зачумлених Землях.",
    P = "",
    C = "",
},

[9121] = {
    en = "The Dread Citadel - Naxxramas",
    T = "Страшна Цитадель — Наксрамас",
    D = "У гущавині Зачумленого Лісу розташований вхід до страшної цитаделі Наксрамаса. Раніше всі спроби проникнути туди зазнавали невдачі через магічні бар’єри на рунному порталі. Але тепер це змінилося.$B$BМи розробили спосіб проникнення за допомогою арканного маскування — старого заклинання Кірін Тору з кількома моїми власними модифікаціями. Оскільки твоя відданість справі Світанкової Зорі дещо слабка, $N, ціна буде високою. Ти можеш відмовитися і повернутися, коли станеш поважним або прославленим, щоб отримати знижку.",
    O = "Архімаг Анджела Досантос у Каплиці Світла Надії в Східних Зачумлених Землях вимагає 5 Арканових Кристалів, 2 Кристали Нексусу, 1 Сферу Праведності та 60 золотих. Ти також маєш бути Шанованим у Світанковій Зорі.",
    P = "Ніхто не увійшов у Наксрамас і не жив, щоб розповісти цю історію.",
    C = "Ви відчуєте легке поколювання, $N. Це відчуття означає, що воно працює. Після завершення ви зможете потрапити в Наксрамас, ступивши на портал рун у Чумному лісі.",
},

[9122] = {
    en = "The Dread Citadel - Naxxramas",
    T = "Страшна Цитадель — Наксрамас",
    D = "У гущавині Зачумленого Лісу розташований вхід до страшної цитаделі Наксрамаса. Раніше всі спроби проникнути туди зазнавали невдачі через магічні бар’єри на рунному порталі. Але тепер це змінилося.$B$BМи розробили спосіб проникнення за допомогою постійного арканного маскування — старого заклинання Кірін Тору з кількома моїми власними модифікаціями. З урахуванням цього, маскування коштує дорого. Оскільки твоя відданість справі Світанкової Зорі гідна похвали, ми готові частково покрити ці витрати.",
    O = "Архімаг Анджела Досантос у Каплиці Світла Надії в Східних Зачумлених Землях вимагає 2 Арканові Кристали, 1 Кристал Нексусу та 30 золотих. Ти також маєш бути Поважним у Світанковій Зорі.",
    P = "Ніхто не увійшов у Наксрамас і не жив, щоб розповісти цю історію.",
    C = "Ви відчуєте легке поколювання, $N. Це відчуття означає, що воно працює. Після завершення ви зможете потрапити в Наксрамас, ступивши на портал рун у Чумному лісі.",
},

[9123] = {
    en = "The Dread Citadel - Naxxramas",
    T = "Страшна Цитадель — Наксрамас",
    D = "У гущавині Зачумленого Лісу розташований вхід до страшної цитаделі Наксрамаса. Раніше всі спроби проникнути туди зазнавали невдачі через магічні бар’єри на рунному порталі. Але тепер це змінилося.$B$BМи розробили спосіб проникнення за допомогою постійного арканного маскування — старого заклинання Кірін Тору з кількома моїми власними модифікаціями. З урахуванням цього, маскування коштує дорого; однак твоя відданість справі Світанкової Зорі непохитна! Ми скасуємо всі витрати.",
