    C = "Я дуже вдячний, $N.$B$B<Рейн кланяється.>$B$BPlease пам’ятайте, що я завжди приймаю листя.",
},

[9137] = {
    en = "Savage Fronds",
    T = "Дикі Паростки",
    D = "",
