    P = "",
    C = "",
},

[9165] = {
    en = "Writ of Safe Passage",
    T = "Пропуск Безпеки",
    D = "Без допомоги шукачів пригод мій караван ніколи б не дістався сюди! Плета виповзала звідусіль, намагаючись зупинити нас.$B$B<Вартовий Дід’є витирає піт із чола.>$B$BТепер нам потрібно чекати тут на прибуття фельдмаршала Чемберса. Він підпише твій пропуск безпеки, який ти маєш віднести назад до Командира Розсилань Меца в Каплиці Світла Надії.$B$BІ, $N, стеж за тим, що говориш при Чемберсі. Він із тих, хто може відкусити тобі голову і плюнути тобі в горло — тільки він справді це зробить...",
    O = "Достав Підписаний Пропуск Безпеки до Командира Розсилань Меца в Каплиці Світла Надії в Східних Зачумлених Землях.",
    P = "Ім'я, звання та порядковий номер!",
    C = "<Диспетчерський комендант Мец бере наказ і підписує його.>$B$BExcellent робота, $N. Навіть видатний! Сприйміть це як знак нашої вдячності. Без каламбуру, скраб.",
},

