},

[9248] = {
    en = "A Humble Offering",
    T = "Скромна Пропозиція",
    D = "Ішну-ала, $r. Покажи мені доказ знищення Лорда Ради Безодні, і я винагороджу тебе предметом, який допоможе тобі в битвах проти Кіражі.",
    O = "Аурель Золотолист у Ценаріонській Фортеці в Силітусі хоче, щоб ти приніс їй 1 Скiпетр Безодні. Ти також мусиш мати репутацію Шанованого у Ценаріонському Колі.",
    P = "Fandu-dath-belore? О, вибачте, $N. Я тебе не впізнав. У вас є скіпетр?$B",
    C = "Анде'торас-етил. Це означає; «Нехай поменше твоїх проблем», моєю рідною мовою.$B$BWear гурт з гордістю та здоров’ям, $N.",
},

