[9266] = {
    en = "Making Amends",
    T = "Виправлення Помилок",
    D = "",
    O = "",
    P = "Мабуть, ти зробив щось дуже погане нам або нашим друзям, $N. У будь-якому разі я тут, щоб запропонувати вам спосіб повернути нашу ласку.$B$BAs ви знаєте, Winterspring досить холодно. З такою кількістю гоблінів, які приїжджають з інших міст, ми могли б зігріти руку. Принеси мені трохи рунічної тканини та вугілля, і я скажу за тебе добре слово. Але майте на увазі, що наші вороги не сприймуть доброзичливого ставлення до вашої допомоги.",
    C = "Дякую, $N. Ви на швидкому шляху до того, щоб відкупити себе з нашим справедливим містом.",
},

[9267] = {
    en = "Mending Old Wounds",
    T = "Зцілення Старих Ран",
    D = "",
    O = "",
    P = "Вам краще двічі подумати, перш ніж ступити в Ratchet, $n! Ходять чутки про ваші брудні вчинки.$B$BYou Але вам пощастило, щойно прибув корабель із багатьма пораненими внаслідок зіткнення з піратами Bloodsail. Це ваш шанс довести, що ви не повний негідник. Допоможіть нам, принісши лляну тканину для бинтів і порожні флакони для зілля.",
    C = "Я радий, що ти бачиш свою помилку, $N. Продовжуйте надходити запаси; ми не забудемо про вас так легко, $Gmister:міс;!",
},

[9268] = {
    en = "War at Sea",
    T = "Війна на Морі",
    D = "",
    O = "",
    P = "Ти знову прагнеш подружитися з гоблінами Танаріса, $N? Нам потрібні матеріали для вітрил і гармат, щоб боротися з нашими давніми ворогами, піратами Кривавого вітрила. Принесіть мені магічну тканину та сильний флюс, і ми підемо на шлях прощення ваших провин.",
    C = "Тримай так, $N. Ми, гобліни, не забуваємо цього легко!",
},

[9269] = {
    en = "Atiesh, Greatstaff of the Guardian",
    T = "Атійш, Великий Посох Охоронця",
    D = "Ця остання задача буде найскладнішою з усіх, $N. Ти переміг і Старого Бога, і генерала Короля-Ліча, але тепер тобі доведеться зіткнутися з рукою Саргераса.$B$BВіднеси посох до Стратгольма. Там ти знайдеш освячену землю: місце, де були вбиті найвеличніші лицарі Лордерона. Поклади осквернений посох на святу землю і готуйся до появи сутності величезної сили, що вирветься зсередини... Переможи демонічну істоту, яка контролює посох, і повернися до мене.",
    O = "Анахронос у Печерах Часу в Танарісі хоче, щоб ти відніс Атійша, Великий Посох Охоронця, до Стратгольма і використав його на Освяченій Землі. Переможи сутність, яку виженуть із посоха, і повернися до нього.",
    P = "",
    C = "Атіш Очищений",
},

