[9322] = {
    en = "Wild Fires in Kalimdor",
    T = "Дикі Вогні в Калімдорі",
    D = "Фестиваль Полум’я Середини Літа святкують по всьому Азероту, і різноманітні землі Калімдору не є винятком. Ти виглядаєш готовим до подорожі — можливо, час вирушити в дорогу.$b$bСередину Літа не можна по-справжньому оцінити, якщо ти не бачив палаючих блакитних вогнів за кордоном. Святкуючі розпалили вогнища в холодному західному Зимоключі, на північному сході Азшари, біля Спочинку Доблесті в пустелях Сілітісу та біля входу в пишний кратер Ун’Горо. Повертайся, коли завершиш подорож.",
    O = "Відвідай табори Фестивалю Середини Літа в Азшарі, Сілітісі, кратері Ун’Горо та Зимоключі, а потім повернися до Хранителя Полум’я Фестивалю.",
    P = "Полум'я Калімдору яскраво горить?",
    C = "Твій дух сяє теплом калімдорських вогнів, друже. Спека не бадьорить? Коли сила зникає, можливо, це допоможе відродити почуття.",
},

[9323] = {
    en = "Wild Fires in the Eastern Kingdoms",
    T = "Дикі Вогні в Східних Королівствах",
    D = "Наше святкування полум’я поширене по всій землі, $c. Жодне місце не залишається недоторканим теплом цього свята, і найсильніші вогні палають яскраво-блакитним. Знайди їх.$b$bОдин із них ти знайдеш на північ від Чорноскельного Шпиля. Інші розташовані глибоко в Східних Зачумлених Землях біля занедбаного міста, уздовж дороги до скель у гірських Внутрішніх Землях і на шляху до Темного Порталу у Вибухових Землях.$b$bПовертайся, коли завершиш подорож.",
    O = "Відвідай табори Фестивалю Вогню у Вибухових Землях, Східних Зачумлених Землях, Внутрішніх Землях і Палаючій Ущелині, а потім поговори з Хранителем Полум’я Фестивалю.",
    P = "Потрібен час, щоб перемогти цю загрозу. Як справи, $N?",
    C = "Ах, ось ти. Трохи втомленіший, трохи запорошений, але просвітлений! Ця пора року тепло торкається всіх нас і об’єднує; саме твоє єство сяє силою вогню, якого ти торкнувся. Ах, але в наші дні просвітництво сприймається як досить погана винагорода за те, що тебе відправляють виконувати завдання, я вважаю. Тоді візьміть їх і насолоджуйтеся святкуванням.",
},

[9324] = {
