[9362] = {
    en = "Warlord Krellian",
    T = "Воєвода Крелліан",
    D = "Часу обмаль, $n! Мої заклинання ясновидіння виявили потужне джерело магії. Я не можу залишити вежу і прошу тебе знищити мерзенну істоту, що володіє цим артефактом.$b$bЦей жалюгідний нікчема відомий як Воєвода Крелліан, що ховається за своїми охоронцями в Храмі Зін-Малора. Спали його на попіл і забери призматичну шкаралупу, яку він так жадає.",
    O = "Добудь Призматичну Шкаралупу для Архімага Ксілема. Архімаг мешкає у вежі на скелях Азшари.",
    P = "Немає часу марнувати! У вас є оболонка?",
    C = "Треба сказати, у цієї раковини дивна аура. Здається, цілком доречно, що частиною вашої винагороди за його отримання буде випробування його магічних можливостей...",
},

[9364] = {
    en = "Fragmented Magic",
    T = "Фрагментована Магія",
    D = "Мої дослідження виявили унікальне призначення призматичної шкаралупи.$b$bНоси шкаралупу і використай своє заклинання поліморфу на Плюскохвостах в Азшарі. Якщо зачекати кілька секунд, хаотична аура шкаралупи змусить їх розщепитися на кілька менших клонів на короткий час. Убий ці клони якомога швидше, і шкаралупа збере їхню есенцію.$b$bКоли шкаралупа наповниться, поверни її мені.",
    O = "Застосуй поліморф на Плюскохвостах Азшари і вбий клони, що з'являться через кілька секунд. Коли ти знищиш 50 Клонів Поліморфу, повернися до Архімага Ксілема в Азшарі.",
    P = "Ви зібрали магію?",
    C = "Чудово! Чудово!$B$BNow ми можемо перетворити цю магію на нове заклинання. Ось!",
},

[9365] = {
    en = "A Thief's Reward",
    T = "Нагорода Злодія",
    D = "",
    O = "",
    P = "",
    C = "Сьогодні ти довів себе, $n.$b$bWhile Я ще мало можу тобі дати, у мене є ця корона; гідний подарунок для завойовника. Нехай він освітлює твій шлях.",
},

[9367] = {
    en = "The Festival of Fire",
    T = "Фестиваль Вогню",
    D = "Середина Літа знову настала!$b$bЩороку, за традицією, обирають Хранителів Полум’я, щоб доглядати за багаттями в наших столицях. Поки вогні палають по всьому Азероту, надзвичайно важливо, щоб наші були найгарячішими і найяскравішими, щоб належно вшанувати цей сезон.$b$bДо речі, у мене є для тебе завдання, якщо не заперечуєш. Я ще не чув, чи всі вогні в столицях палають належно. Відправляйся туди сам і зігрійся біля вогнищ — переконайся, що вони гарячі!",
    O = "Торкнися багаттів у Штормовії, Залізогарті та Дарнассі, а потім поговори з Лоремістром Фестивалю в одній зі столиць.",
    P = "Чи горять вогні?",
    C = "Чудово! Здається, цього року ми призначили сумлінних охоронців вогню, якщо багаття дотримані так добре, як ви стверджуєте. Дякую, що оглянули їх для мене; ось, прийміть це як маленький знак моєї поваги.",
},

[9368] = {
    en = "The Festival of Fire",
    T = "Фестиваль Вогню",
    D = "Середина Літа знову настала!$b$bЩороку, за традицією, обирають Хранителів Полум’я, щоб доглядати за багаттями в наших столицях. Поки вогні палають по всьому Азероту, надзвичайно важливо, щоб наші були найгарячішими і найяскравішими, щоб належно вшанувати цей сезон.$b$bДо речі, у мене є для тебе завдання, якщо не заперечуєш. Я ще не чув, чи всі вогні в столицях палають належно. Відправляйся туди сам і зігрійся біля вогнищ — переконайся, що вони гарячі!",
    O = "Торкнися багаттів в Оргріммарі, Громовому Бескиді та Підмісті, а потім поговори з Казкарем Фестивалю в одній зі столиць.",
    P = "Тобі пощастило, $N?",
    C = "Чудова робота, $N. Оскільки тіні знищено, це може бути лише питанням часу, коли Король-Ліч вирішить відкликати свої некрополі та залишити нас у спокої.",
},

[9378] = {
    en = "DND FLAG The Dread Citadel - Naxxramas",
    T = "DND FLAG Страшна Цитадель — Наксрамас",
    D = "У гущавині Зачумленого Лісу розташований вхід до страшної цитаделі Наксрамаса. Раніше всі спроби проникнути туди зазнавали невдачі через магічні бар’єри на рунному порталі. Але тепер це змінилося.$B$BМи розробили спосіб проникнення за допомогою постійного арканного маскування — старого заклинання Кірін Тору з кількома моїми власними модифікаціями. З урахуванням цього, маскування коштує дорого; однак твоя відданість справі Світанкової Зорі непохитна! Ми скасуємо всі витрати.",
    O = "Архімаг Анджела Досантос у Каплиці Світла Надії в Східних Зачумлених Землях надасть тобі Арканне Маскування безкоштовно. Ти маєш бути Прославленим у Світанковій Зорі.",
    P = "",
    C = "",
},

[9386] = {
    en = "A Light in Dark Places",
    T = "Світло в Темряві",
    D = "Нетерплячий, еге ж? Якщо ти готовий ще раз спуститися в глибини, я з радістю винагороджу тебе.$b$bЗнайди багаття, що палають у Стратгольмі, Схоластві, Грізному Молотові та в залах самого Чорноскельного Шпиля; я з нетерпінням чекаю твого повернення, $n.",
    O = "Знайди і торкнися багаттів у Чорноскельному Шпилі, Грізному Молотові, Схоластві та Стратгольмі, а потім поговори з Хранителем Полум’я Фестивалю.",
    P = "Ви знайшли шлях крізь темряву?",
    C = "Ти довів, що ти не зовсім марний, смертний.",
},

[9388] = {
    en = "Flickering Flames in Kalimdor",
    T = "Мерехтливі Вогні в Калімдорі",
    D = "Сьогодні по всьому світу палає багато вогнів, $n. Найскладніше доглядати за зеленими вогнями; вони не горять довго без нагляду. Переконайся, що смарагдові вогні все ще палають на Калімдорі для нашого Хранителя Полум’я, га?$b$bТи знайдеш їх біля Ратчета в Степах, неподалік від Майстрівського Глефта в Темнобережжі, у лісах Ясенедолу біля мосту поруч із Срібнокрилим Постом і біля дороги до Скелі Вітрошмату вздовж головної дороги в Кам’яних Кігтях.",
    O = "Відвідай багаття в Ясенедолі, Степах, Темнобережжі та горах Кам’яних Кігтів, а потім поговори з Хранителем Полум’я Фестивалю.",
    P = "Вогні не можуть згаснути, доки не закінчиться фестиваль!",
    C = "Аааа, значить, вони все ще горять. я радий; не варто, щоб ті пожежі згоріли раніше свого часу. Ви добре зробили, $N. Прийми це з моїм благословенням.",
},

[9389] = {
    en = "Flickering Flames in the Eastern Kingdoms",
    T = "Мерехтливі Вогні в Східних Королівствах",
    D = "Фестиваль Полум’я Середини Літа традиційно освітлює землю безліччю вогнів. Дехто стверджує, що зелені вогні — найкращі, адже їх найважче підтримувати і вони мають такий виразний відтінок.$b$bПереконайся, що вони все ще палають у Східних Королівствах для нашого Хранителя Полум’я. Вони розташовані біля Дун Модра в Болотинах, неподалік від села Похмуроди в Срібнохвойому Лісі, на скелях над маяком у Західному Краю та біля зруйнованої вежі в Передгір’ях Гіллсбрада.",
    O = "Відвідай багаття в Передгір’ях Гіллсбрада, Срібнохвойому Лісі, Західному Краї та Болотинах, а потім поговори з Хранителем Полум’я Фестивалю.",
    P = "Ви виконали своє завдання?",
    C = "Отже, ви повернулися й побачили смарагдове полум’я континенту. Що ти думаєш, мм? Безсумнівно, рідкісне і чудове видовище. Однак я знаю, що матеріальні винагороди краще цінуються... тож, будь ласка, візьміть це на себе.",
},

