[9415] = {
    en = "Report to Marshal Bluewall",
    T = "Доповісти Маршалу Синьостінному",
    D = "Ви новобранці Маршала Синьостінного? Звісно, що так.$b$bЧого ви чекаєте? Добрі солдати гинуть у пустелі. Хіба ви не раді приєднатися до них?$b$bА тепер гайда, і не пересохни по дорозі.",
    O = "Поговори з Маршалом Синьостінним у таборі Альянсу біля Вулик’Зора.",
    P = "",
    C = "Альянсу потрібні всі здатні сили, які вони можуть отримати. Орда постійно отримувала підкріплення з північної частини континенту, і їй було важко не відставати.$B$BLet я поясню вам ситуацію.",
},

[9416] = {
    en = "Report to General Kirika",
    T = "Доповісти Генералу Кіріці",
    D = "Ви, мабуть, один із новобранців Генерала Кіріки. Нарешті ви з’явилися. У пустелі тіла швидко зношуються.$b$bГноми отримують підкріплення щодня, і ми не можемо дозволити собі втрачати позиції в нашій боротьбі за ресурси в Сілітісі.$b$bОтримай інструкції від Генерала. Не моя справа тебе тренувати, лише знайти.",
    O = "Поговори з Генералом Кірікою в таборі Орди біля Вулик’Регала.",
    P = "",
    C = "Добре, що ти тут, але не можна витрачати час на світські розмови. Вам потрібні інструкції, а потім вам потрібно вийти.$B$BListen вгору.",
},

[9419] = {
    en = "Scouring the Desert",
    T = "Очищення Пустелі",
    D = "Нещодавно ми дізналися, що Орда розграбовує пустелю Сілітісу в пошуках ресурсів, але ми не звертали на це уваги. Ми думали, що не варто розміщувати великі сили в цій пекельній пустелі.$b$bОднак ми виявили важливість цих ресурсів, і тепер намагаємося надолужити згаяне.$b$bЯкщо я можу розраховувати на твою допомогу, ти мусиш вирушити в пустелю, зібрати сілітіст і принести його сюди.",
    O = "Знайди і достав Сілітіст до Витягувача Сілітіста, а потім поговори з Маршалом Синьостінним у таборі Альянсу біля Вулик’Зора.",
    P = "Будьте обережні там, але також будьте швидкими. Ми не маємо часу втрачати.",
    C = "Дякуйте Світлу, що ви досягли успіху.$B$BNow Якби ми могли почати це раніше, наші потреби не були б такими відчайдушними. Ми повинні вберегти щедрість пустелі від потрапляння в руки Орди.",
},

[9422] = {
    en = "Scouring the Desert",
    T = "Очищення Пустелі",
    D = "Вже деякий час ми видобуваємо кристалічні ресурси пустелі Сілітісу. Єдиними загрозами були істоти, що вважали це місце своїм домом, а також гнітючий пісок, пил і спека.$b$bАле тепер Альянс, здається, зрозумів, що ми тут знайшли. Тепер це гонка між нами за контроль над природними ресурсами, щоб не дати їх іншій стороні.$b$bМені потрібна кожна пара рук, яка є в наявності. Сподіваюся, твої серед них.",
    O = "Знайди і достав Сілітіст до Витягувача Сілітіста, а потім поговори з Генералом Кірікою в таборі Орди біля Вулик’Регала.",
    P = "Будьте обережні щодо небезпек пустелі, $n. Оскільки Альянс ховається в дюнах, будь-який крок може стати вашим останнім.",
    C = "Ти добре впорався, $N. Ці ресурси будуть додані до наших запасів, і кожен шматочок буде для нас на користь і втрат для нашого ворога.",
},

