[40019] = {
    en = "The Wildtusk Charms",
    T = "[*] Обереги дикого бивня",
    D = "Коли ми втекли з нашого колись прихованого міста, ми залишили все, що нам не було потрібно, навіть чари, які ми використовуємо в багатьох наших магічних ритуалах і в прояві поваги до духів.$B$BI боїмося, що ми засмутили духів, покинувши наші чари в Зул'Расазі, і коли наступного разу нападе Кора Вуду, наше вуду покине нас!$B$BThere немає надії протистояти Корі без допомоги духів, $c. Йдіть швидко до руїн Зул'Расаза та поверніть наші втрачені чари, поки не пізно.",
    O = "Зберіть 5 оберегів дикого бивня з руїн Зул'Расаза.",
    P = "",
    C = "",
},

[40020] = {
    en = "The Ancestral Amulet",
    T = "[*] Родовий амулет",
    D = "Коли ми тікали від хаосу Зул-Расаза, багатьом моїм людям довелося залишити дорогі речі та інші речі, які мали особисту цінність. Я нічим не відрізняюся. Мені соромно сказати, що я відмовився від амулета, який передавався в моїй родині поколіннями, починаючи з часів останньої великої імперії.$B$BIt мучить мій розум, $c. Духи більше ніколи не відповідатимуть на мій заклик, якщо я не загладжу цю велику ганьбу. Ви повинні повернути його для мене! До руїн Зул'Расаза можна дістатися стежкою за містом на північний захід. Мій дім знаходиться на вершині зруйнованого міста.$B$BI здійснив би подорож, але я не можу ризикувати своїм життям із такої егоїстичної причини. Ви будете винагороджені за свою допомогу, я вас запевняю.",
    O = "Знайдіть намисто Yin'dos в руїнах Zul'Rasaz.",
    P = "",
    C = "",
},

[40021] = {
    en = "The Speaker's Betrayal",
    T = "[*] Зрада спікера",
    D = "Після розпаду імперії мій народ втік у гори, де ми процвітали поколіннями, зберігаючи позитивні стосунки з місцевими елементалями та сприяючи їхньому зростанню.$B$BWe не знав, що один із наших власних упав під впливом жаги влади Кори Сухої Кори. Зрадники пам’яті імперії, вони напали на Зул'Расаз і вбили мій народ у їхніх ліжках.$B$BSpeaker Ган'то, когось я колись називав другом, відповідальний за цю трагедію. Ти підеш до руїн Зул'Расаза і вб'єш його заради мого народу. Здійсніть справедливість щодо тих, хто не встиг битися того дня, $c.",
    O = "Принесіть голову спікера Ган'то вождю Їн'до.",
    P = "",
    C = "",
},

[40022] = {
    en = "The Witherbark Warband Leader",
    T = "[*] Лідер бойового загону Візербарк",
    D = "Тепер, коли зрадник притягнутий до відповідальності, ми можемо зосередитися на лідері цього бойового загону, Кін'тозі. Одержимий темною люттю, ватажок бойового загону тепер претендує на руїни нашого міста, готуючись спуститися з гори після повернення до села Візербарк.$B$BYou має зупинити їх грабіж і зруйнувати їх моральний дух! Принесіть мені голову Кін'този, і вона стане символом для мого народу, щоб об’єднатися. З їхнім керівництвом у руїні, ми справді матимемо шанс повернути Зул'Расаз.",
    O = "Принесіть голову вождя Кін'този вождю Їньдо.",
    P = "",
    C = "",
},

[40023] = {
    en = "Assisting Lord Rog",
    T = "[*] Допомога лорду Рогу",
    D = "Wildtusk завжди підтримував добрі стосунки з елементальними істотами. Це залежить від нас, спікерів, спілкуватися як з духами, так і зі стихіями. Лорда Рога турбують негаразди, які виходять за межі Села Дикого Блика.$B$BWe Ви не маєте ні сил, ні засобів, щоб допомогти йому, але, можливо, ви можете, мій? Стихії простягаються нечасто, тому ми не можемо упустити цю можливість. Поговоріть з лордом Рогом і подивіться, чи можете ви допомогти замість нас.",
    O = "Поговоріть з лордом Рогом.",
    P = "",
    C = "",
},

[40024] = {
    en = "Lord Rog's Exiles",
    T = "[*] Вигнанці лорда Рога",
    D = "Мій рід від’єднався від елементарного плану тут, на нагір’ї Араті. Іноземні заворушення та смерть наших лідерів розчарували нас і втратили наші сили. Я не маю контролю над елементалями, якими мене звинуватили, і я вважаю, що тут грає щось інше.$B$BTo на південному заході — це Коло внутрішнього зв’язку. Тут мої послідовники розкидані. Ідіть туди та візьміть у них внутрішні наручі, якими вони володіють. Вони не віддадуть їх вам добровільно, тому ви повинні їх знищити.",
    O = "Зберіть 5 наручів внутрішнього зв’язування від Скельних елементалів у Колі внутрішнього зв’язування на нагір’ї Араті.",
    P = "",
    C = "",
},

[40025] = {
    en = "I$b$ber Binding Purification",
    T = "[*] Очищення внутрішньої зв'язки",
    D = "З огляду на зауваження Ганца, здається, що ці наручі зіпсувалися. Хтось користується нашим ослабленим становищем і звертає мій рід на підлі засоби. Ми повинні очистити ці наручі від їхнього забруднення, і для цього мені потрібні природні матеріали.$B$BYou можна знайти їх у цьому світі, і вони повинні добре очищати забруднення. Принесіть спікеру Ганзі п'ять коренів життя, десять твердих каменів і три квітки дикої сталі. Він готуватиме для мене матеріали.",
    O = "Зберіть 5 коренів життя, 10 суцільних каменів і 3 квітки дикої сталі та віднесіть їх до спікера Ганзі.",
    P = "",
    C = "",
},

[40026] = {
    en = "Lord Rog's Favor",
    T = "[*] Ласка лорда Рога",
    D = "Це зроблено. Я підготував усі матеріали та передав їх лорду Рогу. Він почне очищати свої наручі. Ми зробили добре. Давайте почекаємо, поки він закінчить.",
    O = "Зачекайте, поки Лорд Рог очистить наручі.",
    P = "",
    C = "",
},

[40027] = {
    en = "The Sanv Charm",
    T = "[*] Оберіг Санв",
    D = "Світ, з якого ми прийшли, це пекло. Сповнений небезпеки, демонів і ворожий до життя всіма способами. Їжі було мало, а води ще менше. Я привів свій народ у безпеку цього світу завдяки нашій магії через Розлом. У давні часи мій народ створив чари, які налаштовували їх на старий світ, і в ньому містилася велика магія. Це дозволяло проходити по тріщинах, здатність подорожувати на великі відстані.$B$BMuch цієї навички зараз ми втратили. З історій, розказаних мені старшими поколіннями, це було набагато потужніше, ніж примітивні засоби, якими ми зараз користуємося.$B$BThe Заклинання Санв, потужний предмет, було втрачено під час однієї з моїх подорожей до Туманної Долини. Я намагався зв’язатися з Шукачем Розломів, який був із Гавані. Коли я намагався зв’язатися в долині, болотоноші підійшли й напали на мене. Я не зміг зібрати оберіг, тому залишив його в маленькій скрині та втік, рятуючи своє життя. Візьміть це для мене. Це має велике значення.",
    O = "Вирушайте в Туманну долину та знайдіть чарівність Sanv.",
    P = "",
    C = "",
},

[40028] = {
    en = "The Horn of Garek'sa",
    T = "[*] Ріг Гареки",
    D = "Колись давно я був головним мисливцем племені. Я успішно переслідував шляхи Закордоння і переміг багатьох страшних ворогів. І орк, і звір були вбиті моїми швидкими стрілами та смертоносною майстерністю.$B$BBut, я більше не Хар На'лан, великий мисливець, я Хар На'лан, старий. Я відчуваю, як вік уповільнює мене, і навіть місцева дика природа була випробуванням.$B$BOver шістсот років тому я вбив свого найстрашнішого ворога, могутнього Спустошителя на ім’я Гарека. Спустошителі здебільшого вимерли з появою демонів і через вік. Але Гарека продовжував жити як могутній і грізний ворог, розміром з найбільшу з наших хатин. Двома швидкими стрілами в його шию та порізом у живіт я вбив це створіння та взяв його ріг як трофей.$B$BIt Прикро сказати, коли ми залишили Заповідник Фоллоу на схід, я не встиг зібрати своє майно, і мій ріг залишився позаду. Візьміть його мені, будь ласка, і я вам дуже винагороджу.",
    O = "Знайдіть Ріг Гареки для Хар Налана в Заповіднику Фоллоу.",
    P = "",
    C = "",
},

[40029] = {
    en = "Hunting the Hunters",
    T = "[*] Полювання на мисливців",
    D = "Загублені заповідники Фоллоу є загрозою для Гавані. Кожен день ми повинні жити в страху, що вони нападуть у стані божевілля. У нас немає дренеїв, які могли б відбити їх, якщо вони колись зберуться в достатньо велику силу.$B$BThe Мешканці бруду вже кілька днів розвідують Гавань, і я відчуваю, що вони, можливо, до чогось готуються. Я прошу вас допомогти нам убити божевільних і дати нам шанс вижити. Ви знайдете їх на сході, але будьте обережні. Вони надзвичайно ворожі.",
    O = "Убийте 8 заблуканих жителів і 3 заблуканих мисливців.",
    P = "",
    C = "",
},

[40030] = {
    en = "Noboru the Cudgel",
    T = "[*] Нобору Дубина",
    D = "Є один, якого ми боїмося. Його звуть Нобору Дубина, і він блукає з бандою головорізів, які тероризують нас при кожній нагоді. Він вправний воїн із нашого старого племені на Запределі. Мало хто в селі може протистояти йому та його головоломкам. Нобору вчинив велику жорстокість у Гавані та вбив членів нашого племені без жодних ознак каяття.$B$BNoboru треба зупинити. Ви повинні вбити його, щоб кровопролиття припинилося. Він володіє дубиною, і саме завдяки цій жорстокій зброї він отримав своє прізвисько. Переможи його і принеси нам його зброю, щоб ми могли вижити в цьому чужому світі.",
    O = "Знайдіть і вбийте Палицю Нобору та принесіть Палицю Нобору до Магтура.",
    P = "",
    C = "",
},

[40031] = {
    en = "Leather, a Draenic Luxury",
    T = "[*] Шкіра, дренська розкіш",
    D = "Знову добре працювати зі шкірою. На нашій старій планеті Outland ми мали обмежений доступ до цього ресурсу. Там це вважалося рідкістю, розкішшю при відсутності звірів і відсутності води. Наша планета колись була такою ж щільною та населеною, як цей світ, поки не прийшли демони, і води не висохли. Ми ніби живемо в раю на Азероті. Спочатку я сумнівався щодо Санв К'ла та його плану, але здається, що ця земля набагато перспективніша, ніж я собі уявляв.$B$BI просив би тебе, сторонній, зібрати для мене шкіру з Молодих пилкоподібних кроколісків. Він товстий, але все ще розтягується за своєю якістю, і добре використаний для наших цілей. З огляду на те, що ховаються втрачені з Fallow Sanctuary, дістати їх було небезпечніше.",
    O = "Зберіть 10 зубчастої шкіри для Masat T'andr.",
    P = "",
    C = "",
},

[40032] = {
    en = "Draenic Communication",
    T = "[*] Дренське спілкування",
    D = "Ах З'адор — шукач розломів, який привів нас у цей світ. Він був одним із небагатьох у нашому роді, хто знав магію наших давніх предків. Він був достатньо вправним, щоб привести сюди все наше плем’я та плем’я Заповідника Фоллоу за допомогою інших менших Шукачів Розломів.$B$BA кілька тижнів тому він спробував повернутися до старого світу в пошуках нових вигнанців, щоб привести їх до Гавані. Я підозрюю, що щось пішло не так, бо я не міг помітити його присутність у нашому старому світі за допомогою заклинань Санв. Розумієте, магія, яку він використовує, стара й дещо нестійка. Ми ледве розуміємо його використання, і лише такі світлі уми, як Ах З'адор, можуть маніпулювати ним настільки, щоб подорожувати.$B$BI потрібно, щоб ви зібрали матеріали, щоб прокласти заклинання, щоб знайти його місцезнаходження та побачити, можливо, куди він подівся. Місцеві матеріали повинні добре працювати. Зберіть шість заплутаних сутностей із заплутаних жахів на сході та око болотного мурлока з мурлоків на узбережжі.",
    O = "Зберіть 6 заплутаних сутностей і око болотного мурлока для Санв К'ла.",
    P = "",
    C = "",
},

[40033] = {
    en = "Finding Akh Z'ador",
    T = "[*] Пошук Ах З'адора",
    D = "Мої сили вичерпані. Я почуваюся старим і слабким, але я побачив місто. Місто, яке затонуло під хвилями, ніби самі припливи прийшли і все це потопили. Там були високі скелі, величезні за розміром, і здавалося, ніби духи там потопають у нещасті. Червоне листя падало з дерев, сильна магія затримувалася й пульсувала, наче хотіла, щоб я зник. Це ослабило мене й ускладнило зосередження.$B$BI Я впевнений, що Ах З'адор зараз у цьому світі. Мабуть, він зіткнувся з чимось на Закордоні й був змушений піти. Це або його нестабільність привела його в цей чужий ландшафт.$B$BThis це все, що я можу пригадати, сторонній. Здавалося, усе, що там мешкало, було сильним — набагато сильнішим за тутешню дику природу. Набагато сильніше навіть за вас. Я прошу вас спробувати знайти Аха З'адора, де б він не був, скільки б часу вам не знадобилося.",
    O = "Знайдіть Akh Z'ador.",
    P = "",
    C = "",
},

[40034] = {
    en = "A Meeting With Royalty",
    T = "[*] Зустріч з роялті",
    D = "Які у вас справи тут, у Ретресс Санктумі? Тобі пощастило, що наша сила вже не та, що була. У нас часи випробувань. Якщо хтось бажає відвідати Володарку припливів, спершу має поговорити зі мною. Ми Rethress походимо з самих глибин цього світу в місцях, яких ваш рід ніколи не бачив і ніколи не побачить.$B$B... Як би я не довіряв вам, помешканцю, нам потрібна допомога від усіх, хто може її запропонувати. Поговоріть з Володаркою припливів Рашал. Ви маєте моє благословення, щоб побачити її.",
    O = "Поговоріть з Володаркою припливів Рашал.",
    P = "",
    C = "",
},

[40035] = {
    en = "Spoils Left Behind",
    T = "[*] Залишена псування",
    D = "Перш ніж ми пішли на великі глибини, Ретресс провів деякий час у Тернистій долині. Ми стикалися там головами з іншими нагами, але в іншому трималися тихо й усамітнено. Володарка припливів Рашал мала щось на зразок особистої місії далеко на сході, і ми перетворили острів Хагуеро на тимчасову базу.$B$BIt Незабаром ми повернулися на великі глибини, щоб розпочати нашу місію тут. Поспішаючи, ми залишили невелику скриньку, у якій зберігаються здобичі, які мають велике значення для нашого майбутнього. Ідіть туди і зберіть нашу здобич!",
    O = "Отримайте здобич Rethress для Хашаза.",
    P = "",
    C = "",
},

[40036] = {
    en = "A Broken Oath",
    T = "[*] Порушена клятва",
    D = "Мірмідони з Ретресу склали священну клятву на каменях Храму Ретреса під глибокими хвилями. Їхнє слово було їхнім узом, але вони порушили слово своїх гострих язиків і клятву, яку обіцяли дотримуватися. Нам було доручено захищати Володарку припливів Рашал і виконувати її примхи та вчинки для великих глибин усіх Наг.$B$BWhen було створено Спітелеш, і почався поділ, усі Мірмідони змінили сторону. Вони зрадили вірних Rethress за наказом з Naszharr і вбили багатьох з моїх найбільш довірених братів на The Shattered Strand.$B$BI хочуть їх убити, втручальнику. Я хочу, щоб їхніми трупами бенкетувала глибина. Візьміть з їхніх тіл печатку Мірмідон — перстень, який вони отримали під час присяги.",
    O = "Зберіть 20 печаток Мірмідону зі Спітелеша Мірмідона на Роздробленому пасмі.",
    P = "",
    C = "",
},

[40037] = {
    en = "The Storm Bay Mutiny",
    T = "[*] Повстання у Шторм-Бей",
    D = "Мене послали в Азшару з глибин світу, щоб претендувати на право власності на ці землі. Я королівська особа — королівська особа наг — і зі своєю армією я міг би бути таким же сильним, як королева Азшара!$B$BYet, ось я, керую невеликою групою своїх відданих послідовників, не маючи впливу чи влади в світі. Мене зрадили наги, які стежили за мною, і ти допоможеш мені помститися. Мурлоки Штормової Бухти були слугами моєї родини. Їхня зрада мені найбільше огидна. Істоти вважають, що вони вище волі Володарки припливів Рашал?$B$BYou можна знайти цих безхребетних послідовників по всьому узбережжю Азшари. Можливо, прояв сили допоможе повернути їх у стрій.",
    O = "Убийте 10 воїнів Штормової затоки та 10 оракулів Штормової затоки для Володарки припливів Рашал.",
    P = "",
    C = "",
},

[40038] = {
    en = "Keeping Command",
    T = "[*] Тримання команди",
    D = "Ватажок Штормової Бухти - мурлок з мозком розміром з маленьку устрицю. Ммрмглул - це його ім'я. Він має бути жорстоко покараний за те, що згуртував мурлоків Штормової затоки на відкрите повстання.$B$BYouЗнайде цього слизового вугра на півночі стежками та вздовж берегової лінії на пляжі Саутрідж. Принесіть мені його голову, щоб показати решті його лакеїв, що Володарка припливів Рашал командує мурлоками Штормової Бухти.",
    O = "Убийте Ммрмглула та принесіть його голову Володарці припливів Рашал.",
    P = "",
    C = "",
},

[40039] = {
    en = "The Rethress Tide Scepter",
    T = "[*] Скіпетр Rethress Tide",
    D = "Скіпетр Rethress Tide тримає для мене владу у великих глибинах світу, особливо в Назджатарі. Це право Rethress від народження, і воно дає нам панування над багатьма іншими. Я підозрював, що вони спробують його вкрасти, коли Spitelash було сформовано, щоб отримати це панування.$B$BYou може здивуватися, чому я вам це розповідаю. Це ніколи не стосуватиметься такої наземної істоти, як ти. Що ж, я поховав Скіпетр у секретному місці, щоб вони ніколи не могли законно претендувати на владу. Тепер, коли святилище Rethress засновано, і ми не перебуваємо в безпосередній небезпеці, я хотів би, щоб його повернули мені.$B$BThere — це місце під назвою Вежа Ельдари, яке утримує якийсь Високонароджений Хранитель. Він розташований на самому північно-східному краю півострова. На захід від нього, уздовж узбережжя, чотири скелі. Навколо цих скель похований Скіпетр припливу Rethress. Візьми його і принеси мені, помешканцю, щоб допомогти мені повернути своє право первородства.",
    O = "Знайдіть закопаний скіпетр Rethress Tide і віднесіть його Володарці припливів Рашал.",
    P = "",
    C = "",
},

[40040] = {
    en = "The Flaxwhisker Front",
    T = "[*] Фронт льоноуса",
    D = "Привіт! Ласкаво просимо до публікації Flaxwhiker. Я Фендо, відповідальний за всілякі речі тут. Я повинен направляти всіх новоприбулих у Флаксвуіскер до боса. Тобто ми не чули жодного слова від Гномерегана місяцями або не отримували нових людей! І все-таки добре, що ти поруч, $R. Ви знайдете Gigno Flaxwhisker всередині, на верхньому поверсі.",
    O = "Поговоріть з Джіньо Льонусик.",
    P = "",
    C = "",
},

[40041] = {
    en = "Flaxwhisker Loyalty",
    T = "[*] Вірність льону",
    D = "Якщо ти справжня справа, то ти повинен виконати справжнє завдання. Це має сенс, так? Деякий час я вмирав від бажання отримати в свої руки Mistwing Horn! Ці істоти досить потужні та наділені всілякою природною енергією. Деякий час у мене були підозри, що Ріг Туманного Крила може бути корисним не тільки для практичних цілей, і я хотів би його випробувати. Ось тут і ви.$B$BThe Туманне крило можна знайти на північному заході, відразу за озером Меннар. Але будьте обережні. Там є всілякі великі та могутні речі! Азшара, звичайно, небезпечне місце.",
    O = "Отримайте ріг туманного крила для Гігно Льонусика, щоб підтвердити свою відданість.",
    P = "",
    C = "",
},

[40042] = {
    en = "Delivery for Bromley",
    T = "[*] Доставка для Бромлі",
    D = "Даларанський чарівник зупинився кілька тижнів тому, вірте чи ні! Я ніколи не зустрічав чарівника з Даларану, і його магія була бездоганною. Я маю на увазі! Він запропонував нам допомогу з кількома проектами, але попросив натомість деякі матеріали. У мене ще немає засобів доставити їх до нього, враховуючи всю небезпеку між мною та табором, у якому він знаходиться на півночі звідси.$B$BDo Зроби мені послугу, чи не міг би? Запустіть мою доставку Магусу Бромлі. Ви можете знайти його на північний захід від озера Меннар. У нього є намет із краєвидом на руїни Елдарату, просто на хребтах!",
    O = "Доставте вантаж Джіньо Магу Бромлі в Азшару.",
    P = "",
    C = "",
},

[40043] = {
    en = "The Missing Robot",
    T = "[*] Зниклий робот",
    D = "Перш ніж ви повернетеся до Flaxwhisker Post, я прошу вас доставити мені листа. Йдеться про робота, який деякий час працює в області Льонопошта. Я допомагав із його створенням у виявленні магії в Азшарі, і я помітив його під час подорожі до Святилища Ретреса кілька тижнів тому. Він безнадійно загруз у якомусь занедбаному стані, зламаний і безглуздий.$B$BGigno хотів би знати принаймні, що з ним сталося. Доставте цього листа йому, $N, і ще раз подякуйте за припаси.",
    O = "Доставте лист для Джіньо Джіньо Льновусу.",
    P = "",
    C = "",
},

[40044] = {
    en = "The Analyzation Chip",
    T = "[*] Чіп аналізу",
    D = "Якщо Analyzor 53G все ще існує, то це чудова новина! Ми витратили стільки часу на його аналітичний чіп, що його було б майже неможливо відтворити. Ми мали магію Бромлі вперше, і без неї я не міг би відтворити її повністю.$B$BThe Rethress Sanctum розташований на схід від цього узбережжя. У ньому живуть наги, які не дуже дружні до нас. Я не хочу ризикувати ніким із своєї команди, щоб отримати чіп аналізу! Ви легко знайдете, що він розташований прямо під випускним отвором інгібіторної камери на головному шасі на задній стороні.",
    O = "Отримайте чіп аналізу з Analyzor 53G біля святилища Rethress.",
    P = "",
    C = "",
},

[40045] = {
    en = "Lorie's Logbook",
    T = "[*] Бортовий журнал Лорі",
    D = "Тепер, коли у нас є чіп аналізу, я можу зосередитися на інших справах! Я хотів би, щоб ви поговорили з Лорі Гівортч. Вона керувала польотами з Фронту Флаксуіскер! Нашу головну літальну машину не бачили тижнями, і я хочу знати, хто взяв цю прокляту штуку.$B$BYouЗнайде її надворі, у неї повинен бути Бортовий журнал або принаймні знати, де він!",
    O = "Поговоріть із Lorie Gearwatch про журнал польотів.",
    P = "",
    C = "",
},

[40046] = {
    en = "The Flight Logbook",
    T = "[*] Журнал польотів",
    D = "Дінкл Тогпайп — він був на посадковому майданчику на далекому сході, на маленькому острові.$B$BWe використовував цей посадковий майданчик як місце дозаправки та відпочинку для пілотів. Раніше ми розганяли їх через океан ближче до кінця споживання палива бортової машини. Раніше можна було легко потрапити з Гномерегана в Калімдор, але я відчуваю, що посадкові майданчики в занедбаному стані. Ми давно нічого не чули з дому.$B$BIf тобі потрібен Бортовий журнал польотів, іди та візьми його від Dinkle Togpipe, який там розміщений.",
    O = "Відправляйтеся на посадкову площадку на сході та отримайте журнал польотів у Дінкла Тогпайпа, а потім поверніть журнал польотів Гігно Флаксвуіскеру.",
    P = "",
    C = "",
},

[40047] = {
    en = "Report for Gnomeregan!",
    T = "[*] Звіт про Гномреган!",
    D = "Фронт Flaxwhisker був заснований Гномреганом, щоб просувати гномську інженерію за кордоном за допомогою магічної сили Азшари, щоб спробувати зробити прорив! Нам дали транспондер Tinkerspark, призначений для використання магічної енергії в наших пристосуваннях, хоча цей пристрій давно втратили наги. Ми чекали отримання ще одного місяцями.$B$BWith Втрата членів моєї команди та відсутність поставок з Гномрегану, у мене немає вибору дізнатися, що там відбувається. Чому все так затримується?$B$BFind Tinkmaster Overspark. Він повинен бути в Гномрегані, якщо якесь жахливе лихо не зруйнувало місто! Зазвичай він знаходиться в інженерному секторі на верхньому поверсі. Неспішно принесіть йому цей звіт!",
    O = "Знайдіть і принесіть звіт Джіньо Tinkmaster Overspark на Gnomeregan Reclamation Facility.",
    P = "",
    C = "",
},

[40048] = {
    en = "Report from Gnomeregan!",
    T = "[*] Звіт із Гномрегана!",
    D = "Я, чесно кажучи, шокований, коли отримав відповідь від Flaxwhisker Front. Я припускав, що вони вже знають, що сталося в Ґномерегані! Крах Gnomeregan знищив майже всю нашу матеріально-технічну базу, що рухалася в цьому напрямку, і допомогти їм неможливо.$B$BI хочу, щоб ви надіслали Gigno цього листа. Я додав туди кілька монет, щоб профінансувати повернення гномів у Азшару. Переконайтеся, що він отримує це; він містить усю інформацію, яка йому знадобиться, щоб інформувати його про те, що сталося!",
    O = "Принесіть відповідь Tinkmaster Overspark Gigno Flaxwhisker.",
    P = "",
    C = "",
},

[40051] = {
    en = "Mysterious Cow Scroll I",
    T = "[*] Таємнича корова сувій I",
    D = "Малий, обітована земля далеко, і є багато справ. Якщо ви бажаєте потрапити туди, ви повинні отримати підказки, розсіяні краєвидом, і слідувати моїм інструкціям. Робіть це з терпінням і обережністю. Ми повинні діяти так, ніби все нормально.$B$BThe Першу підказку буде розміщено на фермі, що містить елементи фестивалю Hallow's End.",
    O = "Знайдіть першу підказку.",
    P = "",
    C = "",
},

[40052] = {
    en = "Mysterious Cow Scroll II",
    T = "[*] Таємничий сувій корови II",
    D = "Ви знайшли першу підказку. У тебе ще є майбутнє, маленька Му. Друга підказка буде знайдена далеко на заході, в шахті, названій на честь найціннішої монети людини.",
    O = "Знайдіть другу підказку.",
    P = "",
    C = "",
},

[40053] = {
    en = "Mysterious Cow Scroll III",
    T = "[*] Таємничий сувій корови III",
    D = "Друга підказка у вас, але наступна буде більш небезпечною. Тримайте свій розум. Один, якого я назвав другом, давно помер і був похований на великому кладовищі, більшому за більшість. Знайдіть цю могилу, і ви знайдете свою підказку.",
    O = "Знайдіть третю підказку.",
    P = "",
    C = "",
},

[40054] = {
    en = "Mysterious Cow Scroll IV",
    T = "[*] Таємничий сувій корови IV",
    D = "З третьою знайденою підказкою ти підходиш ближче, крихітко. Попереду ще пошуки, які будуть для вас важчими. Наступна підказка знаходиться в країні, яку тролі називають своїм домом, борючись один з одним. Місце, де тварини ховаються в глухих лісах. Ви знайдете цю підказку там, біля води.",
    O = "Знайдіть четверту підказку.",
    P = "",
    C = "",
},

[40055] = {
    en = "Mysterious Cow Scroll V",
    T = "[*] Таємнича корова сувій V",
    D = "Це полювання на останню підказку. Це буде неймовірно небезпечно. Поводься з собою обережно, маленький Му. Це місце, звідки люди з зеленою шкірою прийшли в наш світ.",
    O = "Знайдіть останню підказку.",
    P = "",
    C = "",
},

[40056] = {
    en = "The Scroll of Cow Portal",
    T = "[*] Сувій коров'ячого порталу",
    D = "Ви знайшли сувій. Відмінна робота. Ви повинні принести необхідні матеріали Бессі в Коло каменів. Вас зустрінуть з розкритими обіймами.",
    O = "",
    P = "",
    C = "",
},

[40057] = {
    en = "Reclaiming the Tinkerspark Transponder",
    T = "[*] Повернення транспондера Tinkerspark",
    D = "Тепер, коли ми знаємо, що Гномреган знищено, і немає можливості отримати новий транспондер Tinkerspark, ми повинні повернути наш старий. Наги вкрали його кілька місяців тому, і ми повинні мати його, щоб досягти успіху тут.$B$BThere шляху назад до Гномрегану немає, тож ми повинні задовольнитися тим, що є тут, у Азшарі, і я знаю, що ці прокляті Наги все ще мають це! Того, хто очолював набіг, звали Ласзан, страшний ворог. Якщо ви хочете отримати шанс, раджу взяти з собою друзів. Це може бути вашим єдиним способом убити його назавжди!$B$BHe має бути на схід від руїн Елдарата вздовж берегової лінії.",
    O = "Поверни транспондер Tinkerspark для Gigno Flaxwhisker.",
    P = "",
    C = "",
},

[40061] = {
    en = "Killing the Tide Lord",
    T = "[*] Вбивство Володаря припливів",
    D = "Тобі, аутсайдеру, залишається зробити одне, якщо ти справді хочеш допомогти Ретресу. Той, хто претендував на панування над цими землями і зрадив мене, — Володар припливів Нашжарр. Він підлий зрадник, якого треба вигнати з цього світу.$B$BI хочу, щоб він страждав — і дуже страждав. Він живе біля Монумента Гребі Ворона на північному сході. Іди туди, вирви в нього серце, а потім принеси його мені. Переконайтеся, що він шкодує про все, що зробив нам.",
    O = "Принесіть серце Нашарра Володарці припливів Рашал.",
    P = "",
    C = "",
},

[40062] = {
    en = "An Azure Scale for Gnomeregan!",
    T = "[*] Лазурна шкала для Гномрегана!",
    D = "Коли Гномереган уперше прислав нас сюди, вони доручили нам отримати Лазурну луску з Блакитного дракона. На жаль, у нас не було для цього засобів!$B$BWeМи були надто зайняті іншими проектами, і, ну, ми не хотіли ворушити вулик. Тим паче, що ми не маємо реальних військових можливостей! Тепер, коли ви поруч, є можливість!$B$BThe Dragonflight зібралася навколо озера Меннар на північному заході. Принесіть мені Лазурну луску від зграї Блакитних Драконів і обов’язково візьміть друзів.$B$BI Не хотів би, щоб ви померли за мій рахунок!",
    O = "Зберіть Azure Scale для Blimo Gadgetspring.",
    P = "",
