[40150] = {
    en = "Drowning Deeptide",
    T = "[*] Drowning Deeptide",
    D = "Наги Безодні були проблемою відтоді, як ми прибули. Вони напали на наші кораблі, коли ми вперше висадилися на острові Ґілліджим разом із Вищими ельфами, з якими прибули. Незважаючи на те, що ми перемогли, це все одно було достатньою причиною для нас, щоб замість цього поїхати до Лапідіса.$B$BUnfortunately, ти знаєш, що сталося після того, як ми прийшли сюди, але все одно наги залишаються загрозою, з якою потрібно боротися. У них є святилище біля південно-західного узбережжя острова Гілліджіма, розташованого на південь від Лапідіса.$B$BHead до свого святилища, і вбийте нага, якого знайдете. Візьміть у них браслети і принесіть їх до мене.",
    O = "Зберіть 10 браслетів Deeptide від Deeptide Naga для Елізи Колдуелл у Caelan's Rest.",
    P = "",
    C = "",
},

[40151] = {
    en = "The Aqua Stone",
    T = "[*] Водний камінь",
    D = "Маргон Могутній і його син Харгул Витривалий — два морські гіганти, які бродять по острову Лапідіс і навколишніх водах. Особливо Харґул був чимось неприємним і напав на Відпочинок Келана багато тижнів тому. Хоча ніхто не постраждав, він позбавився кількох важливих предметів до того, як морські піхотинці зібралися й підготувалися до бою.$B$BOne таким предметом був Водяний камінь, магічно потужний камінь, який був просочений енергією могутніх Гідромантів. З цим каменем ми могли б краще направити наші здібності з підвищеною потенцією. Я хотів би, щоб ви повернули цей цінний скарб і для цього вбили Харгула Витривалого. Більш ніж на благо Гідромантів, щоб воно ніколи не потрапило в чужі руки.",
    O = "Відновіть Водяний камінь у Харгула Витривалого.",
    P = "",
    C = "",
},

[40152] = {
    en = "Faelon's Folly",
    T = "[*] Безумство Фаелона",
    D = "Наш флот супроводжувала ескадра кораблів високих ельфів. Вони подорожували з нами на острови для дещо секретної місії. У мене було багато друзів у їхній команді, яких я зустрів у Кул-Тірасі. Вищі ельфи — добрий народ, але їхній лідер, Фаелон, був досить сумнівним персонажем — він торгував незаконними товарами та мав справу з неприємними особами.$B$BIt З сумом констатую, що багато з тих людей, яких я колись називав добрими друзями, були вбиті Нагами Глибинної Плити. Зараз вони блукають по берегах Фаелонової дурниці на острові Ґілліджим, збентежені предметом, яким Фаелон прагнув і яким сподівався продати.$B$BGo там і звільнити душі мертвих. Ви знайдете їх на західному узбережжі острова Гілліджім на південь від Лапідіса.",
    O = "Відправляйтеся до Faelon's Folly на острові Gillijim і вбийте 7 забутих фехтувальників, 7 потонулих душ і 7 забутих команд.",
    P = "",
    C = "",
},

