},

[40536] = {
    en = "Bond Through Battle",
    T = "[*] Bond Through Battle",
    D = "Тепер, коли у вас є м’ясо, настав час для справжнього тесту. Це підтвердить, чи ви достатньо здібні, щоб подарувати дитинча віверни, яке стане вашим найнадійнішим супутником.$B$BTake це м’ясо для Sunchaser, він один з Альфи віверни і мій найнадійніший друг. Зауважте, що це буде не подарунок, а виклик. Представляти себе перед альфою з впольованою дичиною є неповагою. Сонцепереслідувач знатиме, що ви шукаєте одного з його дитинчат, і, показуючи м’ясо, ви дасте зрозуміти, що можете бути настільки ж опікуном, як він, і він сам це перевірить.$B$BHe, ймовірно, не вб’є вас.",
    O = "Нагодуйте Sunchaser і переможете його в бою, після завершення поверніться до Тренера Токали в Red Cloud Roost у Mulgore.",
    P = "",
    C = "",
},

[40537] = {
