    P = "",
    C = "",
},

[40538] = {
    en = "Peculiar Won't Even Cut It",
    T = "[*] Peculiar Won't Even Cut It",
    D = "Одна з наших скаутських груп взяла цього ворга з собою. Їм довелося зіткнутися з деякими дитинчатами, і вони стверджують, що деякі з них такі ж тверді, як метал, який ми формуємо та куємо. Я б ніколи не довіряв своєму клану, $N. Але я не буду наражати на небезпеку і скаутську партію, вони не створені для такої роботи. Я навіть не можу послати цього ворга з вами, він поранений і, здається, надто боїться повертатися, його потрібно змінити.$B$BI закликаю вас піти, знайти цих дивних дракончиків і покінчити з ними. Члени мого клану кажуть, що їх можна знайти на схід від Степу, де бродило темне залізо, яке прийняло ім’я Кузниця Ненависті.$B$BKill їх і з’ясуйте, яку хитрість задумали ці гноми.",
    O = "Убийте 8 дивних дракончиків для володарки воргів Каталли в форте Карфанг.",
    P = "",
    C = "",
},

