[40613] = {
    en = "The Forbidden Arts",
    T = "[*] Заборонені мистецтва",
    D = "Був час, коли заради влади ми робили все. Шамани, темні мистецтва, ритуали та жертвопринесення. Але коли ми відкинули захист Терадраса, ми також відкинули багато слабких магій!$B$B<Вона глибоко гарчить.>$B$BWe — це Маграм! Ми сильні! Нам не треба хитрощів, нам не треба материнства! Ми трощимо те, що можемо розбити, і спалюємо те, що не можемо. Подивіться на палаючі ліси на півночі! Жалюзі ельфійські землі є доказом!$B$BWe виганяйте тих, хто не кидає темних мистецтв. Але вони погрожують нам воскреслими мертвими завдяки нашому нерозумному милосердю, що ми не вбиваємо своїх. Знайдіть неподалік наших сестер ізгоїв. Не виявляйте до них милосердя, бо ми ніколи не повинні мати до них.",
    O = "Убийте 4 ізгоїв-некромантів для Джочі в селі Маграм у Пустощі.",
    P = "",
    C = "",
},

[40614] = {
    en = "Almaudrak",
    T = "[*] Альмаудрак",
    D = "$N, добре, що ти сьогодні тут. Ходіть, сядьте, послухайте.$B$BWhen ми повернулися з північних гірських лісів, ми були славні, у піднесеному настрої, ділилися історіями про наші вбивства! Але багато хто з нас не повернувся в село. Щось мстиве шукало нас...$B$BWe на ім’я звір Альмаудрак. Він несе смерть. Він все ще кружляє по темному небу. Я рідко кому розповідаю про Альмаудрака. Багато хто вважає його легендою. Той, хто його шукає, ніколи більше не побачить. Але я знаю його лігво. Це далеко на півночі, біля шляху до гірських лісів, біля зруйнованої ельфійської вежі.$B$BIf ти хочеш бути справжнім ім’ям серед нас. Знайдіть і вбийте Альмаудрака.",
    O = "Знайдіть Альмаудрака, убийте його та поверніть його серце Джочі в село Маграм у Пустощі.",
    P = "",
    C = "",
},

