[40687] = {
    en = "Daelin's Brigade",
    T = "[*] Бригада Даеліна",
    D = "Терамор був заснований багатьма вихідцями з народу Кул-Тірас; наш лідер Джайна навіть родом звідти. Наша позиція обережного нейтралітету з Ордою спричинила проблеми для багатьох ветеранів. Ці солдати одного разу бачили, як брати й сестри гинули під час бою або їхні сім’ї пройшли на війні.$B$BMore і більше наших родичів заблукали з Терамора з кожним днем. Або відразу дезертирував, або був засланий за надто агресивні та розкольницькі дії в спробах призвести нас до конфлікту.$B$BWhile Я поважаю тих, хто служив, я не терплю нелояльності. Дезертири почали заходити занадто далеко, одягаючи наші накидки, уніформу та ховаючись у болоті.$B$BThey треба розібратися, перш ніж вони спричинять нам повну війну. Схованка розташована прямо на захід від Терамора, у Тресатині. Ідіть туди та приберіть їх присутність.",
    O = "Знайдіть схованку дезертирів і вбийте 9 дезертирів-відступників і 9 вигнанців-дезертирів для полковника Бріна на острові Терамор у Пилових болотах.",
    P = "",
    C = "",
},

[40688] = {
    en = "The Blackhorn Conflict",
    T = "[*] Блекхорнський конфлікт",
    D = "Кілька тижнів тому на патруль наших вартових напали таурени з племені чорнорогів неподалік, це було невиправдано та дещо несподівано. З тих, хто піддався нападу, двоє були вбиті, а інші отримали серйозні поранення. Загроза Чорного Рога лише змусила нас бути ще більш обережними в наших діях у Запилених Валах.$B$BThe лідера Чорного Рога звуть Таргос Ненависний Вітер, мерзенний та жорстокий воїн, який навіть не шукає зв’язку з Ордою.$B$BIt це його потрібно зупинити, ви можете його знайти у селі Блекхорн на північному заході на північному краю Dustwallow Marsh.$B$BGo там убийте його родичів і заберіть його голову.",
    O = "Убийте 6 воїнів Чорного Рога, 6 Містиків Чорного Рога та заберіть голову Таргоса Ненависного Вітру для полковника Бріна на острові Терамор у Пилевих болотах.",
    P = "",
    C = "",
},

[40689] = {
    en = "Theramore Deserters",
    T = "[*] Тераморські дезертири",
