    P = "",
    C = "",
},

[40738] = {
    en = "News for Danonzo!",
    T = "[*] Новини для Данонзо!",
    D = "Я не можу повірити, що ми змогли це зробити, але якщо є комусь дякувати, то це Данонзо, він переконав мене продовжити свою роботу і навіть поручився за те, щоб я залишився тут, у цій халупі.$B$BHe вже деякий час хоче працювати над унікальним рецептом, очевидно, йому важко придумати щось, ну, особливе.$B$BМожливо a Гаргантюан Тель-Абім Банан допоможе йому!",
