[40913] = {
    en = "[Deprecated] Mastery of the Bow",
    T = "[*] [Не рекомендовано] Майстерність лука",
    D = "Моїм прицілом керує Елуна, бо кожен мій постріл вірний. Не вірте скептикам, відданість справді є найкращим учителем.$B$BWhilst Я не можу навчити вас усього, я не проти поділитися техніками, які допоможуть вам у довгостроковій перспективі. Принесіть мені п'ятдесят осколків Яскравої Мрії, і в обмін на це ви отримаєте мої знання.",
    O = "Зберіть 50 осколків яскравої мрії для мисливиці Ельдасани в Норданаарі в Хіджалі.",
    P = "",
    C = "",
},

[40914] = {
    en = "A Mysterious Missive",
    T = "[*] Таємниче послання",
    D = "Лист постає перед вами: незапечатаний, але дуже недоторканий. Всередині лист нашкрябаний у грубій та грубій манері, слова повністю іноземні.$B$BSomething почувається дуже неправильно з цього приводу. Знайомий, жахливий голос з'являється у вашій голові; вас тягне до Майстерського льоху біля Каражан.",
    O = "Шукайте цю таємничу енергію в підвалі Майстра на перевалі Мертвого вітру.",
    P = "",
    C = "",
},

[40917] = {
    en = "Eye for an Eye",
    T = "[*] Око за око",
    D = "У цій поштовій скриньці я зберігаю кристал величезної величини та незрівнянної важливості, §N. Цей кристал колись містив сили, отримані з Криниці Вічності. І хоча його сила вже давно вичерпана, шанс її відновити коли-небудь є, погодьтеся? Мені потрібна його сила, і ти допоможеш мені її відновити, якщо хочеш, щоб ти вгамував свій голод, тобто. Якщо ви вирішите допомогти повернути їй колишню славу, будьте впевнені – ваші зусилля будуть винагороджені більш ніж справедливо.$B$BFirstly, ви повинні заглибитися в гору Чорної скелі та привернути увагу Володаря Вірмталака, який переслідує нижні зали Шпиля Чорної скелі.",
    O = "Отримайте Око Вірмталака і принесіть його до Таємничої поштової скриньки.",
    P = "",
    C = "",
},

[40918] = {
    en = "The Stranger and the Potion",
    T = "[*] Незнайомець і зілля",
    D = "У вас все добре, але ви, звичайно, не поспішали повертатися, чи не так? Око вже розкладається, і сили його згасають. Що додає ще один крок до вашого зростаючого списку завдань, $N.$B$BSome некромантія тепер буде потрібною, і хоча подорож до Нордскола не є можливістю, Scholomance все ще існує. Я впевнений, що вони знайдуть зілля, яке може зберегти око.$B$BYou знаєте, що робити, не розчаровуйте мене.",
    O = "Отримайте некромантичне зілля та принесіть його до таємничої поштової скриньки.",
    P = "",
    C = "",
},

[40919] = {
    en = "A Focus of the Ancients",
    T = "[*] Фокус стародавніх",
    D = "Щоб правильно спрямувати сили Ока в кристал, потрібен Аркан Фокус. Такі вогнища були звичайним явищем під час розквіту цивілізації Калдорей, на жаль, я це добре пам’ятаю… Тепер що залишилося від тих пихатих владних крісел, хм? Руїни. Знання, втрачені часом.$B$BYou може вважати, що знайти його неможливо. На ваше щастя, я дам вам провід. Можливо, хтось затримується з Highborne of Dire Moul.",
    O = "Отримайте Arcane Focus і принесіть його до Mysterious Mailbox.",
    P = "",
    C = "",
},

[40920] = {
    en = "Beckoned by the Hateful Depths",
    T = "[*] Манять ненависні глибини",
    D = "О, яке це жалюгідне уособлення. Ви навмисно повернули найбільш аматорський зразок, який тільки могли знайти?$B$BSince вам подобається додавати до власного списку завдань через власну некомпетентність, тоді послухайте: кристал потребує усунення недоліків. Це непросте завдання, і знадобляться дуже спеціальні інструменти. Два молоти: один викуваний глибоко в каменоломні Кузниці Ненависті, а інший використовується Темним Залізом Глибин Чорної Гірниці. Принесіть їх до мене, і ваші помилки будуть прощені.",
    O = "Отримайте Молот Ненависті та Молот Глибин і принесіть їх до Таємничої поштової скриньки.",
    P = "",
    C = "",
},

[40921] = {
    en = "Drenched in Draconic Blood",
    T = "[*] Залитий Драконовою кров'ю",
    D = "Кристал майже готовий: око готове до злиття, фокус готовий забезпечити енергію. Тепер нам потрібен рідкий флюс, щоб зв’язати їх. Найсильніша кров, яку ви можете отримати. Кров могутнього смертного Драконіна.$B$BThere — це генерал, відомий як генерал Драккісат, могутня істота навіть серед інших могутніх істот. Якщо хочеш завершити своє завдання, то переможи його і принеси мені його серце. З ним кристал відродиться, ви отримаєте нагороду, якої так відчайдушно прагнули... і так довго.",
    O = "Здобудьте Серце Крові Дракона та принесіть його до Таємничої поштової скриньки.",
    P = "",
    C = "",
},

[40922] = {
    en = "Eternal Mortality",
    T = "[*] Вічна смертність",
    D = "Я вражений вашим прогресом. Ви виявилися набагато... стійкішими... ніж більшість. Ця наполегливість буде винагороджена благословенням, яке личить такій сміливій душі, як ти, — солодким смаком вічного смертного життя. Але чи справді це те, що ви хочете? Бути схожим на тих пихатих створінь давнини, які ніколи не боялися холодних лещата смерті? Ніколи не відчуваєте приплив адреналіну від життя на межі? Ризик, який робить життя вартим життя... зник. Війна, яку я бачу у твоїй душі, заради якої ти живеш, стане тьмяною.$B$BYou житиме вічно. Ви спостерігатимете, як ваша родина помирає. Ваші друзі. Ваші близькі. А потім що? Коли все, що ти цінуєш, зникне?$B$BNo, я позбавлю тебе цих мук і натомість дам тобі справжнє благословення: благословення смертного життя. Це той момент, якого ви чекали. Зіткнутися з найбільшими викликами і знати, що твоє життя може обірватися будь-якої миті. Це... це те, за що справді варто боротися. Я не правий, $N?",
    O = "Знову поговоріть із Таємничою поштовою скринькою, щоб назавжди стати смертним, або відмовтеся від цього квесту й отримайте безсмертя на своєму 60-му рівні.",
    P = "",
    C = "",
},

[40923] = {
    en = "A Mysterious Boon",
    T = "[*] Таємниче благо",
    D = "Ви виконали свою частину угоди, $N. Найбільш відмінно. Не бійтеся, я дотримаюся свого слова. Зрештою, ви значно допомогли мені, і все це через відчуття хвилювання та небезпеки.$B$BIt настав час, щоб ви отримали моє останнє благословення.",
    O = "Поговоріть із таємничою поштовою скринькою ще раз, щоб отримати подарунок.",
    P = "",
    C = "",
},

[40924] = {
    en = "Signet of Silverlaine",
    T = "[*] Печатка Сільверлена",
    D = "Під час облоги Рейвеншира група злодіїв і розбійників увірвалася до моїх покоїв і викрала найцінніші речі моєї родини. Однією з них була Печатка Сільверлена, яка колись належала моєму батькові й передалася мені.$B$BI отримав новину, що мою сімейну Печатку було передано на знак пошани шановному офіцеру серед роялістів на ім’я Осмарк. Він мав би панувати над Драйрок Піт далеко на заході. Шукайте, де трава перестає рости, і знайдіть величезну яму, повну промисловості.$B$BReclaim моє первородство, і ви будете винагороджені.",
    O = "Поверніть печатку Сільверлейна у верховного офіцера Осмарка в ямі Dryrock для барона Калібана Сільверлейна в Рейвенширі в Гілнеасі.",
    P = "",
    C = "",
},

[40925] = {
    en = "Hollow Web Silk",
    T = "[*] Шовкова павутина",
    D = "Коли цей конфлікт закінчиться, незалежно від того, хто переможе, я повинен бути презентабельним, як знатний представник, який зобов’язаний моїй родині. If I am to retain such a high standing, I require the finest silk that the land can offer.$B$BThe spiders of the Hollow Web Woods create a rare and hard to come by silk. I must have it so that I can commission a fine set of new garments for when this conflict inevitably comes to an end.$B$BYou can find the Hollow Web Woods just to the west of here. Збери мені десять шовків із порожнистої павутини, і я зроблю це варте твого часу, простолюдине.",
    O = "Зберіть 10 шовків із порожнистої павутини з павуків лісу з порожнистої павутини для судді Карсона в Рейвенширі в Гілнеасі.",
    P = "",
    C = "",
},

[40926] = {
    en = "Securing Gilneas I",
    T = "[*] Забезпечення Гілнеаса I",
    D = "Земля заплямована огидним слідом воргенів, які безперешкодно ступають нашими землями. Роялісти вважали за потрібне покарати людей, дозволивши їхньому роду поширюватися, як хвороба.$B$BEven тепер воргени сягають далеко на південь, аж до Зарослого Акра на північний захід звідси. Якщо вони не покладуть край цій загрозі, то ми повинні. Знайдіть плем'я Кривавого Кігтя, яке переслідує Гілнеас, вполюйте на нього та відберіть десять їхніх шкур.",
    O = "Зберіть 10 шкір Bloodclaw у воргенів Bloodclaw для капрала Ренворта в Рейвенширі в Гілнеасі.",
    P = "",
    C = "",
},

[40927] = {
    en = "Securing Gilneas II",
    T = "[*] Закріплення Гілнея II",
    D = "Щоб зупинити Bloodclaw, ми повинні покласти край альфа-версії їхніх зграй. Найсильніші з воргенів відомі як 'альфа', і саме ці істоти керують рештою менших воргенів.$B$BThe Альфу Кривавого Кігтя можна знайти в печері на північному заході. Шукайте табір воргенів на захід від Нортгейтської вежі. Печера має бути зовсім поруч.$B$BSlay їх тринадцять, і поверніться до мене, коли роботу буде виконано.",
    O = "Убийте 13 альфа Кривавого Кігтя, які затримуються в північних печерах для капрала Ренворта в Рейвенширі в Гілнеасі.",
    P = "",
    C = "",
},

[40928] = {
    en = "Foulhide Pests",
    T = "[*] Гнилі шкідники",
    D = "Гноли з мерзотної шкіри стають великою проблемою для регіону. Нещодавно вони напали та заволоділи садом Саутмайр, де помер мій хороший друг на ім’я Ернест.$B$BWhile Я все ще сумую через його втрату, я не можу стояти без діла. Смердна шкіра незабаром переміститься, щоб знайти іншу ціль, щоб втілити своє нестримне бажання битися, і таверна Шейдмор може стати їхньою наступною ціллю.$B$BI прошу вас відправитися до фруктового саду мого друга на південний схід звідси та вбити гнолів, які там мешкають. Принесіть мені на доказ чотирнадцять їхніх пов’язок.",
    O = "Убийте гнолів з огидної шкіри та відновіть 14 пов’язок із огидної шкіри для Дарроу Шейдмора в таверні Шейдмор у Гілнеасі.",
    P = "",
    C = "",
},

[40929] = {
    en = "The Gilneas Lighthouse",
    T = "[*] Гілнеаський маяк",
    D = "Я Еларот Ренворт, і я зобов’язаний підтримувати яскраве горіння вогню цього маяка. До війни ми покладалися на постійне постачання нафти з Південного узбережжя.$B$BEver відтоді, як Стіну Сивогриви було закрито, цей маяк горів від надлишку, який я міг знайти. Це лише питання часу, коли світло перестане горіти, а разом з ним я зникну з цього світу.$B$BI я ще не готовий піти, тому я в розпачі. Лордерон знищила чума, але шепіт розповідає мені про новий бастіон людської сили далеко на заході.$B$BI прошу вас відвідати місто під назвою Терамор, поговорити з їхнім начальником доку та перевірити, чи є нафта, яку можна мені дати.",
    O = "Поговоріть з начальником порту Лорманом на острові Терамор у Пилевих болотах, щоб отримати нафту, призначену для Гілнеасу.",
    P = "",
    C = "",
},

[40930] = {
    en = "The Gilneas Lighthouse II",
    T = "[*] Маяк Гілнеас II",
    D = "Га, тепер, коли ви згадали про це, у нас дійсно є запас старої нафти, яка лежить тут уже кілька років. Мені неприємно вам це казати, але це було зроблено, коли дезертири залишили місто та вирушили заснувати свій табір у Болоті.$B$BI не сумніваються, що їхні цілі щодо легкозаймистої рідини є мерзенними. Це або вони хочуть зробити трохи монети з цінного ресурсу. Зараз не так багато діючих джерел.$B$BIf якщо вам потрібна нафта, вам доведеться її відновити в тих дезертирів.",
    O = "Зберіть викрадену нафту зі схованки дезертира для докмейстера Лормана на острові Терамор у Пилевих болотах.",
    P = "",
    C = "",
},

[40931] = {
    en = "The Gilneas Lighthouse III",
    T = "[*] Гілнеаський маяк III",
    D = "Оскільки ви доклали всіх зусиль, щоб отримати цю нафту, я не бачу причин не надати її вам для вашого повернення до Гілнеасу. Припускаючи, що у вас є засоби, щоб фактично потрапити на це місце. Я чув чутки про громадянську війну, яка назріває за великою стіною, тому пропоную вам бути обережними.",
    O = "Поверніть викрадену партію нафти Елароту Ренворту на варту Сівогрива в Гілнеасі.",
    P = "",
    C = "",
},

[40932] = {
    en = "Wagon Woes",
    T = "[*] Wagon Woes",
    D = "Ти там, чому мені пощастило, що ти наткнувся на мене. Я жахливо проводжу час. Змушений покинути свій сімейний дім, тепер це!$B$BThe колесо на моєму візку зламалося, і його потрібно замінити, але я залишив запасне на плантації. Ви б не проти зробити мені послугу, чи не так? Я не можу повернутися, оскільки воргени взяли верх, але, можливо, ти зможеш.$B$BHead на плантацію Розвік, що на північний захід звідси, і принеси мені моє запасне колесо з дому.",
    O = "Відновіть запасне колесо воза для Дональда Роузвіка біля Нортгейтської вежі в Гілнеасі.",
    P = "",
    C = "",
},

[40933] = {
    en = "Rosewick Worries",
    T = "[*] Розвік Ворс",
    D = "Я хочу вас запитати про одне. Мені знадобиться деякий час, перш ніж я зможу знову почати роботу, але тим часом я хочу, щоб ви переконалися, що турботи моєї дружини вирішені.$B$BI відправив її до таверни Шейдмор перед моїм від’їздом із деякими з наших найцінніших речей. Я хочу, щоб ти дав їй знати, що я в дорозі, і я в безпеці. Ви можете знайти таверну Shademore, прямуючи цією дорогою та прямуючи на захід на перехресті до Рейвенширу.",
    O = "Зустріньтеся з Фреллом Роузвіком у таверні Шейдмор у Гілнеасі.",
    P = "",
    C = "",
},

[40934] = {
    en = "Allies Against Undeath",
    T = "[*] Союзники проти нежиті",
    D = "Огидна пляма нежиті — наймерзенніша й жахлива річ. Землю Гілнеас кілька років тому захопив лич, який поранив землю своєю злою магією.$B$BThis — це історія, схожа на те, що спіткало мої землі. Розумієте, Багряний хрестовий похід не є ворогом, оскільки всі ми служимо одній меті.$B$BI просимо вас проявити себе як агент проти некромантії. Подорож до Грейширу або того, що від нього залишилося. Вбийте мертвих, які все ще там ходять.",
    O = "Убийте 7 скелетів, що залишилися, і 7 мертвих, що тріпаються, для брата Еліаса в таверні Шейдмор у Гілнеасі.",
    P = "",
    C = "",
},

[40935] = {
    en = "Scarlet Corruption",
    T = "[*] Червона корупція",
    D = "Тепер, коли я можу довіряти тобі, що ти не агент нежиті, я можу розкрити справжню причину, чому я шукав нейтральні землі. Хрестовий похід колись був благородною організацією високої чесності, але в стовпах наших лідерів, яким найбільше довіряють, почали з’являтися тріщини.$B$BDeep в Соборі ширяться чутки про справжню долю Верховного інквізитора Фербенкса. У мене є вагомі джерела, які стверджують, що його смерть була зупинена... Неприродним шляхом. Якщо це правда, що некромантія стала звичним явищем серед еліти Хрестового походу, мені потрібні докази.$B$BFind Інквізитор Фербенкс у Багряному соборі та дізнайтеся правду.",
    O = "Дізнайтеся правду про долю верховного інквізитора Фербенкса для брата Еліаса в таверні Шейдмор у Гілнеасі.",
    P = "",
    C = "",
},

[40936] = {
    en = "Vagrant Supplies",
    T = "[*] Бродяга Припаси",
    D = "Ми прибули до Гілнеасу з надією позбутися конфлікту. Однак ми лише виявили ворожнечу.$B$BThree ночей тому рейд воргенів напав на наш табір і забрав найважливіші для нас припаси. Однак ці припаси забрав не блідий Нічний Рев, а Кривавий Кіготь. Вони ще одне плем’я, яке конфліктує з нічним ревом, який має табір на південь від нас. Я не сумніваюся, що вони сховали наші припаси в своїх халупах.$B$BRecover припаси, і поверніть їх нам.",
    O = "Відновіть припаси бродяг із табору Кривавого Кігтя на півдні та поверніться до керівника табору Гетенора в табір бродяг у північному Гілнеасі.",
    P = "",
    C = "",
},

[40937] = {
    en = "Nighthowl Nuisance",
    T = "[*] Нічний вой Неприємність",
    D = "Щоночі ми піддавалися набігам ворожого Nighthowl. Вони є лютим і безжальним ворогом, який випробував наш захист.$B$BWe просимо вашої допомоги в боротьбі з цією загрозою, перш ніж вона здолає нас. Нічного реву можна знайти по всьому північному Гілнеасу, від перевалу Олдрок до Нортгейтської вежі.$B$BSlay їх, і принесіть мені одинадцять кайданів, які вони носять на своїх зап’ястях.",
    O = "Убийте воргенів нічного реву та зберіть 11 кайданів нічного реву для керівника табору Гетенора в таборі волоцюг на півночі Гілнеасу.",
