    P = "",
    C = "",
},

[40987] = {
    en = "Imbued Stone",
    T = "[*] Просочений камінь",
    D = "Clutch of Atherelex покладається на стихійну магію, черпаючи силу з могутньої природної енергії. Щоб отримати доступ до магії, якої ми так бажаємо, ми повинні придбати Просочений камінь.$B$BPowerful, а розлючені кам’яні елементалі, як відомо, зберігають такі предмети.$B$BOn на острові Тель-Абім на схід від Танаріса можна знайти Схвильованих кам’яних елементалів. Подорожуйте туди та придбайте у них Просочений камінь.",
