[41006] = {
    en = "Illusion: Green Dragonkin",
    T = "[*] Ілюзія: Зелений дракон",
    D = "Я, Слумбназ, є майстром оманливої ​​магії.$B$BMy драконові сили можна налаштувати, щоб змінити вигляд мене та тих, хто мене оточує, змінити візуальну реальність самого Азероту. Якщо ви бажаєте скуштувати такої магії, я можу винагородити вас за ваші зусилля в допомозі моїм родичам.$B$BBring мені двадцять п’ять осколків яскравої мрії, і я запропоную вам цю ілюзію.",
    O = "Зберіть 25 яскравих осколків мрії для Slumbnaz у Nordanaar у Hyjal.",
    P = "",
    C = "",
},

[41007] = {
    en = "Collecting Fading Dream Fragments",
    T = "[*] Збирання фрагментів згасаючих снів",
    D = "",
    O = "",
    P = "",
    C = "",
},

[41008] = {
    en = "Nordrassil Stag",
    T = "[*] Нордрасільський олень",
    D = "Могутнього оленя Нордрасіла найбільше шанують друїди тут, у Норданаарі.$B$BFor найбільш тріумфальний з подвигів для нашої справи, я міг би нагородити вас таким верхом. Ця нагорода привілейована лише для тих, хто пішов більше та більше. Принесіть мені п’ятсот осколків Яскравої Мрії, і ви отримаєте винагороду верхом, який найбільше відповідає вашій відданості.",
    O = "Зберіть 500 осколків яскравих снів для Еванділа Найтвінда в Норданаарі в Хіджалі.",
    P = "",
    C = "",
},

[41009] = {
    en = "Glyph of the Dream Panther",
    T = "[*] Гліф пантери сну",
    D = "Саме тут, на Хіджалі, найбільше можна відчути силу Смарагдової Мрії. Останнім часом спостерігаються порушення у спрямуванні таких енергій. Небагато людей здійснюють паломництво до Хіджала, як колись.$B$BI були послані як посланці духів Місячної поляни, які попросили здорових друїдів допомогти Хіджалу. Якщо ви хочете довести свої зусилля, духи в Місячній поляні неодмінно винагородять такі благородні дії. Шукайте Великого Котячого Духа в Місячній поляні та візьміть із собою двадцять Яскравих осколків Мрії, а також вісім Таємничої Есенції.",
    O = "Зберіть 20 яскравих осколків мрії та 8 таємничих есенцій для великого духа кота в Місячній поляні.",
    P = "",
    C = "",
},

[41010] = {
    en = "Glyph of the Emerald Bear",
    T = "[*] Гліф Смарагдового Ведмедя",
    D = "Саме тут, на Хіджалі, найбільше можна відчути силу Смарагдової Мрії. Останнім часом спостерігаються порушення у спрямуванні таких енергій. Небагато людей здійснюють паломництво до Хіджала, як колись.$B$BI були послані як посланці духів Місячної поляни, які попросили здорових друїдів допомогти Хіджалу. Якщо ви хочете довести свої зусилля, духи в Місячній поляні неодмінно винагородять такі благородні дії. Шукайте Духа Великого Ведмедя в Місячній поляні та візьміть із собою двадцять осколків яскравих снів, а також вісім магічних сутностей.",
    O = "Зберіть 20 яскравих осколків мрій і 8 таємничих есенцій для Духа Великого Ведмедя в Місячній поляні.",
    P = "",
    C = "",
},

[41011] = {
    en = "The Upper Binding I",
    T = "[*] Верхня палітурка I",
    D = "Багато років тому я зіткнувся з потужним артефактом, який черпав величезну силу з лей-ліній Азероту. Я мав намір вивчити цей артефакт, але його сили повільно виснажувалися роками. Те дослідження, яке я зміг провести, було досить розчаровуючим, і тепер у мене залишився досить вишуканий прес-пап’є.$B$BIf ви допомогли мені відновити колишню силу цієї старої реліквії, можливо, вам пощастило з нею більше, ніж мені. Перше, що мені потрібно, це Dragonkin Charge, який містить чудову драконічну магію. Я чув, що драконкіни зі Шпиля Чорної Гірки, як відомо, володіють такими предметами.",
    O = "Зберіть заряд Драконіна з Чорного Драконіна в Шпилі Чорної Гірниці для Парнаба в Гілнеасі.",
    P = "",
    C = "",
},

[41012] = {
    en = "The Upper Binding II",
    T = "[*] Верхня палітурка II",
    D = "Я намагався використати Dragonkin Charge, щоб відновити силу реліквії, але мені не вдалося активувати її приховану силу. Я підозрюю, що нам знадобиться більш активне джерело лей-енергії.$B$BI знадобляться деякі предмети, перш ніж я зможу почати цей ритуал. По-перше, мені потрібно, щоб ви зібрали наступні предмети, які має бути легше отримати. П’ять есенцій вогню та один фрагмент землі вистачить, щоб почати. Ці матеріали може бути складно знайти, але я точно знаю, що фрагменти землі можна знайти у земляних елементалів, помічених у Сілітусі. Я пропоную вам почати з цього.",
    O = "Зберіть 5 есенцій вогню та 1 фрагмент землі для Парнаба в Гілнеасі.",
    P = "",
    C = "",
},

[41013] = {
    en = "The Upper Binding III",
    T = "[*] Верхня палітурка III",
    D = "За допомогою елементарного вогню та фрагмента землі ми можемо заземлити реліквію, щоб підготуватися до справжнього зарядження. Це зв’язування вимагає надзвичайного заряду лей-енергії, який міг би конкурувати з силою, яку він мав колись. В Азероті рідко можна знайти таку колекцію таємної сили.$B$BI певний час відчули надзвичайну кількість таємних розрядів, що надходять із континенту Калімдор. З чуток, які я чув, я можу лише зробити висновок, що колись ельфійське місто, яке зараз називається Страшний Мол, виділяє надзвичайну енергію.$B$BIt тут мені потрібен Надзаряджений таємничий резонанс, який слід знайти з будь-яких елементів таємниці, які там матеріалізувалися. Збери мені одну, і я дам тобі реліквію, якою вона була колись.",
    O = "Зберіть надзаряджений таємничий резонанс від таємничих елементалів Страшного Молота для Парнаба в Гілнеасі.",
    P = "",
    C = "",
},

[41014] = {
    en = "The Upper Binding IV",
    T = "[*] Верхня палітурка IV",
    D = "Ви добре впоралися з придбанням цих матеріалів $c. Як я обіцяв, я проведу ритуал, щоб відновити цю реліквію, якою вона була колись. Поговори зі мною, коли я закінчу.",
    O = "Поговоріть з Парнабусом, коли ритуал завершиться.",
    P = "",
    C = "",
},

[41015] = {
    en = "The Binding of Xanthar",
    T = "[*] Зв'язування Ксантара",
    D = "Кілька років тому всередині цієї церкви зберігався рідкісний і потужний предмет. Я був проклятий залишатися з тих пір, як він зник кілька років тому. Якщо ви зможете відновити цей предмет і повернути його Каражану, я був би дуже вдячний.$B$BThe Палітурку розірвали на частини, перш ніж її вкрали, обидві половини тепер належать окремим власникам. Першу взяв маг-відлюдник, який не мав ніяких зв’язків, його акцент, безсумнівно, звучав так, ніби він прибув з півночі.$B$BThe другу половину палітурки взяв чоловік віри, пильності, одягнений у червону тканину та з символом самого Світла. Його марення звучало майже божевільно!$B$BGather Мені і верхню, і нижню половину палітурки, і я можу зробити це цілим.",
    O = "Зберіть верхню палітурку Ксантара та нижню палітурку Ксантаря для Ганвара Праведного в маленькій церкві за межами Каражана.",
    P = "",
    C = "",
},

[41016] = {
    en = "The Wildshaper",
    T = "[*] Wildshaper",
    D = "Альзін він називає себе, Wildshaper, титул, який дали йому друїди в Хіджалі. Перекручена, зіпсована насмішка над тим, ким він був колись, протистоячи всім віруванням, які він колись любив.$B$B'Алзін' колись був моїм другом, але тепер не прагне нічого, крім повної розбещеності Фераласа. Я вважаю своїм обов’язком раз і назавжди покласти край його злим планам.$B$BYou можу знайти його, що ховається глибоко в Жахливому Молоті разом зі своїми родичами сатирів. Убий його і принеси мені його голову, тільки тоді я знайду розраду.",
    O = "Принесіть голову Альзіна Дикотворця для архидруїда Dreamwind у Норданар у Хіджалі.",
    P = "",
    C = "",
},

[41017] = {
    en = "Vilemusk Infiltration",
    T = "[*] Вілемускова інфільтрація",
    D = "Поляна Нордрасіль була місцем спокою протягом багатьох століть, але агенти легіону вже почали поширювати свою бруд. Сатири, зрадники найогиднішого роду, досліджували наші кордони.$B$BThey називають себе 'Вілемуск', ім'я, яке відповідає їхнім незаконним родичам. Я вимагаю їхньої присутності з Хіджала, полюю на них і принесу мені їхні копита як доказ ваших вчинків. Робіть так, і ви будете винагороджені.",
    O = "Зберіть тридцять копит Вілемуса для архидруїда Dreamwind у Nordanaar у Hyjal.",
