[41215] = {
    en = "Whispers of Autumn",
    T = "[*] Шепіт осені",
    D = "На заході лежить Острів Вічної Осені — майже забута легенда нашого народу. Тисячоліття тому, у перші дні нашого прибуття на ці береги, серед нас були ті, хто намагався посадити нове Світове Дерево. На жаль, спроба провалилася, і прокляте дерево наклало на всю землю трансформаційне заклинання, прирікаючи її на вічну осінь. Острів, який не міг ні загинути, ні справді процвітати, став свідченням минулих амбіцій, які пішли наперекосяк.$B$BI просимо вас вирушити в подорож до цього таємничого острова та отримати первісне серце від третантів, які зараз його населяють. Ваші зусилля не залишаться без винагороди.",
    O = "Отримайте первісне серце таласійця в Autumnal Treants для Calhir Dawnchaser в Anasterian Park.",
    P = "",
    C = "",
},

[41216] = {
    en = "The Highland Menace",
    T = "[*] Горяча загроза",
    D = "Ласкаво просимо до Thaumarium. У цих стінах моя чарівна дружина виготовляє найкращі вина, щоб прикрасити Таласське нагір’я. Ми дали цій гавані таку саму назву, як і нашій колишній виноробні в Кель-Таласі, з нетерпінням чекаючи процвітання нашого підприємства.$B$BHowever, нас спіткала неприємність. Наші прагнення спонукають нас вирощувати виноградник на пагорбах на південний схід від цього святилища. Мікроклімат тут виключно сприятливий для вирощування винограду. На жаль, на цих самих пагорбах живе дика порода рисі, через що наші працівники не можуть спокійно обробляти землю. Я благаю вас знищити якомога більше цих істот і повернутися з їхнім хутром як матеріальним доказом їхньої смерті. Ваша допомога не залишиться без винагороди.",
    O = "Принесіть 10 яскравих хутр рисі Мейлору Сталевому Варту в Таумаріум.",
    P = "",
    C = "",
},

[41217] = {
    en = "A Score To Settle",
    T = "[*] Рахунок до зведення",
    D = "Я мушу обтяжити вас ще одним проханням, $N. Кілька тижнів тому, коли я нишпорив пагорбами в пошуках ідеальних місць для вирощування винограду, я став жертвою незрівнянної лютості рисі. У наступній боротьбі ця істота здолала мене, залишивши тяжко пораненим, моє око назавжди втраченим.$B$BA тепер у мені вирує особиста вендета проти цього грізного ворога. Переможете звіра та відновіть його ікло як доказ. Я легко впізнаю це; ікла були більші за будь-які, які я коли-небудь бачив.",
    O = "Принесіть 1 Ікло Шар'Лану Мейлору Сталевому Варту як доказ свого вчинку.",
    P = "",
    C = "",
},

[41218] = {
    en = "Grapes in the Hills",
    T = "[*] Виноград на пагорбах",
    D = "Вітаю, друже. Ви прийшли скуштувати наші славетні вина? На жаль, через безперервні напади рисі вирощування винограду на пагорбах довелося припинити, залишивши нас ні з чим.$B$BYet, я живу з оптимізмом, що серед цього хаосу наші працівники, можливо, залишили відра, наповнені виноградом, на пагорбах на південний схід від цієї оселі. Можливо, вони вже трохи перебродили, але хіба суть виноробства не в тому, щоб враховувати такі нюанси? Якби ви могли дістати хоч десять відер, я міг би наколдувати трохи вина для майбутніх відвідувачів! Ваша допомога була б неоціненною.",
    O = "Принесіть 10 відер винограду Файнріелю Сілверхарпу в Таумарій.",
    P = "",
    C = "",
},

[41219] = {
    en = "Wyrms of the Highlands",
    T = "[*] Wyrms of the Highlands",
    D = "Як членів Срібного Завіту, наша місія чітка – очистити ці землі від будь-яких небезпек, які загрожують біженцям, які шукають притулку. Серед цих загроз значне занепокоєння викликає зростаюча популяція Mana Wyrms. Їхня кількість різко зростає, оскільки вони харчуються маною, яка використовується поблизу, порушуючи баланс, якого ми прагнемо.$B$BI доручити вам вилучити їхню кількість і принести мені десять очей манного змея як доказ їхньої смерті. Цей акт не тільки принесе мир на ці землі, але зібрані очі також послужать каталізаторами для заряджання більшої кількості кристалів мани, вирішуючи дві проблеми в одній спробі.",
    O = "Принесіть 10 очей манного змея командиру Брейдіну в табір Срібного Ковенанта.",
    P = "",
    C = "",
},

[41220] = {
    en = "A Feast for the Poor",
    T = "[*] Свято для бідних",
    D = "Ласкаво просимо до Каплиці Балладора, притулку для тих, хто шукає розради у Світлі в ці складні часи. Навіть за відсутності Сонячного колодязя його сяйво продовжує милувати нас з небес.$B$BMight Я надаю тобі невелику послугу, любий друже? У наших зусиллях організувати бенкет для бідних жителів Кель-Таласа ми виявили, що потребуємо додаткового прожитку. Незважаючи на те, що знатні родини зробили щедрі внески, їжі все ще не вистачає.$B$BI Мене повідомили рейнджери, що м’ясо оленя з рогачого оленя особливо смачне, і особисто я маю схильність до смаку крил Багряного Яструбиного. Якщо ви зможете придбати дюжину кожного, ми влаштуємо бенкет, який запам’ятається на віки.",
    O = "Принесіть 12 шматочків м’яса Стеллхорна та 12 крил Багряного Яструба Талірену в каплицю Балладора.",
    P = "",
    C = "",
},

[41221] = {
