},

[41327] = {
    en = "Manifested Oddities",
    T = "[*] Виявлені дивацтва",
    D = "Треба багато зробити, у Гавані панує хаос, багато поранених. Ви маєте мене вибачити, бо мені потрібно подбати про своїх братів. Хоча будь-яка допомога буде вдячна, я мушу наполягати на тому, щоб поки що залишити це нам. Ви вже зробили достатньо, і було б неввічливо просити більше.$B$BBefore ви йдете, однак Ах З'адор хоче знову поговорити з вами про щось термінове. Ви можете знайти його надворі. Енкіле Тораларе, друже, і тобі хороших новин.",
    O = "Поговоріть з Akh Z'ador в Гавані.",
    P = "",
