[41351] = {
    en = "Death In One Strike",
    T = "[*] Смерть одним ударом",
    D = "Зламаний клинок, який ви принесли мені, належав Разуву Івальді, одному з найсильніших лицарів Лордерона. Лише його меч убив більше орків, ніж будь-який інший солдат у доленосний день облоги Лордерона, оскільки він урізав їх одним ударом. $B$BFollowing через кілька днів після того, як загарбники були відбиті, його проголосили чемпіоном, оскільки саме він зупинив цю абсолютно жорстоку жінку-орка, яка прорізала собі шлях крізь наші війська, як масло. Як трофей після її смерті він узяв у неї чудове діамантове намисто, яке ревно тримали, проголошуючи це свідченням свого найбільшого досягнення.$B$BHe був хорошою людиною та другом, але одержимість цим кулоном і його значенням поглинула його. Востаннє я бачив його, коли він повертався зі зрадником Менетілом, коли він, як один зі своїх товаришів по лицарях смерті, встромив у мене свій заплямований рунний клинок. $N, я благаю вас, знайдіть його і заспокойте його збентежений дух. Будь ласка, зробіть це замість його господаря.",
    O = "Знайдіть Разува Івальді та візьміть у нього намисто Тіллі. Поверніть її їй в опері Нижніх Каражанських залів.",
    P = "",
    C = "",
},

[41352] = {
    en = "Auntie Tillia",
    T = "[*] Тітонька Тілля",
    D = "<Якщо робота виконана та винагорода під рукою, у вас залишився дорогий золотий перстень, який вам непотрібний. Розглядаючи це технічно власність родини Ерлуоків, ви думаєте, чи погодився б Арчибальд на це в його жахливій ситуації.>",
