[41555] = {
    en = "Razorfen Grog",
    T = "[*] Разорфен Грог",
    D = "Це моя ціль всього життя — створити найпотужніший, смачний і смачний напій, відомий Азероту: заповідник Хорнфанг! Його багатий смак і унікальна текстура зачарують кожного, хто насолоджується його пінним верхом і гірким смаком. Тоді я закінчив розбирати правильну формулу. Мені неприємно визнавати це, але мої попередні спроби так чи інакше провалилися. Завжди чогось не вистачає, що справді об’єднує всі інгредієнти. Мені просто потрібно дізнатися, що це таке! Ось чому я приїхав сюди, до Ратчет, щоб я міг зібрати всілякі чутки та історії про потенційні компоненти, яких може не вистачати для моєї наварки.$B$BApparently місцевий quillboar Razorfen Kraul варить власний алкоголь. Хто б міг подумати, що ці примітивні люди-свині здатні самостійно виробляти грог? Мені потрібно дізнатися, що таке цей грог, як його роблять і чи є в ньому секретний інгредієнт, який я шукаю!",
    O = "Принесіть зразок Razorfen Grog до Hal'togg Hornfang у Ratchet.",
    P = "",
    C = "",
},

[41556] = {
    en = "The Hottest Hot!",
    T = "[*] Найгарячіші гарячі!",
    D = "Мені здається, я добре розумію, як був зроблений цей грог. Це мало схоже на те, що я варив раніше з шиповника, але вони, мабуть, використовують інший метод. Можливо вони використовували вищу температуру...? Так, це повинно бути так! Вища температура під час варіння шипшини може зменшити гіркоту до приємної кількості. Проте як вони досягли такого потужного полум’я, я досі не розумію. Вони напевно використовували магію. Оскільки в мене немає магічних засобів, ми повинні знайти щось інше. Стихії цього світу іноді залишають відблиск своєї сутності. Одна така річ може потенційно нагріти полум’я до необхідного рівня. $N, вийди і принеси мені елементальний вогонь з будь-якого вогняного елементала — він нам потрібен, щоб роздути вогонь!",
    O = "Поверніться з шістьма Elemental Fire до Hal'togg Hornfang у Ratchet.",
    P = "",
    C = "",
},

