},

[41562] = {
    en = "Yellow Hops",
    T = "[*] Жовтий хміль",
    D = "Це моя ціль всього життя — створити найпотужніший, смачний і смачний напій, відомий Азероту: Золотий лагер Thunderbrew! Його багатий смак і унікальна текстура зачарують кожного, хто насолоджується його пінним верхом і гірким смаком. Принаймні я б хотів, щоб це було так, але мої попередні спроби так чи інакше провалилися. Завжди чогось не вистачає, що справді об’єднує всі інгредієнти. Мені просто потрібно дізнатися, що це таке! Ось чому я прийшов сюди, до Ретчету, ті дурні в Стальгорні базікають нісенітницю з немитих борід. Вони не побачать величі, якщо він вкусить їх за дупу!$B$BTo щоб зварити справді смачний лагер, потрібно багато різних сортів хмелю. Оскільки більш поширені його варіанти не мали того сильного ефекту, якого я бажаю від свого навару, мені потрібно шукати щось незвичайне. Quillboar з глибокого півдня цих земель, здається, обізнаний у мистецтві пивоваріння, принаймні я так чув. У них повинен бути свій хміль, з якого варять!",
    O = "Thaldon Thunderbrew у Ratchet потребує п’ятнадцять пучків жовтого хмелю.",
    P = "",
    C = "",
},

[41563] = {
