[41716] = {
    en = "The Shatterblade Expedition",
    T = "[*] Експедиція Shatterblade",
    D = "Наша ситуація тут, у Shatterblade Post, небезпечна. Ми далеко від дому, і наші лінії постачання розтягнуті надзвичайно тонко. Це, звичайно, не ідеальна ситуація ні для воїна, ні для будь-якого форпосту.$B$BMy радник Ранагг має більш актуальну інформацію. Якщо ви дійсно бажаєте допомогти нам тут, поговоріть з ним, і він надасть вам інформацію.",
    O = "Поговоріть з радником Ранаггом у Shatterblade Post у Grim Reaches.",
    P = "",
    C = "",
},

[41717] = {
    en = "The Dragonmaw Threat",
    T = "[*] Загроза Dragonmaw",
    D = "Наша найбільша загроза — це клан Драконьої Пасти. Їхня кількість величезна, а їхня сила завжди присутня. Нещодавно вони напали і зруйнували вал Беґґота. Одна з ключових оборонних споруд для гномів Дун Кітаса.$B$BI бояться, що з цією перемогою вони стануть сміливішими у своїх діях.$B$BWe повинні дізнатися про їхні плани на майбутнє. Я вимагаю, щоб ви прямували до Валу Баґгота на південний захід і знайшли Ордени Драконьої Пасти у нападників. Я впевнений, що в одного з них воно є.$B$BWhen ви відновите замовлення, поверніться до мене.",
    O = "Отримайте накази Драконьої Пащі в одного з орків у Валу Беґґота та поверніться до радника Ранагґа на пост Shatterblade Post у Грим-Річі.",
    P = "",
    C = "",
},

[41718] = {
    en = "The Dragonmaw Orders",
    T = "[*] Ордени Драконьої Пасти",
    D = "У цих планах детально описано подальші напади на Дун Кітас, але, що важливіше, на Пост Шатерблейд. Схоже, що ці плани координує Гешган Блекхоллоу, один із капітанів «Драконової Пащі».$B$BBring цю інформацію командиру Аґгнашу, він вирішить наш подальший курс дій.",
    O = "Передайте накази командиру Аґгнашу на пост Shatterblade у Grim Reaches.",
    P = "",
    C = "",
},

[41719] = {
    en = "Death to Geshgan",
    T = "[*] Смерть Гешгану",
    D = "Гешган Чорна порожнина, це ім’я мені знайоме.$B$BWhen ми вперше прибули в Грим Ричіз, ми провели низку розслідувань клану Драконьої Пасти. Гешган — вірний капітан, який керує власною свитою досвідчених і загартованих у боях воїнів. Настав час покласти край його планам.$B$BGeshgan можна знайти в руїнах фортеці Столгаз на північному заході. Я раджу тобі взяти союзників, бо це забуте місце заповнене воїнами Драконьої Пащі. Убий його і принеси мені його голову як доказ.",
    O = "Убийте Гешгана Блекхоллоу та принесіть його голову командиру Аґґнашу на пост Шатерблейд у Грим-Річі.",
    P = "",
    C = "",
},

[41720] = {
    en = "Stolgaz Documents",
    T = "[*] Документи Stolgaz",
    D = "Я чув, що ви маєте намір сміливо подолати фортецю Столгаз, якщо так, у мене є завдання, яке потребує уваги.$B$BSome час тому фортеця Столгаз колись була серцем Похмурих плесів. Він створював силу та містив багато важливих документів.$B$BIt ці документи мені потрібні, і я впевнений, що зможу знайти серед них щось корисне. Відправляйтеся до Крепості Столгаз на північний захід і знайдіть ящик із цими документами. Принесіть їх до мене, і я винагороджу вас.",
    O = "Відновіть документи Stolgaz із Stolgaz Keep для радника Ranagg на Shatterblade Post у Grim Reaches.",
    P = "",
    C = "",
},

[41721] = {
    en = "Zarm'geth Stronghold",
    T = "[*] Зам'гетська фортеця",
    D = "Час битви настав, і час героїв настав. Настав час вдарити в серце наших ворогів і розтрощити їх. Фортеця Зармґет на північному заході є штаб-квартирою клану Драконьої Пащі в Похмурих плесах. Саме там ми забезпечимо нашу перемогу.$B$BTravel там і вбийте їх іменем Орди! Нехай вони пізнають нашу лють і повернуться, коли їх заб’ють.",
    O = "Убийте 7 елітних представників Dragonmaw, 7 чемпіонів Dragonmaw і 7 Dragonmaw Darkweavers для командира Aggnash на Shatterblade Post у Grim Reaches.",
    P = "",
    C = "",
},

[41722] = {
    en = "Shatterblade Stew",
    T = "[*] Рагу Shatterblade",
    D = "Лок'тар друг! Я Барголнак, і я відповідаю за куховарство тут, у місті. Якщо ви щось знаєте про перебування на периферії, це те, що все може стати досить застарілим.$B$BIt Моя робота — запропонувати певну різноманітність тим, хто розміщений тут. Ви були б здивовані, як зміна їжі може вплинути на моральний дух.$B$BThe Єдиний раціон, який у мене є, — це м’ясо, і я хотів би трохи порізноманітнити.$B$BYou мав би знайти багато Коричневого затворника по всьому Грим Ричз. Якби ви змогли зібрати шість ніг затворника, це б мені дуже допомогло.",
    O = "Зберіть 6 ніг відлюдників у коричневих павуків-відлюдників для Барголнака на пошті Shatterblade у Грім-Річс.",
    P = "",
    C = "",
},

[41723] = {
    en = "Bounty on Wild Maw",
    T = "[*] Нагорода за Wild Maw",
    D = "Люта Дика Пасть на північ від Shatterblade Post стала більшою загрозою, ніж раніше вважалося. Їхня ворожість і розташування створюють загрозу для наших операцій тут, у цьому регіоні.$B$BA винагорода дається кожному, хто пропонує свої послуги від імені орди. Зменште популяцію Дикої Пащі, щоб їхня кількість не становила реальної небезпеки для експедиції, і шукайте Гранта Моркана в Shatterblade Post за нагороду після завершення.",
    O = "Убийте 6 диких пащів і 10 незграбних диких пащів для Гранта Моркана на посту Шатерблейд у Грім-Річі.",
    P = "",
    C = "",
},

[41724] = {
    en = "The Betrayal of Rethkag",
    T = "[*] Зрада Реткага",
    D = "Колись у нас був чорнокнижник тут, у Shatterblade Post, який говорив про честь, про вірність. Насправді він був відданий клану Драконьої Пащі.$B$BThis орк має ім’я Реткаг Мірефанг. Воістину мерзенна і безхребетна істота. Я допоміг йому знайти сімейну реліквію, допоміг знайти спокій. Я навіть вважав цього хробака своїм дорогим другом протягом багатьох місяців.$B$BHis дії завдали мені болю набагато більше, ніж будь-яка рана, яку я зазнав, і тепер я вимагаю його крові. Ви можете знайти його, дивлячись на регіон із його вежі в Геткарі, що на північний захід звідси. Убий його і повернися до мене.",
    O = "Убийте Реткага Мірефанга в Гет'карі за Гар'гекка на посту Шаттерблейд у Грім Ричі.",
    P = "",
    C = "",
},

[41725] = {
    en = "Dark Iron Components",
    T = "[*] Компоненти темного заліза",
    D = "Бах, стан цього місця майже неможливо зберегти. Мені доручено бути інженером-облогою без фактичної техніки чи частин?$B$BThe Єдине обладнання, над яким я маю працювати, це дві захоплені катапульти Драконьої Пасти. Якщо я буду коли-небудь створювати чи працювати над чимось, мені доведеться імпровізувати.$B$BThe сусідні розкопки гномів на півдні нещодавно були зайняті Темним Залізом. Якщо вони щось знають, це його зловмисні хитрощі та інженерія.$B$BI хочу, щоб ви пішли до розкопок Ґролдана на південь звідси та знайшли будь-які компоненти з темного заліза, які вони могли б мати. Вони краще принесуть користь у моїх руках, ніж у наших ворогів.",
    O = "Зберіть 6 компонентів із темного заліза з розкопок Гролдана на південь для Харлека на пошті Shatterblade у Grim Reaches.",
    P = "",
    C = "",
},

[41726] = {
    en = "Scavenging the Wrecks",
    T = "[*] Розбирання уламків",
    D = "Тепер, коли я відновив деякі компоненти, я хотів би взятися за деякі більш складні частини. Деякий час тому багато парових танків було знищено під час війни між гномами Дун Кітаса та Драконьою Пащею. Ці колись могутні машини стоять без діла в сільській місцевості на заході та південному заході, гниючи.$B$BSuch складну інженерну техніку я не можу відтворити тут, у полі. Знайдіть мені сім із цих заплутаних частин на затонулих кораблях у всьому регіоні, і я подбаю про те, щоб ви отримали щедру винагороду.",
    O = "Зніміть 6 заплутаних частин з уламків парових танків у всьому регіоні для Harlekk у Shatterblade Post у Grim Reaches.",
    P = "",
    C = "",
},

[41727] = {
    en = "Entranced Magic",
    T = "[*] Entranced Magic",
    D = "Ти там, $c. Мені потрібна допомога в життєво важливому для Орди завданні, яке могло б забезпечити наше місце тут, у Похмурих плесах. У регіоні зберігається прихована сила, і я хочу отримати її для себе.$B$BTo для використання такої енергії потрібні природні матеріали, приховані магічною життєвою силою. Я вимагаю, щоб ви зібрали кров сусіднього зачарованого дракона. Ці істоти знаходяться під контролем клану Драконя Пасть, і їх можна знайти на південний захід звідси. Збери їхню кров і поверни її мені.",
    O = "Зберіть 5 флаконів зачарованої крові для далекого провидця Мотанга на пошті Shatterblade у Грим-Річі.",
    P = "",
    C = "",
},

[41728] = {
    en = "Natural Remedies",
    T = "[*] Природні засоби",
    D = "Якщо я хочу по-справжньому захопити магією регіону, мені знадобиться низка природних матеріалів, щоб розширити мої здібності. Наша справжня робота ще попереду, але ми все одно маємо підготуватися.$B$BI потрібні трохи енергії Скверни від демонів палаючого легіону, я знаю, що вони присутні в Пустощі, шукайте їх там.$B$BLastly, мені знадобиться луска василіска, василіски Кришталевого хребта, щоб бути точнішим. Цю рідкісну породу можна знайти вздовж Дикого узбережжя в Тернистій долині, пошукайте їх і візьміть одну з їхніх лусок.",
    O = "Зберіть довготривалу енергію Скверни у демонів у Пустощі та кришталеву луску хребта у василісків у Тернистій долині для Далекого провидця Мотанга на посту Shatterblade у Grim Reaches.",
    P = "",
    C = "",
},

[41729] = {
    en = "Dark Essence",
    T = "[*] Темна сутність",
    D = "Є один останній матеріал, який мені потрібен перед тим, як виконати наші завдання. На південь від області лежить місце під назвою Похмура Долина. Це спустошена й зіпсована земля, яку спотворила темна й невідома сила.$B$BThis сила — це те, чого я шукаю, і її можуть заволодіти духи гномів, які зараз переслідують саму западину. Убийте їх і поверніть мені Темну Есенцію з їхніх останків.",
    O = "Відновіть Темну Есенцію від привидів Похмурої Долини для Далекого Провидця Мотанга на Пості Шаттерблейд у Грім Ричі.",
    P = "",
    C = "",
},

[41730] = {
    en = "The Power of Uth'okk",
    T = "[*] Сила Uth'okk",
    D = "Всі матеріали зібрано, ми підійшли до кульмінації наших зусиль. Якщо ми хочемо по-справжньому використати таку енергію, ми повинні спочатку знайти відповідний канал, який би її утримував.$B$BLong тому великий дорогоцінний камінь величезної сили був принесений у цей світ Гул'даном і його поплічниками. Кулон Ут'окка був залишений Ороноку Розірване Серце, одному з лейтенантів Гул'дана. Саме цей кулон я шукаю. Ви можете знайти його в глибинах Штормових руїн на острові Балор. Це буде непросте завдання, але я хочу, щоб ви вбили його і принесли мені силу Кулона Ут'окка.$B$BDo це, і ви будете винагороджені.",
    O = "Убийте Оронока Розірване Серце та відновіть Підвіску Ут'окка з Руїн, викликаних Бурею, для Далекого Провидця Мотанга на Посту Шаттерблейд у Похмурих плесах.",
    P = "",
    C = "",
},

[41731] = {
    en = "The Ritual of Uth'okk",
    T = "[*] Ритуал Uth'okk",
