},

[41735] = {
    en = "Stonehide Rations",
    T = "[*] Раціони Stonehide",
    D = "Ви там, ви збираєтеся відправитися в Shatterblade Post? Якщо так, у мене є хороший друг, який живе там, і я впевнений, що йому знадобиться послуга. Барголнакк відповідає за приготування їжі як м’ясник на аванпостах, і він завжди шукає свіже м’ясо.$B$BIf Ви могли б зробити мені солідну користь і принести йому вісім кам’яношкірих флангів від місцевих кам’яношкірих кабанів, я впевнений, що це багато означало б.$B$BYou може знайти Shatterblade Post на сході, зібрати фланги та принести їх до Барголнакк.",
    O = "Зберіть 8 кам’яношкірих флангів для Барголнакка на посту Shatterblade у Grim Reaches.",
    P = "",
    C = "",
},

[41736] = {
    en = "A Land in Peril",
    T = "[*] Земля в небезпеці",
    D = "Кілька місяців тому я прибув з Мотангом, щоб вивчити елементи тут, у Грим-Річс. Як бачите, тепер я залишився один у цьому завданні, оскільки Мотанг втратив себе в гонитві за владою...$B$B<Your'thegg зітхає.>$B$BThe сама земля волає про допомогу. Я відчуваю страждання стихій і шукаю відповіді на них. Якщо ви хочете допомогти, мені потрібно, щоб Reachroot, місцева трава, яка росте по всьому регіону, зібрала вісім бушелів і повернулася до мене.",
    O = "Зберіть 8 Reachroot для Yor'thegg the Wise у Grim Reaches.",
    P = "",
    C = "",
},

[41737] = {
    en = "Signs of Corruption",
    T = "[*] Ознаки корупції",
    D = "Якщо ми хочемо справді зрозуміти масштаби корупції в Grim Reaches, ми повинні зібрати її зразок. Прояви цієї огидної енергії вкорінилися у формі мулу, який заразить землю. Я прошу вас принести мені шість застарілих псувань із Огидного тину Похмурих плесів. Ви можете знайти їх скупчення в Бранґарській дурниці на північний схід звідси.",
    O = "Зберіть 6 затяжних пошкоджень із Огидного тину неподалік для Йор'тега Мудрого в Похмурих плесах.",
    P = "",
    C = "",
},

[41738] = {
    en = "Yor'thegg's Ritual",
    T = "[*] Ваш ритуал",
    D = "Ситуація така, як я й побоювався, земля зіпсована і в стані безладу. Мені потрібно буде поспішно спілкуватися зі стихіями.$B$BThis Для проведення ритуалу потрібні місцеві природні матеріали. По-перше, мені потрібно п’ять декоративних пір’я з найближчих молотів. Три зв'язуючі полум'я від Вогнем'язів Драконої Пасти на північний захід. І, нарешті, мені потрібне одне незаймане Серце з Кам’яної Шкури від Старших Кабанів із Кам’яної Шкури. Зберіть усі ці матеріали та поверніть мені.",
    O = "Зберіть 5 вишуканих пір’я, 3 зв’язуючого полум’я та незаймане серце з кам’яної шкіри для Йор’тегга Мудрого в Грим Рейчі.",
    P = "",
    C = "",
},

[41739] = {
    en = "The Flame of Dagnoth",
    T = "[*] Полум'я Дагнота",
    D = "Полум'я Дагнота? Елементи дали нам дуже важливу інформацію, але це те, чого я не знаю. На думку спадає лише одне ім’я, яке може знати про цей таємничий вогонь. Дортас Рід$B$BHe — людина, яка мандрує Похмурими плесами. Останній раз, коли я з ним розмовляв, він, здається, досить багато знав про регіон, я підозрюю, що він знає дещо про це полум’я. Знайдіть його на південному заході, біля входу в Grim Reaches, і запитайте про Flame of Dagnoth.",
    O = "Поговоріть з Дортасом Рідом біля входу в Grim Reaches і запитайте про Flame of Dagnoth.",
    P = "",
    C = "",
},

[41740] = {
    en = "The Deed for Dorthas",
    T = "[*] Документ для Дортаса",
    D = "Якщо я чомусь навчився тут, на Азероті, це те, що все має свою ціну. Якщо вам потрібна інформація про Полум’я Даґнота, я вимагаю доказів того, що ви на моєму боці, а не на боці якогось замаскованого ворожого агента.$B$BThat здається справедливим компромісом, так?$B$BI вимагаю, щоб ви вирушили до Безплодних земель на південний захід і виявили присутність Чорного Драконіна в ущелині Летлор. Я чув чутки, що їхні луски зачаровані прихованою драконовою енергією. Принесіть мені одну таку зачаровану луску дракончика від «Пікучих дракончиків», і ви отримаєте необхідну інформацію.",
    O = "Зберіть зачаровану луску дракончика з обпікаючих дракончиків у безплідних землях для Дортаса, читаючого в Grim Reaches.",
    P = "",
    C = "",
},

[41741] = {
    en = "Return to Yor'thegg",
    T = "[*] Поверніться до Yor'thegg",
    D = "Полум'я Дагнота - це старий і майже древній колодязь гномської магії. Це полум’я було розпочато давно як традиція вшановувати духи померлих.$B$BHowever, це колись почесне полум’я було перекручено та зіпсовано.$B$BThe Полум’я Даґнота все ще горить сьогодні, глибоко в серці Похмурої Долини, спонукаючи стародавніх духів знову прокинутися.$B$BTake цю інформацію назад до Йор'тег, можливо, він придумає спосіб очистити це зло.",
    O = "Віднесіть зібрану інформацію до Йор'тегга Мудрого в Грим Ричі.",
    P = "",
    C = "",
},

[41742] = {
    en = "Expelling Evil",
    T = "[*] Вигнання зла",
    D = "Будьте готові, адже справжній виклик нарешті настав. Якщо ми хочемо принести мир стихіям, ми повинні вигнати зло, пов’язане з Полум’ям Даґнота. Його отрута зберігалася надто довго й завдала всім великого хаосу.$B$BFind Полум’я Даґнота та киньте цей чарівний пил у вогонь. Він повинен проявити злу енергію, дозволивши їй бути знищеною раз і назавжди, зробіть це на благо стихій і на благо самої землі.",
    O = "Знищіть злу енергію, що зберігається у Полум'ї Даґнота, для Йор'тегга, мудрого в Grim Reaches.",
