[41789] = {
    en = "Ursan Tribe",
    T = "[*] плем'я урсан",
    D = "Подивіться навколо себе. Плем’я Урсана — колись шляхетне для меншої раси — тепер марить божевіллям, спричиненим смертю. Їхні серця розбиті, їхні розуми втрачені.$B$BThey осквернили одну з наших священних місячних криниць... і вбили її охоронця. Такий проступок не може залишитися без відповіді.$B$BWere часи менш жахливі, я прагнув би вилікувати їхній дух. Але ви це бачили — що сквернистий мох робить із цими лісами. Як тільки воно пустить коріння, немає спокути для їхнього роду.$B$BCull їх. Скільки зможете. Принесіть мені їхні чари — жалюгідні реліквії, колись створені їхніми шаманами для відганення злих духів. Дивна віра.$B$B<Він ледь помітно посміхається, гіркий блиск в його очах.>$B$BClearly... їм не вдалося.",
    O = "Принесіть 20 амулетів Урсана для Дретаніса на Урсанових висотах.",
    P = "",
    C = "",
},

[41790] = {
    en = "Reclaiming the Moonwell",
    T = "[*] Повернення Місячного колодязя",
    D = "Плем'я розбите, їхня сила розвіяна за вітром. Настав час повернути те, що належить нам — місячна криниця не повинна залишатися зануреною в їхній сморід.$B$BTheir так званий лідер, Аркод Білий, ймовірно, навіть зараз гуляє навколо священних вод, оскверняючи те, що залишилося від його охоронців. Колись він був відданим слугою Урсола... одного з найшанованіших священнослужителів бога-ведмедя.$B$BCurious, чи не так? Впасти так далеко. Потрібно дивуватися, яке богохульство змусило його мовчати Урсол.$B$BEnd його. Відріжте голову їхньої корупції і принесіть її мені. Без нього плем’я розпадеться — і я раз і назавжди очистю місячну криницю від їхнього бруду.",
    O = "Принесіть голову Аркода Білого Дретанісу.",
    P = "",
    C = "",
},

[41791] = {
    en = "The Shatterblade Outpost",
    T = "[*] Застава Shatterblade",
    D = "Наша експансія до Східних Королівств є дуже успішною. Заснування Kargath стало життєво важливим моментом у зміцненні нашої присутності на околицях Khaz Modan. Але це був лише один крок у плані Вождя щодо земель за Великим морем.$B$BTo На північний схід від великого ставка Лох-Модан прохід веде до Похмурих плесів, незв’язаних земель гірських гномів, пронизаних мерзенними орками Драконої Пасти. Командир Аґгнаш заснував на північно-східній околиці форпост Шаттерблейд — фортецю, побудовану для нейтралізації агресії Драконьої Пасти в цих частинах Східного Королівства. Вирушайте туди та допоможіть йому виконати справу Вождя.",
    O = "Белгром Рокмол хоче, щоб ви поговорили з командиром Аґгнашем на посту Shatterblade у Похмурих плесах.",
    P = "",
    C = "",
},

[41792] = {
    en = "Hog For Morkan",
    T = "[*] Кабан для Моркана",
    D = "Мій брат Моркан дислокується на посту Shatterblade Post у Грим Ричі. Сурова земля на схід від озера Лох-Модан і водно-болотних угідь. Гноми та орки Драконьої Пасти вже давно борються за контроль, і наш воєначальник Тралл бажає сам оцінити ситуацію. Дика природа підступна й невблаганна, а мій брат, хоч і амбітний і дисциплінований, все ще молодий і недосвідчений. Щоб підбадьорити його дух, я хочу, щоб він скуштував цю варену свинину, яку я приготував, вона є його улюбленою. Якби ви могли принести це йому, я був би вам у великому боргу, $c.",
    O = "Принесіть тушкованого свиня до Бурчання Моркана в Shatterblade Post у Грим Рейчі. Ви можете дістатися до нього, прямуючи на схід від боліт, або пройшовши через тунель на південному сході озера Лох-Модан.",
    P = "",
    C = "",
},

[41793] = {
    en = "Scars of the Past",
    T = "[*] Шрами минулого",
    D = "Минуле Орди пронизане провиною та помилками. Наші колишні союзи з різними кланами орків заплямували нашу честь, пляму, яку ми повинні зішкребти, якщо хочемо ступити в нове майбутнє. Клан Драконьої Пасти, фанатичні ветерани, відповідальні за поневолення Червоних Драконів, згуртувався в Похмурому Плесі, скелястому місці на схід від озера Лох-Модан. Їхні ілюзії змушують їх чіплятися, як божевільні, за свої старі способи, нездатні побачити безглуздя всього цього.$B$BWe відправив загін до Похмурих плесів за наказом вождя Тралла через озеро Лох-Модан, повз тунель у Будинку Далеких Странців на південний схід від озера. Я хочу, щоб ви приєдналися до них у Shatterblade Post. Допомагайте їм усюди, де можете. Неси честь орді, леле!",
    O = "Відправляйтеся до Shatterblade Post у Грим Ричі та поговоріть з їхнім командиром.",
    P = "",
    C = "",
},

[41794] = {
    en = "The Storms of Balor",
    T = "[*] Бурі Балора",
    D = "Мок'рах, молодий. За затоками Великого моря на півночі лежить занедбаний острів Балор. Неприродні шторми спустошують його береги, а зловісна магія псування Гул'дана все ще залишається на землі навіть через десятиліття після його знищення. Мій клан, Кровава Долина, дислокується на одному зі східних островів, що оточують Балор, від імені нашого вождя Трала. Вождь Кілрогг сам зголосився очолити цей наступ проти відродженого давнього клану Штормрейверів.$B$BCould Прошу про послугу? Моєму товаришу по клану, далекому провидцю Сарно, потрібне це зілля для його ворожінь. Якби ви могли принести це йому, ви зробили б велику послугу Орді. Поговоріть із Тістою, майстром вітряного вершника, і вона швидко приведе вас до Балора.",
    O = "Доставте зілля Мока Тардіна далекому провидцю Сарно в Поймку Штормбрейкер.",
    P = "",
    C = "",
},

[41795] = {
    en = "A Unknown Letter",
    T = "[*] Невідомий лист",
    D = "З нашого минулого, юного, виринула страшна темрява. Темрява загрожує не лише Орді, а й усьому живому в Азероті. Нещодавно ми отримали загадкового листа від невідомого відправника, написаного чорним як смоль чорнилом. Він попередив нас про реліквію Другої війни, яка відродилася, щоб поширити своє насіння хаосу по всьому світу. Клан Штормів, маріонетковий клан Гул'дана, повернувся та об'єднав сили зі своїми старими союзниками, Радою тіней. Їхні чорнокнижники вчинили незліченні звірства в минулому, і якщо ми не зупинимо їх, я боюся, що ми можемо зіткнутися з новою епохою терору. Я наказав одному зі своїх радників і вождю клану Кровавої Долини, Кілроггу Мертвому Оку, придушити їхнє повстання. Він відправився на острів Балор, їхню колишню оперативну базу незліченну кількість років тому.$B$B$N, я хочу, щоб ти наслідував їхній приклад і допоміг клану Кровавої Порожнини. Візьміть цепелін до базового табору Гром'гол і поговоріть з місцевим майстром вітряного вершника. Вона може привести вас на острів на захід від Штормовія.",
    O = "Поговоріть з Kilrogg Deadeye на Balor.",
    P = "",
    C = "",
},

[41796] = {
    en = "Far From Home",
    T = "[*] Далеко від дому",
    D = "Вітаю, добре $c. Ви чули про грандіозний турнір у Northwind? Місцева вельможа влаштувала лицарський турнір і запросила до участі різні народи людей, у тому числі Терамор! Леді Праудмур обрала жменьку наших охоронців у змагання, і мої прекрасні діти були серед них! Я ледве встиг з ними попрощатися, так швидко вони повинні були піти. Скажіть, ви випадково подорожуєте до Northwind? Чи не могли б ви бути такими добрими і дати моєму хлопчику Борису ці шарфи? Вважайте, що я як їхній батько підтримую їх навіть тут, у Тераморі.$B$BI чув, що ви можете дістатися Northwind, перетнувши гавань Stormwind. удачі!",
    O = "Доставте шарфи Farwind Борису Farwind на бойових змаганнях у Northwind.",
    P = "",
    C = "",
},

[41797] = {
    en = "A Good Friend",
    T = "[*] Хороший друг",
    D = "Сутінковий ліс стає небезпечнішим з кожним днем. Скажені воргени, мандрівні мерці чи злодії-головорізи – тут завжди знайдеться щось для вашого життя. Зрештою, хтось може задатися питанням, чому ми всі досі тут. Відповідь проста: ці ліси є нашим домом, і ми не дозволимо цим чудовиськам забрати їх у нас.$B$BStill, моє перебування тут важке для моїх друзів, для Барбари більше, ніж для інших'. Вона є флетчером лорда Амбервуда, правлячої знаті Нортвінду на північ від Штормовія. Я її давно не бачив, не кажучи вже про своє самопочуття. Вона, напевно, дуже хвилюється за мене, і мені це дуже соромно. Якщо у вас є вільна хвилинка, чи могли б ви доставити їй цього листа? У ньому написано речі, які я повинен був їй сказати давно, тому я доручаю тобі дуже важливе завдання. Якби ви могли це зробити для мене, я був би вам безмежно вдячний.$B$BThe Найшвидший шлях до Northwind — пройти через гавань Stormwind.",
    O = "Принесіть лист Аветт Феллвуд до Барбари Лі в Amberwood Keep у Northwind.",
    P = "",
    C = "",
},

[41798] = {
    en = "My Darling Wife",
    T = "[*] Моя дорога дружина",
    D = "Доброго дня тобі, $c. Ти мені схожий на авантюрного типу. Чи ви впоралися з багатьма небезпеками, які є всюдисущими сьогодні? Куди б не поїхав, здається, що криза не за горами. Звісно, ​​це не той світ, у якому ми хочемо, щоб наші діти росли. Моя дружина робить усе можливе, щоб зробити Азерот кращим місцем, але навіть у тій організації, у якій вона працює, для неї це майже неможливе завдання. Скажіть, ви б хотіли їй допомогти, як найманець? Операція, яку їй призначено цього разу, є... особливо делікатною, принаймні вона мені так сказала. Відверто кажучи, я хвилююся за її самопочуття, це може бути занадто навіть для неї. Я був би у вашому боргу назавжди, якби ви змогли їй допомогти.$B$BIf так, тоді вирушайте до гавані, на захід звідси. На одному з південних доків ви повинні знайти її колегу — здається, його звуть Сіммонс. Скажіть йому, що оперуповноважений Джилліан попросила додаткової зовнішньої допомоги, і він повинен доставити вас до неї, на острів Балор.",
    O = "Рональд Джилліан попросив вас приєднатися до його дружини на Балор, щоб допомогти їй у роботі.",
    P = "",
    C = "",
},

[41799] = {
    en = "A Hydromancer's Curiosity",
    T = "[*] Цікавість гідроманта",
    D = "Той нікчемний Фінніган! Клянусь, одного дня одна з його ескапад приведе до його кінця. Бачите, нещодавно група агентів SI:7 зібралася в доках. Очевидно, судячи з того, що ми могли підслухати, вони прямували виконати небезпечну місію на острові біля узбережжя Західного Краю. Балор — його назва. Цей острів був просочений нескінченною грозою ще задовго до того, як ми оселилися тут, у Давенбурзі. Кул Тірас підтримував зв’язок із Балором та його людьми в минулому, тому це місце для нас невідоме.$B$BBe що, як це може бути, Фініган, наш місцевий гідромансер, насправді зголосився допомогти SI:7 у виконанні їхнього завдання на Балорі, і зараз він з ними на їхній заставі. Нам потрібно якомога швидше повернути його сюди, в Давенбург, щоб не поставити під загрозу нашу дипломатичну місію. $C, ти хочеш допомогти йому закінчити все, що він почав, щоб він міг повернутися до нас? Один із агентів залишився в південних доках, я впевнений, що він зможе доставити вас на острів.",
    O = "Поговоріть із Гідромантом Фінніганом на аванпості SI:7 на Балорі.",
    P = "",
    C = "",
},

[41800] = {
    en = "The Grim Hollow",
    T = "[*] Похмура Лощина",
    D = "Це місце бачило багато — героїв, які піднімалися й падали, битви, які перетворилися на легенди, і втрати, про які люди хотіли б забути. Тут, де вітер гуде крізь скелі, а земля просякнута кров’ю старих війн, можна відчути, як минуле витає в повітрі.$B$BTucked на півдні, у Похмурій Долині, є Могила Предків. Це давнє місце відпочинку, старе, як сам Грім Батол. Гноми поховали там своїх мертвих кілька століть тому, вирізавши їхні імена в рунічному камені та пам’яті. Ми думали, що вони спокійні.$B$BTurns вийшли, ми помилялися.$B$BSomething ворушиться в темряві. Мертві відпочивають не так, як мали б. Крізь туман пливуть духи, неспокійні. Під болотом поховано щось мерзенне — те, що не належить.$B$BSo ось у чому справа: рушайте в ці туманні болота. З’ясуйте, що псує гробницю, і покладіть цьому край. Нехай мертві знову сплять спокійно... і подбайте про те, щоб усе, що спричинило це, не продовжувалось.",
    O = "Покладіть 10 мандрівних душ і 10 переміщених предків на спочинок для Дортаса Ріда біля північного входу в Грим-Річс.",
    P = "",
    C = "",
},

[41801] = {
    en = "The Blue Dragonkin",
    T = "[*] Блакитний дракон",
    D = "Є хтось, хто може знати, що стоїть за всім цим безладом. Глибоко в Похмурій Долині є старе дерево — величезний дуб, який стоїть задовго до того, як будь-який гном помітив ці землі. Ніхто точно не знає, скільки йому років, але його завжди поважали. Тихо. Стійкий. Частина землі, знаєте?$B$BBut зараз... розвідники Громового Молота повідомили нам, що блакитний дракон розбив табір під його гілками. Не знаю, що він там робить, але я відчуваю, що це не випадково. Зважаючи на те, як останнім часом крутиться земля, його прихід не може бути випадковим. Дракони зазвичай не втикаються в смертельні проблеми, якщо не відбувається щось велике.$B$BIf ти збираєшся поговорити з ним, ступай обережно. Дракони не зовсім відомі своєю сонячною вдачею, і одне неправильне слово може вас запекти. І все-таки... якщо ви зможете змусити його заговорити, у нього можуть бути відповіді, які ми більше ніде не знайдемо.",
    O = "Знайдіть Блакитного Драконіна поблизу великого дуба в Похмурій Долині.",
    P = "",
    C = "",
},

[41802] = {
    en = "Tomb of Ancestors",
    T = "[*] Могила Предків",
    D = "Лише сліпий міг не помітити зіпсуття, що охопило ці болота, її мерзенні вусики просочуються в кожне коріння й тінь. Мене послали сюди, щоб розкрити правду про те, що мучить Похмуру Долину, але моє завдання було нелегким. Болота патрулюють червоні дракони, їхні розуми захоплені тією ж корупцією, що отруює цю землю. $B$BWe дракони об’єднують зв’язок, почуття нашої родини, і вони відчувають мене так само точно, як я відчуваю їх. Кожного разу, коли я намагався наблизитися до Могили Предків, вони перехоплювали мене, керовані не розумом, а темрявою, яка затьмарює їхній розум. Отже, я залишаюся тут, захищений під цим старовинним дубом, але не можу виконати мету, яка привела мене в це прокляте місце. $B$BYou, однак, не пов’язані узами роду драконів. Ви повинні відправитися в глибини Гробниці Предків і відкрити джерело цієї корупції. Я впевнений, що він лежить усередині, гноїться та поширює свою пляму. Доля цих земель може залежати від вашої смертної мужності.",
    O = "Досягніть глибин Могили Предків.",
    P = "",
    C = "",
},

[41803] = {
    en = "The Skardyn",
    T = "[*] Скардина",
    D = "А тепер, смертний, слухай добре. Якщо ви хочете зрозуміти всю серйозність того, з чим ми стикаємося, ви повинні спочатку зрозуміти скардин і мерзенне походження, яке їх породило. Їхня історія — це історія зради, корупції та темряви, яка повинна була залишитися похованою. Зверніть увагу, бо це знання настільки ж небезпечне, наскільки й необхідне.",
    O = "Послухайте казку про Сартіс Лускосерце.",
    P = "",
    C = "",
},

[41804] = {
    en = "Memories of Dark Iron",
    T = "[*] Спогади про Чорне Залізо",
    D = "Скардин... істоти жахливої ​​могутності та затьмареної люті. Набагато сильніший за вас, смертний, і ще сильніший за будь-яку звичайну групу шукачів пригод. Зіткнутися з ними прямо було б безглуздям. Їхня плоть захищена лускою, просякнутою мерзенним чаклунством, їхні форми захищені прокляттями, вплетеними глибоко в їхню суть. $B$BIf у нас є шанс, нам потрібно буде викувати зброю — зброю, наповнену силою, щоб пробити їхні темні чари. -- Але мушу зізнатися, смертний... навіть з усім моїм знанням я не знаю, що це за зброя. Секрети їх знищення лежать поза межами моєї розуміння. $B$BYet може бути інший шлях. Колись скардини були гномами з темного заліза — так, спокутані тінню, але колись були родичами тих, хто все ще ходить поверхнею. Можливо, їхні нащадки зберегли записи про те, що спіткало їхню прокляту родину. $B$BYou повинен піти до фортеці Ангор у Безплодних землях. Там досі затримуються члени Чорного заліза — відлюдні, таємні та небезпечні. Але якщо хтось із них пам’ятає правду про те, що сталося під Грім Батолом... ви її знайдете саме там.",
    O = "Вирушайте до фортеці Ангор у Безплодних землях і знайдіть будь-які підказки, які можуть пролити світло на те, як перемогти Скардин.",
    P = "",
    C = "",
},

[41805] = {
    en = "Bathed in Dragonfire",
    T = "[*] Викупаний у Dragonfire",
    D = "А тепер послухай, смертний. $B$BThe Червоні родичі, які переслідують ці гнійні болота... їхній розум більше не належить їм. Брудне чаклунство Скардина проникло в їхні думки, перетворюючи гордих дрейків на гарчачих маріонеток. Ганьба... але не без користі. $B$BTheir вогняні залози — недоторкані руйнуванням — все ще гарячі. Збирайте їх. Нехай їхні останні вуглинки служать меті, більшій за божевілля. З ними ми спалимо оборону Скардина дотла. $B$BDo не сплутайте це з милосердям. Це необхідність. Їхні страждання закінчаться... і Скардина теж. $B$BNow іди. І не витрачайте їхнього вогню.",
    O = "Витягніть 3 незаймані вогняні залози з червоних драконів у Grim Hollow.",
    P = "",
    C = "",
},

[41806] = {
    en = "Dragonfire Bombs!",
    T = "[*] Бомби Dragonfire!",
    D = "Одних лише вогняних залоз недостатньо, щоб пробити оборону скардину — ні, далеко не так. Їхню спотворену плоть затверділа тінь, захищена від простого полум’я. Нам потрібен каталізатор... цілеспрямований канал, через який лють драконячого вогню може правильно направлятися. $B$BThere — цікавий і хитрий гном, на ім’я Облеторп Облотікус, який мешкає в хаотичній вигрібній ямі, яку смертні називають Здобиччою бухтою. У свої молоді роки він працював з летючим полум'ям, намагаючись очистити гномереган. Його методи були... неортодоксальними і не без суперечок. Проти них виступив сам Тинкмайстер. $B$BYet, якщо існує розум, здатний викувати пристрій драконячого вогню, достатньо потужний, щоб пробити тіньову шкуру скардина, то це його. $B$BSeek його. Час не на нашому боці.",
    O = "Знайдіть експерта з вибухівки Dragonfire Explosives у Booty Bay.",
    P = "",
    C = "",
},

[41807] = {
    en = "I Am Become Death...",
    T = "[*] Я став смертю...",
    D = "Ага! Хм... ну, це не зовсім катастрофа. У мене є — давайте подивимося — гвинтові пружини, регулятори потоку, захисний гель... Так! Я маю більшість із того, що мені потрібно! $B$BHowever! Мені трохи не вистачає кількох ключових компонентів, а саме твердого вибухового порошку, бронзових каркасів і дзвінких бронзових штучок. Нічого занадто екзотичного! Будь-який напівкомпетентний інженер міг би створити їх за допомогою потрібних матеріалів. Звичайно, без образ, якщо ви компетентні лише на чверть! $B$BNow, одна річ може виявитися дещо складнішою... термостійкий тригер. Зауважте, не просто якийсь старий тригер — це спеціальна штука від Undermine. Створений, щоб витримувати екстремальні температури. Останнє, що я чув, останній вантаж з Undermine перехопили ті мерзотні пірати Bloodsail. $B$BIf тобі пощастило — у тебе все ще є всі кінцівки — ти можеш знайти один із тих дорогоцінних тригерів, схованих у піратських таборах на південному сході. $B$BOff тоді йди! Принесіть мені товар, і я принесу бум!",
    O = "Принесіть необхідні матеріали до Oblethorpe Obloticus у Booty Bay.",
    P = "",
    C = "",
},

[41808] = {
    en = "The Destroyer of Skardyn",
    T = "[*] Руйнівник Скардина",
    D = "<Облеторп дивиться на готову бомбу з поєднанням гордості та глибокого, зростаючого занепокоєння> $B$BWell... трохи поміркувавши — і, можливо, трохи заднім числом — я не зовсім переконаний, що для вас це була найкраща ідея, яку я коли-небудь мав... $B$BM — можливо, мені варто її зберегти... просто, знаєте, зберегти світ неушкодженим ще день чи два... $B$BOkay, добре! Немає потреби в смертельному погляді — ой! Просто... візьміть прокляту річ! Але зробіть нам усім послугу і віднесіть його якомога далі! Уникайте вогню, гоблінів, різких рухів, гучних звуків і особливо мене, коли ви його тримаєте! $B$B<Він обережно кладе бомбу вам у руки> $B$BNow вперед, вперед! Шу! Геть, поки я не задумався! $B$BOoooh—але зачекайте! Усе це майстрування просто дало мені найгеніальнішу ідею — ВИБУХОВІ КАЧКИ! Ніхто не очікує вибухонебезпечної качки! Хі-хі! Перевалювання! Детонуючий! МОЖЛИВОСТІ!",
    O = "Поверніться до Sarthyss Scaleheart з бомбою.",
    P = "",
    C = "",
},

[41809] = {
    en = "Smell of Dragonfire",
    T = "[*] Запах Dragonfire",
    D = "Досить чекати, смертний.$B$BThat Бруд Скардина ховається внизу, його пазурі глибоко встромилися в земні вени, отруюючи все, до чого він торкається. Його підопічні можуть бути сильними, але не проти вогню, який ви зараз носите. Нехай лють мого загиблого родича стане іскрою, що спалює його захист дотла. $B$BThen візьміть його за голову. Чисто. Нехай його кров буде останньою розбещеністю, яку він проллє. $B$BBut не будь дурнем. Увійдіть один, і ви станете ще одним трупом у його колекції. Приведіть воїнів. Принесіть сталь. Принесіть достатньо люті, щоб відповідати його зраді. $B$BNow іди. І не розчаровуйте мене.",
    O = "Використовуйте бомбу Dragonfire Bomb, щоб послабити щит Скардина, а потім перемогти чаклуна Скардина.",
    P = "",
    C = "",
},

