[50230] = {
    en = "[Deprecated] Night's Exploration",
    T = "[*] [Не рекомендовано] Нічне дослідження",
    D = "Йди сюди, шукаче пригод!$B$BI Переконайся, що ти здатна людина, тож я навчу тебе чогось корисного, оскільки доля звела нас разом.$B$BYou тут, у джунглях, може бути корисним!$B$BIf ти принесеш мені тугу мотузку від Джавіліни, трохи олії від гоблінів Буті-Бей і товсту дубину, яку знайдеш навколо табору, тоді я розповім вам про унікальний спосіб миттєво створити правильний факел, який ви зможете використовувати під час подорожей або для нічних розвідок, або для захисту від диких тварин.$B$BSee ті, що поблизу нашого табору? Вони ніколи не виходять!",
    O = "Принесіть мотузку з Яквіліни, олію з Буті-Бей і палицю з усього табору в експедицію Несінгварі для С. Дж. Ерлгадіна.",
    P = "",
    C = "",
},

[50305] = {
    en = "Higher Stakes",
    T = "[*] Вищі ставки",
    D = "що тепер Ах, це знову ти. Які яйця?$B$BOh, правильно. Хвостові війки. То ви хочете приготувати ще щось, крім яєць? Гадаю, я можу тебе чогось навчити.$B$BDo ти знаєш, де закінчується річка Саутфурі? Ось куди вам доведеться піти. чому Я маю намір підвищити тут ставки, хлопче! Дайте мені це м'ясо кроколіска, і я навчу вас правильно його готувати! Ви знайдете їх по всій річці, тому вам краще негайно рухатися!",
    O = "Принесіть 8 м’яса кроколіска, щоб приготувати Торку в Razor Hill.",
    P = "",
    C = "",
