[50310] = {
    en = "Goblin Engineering At Its Finest!",
    T = "[*] Гоблінська інженерія у своєму найкращому вигляді!",
    D = "Ей, дитя! Так ти! Я бачу, що ви любитель пригод і готові кинутися в будь-яку сутичку, якщо тільки є така, у яку можна кинутися, чи не так? Так само, як я думав. що? Звичайно, це винагорода, як інакше це може бути тут? Зрештою, це Mirage Raceway!$B$BWhat що робити? О, це так просто, я впевнений, що навіть гном зуміє випробувати нашу веселу машину на сустейн на... е-е, умови довговічності! так! Отже, якщо ти готовий заробити кілька монет і зламати кілька скорпідів, тоді ти в правильному місці, хлопче! Який шолом? Інструкція? Бах! Кому вони взагалі потрібні?!$B$BYes, можливо, ви захочете поговорити з нашою чарівною Долорес, щоб зареєструватися на тестову гонку, $N.$B$BLet’s fuck it!",
    O = "Знайдіть Долорес і покатайтеся на гоночному боліді гобліна, щоб перевірити, чи витримає він взагалі старт.",
    P = "",
    C = "",
},

[50311] = {
    en = "Mirage Raceway: Goblin's Team",
    T = "[*] Mirage Raceway: Goblin's Team",
    D = "О, як добре, що ти живий і повернувся цілим! Я, звісно, ​​не сумнівався у вас.$B$BSo Ви готові ще раз спробувати наш інженерний шедевр гоблінів, еге ж? Тоді, якщо ви знаєте вправу, то краще приготуйтеся та знову займіть перше місце!",
    O = "Знайдіть Дейзі та пройдіть коло з найкращим часом.",
    P = "",
    C = "",
},

[50312] = {
    en = "Gnomes Are Genuine Inventors",
    T = "[*] Гноми - справжні винахідники",
    D = "Я впевнений, що ви добре знаєте про нас, гномів, ми найкращі винахідники. Якщо ви прагнете покращити свої навички та знання, зрештою буде прийнято рішення про навчання у нас. Очевидно, що жоден гном не такий дурний, щоб відмовитися від цього інтригуючого та захоплюючого партнерства, на жаль, іноді це може коштувати дорого.$B$BSpeaking коротше; нам потрібен хтось, хто б доповнив нашу природну винахідливість мозкової діяльності своїми м’язами та витривалістю!$B$BIf ви успішно їздите на цьому дивовижному шедеврі гномської інженерії, будь-який інший тупий гоблін просто назвав би гоночний автомобіль, тоді ви отримаєте можливість ще більше представляти наше яскраве товариство винахідників у Mirage Races!$B$BCool, чи не так?$B$BWell, ось інструкції, які ми спеціально розробили для інших рас, для кращого розуміння та розуміння.$B$BYes, можливо, ти захочеш поговорити з нашою чарівною Долорес, щоб зареєструватися на тестову гонку, $N.$B$BGood удачі, розумний!",
    O = "Знайдіть Долорес і покатайтеся на гоночному автомобілі гнома, щоб перевірити, чи витримає він взагалі старт.",
    P = "",
    C = "",
},

[50313] = {
    en = "Mirage Raceway: Gnome's Team",
    T = "[*] Mirage Raceway: команда Gnome",
    D = "Вітаю, розумний! Ми дуже задоволені результатами, яких ви досягли під час тест-драйву нашого механічного пристрою, і виявилися дуже корисними для надання нам таких необхідних даних для аналізу. Ми готові дозволити вам постійну часткову участь у нашій дослідницькій групі та погодилися підтримувати вас у ваших зусиллях.$B$BWhen ви готові продовжити збір даних, обов’язково запам’ятайте надані інструкції та рекомендовані заходи безпеки.$B$BHave чудового дня!",
    O = "Знайдіть Дейзі та пройдіть коло з найкращим часом.",
    P = "",
    C = "",
},

