[80209] = {
    en = "Porting to Goldshire",
    T = "[*] Перенесення на Goldshire",
    D = "Ви вирішили допомогти? Я вдячний, $N!$B$BThe ситуація вдома жахлива, і ми зараз не можемо повернутися, щоб допомогти. Я не знаю, що за страждання вельмож у Штормовії, але відтоді, як король Варіан зник, Королівство впало під землю!$B$BAlas, хоча ми не можемо контролювати вельмож, ми можемо впоратися з проблемами в провінціях королівства! Elwy$b$b Forest — гарне місце для початку. Столиця розташована в цьому регіоні, і вона була оточена питаннями. Кобольди керують шахтами, гноли здійснюють набіги на міста, а бандити захоплюють дороги.$B$BMy друг, маршал Дуган, дислокується в Золотоширі, і він може добре вам скористатися. Я вважаю, що Магістрікс може телепортувати вас до Золотого краю.",
    O = "Поговоріть з магістром Ішалахом, щоб вас телепортували до Золотоширу, а потім доповідайте маршалу Дугану.",
    P = "",
    C = "",
},

[80210] = {
