},

[80360] = {
    en = "Power Taken, Power Given",
    T = "[*] Влада взята, влада надана",
    D = "Подорож із наших лісів у старому світі до нашого нового дому тут, у Калімдорі, була важкою не лише для нас, але й для лоа, які захищали нас у цій дорозі. Наскільки далеко від лісів, якими вони кочували тисячоліттями, вони ослаблені своєю присутністю тут.$B$BFar на півдні, тролі Піщаної Люті Зул'Фаррака підтримували зв'язок із Кімбулом, незважаючи на їх віддаленість від джунглів Гурубаші. Шукайте силу Кімбула і поверніть її мені. Я використаю силу, надану Піщаною люттю, щоб збільшити присутність і силу наших лоа на цих чужих землях.",
    O = "Отримайте 5 Jujus of Kimbul і принесіть їх Mystic Guay'jin.",
    P = "",
    C = "",
},

